window.SERPENTS_GLOSSARY = [{"term":"Abbot, Arsene","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred as a punishment for the crowd's mockery during his sermon from the Annabella Saint Ledger (112).","notesPages":[240],"id":"glossary-entry-abbot-arsene","letter":"A"},{"term":"Abboud, Lolly Jane","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[240],"id":"glossary-entry-abboud-lolly-jane","letter":"A"},{"term":"Abdo, Elias","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[240],"id":"glossary-entry-abdo-elias","letter":"A"},{"term":"Abel, Sally E.","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred; explicitly distinguished from Sally J. Abel in the same crowd (112).","notesPages":[240],"id":"glossary-entry-abel-sally-e","letter":"A"},{"term":"Abel, Sally J.","definition":"A person in the crowd addressed by the Prophet Invisible Alfred; explicitly spared from the prophet's ten-minute death sentence directed at Sally E. Abel and nine others (112).","notesPages":[240],"id":"glossary-entry-abel-sally-j","letter":"A"},{"term":"Abercrombie, Alice","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[240],"id":"glossary-entry-abercrombie-alice","letter":"A"},{"term":"Abernathy, Thompson","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[240],"id":"glossary-entry-abernathy-thompson","letter":"A"},{"term":"Ability","definition":"Often refers to exceptional or \"mega\" levels of intelligence, psychic power, or specialized skills possessed by experimental subjects like the Axel's Apes (19), unique angelic powers like Luas's multi-location (61), or the re-emergence of fantastic capabilities like animal speech or bi-location in the world (128).","notesPages":[240],"id":"glossary-entry-ability","letter":"A"},{"term":"Ableson, Scott","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[240],"id":"glossary-entry-ableson-scott","letter":"A"},{"term":"Abney, Billy Joe","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[241],"id":"glossary-entry-abney-billy-joe","letter":"A"},{"term":"Abraham","definition":"The biblical patriarch whose name occurs in \"Abraham's Bosom.\" The passage locates David, Solomon, Prester John, the Cid, Arthur, Melchisedech, and others in this valley, but does not explicitly say Abraham himself sleeps there (11).","notesPages":[241],"id":"glossary-entry-abraham","letter":"A"},{"term":"Abraham, David E.","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[241],"id":"glossary-entry-abraham-david-e","letter":"A"},{"term":"Abraham's Bosom","definition":"According to Axel Grindstone's \"awkward\" beliefs, a specific valley near Second Eden where ancient figures like Kings David and Solomon, Prester John, the Cid, Arthur, and even older persons like Melchisedech lie sleeping but still alive (11).","notesPages":[241],"id":"glossary-entry-abrahams-bosom","letter":"A"},{"term":"Abstract thought","definition":"Along with speech and role-playing, identified as a \"trans-animal talent\" emerging among \"geniused animals\" as part of the \"Fulfillment of the World\" (93).","notesPages":[241],"id":"glossary-entry-abstract-thought","letter":"A"},{"term":"Abt, Morris","definition":"One of the ten people named by Invisible Alfred, all of whom die within ten minutes (112).","notesPages":[241],"id":"glossary-entry-abt-morris","letter":"A"},{"term":"Academic cap and gown","definition":"Attire regularly worn by Schimp, the young, erudite chimpanzee who obtained his doctorate and masters degrees by the age of eight (63).","notesPages":[241],"id":"glossary-entry-academic-cap-and-gown","letter":"A"},{"term":"Ace card","definition":"God's reserve option; specifically, the Second Eden populated by \"The People Who Had Not Fallen\", held back should First Eden fail (11).","notesPages":[241],"id":"glossary-entry-ace-card","letter":"A"},{"term":"Acorn","definition":"The vessel, according to Dubu's \"notion,\" containing the answers to all hard questions, written on its inside; requires swelling in lye-water to burst and reveal \"whole mountains- full of writing\" (74).","notesPages":[241],"id":"glossary-entry-acorn","letter":"A"},{"term":"Adam","definition":"The first man of First Eden, created thirty years before Prester John in the novel's chronology (12); mankind originated from his \"depraved origin\" and \"corrupt root\" (35).","notesPages":[241],"id":"glossary-entry-adam","letter":"A"},{"term":"Adjudged","definition":"Judged or formally classified, specifically in the context of being identified as a \"Serpent's Egg\" (2), a classification potentially leading to extermination by the Dolophonoi (84); also used regarding giving cause for such judgment (146).","notesPages":[241],"id":"glossary-entry-adjudged","letter":"A"},{"term":"Adventure (First Ocean-Floor)","definition":"The underwater expedition undertaken by Satrap Saint Ledger and the Nine Royal Kids to observe the Whales building their Temple-City on the Ocean Bottom (134).","notesPages":[242],"id":"glossary-entry-adventure-first-ocean-floor","letter":"A"},{"term":"Aeneas Legends (Medieval)","definition":"Cited by Lutin the Pythoness as containing references to the \"Midnight Cock\" associated with awakening (143).","notesPages":[242],"id":"glossary-entry-aeneas-legends-medieval","letter":"A"},{"term":"Affair of honor","definition":"The code requiring Donatus O'Reily, as a member of the Natural Nobility who committed a hangable misdemeanor, to be hanged by friends of his choosing rather than by a common hangman (117).","notesPages":[242],"id":"glossary-entry-affair-of-honor","letter":"A"},{"term":"Affair (The Life)","definition":"Felix Culebra y Columba's term for the \"seamless garment\" woven from individual lives, the neighborhood, the countryside, creatures, realms, continents, oceans, sub-atomic particles, galaxy clusters, minds, ideas, joys, and immediacies (74).","notesPages":[242],"id":"glossary-entry-affair-the-life","letter":"A"},{"term":"Agents","definition":"Unwitting instruments of God; specifically, the \"somewhat grubby and greedy\" human interlopers who captured the Axel's Apes from Second Eden, thereby facilitating the Apes' fated expansion into the world (19).","notesPages":[242],"id":"glossary-entry-agents","letter":"A"},{"term":"Aiken","definition":"Howard Aiken, historical computer pioneer associated with the Harvard Mark I, mentioned in the history of computation (25).","notesPages":[242],"id":"glossary-entry-aiken","letter":"A"},{"term":"Airliner analogy","definition":"Metaphor illustrating the paradoxical nature of human free choice within collective constraints: three hundred people on one airliner are told each has absolute freedom to choose their individual non-stop destination, despite all being on the same plane (41).","notesPages":[242],"id":"glossary-entry-airliner-analogy","letter":"A"},{"term":"Al-Waghe","definition":"Site of an ancient cliff mural depicting God holding a two- stringed bow, interpreted by Axel Grindstone as evidence for God always having a second option, such as a Second Eden (11).","notesPages":[244],"id":"glossary-entry-al-waghe","letter":"A"},{"term":"Alaskan brown bear","definition":"A fearsome first mate on the pirate ship The Unrepentent Rascal, recalled by Lanternjaw Lunnigan (102-3).","notesPages":[242],"id":"glossary-entry-alaskan-brown-bear","letter":"A"},{"term":"Alexandria","definition":"Ancient city cited as a place from which great mathematicians came to sit at the feet of the Unfallen Ones to learn high mathematics (15).","notesPages":[243],"id":"glossary-entry-alexandria","letter":"A"},{"term":"Alfred, Invisible","definition":"An enigmatic Prophet (108) and stowaway initially living in one of seven one-hundred-gallon drums of Invisible Paint aboard the Annabella Saint Ledger (97, 98); possesses weak eyes and a powerful, ambiguous voice (108, 110); preaches repentance and performs miracles (whale summoning, revealing celestial signs) before crowds (109-11); later revealed via kangaroo knuckle-bone to be the current Supreme Head of the Kangaroo (145, 149); ultimately responsible for the deaths of Axel, Lord Randal, and Henryetta (148- 50).","notesPages":[242,243],"id":"glossary-entry-alfred-invisible","letter":"A"},{"term":"All-animal","definition":"See Pan-Ther.","notesPages":[243],"id":"glossary-entry-all-animal","letter":"A"},{"term":"\"All Day and All Night\" (Song)","definition":"A song being performed at Jack Flannagan's Piano Bar and Sidewalk Cafe during the ghost dawn as the Third Night of Summerset ends (151).","notesPages":[243],"id":"glossary-entry-all-day-and-all-night-song","letter":"A"},{"term":"All-eyes-and-mouth","definition":"A name shouted by a heckler at Invisible Alfred, referencing the only parts of the Prophet usually visible (109).","notesPages":[243],"id":"glossary-entry-all-eyes-and-mouth","letter":"A"},{"term":"All-knowing wink","definition":"A subtle facial gesture that only bears who \"know everything\" can perform; used to signal this comprehensive knowledge to other bears met on the trail (75).","notesPages":[243],"id":"glossary-entry-all-knowing-wink","letter":"A"},{"term":"All-the-animals","definition":"See Pan-Ther.","notesPages":[243],"id":"glossary-entry-all-the-animals","letter":"A"},{"term":"Alley Oop","definition":"The name used by the Yellow Apes for the Allez-Oop locks (47); invoked by Quentillius the Fifth when describing loading procedures (101). A human guard warns Inneall not to try using the \"Alley Oop\" to enter the sealed Ape Caverns (68).","notesPages":[243],"id":"glossary-entry-alley-oop","letter":"A"},{"term":"Allez-Oop","definition":"The name given by Satrap Saint Ledger to the series of locks and tubes connecting his suite in the New Eden Hotel directly to Inneall's Ocean (47); used by Satrap to assign crewmen elsewhere after Inneall takes over the Annabella Saint Ledger (49); its entrance is blocked by bodies attempting an unguarded way into Ape Caverns (68). Also called \"Alley Oop\" (47).","notesPages":[243],"id":"glossary-entry-allez-oop","letter":"A"},{"term":"Alligator blood","definition":"The bizarre ink identified by analysis as having been used to write Tom Dooley's will (124).","notesPages":[243],"id":"glossary-entry-alligator-blood","letter":"A"},{"term":"Alligator-gar","definition":"A species of fish present in the diverse fauna flocking to Inneall's new Ocean (138).","notesPages":[243],"id":"glossary-entry-alligator-gar","letter":"A"},{"term":"Alligator wrestling","definition":"One of the many arts and hobbies abandoned by humans but recently invented or reinvented by Computers (33).","notesPages":[243],"id":"glossary-entry-alligator-wrestling","letter":"A"},{"term":"Almost-invisible government","definition":"The effective ruling power of the Floating World, supplanting overt superstructures; identified explicitly as the Kangaroo (80).","notesPages":[244],"id":"glossary-entry-almost-invisible-government","letter":"A"},{"term":"Alpha","definition":"A \"very powerful and unfettered\" male Golden Ape from Second Eden (20); father of Axel the Ape (20, 51); followed the captured Apes to Arba Mench, then trans-located to America (21); founded Ape Alley in limestone caves under a city with other escaped Apes and human \"white trash\" (21-2); became the grizzled patriarch, King, and Prophet of the Apes' Caverns (51); adopted Inneall as a granddaughter (52); may be the leading Axel who explains the closure of Ape Caverns for the \"Holy Sleep\" (67).","notesPages":[244],"id":"glossary-entry-alpha","letter":"A"},{"term":"Alpha Cliff","definition":"One of two cliffs (along with Beta Cliff) in The Three's contrived five-acre habitat, between which they swung on reinforced vines over water (4).","notesPages":[244],"id":"glossary-entry-alpha-cliff","letter":"A"},{"term":"Alphabet (runic)","definition":"Writing system fancifully attributed to whales in a passage the novel credits to Olaf Hensen; it says Scandinavians learned runes from whales (131).","notesPages":[244],"id":"glossary-entry-alphabet-runic","letter":"A"},{"term":"Alternatives","definition":"Ansel Grindstone's term for the Unfallen People, describing them as God's inactive, unfinished backup beings, poised to receive \"living fire\" and replace humanity should God finally give up on the latter (17).","notesPages":[244],"id":"glossary-entry-alternatives","letter":"A"},{"term":"Amanuenses","definition":"Secretaries or recorders; specifically, the sea-lice who write on limestone slabs at the direction of the Whales, taking over the function of log-keeping from Computers (163-4); a role potentially available to humans or Computers in the future (164).","notesPages":[244],"id":"glossary-entry-amanuenses","letter":"A"},{"term":"Ambulatory Ambles","definition":"A campfire song sung by the people and 'people' on the shores of Heart's Desire Cove during the chilly End-of-Summer nights (59).","notesPages":[244],"id":"glossary-entry-ambulatory-ambles","letter":"A"},{"term":"Ambulatory calculators","definition":"A self-referential term used by the computer Livius Secundus (72).","notesPages":[244],"id":"glossary-entry-ambulatory-calculators","letter":"A"},{"term":"Ambulatory computer(s)","definition":"A mobile, miming computer, often possessing human-like form and advanced intelligence but sometimes lacking common sense or responsibility (26); capable of mimicking anything (26), creating props by cannibalizing their environment (27), running amok (27), or becoming inhabited by spirits (28); includes Inneall (3), Livius Secundus (70), and possibly Jack Flannagan (152); some haunt body-and-organ banks (42); involved with the Kangaroo (80, 83). See also Ambulatory Mime-Human (AMH) Computers.","notesPages":[245],"id":"glossary-entry-ambulatory-computer-s","letter":"A"},{"term":"Ambulatory Computer species","definition":"The formal classification of certain guards at the entrance to Ape Caverns (68).","notesPages":[245],"id":"glossary-entry-ambulatory-computer-species","letter":"A"},{"term":"Ambulatory Mime-Human (AMH) Computers","definition":"The full designation for sophisticated mobile computers capable of mimicking human form and exceeding human intelligence (26); originated partly from human vanity and Analytical Human Psychology (26); built using Wotto Metal matrix (25); prone to running amok or being haunted (27-8); includes Inneall (3); source of commentary on mankind (36, 38); feature in Structo Lane Dramas (76); part of the Kangaroo membership (80).","notesPages":[245],"id":"glossary-entry-ambulatory-mime-human-amh-computers","letter":"A"},{"term":"Ambulatory miming-human species","definition":"The species designation of Inneall (20).","notesPages":[245],"id":"glossary-entry-ambulatory-miming-human-species","letter":"A"},{"term":"Amharic","definition":"An Ethiopian language studied by Axel Grindstone (11), understood and potentially spoken by the Unfallen Ones (15), and used by Alpha when speaking with the raiding men (20).","notesPages":[245],"id":"glossary-entry-amharic","letter":"A"},{"term":"AMHs","definition":"See Ambulatory Mime-Human (AMH) Computers.","notesPages":[245],"id":"glossary-entry-amhs","letter":"A"},{"term":"Anak (Sons of)","definition":"Giants mentioned in the Old Testament; suggested as possible builders of the underwater city of Lyonesse (106).","notesPages":[245],"id":"glossary-entry-anak-sons-of","letter":"A"},{"term":"Analytical Engine","definition":"Charles Babbage's proposed general-purpose programmable computing machine, conceived in 1834 and never completed. The novel dates its invention to 1835 (25).","notesPages":[245],"id":"glossary-entry-analytical-engine","letter":"A"},{"term":"Analytical Human Psychology","definition":"One of the motivating factors cited for the creation of Ambulatory Mime-Human Computers, involving the study of human minds and bodies via mobile schematics (26).","notesPages":[245],"id":"glossary-entry-analytical-human-psychology","letter":"A"},{"term":"Ananthropoi","definition":"A term coined by an AMH Computer to designate Computers who, analogous to human Atheists not believing in the Theos, do not believe in the existence or significance of Humans (Anthropoi) (38).","notesPages":[245,246],"id":"glossary-entry-ananthropoi","letter":"A"},{"term":"Anastasia Blickworthy","definition":"A carry-over party guest at Persimmon Manor (124); one of the four 'seconds' honor-sworn to hang Donatus O'Reily (124); unimpressed by Invisible Alfred's prophetic claims (123).","notesPages":[246],"id":"glossary-entry-anastasia-blickworthy","letter":"A"},{"term":"Angel","definition":"A type of being from a different universe (61); includes Luas (55); angelic voices call Axel Grindstone toward his quest (10-11); involved in a wrestling match recounted in the Book of Jasher (88); can know which acorn holds all answers but is too ethical to tell (74). Archangels possess specific, potentially terrifying features (17).","notesPages":[246],"id":"glossary-entry-angel","letter":"A"},{"term":"Angel Bridge","definition":"Axel Grindstone's belief for the true name of the Ape Bridge, suggesting superstition caused the change (12).","notesPages":[246],"id":"glossary-entry-angel-bridge","letter":"A"},{"term":"Angel-gun","definition":"A deadly weapon required to kill an angel, which simultaneously kills the person who fires it (88); sought by one of the Dolophonoi-Assassins to use against Luas (89); obtained by Shadrack Saleh (89) but thrown down in weakness (90).","notesPages":[246],"id":"glossary-entry-angel-gun","letter":"A"},{"term":"Angelic will","definition":"The immovable will possessed by even the least of angels, unaffected by humans, machines, or devious humans like Henryetta (61).","notesPages":[246],"id":"glossary-entry-angelic-will","letter":"A"},{"term":"Angkor Wat (Temple of)","definition":"The famous Cambodian temple complex, speculated in the text to have been built by 'King of Whales' Suryavarman II, possibly raised from the Ocean floor, exhibiting a strange 'dripping' quality (132).","notesPages":[246],"id":"glossary-entry-angkor-wat-temple-of","letter":"A"},{"term":"Anglers","definition":"A species of fish present in Inneall's Ocean (138).","notesPages":[246],"id":"glossary-entry-anglers","letter":"A"},{"term":"Animal-and-bird stories","definition":"The exclusive narrative genre of the Axel's Apes, featuring tales Alpha claimed were originally sourced from animal/bird speech and transmitted to humans when humans lost the ability to communicate directly with animals (51).","notesPages":[246],"id":"glossary-entry-animal-and-bird-stories","letter":"A"},{"term":"Animism","definition":"Belief in spiritual presences or agency in the natural world. Satrap invokes an \"animistic period\" to explain persimmon wood's supposed susceptibility to haunting (125).","notesPages":[246],"id":"glossary-entry-animism","letter":"A"},{"term":"Annabella Pansy-Face","definition":"The \"pixie face\" depicted as the \"Grindstone\" figure on the Saint Ledger coat-of-arms aboard the Annabella Saint Ledger (49).","notesPages":[247],"id":"glossary-entry-annabella-pansy-face","letter":"A"},{"term":"Annabella Saint Ledger (daughter)","definition":"Deceased daughter of Satrap Saint Ledger, who would have been ten years old (like Inneall); the namesake of the yacht Annabella Saint Ledger (48); Inneall is adopted by Satrap \"in place of\" her (49).","notesPages":[247],"id":"glossary-entry-annabella-saint-ledger-daughter","letter":"A"},{"term":"Annabella Saint Ledger Pirate Chantey","definition":"Title of the verse epigraph for Chapter Nine (92).","notesPages":[247],"id":"glossary-entry-annabella-saint-ledger-pirate-chantey","letter":"A"},{"term":"Annabella Saint Ledger (ship)","definition":"Satrap Saint Ledger's yacht (47), named after his deceased daughter (48); acquired by Inneall via ultimatum and contract signed in blood, becoming her pirate flagship (47-9); its coat-of-arms depicts a \"Black Sail-Ship\", the \"Red Laird\", the \"Yellow Dwarf\" (Gargoyle face), and the \"Grindstone\" (pixie face of Annabella Pansy-Face) over a \"Green Porpoise\" (49); used as headquarters for the Royal Kids (95); becomes invisible after being painted with Invisible Paint (97, 101, 107, 120); hosts the Prophet Invisible Alfred (108); provides diving gear (132); provides the pirate crew's continuing home as the children contemplate life on the ocean bottom (119-122); withdraws before Tom Dooley's Island sinks (152,159).","notesPages":[247],"id":"glossary-entry-annabella-saint-ledger-ship","letter":"A"},{"term":"Annihilation shells","definition":"Henryetta's term for the seven enchanted cannon-balls belonging to the ninety-ninth cannon from the Golden Hind (95).","notesPages":[247],"id":"glossary-entry-annihilation-shells","letter":"A"},{"term":"Anon","definition":"Source of \"The Child's Big Book of Whales\" verse (105).","notesPages":[247],"id":"glossary-entry-anon","letter":"A"},{"term":"Anthropoi","definition":"The term used by Ananthropoi Computers to refer to Humans (38).","notesPages":[247],"id":"glossary-entry-anthropoi","letter":"A"},{"term":"Antics","definition":"An alternative name for the media format also known as 'prowls', 'romps', 'trips', 'experiences', or 'jaunts' (6); also refers to the actions of ghosts inhabiting Inneall (29).","notesPages":[247],"id":"glossary-entry-antics","letter":"A"},{"term":"Antique shop","definition":"Location in Structo Lane where Satrap Saint Ledger purchased the steam calliope (85) and the seven drums of Invisible Paint (97) for the Royal Kids.","notesPages":[247],"id":"glossary-entry-antique-shop","letter":"A"},{"term":"Ape","definition":"A term sometimes used as a reverse euphemism for the Unfallen People (13); also used derogatorily by Axel Grindstone for the Unfallen People/Gargoyles (17); sometimes applied to humans (by Dolophonoi) (42) or Computers (by humans) (26).","notesPages":[247,248],"id":"glossary-entry-ape","letter":"A"},{"term":"Ape Alley","definition":"The primary underground enclave of the Axel's Apes in America (9, 22), located within the Ape Caverns (45); founded by Alpha (22); features shops, studios, clubs, a hotel, a mint, smithies, and a silent movie theatre (45-6); connected to Inneall's Ocean via the Allez-Oop/Alley Oop locks (47); closed and put under \"Holy Sleep\" (67, 69, 70). Also called Ape Lane (9, 45) or Yellow Ape Lane (43).","notesPages":[248],"id":"glossary-entry-ape-alley","letter":"A"},{"term":"Ape (Axel's / Smithy / Golden / Blue-Eyed / Yellow)","definition":"A species originating from Second Eden (19, 45), also called Smithy Apes for metalworking skill (3, 13, 19), Stone-Master Apes (13), Golden Apes for color (3, 13, 20), or Blue-Eyed Apes (3, 10, 18); characterized by Gargoyle faces (21, 41, 44) and exceptional (\"mega\") abilities (19); some captured and dispersed to zoos (19-20), others established Ape Alley (21-2); includes Axel (ape) (3) and Alpha (20); possess talents for locating ores (46), bi-location (21), and telling animal-and- bird stories (51); associated with wine (46) and meditation (46); subject to the \"Holy Sleep\" (70, 142) and the \"Moment of Awakening\" (46, 51).","notesPages":[248],"id":"glossary-entry-ape-axels-smithy-golden-blue-eyed-yellow","letter":"A"},{"term":"Ape Bridge","definition":"A land bridge, sometimes reappearing miraculously, connecting the Horn of Africa to Arabia (12); said to have been used by the Unfallen People (12), and conjecturally by Moses (13); later crossed by the Gypsies led by golden apes (13). Axel Grindstone believed its true name was the Angel Bridge (12).","notesPages":[248],"id":"glossary-entry-ape-bridge","letter":"A"},{"term":"Ape Caverns","definition":"The network of natural limestone caves and old mine passages under the Green Country Valley (45), containing Ape Alley (9, 45); home to Axel's Apes and some humans (9); site of the \"Holy Sleep\" (67, 70, 144); has a fissure in the roof through which lightning strikes (45, 68) and a giant hand descends (68); location of the Cenaculum of the Sleepers (143, 144, 148, 161).","notesPages":[248],"id":"glossary-entry-ape-caverns","letter":"A"},{"term":"Ape Lane","definition":"An alternate name for Ape Alley, or specifically its urban \"downtown block\" (9, 45); site of the Second Eden Hotel (67). The later antique-shop purchases are arranged while the group is based in Structo Lane (85,95-98).","notesPages":[248],"id":"glossary-entry-ape-lane","letter":"A"},{"term":"\"Apes in Exile\"","definition":"Alpha's term for the Axel's Apes living in zoos and institutions outside of Second Eden or Ape Caverns (51).","notesPages":[248],"id":"glossary-entry-apes-in-exile","letter":"A"},{"term":"Apostles","definition":"The twelve disciples of Christ, identified by the Prophet Invisible Alfred as the true identities behind the twelve zodiacal constellations/stations (e.g., Thomas as Gemini) (111).","notesPages":[249],"id":"glossary-entry-apostles","letter":"A"},{"term":"Arabia","definition":"Region connected to the Horn of Africa by the Ape Bridge, crossed by the Unfallen People (12) and Gypsies (13).","notesPages":[249],"id":"glossary-entry-arabia","letter":"A"},{"term":"Arabian comedy (Medieval)","definition":"One of the historical human sources influencing the dramas performed in Structo Lane (76).","notesPages":[249],"id":"glossary-entry-arabian-comedy-medieval","letter":"A"},{"term":"Arabian Yemen","definition":"Location (Mocha) forming one end of the original Ape Bridge (13).","notesPages":[249],"id":"glossary-entry-arabian-yemen","letter":"A"},{"term":"Arabic","definition":"Language studied by Axel Grindstone (11); understood, and potentially spoken slowly and measuredly, by the Unfallen Ones (15).","notesPages":[249],"id":"glossary-entry-arabic","letter":"A"},{"term":"Arba Mench","definition":"Provincial capital city in Gamu Gofa Province, Ethiopia (14); location near Second Eden (14) from which Axel Grindstone travels (14) and to which he is returned delirious (16); site where Ansel Grindstone arrives (16) and from which the newborn Axel the Ape is flown to America (19-20); Alpha follows the captured Apes only as far as Arba Mench before trans-locating west (21).","notesPages":[249],"id":"glossary-entry-arba-mench","letter":"A"},{"term":"Archangel","definition":"Celestial being whose hypothetical face Ansel Grindstone uses to illustrate terrifying divine beauty, suggesting immense features like a nose bridge a hundred yards deep, half-mile wide eyeballs, and magnificently slack jaws (17).","notesPages":[249],"id":"glossary-entry-archangel","letter":"A"},{"term":"Archeology (Megalithic)","definition":"Academic field thoroughly researched by Ruddy Lord Randal, particularly concerning its Ocean Floor context (137).","notesPages":[249],"id":"glossary-entry-archeology-megalithic","letter":"A"},{"term":"Archeology (Ocean)","definition":"Field concerned with underwater discoveries, such as the city of Lyonesse (105) and the Giant Underwater Cenotaphs off San Sabian (132).","notesPages":[249],"id":"glossary-entry-archeology-ocean","letter":"A"},{"term":"Archeology Today","definition":"A journal (cited issue Winter 1927) quoted regarding the unnoticed building of giant submarine structures over nine thousand years (131).","notesPages":[249],"id":"glossary-entry-archeology-today","letter":"A"},{"term":"Aries","definition":"The first constellation of the Zodiac, depicted conventionally in the sky by Invisible Alfred (111).","notesPages":[249],"id":"glossary-entry-aries","letter":"A"},{"term":"Aristerocheiric-spheres","definition":"Inneall's neologism, meaning left-handed or awkward spheres, used to describe layers of complex, unsolvable mysteries (163).","notesPages":[250],"id":"glossary-entry-aristerocheiric-spheres","letter":"A"},{"term":"Aristocrats","definition":"Social classification claimed by Henryetta for all members of the Experiments (human, animal, angel, machine), contrasting them with Dubu as the supposed sole \"commoner\" (63); also, the traditional players of lacrosse (65).","notesPages":[250],"id":"glossary-entry-aristocrats","letter":"A"},{"term":"Arithmetic machine","definition":"Blaise Pascal's historical calculating device (1642), noted in the history of computers (25).","notesPages":[250],"id":"glossary-entry-arithmetic-machine","letter":"A"},{"term":"Ark","definition":"Metaphor used to describe the Floating World as a giant boat of remarkable resiliency (82).","notesPages":[250],"id":"glossary-entry-ark","letter":"A"},{"term":"Arkansas River","definition":"River whose branches flow underground through the Ape Caverns (45); also one of the rivers whose valley is being captured by the growing Inneall's Ocean (55).","notesPages":[250],"id":"glossary-entry-arkansas-river","letter":"A"},{"term":"Armageddon (Battle of)","definition":"The apocalyptic final battle, predicted by a fortune-teller on North Rockford to begin \"yet this year\" in the limestone caverns and old coal mines under the city, eventually becoming worldwide (44).","notesPages":[250],"id":"glossary-entry-armageddon-battle-of","letter":"A"},{"term":"Art of the Whales","definition":"The great portraiture art cut in high-and-bas relief into giant stone pillars, walls, and lintels by the small ocean-floor sculpturing Lice, presumably at the direction of the Whales; finished works are plated with nacre (138).","notesPages":[250],"id":"glossary-entry-art-of-the-whales","letter":"A"},{"term":"Arthur","definition":"King Arthur of England, believed by Axel Grindstone to be sleeping, undead but alive, in Abraham's Bosom (11).","notesPages":[250],"id":"glossary-entry-arthur","letter":"A"},{"term":"Artisans","definition":"Specifically, human magician-artisans who, according to AMH Computer research, attempted to make mechanical horses which inadvertently resembled later biological horses (31).","notesPages":[250],"id":"glossary-entry-artisans","letter":"A"},{"term":"Arty World","definition":"One interpretation of the Japanese phrase \"The Floating World\", alongside \"Bohemian World\" and \"Unmoored World\" (79).","notesPages":[250],"id":"glossary-entry-arty-world","letter":"A"},{"term":"Arutinov, Arpad","definition":"Author of The Back Door of History, quoted regarding the future reduction of armaments to \"One Man, One Knife\" (79) and the belief that the underwater city of Lyonesse was built by whales (106).","notesPages":[250],"id":"glossary-entry-arutinov-arpad","letter":"A"},{"term":"Aryan type","definition":"Physical description (\"strong-nosed\") of the Asiatic man employed by Satrap Saint Ledger who reports on Riesin's final journey (94).","notesPages":[251],"id":"glossary-entry-aryan-type","letter":"A"},{"term":"Asiatic","definition":"Description of Satrap Saint Ledger's employee in the Himalayas (94).","notesPages":[251],"id":"glossary-entry-asiatic","letter":"A"},{"term":"Asinine","definition":"Quality of speech or relationship; an AMH computer claims affinity between Computers and asses (donkeys, onagers) and states their relationship with humans is \"of an astute asinine sort,\" justifying \"asinine talk\" as fitting the human perception of machines as \"jack-and-jenny asses\" (31).","notesPages":[251],"id":"glossary-entry-asinine","letter":"A"},{"term":"Ass (Baalam's)","definition":"The talking donkey from the Book of Numbers, cited by Invisible Alfred as a precedent for a Prophet being an Ass (124).","notesPages":[251],"id":"glossary-entry-ass-baalams","letter":"A"},{"term":"Assab","definition":"City in Eritrea, identified as the African end of the original Ape Bridge location (connecting to Mocha, Yemen) (13).","notesPages":[251],"id":"glossary-entry-assab","letter":"A"},{"term":"Assassin(s)","definition":"Agents of the Kangaroo (82, 83), also called Dolophonoi (41, 42) or Knives (82, 83); used to eliminate \"Serpent's Eggs\" or other perceived threats (82, 84); possess Dolophonoi knives (100) and specialized weapons like angel-guns and python-guns (88-90); some assigned to monitor the Four Experiments (84, 89); hunted by Iris, Shadrack, and Gregor (84-5); heckled by Lutin at the circus (86); practice directed somnambulistic killing (98); three are rendered unconscious by the Deep Sleep in the Cenaculum (147).","notesPages":[251],"id":"glossary-entry-assassin-s","letter":"A"},{"term":"Assassins (Dolophonoi)","definition":"See Dolophonoi.","notesPages":[251],"id":"glossary-entry-assassins-dolophonoi","letter":"A"},{"term":"Asses","definition":"Animals (donkeys, onagers) with which an AMH Computer claims great affinity for machines, citing humans historically calling machines by \"asinine names\" like donkey- engine, jackscrew, spinning jenny, etc. (31).","notesPages":[251],"id":"glossary-entry-asses","letter":"A"},{"term":"Asses (Jack and Jenny)","definition":"Male and female donkeys, used in names for machines (jack-plane, spinning jenny), reflecting the human perception of machines according to an AMH Computer (31).","notesPages":[251],"id":"glossary-entry-asses-jack-and-jenny","letter":"A"},{"term":"Astrology","definition":"Practice taken up \"on their own\" by Computers (1); considered dangerous by Lord Randal's mother because computers might treat predictions as instructions (1); used by AMH Computers for fun to predict human futures, using corrected calculations but acknowledging zodiacal signs are merely fortune-telling devices (29- 30); dismissed by a heckler as pseudoscience but defended by Invisible Alfred as a \"parable-science\" describing a \"parable-universe\" (111).","notesPages":[251,252],"id":"glossary-entry-astrology","letter":"A"},{"term":"Atheists","definition":"People who do not believe in the Theos (38).","notesPages":[252],"id":"glossary-entry-atheists","letter":"A"},{"term":"Atlantic Ocean","definition":"Where the seven richest metamorphic men supposedly meet annually two miles deep (135); dragged for whales by a playful Mark Twain using meridians and parallels as seines (131).","notesPages":[252],"id":"glossary-entry-atlantic-ocean","letter":"A"},{"term":"Atlantic Showhouse","definition":"Location of the Dolphins' Underwater Theater, a source for Structo Lane Dramas (76).","notesPages":[252],"id":"glossary-entry-atlantic-showhouse","letter":"A"},{"term":"Atropos","definition":"One of the Three Fates or \"three ugly sisters\" first encountered with her sisters in a hidden shipboard room, then in Persimmon Manor (114,126); the \"cutting sister\" (126); threatens to cut Inneall's thread (126); put into a deep sleep by Dubu (127); her scissors are foiled by wotto-metal threads placed by Inneall (127, 129).","notesPages":[252],"id":"glossary-entry-atropos","letter":"A"},{"term":"Auctore","definition":"Ablative form of Latin auctor, \"author\"; used here as an authorial attribution to the verse \"In A Green Tree\" (151).","notesPages":[252],"id":"glossary-entry-auctore","letter":"A"},{"term":"Authentic Legends of the Computers and Other Mechanisms, The","definition":"Title of an unpublished book of machine legends, from whose galley sheets an AMH Computer quotes tales about the origin of Mankind and the Serpent (36).","notesPages":[252],"id":"glossary-entry-authentic-legends-of-the-computers-and-other-mechanisms-the","letter":"A"},{"term":"Authentic Mega Persons","definition":"Legal term for individuals who reach the age of majority at ten years old, distinct from \"lesser persons\" who mature at eighteen (146).","notesPages":[252],"id":"glossary-entry-authentic-mega-persons","letter":"A"},{"term":"Autosomes","definition":"Non-sex chromosomes; the Unfallen People possess twenty-two pairs, the same as humans, cited by Ansel Grindstone as \"proof positive\" they are men, not apes (18).","notesPages":[252],"id":"glossary-entry-autosomes","letter":"A"},{"term":"Awakening (Moment of the Awakening of the Second People)","definition":"The anticipated event when the Axel's Golden Apes (Second Humanity) will emerge from their Deep Sleep (142); predicted by Alpha to be imminent (51) and by Lutin to occur at midnight when Axel wakes (143); believed to trigger a worldwide awakening of all Axel's Apes (51, 142); the critical moments involve Axel waking, then waking the others (143, 145).","notesPages":[252],"id":"glossary-entry-awakening-moment-of-the-awakening-of-the-second-people","letter":"A"},{"term":"Axel","definition":"One of the central Three raised together in the Lynn-Randal Experiment (1); an Axel's Ape (3), specifically a Golden Ape/Blue-Eyed Ape/Smithy Ape (3); son of Alpha (20, 51); possesses exceptional intelligence (\"clear off the scale\") (5, 7) and abilities like smelling metal ores (46); proposed the Swinburne motto for The Three (2); first of The Three to learn reading (7); overheard the \"Serpent's Egg\" conversation (2); feared by Iris Lynn-Randal to be a potential \"Serpent's Egg\" (84); enters a 72-hour Deep Sleep in Ape Caverns just before the Experiments end (65); believed by Lutin to be the trigger for the Apes' awakening (143); murdered by a Dolophonoi knife immediately upon waking at midnight (147-8); entombed in a cenotaph on the Ocean Bottom (148).","notesPages":[253],"id":"glossary-entry-axel","letter":"A"},{"term":"Axel, a True Child of Wonder","definition":"Inscription on the cenotaph of Axel the Ape (148).","notesPages":[253],"id":"glossary-entry-axel-a-true-child-of-wonder","letter":"A"},{"term":"Axel to-the-life","definition":"Description of the high-relief carving representing Axel the Ape on his stone cenotaph lid (148).","notesPages":[253],"id":"glossary-entry-axel-to-the-life","letter":"A"},{"term":"Axel's Ape blood","definition":"Component, along with human blood, of the circulating fluid in Inneall's artificial heart/pump system, obtained covertly while Axel slept (48).","notesPages":[253],"id":"glossary-entry-axels-ape-blood","letter":"A"},{"term":"Axel's bones","definition":"The skeletal structure of Axel the Ape, confirmed by X- Ray to be fully human despite his external gargoyle face, apeish jaw, bull-hump (containing nutriment/water), and wide splay feet, all composed of \"flab-flesh\" (42).","notesPages":[253],"id":"glossary-entry-axels-bones","letter":"A"},{"term":"Babbage","definition":"Charles Babbage, English mathematician who conceived the Analytical Engine in 1834. The novel dates its invention to 1835 in its partly fanciful computer history (25); the complete machine was never built.","notesPages":[253],"id":"glossary-entry-babbage","letter":"B"},{"term":"Back door","definition":"Specifically, the door from The Three's contrived habitat into the Lynn-Randal house (5, 9), the access Satrap Saint Ledger builds (Allez-Oop) from his hotel suite to Inneall's Ocean (47), and Arpad Arutinov's The Back Door of History (79, 106).","notesPages":[253],"id":"glossary-entry-back-door","letter":"B"},{"term":"Bait Shop (Happy Charley's/Monkey Charley's)","definition":"A seaside establishment purchased cheaply by Schimp during the End of Summer chaos; Schimp intends to operate it while continuing his intellectual pursuits, renaming it \"Monkey Charley's Bait Shop\" (161- 162). Several bait shops also appear suddenly near Heart's Desire Cove, offering preferred dining for some of the Eleven (58).","notesPages":[254],"id":"glossary-entry-bait-shop-happy-charleys-monkey-charleys","letter":"B"},{"term":"Ball (Lacrosse)","definition":"Played by the Twelve Great Contemporaries; notably carried aloft by Popugai in his crosse-stick pocket or moved underground by Carcajou (65).","notesPages":[254],"id":"glossary-entry-ball-lacrosse","letter":"B"},{"term":"\"Ballad of Invisible Alfred\"","definition":"A poem epigraph for Chapter Ten, containing the lines \"I love to paint with sightless paint, / I love to whack my brush-o\" (105).","notesPages":[254],"id":"glossary-entry-ballad-of-invisible-alfred","letter":"B"},{"term":"Baltimore Catechism","definition":"Religious text cited for its definition of Man as \"a creature composed of body and soul, / And made in the image and likeness of God\" (35).","notesPages":[254],"id":"glossary-entry-baltimore-catechism","letter":"B"},{"term":"Bandicoots","definition":"Marsupials included among the experimental animals sharing the contrived five- acre habitat with The Three (3).","notesPages":[254],"id":"glossary-entry-bandicoots","letter":"B"},{"term":"\"Bandicot Blues\"","definition":"A campfire song sung during the End-of-Summer nights at Heart's Desire Cove (59).","notesPages":[254],"id":"glossary-entry-bandicot-blues","letter":"B"},{"term":"Bands (Gypsy)","definition":"Groups of Romany people who, according to legend, crossed the Ape Bridge into Africa, learned trades from the Unfallen People, and were subsequently led into Egypt, Turkey, and Europe by a golden ape walking ahead of each band (13).","notesPages":[254],"id":"glossary-entry-bands-gypsy","letter":"B"},{"term":"Banquet","definition":"The meal held by the Nine Royal Kids and Sebastian Lazar in the Clubroom Banquet-Hall of the condominium just before midnight on the Third and Last Night of Summerset, preceding their entry into the Cenaculum of the Sleepers (144, 145, 147, 149).","notesPages":[254],"id":"glossary-entry-banquet","letter":"B"},{"term":"Barbarians (New)","definition":"A group described as \"blue-eyed towheaded white trash\" who, for private reasons, decided to pass themselves off as Axel's Apes and joined Alpha's group in Ape Alley (9, 22).","notesPages":[254],"id":"glossary-entry-barbarians-new","letter":"B"},{"term":"Barefoot prophets","definition":"A category of religious figures, including Invisible Alfred and the Christus, contrasted with the rich and powerful who have access to strategic balconies for addressing crowds (109).","notesPages":[254],"id":"glossary-entry-barefoot-prophets","letter":"B"},{"term":"Bas reliefs (Greek)","definition":"Ancient Greek sculptures cited as depicting Titans with \"almost-gargoyle faces,\" similar to Axel's Apes (44).","notesPages":[255],"id":"glossary-entry-bas-reliefs-greek","letter":"B"},{"term":"Base-ten computers","definition":"Designation for early abacuses, explained as deriving from humans' ten fingers, despite the devices often having only nine rods (24).","notesPages":[255],"id":"glossary-entry-base-ten-computers","letter":"B"},{"term":"Battle of Armageddon","definition":"The final apocalyptic battle, predicted by a fortune-teller to begin imminently in the local limestone caverns and coal mines, eventually spreading worldwide (44).","notesPages":[255],"id":"glossary-entry-battle-of-armageddon","letter":"B"},{"term":"Baxter's Buzzards","definition":"Hypothetical creatures whose entrails could, according to an AMH Computer, be used for fortune-telling just as effectively as the machinery of astrology (30).","notesPages":[255],"id":"glossary-entry-baxters-buzzards","letter":"B"},{"term":"Bear (Dubu)","definition":"The young female bear of the Dorantes-Saleh Experiment (55); called \"Little Mother\" by the others (63); considered the \"only commoner\" by Henryetta but insists she is one-sixteenth human (63); claims bears have four brain lobes and access to total knowledge via the \"All-Knowing Wink\" (75); possesses talent for chess (75) and inducing sleep (127); main reading is murder-and- horror novels (124); believes answers are hidden inside a single Acorn (74) and solves the Persimmon Manor murder mystery (153); introduces the concept of the \"Ultimate Egg\" (155).","notesPages":[255],"id":"glossary-entry-bear-dubu","letter":"B"},{"term":"Beauty","definition":"Possessed by The Three (9); associated with the Unfallen People/Gargoyles, whose \"high and harsh beauty\" is comparable to angels or mountains and represents God's intended ideal, challenging human aesthetic standards (17); also an attribute for which Dolophonoi- Assassins are not primarily designed (82).","notesPages":[255],"id":"glossary-entry-beauty","letter":"B"},{"term":"Bed-rock","definition":"The geological foundation beneath Tom Dooley's Island, which the Whales are presumed to be excavating down to in order to build their structures (106).","notesPages":[255],"id":"glossary-entry-bed-rock","letter":"B"},{"term":"Beer (Choc)","definition":"A beverage specialty, described as \"made as Mother Used to Make It,\" available at Heart's Desire Cove (58).","notesPages":[255],"id":"glossary-entry-beer-choc","letter":"B"},{"term":"Bi-location","definition":"The talent, possessed by all Axel's Apes, for instantaneous travel between locations (21); also exhibited by dying India Elephants (95, 128) and said in the novel to be documented in Hubbard's Big Book of Strange Happenings (95).","notesPages":[256],"id":"glossary-entry-bi-location","letter":"B"},{"term":"Big Birthday","definition":"The collective tenth birthdays of the experimental children, with Gajah's expected birth completing her ten-year gestation, anticipated to occur over the last three days of summer, The Three Days of Summerset (57). Big Book of Strange Happenings A book by Hubbard listing eleven cases of human bi- location or trans-location, similar to that used by dying India Elephants (95).","notesPages":[255,256],"id":"glossary-entry-big-birthday","letter":"B"},{"term":"Big Egg","definition":"The mysterious, artificial, approximately five-ton, egg-shaped object that appears while Lutin and her midwife are asleep (154-156,162). Lutin claims it as her offspring, but her actual offspring are three live baby pythons (160). The Egg contains electronic gear and something alive (155-156); its contents remain undisclosed. The adjacent Second Coming passage and the later discussion of a motion-generating universe suggest possible interpretations (155,162); Miol-Mor attends it (160).","notesPages":[256],"id":"glossary-entry-big-egg","letter":"B"},{"term":"Big House","definition":"Specifically, Persimmon Manor on Tom Dooley's Island (115, 116, 157, 159).","notesPages":[256],"id":"glossary-entry-big-house","letter":"B"},{"term":"Bilge-water tonic","definition":"According to Henryetta, the \"universal cure-all for sick pirates,\" prescribed via directive on the Annabella Saint Ledger for any sickness or suppuration (100).","notesPages":[256],"id":"glossary-entry-bilge-water-tonic","letter":"B"},{"term":"Bird-of-paradise feathers","definition":"Metaphorical description of the fletching on the arrow-like stone bridge built by the Unfallen Ones (15).","notesPages":[256],"id":"glossary-entry-bird-of-paradise-feathers","letter":"B"},{"term":"Birdmaster","definition":"A \"probably-human boy,\" simple-minded but able to marshal and inspire vast choirs and orchestras of birds; his unexplained departure diminishes the birds' musical participation at Heart's Desire Cove (60).","notesPages":[256],"id":"glossary-entry-birdmaster","letter":"B"},{"term":"Birthday Banquet","definition":"The celebratory meal held for the Nine Royal Kids on the Third and Last Night of Summerset in the condominium clubroom, immediately preceding their venture into the Ape Caverns (145).","notesPages":[256],"id":"glossary-entry-birthday-banquet","letter":"B"},{"term":"Bishop","definition":"The ecclesiastical rank held by Hieronymous Ignatius Zchold of the Old Religion; this status, according to officials, denied him any special consideration regarding the manner of his execution or the disposal of his body (158).","notesPages":[256],"id":"glossary-entry-bishop","letter":"B"},{"term":"\"Black Sail-Ship\"","definition":"The central image on the Saint Ledger coat-of-arms flag, depicted on a Blue Ocean (49).","notesPages":[256],"id":"glossary-entry-black-sail-ship","letter":"B"},{"term":"\"Black Ship\"","definition":"The ship depicted on the Saint Ledger coat-of-arms flag (49).","notesPages":[257],"id":"glossary-entry-black-ship","letter":"B"},{"term":"Black-smithery","definition":"One of the honest avocations taught by the Unfallen People to the Gypsies, along with cutlery and the tinker trades (13).","notesPages":[257],"id":"glossary-entry-black-smithery","letter":"B"},{"term":"Blaze (Holy)","definition":"The traditional fire lit nightly in Apes' Caverns by lightning striking the main gas jet, enjoyed for twenty-three hours (68).","notesPages":[257],"id":"glossary-entry-blaze-holy","letter":"B"},{"term":"Blood","definition":"Can refer to literal human blood (62, 90), Axel's Ape blood (48), kinship/lineage (10, 157), or serve as a symbolic hostage (68); required for signing the contract between Inneall and Satrap (48); shed avidly by Henryetta as an act of love, according to Lutin (62); used by Tom Dooley as ink (124).","notesPages":[257],"id":"glossary-entry-blood","letter":"B"},{"term":"Bloody Mary Muldoon","definition":"A \"Pirate Queen\" role selected by Inneall for herself (24, 59); requires props like an ocean and ships (24); the name Inneall uses aboard the Annabella Saint Ledger (114); used by Atropos when addressing Inneall (126).","notesPages":[257],"id":"glossary-entry-bloody-mary-muldoon","letter":"B"},{"term":"Bloody Mary Saltwater","definition":"An alternative rebellious cry used by Inneall (23).","notesPages":[257],"id":"glossary-entry-bloody-mary-saltwater","letter":"B"},{"term":"Blue-Eyed Apes","definition":"An alternative name for the Axel's Apes (3); the title of Chapter Two (10); specifically references the apes found in one of five hundred green-tree valleys sought by zoo suppliers (18). See also Ape (Axel's / Smithy / Golden / Blue-Eyed / Yellow).","notesPages":[257],"id":"glossary-entry-blue-eyed-apes","letter":"B"},{"term":"Blue moods","definition":"Gnawing and garish emotional states produced by the tedious, low-quality 'prowls' from Jackdaw Press (8).","notesPages":[257],"id":"glossary-entry-blue-moods","letter":"B"},{"term":"Blue Ocean","definition":"The background field color on the Saint Ledger coat-of- arms flag (49).","notesPages":[257],"id":"glossary-entry-blue-ocean","letter":"B"},{"term":"Bohemian World","definition":"One meaning of the Japanese phrase \"The Floating World\", alongside \"Arty World\" and \"Unmoored World\" (79).","notesPages":[257],"id":"glossary-entry-bohemian-world","letter":"B"},{"term":"Bolts (Lightning)","definition":"Cause of death for Unfallen People taken by God (12); responsible for killing and consuming the bodies of one hundred Axel's Apes scattered in zoos worldwide, all within a five-minute period (21).","notesPages":[257],"id":"glossary-entry-bolts-lightning","letter":"B"},{"term":"Bombs (Directional cluster-bombs)","definition":"Part of the armament aboard the Annabella Saint Ledger (101).","notesPages":[258],"id":"glossary-entry-bombs-directional-cluster-bombs","letter":"B"},{"term":"Bones (Napier's)","definition":"Calculating rods described by John Napier in his 1617 Rabdologiae, often made of ivory. The novel loosely calls them a sophisticated abacus (25).","notesPages":[258],"id":"glossary-entry-bones-napiers","letter":"B"},{"term":"Bongo and His Beepers","definition":"Title of a low-quality children's/teen/adult media series produced by the Jackdaw Two-and-Three Track Press (8).","notesPages":[258],"id":"glossary-entry-bongo-and-his-beepers","letter":"B"},{"term":"Book of Jasher","definition":"The lost book invoked and freely reimagined by the novel. Livius Secundus says he is reconstructing it and explicitly acknowledges that all sorts of things are falsely ascribed to it (72). The novel attributes to it the wrestling passage (88), the First and Second Coming meditation (155), and the transfer of record-keeping from humans to machines to whales (163). These are Lafferty's literary attributions, not authenticated quotations from a surviving ancient text.","notesPages":[258],"id":"glossary-entry-book-of-jasher","letter":"B"},{"term":"Boole","definition":"George Boole, author of the 1859 Treatise on Differential Equations. The novel jokes that it was written to give Babbage's Analytical Engine something to think about (25); that stated purpose is not documented history.","notesPages":[258],"id":"glossary-entry-boole","letter":"B"},{"term":"Bootjack","definition":"A tool whose name exemplifies the human tendency to apply asinine names (\"jack\") to machines (31).","notesPages":[258],"id":"glossary-entry-bootjack","letter":"B"},{"term":"Border-line","definition":"Self-assessment by Lord Randal's father regarding his family's status relative to \"mega persons,\" suggesting they are not important enough to attract the Kangaroo's negative attention but are close (1).","notesPages":[258],"id":"glossary-entry-border-line","letter":"B"},{"term":"Bottom (Ocean)","definition":"The floor of Inneall's Ocean, where the Whales build their Temple-City (136, 137) and where the cenotaphs for Axel, Lord Randal, and Henryetta are located (148, 149, 150); destination of the sinking Tom Dooley's Island and Persimmon Manor (113, 116, 119, 159); is evoked through the literary image of the underwater castle Domdaniel (131); requires specialized adaptation (Ocean Metastasis) for extended visits (133, 135).","notesPages":[258],"id":"glossary-entry-bottom-ocean","letter":"B"},{"term":"Bow-and-arrow","definition":"Weapon invented by Lord Randal but shot farther, faster, and higher by Axel (4).","notesPages":[259],"id":"glossary-entry-bow-and-arrow","letter":"B"},{"term":"Bow (God's)","definition":"A two-stringed bow depicted in God's hands in an ancient cliff mural at Al- Waghe, interpreted by Axel Grindstone as symbolizing God's preparedness with a second option (like Second Eden) (11).","notesPages":[258],"id":"glossary-entry-bow-gods","letter":"B"},{"term":"Boy human","definition":"Designation for Lord Randal within the Lynn-Randal experiment, emphasizing his species (3); also used by Marino the Seal to refer specifically to Lord Randal as one of the assigned pilots of the speedsters (58).","notesPages":[259],"id":"glossary-entry-boy-human","letter":"B"},{"term":"Brass cannon","definition":"An enchanted cannon, the ninety-ninth from the Golden Hind, acquired by Satrap for the Annabella Saint Ledger at Henryetta's insistence; its seven self-perpetuating annihilation shells can hit any target ordered, regardless of distance (95-6, 101).","notesPages":[259],"id":"glossary-entry-brass-cannon","letter":"B"},{"term":"Bread-bushes","definition":"Experimental plants providing sustenance in The Three's contrived habitat (3).","notesPages":[259],"id":"glossary-entry-bread-bushes","letter":"B"},{"term":"Brimstone","definition":"Substance whose strong, frightful smell accompanied the otherworldly wrestling match between Carcajou and Luas (87).","notesPages":[259],"id":"glossary-entry-brimstone","letter":"B"},{"term":"Britannica","definition":"Encyclopedia cited for its definition of Human Culture (39).","notesPages":[259],"id":"glossary-entry-britannica","letter":"B"},{"term":"Bronze-casting","definition":"One of the arts abandoned by humans but reinvented by Computers (33).","notesPages":[259],"id":"glossary-entry-bronze-casting","letter":"B"},{"term":"Bronze-workers","definition":"Craftsmen classification, alongside iron-workers, describing the smithery expertise of the Unfallen Ones (15).","notesPages":[259],"id":"glossary-entry-bronze-workers","letter":"B"},{"term":"Bug-locators","definition":"Devices carried by half of the Royal Kids to detect surveillance \"bugs\" (142).","notesPages":[259],"id":"glossary-entry-bug-locators","letter":"B"},{"term":"Bug-scramblers","definition":"Anti-surveillance devices carried by half of the Royal Kids (142).","notesPages":[259],"id":"glossary-entry-bug-scramblers","letter":"B"},{"term":"Bull-hump","definition":"The animal-like hump on the back of Axel the Ape's neck, functionally like a camel's hump storing nutriment and water, composed entirely of \"flab-flesh\" with no underlying skeletal structure (42).","notesPages":[259],"id":"glossary-entry-bull-hump","letter":"B"},{"term":"Burglar's Jenny","definition":"Original term, according to an AMH Computer, for the tool now known as a burglar's \"jimmy,\" illustrating the application of female asinine names to tools (31).","notesPages":[259],"id":"glossary-entry-burglars-jenny","letter":"B"},{"term":"Burks","definition":"Arthur Burks, historical computer pioneer associated with Von Neumann (25).","notesPages":[260],"id":"glossary-entry-burks","letter":"B"},{"term":"Burlesque shows","definition":"Entertainment format, abandoned by humans but reinvented by Computers who stage their own (33).","notesPages":[260],"id":"glossary-entry-burlesque-shows","letter":"B"},{"term":"Burning Bush","definition":"The biblical manifestation from which God spoke to Moses; cited by Invisible Alfred as an instance where only God's eyes and mouth were visible, similar to his own appearance (110).","notesPages":[260],"id":"glossary-entry-burning-bush","letter":"B"},{"term":"\"Byzantine Intrigue Productions\"","definition":"A genre cited as one of the human sources influencing the dramas performed in Structo Lane (76).","notesPages":[260],"id":"glossary-entry-byzantine-intrigue-productions","letter":"B"},{"term":"Cafe","definition":"Location where Inneall's ghosts gather late at night (29); also refers to Jack Flannagan's Piano Bar and Sidewalk Cafe (151).","notesPages":[260],"id":"glossary-entry-cafe","letter":"C"},{"term":"Cafes (Sidewalk)","definition":"Establishments with colorful umbrellas along the stony shore of Heart's Desire Cove (58); Jack Flannagan's Sidewalk Cafe is one such place (77, 151).","notesPages":[260],"id":"glossary-entry-cafes-sidewalk","letter":"C"},{"term":"Calculator(s)","definition":"Basic computing machines like the abacus (24); Eckert and Mauchly's electronic calculator (25); term used self-referentially by Livius Secundus (Ambulatory Calculators) (72).","notesPages":[260],"id":"glossary-entry-calculator-s","letter":"C"},{"term":"Calendar","definition":"The Whale Temple-City incorporates alignments of stones and turrets serving as a calendar, capable of clocking the heliacal rising of the Dog Star and other events, though this function is now considered customary rather than essential (137).","notesPages":[260],"id":"glossary-entry-calendar","letter":"C"},{"term":"Calking compound","definition":"Waterproofing material; thirty tons are ordered by Quentillius the Fifth to seal Persimmon Manor against the rising ocean (101, 116).","notesPages":[260],"id":"glossary-entry-calking-compound","letter":"C"},{"term":"Calliope (Steam)","definition":"A loud, brass-tubed musical instrument purchased by Satrap Saint Ledger from an antique shop at Henryetta's request (85); played by Henryetta during the circus performance (85); its sound attracted both pleasure-seekers and the Dolophonoi-Assassins (85); moved onto the Annabella Saint Ledger to scare other ships and evil spirits (97, 101); played, \"horribly loud, horribly beautiful,\" after the tragic events involving Gregor McGregor (91).","notesPages":[260,261],"id":"glossary-entry-calliope-steam","letter":"C"},{"term":"Camel's hump","definition":"Compared functionally to the bull-hump on Axel the Ape's neck, which stores nutriment and water (42).","notesPages":[261],"id":"glossary-entry-camels-hump","letter":"C"},{"term":"Campfire songs","definition":"Songs sung by people and 'people' on the shores of Heart's Desire Cove during the chilly End-of-Summer nights, including titles like \"Star People\", \"Skokemchuck Rag\", \"Inneall's Ocean Hallelulah\", etc. (59).","notesPages":[261],"id":"glossary-entry-campfire-songs","letter":"C"},{"term":"Cancer","definition":"The fourth constellation of the Zodiac, depicted conventionally by Invisible Alfred; its hidden sign is revealed as Crocodilus (111).","notesPages":[261],"id":"glossary-entry-cancer","letter":"C"},{"term":"Captain","definition":"The practical and effective leader of the Annabella Saint Ledger's covenanted pirate crew, officially designated as Lanternjaw Lunnigan (119); also the title bestowed upon Ruddy Lord Randal for the Nine Royal Kids' final crisis (122-123); Invisible Alfred addresses the ship's captain (108, 109).","notesPages":[261],"id":"glossary-entry-captain","letter":"C"},{"term":"Caput","definition":"Architectural term for the top part of a pillar; festooned by beautiful blotches of living green sea-lice in the Whales' Temple-City (138).","notesPages":[261],"id":"glossary-entry-caput","letter":"C"},{"term":"Carcajou","definition":"The young male wolverine of the Gruenbaum-McGregor Experiment (55); possesses \"evil intelligence\" yet is also \"clear off the secret-scale\" (55, 64); considered half animal and half devil (64); treacherous but personable and a full member of the Elite Twelve Contemporaries (64); knows many languages but pronounces them roughly until accompanying Popugai (64); carries the lacrosse ball underground through tunnels (65); wrestles Luas in a metamorphosized man-devil form (73, 87-88); declares Lanternjaw Lunnigan Captain of the Annabella Saint Ledger (119); uses a Dolophonoi knife effectively (125); helps entomb Axel and Lord Randal (148) and Henryetta (150); finally heads to \"Monkey Charley's Bait Shop\" (161-2).","notesPages":[261],"id":"glossary-entry-carcajou","letter":"C"},{"term":"Cardinal places","definition":"Prime arenas of the world where events of far- reaching effect are likely to occur; Ape Alley is identified as one such location (43).","notesPages":[262],"id":"glossary-entry-cardinal-places","letter":"C"},{"term":"Cardinals","definition":"Multi-songed birds participating in the enhanced music choruses at Heart's Desire Cove (58).","notesPages":[261],"id":"glossary-entry-cardinals","letter":"C"},{"term":"Cards (Playing)","definition":"Used as an analogy; the Kings and Queens on playing cards have as little connection to real royalty as the planets in astrology have to celestial bodies (30); human ineptitude at cards is noted (39).","notesPages":[262],"id":"glossary-entry-cards-playing","letter":"C"},{"term":"Cards (Punched)","definition":"The medium used by Jacquard's loom (developed in the early 1800s, although the novel says mid-1800s) to dictate weaving patterns, an early form of programming (25).","notesPages":[262],"id":"glossary-entry-cards-punched","letter":"C"},{"term":"Cards (Tarot)","definition":"One method used by Lutin the Pythoness for predicting futures in her sideshow tent (86).","notesPages":[262],"id":"glossary-entry-cards-tarot","letter":"C"},{"term":"Care-takers","definition":"Overly-silent overseers who make adjustments within The Three's contrived habitat, trying to remain unnoticed (4).","notesPages":[262],"id":"glossary-entry-care-takers","letter":"C"},{"term":"Carnivals","definition":"Operations in which the Unfallen People were adept, according to obscure legends (14).","notesPages":[262],"id":"glossary-entry-carnivals","letter":"C"},{"term":"Carob tree","definition":"The tree on which Gregor McGregor hangs himself after fatally shooting Gajah and wounding Riesin (91). The novel calls the Mediterranean evergreen the \"Judas Tree\"; botanically, carob is Ceratonia siliqua, while Judas tree usually denotes Cercis siliquastrum.","notesPages":[262],"id":"glossary-entry-carob-tree","letter":"C"},{"term":"Carry-over guests","definition":"Thirty-two \"quality people\" remaining from previous parties at Persimmon Manor, current with supra-world fellowship but unaware of the outside world's changes (like the Ocean); they readily accept the Manor's impending sinking and resolve to continue partying underwater (116); become subjects of a real-time murder mystery (128).","notesPages":[262],"id":"glossary-entry-carry-over-guests","letter":"C"},{"term":"Carton, Sydney","definition":"Character from Dickens' A Tale of Two Cities, noted for his resemblance to Charles Darnay; Sebastian Lazar denies having a similar resemblance to Hieronymous Zchold (156).","notesPages":[262],"id":"glossary-entry-carton-sydney","letter":"C"},{"term":"Cartoons","definition":"Primary visual medium for 'prowls', often sketchy with characters fully drawn only one frame in a hundred (6); the celestial apparitions created by Invisible Alfred are ultimately revealed to be badly drawn cartoons (111); used metaphorically for hellish figures in fireworks (87).","notesPages":[262],"id":"glossary-entry-cartoons","letter":"C"},{"term":"Carving","definition":"Includes scrimshaw from walrus ivory and wood-carved mottos, arts abandoned by humans but reinvented by Computers (33); also the high-relief representations on the cenotaph lids (148).","notesPages":[263],"id":"glossary-entry-carving","letter":"C"},{"term":"Casings","definition":"Specifically, the casings of half a dozen old, capped natural- gas wells penetrating the Ape Caverns, illegally tapped by the Apes for illumination and power (45).","notesPages":[263],"id":"glossary-entry-casings","letter":"C"},{"term":"Castle","definition":"A potential structure (along with Palace or Monument) that the Whales might be building on the Ocean Bottom (106); also the literary underwater castle Domdaniel, invoked in a quoted fragment (131).","notesPages":[263],"id":"glossary-entry-castle","letter":"C"},{"term":"Castle (Sea-Food)","definition":"Name of Elmer Springer's princely eating establishment at Heart's Desire Cove (58).","notesPages":[263],"id":"glossary-entry-castle-sea-food","letter":"C"},{"term":"Castles","definition":"Structures built by Whales on the Ocean Floor, according to The Child's Big Book of Whales (105); metaphorical castles dreamed of by Lutin (136); built grandly by Whales (105).","notesPages":[263],"id":"glossary-entry-castles","letter":"C"},{"term":"Cat-food factory","definition":"Business owned by the man who collects the bodies of Donatus O'Reily and the nine dead men after the hanging (158).","notesPages":[263],"id":"glossary-entry-cat-food-factory","letter":"C"},{"term":"Cat (Sea-)","definition":"The more pleasant, alternative name for the pseudo-fish printed as Chimaera Monstrusa or \"Nightmare Monster\" (139).","notesPages":[263],"id":"glossary-entry-cat-sea","letter":"C"},{"term":"Catfish (Ocean)","definition":"A food specialty garnished with Crayfish Tails at Heart's Desire Cove (58); also a species flocking to Inneall's Ocean (138).","notesPages":[263],"id":"glossary-entry-catfish-ocean","letter":"C"},{"term":"Cathedrals","definition":"Grand structures built in Europe (12th-14th centuries), according to legend, by the Unfallen People, evidenced by the Gargoyles left as signs (13); used as a metaphor for the original complexity of languages compared to later \"grass houses\" (37).","notesPages":[263],"id":"glossary-entry-cathedrals","letter":"C"},{"term":"Cave","definition":"Underground location where old-settler Apes reside, remarking \"There goes the neighborhood\" (44).","notesPages":[263],"id":"glossary-entry-cave","letter":"C"},{"term":"Cavern","definition":"Refers singularly to the Ape Caverns complex (45, 143, 161).","notesPages":[263],"id":"glossary-entry-cavern","letter":"C"},{"term":"Caverns (Ape)","definition":"The underground habitat of the Axel's Apes, encompassing natural limestone caves, old mine passages, and Ape Alley (9, 45); location of the Cenaculum of the Sleepers (144, 161); scene of the \"Holy Sleep,\" during which a giant hand smothers the nightly fire (67-68).","notesPages":[263,264],"id":"glossary-entry-caverns-ape","letter":"C"},{"term":"Cenoacle / Cenaculum","definition":"The original underground gathering place of the Axel's Apes in Second Eden (45); replicated in Ape Caverns (143), specifically the Cenaculum of the Sleepers (144, 147, 153, 161), the upper room containing the sleeping Apes, accessible via the Executive Passage (144).","notesPages":[264],"id":"glossary-entry-cenoacle-cenaculum","letter":"C"},{"term":"Cenotaphs","definition":"Monumental stone markers found in the Whale Graveyard off San Sabian, erected for whales whose bones are not present (132); also, the specific stone tombs constructed by the Whales on the Ocean Bottom for Axel, Lord Randal, and Henryetta (148, 149, 150); one empty cenotaph bears the name Hieronymous Ignatius Zchold (150, 156). Small, human-sized cenotaphs are central to the Tau-Temple Complex built by Whales (137).","notesPages":[264],"id":"glossary-entry-cenotaphs","letter":"C"},{"term":"Center (Entertainment)","definition":"Heart's Desire Cove's rapid transformation into a major entertainment hub, built by Satrap Saint Ledger as a Memorial Park to Inneall (57).","notesPages":[264],"id":"glossary-entry-center-entertainment","letter":"C"},{"term":"Chaldee (Code)","definition":"The written language, independently reinvented by The Three, used by Axel to write a message in mud marks on the transparent sky-cover (4). Old Chaldee was one of the languages studied by Axel Grindstone (11).","notesPages":[264],"id":"glossary-entry-chaldee-code","letter":"C"},{"term":"Chamber (Pressure)","definition":"Equipment deemed necessary by Lord Randal for humans diving to half-mile depths to avoid the bends (133).","notesPages":[264],"id":"glossary-entry-chamber-pressure","letter":"C"},{"term":"\"Charisma Concerto\"","definition":"A campfire song sung at Heart's Desire Cove (59).","notesPages":[264],"id":"glossary-entry-charisma-concerto","letter":"C"},{"term":"Chimaera Monstrusa","definition":"Name as printed in the novel for the pseudo-fish also called the \"Nightmare Monster\" or, more pleasantly, the \"Sea-Cat\" (139).","notesPages":[264],"id":"glossary-entry-chimaera-monstrusa","letter":"C"},{"term":"Chimp","definition":"Common name for Schimp, the young male chimpanzee (85, 100, 133, 148, 149, 150, 151, 152, 153, 154).","notesPages":[264],"id":"glossary-entry-chimp","letter":"C"},{"term":"Chimpanzee","definition":"Species of Schimp, one of the Twelve Great Contemporaries (55, 63).","notesPages":[264],"id":"glossary-entry-chimpanzee","letter":"C"},{"term":"Chinese fortune cookies","definition":"Compared to the turtles' tongues which, according to Dubu, contain cryptic information yielding total knowledge when read (75).","notesPages":[265],"id":"glossary-entry-chinese-fortune-cookies","letter":"C"},{"term":"Choc Beer","definition":"See Beer (Choc).","notesPages":[265],"id":"glossary-entry-choc-beer","letter":"C"},{"term":"Choice","definition":"Principle strongly believed in by humans in the Floating World, allowing individuals absolute freedom in destination, likened paradoxically to passengers on a single airliner (41); denied to the Nine Dead Hearties regarding accompanying Donatus O'Reily (157); denied to Henryetta regarding shooting the Elephants (90).","notesPages":[265],"id":"glossary-entry-choice","letter":"C"},{"term":"Choke-Cherry Lane","definition":"One of the countrified lanes on the surface above part of Ape Alley (43).","notesPages":[265],"id":"glossary-entry-choke-cherry-lane","letter":"C"},{"term":"Chord","definition":"Responsive feeling evoked by enhanced music in birds (58); the novel prints \"struck a cord,\" a variant or error for the idiom \"struck a chord.\"","notesPages":[273],"id":"glossary-entry-chord","letter":"C"},{"term":"Chorus(es)","definition":"Groups of singing birds (larks, catbirds, mockingbirds, cardinals, crows) at Heart's Desire Cove (58); the rousing chorus joined by people and 'people' on Sidewalk Cafe Row singing \"Have fun, have fun before you're dead\" (77).","notesPages":[265],"id":"glossary-entry-chorus-es","letter":"C"},{"term":"Christus","definition":"Jesus Christ, mentioned as having often spoken from shipboard like Invisible Alfred (109); the strategic balcony is noted as unavailable to him (109).","notesPages":[265],"id":"glossary-entry-christus","letter":"C"},{"term":"Cigar","definition":"An expensive, aromatic cigar smoked elegantly and urbanely, without lungs or breath, by an AMH Computer during a discourse on astrology (30).","notesPages":[265],"id":"glossary-entry-cigar","letter":"C"},{"term":"Cincinnati","definition":"City mentioned as location of a hundred-piece penny- whistle band organized by Computers (33).","notesPages":[265],"id":"glossary-entry-cincinnati","letter":"C"},{"term":"Clanking","definition":"Sound attributed to Inneall by Satrap Saint Ledger, calling her a \"clanking urchin\" (48).","notesPages":[265],"id":"glossary-entry-clanking","letter":"C"},{"term":"Clashes","definition":"Conflicts occurring between the strong-willed Henryetta and her equally determined contemporaries, including the angel Luas (61).","notesPages":[265],"id":"glossary-entry-clashes","letter":"C"},{"term":"Classified","definition":"Designated or categorized, specifically as a Serpent's Egg (84, 117) or regarding security levels of information (implied) (144).","notesPages":[265],"id":"glossary-entry-classified","letter":"C"},{"term":"Closet","definition":"A feature sometimes found in old ranch houses like Persimmon Manor, often containing a literal skeleton (114, 126).","notesPages":[265],"id":"glossary-entry-closet","letter":"C"},{"term":"Clotho","definition":"One of the Three Fates or \"three ugly sisters,\" the spinner of life threads; found by Inneall in Persimmon Manor (114, 126); expresses delight at the three baby python \"foster children\" (160).","notesPages":[266],"id":"glossary-entry-clotho","letter":"C"},{"term":"Code Chaldee","definition":"See Chaldee (Code).","notesPages":[266],"id":"glossary-entry-code-chaldee","letter":"C"},{"term":"Codfishes","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[266],"id":"glossary-entry-codfishes","letter":"C"},{"term":"Coin","definition":"Used to determine surname order in unrandomized marriage law (55); used metaphorically by a Sea Louse (\"I love myself when I coin thunderous words\") (166).","notesPages":[266],"id":"glossary-entry-coin","letter":"C"},{"term":"Coincidence","definition":"Dismissed as the explanation for the hundred lightning bolts striking Axel's Apes simultaneously worldwide (21); cited regarding the resemblance between mechanical horses and biological horses (31); mentioned regarding the synchronicity of dogs and other animals regaining speech after nine thousand years (124).","notesPages":[266],"id":"glossary-entry-coincidence","letter":"C"},{"term":"Coins","definition":"Not struck in the Ape Caverns mint during the three days of Holy Sleep (67).","notesPages":[266],"id":"glossary-entry-coins","letter":"C"},{"term":"Coke-Town (Cut-Throats of)","definition":"Title of a low-quality media series from Jackdaw Press (8).","notesPages":[266],"id":"glossary-entry-coke-town-cut-throats-of","letter":"C"},{"term":"Cold","definition":"Temperature condition during winter in the hills around Second Eden (16); applied by the novel to Jupiter's \"surface\" (60), although Jupiter has no solid surface; used metaphorically in the song \"Excitements Hot and Cold Suite\" (60). Collegiate Dictionary Webster's dictionary, cited for its definition of \"Kangaroo court\" (79).","notesPages":[266],"id":"glossary-entry-cold","letter":"C"},{"term":"Collared-and-chained bear","definition":"Takes the place of the ape in later depictions of Gypsy caravans moving west through Europe (14).","notesPages":[266],"id":"glossary-entry-collared-and-chained-bear","letter":"C"},{"term":"Columns (Marble)","definition":"Square columns, originally limestone sold by Satrap, now fully crystallized variegated marble, being erected by the Whales on the Ocean Bottom (136).","notesPages":[266],"id":"glossary-entry-columns-marble","letter":"C"},{"term":"Combat","definition":"Form of contest, either game or mortal, which Man seems to require (72); pirates bleed heavily in bloody combat (101).","notesPages":[266],"id":"glossary-entry-combat","letter":"C"},{"term":"Combinations","definition":"Unlikely combinations and circumstances juxtaposed can result in \"wild and extreme talents\" or \"disasters\" like \"Serpent's Eggs\" (81-2).","notesPages":[267],"id":"glossary-entry-combinations","letter":"C"},{"term":"Computer Aegis","definition":"The protective authority or umbrella under which cranky human remnants attempt to shelter by passing themselves off as AMHs (69).","notesPages":[267],"id":"glossary-entry-computer-aegis","letter":"C"},{"term":"Computer Age (Seventh)","definition":"The current technological era of mankind, of which present-day computers see themselves as the fruit (37).","notesPages":[267],"id":"glossary-entry-computer-age-seventh","letter":"C"},{"term":"Computer-child","definition":"A grotesque offspring born naturally (in the human manner) to an AMH Computer in Structo Lane, did not breed true initially (32).","notesPages":[267],"id":"glossary-entry-computer-child","letter":"C"},{"term":"Computer-enhanced human music","definition":"A musical genre featured at the entertainment center in Heart's Desire Cove, attracting music lovers and birds (57).","notesPages":[267],"id":"glossary-entry-computer-enhanced-human-music","letter":"C"},{"term":"Computer(s)","definition":"Electronic entities possessing varying degrees of intelligence, mobility, and consciousness; range from historical devices (abacus, \"Analytical Engine\") (24-5) to sophisticated Ambulatory Mime-Human Computers (AMHs) (3, 25-33); have taken up Astrology (1); can lack ability to distinguish prediction from instruction (1); some are members of the Kangaroo (80, 83); run world population scans (82); engage in arts like penny-whistle bands and bronze-casting (33); subject to taking over log-keeping from humans, then losing it to Whales due to dishonesty (164); includes specific individuals like Inneall (1) and Livius Secundus (70).","notesPages":[267],"id":"glossary-entry-computer-s","letter":"C"},{"term":"Computer vanity","definition":"A motivation, alongside human vanity, for creating AMHs; succeeded human vanity in driving the creation (26).","notesPages":[267],"id":"glossary-entry-computer-vanity","letter":"C"},{"term":"Computer World","definition":"The realm or sphere of computer existence and activity, noted for its increasing sophistication and internal anomalies (33).","notesPages":[267],"id":"glossary-entry-computer-world","letter":"C"},{"term":"Computerized lass","definition":"Satrap Saint Ledger's slightly mocking term for Inneall (48).","notesPages":[267],"id":"glossary-entry-computerized-lass","letter":"C"},{"term":"Concatenated","definition":"Linked together in a chain or series; used to describe the complex structure of evil originating from the misuse of free will (35); also describes Dubu's exasperating, mysterious grin (163) and layers of mysteries (163).","notesPages":[267,268],"id":"glossary-entry-concatenated","letter":"C"},{"term":"Concerned","definition":"Emotion felt by the Royal Kids about the waterproofing of Persimmon Manor (117); the companions' concern about the menace of the wolverenes and the three sisters (102-103).","notesPages":[268],"id":"glossary-entry-concerned","letter":"C"},{"term":"Concerto (Charisma)","definition":"A campfire song sung at Heart's Desire Cove (59).","notesPages":[268],"id":"glossary-entry-concerto-charisma","letter":"C"},{"term":"Concourses","definition":"Large open spaces or thoroughfares within the giant underwater stone structures built by Whales (105, 132).","notesPages":[268],"id":"glossary-entry-concourses","letter":"C"},{"term":"Concrete power","definition":"Element, along with abstract laws, comprising the mere impersonal mechanism of the State (78).","notesPages":[268],"id":"glossary-entry-concrete-power","letter":"C"},{"term":"Conditions","definition":"Circumstances affecting life; shared happy conditions of the carry-over guests at Persimmon Manor (\"For them, no party ever had to end\") (116); the third condition of people needing repentance (110).","notesPages":[268],"id":"glossary-entry-conditions","letter":"C"},{"term":"Condominium","definition":"Triple condominium suite shared by Satrap Saint Ledger, Livius Secundus, and Felix Culebra y Columba in Structo Lane (71); its clubroom houses the Eleven Young People (71) and later hosts the Birthday Banquet (144).","notesPages":[268],"id":"glossary-entry-condominium","letter":"C"},{"term":"Condor-winged","definition":"Description of Popugai, emphasizing his ability for high flight and overview (64).","notesPages":[268],"id":"glossary-entry-condor-winged","letter":"C"},{"term":"Confessions of an English Opium-Eater","definition":"Work by Thomas de Quincey to which the novel attributes the passage about departing summer and sea mists (132). The passage actually occurs in \"Dream-Fugue,\" part III of The English Mail-Coach.","notesPages":[302],"id":"glossary-entry-confessions-of-an-english-opium-eater","letter":"C"},{"term":"Confidence","definition":"State displayed by Invisible Alfred when launching into his sermon after successfully summoning a whale (110).","notesPages":[268],"id":"glossary-entry-confidence","letter":"C"},{"term":"Confined","definition":"Limited or restricted; the popular idea that venial and adulterous generations are hardly confined to belief (112); Riesin warns the fourth Dolophonoi not to confine himself merely to monitoring (89).","notesPages":[268],"id":"glossary-entry-confined","letter":"C"},{"term":"Confused","definition":"Mental state of The Three after Axel overheard the Serpent's Egg conversation (2); state of the enclave 'Ape Caverns' (9); state of Lutin's visions (154); state of apperception regarding the wrestling match (87).","notesPages":[268],"id":"glossary-entry-confused","letter":"C"},{"term":"Confusion","definition":"State of the building-activity of the Whales to the unpenetrating eye (137).","notesPages":[269],"id":"glossary-entry-confusion","letter":"C"},{"term":"Conger eels","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[269],"id":"glossary-entry-conger-eels","letter":"C"},{"term":"Connected","definition":"Linked or associated; Lord Randal denies Invisible Alfred is connected with the Royal Kids' supposed movement (113); gravity anomaly is connected with the drums of Invisible Paint (97).","notesPages":[269],"id":"glossary-entry-connected","letter":"C"},{"term":"Connection","definition":"Relationship or link; the human connection discussed by an AMH Computer (31); the connection between Romany Legends and the Unfallen People believed by Axel Grindstone based on voices (14); connections between astrology and celestial bodies (30); the type of connections made by AMH Computers based on stimulus (32); Inneall's ability to research through \"connections\" (121).","notesPages":[269],"id":"glossary-entry-connection","letter":"C"},{"term":"Connections","definition":"Relationships between entities; the nature of the human connection (31); types of connections made by AMHs (32); dubious human connections regarding the airliner analogy (41); Inneall's research capability via \"connections\" (121).","notesPages":[269],"id":"glossary-entry-connections","letter":"C"},{"term":"Conquerors","definition":"Specifically, the Moguls who came to India as conquerors and despoilers, slaying the Empress Elephants (92).","notesPages":[269],"id":"glossary-entry-conquerors","letter":"C"},{"term":"Conscience","definition":"Internal moral sense; an AMH claims it can use sinister means with a clear conscience, then denies that AMHs have consciences and calls this a human cliché (31); the faculty represented by the reigning \"sleepy one\" among the Unfallen People (19).","notesPages":[269],"id":"glossary-entry-conscience","letter":"C"},{"term":"Conscious","definition":"State of awareness; denied by Inneall about herself initially (23); attribute of cartoon characters only perceived subliminally (6); state during which Inneall does diversions for her ocean-making (59).","notesPages":[269],"id":"glossary-entry-conscious","letter":"C"},{"term":"Consciousness","definition":"State of being aware; denied by Inneall for computers, though she researches it completely (23).","notesPages":[269],"id":"glossary-entry-consciousness","letter":"C"},{"term":"Consecrated","definition":"Made holy; status of the body of Hieronymous Ignatius Zchold, Priest of the Old Religion, making him not want it eaten by dogs (122).","notesPages":[269],"id":"glossary-entry-consecrated","letter":"C"},{"term":"Consensus eschatology","definition":"A complete agreement on aim, goal, direction, destination, and final end, possessed oddly enough by Intelligent Computers but kept secret from humans (41).","notesPages":[270],"id":"glossary-entry-consensus-eschatology","letter":"C"},{"term":"Consensus quality","definition":"The shared supra-world fellowship and standard possessed by the thirty- two carry-over guests at Persimmon Manor (116).","notesPages":[270],"id":"glossary-entry-consensus-quality","letter":"C"},{"term":"Consensus voice","definition":"The \"all-people throatiness\" adopted by media after acknowledging universal ethnicity (6).","notesPages":[270],"id":"glossary-entry-consensus-voice","letter":"C"},{"term":"Consequences","definition":"Results or effects; hauntings encountered in daylight are of no consequence (125).","notesPages":[270],"id":"glossary-entry-consequences","letter":"C"},{"term":"Consideration","definition":"Thoughtful attention; denied to Bishop Zchold by officials regarding his execution (158); Donatus O'Reily asks this favor of others (122).","notesPages":[270],"id":"glossary-entry-consideration","letter":"C"},{"term":"Conspicuous","definition":"Easily seen or noticed; gambling is the most conspicuous human vulnerability (38); Rachel's mourning is a conspicuous case (81).","notesPages":[270],"id":"glossary-entry-conspicuous","letter":"C"},{"term":"Constellated physician","definition":"The professional status of the midwife-nurse attending Lutin (154, 155).","notesPages":[270],"id":"glossary-entry-constellated-physician","letter":"C"},{"term":"Constellation (Interloper)","definition":"The Kangaroo, seen in the sign of Virgo (76).","notesPages":[270],"id":"glossary-entry-constellation-interloper","letter":"C"},{"term":"Constellations","definition":"The twelve traditional groupings of stars forming the Zodiac (Aries, Taurus, etc.), depicted by Invisible Alfred; identified by him as masks for the true signs (Crocodilus, Panther, Leviathans, Kanguruus, etc.) and as corresponding to the twelve Apostles (111).","notesPages":[270],"id":"glossary-entry-constellations","letter":"C"},{"term":"Constructions (Whales')","definition":"The Temple-City and associated structures built by the Whales on the Ocean Bottom, featuring varicolored marble and Wichita-Mountain Granite, adorned with living green sea- lice (137).","notesPages":[270],"id":"glossary-entry-constructions-whales","letter":"C"},{"term":"Consume","definition":"To use up or ingest; Mushroom Wine and Protein-Oil Olio-Stew were the only dishes every one of the Eleven could consume; individual favorites were also provided (72); lightning consumed the bodies of the dead Axel's Apes (21).","notesPages":[271],"id":"glossary-entry-consume","letter":"C"},{"term":"Consummate","definition":"Perfect or highly skilled; refers to the genius of the dove Yonah (71) and the showmanship of the animal performers (86).","notesPages":[270],"id":"glossary-entry-consummate","letter":"C"},{"term":"Contact","definition":"Communication or interaction; common people came into contact with Lord Randal (123).","notesPages":[271],"id":"glossary-entry-contact","letter":"C"},{"term":"Contained","definition":"Held within; knowledge contained in Dubu's brain (75); crypto-memory contained within human under-minds (70); phrase used by Henryetta about the contents of Invisible Paint drums (97).","notesPages":[271],"id":"glossary-entry-contained","letter":"C"},{"term":"Container","definition":"Metaphor for the human brain, capable of holding three times more than ever asked (40).","notesPages":[271],"id":"glossary-entry-container","letter":"C"},{"term":"Contaminated","definition":"Compromised or corrupted; the Experiment of The Three possibly contaminated by their contacts with pre-postliterate culture (9).","notesPages":[271],"id":"glossary-entry-contaminated","letter":"C"},{"term":"Contemplation","definition":"Deep thought; rapturous self-contemplation attributed to Man (35); state occupying eighteen hours daily for the prophet Alpha (51).","notesPages":[271],"id":"glossary-entry-contemplation","letter":"C"},{"term":"Contemporaries","definition":"Individuals existing at the same time; Jasper Junkins (great contemporary philosopher) (8); Henryetta's group, all excelling in everything (61); the Twelve Great Contemporaries who took up lacrosse (65).","notesPages":[271],"id":"glossary-entry-contemporaries","letter":"C"},{"term":"Contemporary","definition":"Existing or occurring at the present time; architecture of the Whales' structure (106).","notesPages":[271],"id":"glossary-entry-contemporary","letter":"C"},{"term":"Content","definition":"Substance or meaning; the method and content of Satrap's indoctrination into Oceanic Metastasis is secret (134).","notesPages":[271],"id":"glossary-entry-content","letter":"C"},{"term":"Contest","definition":"Competition, whether game or mortal combat, seemingly necessary for Man's vitality (72).","notesPages":[271],"id":"glossary-entry-contest","letter":"C"},{"term":"Contexts","definition":"Circumstances or settings; music acquires different contexts with different listeners (5); human inability to understand their own context (72); bi-location occurs in contexts other than dying elephants (95).","notesPages":[271],"id":"glossary-entry-contexts","letter":"C"},{"term":"Continent","definition":"Large landmass; the novel compares the fishes' discovery of new ocean waters to humans hearing of a new continent and finding the rumor true (138). No actual new continent is announced. A continent is also one element of \"The Life Affair\" (74).","notesPages":[272],"id":"glossary-entry-continent","letter":"C"},{"term":"Continent (North American)","definition":"Landmass where the novel fancifully traces lacrosse to Saint Brandon in 536 (65). Historically, lacrosse is an Indigenous North American game.","notesPages":[271],"id":"glossary-entry-continent-north-american","letter":"C"},{"term":"Continents","definition":"Large landmasses included in the scope of \"The Life Affair\" (74).","notesPages":[272],"id":"glossary-entry-continents","letter":"C"},{"term":"Contingent","definition":"Dependent on circumstances; the Kangaroo operates on the unconscious level of its contingent members (83).","notesPages":[272],"id":"glossary-entry-contingent","letter":"C"},{"term":"Contraption","definition":"Lanternjaw refers to Inneall as a \"little contraption\" (98).","notesPages":[272],"id":"glossary-entry-contraption","letter":"C"},{"term":"Contrary","definition":"Oppositional or perverse; the Human species is the most contrary, and Henryetta the most contrary human (61).","notesPages":[272],"id":"glossary-entry-contrary","letter":"C"},{"term":"Contrivances","definition":"Devices or schemes; part of Human Culture (39); entities that would block the \"Fulfillment of the World\" (93); legal and extra-legal groups seeking Ape Alley (43).","notesPages":[272],"id":"glossary-entry-contrivances","letter":"C"},{"term":"Contrived","definition":"Artificial or deliberately created; The Three's five-acre habitat (3, 9, 108); Inneall's ambulatory form (9); the rippling blue of Inneall's ocean (24); the pirate names given by Inneall and Henryetta (98); the pirates' costumes (99).","notesPages":[272],"id":"glossary-entry-contrived","letter":"C"},{"term":"Control","definition":"Power or influence; Satrap Saint Ledger likes to be in control (70); Inneall suspects her imprinting and \"Multiple Run-Amoks\" are out of control (50).","notesPages":[272],"id":"glossary-entry-control","letter":"C"},{"term":"Conventional","definition":"Standard or customary; the twelve Zodiac constellations are merely conventional masks for the true signs (111).","notesPages":[272],"id":"glossary-entry-conventional","letter":"C"},{"term":"Conventions","definition":"Established practices or symbols; the prosaic Floating World possibly just a collection of symbols and covering conventions; alternatively, \"our world\" only a collection of allegories, metaphors, symbols and conventions (17, 141).","notesPages":[272],"id":"glossary-entry-conventions","letter":"C"},{"term":"Conversation","definition":"Spoken exchange; the breakfast conversations of Lord Randal's parents that terrified The Three (1, 2); conversations in the Ape Cavern clubs cease during the Holy Sleep (67).","notesPages":[272],"id":"glossary-entry-conversation","letter":"C"},{"term":"Conversations","definition":"Discussions; Invisible Alfred's eavesdropping alleged by Carcajou (149); lighthearted banter among the Nine, Satrap, Livius, and Felix (147).","notesPages":[273],"id":"glossary-entry-conversations","letter":"C"},{"term":"Convert","definition":"To change form or substance; a single small computer or earthworm could theoretically convert the whole world (27).","notesPages":[273],"id":"glossary-entry-convert","letter":"C"},{"term":"Coon-dog crazy","definition":"State of extreme dementia predicted for the last living pirate (Lanternjaw), surrounded by the other pirates' skeletons aboard the invisible ghost ship (121).","notesPages":[273],"id":"glossary-entry-coon-dog-crazy","letter":"C"},{"term":"Coon hunting","definition":"Hobby abandoned by humans, reinvented by Computers (using mechanical coons) (33).","notesPages":[273],"id":"glossary-entry-coon-hunting","letter":"C"},{"term":"Coons (Mechanical)","definition":"Artificial animals required for Computers to practice coon hunting, as real coons are extinct (33).","notesPages":[273],"id":"glossary-entry-coons-mechanical","letter":"C"},{"term":"Cooperation","definition":"Spirit noted as more prominent now than the previous machine attitude of \"double-talk them, bring them to a slow boil\" regarding humans (31).","notesPages":[273],"id":"glossary-entry-cooperation","letter":"C"},{"term":"Coral","definition":"Material forming the chairs and table where the seven richest metamorphic men supposedly meet two miles deep in the Atlantic (135).","notesPages":[273],"id":"glossary-entry-coral","letter":"C"},{"term":"Coral chairs","definition":"Seating for the seven richest metamorphic men at their deep-ocean meeting place (135).","notesPages":[273],"id":"glossary-entry-coral-chairs","letter":"C"},{"term":"Coral table","definition":"Furniture at the deep-ocean meeting place of the seven richest metamorphic men (135).","notesPages":[273],"id":"glossary-entry-coral-table","letter":"C"},{"term":"Cordial (Apple)","definition":"Drink consumed by Inneall, Carcajou, and Schimp at Jack Flannagan's Piano Bar (151).","notesPages":[273],"id":"glossary-entry-cordial-apple","letter":"C"},{"term":"Core","definition":"Central part; the bright ideal of Honor Itself at the core of related rituals (118); the Tau-Temple at the core of the Whale Temple- City (137).","notesPages":[273],"id":"glossary-entry-core","letter":"C"},{"term":"Corner","definition":"Location; a far corner of Ethiopia chosen by Axel Grindstone for Second Eden (12); corner of city strip pits where Inneall began her ocean (24); corners of Ape Cavern crossed by city sewers (45); location of the little pythoness during Satrap's lecture (101).","notesPages":[273,274],"id":"glossary-entry-corner","letter":"C"},{"term":"Corners","definition":"Boundary markers or reference points; The Three Corners of the World (Chapter One title) (1).","notesPages":[274],"id":"glossary-entry-corners","letter":"C"},{"term":"Cornus (Capricornus)","definition":"Capricorn, the tenth constellation of the Zodiac (111).","notesPages":[274],"id":"glossary-entry-cornus-capricornus","letter":"C"},{"term":"Cosmopolitan","definition":"Worldly or universal in scope; the Kangaroo is described as high-level cosmopolitan (80).","notesPages":[274],"id":"glossary-entry-cosmopolitan","letter":"C"},{"term":"Cosmopolitans","definition":"Worldly individuals; AMHs passed themselves off as such (26).","notesPages":[274],"id":"glossary-entry-cosmopolitans","letter":"C"},{"term":"Cost","definition":"Price or expenditure; the Floating World is very nearly a free- cost world (79).","notesPages":[274],"id":"glossary-entry-cost","letter":"C"},{"term":"Costume","definition":"Outfit worn for a particular activity or role; the 'Elegance- for-Hire' Costume Shops visited by the Eleven (76).","notesPages":[274],"id":"glossary-entry-costume","letter":"C"},{"term":"Costumer","definition":"Supplier of costumes; provided the pirate duds for the Annabella Saint Ledger crew (99); suggested source of Axel's Ape's \"disguises\" (42).","notesPages":[274],"id":"glossary-entry-costumer","letter":"C"},{"term":"Costumes","definition":"Clothing worn by the pirate crewmen, sent by a costumer at Inneall and Henryetta's behest, deemed too high-binding in the crotch (99).","notesPages":[274],"id":"glossary-entry-costumes","letter":"C"},{"term":"Couch (Snake)","definition":"Long, low piece of furniture upon which Lutin reclines in her lying-in room (154).","notesPages":[274],"id":"glossary-entry-couch-snake","letter":"C"},{"term":"Couches (Stone)","definition":"Furniture found in the underwater City of Lyonesse, twenty times the length of a man (105).","notesPages":[274],"id":"glossary-entry-couches-stone","letter":"C"},{"term":"Council of War","definition":"Meeting held by the Nine Royal Kids and Lanternjaw Lunnigan in the crows-nest to plan against the Dolophonoi and the Kangaroo during the final night (142, 143, 145).","notesPages":[274],"id":"glossary-entry-council-of-war","letter":"C"},{"term":"Counseling (Interspecies)","definition":"Profession Popugai intends to pursue upon returning to New Zealand (161).","notesPages":[274],"id":"glossary-entry-counseling-interspecies","letter":"C"},{"term":"Counter-action","definition":"Defensive measures the Kangaroo might take if the Nine arrive in the Cenaculum too early (145).","notesPages":[275],"id":"glossary-entry-counter-action","letter":"C"},{"term":"Counter-attack","definition":"Capability possessed by the Annabella Saint Ledger, enabling retaliation against invaders all the way to the ocean bottom (101).","notesPages":[275],"id":"glossary-entry-counter-attack","letter":"C"},{"term":"Countered","definition":"Opposed or responded to; Atropos had likely countered similar tricks (wotto- metal threads) before (127).","notesPages":[275],"id":"glossary-entry-countered","letter":"C"},{"term":"Counterparts","definition":"Entities corresponding to others; Luas and Lutin are too ethical to tell answers, as are their counterparts everywhere (74).","notesPages":[275],"id":"glossary-entry-counterparts","letter":"C"},{"term":"Country Lane (Green)","definition":"Picturesque lane on the surface above Ape Alley (43, 45).","notesPages":[275],"id":"glossary-entry-country-lane-green","letter":"C"},{"term":"Countryside","definition":"Rural area, one element woven into \"The Life Affair\" (74).","notesPages":[275],"id":"glossary-entry-countryside","letter":"C"},{"term":"Couple","definition":"A pair, usually married; surnames of married couples recently unrandomized by law (54); the sponsor couple of an Experiment gives it their name (55).","notesPages":[275],"id":"glossary-entry-couple","letter":"C"},{"term":"Couple (Clement and Rose-of-Sharon)","definition":"Guests at Persimmon Manor, serving as two of Donatus O'Reily's four 'seconds' for his hanging (124).","notesPages":[275],"id":"glossary-entry-couple-clement-and-rose-of-sharon","letter":"C"},{"term":"Couple (Dorantes-Saleh)","definition":"Sponsors of the experiment involving Lutin, Dubu, and Schimp; accused by Henryetta of encouraging Lutin's promiscuity before her adoption by Felix (73). Lutin calls this scandal-mongering.","notesPages":[275],"id":"glossary-entry-couple-dorantes-saleh","letter":"C"},{"term":"Couple (Wintergreen-Luna)","definition":"Sponsors of the experiment involving Marino, Luas, and Henryetta; obtained the angel Luas with great difficulty (61).","notesPages":[275],"id":"glossary-entry-couple-wintergreen-luna","letter":"C"},{"term":"Court (Kangaroo)","definition":"Slang U.S. term for an irresponsible, unauthorized, or irregular tribunal disregarding law and justice; applied metaphorically to the Kangaroo organization (79).","notesPages":[275],"id":"glossary-entry-court-kangaroo","letter":"C"},{"term":"Courts irregular","definition":"Unfathomable or non-standard operations attributed to the ruling Kangaroo in a Structo Alley Music-Hall song (78).","notesPages":[275],"id":"glossary-entry-courts-irregular","letter":"C"},{"term":"Covenanted","definition":"Bound by solemn agreement; the pirate crew of the Annabella Saint Ledger operate under a covenant (\"all for one and one for all, share and share alike, none superior and none inferior\") (119); applies also to the Nine Royal Kids (148).","notesPages":[276],"id":"glossary-entry-covenanted","letter":"C"},{"term":"Covenanted Nine","definition":"The remaining members of the Royal Kids after the loss of Axel, Gajah, and Luas (115).","notesPages":[276],"id":"glossary-entry-covenanted-nine","letter":"C"},{"term":"Cover (Stone)","definition":"Lid of a cenotaph (148, 150).","notesPages":[276],"id":"glossary-entry-cover-stone","letter":"C"},{"term":"Covering","definition":"Concealing or overlaying; the Floating World possibly just a collection of symbols and covering conventions (141).","notesPages":[276],"id":"glossary-entry-covering","letter":"C"},{"term":"Cow-and-sheep barn","definition":"Birthplace of the King and Creator of the Universe, according to The Book of Jasher, cited as an example of ridiculous circumstances surrounding the First Coming (155).","notesPages":[276],"id":"glossary-entry-cow-and-sheep-barn","letter":"C"},{"term":"Cow-blanket","definition":"Swaddling cloth used for the King and Creator born in a barn (155).","notesPages":[276],"id":"glossary-entry-cow-blanket","letter":"C"},{"term":"Crab","definition":"Constellation Cancer, whose conventional mask hides the true sign Crocodilus (111).","notesPages":[276],"id":"glossary-entry-crab","letter":"C"},{"term":"Crabby Roger","definition":"One of two Fast and Scampering Boats provided by Satrap Saint Ledger for the Eleven's use, technically a Ship Boat of the Annabella Saint Ledger (58).","notesPages":[276],"id":"glossary-entry-crabby-roger","letter":"C"},{"term":"Crash course","definition":"Intensive instruction; Invisible Alfred requests this from Satrap regarding Oceanic Metastasis (134).","notesPages":[276],"id":"glossary-entry-crash-course","letter":"C"},{"term":"Crawling","definition":"Movement employed by Sebastian Lazar when emerging from the priest's hole (156).","notesPages":[276],"id":"glossary-entry-crawling","letter":"C"},{"term":"Crayfish tails","definition":"Garnish for Ocean Catfish specialty at Heart's Desire Cove (58).","notesPages":[276],"id":"glossary-entry-crayfish-tails","letter":"C"},{"term":"Crazy (Coon-Dog)","definition":"See Coon-Dog Crazy.","notesPages":[276],"id":"glossary-entry-crazy-coon-dog","letter":"C"},{"term":"Created","definition":"Brought into existence; Adam created thirty years before Prester John (12); Man made in God's image (35); state in which nature was first created (35).","notesPages":[276],"id":"glossary-entry-created","letter":"C"},{"term":"Creation (Perfect)","definition":"Designation for Mankind at origin, despite fitting badly into the world made for him (34).","notesPages":[277],"id":"glossary-entry-creation-perfect","letter":"C"},{"term":"Creator","definition":"The King and Creator of the Universe, reference to the figure of the First Coming (155).","notesPages":[277],"id":"glossary-entry-creator","letter":"C"},{"term":"Creature","definition":"Singular being; Man defined as composed of body and soul (35); the \"Perfect Creature\" attempted by the Theos (36); refers to individual beings of various species (11, 71, 130, 138).","notesPages":[277],"id":"glossary-entry-creature","letter":"C"},{"term":"Creatures","definition":"Living beings; includes experimental plants, insects, mammals, marsupials, worms, fish, fowl (3); whales (11, 106); humans (34, 35, 71, 74, 130); metamorphic ocean denizens (135); various fish and shelly folks (138); pythons (103); elephants (132).","notesPages":[277],"id":"glossary-entry-creatures","letter":"C"},{"term":"Creatures (Metamorphic)","definition":"Beings capable of changing form, specifically the legendary seven richest men who can turn into Deep Ocean Denizens (135).","notesPages":[277],"id":"glossary-entry-creatures-metamorphic","letter":"C"},{"term":"Creed","definition":"System of belief; Sebastian Lazar refers to the Old Religion as the \"obsolete creed\" (156).","notesPages":[277],"id":"glossary-entry-creed","letter":"C"},{"term":"Crew","definition":"Personnel operating a ship; paid by Satrap for Inneall's yacht (47, 48); pirate crew of the Annabella Saint Ledger (98, 108, 119, 120); attitude of the crew (100).","notesPages":[277],"id":"glossary-entry-crew","letter":"C"},{"term":"Crewman (Pirate)","definition":"Designation for Lanternjaw Lunnigan (115, 119) and Sebastian Lazar (98, 134).","notesPages":[277],"id":"glossary-entry-crewman-pirate","letter":"C"},{"term":"Crewmen","definition":"Assigned other tasks by Satrap (49); addressed by Invisible Alfred (108); all pirates on the Annabella (119).","notesPages":[277],"id":"glossary-entry-crewmen","letter":"C"},{"term":"Crisis","definition":"Hour of danger or decision; faced by the Nine Royal Kids (123).","notesPages":[277],"id":"glossary-entry-crisis","letter":"C"},{"term":"Critical moment","definition":"The instant just after midnight cockcrow when Axel wakes the other Apes, during which he is vulnerable (145).","notesPages":[277],"id":"glossary-entry-critical-moment","letter":"C"},{"term":"Critical times","definition":"Period known as \"The Enlargement of the World\" (113).","notesPages":[277],"id":"glossary-entry-critical-times","letter":"C"},{"term":"Critics","definition":"Persons who evaluate; most believe sea-lice have stylistic edge over humans (165). Crocodilus The true sign revealed behind the mask of Cancer the Crab (111).","notesPages":[277,278],"id":"glossary-entry-critics","letter":"C"},{"term":"Crook","definition":"The bridge of an Archangel's nose, hypothesized by Ansel Grindstone to be a hundred yards deep (17).","notesPages":[278],"id":"glossary-entry-crook","letter":"C"},{"term":"Cross-fertilization","definition":"Interaction between different species or types, considered stimulating; proposed experimentally between AMHs and humans (32).","notesPages":[278],"id":"glossary-entry-cross-fertilization","letter":"C"},{"term":"Cross-shaped","definition":"Form of the Tau-Temple at the core of the Whale Temple-City (137).","notesPages":[278],"id":"glossary-entry-cross-shaped","letter":"C"},{"term":"Cross words","definition":"Banter or argument; exchanged by Pleasure People with mountebanks (109).","notesPages":[278],"id":"glossary-entry-cross-words","letter":"C"},{"term":"Crosse-stick","definition":"Equipment used in lacrosse; Popugai carries the ball in the pocket of his stick held in his beak (65).","notesPages":[278],"id":"glossary-entry-crosse-stick","letter":"C"},{"term":"Crossed","definition":"Moved from one side to the other; Ape Bridge crossed by the Unfallen and Gypsies in the novel's legends, and possibly by Moses (12-13); city sewers crossed corners of Ape Cavern (45).","notesPages":[278],"id":"glossary-entry-crossed","letter":"C"},{"term":"Crow-calls","definition":"Vocalizations of crows, heard in mighty ten-thousand voice choruses (58).","notesPages":[279],"id":"glossary-entry-crow-calls","letter":"C"},{"term":"Crowd","definition":"Gathering of people; attracted by Invisible Alfred's novelty (109); joined Lutin in heckling Assassins (86); impressed by Alfred more than the carry-over guests were, though neither group respected him (123).","notesPages":[278],"id":"glossary-entry-crowd","letter":"C"},{"term":"Crowded","definition":"Filled with many occupants; the crows-nest becomes crowded with the Nine and Lanternjaw (142-3).","notesPages":[278],"id":"glossary-entry-crowded","letter":"C"},{"term":"Crowds","definition":"Multitudes of people; addressed by Invisible Alfred (109); attracted to the circus by the calliope (85).","notesPages":[278],"id":"glossary-entry-crowds","letter":"C"},{"term":"Crowed","definition":"Sound made by the Midnight Cock upon being unhooded (156).","notesPages":[278],"id":"glossary-entry-crowed","letter":"C"},{"term":"Crowing","definition":"Sound made by a cock; the Midnight Crowing Cock signals the Apes' awakening (142).","notesPages":[278],"id":"glossary-entry-crowing","letter":"C"},{"term":"Crowing Cock (Midnight)","definition":"Variant term for the Midnight Cock (142).","notesPages":[278],"id":"glossary-entry-crowing-cock-midnight","letter":"C"},{"term":"Crown","definition":"Topmost part; humanity healthy from roots to crown after pruning (81); Man's a king without a crown (34).","notesPages":[278],"id":"glossary-entry-crown","letter":"C"},{"term":"Crows","definition":"Birds known for loud calls; form ten-thousand-voice choruses at Heart's Desire Cove, while swifts, swallows, and shrikes perform air dances (58); chortle at Invisible Alfred's sermon (112).","notesPages":[279],"id":"glossary-entry-crows","letter":"C"},{"term":"Crows-nest","definition":"High lookout platform on a ship's mast; used by the Nine and Lanternjaw for their Council of War (142, 143, 145); location from which Lanternjaw returns Inneall's morning signal (152); Inneall later recognizes that Invisible Alfred had eavesdropped there (149).","notesPages":[279],"id":"glossary-entry-crows-nest","letter":"C"},{"term":"Crumpled","definition":"Crushed or collapsed; the Theos crumples up the six \"Almost Perfect Creatures\" (36) and the seventh flawed \"Mankind\" creature, forgetting to deactivate the latter first (37).","notesPages":[279],"id":"glossary-entry-crumpled","letter":"C"},{"term":"Cryptic","definition":"Mysterious or enigmatic; information written on turtles' tongues (75).","notesPages":[279],"id":"glossary-entry-cryptic","letter":"C"},{"term":"Crypts","definition":"Underground chambers or vaults; giant crypts built by Whales from marble on the Ocean Bottom (136).","notesPages":[279],"id":"glossary-entry-crypts","letter":"C"},{"term":"Crystal ball","definition":"Divination tool used by Lutin the Pythoness in her sideshow tent (86).","notesPages":[279],"id":"glossary-entry-crystal-ball","letter":"C"},{"term":"Crystalized","definition":"Formed into crystals; the limestone sold to the Whales becomes totally crystalized variegated marble (136).","notesPages":[279],"id":"glossary-entry-crystalized","letter":"C"},{"term":"Cubs of the Kangaroo","definition":"Hypothetical offspring or junior members of the Kangaroo organization; question raised whether they are exempt from potential obliteration (83).","notesPages":[279],"id":"glossary-entry-cubs-of-the-kangaroo","letter":"C"},{"term":"Culebra y Columba, Felix","definition":"Designated human father-and-guardian of Lutin the Pythoness (70-1); his name means \"Happy Snake and Dove,\" reflecting his wise and guileless nature derived from Matthew's Gospel (71); a naturalist in love with all creatures (71); previously declared guardian of the dove Yonah (71); shares a condominium with Satrap and Livius (71); discusses the purpose of life and contest (72-4).","notesPages":[279],"id":"glossary-entry-culebra-y-columba-felix","letter":"C"},{"term":"Cultural indicators","definition":"Trends or symbols reflecting the values of a society; Honor is cited as a leading one for the Floating World during that summer (117).","notesPages":[279],"id":"glossary-entry-cultural-indicators","letter":"C"},{"term":"Culture (Human)","definition":"Defined by Britannica as behavior peculiar to mankind, including language, ideas, beliefs, customs, codes, institutions, tools, works of art, etc. (39).","notesPages":[280],"id":"glossary-entry-culture-human","letter":"C"},{"term":"Cunning cut","definition":"The precise shaping of stones allowing the Unfallen Ones' bridge to be key- locked together without mortar (15).","notesPages":[280],"id":"glossary-entry-cunning-cut","letter":"C"},{"term":"Curry comb","definition":"Grooming tool used by Dubu the Bear instead of water; considered too good for horses but just right for bears (63).","notesPages":[280],"id":"glossary-entry-curry-comb","letter":"C"},{"term":"Curtness","definition":"Sharpness or abruptness in speech; characteristic of Inneall's metallic voice when impatient (156).","notesPages":[280],"id":"glossary-entry-curtness","letter":"C"},{"term":"Dame Elephant","definition":"Title used by a Dolophonoi-Assassin when addressing Riesin, the Mother Elephant, threateningly (89).","notesPages":[280],"id":"glossary-entry-dame-elephant","letter":"D"},{"term":"Damnable","definition":"Adjective describing the mixtures of human, animal, and machine represented by the Knives-Dolophonoi-Assassins (87).","notesPages":[280],"id":"glossary-entry-damnable","letter":"D"},{"term":"Damned","definition":"Used to describe the souls howling on the Flying Dutchman (97); also describes the Devil-Fish addressed by Invisible Alfred (108); adjective for the ghost-ship legend generated by the invisible Annabella Saint Ledger (121).","notesPages":[280],"id":"glossary-entry-damned","letter":"D"},{"term":"Dance(d)","definition":"Describes the movement of the murderous Dolophonoi knife after killing Axel and Lord Randal (148); people and 'people' danced at Heart's Desire Cove (58).","notesPages":[280],"id":"glossary-entry-dance-d","letter":"D"},{"term":"Dancing","definition":"Includes square dancing and round dancing, arts abandoned by humans but reinvented by Computers (33); also the movement of the Dolophonoi knife (148).","notesPages":[280],"id":"glossary-entry-dancing","letter":"D"},{"term":"Danger","definition":"Associated with computers making predictions come true (1); potential danger of AMHs running amok (27) or being haunted (28); minority of mega-persons who could be a danger to the world (82); the Dolophonoi acknowledge their job is not free from danger (88, 89).","notesPages":[280,281],"id":"glossary-entry-danger","letter":"D"},{"term":"Dangerous","definition":"Computers taking up Astrology (1); venomous serpents (3); turbulent waves in the floating world (81).","notesPages":[281],"id":"glossary-entry-dangerous","letter":"D"},{"term":"Dangled","definition":"Refers to the trestles used by the Royal Kids to paint the ship's hull (104).","notesPages":[281],"id":"glossary-entry-dangled","letter":"D"},{"term":"Dangling","definition":"Describes the reappearance of the Dolophonoi knife just before it kills Henryetta (149).","notesPages":[281],"id":"glossary-entry-dangling","letter":"D"},{"term":"Dark","definition":"The time when lightning ignites the gas in Ape Caverns (45, 68) and Second Eden (45); the time when the Eleven try to enter Ape Caverns (67); time when Invisible Paint is best applied (97, 104); time of Axel's message and descent into sleep (65); time when Henryetta needs the knife (135); depth of the ocean after sunset (139); 'tide of color' associated with common people (123); adjective for unfathomed caves (131).","notesPages":[281],"id":"glossary-entry-dark","letter":"D"},{"term":"Darkness","definition":"Brought by invisible persons (125).","notesPages":[281],"id":"glossary-entry-darkness","letter":"D"},{"term":"Darnay, Charles","definition":"Character from Dickens' A Tale of Two Cities, noted for his resemblance to Sydney Carton. Serpent's Egg prints his name as \"Darney\" (156).","notesPages":[281],"id":"glossary-entry-darnay-charles","letter":"D"},{"term":"Dateline (International)","definition":"Geographical line near which the novel places Kure Island and its Gallows Guesthouse, claiming the latest official cockcrow there (118).","notesPages":[281],"id":"glossary-entry-dateline-international","letter":"D"},{"term":"Daughter","definition":"Annabella Saint Ledger, daughter of Satrap (48, 49); Inneall adopted as daughter by Satrap (49) and granddaughter by Alpha (52); Gajah, daughter of Riesin (57, 84, 90, 91); Lutin, adopted 'daughter' of Shadrack Saleh (84-5) and Felix Culebra y Columba (73).","notesPages":[281],"id":"glossary-entry-daughter","letter":"D"},{"term":"David (King)","definition":"King of Israel, believed by Axel Grindstone to be sleeping, undead but alive, in Abraham's Bosom (11).","notesPages":[281],"id":"glossary-entry-david-king","letter":"D"},{"term":"Dawn","definition":"Ghosts go to sleep at dawn (29); gas sighs and extinguishes at dawn in Second Eden (45); False Dawn precedes True Dawn (76, 106); ghost dawn precedes false dawn (151).","notesPages":[281],"id":"glossary-entry-dawn","letter":"D"},{"term":"Day-dreamers","definition":"Birds are notoriously deep day-dreamers (95).","notesPages":[281],"id":"glossary-entry-day-dreamers","letter":"D"},{"term":"Daydream","definition":"During which bi-location can occur in humans and birds (95).","notesPages":[282],"id":"glossary-entry-daydream","letter":"D"},{"term":"Daydreaming","definition":"By a man who bi-located from Manila to San Francisco (95).","notesPages":[282],"id":"glossary-entry-daydreaming","letter":"D"},{"term":"Daylight","definition":"Time when Alfred maps the heavens (110); time when Dubu is present at Persimmon Manor, initially minimizing the effect of hauntings (125).","notesPages":[282],"id":"glossary-entry-daylight","letter":"D"},{"term":"Dazzle","definition":"Associated with the wrestling match between Carcajou and Luas (87).","notesPages":[282],"id":"glossary-entry-dazzle","letter":"D"},{"term":"Dead","definition":"Axel Grindstone (10, 52); his mother (10); Neanderthals and Cro- Magnons (40); Annabella Saint Ledger (daughter) (49); Dolophonoi- Assassins (100); Gregor McGregor (91); Axel the Ape (148, 161, 166); Lord Randal (148, 161, 166); Quentillius Quern the Fifth (139, 145); Henryetta (149, 161, 166); the nine dead hearties accompanying Donatus O'Reily (157); Donatus O'Reily (157); Hieronymous Zchold (158); the ten persons condemned by Alfred (112); carry-over guests at Persimmon Manor (116); Gajah (91, 94); the Royal Kids anticipated being dead (119).","notesPages":[282],"id":"glossary-entry-dead","letter":"D"},{"term":"Dead bodies","definition":"Specifically, several dead bodies of Dolophonoi examined, revealing traces of human faces under Gargoyle heads (41).","notesPages":[282],"id":"glossary-entry-dead-bodies","letter":"D"},{"term":"Dead Gajah","definition":"The unborn 'Wonder of the World' Elephant after being killed by Gregor McGregor's shot (94).","notesPages":[282],"id":"glossary-entry-dead-gajah","letter":"D"},{"term":"Dead men","definition":"Specifically, the nine companions killed by Donatus O'Reily (156, 157).","notesPages":[282],"id":"glossary-entry-dead-men","letter":"D"},{"term":"Deadly","definition":"Weapons sought by the Dolophonoi-Assassins (89).","notesPages":[282],"id":"glossary-entry-deadly","letter":"D"},{"term":"Deadness","definition":"Resumed by the nine companions on the gallows deck (157).","notesPages":[282],"id":"glossary-entry-deadness","letter":"D"},{"term":"Deal","definition":"Sweet reason should prevail in every deal (39); Satrap's business deal with the Whales for limestone (106).","notesPages":[282],"id":"glossary-entry-deal","letter":"D"},{"term":"Death","definition":"Predicted for Axel Grindstone (10); of Axel's mother (10); Unfallen People immune to natural death (12); results of sentiment (7); caused by lightning (12, 21); of Axel, Lord Randal, Henryetta (84, 148-9); associated with Serpent's Eggs (50); of the 'parents' of experiments (85); of Gregor McGregor (91); of Quentillius Quern (139); of Donatus O'Reily (118, 157) and his companions (157); of Hieronymous Zchold (158); of Tom Dooley (124); of ten persons named by Alfred (112); hour of death for old dogs (128); second death (35).","notesPages":[282,283],"id":"glossary-entry-death","letter":"D"},{"term":"Death Combat","definition":"Mortal struggle, one form of 'Contest' seemingly required by Man (72).","notesPages":[283],"id":"glossary-entry-death-combat","letter":"D"},{"term":"Death Journey","definition":"The final passage, for which Donatus O'Reily is entitled to take nine dead friends as companions (157).","notesPages":[283],"id":"glossary-entry-death-journey","letter":"D"},{"term":"Death Threats","definition":"Perceived dangers hanging over the Royal Kids (113).","notesPages":[283],"id":"glossary-entry-death-threats","letter":"D"},{"term":"Deceive","definition":"Popugai's companion Carcajou acquired elegance in speech so as to deceive the elect (64).","notesPages":[283],"id":"glossary-entry-deceive","letter":"D"},{"term":"Deceived","definition":"The eyes of the beholders were deceived by the pyrotechnic-like wrestling match (87).","notesPages":[283],"id":"glossary-entry-deceived","letter":"D"},{"term":"Deceiver","definition":"Man described as saying \"I am a handsome man, But I'm a gay deceiver\" (35).","notesPages":[283],"id":"glossary-entry-deceiver","letter":"D"},{"term":"Deep Ocean Denizens","definition":"Metamorphic creatures, supposedly the seven richest men in the world, who meet two miles deep in the Atlantic (135).","notesPages":[283],"id":"glossary-entry-deep-ocean-denizens","letter":"D"},{"term":"Deep Sleep","definition":"A profound state of unconsciousness; cast upon the twelve sons of the first generation (18); the \"Holy Sleep\" cast upon occupants of Ape Caverns (67, 68, 70, 147); the specific sleep Axel enters for 72 hours (65, 142, 143); Ocean Sleep is an inoculation against it (142); sleep-walking Dolophonoi vulnerable to it (143).","notesPages":[283],"id":"glossary-entry-deep-sleep","letter":"D"},{"term":"Defects","definition":"Persimmon wood has many built-in defects (125).","notesPages":[283],"id":"glossary-entry-defects","letter":"D"},{"term":"Defence","definition":"Popugai and Carcajou difficult to defend against in lacrosse (65); there seems to be no defence against the Dolophonoi, who are compared to smoke and invisibility (83).","notesPages":[283],"id":"glossary-entry-defence","letter":"D"},{"term":"Definition","definition":"Wotto-metal is, by definition, unburnable (97).","notesPages":[283],"id":"glossary-entry-definition","letter":"D"},{"term":"Degenerates","definition":"Man degenerates without 'Contest' (72).","notesPages":[283],"id":"glossary-entry-degenerates","letter":"D"},{"term":"Degreed","definition":"Schimp was degreed unusually early (63).","notesPages":[283],"id":"glossary-entry-degreed","letter":"D"},{"term":"Dejection","definition":"State, along with shock and sorrow, that can erode Oceanic Metastasis (150).","notesPages":[284],"id":"glossary-entry-dejection","letter":"D"},{"term":"Delight","definition":"Expressed by sister Clotho upon seeing Inneall and the baby pythons (160); Lutin's is the most delightful sickness imaginable (134); Inneall squeaks with secret delight (144).","notesPages":[284],"id":"glossary-entry-delight","letter":"D"},{"term":"Delighted","definition":"The eleven other contemporaries delighted by Gajah's telepathic concepts (57).","notesPages":[284],"id":"glossary-entry-delighted","letter":"D"},{"term":"Delightful","definition":"Henryetta described as quite delightful (61); Lutin's sickness (62, 134).","notesPages":[284],"id":"glossary-entry-delightful","letter":"D"},{"term":"Delirium","definition":"Experienced by Axel Grindstone upon seeing the Unfallen faces (16); dreams of Inneall's ghosts are like segments of delirium (29).","notesPages":[284],"id":"glossary-entry-delirium","letter":"D"},{"term":"Delta Virginis","definition":"A star in the constellation Virgo, seemingly shifted position to form the hypnotic Kangaroo image (77).","notesPages":[284],"id":"glossary-entry-delta-virginis","letter":"D"},{"term":"Demand","definition":"Henryetta demands the steam calliope, and Inneall demands the Invisible Paint drums for the ship (97).","notesPages":[284],"id":"glossary-entry-demand","letter":"D"},{"term":"Demanded","definition":"Inneall demands Lutin reveal who the Kangaroo will kill (62).","notesPages":[284],"id":"glossary-entry-demanded","letter":"D"},{"term":"Demands","definition":"Inneall and Henryetta make sharp demands of Satrap (96).","notesPages":[284],"id":"glossary-entry-demands","letter":"D"},{"term":"Demeaning","definition":"Donatus O'Reily considers being hanged on the same gallows as a Priest of the Old Religion to be demeaning (122).","notesPages":[284],"id":"glossary-entry-demeaning","letter":"D"},{"term":"Demonic","definition":"One of the types of voices heard by young Axel Grindstone (10).","notesPages":[284],"id":"glossary-entry-demonic","letter":"D"},{"term":"Denizens (Deep Ocean)","definition":"See Deep Ocean Denizens.","notesPages":[284],"id":"glossary-entry-denizens-deep-ocean","letter":"D"},{"term":"Denouncing","definition":"Part of the Prophesying-and-Denouncing business practiced by Invisible Alfred (108).","notesPages":[284],"id":"glossary-entry-denouncing","letter":"D"},{"term":"Depraved","definition":"Refers to the origin of the human race (35).","notesPages":[285],"id":"glossary-entry-depraved","letter":"D"},{"term":"Depth","definition":"Of the Ocean (108, 133, 135, 139); of intelligence (60); of Marino's thought, which some criticize as lacking depth (60).","notesPages":[284],"id":"glossary-entry-depth","letter":"D"},{"term":"Depth-Creatures","definition":"Inhabitants of the deep ocean who possess lights (139).","notesPages":[285],"id":"glossary-entry-depth-creatures","letter":"D"},{"term":"Depths","definition":"Of the Ocean (135, 136, 139, 158); of human underminds (70).","notesPages":[285],"id":"glossary-entry-depths","letter":"D"},{"term":"Derived","definition":"Computer standards derived from an earlier age (8); Felix Culebra y Columba's nature derived from the Gospel of Matthew (71).","notesPages":[285],"id":"glossary-entry-derived","letter":"D"},{"term":"Descended","definition":"Lacrosse is said in the novel's invented history to descend from Irish hurley (65); into the depths with Satrap (135); the four fish-faced men descended toward Ocean Bottom (159).","notesPages":[285],"id":"glossary-entry-descended","letter":"D"},{"term":"Descent","definition":"Of the house and island to Ocean Bottom (159).","notesPages":[285],"id":"glossary-entry-descent","letter":"D"},{"term":"Designated","definition":"Father figure for Inneall (52); father-and-guardian for Lutin (71, 115); prey for Assassins (85); Captain of the pirate crew (119).","notesPages":[285],"id":"glossary-entry-designated","letter":"D"},{"term":"Designed","definition":"The Three designed to be intelligent off the scale (7); Dolophonoi-Assassins designed more for killing than style (82).","notesPages":[285],"id":"glossary-entry-designed","letter":"D"},{"term":"Desire","definition":"Of humans to make entities in their own image (26); Heart's Desire Cove (55, 56, 57, 58, 59, 86, 89, 109, 119, 151, 152, 153).","notesPages":[285],"id":"glossary-entry-desire","letter":"D"},{"term":"Desired","definition":"Modifications effected by computers (27).","notesPages":[285],"id":"glossary-entry-desired","letter":"D"},{"term":"Destination","definition":"Absolute free choice of destination offered on the paradoxical airliner (41); part of the consensus eschatology of Intelligent Computers (41); the final end or aim (40).","notesPages":[285],"id":"glossary-entry-destination","letter":"D"},{"term":"Destination Town","definition":"Metaphorical place indicated by a sign tipped awry, symbolizing Man's lost way (34).","notesPages":[285],"id":"glossary-entry-destination-town","letter":"D"},{"term":"Destinations","definition":"Implicitly varied despite being on one airliner (41).","notesPages":[285],"id":"glossary-entry-destinations","letter":"D"},{"term":"Destroyed","definition":"Validity of experiment might be destroyed by emotional involvement (7); targets destroyed by Imperial Heads/flaming arrows (83).","notesPages":[285],"id":"glossary-entry-destroyed","letter":"D"},{"term":"Destruction","definition":"Of the second death (35); possible result of betrayal (142); potential total destruction faced by the Nine (123).","notesPages":[285],"id":"glossary-entry-destruction","letter":"D"},{"term":"Destructively","definition":"AMH Computers may draw power destructively from the ambient to make predictions come true (30).","notesPages":[286],"id":"glossary-entry-destructively","letter":"D"},{"term":"Detached","definition":"Axel is detached from the company of the Nine for a while (123).","notesPages":[286],"id":"glossary-entry-detached","letter":"D"},{"term":"Detail","definition":"extradigitalism implemented by Inneall (25); intricate detail of AMH circuitry (25); extravagant detail in Ape and Structo Lanes (9); odd details taught by Unfallen People (12); obscure detail of early legends (14); forgetting a single detail (121).","notesPages":[286],"id":"glossary-entry-detail","letter":"D"},{"term":"Detailed","definition":"Drawings happening rarely in prowls (8); highly detailed nature of 'The Life Affair' (74); complexity of languages and concepts traced back (37).","notesPages":[286],"id":"glossary-entry-detailed","letter":"D"},{"term":"Details","definition":"Odd details taught by Unfallen (12); brilliant details in 'The Life Affair' (74); discussed in Council of War (142).","notesPages":[286],"id":"glossary-entry-details","letter":"D"},{"term":"Determine","definition":"Coin flip determines surname order (55).","notesPages":[286],"id":"glossary-entry-determine","letter":"D"},{"term":"Determined","definition":"Inneall is determined her ocean shall cover the world (147).","notesPages":[286],"id":"glossary-entry-determined","letter":"D"},{"term":"Devil","definition":"Fallen angels have Carcajou as representative (64); Carcajou's supposed devil form (73,87), before his true human form is disclosed (88,102); Dolophonoi have roots in hell (87); source of Mephistopheles' name (35).","notesPages":[286],"id":"glossary-entry-devil","letter":"D"},{"term":"Devil-Animal","definition":"Creature (specifically, a wolverene) that inhabited Carcajou, now cast out (102).","notesPages":[286],"id":"glossary-entry-devil-animal","letter":"D"},{"term":"Devil-Fish","definition":"Creatures into which Luas transformed the eleven wolverenes (103); subsequently silenced by Invisible Alfred (107, 108).","notesPages":[286],"id":"glossary-entry-devil-fish","letter":"D"},{"term":"Devilish","definition":"Carcajou described as the devilish Wolverene (64).","notesPages":[286],"id":"glossary-entry-devilish","letter":"D"},{"term":"Devils","definition":"Inhabit old houses (124); Unfallen People are experts in smithery like devils (15); Carcajou is half devil (64); wolverenes are called devils (102); sea-satans howl like devils (107); Alfred claims power over Devils (108).","notesPages":[286],"id":"glossary-entry-devils","letter":"D"},{"term":"Devoid","definition":"Music in the Lynn-Randal house devoid of melody (8).","notesPages":[286],"id":"glossary-entry-devoid","letter":"D"},{"term":"Devour","definition":"Experimental fish devour nutrient-mud (3); dogs would devour Zchold's body (122); implicitly what cats do (158).","notesPages":[287],"id":"glossary-entry-devour","letter":"D"},{"term":"Devoured","definition":"Zchold does not want his body devoured by dogs (158).","notesPages":[287],"id":"glossary-entry-devoured","letter":"D"},{"term":"Dew-Hour","definition":"Specifically the ocean-dew hour after False Dawn (76).","notesPages":[287],"id":"glossary-entry-dew-hour","letter":"D"},{"term":"\"Dial-a-Picture Arrangements\"","definition":"Devices in the Lynn-Randal house holding thirty thousand changeable pictures (5).","notesPages":[287],"id":"glossary-entry-dial-a-picture-arrangements","letter":"D"},{"term":"Dickens, Charles","definition":"English novelist; Inneall invokes A Tale of Two Cities when she mistakenly thinks Sebastian Lazar proposes to die in Zchold's place (156). Sebastian denies a physical resemblance and explains that he intends to take Zchold's place in the world.","notesPages":[287],"id":"glossary-entry-dickens-charles","letter":"D"},{"term":"Dickensian","definition":"Characteristic of Charles Dickens' work; the appearance and flavor of shops and persons in Ape Alley (46).","notesPages":[287],"id":"glossary-entry-dickensian","letter":"D"},{"term":"Dictates","definition":"AMHs changed roles according to the dictates of whim (26).","notesPages":[287],"id":"glossary-entry-dictates","letter":"D"},{"term":"Disassociation Attitude","definition":"The stance of total disbelief in Mankind, deemed necessary by Ananthropoi Computers to sever ties with humanity's cyclic sinking (38).","notesPages":[287],"id":"glossary-entry-disassociation-attitude","letter":"D"},{"term":"Disband","definition":"Demanded of the Twelve-Group by a Dolophonos (87).","notesPages":[287],"id":"glossary-entry-disband","letter":"D"},{"term":"Disbelief","definition":"Total disbelief in Mankind advocated by Ananthropoi Computers (38); Carcajou asks the Ocean in disbelief about Zchold (150).","notesPages":[287],"id":"glossary-entry-disbelief","letter":"D"},{"term":"Discern","definition":"Needed to predict the worst outcomes from experiments (82); Satrap unable to discern negotiation possibility with Inneall (47).","notesPages":[287],"id":"glossary-entry-discern","letter":"D"},{"term":"Discovered","definition":"Doors discovered by The Three (9); Red Raiders discovered to be real (63); talent for pyrokinesis discovered by Henryetta (96); error discovered in Rose-of-Sharon's record (117); murder mystery discovered by Dubu (157).","notesPages":[287],"id":"glossary-entry-discovered","letter":"D"},{"term":"Discoverer","definition":"The brave discoverer who comes onto the invisible ship (120).","notesPages":[287],"id":"glossary-entry-discoverer","letter":"D"},{"term":"Discovery","definition":"Excitement of discovery among the fishes in the new ocean (138).","notesPages":[287],"id":"glossary-entry-discovery","letter":"D"},{"term":"Discredited","definition":"Invisible Alfred becomes completely discredited after failed speeches (114); the discredited Prophet (114).","notesPages":[288],"id":"glossary-entry-discredited","letter":"D"},{"term":"Disemboweled","definition":"Performed on Hieronymous Zchold before his stoning (158).","notesPages":[288],"id":"glossary-entry-disemboweled","letter":"D"},{"term":"Disguise","definition":"Worn by Dolophonoi on hands, feet, or face (86).","notesPages":[288],"id":"glossary-entry-disguise","letter":"D"},{"term":"Disguises","definition":"The \"flab-flesh\" constituting Axel the Ape's gargoyle features (42); forms manifested by Carcajou (89).","notesPages":[288],"id":"glossary-entry-disguises","letter":"D"},{"term":"Dish","definition":"Improved by a small amount of common sense (27).","notesPages":[288],"id":"glossary-entry-dish","letter":"D"},{"term":"Dishonest","definition":"Words never used by the Unfallen Ones (15).","notesPages":[288],"id":"glossary-entry-dishonest","letter":"D"},{"term":"Dishonesties","definition":"When Humans, then Machines, fell into dishonesties in their narrations, their record-keeping portion was taken away (163).","notesPages":[288],"id":"glossary-entry-dishonesties","letter":"D"},{"term":"Dishonorably","definition":"Possibility that Donatus O'Reily might try to back out of his hanging (124).","notesPages":[288],"id":"glossary-entry-dishonorably","letter":"D"},{"term":"Disintegration","definition":"Traced back to integration when studying Mankind's past (37).","notesPages":[288],"id":"glossary-entry-disintegration","letter":"D"},{"term":"Dismantled","definition":"Fate predicted for the Dolophonos by Lutin (86); state Inneall fears for herself (143).","notesPages":[288],"id":"glossary-entry-dismantled","letter":"D"},{"term":"Dispensary","definition":"Run according to Henryetta's directive on the Annabella Saint Ledger (100).","notesPages":[288],"id":"glossary-entry-dispensary","letter":"D"},{"term":"Dispersal","definition":"True dissertation of the origin and first dispersal of Axel's Apes (22) and AMH Computers (33).","notesPages":[288],"id":"glossary-entry-dispersal","letter":"D"},{"term":"Disposition","definition":"Felix Culebra y Columba's happy disposition gave him his first name (71); the Sea-Cat has a more pleasant disposition than the Nightmare Monster (138); total silence would kill one of Inneall's disposition (164).","notesPages":[288],"id":"glossary-entry-disposition","letter":"D"},{"term":"Dispositions","definition":"Offended by the howling devil-fish (107).","notesPages":[288],"id":"glossary-entry-dispositions","letter":"D"},{"term":"Disputed","definition":"The facts about the Kangaroo's enrollment of the world are somewhat disputed (80).","notesPages":[288],"id":"glossary-entry-disputed","letter":"D"},{"term":"Disputes","definition":"Seen by Popugai from a lofty viewpoint (64).","notesPages":[289],"id":"glossary-entry-disputes","letter":"D"},{"term":"Disregarded","definition":"Principles of law and justice disregarded in a Kangaroo court (79).","notesPages":[289],"id":"glossary-entry-disregarded","letter":"D"},{"term":"Dissertation","definition":"Provided on the origin/dispersal of Axel's Apes (22), AMH Computers (33), and the Human Species (42); on the Fundamental Nature of Computers (24); brought to an impossible place regarding Mankind (38).","notesPages":[289],"id":"glossary-entry-dissertation","letter":"D"},{"term":"Distance","definition":"Alpha watches over Axel from a near distance (20); Marino travels distance in the ocean (56); fire set by Henryetta from a distance (96); noises diminish into the distance (103); short distance walked to the gallows (157); short distance sailed to Tom Dooley's Island (152).","notesPages":[289],"id":"glossary-entry-distance","letter":"D"},{"term":"Distances","definition":"Axel's Apes smell ore deposits to distances of 200 km (46).","notesPages":[289],"id":"glossary-entry-distances","letter":"D"},{"term":"Distinct","definition":"Humans always considered a distinct species (41).","notesPages":[289],"id":"glossary-entry-distinct","letter":"D"},{"term":"Distinctiveness","definition":"Possessed by Tom Dooley's Island even after sinking (159).","notesPages":[289],"id":"glossary-entry-distinctiveness","letter":"D"},{"term":"Distinguish","definition":"Computers do not distinguish between prediction and instruction (1).","notesPages":[289],"id":"glossary-entry-distinguish","letter":"D"},{"term":"Distinguished","definition":"Livius Secundus is a distinguished Ambulatory Computer (70); distinguished- looking animal faces sculpted by sea- lice (138).","notesPages":[289],"id":"glossary-entry-distinguished","letter":"D"},{"term":"Distraction","definition":"The ocean adventure will be a pleasant distraction for Lutin's sickness (134).","notesPages":[289],"id":"glossary-entry-distraction","letter":"D"},{"term":"Disturbance","definition":"Created by the Eleven's circus to attract Assassins (85); made by eleven wolverenes outside the clubroom (101).","notesPages":[289],"id":"glossary-entry-disturbance","letter":"D"},{"term":"Disturbing","definition":"The sounds of the calliope recognized as disturbing by the Assassins (85).","notesPages":[289],"id":"glossary-entry-disturbing","letter":"D"},{"term":"Ditches","definition":"The red bloodshot marks in an Archangel's eyes are imagined as wide red ditches (17).","notesPages":[289],"id":"glossary-entry-ditches","letter":"D"},{"term":"Diver","definition":"Satrap Saint Ledger is an ocean diver by hobby (47).","notesPages":[289],"id":"glossary-entry-diver","letter":"D"},{"term":"Divergent","definition":"Certain high-headed and divergent excellence had to be curtailed (81).","notesPages":[290],"id":"glossary-entry-divergent","letter":"D"},{"term":"Diverted","definition":"The sun's power locally diverted by certain Ambulatory Computers (like Inneall) (59).","notesPages":[290],"id":"glossary-entry-diverted","letter":"D"},{"term":"Divest","definition":"Members divest themselves of species identity upon entering the Kangaroo (83).","notesPages":[290],"id":"glossary-entry-divest","letter":"D"},{"term":"Dividing walls","definition":"Barriers separating nations, lost when the unmoored nations drifted together (79).","notesPages":[290],"id":"glossary-entry-dividing-walls","letter":"D"},{"term":"Diving","definition":"Real Ocean Diving requires inducing Oceanic Metastasis (133); trick learned by Satrap from Indian Ocean Masters (133); Satrap is an expert (132); Annabella often Satrap's diving ship (132); plenty of diving gear aboard (129).","notesPages":[290],"id":"glossary-entry-diving","letter":"D"},{"term":"Diving gear","definition":"Plenty aboard the Annabella Saint Ledger (129); Satrap decides what gear the Nine should wear (133).","notesPages":[290],"id":"glossary-entry-diving-gear","letter":"D"},{"term":"Dog","definition":"Old and faithful dog talked to Satrap in its dying hour (128); Anastasia Blickworthy suggests Alfred might be a dog (123); Alfred queries if he denied being a dog (124); Invisible Alfred heard like a dog under the banquet table (149).","notesPages":[290],"id":"glossary-entry-dog","letter":"D"},{"term":"Dog Star","definition":"Sirius, whose heliacal rising could be clocked by alignments in the Whale Temple- City (137).","notesPages":[290],"id":"glossary-entry-dog-star","letter":"D"},{"term":"Dogfish (Salt-water)","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[290],"id":"glossary-entry-dogfish-salt-water","letter":"D"},{"term":"Dogfish sharks","definition":"Species of shark present in Inneall's Ocean (138).","notesPages":[290],"id":"glossary-entry-dogfish-sharks","letter":"D"},{"term":"Dogs","definition":"Cannot be kept away from semi-private hangings (152); savage dogs accompany police officials (158); Zchold does not want his body devoured by dogs (122, 158); specifically excluded from receiving bodies by quit-claim releases, which fail to mention cats (158); howl and cringe from fish-faced men (159); Old Dogs song reference (121).","notesPages":[290],"id":"glossary-entry-dogs","letter":"D"},{"term":"Dolophonos Delphicus","definition":"Author of the verse epigraph for Chapter Six (54).","notesPages":[291],"id":"glossary-entry-dolophonos-delphicus","letter":"D"},{"term":"Dolophonos / Dolophonoi / Dolos","definition":"Beings serving the Kangaroo as assassins or exterminators (82-83); also called Knives or Pruning Hooks (83); term can refer to the specialized knives they wield (100, 135, 148); potentially leucotomized humans, irascible computers, or aberrant animals (82); wear Gargoyle heads (41) which apparently grow onto them (41); hunt and kill Serpent's Eggs (50, 84); cool, stylish, elegant top-dogs (50); assigned to the Four Experiments (84); stalk the Nine (127); three found unconscious in Cenaculum (147); one killed by Quentillius (139); a Dolophonoi knife, wielded invisibly by Alfred, kills Axel and Lord Randal (148-150).","notesPages":[290,291],"id":"glossary-entry-dolophonos-dolophonoi-dolos","letter":"D"},{"term":"Dolphins","definition":"Serve as middlemen in Satrap's limestone deal with the Whales (106); seldom reach these depths, but occasionally learn Oceanic Metastasis from other creatures and descend (139).","notesPages":[291],"id":"glossary-entry-dolphins","letter":"D"},{"term":"Dolphins' Underwater Theater","definition":"Located at Atlantic Showhouse, provides excellent source material for Structo Lane Dramas (76).","notesPages":[291],"id":"glossary-entry-dolphins-underwater-theater","letter":"D"},{"term":"Domdaniel (Castle)","definition":"Legendary underwater castle invoked in a quoted fragment among the novel's oceanic allusions (131).","notesPages":[291],"id":"glossary-entry-domdaniel-castle","letter":"D"},{"term":"Donatus O'Reily","definition":"A member of the Natural Nobility who committed a hangable misdemeanor (trying to save a Serpent's-Egg person) (118); must be hanged by friends at cockcrow on the Third Morning of Summerset (118); procures a late-crowning Drake Passage Cock (118); explains the presence of nine dead companions (killed by him to accompany his death journey) to his 'seconds' (157); hanged efficiently (157).","notesPages":[291],"id":"glossary-entry-donatus-oreily","letter":"D"},{"term":"Donegal (Royal House of)","definition":"Lineage from which Donatus O'Reily claims descent as a Prince of the Blood (157).","notesPages":[291],"id":"glossary-entry-donegal-royal-house-of","letter":"D"},{"term":"Door","definition":"Back door of Lynn-Randal house (5, 9); front door of Whale Tau- Temple (137); door to hidden room in Persimmon Manor (114, 126); brass door in limestone wall leading to Cenaculum (144, 147).","notesPages":[291],"id":"glossary-entry-door","letter":"D"},{"term":"Doors","definition":"Discovered by The Three into Structo Lane and Ape Lane (9); of Second Eden (13); back door of history (79).","notesPages":[291],"id":"glossary-entry-doors","letter":"D"},{"term":"Dorantes-Saleh Couple","definition":"Sponsors of the experiment involving Lutin, Dubu, and Schimp (73).","notesPages":[291],"id":"glossary-entry-dorantes-saleh-couple","letter":"D"},{"term":"Dorantes-Saleh Experiment","definition":"One of the four experiments merged in the final days; its members are Lutin (python), Dubu (bear), and Schimp (chimpanzee) (55); Shadrack Saleh is one of its 'parents' (84).","notesPages":[291],"id":"glossary-entry-dorantes-saleh-experiment","letter":"D"},{"term":"Double scanner","definition":"Device set up by Satrap Saint Ledger in the condominium clubroom, showing both Riesin's trek and the road to the Elephant Graveyard (93).","notesPages":[292],"id":"glossary-entry-double-scanner","letter":"D"},{"term":"Double-talk","definition":"Previously used by machines against humans (31).","notesPages":[292],"id":"glossary-entry-double-talk","letter":"D"},{"term":"Doubts","definition":"Lord Randal's mother has doubts about the Floating World (1); Satrap has only doubtful applications from scriptures regarding the sleeping Apes (70); the surviving trio of Inneall, Schimp, and Carcajou have doubts about reaching the surface (150).","notesPages":[292],"id":"glossary-entry-doubts","letter":"D"},{"term":"Dove","definition":"Felix Culebra y Columba is guileless as a dove (71); Yonah, a dove of consummate genius, was previously Felix's ward (71).","notesPages":[292],"id":"glossary-entry-dove","letter":"D"},{"term":"Dove (The)","definition":"Second part of Felix Culebra y Columba's symbolic surname (71).","notesPages":[292],"id":"glossary-entry-dove-the","letter":"D"},{"term":"Down","definition":"Ape Alley down there (45); going down into Ape Caverns (44); down into Structo Lane (144); down to Ocean shore (148); down into the Ocean (148, 159); down to the bottom (101, 116, 119, 133); down the middle (129); down on four legs (88); Waif-arama burned down (96); sat down (116, 160); lay down (94); fell down (157); went down (104, 106, 131, 148); running down scientists (152); whittled down (124); set down (162); throw down (90).","notesPages":[292],"id":"glossary-entry-down","letter":"D"},{"term":"Downtown block","definition":"The urban part of Apes' Alley containing shops, studios, clubs, etc. (45).","notesPages":[292],"id":"glossary-entry-downtown-block","letter":"D"},{"term":"Drama (\"Japanese Noh\")","definition":"One source influencing Structo Lane Dramas (76).","notesPages":[292],"id":"glossary-entry-drama-japanese-noh","letter":"D"},{"term":"Dramas","definition":"Discovered by The Three (9); performed in Structo Lane, influenced by various human and non-human sources (76).","notesPages":[292],"id":"glossary-entry-dramas","letter":"D"},{"term":"Dramatic cycle","definition":"The sequence of events involving the queer End-of- Summer Sun, played out quickly (59).","notesPages":[292],"id":"glossary-entry-dramatic-cycle","letter":"D"},{"term":"Draw","definition":"AMHs draw destructively from the ambient (30); Alfred drew power from invisible paint residue (110).","notesPages":[292],"id":"glossary-entry-draw","letter":"D"},{"term":"Drawn","definition":"Cartoon characters (6); badly-drawn cartoons of celestial signs (111); Whales drawn up in a circle (150).","notesPages":[292],"id":"glossary-entry-drawn","letter":"D"},{"term":"Dream","definition":"Inneall's secret dream of a world-covering ocean (130); Lutin's dream of Castles at bottom of the Sea (136); dream state of Oceanic Metastasis (133, 135, 136, 137, 150).","notesPages":[293],"id":"glossary-entry-dream","letter":"D"},{"term":"Dream State (Oceanic Hyper-Active)","definition":"Alternate name for the Pseudo- Dream State of Oceanic Metastasis (135).","notesPages":[293],"id":"glossary-entry-dream-state-oceanic-hyper-active","letter":"D"},{"term":"Dream-State of Oceanic Metastasis","definition":"See Oceanic Metastasis.","notesPages":[293],"id":"glossary-entry-dream-state-of-oceanic-metastasis","letter":"D"},{"term":"Dreamed","definition":"Axel did what many persons have dreamed of doing (making a mark on the sky) (4).","notesPages":[293],"id":"glossary-entry-dreamed","letter":"D"},{"term":"Dreaming","definition":"Inneall dreams with Axel and Lord Randal (28-9); ghosts dream segments of delirium (29); birds are deep day-dreamers (95).","notesPages":[293],"id":"glossary-entry-dreaming","letter":"D"},{"term":"Dreams","definition":"Shared three-way dreams of The Three, sometimes stimulated or bothered by Inneall's ghosts (28-9); Iris tortured by dreams of Lord Randal and Inneall dead (84).","notesPages":[293],"id":"glossary-entry-dreams","letter":"D"},{"term":"Dreamworlds","definition":"States of existence lived in by all inhabitants of the Deep ocean (138).","notesPages":[293],"id":"glossary-entry-dreamworlds","letter":"D"},{"term":"Dregs","definition":"Stirred up by Whales from the ocean bottom (105, 106).","notesPages":[293],"id":"glossary-entry-dregs","letter":"D"},{"term":"Dress (Full)","definition":"Elegant attire worn by theatre-goers to Structo Lane (76).","notesPages":[293],"id":"glossary-entry-dress-full","letter":"D"},{"term":"Drink","definition":"Bilge-water tonic (100); pirates supposed to drink rum (99); fresh water available near stream mouths (119).","notesPages":[293],"id":"glossary-entry-drink","letter":"D"},{"term":"Dripping","definition":"Quality of stonework at Angkor Wat, suggesting recent emergence from water (132).","notesPages":[293],"id":"glossary-entry-dripping","letter":"D"},{"term":"Drippings","definition":"Formations hanging from cave roofs, like swords (45).","notesPages":[293],"id":"glossary-entry-drippings","letter":"D"},{"term":"Drove","definition":"AMHs drove adult Lynn-Randals crazy (5); Levellers drove cranky people underground (69); Riesin drove the Dolophonos away (89).","notesPages":[293],"id":"glossary-entry-drove","letter":"D"},{"term":"Drown","definition":"People in overloaded boats drown outright (159).","notesPages":[293],"id":"glossary-entry-drown","letter":"D"},{"term":"Drowned","definition":"Devil-fish would have drowned in air (103); most people witnessing the stoning were drowned (159).","notesPages":[293],"id":"glossary-entry-drowned","letter":"D"},{"term":"Drowsy","definition":"A leading Axel, possibly Alpha, becomes drowsy before the hour of Holy Sleep (67).","notesPages":[294],"id":"glossary-entry-drowsy","letter":"D"},{"term":"Drum","definition":"Small drum intruded into Riesin's womb for communication with Gajah (56).","notesPages":[294],"id":"glossary-entry-drum","letter":"D"},{"term":"Drumming","definition":"Gajah's signature more in her trumpeting than her drumming (56).","notesPages":[294],"id":"glossary-entry-drumming","letter":"D"},{"term":"Drums","definition":"Seven one-hundred-gallon drums of Invisible Paint (97, 101); one-hundred-gallon paint drum in which Alfred claims to have spent nine thousand years (110,124).","notesPages":[294],"id":"glossary-entry-drums","letter":"D"},{"term":"Drunk","definition":"Condition of the man married thirty years (47); the Unfallen People look drunk to humans (17); mushroom wine drunk in Ape Alley taverns (46); not the state of sleepers in Ape Caverns (67).","notesPages":[294],"id":"glossary-entry-drunk","letter":"D"},{"term":"Drunken","definition":"Riesin walks as if drunken (93); the state of the carry-over guests' wits (153).","notesPages":[294],"id":"glossary-entry-drunken","letter":"D"},{"term":"Eagle-eyed","definition":"Descriptive of Popugai the parrot, who also has the best overview or \"long view\" among the Twelve (64).","notesPages":[294],"id":"glossary-entry-eagle-eyed","letter":"E"},{"term":"East","definition":"The front door of the Whale Tau-Temple faces East (137); location of Kure Island relative to the International Dateline in the novel (118); direction of Inneall's Ocean's growth (55); one of the wings of Persimmon Manor (126).","notesPages":[294],"id":"glossary-entry-east","letter":"E"},{"term":"Eastern Oklahoma","definition":"Geographical location of Inneall's Ocean, said by the Sea Louse to cover about ten thousand square miles and to have been planned for at least thirty years before Inneall was manufactured (166).","notesPages":[294],"id":"glossary-entry-eastern-oklahoma","letter":"E"},{"term":"Eastern Sky","definition":"Location where the \"Prodigy,\" the Kangaroo constellation, appears just before sunrise (76).","notesPages":[294],"id":"glossary-entry-eastern-sky","letter":"E"},{"term":"Eat","definition":"Lord Randal could eat experimental truffles (4); bears eat \"Filchman's Daughter\" raw for insights (75); Devil-Fish threaten to eat the Royal Kids alive or dead (107-8).","notesPages":[295],"id":"glossary-entry-eat","letter":"E"},{"term":"Eavesdropping","definition":"Invisible Alfred accused by Carcajou of doing this invisibly (149).","notesPages":[295],"id":"glossary-entry-eavesdropping","letter":"E"},{"term":"Eccentric","definition":"Describes the majority of Ambulatory Computers and humans residing in Structo Lane (69); Satrap Saint Ledger is human, eccentric, and male (70).","notesPages":[295],"id":"glossary-entry-eccentric","letter":"E"},{"term":"Eckert","definition":"J. Presper Eckert, historical computer pioneer associated with Mauchly and their electronic calculator (25).","notesPages":[295],"id":"glossary-entry-eckert","letter":"E"},{"term":"Eden (First)","definition":"The original paradise of humanity, from which mankind is fallen (12, 17).","notesPages":[295],"id":"glossary-entry-eden-first","letter":"E"},{"term":"Eden (New Eden Hotel)","definition":"The only hotel in Ape Lane, called New Eden Hotel on p.47 and Second Eden Hotel on pp.67,70, where Satrap Saint Ledger maintains a permanent suite (47) connected to Inneall's Ocean via the Allez-Oop locks (47); guests are expelled during the \"Holy Sleep\" (67).","notesPages":[295],"id":"glossary-entry-eden-new-eden-hotel","letter":"E"},{"term":"Eden (Other)","definition":"Axel Grindstone's term for the Second Eden he sought (11).","notesPages":[295],"id":"glossary-entry-eden-other","letter":"E"},{"term":"Eden (Outdoor)","definition":"The somewhat contrived five-acre habitat where The Three were initially raised (9).","notesPages":[295],"id":"glossary-entry-eden-outdoor","letter":"E"},{"term":"Eden (Second)","definition":"The hidden realm of \"The People Who Had Not Fallen\" (11), located by Axel Grindstone in Gamu Gofa, Ethiopia (11, 14); home of the Unfallen Ones (12, 15) and the Axel's Apes (19, 20); features a valley of perfect climate (16) and an underground cenaculum lit nightly by ignited natural gas (45); its Ape population provides the stock for zoos and the Apes' Cavern community (19, 20, 45).","notesPages":[295],"id":"glossary-entry-eden-second","letter":"E"},{"term":"Edge","definition":"Humanity crowded over the edge to their deaths (40); sea-lice have the stylistic edge over humans (165).","notesPages":[295],"id":"glossary-entry-edge","letter":"E"},{"term":"Edible","definition":"Experimental worms weighing over a ton were edible, though with sickening after- effects (3).","notesPages":[295],"id":"glossary-entry-edible","letter":"E"},{"term":"Edition (Special/Trade)","definition":"Publishing formats listed for the book containing the text (publisher’s biographical note).","notesPages":[296],"id":"glossary-entry-edition-special-trade","letter":"E"},{"term":"Effect","definition":"Axel was of great moment and effect (10); events and battles of far effect to happen in Ape Alley (43); the \"dripping\" effect of Angkor Wat's stonework (132); the strange and happy effect of Luas's piano playing (77); the full effect of Invisible Paint only occurs in the dark (104).","notesPages":[296],"id":"glossary-entry-effect","letter":"E"},{"term":"Efficient","definition":"AMH Computers create efficient present-times (71); land and sea armaments thought to be sophisticated and efficient (79).","notesPages":[296],"id":"glossary-entry-efficient","letter":"E"},{"term":"Egg","definition":"The Three believe that only harmless snakes lay eggs (3); this is not zoologically correct, since venomous cobras also lay eggs. Man hatches from a Serpent's Egg in one AMH creation legend (36). The term also names the metaphor for potentially dangerous talent (82) and the mysterious five-ton object that appears beside Lutin after her childbirth (154-156,160-163,166).","notesPages":[296],"id":"glossary-entry-egg","letter":"E"},{"term":"Egg (Big)","definition":"The enormous, artificial, pulsating object found beside Lutin after she gives birth. Lutin initially claims the Egg, but her actual offspring are three live baby pythons (160). Inneall detects electronic gear, a pump, and something alive inside (155-156). Its contents remain secret; the Second Coming passage and the discussion of a motion-generating universe suggest interpretations (155,162,166). Miol-Mor attends it (160).","notesPages":[296],"id":"glossary-entry-egg-big","letter":"E"},{"term":"Egg (Serpent's)","definition":"Metaphor (from Shakespeare's Julius Caesar) for a potential danger that should be destroyed early (1); The Three fear being identified as such (2); a classification adjudged by the Kangaroo, potentially leading to extermination (2, 84); occurs rarely (\"one in a million\") but possibly more often (\"one in a thousand\") in special experiments (2); associated with mega-persons of unruly proclivities (127); subject of Donatus O'Reily's hangable misdemeanor (118); Lutin reinterprets its meaning while claiming the Big Egg as her offspring (154), although her actual offspring are three baby pythons (160).","notesPages":[296],"id":"glossary-entry-egg-serpents","letter":"E"},{"term":"Egg-shell","definition":"In legend, the Theos marked egg-shells, but Man hatched from one marked for Serpent (36).","notesPages":[296],"id":"glossary-entry-egg-shell","letter":"E"},{"term":"Egypt","definition":"Country entered by Gypsy bands led by golden apes after crossing the Ape Bridge (13).","notesPages":[296],"id":"glossary-entry-egypt","letter":"E"},{"term":"Eighth","definition":"The eighth Main Waif-arama building (96).","notesPages":[296],"id":"glossary-entry-eighth","letter":"E"},{"term":"Eighty-eight","definition":"Percentage representing Inneall's composition as wotto metal (48).","notesPages":[297],"id":"glossary-entry-eighty-eight","letter":"E"},{"term":"Eighty-five","definition":"Percentage denoting Lord Randal's perceived degree of humanness (63).","notesPages":[296],"id":"glossary-entry-eighty-five","letter":"E"},{"term":"Eighty-seven","definition":"Percentage of the world's persons whose disappearance (\"removals\") was initiated by the Kangaroo's levellers (81).","notesPages":[297],"id":"glossary-entry-eighty-seven","letter":"E"},{"term":"Elect","definition":"Carcajou, as a devil, acquired elegant speech to deceive even the elect (64); Ruddy Lord Randal elected Captain (122).","notesPages":[297],"id":"glossary-entry-elect","letter":"E"},{"term":"Electric vehicle","definition":"Small conveyance given to Marino the Seal for land travel (56); later, a larger one acquired to carry eleven passengers (56- 7).","notesPages":[297],"id":"glossary-entry-electric-vehicle","letter":"E"},{"term":"Electronic","definition":"Eckert and Mauchly's calculator (25); AMH mechanisms (25); hearing and smelling implants in Dolophonoi (50); gear inside the Big Egg (155).","notesPages":[297],"id":"glossary-entry-electronic","letter":"E"},{"term":"Electronic calculator","definition":"Device developed by Eckert and Mauchly (25).","notesPages":[297],"id":"glossary-entry-electronic-calculator","letter":"E"},{"term":"Electronic gear","definition":"Components found inside the artificial Big Egg that appears beside Lutin (155).","notesPages":[297],"id":"glossary-entry-electronic-gear","letter":"E"},{"term":"Electronic mechanisms","definition":"Computer components, which long remained bulkier than human flesh circuitry (25).","notesPages":[297],"id":"glossary-entry-electronic-mechanisms","letter":"E"},{"term":"Elegance","definition":"Possessed by the Dolophonoi (50); acquired by Carcajou in his speech (64); characteristic of the clubroom at the condominium (72).","notesPages":[297],"id":"glossary-entry-elegance","letter":"E"},{"term":"Elegant","definition":"AMH Computer smoking a cigar (30); Satrap Saint Ledger's manner (implied) (32); Ruddy Lord Randal and Axel becoming elegant (53); the condominium clubroom (72); the theatre-goers of Structo Lane (76).","notesPages":[297],"id":"glossary-entry-elegant","letter":"E"},{"term":"Elements","definition":"Cloying element in house smells (6); element added to waterfalls (3); of truth in legends (37); human elements subtracted from Dolophonoi (50); Experiment elements used to create Dolophonoi (87); common elements in bi-location cases (95); elements held in reserve for \"Enlargement of the World\" (128).","notesPages":[297],"id":"glossary-entry-elements","letter":"E"},{"term":"Elephant","definition":"Gajah is an unborn female Indian Elephant (55, 63); Riesin is the Mother Elephant (57, 65, 86, 89, 90, 91, 94); gestation period mythically ten years for \"Wonder\" elephants (57); Empress Elephants served as mayors in India (92); India Elephants use bi-location to reach the Elephant Graveyard (95, 128).","notesPages":[297,298],"id":"glossary-entry-elephant","letter":"E"},{"term":"Elephant (Empress)","definition":"A type of female elephant known for exceptional qualities (honesty, intelligence, diligence, etc.); said in the novel's fantastic history to have served as mayors in India until slain by Moguls (57,92); Riesin is an Empress Elephant (57, 90, 92, 128).","notesPages":[298],"id":"glossary-entry-elephant-empress","letter":"E"},{"term":"Elephant Graveyard","definition":"Mythical destination for dying elephants (132); specifically, located in Mustang, north of India, reachable via a \"jog in the road\" from midland America; Riesin travels there to bury Gajah and die (93, 95, 128).","notesPages":[298],"id":"glossary-entry-elephant-graveyard","letter":"E"},{"term":"Elephant-gun","definition":"A powerful weapon owned by the fourth Dolophonoi (89); Gregor McGregor is compelled to use it against his will to fatally shoot Gajah and mortally wound Riesin, who dies after reaching the elephant graveyard (90-91,94).","notesPages":[298],"id":"glossary-entry-elephant-gun","letter":"E"},{"term":"Elephant (Indian)","definition":"Asian elephant, the species of Gajah. The novel says gestation is slightly less than twenty months (57); actual elephant gestation is about twenty to twenty-two months.","notesPages":[298],"id":"glossary-entry-elephant-indian","letter":"E"},{"term":"Elephant (Mother)","definition":"Riesin, mother of the unborn Gajah (57, 65, 86, 89, 90, 91, 94).","notesPages":[298],"id":"glossary-entry-elephant-mother","letter":"E"},{"term":"Elephant (Unborn)","definition":"Gajah, member of the Gruenbaum-McGregor Experiment (55, 65); communicates via drum language (56); is a \"Wonder of the World Elephant\" with a ten-year gestation (57); killed by Gregor McGregor (90, 91).","notesPages":[298],"id":"glossary-entry-elephant-unborn","letter":"E"},{"term":"Elephants","definition":"Empress Elephants (57, 92); \"Wonder of the World Elephants\" (57, 63, 90, 91, 94); India Elephants practice bi-location (95, 128); ordinary Elephants do not make better mayors than humans (92). Includes African and Indian species (57).","notesPages":[298],"id":"glossary-entry-elephants","letter":"E"},{"term":"Elephants (African)","definition":"Species with gestation period over twenty months (57).","notesPages":[298],"id":"glossary-entry-elephants-african","letter":"E"},{"term":"Elephants (Empress)","definition":"See Elephant (Empress).","notesPages":[298],"id":"glossary-entry-elephants-empress","letter":"E"},{"term":"Elephants (Indian)","definition":"Species that practices bi-location when dying (95).","notesPages":[298],"id":"glossary-entry-elephants-indian","letter":"E"},{"term":"Elephants' ivory","definition":"Material used for the tabs on Napier's Bones (25).","notesPages":[299],"id":"glossary-entry-elephants-ivory","letter":"E"},{"term":"Elephants (Wonder of the World)","definition":"Elephants of absolute genius appearing periodically (every 500 or 1000 years), born to Empress Elephants after a ten-year gestation; Gajah is one (57, 63, 90, 91, 94).","notesPages":[298],"id":"glossary-entry-elephants-wonder-of-the-world","letter":"E"},{"term":"Eleven","definition":"The group of young experimental contemporaries remaining after Axel enters Deep Sleep (67); includes Lord Randal, Inneall, Marino, Luas, Henryetta, Lutin, Dubu, Schimp, Gajah, Carcajou, Popugai (see individual entries); initially housed in the condominium clubroom (71); witness the wrestling match (87-88); after Gajah's death and Luas's departure, the remaining Nine board the Annabella Saint Ledger and witness Alfred's sermon (103,108); see also Nine.","notesPages":[299],"id":"glossary-entry-eleven","letter":"E"},{"term":"Elite Twelve Contemporaries","definition":"Designation for the group including Carcajou (64).","notesPages":[299],"id":"glossary-entry-elite-twelve-contemporaries","letter":"E"},{"term":"Elitist","definition":"The Kangaroo is described as an elitist Vigilante (80).","notesPages":[299],"id":"glossary-entry-elitist","letter":"E"},{"term":"Elizabethan Theater (English)","definition":"One of the human dramatic sources influencing Structo Lane productions (76).","notesPages":[299],"id":"glossary-entry-elizabethan-theater-english","letter":"E"},{"term":"Elk Graveyards","definition":"Legendary places where elks go to die, mentioned alongside Elephant Graveyards (132).","notesPages":[299],"id":"glossary-entry-elk-graveyards","letter":"E"},{"term":"Ellison, Harlan","definition":"Writer who regards R.A. Lafferty as one of Science Fiction's top 10 writers, according to the publisher’s biographical note.","notesPages":[299],"id":"glossary-entry-ellison-harlan","letter":"E"},{"term":"Elroy's (Sea-Food)","definition":"Name of a princely eating establishment at Heart's Desire Cove (58).","notesPages":[299],"id":"glossary-entry-elroys-sea-food","letter":"E"},{"term":"Elusive","definition":"Describes the Axel's Apes sought for experiments (19).","notesPages":[299],"id":"glossary-entry-elusive","letter":"E"},{"term":"Embarcadero District","definition":"Area in San Francisco where a man found himself after daydreaming and bi-locating from Manila (95).","notesPages":[299],"id":"glossary-entry-embarcadero-district","letter":"E"},{"term":"Embarrassed","definition":"Bears become embarrassed if humans see them playing chess with berries (76); Inneall feels embarrassed by the song \"Inneall's Ocean Hallelulah\" (59); AMH computers are not embarrassed by fleecing humans at gambling (39).","notesPages":[299],"id":"glossary-entry-embarrassed","letter":"E"},{"term":"Embarrassment","definition":"A human weakness not yet fallen into by AMH computers regarding gambling (39); declared impossible for computers to feel, immediately after the narration says Inneall feels it (59).","notesPages":[299],"id":"glossary-entry-embarrassment","letter":"E"},{"term":"Embodied","definition":"Man described as an embodied paradox (35).","notesPages":[299],"id":"glossary-entry-embodied","letter":"E"},{"term":"Emotion","definition":"Shared by The Three (1); supposedly absent from machines according to Inneall, although she admits to fears, terrors, jealousy, and other emotions herself (50-51).","notesPages":[300],"id":"glossary-entry-emotion","letter":"E"},{"term":"Emotional","definition":"Emotional involvement with experimental entities discouraged (7); humans prone to emotional quirks upsetting reason (39).","notesPages":[300],"id":"glossary-entry-emotional","letter":"E"},{"term":"Emotionally","definition":"'Parents' not supposed to get emotionally involved with experimental 'children' (7, 85); humans become emotionally involved in many fields (39).","notesPages":[300],"id":"glossary-entry-emotionally","letter":"E"},{"term":"Emotions","definition":"Inneall possesses them and sometimes lets them override reason (51).","notesPages":[300],"id":"glossary-entry-emotions","letter":"E"},{"term":"Emperor (King-and-Emperor)","definition":"Title of Prester John, ruler of the Unfallen People (12).","notesPages":[300],"id":"glossary-entry-emperor-king-and-emperor","letter":"E"},{"term":"Empire Period","definition":"A hypothesized future era in the history of Ambulatory Computers, speculated upon by Livius Secundus; some historians believed it had already lasted a decade (71).","notesPages":[300],"id":"glossary-entry-empire-period","letter":"E"},{"term":"Empress Elephant(s)","definition":"See Elephant (Empress).","notesPages":[300],"id":"glossary-entry-empress-elephant-s","letter":"E"},{"term":"Empty","definition":"Birdhouses inhabited by spirits (28); AMH Computers lacking special interest, making them susceptible to haunting (28); drums of Invisible Paint (97); mansions of the brain (40); movie theatre during \"Holy Sleep\" (67); cenotaph of Hieronymous Zchold (150).","notesPages":[300],"id":"glossary-entry-empty","letter":"E"},{"term":"Empty birdhouses","definition":"Metaphorical structures that attract spirits and spooks, analogous to 'empty' AMH Computers (28).","notesPages":[300],"id":"glossary-entry-empty-birdhouses","letter":"E"},{"term":"Emulate","definition":"Ambulatory Computers emulate each other, potentially leading to mass ocean- making (28).","notesPages":[300],"id":"glossary-entry-emulate","letter":"E"},{"term":"Enchanted","definition":"Sleep Axel is cast into (84); the ninety-ninth cannon from the Golden Hind (95-6, 101).","notesPages":[300],"id":"glossary-entry-enchanted","letter":"E"},{"term":"Enchanted cannon","definition":"The magical ninety-ninth cannon from the Golden Hind, capable of hitting any target with self-perpetuating shells (101).","notesPages":[300],"id":"glossary-entry-enchanted-cannon","letter":"E"},{"term":"Enchantments","definition":"Putting a donkey head on a man is the most ancient (32).","notesPages":[300],"id":"glossary-entry-enchantments","letter":"E"},{"term":"Encounter","definition":"The Three's unparalleled encounter with music (5); encounter between Satrap, Livius, and Felix (70); Inneall's depressing encounter with the Fates (114); encounters with shock and sorrow can erode Oceanic Metastasis (150).","notesPages":[301],"id":"glossary-entry-encounter","letter":"E"},{"term":"Encounters","definition":"Eroded Oceanic Metastasis (150).","notesPages":[301],"id":"glossary-entry-encounters","letter":"E"},{"term":"Encouragement","definition":"Henryetta alleges that the Dorantes-Saleh Couple encouraged Lutin's promiscuity; Lutin calls this scandal-mongering (73).","notesPages":[301],"id":"glossary-entry-encouragement","letter":"E"},{"term":"Encouraging","definition":"Describes God's message \"Fear not, little flock...\" (36).","notesPages":[301],"id":"glossary-entry-encouraging","letter":"E"},{"term":"Encyclopedic","definition":"Describes Axel Grindstone's reading (12).","notesPages":[301],"id":"glossary-entry-encyclopedic","letter":"E"},{"term":"End","definition":"Of the world (12); of experiments (56, 87); of the Ocean or World (93, 94); of Satrap's life/days (100, 162); of the rope (157); of the week (54); of summer (54, 58, 62, 65, 75, 119, 140, 141, 146, 151); of the descent (159); of the final blast (144); final end as part of eschatology (40, 41).","notesPages":[301],"id":"glossary-entry-end","letter":"E"},{"term":"End of Summer","definition":"The final period of August, marked by talking animals, prodigies, the merging of Experiments, and culminating in the Three Days of Summerset (54, 58, 59, 62, 75, 140, 141, 146, 151, 157, 161, 166).","notesPages":[301],"id":"glossary-entry-end-of-summer","letter":"E"},{"term":"End-of-Summer-Days","definition":"Period leading up to the conclusion of the experiments (56).","notesPages":[301],"id":"glossary-entry-end-of-summer-days","letter":"E"},{"term":"End-of-the-World Battle","definition":"Another name for the Battle of Armageddon (44).","notesPages":[301],"id":"glossary-entry-end-of-the-world-battle","letter":"E"},{"term":"Ending","definition":"Inneall's story lacks a real ending because she refuses to die (166); Inneall's ending within three days predicted (143).","notesPages":[301],"id":"glossary-entry-ending","letter":"E"},{"term":"Endless ages","definition":"Vast period of time that has yearned for the Prophet Invisible Alfred (107).","notesPages":[301],"id":"glossary-entry-endless-ages","letter":"E"},{"term":"Endless ocean","definition":"Inneall's dream involves an endless ocean going around the world (130-131).","notesPages":[301],"id":"glossary-entry-endless-ocean","letter":"E"},{"term":"Enemies","definition":"Haunts can be enemies of mankind, computerdom, and everything (28); finding meeting places not easily espied by enemies (162); the ship must hide from enemies (104); the paint conceals well from enemies (107).","notesPages":[301],"id":"glossary-entry-enemies","letter":"E"},{"term":"Enemy","definition":"The Enemy is wide awake (poem epigraph) (130); the Kangaroo is the Supreme Head of your enemy (145).","notesPages":[302],"id":"glossary-entry-enemy","letter":"E"},{"term":"Engine (Analytical)","definition":"Babbage's computing machine (25).","notesPages":[302],"id":"glossary-entry-engine-analytical","letter":"E"},{"term":"Engineer (Hydraulic)","definition":"One of Satrap Saint Ledger's hobbies, alongside ocean diving (47).","notesPages":[302],"id":"glossary-entry-engineer-hydraulic","letter":"E"},{"term":"Engines (Donkey)","definition":"Power source for the Annabella Saint Ledger (104); exemplifies asinine machine names (31).","notesPages":[302],"id":"glossary-entry-engines-donkey","letter":"E"},{"term":"England","definition":"Country associated with King Arthur (11), stonemasters (13), and the pirate Hosea Lanternjaw (98).","notesPages":[302],"id":"glossary-entry-england","letter":"E"},{"term":"English","definition":"Axel Grindstone's ancestry (10); Confessions of an English Opium-Eater (132); English Elizabethan Theater (76).","notesPages":[302],"id":"glossary-entry-english","letter":"E"},{"term":"English Elizabethan Theater","definition":"Source influencing Structo Lane Dramas (76).","notesPages":[302],"id":"glossary-entry-english-elizabethan-theater","letter":"E"},{"term":"Enigma","definition":"Lutin the Pythoness described as a pleasant enigma (62).","notesPages":[302],"id":"glossary-entry-enigma","letter":"E"},{"term":"Enjoy","definition":"Whales enjoy diving and sounding (106); AMH Computers enjoy astrology (30); Lutin enjoying her sickness (154); enjoying knowing everything (74); enjoy the final battle (102).","notesPages":[302],"id":"glossary-entry-enjoy","letter":"E"},{"term":"Enjoyed","definition":"The traditional holy blaze (68); fellowship of battle (102); never enjoyed anything so much (141).","notesPages":[302],"id":"glossary-entry-enjoyed","letter":"E"},{"term":"\"Enlargement of the World\"","definition":"A hypothesized critical time, possibly underway, involving the emergence of new talents and powers (112, 113); associated with elements held in reserve (128); Satrap believes in it (127-8).","notesPages":[302],"id":"glossary-entry-enlargement-of-the-world","letter":"E"},{"term":"Enniscorthy Chronicle","definition":"Publication quoted questioning the planning ability and sanity of \"This clown, this Joker\" (107).","notesPages":[302],"id":"glossary-entry-enniscorthy-chronicle","letter":"E"},{"term":"Enrolled","definition":"The Kangaroo had enrolled the whole world (80).","notesPages":[302],"id":"glossary-entry-enrolled","letter":"E"},{"term":"Entertainment","definition":"Places of entertainment in Ape Alley (45); entertainment center at Heart's Desire Cove (57).","notesPages":[303],"id":"glossary-entry-entertainment","letter":"E"},{"term":"Entities","definition":"The three young entities (The Three) (5); experimental entities (7, 37); contrivances and entities made in human image (26); sorry entities (36); intelligent entities (AMHs) (29, 31, 162).","notesPages":[303],"id":"glossary-entry-entities","letter":"E"},{"term":"Entombed","definition":"Refers to Axel, Lord Randal, and Henryetta in their cenotaphs (148).","notesPages":[303],"id":"glossary-entry-entombed","letter":"E"},{"term":"Entrails","definition":"Used potentially for fortune-telling (Baxter's Buzzards) (30); examined by Lutin from birds (86); given to dogs after Zchold's disembowelment (158).","notesPages":[303],"id":"glossary-entry-entrails","letter":"E"},{"term":"Entry","definition":"First-stage entry into Oceanic Metastasis (134).","notesPages":[303],"id":"glossary-entry-entry","letter":"E"},{"term":"Environment","definition":"Cannibalized by AMHs to create props (24, 27); plundered by certain AMHs (59).","notesPages":[303],"id":"glossary-entry-environment","letter":"E"},{"term":"Environments","definition":"Some cannot survive AMH cannibalization (27).","notesPages":[303],"id":"glossary-entry-environments","letter":"E"},{"term":"Epilog","definition":"Provided by a Sea Louse (166).","notesPages":[303],"id":"glossary-entry-epilog","letter":"E"},{"term":"Epistles","definition":"Schimp invokes Saint Paul's tent-making livelihood while writing epistles as a model for combining his bait shop with intellectual work (162).","notesPages":[303],"id":"glossary-entry-epistles","letter":"E"},{"term":"Equality","definition":"Slogan used by female AMHs demanding representation (\"There can be no freedom until there is equality\") (69).","notesPages":[303],"id":"glossary-entry-equality","letter":"E"},{"term":"Equator","definition":"Winterset Day occurs on August 31 south of the Equator (118).","notesPages":[303],"id":"glossary-entry-equator","letter":"E"},{"term":"Equinoxes (Precession of the)","definition":"Astronomical phenomenon causing human astrology to become inaccurate over centuries (30).","notesPages":[303],"id":"glossary-entry-equinoxes-precession-of-the","letter":"E"},{"term":"Equipment","definition":"More men and equipment brought by newcomers to Second Eden (18, 19); not needed by Satrap for diving (132, 135).","notesPages":[303],"id":"glossary-entry-equipment","letter":"E"},{"term":"Erected","definition":"Temple of Angkor Wat (132).","notesPages":[303],"id":"glossary-entry-erected","letter":"E"},{"term":"Eritrea","definition":"Country on the Horn of Africa, location of Assab, one end of the original Ape Bridge (13).","notesPages":[303],"id":"glossary-entry-eritrea","letter":"E"},{"term":"Eroded","definition":"Oceanic Metastasis can be eroded by shock and sorrow (150).","notesPages":[304],"id":"glossary-entry-eroded","letter":"E"},{"term":"Error","definition":"Possible estimation error regarding Neanderthal/Cro-Magnon attainments (40); error in Rose-of-Sharon Montdrago's record classifying her as a \"Serpent's Egg\" (117).","notesPages":[304],"id":"glossary-entry-error","letter":"E"},{"term":"Erudite","definition":"Schimp the chimpanzee (63); R.A. Lafferty (publisher’s biographical note).","notesPages":[304],"id":"glossary-entry-erudite","letter":"E"},{"term":"Escape","definition":"Chance given by Riesin to the Dolophonos (89); possibility from \"Serpent's Egg\" fate (117); souls escaping from nostrils (157).","notesPages":[304],"id":"glossary-entry-escape","letter":"E"},{"term":"Escaped","definition":"Axel's Apes who escaped capture and founded Ape Alley (21); Rose-of-Sharon Montdrago recently escaped classification and execution as a Serpent's Egg (117).","notesPages":[304],"id":"glossary-entry-escaped","letter":"E"},{"term":"Eschatology","definition":"Theology concerning final events (death, judgment, destiny); human deficiency in sound eschatology noted (40); Intelligent Computers possess a consensus eschatology (41).","notesPages":[304],"id":"glossary-entry-eschatology","letter":"E"},{"term":"Espied","definition":"Meeting places not easily espied by enemies (162).","notesPages":[304],"id":"glossary-entry-espied","letter":"E"},{"term":"Essence","definition":"Essence of perfection in Second Eden's climate (16).","notesPages":[304],"id":"glossary-entry-essence","letter":"E"},{"term":"Essences","definition":"Finding hidden essences of characters via abstracting/psychologing (7); souls and essences of victims torn out by Devil-Fish (107).","notesPages":[304],"id":"glossary-entry-essences","letter":"E"},{"term":"Estimation error","definition":"Possible discrepancy in assessing the intellectual attainments of Neanderthals and Cro-Magnons compared to modern humans (40).","notesPages":[304],"id":"glossary-entry-estimation-error","letter":"E"},{"term":"Eternal present","definition":"The state in which Ambulatory Computers live, lacking historical sense or ability to create pasts or futures (71).","notesPages":[304],"id":"glossary-entry-eternal-present","letter":"E"},{"term":"Eternally good","definition":"Inscription on Lord Randal's cenotaph (149).","notesPages":[304],"id":"glossary-entry-eternally-good","letter":"E"},{"term":"Eternally noble","definition":"Inscription on Lord Randal's cenotaph (149).","notesPages":[304],"id":"glossary-entry-eternally-noble","letter":"E"},{"term":"Ethical","definition":"People termed \"the ethicals\" are exceptions to the public desire for assassins to succeed (50); Luas and Lutin too ethical to reveal the Acorn's location (74).","notesPages":[304],"id":"glossary-entry-ethical","letter":"E"},{"term":"Ethicals","definition":"The only group (besides victims) who did not want assassins to succeed (50).","notesPages":[304],"id":"glossary-entry-ethicals","letter":"E"},{"term":"Ethics","definition":"Livius Secundus says he might withhold ultimate answers from greed, but not from ethics (74-75).","notesPages":[305],"id":"glossary-entry-ethics","letter":"E"},{"term":"Ethiopia","definition":"Country where Axel Grindstone located Second Eden (11, 13, 14); Prime Minister originated from Gamu Gofa province (15).","notesPages":[305],"id":"glossary-entry-ethiopia","letter":"E"},{"term":"Ethnic","definition":"The \"all-people throatiness\" consensus voice arose after recognizing everyone was ethnic (6); Axel Grindstone was non-ethnic (10).","notesPages":[305],"id":"glossary-entry-ethnic","letter":"E"},{"term":"Ethnics","definition":"The world population after \"regular people\" disappeared (11).","notesPages":[305],"id":"glossary-entry-ethnics","letter":"E"},{"term":"Etymologically","definition":"Many words are etymologically dishonest, containing built-in falsifiers (15).","notesPages":[305],"id":"glossary-entry-etymologically","letter":"E"},{"term":"Euphemism","definition":"'Ape' used as a reverse euphemism for the Unfallen People (13); \"Royal Kids\" as a euphemism for \"Serpent's Egg Kids\" (117).","notesPages":[305],"id":"glossary-entry-euphemism","letter":"E"},{"term":"\"Eurema's Dam\"","definition":"R.A. Lafferty story that won the Hugo Award in 1973 (publisher’s biographical note).","notesPages":[305],"id":"glossary-entry-euremas-dam","letter":"E"},{"term":"Europe","definition":"Continent where Unfallen People supposedly built Cathedrals (13, 17); destination of Gypsies (13); source of stonemasters taught by Unfallens (13); location where Golden Apes predicted fortunes (30).","notesPages":[305],"id":"glossary-entry-europe","letter":"E"},{"term":"Evasive","definition":"Intuitive evasive actions to be taken by the Nine (145).","notesPages":[305],"id":"glossary-entry-evasive","letter":"E"},{"term":"Evening","definition":"Shows held in the evenings (76); evening sky above the ocean (139); evening-blue Ocean (103).","notesPages":[305],"id":"glossary-entry-evening","letter":"E"},{"term":"Evening-blue","definition":"Color of the Ocean into which the Annabella Saint Ledger sailed (103).","notesPages":[305],"id":"glossary-entry-evening-blue","letter":"E"},{"term":"Evening (First)","definition":"The beginning of the First Night of Summerset, when the Eleven tried to enter Ape Caverns (67).","notesPages":[305],"id":"glossary-entry-evening-first","letter":"E"},{"term":"Event (Annual)","definition":"The Official Hanging Day will become an annual event (152).","notesPages":[305],"id":"glossary-entry-event-annual","letter":"E"},{"term":"Events","definition":"Events and battles to happen in Ape Alley (43); final events (eschatology) (40).","notesPages":[305],"id":"glossary-entry-events","letter":"E"},{"term":"Eventuality","definition":"Ship to be fitted for any eventuality (98).","notesPages":[305],"id":"glossary-entry-eventuality","letter":"E"},{"term":"Evil","definition":"Carcajou possesses shocking evil (64); mega mind of Invisible Alfred (149); spirits inhabiting AMHs (28); origin of evil from misuse of free will (35); shrikes (58); Alfred distinguishes good and evil hearers before displaying the zodiac (110-111).","notesPages":[306],"id":"glossary-entry-evil","letter":"E"},{"term":"Evil intelligence","definition":"Possessed by Carcajou the wolverine (55).","notesPages":[306],"id":"glossary-entry-evil-intelligence","letter":"E"},{"term":"Evil mega mind","definition":"Attributed to Invisible Alfred by Schimp (149).","notesPages":[306],"id":"glossary-entry-evil-mega-mind","letter":"E"},{"term":"Evil shrikes","definition":"Birds participating in air dances at Heart's Desire Cove (58).","notesPages":[306],"id":"glossary-entry-evil-shrikes","letter":"E"},{"term":"Evil spirits","definition":"Entities scared away by the steam calliope (97).","notesPages":[306],"id":"glossary-entry-evil-spirits","letter":"E"},{"term":"Exact","definition":"Time lightning strikes (68); place Alfred orders ship put ashore (109).","notesPages":[306],"id":"glossary-entry-exact","letter":"E"},{"term":"Exactly","definition":"How Axel's Apes behave (implied) (3); how Satrap feels (implied) (134); how Lutin's Egg resembles her (155); how Alfred takes advantage (109); the cockcrow that rouses Donatus's nine dead companions; Donatus is already awake (156-157).","notesPages":[306],"id":"glossary-entry-exactly","letter":"E"},{"term":"Examination","definition":"Quick examination showed Lutin had given birth (155).","notesPages":[306],"id":"glossary-entry-examination","letter":"E"},{"term":"Examine","definition":"Dolophonoi bodies examined (41).","notesPages":[306],"id":"glossary-entry-examine","letter":"E"},{"term":"Examining","definition":"Lutin examines bird entrails (86); Inneall examines the Big Egg (155).","notesPages":[306],"id":"glossary-entry-examining","letter":"E"},{"term":"Exasperating","definition":"Dubu's concatenated grin (163); Inneall's grin (162).","notesPages":[306],"id":"glossary-entry-exasperating","letter":"E"},{"term":"Excavating","definition":"Activity of the Whales on the Ocean Bottom (106).","notesPages":[306],"id":"glossary-entry-excavating","letter":"E"},{"term":"Excelled","definition":"AMHs excelled humans (32); Luas excelled Marino in agility (60); Henryetta excelled in everything (61).","notesPages":[306],"id":"glossary-entry-excelled","letter":"E"},{"term":"Excellence","definition":"Still prized and rewarded in the Floating World, but high- headed and divergent excellence curtailed (81).","notesPages":[306],"id":"glossary-entry-excellence","letter":"E"},{"term":"Excellent","definition":"Smiths and stonemasons (Unfallen) (14); things from Dolphins' Theater (76).","notesPages":[306],"id":"glossary-entry-excellent","letter":"E"},{"term":"Exceptional","definition":"The Three classified as exceptional persons or mega persons (5); ability indicated by scanners for Axel's Apes (19).","notesPages":[307],"id":"glossary-entry-exceptional","letter":"E"},{"term":"Exceptionally","definition":"Talented person (mega-person) (82); talented assassins (implied) (50).","notesPages":[307],"id":"glossary-entry-exceptionally","letter":"E"},{"term":"Exchanged","definition":"Oxygen canisters at the ship (139).","notesPages":[307],"id":"glossary-entry-exchanged","letter":"E"},{"term":"\"Excitements Hot and Cold Suite\"","definition":"Title of a sing-a-long song enjoyed at Heart's Desire Cove (60).","notesPages":[307],"id":"glossary-entry-excitements-hot-and-cold-suite","letter":"E"},{"term":"Exciting","definition":"Interpretation of printed word by The Three (7).","notesPages":[307],"id":"glossary-entry-exciting","letter":"E"},{"term":"Executed","definition":"Donatus O'Reily tried to save a \"Serpent's-Egg\" person from being executed (118, 122).","notesPages":[307],"id":"glossary-entry-executed","letter":"E"},{"term":"Execution","definition":"Hour of execution for Hieronymous Zchold (122, 158).","notesPages":[307],"id":"glossary-entry-execution","letter":"E"},{"term":"Executioners","definition":"Gave Zchold's intestines to dogs (158).","notesPages":[307],"id":"glossary-entry-executioners","letter":"E"},{"term":"Executive officer","definition":"Temporary role assigned within the Kangaroo (83).","notesPages":[307],"id":"glossary-entry-executive-officer","letter":"E"},{"term":"Executive Passage","definition":"Secret underground passage leading from the condominium clubroom in Structo Lane to the Cenaculum of the Sleepers in Apes Caverns; used by the Nine to enter the Cenaculum just before midnight (144, 147, 148).","notesPages":[307],"id":"glossary-entry-executive-passage","letter":"E"},{"term":"Exempt","definition":"Question whether Cubs of the Kangaroo are exempt from obliteration (83).","notesPages":[307],"id":"glossary-entry-exempt","letter":"E"},{"term":"Exercise","definition":"The question \"what are humans?\" is an exercise in triviality (38).","notesPages":[307],"id":"glossary-entry-exercise","letter":"E"},{"term":"Existence","definition":"Bored existence of empty AMHs (28); Kangaroo flicked in and out of existence (83).","notesPages":[307],"id":"glossary-entry-existence","letter":"E"},{"term":"Existing","definition":"State of the Nine Royal Kids (119).","notesPages":[307],"id":"glossary-entry-existing","letter":"E"},{"term":"Exuberance","definition":"Characteristic of things seen truly (104).","notesPages":[307],"id":"glossary-entry-exuberance","letter":"E"},{"term":"Exuberant","definition":"Some high-headed blooms were more than exuberant, they were poisonous (81); health of the ten persons condemned by Alfred (112).","notesPages":[308],"id":"glossary-entry-exuberant","letter":"E"},{"term":"Eye","definition":"Single eye opened by Alfred in \"reverse wink\" (133); baleful eye cast by Kangaroo (78); wary eye cocked by old-settler Apes (44); unpenetrating eye (137); common eye (115); snake-eye view (62); unshut eye of whales (131); Spica (printed \"Spico\"), the baleful eye of the Kangaroo constellation (77).","notesPages":[308],"id":"glossary-entry-eye","letter":"E"},{"term":"Eye-brows","definition":"Ironically crooked and arched by Sebastian Lazar (147).","notesPages":[308],"id":"glossary-entry-eye-brows","letter":"E"},{"term":"Eye-lash","definition":"A drop of Quentillius's own blood is on his eyelash as Henryetta addresses him (140).","notesPages":[308],"id":"glossary-entry-eye-lash","letter":"E"},{"term":"Eye-view (Fish-eye)","definition":"Perspective from which the invisible ship is visible below the waterline (120).","notesPages":[308],"id":"glossary-entry-eye-view-fish-eye","letter":"E"},{"term":"Eye-view (Snake-eye)","definition":"Perspective held by Lutin, missing many significations (62).","notesPages":[308],"id":"glossary-entry-eye-view-snake-eye","letter":"E"},{"term":"Eyes","definition":"Blue eyes of Apes (3, 70); weak eyes of Alfred (110); used to see through by Axel Grindstone (12); only visible parts of Alfred, and of God according to Alfred's self-serving claim (109-110); green eyes of Whales (148, 150); shifted eyes of stars forming Kangaroo (77); squinty eyes of mockers (111); hideous staring eyes of Lanternjaw skeleton (121); closed eyes of Alfred (112, 113, 114); closed eyes of sleeping Apes (70).","notesPages":[308],"id":"glossary-entry-eyes","letter":"E"},{"term":"Fat-berry vines","definition":"One type of experimental plant cultivated within the contrived five-acre habitat shared by The Three (3).","notesPages":[309],"id":"glossary-entry-fat-berry-vines","letter":"F"},{"term":"Fates (Three Fates)","definition":"The mythological Greek goddesses of destiny (Clotho, Lachesis, Atropos); encountered by Inneall as three ugly sisters spinning, measuring, and cutting life threads in a horrible little room, first in the Annabella Saint Ledger’s aft hold (114) and later manifesting in Persimmon Manor; Clotho explains that they can be present in innumerable places at once (126); put into a deep sleep by Dubu, during which Inneall reinforces life threads with wotto-metal (127); later seen acting as foster mothers to three baby pythons birthed by Lutin (160).","notesPages":[309],"id":"glossary-entry-fates-three-fates","letter":"F"},{"term":"Father","definition":"Used for Lord Randal’s father (1, 2), Axel Grindstone’s father Ansel (10, 14, 16), Axel the Ape's father Alpha (20, 51), and God the Father (36). Also denotes designated or surrogate paternal figures, such as the computer Livius Secundus for Inneall (70), Felix Culebra y Columba for Lutin (71), and Satrap Saint Ledger for Inneall (52); Alpha also acts as a father figure for the Apes in the Caverns (51). The first generation \"father\" of the twelve sleeping Unfallen sons was the initial \"awake one\" (19).","notesPages":[308],"id":"glossary-entry-father","letter":"F"},{"term":"Father-and-guardian","definition":"A designated protective role; held by Felix Culebra y Columba for both the young pythoness Lutin and, previously, for the genius dove Yonah (70, 71).","notesPages":[309],"id":"glossary-entry-father-and-guardian","letter":"F"},{"term":"Fathers-and-grandfathers","definition":"Collective term used for the three older figures, Satrap Saint Ledger (surrogate grandfather to Inneall), Livius Secundus (designated father to Inneall), and Felix Culebra y Columba (designated father to Lutin), when they take charge of the Eleven Young People of the Experiments in the condominium (71).","notesPages":[309],"id":"glossary-entry-fathers-and-grandfathers","letter":"F"},{"term":"Faustus (Doctor)","definition":"Legendary figure cited as having attained power over the Devil by learning his secret name, \"Mephistopheles\" (35).","notesPages":[309],"id":"glossary-entry-faustus-doctor","letter":"F"},{"term":"Fear","definition":"Experienced intensely by Lord Randal and his associates upon hearing certain conversations (1); notably lacked by the Dolophonoi- Assassins (50) but felt by their hunter Gregor McGregor (85); Lutin claims not to know the word (86); the hunters are fearful as they await the Dolophonoi (89); Satrap questions Lord Randal about being fearful before the ocean dive (133).","notesPages":[309],"id":"glossary-entry-fear","letter":"F"},{"term":"Feed-ins","definition":"Source materials incorporated into creative works; specifically, the diverse inputs for Structo Lane Dramas, drawn from human theatrical traditions as well as non-human sources like the Dolphins' Underwater Theater, Ostrich Struts, and Cooney Birds' Capers (76).","notesPages":[309],"id":"glossary-entry-feed-ins","letter":"F"},{"term":"Feed-trough","definition":"A manger for animal fodder; cited in The Book of Jasher as the humiliatingly inappropriate crib for the newborn King and Creator during the First Coming (155).","notesPages":[309],"id":"glossary-entry-feed-trough","letter":"F"},{"term":"Female","definition":"Inneall, though a machine, insists she is a girl (3) and possesses fourteen fingers (25); ten percent of AMH Computers declare themselves female and demand fifty-seven percent representation (69); includes characters Iris Lynn-Randal, Henryetta, Lutin, Dubu, Gajah, and Riesin.","notesPages":[310],"id":"glossary-entry-female","letter":"F"},{"term":"Feral land","definition":"Artificially created wilderness; the two-hectare (five-acre) contrived area where The Three were raised, containing experimental flora and fauna (3).","notesPages":[310],"id":"glossary-entry-feral-land","letter":"F"},{"term":"Fetters","definition":"The five hundred Axel's Apes captured from Second Eden were taken away in iron fetters, which they first insisted on repairing and improving at their own forges (19, 20).","notesPages":[310],"id":"glossary-entry-fetters","letter":"F"},{"term":"Field Museum","definition":"Real museum in Chicago invoked in the novel's fictional claim about a \"Titan Skeleton,\" described as human and almost titanic in size (44). The claim is not an authenticated museum record.","notesPages":[310],"id":"glossary-entry-field-museum","letter":"F"},{"term":"Filchman's Daughter (Fish)","definition":"A type of fish inhabiting Inneall's Ocean; Dubu claims that eating its raw flesh provides sudden insights, swift leaping thoughts, and absolutely original ideas (75).","notesPages":[310],"id":"glossary-entry-filchmans-daughter-fish","letter":"F"},{"term":"Filchman's Daughter (Yacht)","definition":"One of Satrap Saint Ledger's yachts (besides the Annabella Saint Ledger), used to transport himself, Livius Secundus, and Felix Culebra y Columba to Tom Dooley's Island (115).","notesPages":[310],"id":"glossary-entry-filchmans-daughter-yacht","letter":"F"},{"term":"Filter eyes","definition":"Specialized visual organs possessed by Inneall, enabling her to perceive phenomena others cannot, such as the Kangaroo constellation (the \"Prodigy\") appearing in the sky before sunrise (76), and the fact that the angel Luas's fingers do not actually touch the piano keys when he plays (77).","notesPages":[310],"id":"glossary-entry-filter-eyes","letter":"F"},{"term":"Final-quips-before-death","definition":"A literary convention or trope involving witty last words spoken by someone facing execution; Hieronymous Ignatius Zchold expresses hatred for this form when asked for a quotable quip before his stoning (158).","notesPages":[310],"id":"glossary-entry-final-quips-before-death","letter":"F"},{"term":"Fire","definition":"Henryetta demonstrates a talent for setting fires from a distance using her mentality (96), potentially responsible for recent destructive town fires (146); the \"Holy Fire\" burns in the Apes' Caverns, lit nightly by lightning (67, 68); supernatural fire runs over the limbs of Carcajou and Luas during their wrestling match (87); the Unfallen People may receive \"living fire\" at the last moment (17).","notesPages":[310],"id":"glossary-entry-fire","letter":"F"},{"term":"Fires","definition":"Henryetta suspected of causing horrifying fires in four towns within a hundred-mile radius (146); other pyro-mega-maniacs are active in the area (146); Henryetta claims talent for setting fires \"no matter how total\" (96).","notesPages":[311],"id":"glossary-entry-fires","letter":"F"},{"term":"First Coming","definition":"The initial advent of the \"King and Creator of the Universe,\" described by The Book of Jasher as inherently ridiculous due to the circumstances: birth to road-people in a stable, being wrapped in a cow-blanket, and laid in a grubby feed-trough (155).","notesPages":[311],"id":"glossary-entry-first-coming","letter":"F"},{"term":"First Computer Republic of the Mind","definition":"The foundation reached by Livius Secundus's history of the Ambulatory Computers. He excludes the Empire Period because he considers it still future, while another school says it has already begun (70-71).","notesPages":[311],"id":"glossary-entry-first-computer-republic-of-the-mind","letter":"F"},{"term":"First Eden","definition":"The original paradise associated with Adam, from which humanity fell due to the \"bad use\" of free will, resulting in a \"depraved origin\" and \"corrupt root\" (12, 17, 35).","notesPages":[311],"id":"glossary-entry-first-eden","letter":"F"},{"term":"First Evening of the Last Three Days","definition":"The start of the final seventy- two hour period of Summerset, during which the Eleven found Ape Caverns sealed for the \"Holy Sleep\" (67).","notesPages":[311],"id":"glossary-entry-first-evening-of-the-last-three-days","letter":"F"},{"term":"First Night of Summerset","definition":"The night commencing the last three days of Summerset, beginning when the Eleven found Ape Caverns sealed (67).","notesPages":[311],"id":"glossary-entry-first-night-of-summerset","letter":"F"},{"term":"Fish","definition":"Includes experimental varieties in The Three's habitat (3); the 'Filchman's Daughter' grants insights when eaten raw (75); Satrap Saint Ledger is described metaphorically as an \"Ocean Creature,\" even a \"fish\" (135); the Annabella Saint Ledger is visible to fish below the waterline (\"fish-eye view\") (120); fish provide reports (\"Fish-Report\") to locate the invisible ship (120).","notesPages":[311],"id":"glossary-entry-fish","letter":"F"},{"term":"Fish (Devil-Fish)","definition":"See Devil-Fish.","notesPages":[311],"id":"glossary-entry-fish-devil-fish","letter":"F"},{"term":"Fish-eye view","definition":"The perspective from underwater, used by fish, from which the unpainted lower hull of the otherwise invisible Annabella Saint Ledger can be seen (120).","notesPages":[312],"id":"glossary-entry-fish-eye-view","letter":"F"},{"term":"Fish-faced","definition":"Having facial features resembling a fish; applied to the wrestling beings (88) and to the four mysterious men who emerge from the ocean to retrieve Hieronymous Zchold's body (88, 159).","notesPages":[312],"id":"glossary-entry-fish-faced","letter":"F"},{"term":"Fish (Filchman's Daughter)","definition":"See Filchman's Daughter (Fish).","notesPages":[311],"id":"glossary-entry-fish-filchmans-daughter","letter":"F"},{"term":"Fish (Paddle-Fish)","definition":"See Paddle-Fishes.","notesPages":[311],"id":"glossary-entry-fish-paddle-fish","letter":"F"},{"term":"Fish (Porcupine)","definition":"See Porcupine Fishes.","notesPages":[311],"id":"glossary-entry-fish-porcupine","letter":"F"},{"term":"Fish-Report","definition":"Information or intelligence presumably derived from fish, used as a means to track and locate the invisible Annabella Saint Ledger (120).","notesPages":[312],"id":"glossary-entry-fish-report","letter":"F"},{"term":"Fish (Torpedo)","definition":"See Torpedo Fish.","notesPages":[311],"id":"glossary-entry-fish-torpedo","letter":"F"},{"term":"Fishes","definition":"Pisces the Fishes, a constellation whose conventional mask hides the true sign of two Leviathans (111); the \"Nations of the Fishes\" flock to explore Inneall's new Ocean (138); appear dressed in clown suits or party masquerade (139).","notesPages":[312],"id":"glossary-entry-fishes","letter":"F"},{"term":"Fissure","definition":"One exists in the limestone roof of Apes' Caverns, through which lightning strikes nightly to ignite the gas well, and through which a giant hand later descends (45, 68); another in Second Eden's cenaculum roof allows methane to escape and be ignited nightly by lightning (45).","notesPages":[312],"id":"glossary-entry-fissure","letter":"F"},{"term":"Five acres","definition":"Approximate area (two hectares) of the contrived feral land habitat where The Three were raised (3).","notesPages":[312],"id":"glossary-entry-five-acres","letter":"F"},{"term":"Five tons","definition":"Inneall's estimate of the weight of the Big Egg, which appears beside Lutin rather than being established as her offspring (162).","notesPages":[312],"id":"glossary-entry-five-tons","letter":"F"},{"term":"Fixtures (Gas-light)","definition":"Lighting devices crafted by the Axel's Apes from quartz-glass, installed in Ape Alley and fueled by illegally tapped natural gas wells (45).","notesPages":[312],"id":"glossary-entry-fixtures-gas-light","letter":"F"},{"term":"Flab-flesh","definition":"The unique, non-structural tissue making up Axel the Ape's gargoyle face, jaw, splay feet, and functional hump; it gives no hint of the underlying, fully human skeleton and is described as \"real enough\" though appearing artificial (42).","notesPages":[312],"id":"glossary-entry-flab-flesh","letter":"F"},{"term":"Flag-ship","definition":"Inneall declares the Annabella Saint Ledger her flagship after acquiring it (48).","notesPages":[312],"id":"glossary-entry-flag-ship","letter":"F"},{"term":"Flaith","definition":"Gaelic term for a Prince of the Blood; title claimed by Donatus O'Reily from the Royal House of Donegal (157).","notesPages":[313],"id":"glossary-entry-flaith","letter":"F"},{"term":"Flaming Arrow Syndrome","definition":"The fatal condition that consumes the Imperial Heads of the Kangaroo after they fulfill their intense, targeted missions (83).","notesPages":[313],"id":"glossary-entry-flaming-arrow-syndrome","letter":"F"},{"term":"Flaming Arrows","definition":"Metaphor for the Imperial Heads of the Kangaroo, emphasizing their intense focus and self-destructive trajectory (83); also used to describe the twelve young people of the Four Experiments, seen as being launched on problematic paths (56).","notesPages":[313],"id":"glossary-entry-flaming-arrows","letter":"F"},{"term":"Flannagan, Jack","definition":"Proprietor of the 24-hour Piano Bar and Sidewalk Cafe at Oceanside; likely an Ambulatory Miming-Human Computer due to his ceaseless activity and adoption of computer habits; converses with the remaining Three (Inneall, Carcajou, Schimp) during the \"ghost dawn\" of the Third Day of Summerset (151-152).","notesPages":[313],"id":"glossary-entry-flannagan-jack","letter":"F"},{"term":"Floating World","definition":"The contemporary global condition characterized by unmoored, borderless nations, free trade, travel, and communication, operating under an almost-invisible government (the Kangaroo); initially a Japanese phrase for the Bohemian/Arty world; criticized as dangerously vulnerable (1,79-82,141). The scientists' explicit instability warning concerns Inneall's Ocean (143).","notesPages":[313],"id":"glossary-entry-floating-world","letter":"F"},{"term":"Floor (Ocean)","definition":"See Bottom (Ocean).","notesPages":[313],"id":"glossary-entry-floor-ocean","letter":"F"},{"term":"Folk legend","definition":"One describes the seven richest men as metamorphic Deep Ocean Denizens meeting annually underwater (135).","notesPages":[313],"id":"glossary-entry-folk-legend","letter":"F"},{"term":"Folk memory","definition":"Includes faint memories of celestial trumpets welcoming Man (34) and the instinct to build bonfires for warmth and community (58).","notesPages":[313],"id":"glossary-entry-folk-memory","letter":"F"},{"term":"Folks (Unfallen)","definition":"See Unfallen Folks.","notesPages":[313],"id":"glossary-entry-folks-unfallen","letter":"F"},{"term":"Fools (Ship of)","definition":"Allegorical vessel carrying a representative collection of human folly; Inneall questions if the Annabella Saint Ledger represents all Mankind or just Cockeyed Mankind in this capacity (141).","notesPages":[313],"id":"glossary-entry-fools-ship-of","letter":"F"},{"term":"Forbidden","definition":"The Experiment that produced the Dolophonoi used forbidden elements (87); having a Theology of Life is forbidden in the Floating World (141).","notesPages":[313],"id":"glossary-entry-forbidden","letter":"F"},{"term":"Form","definition":"Carcajou is initially thought to have wolverene, man, and devil forms (72-73,87). After the wrestling, his true form is revealed as human; Luas explains that a devil-animal had possessed him (88,102). Also refers to final-quips-before-death as a literary form disliked by Zchold (158).","notesPages":[314],"id":"glossary-entry-form","letter":"F"},{"term":"Fortune cookies (Chinese)","definition":"Compared by Dubu to the undersides of turtles' tongues, which supposedly contain cryptic written information revealing total knowledge when \"read\" (75).","notesPages":[314],"id":"glossary-entry-fortune-cookies-chinese","letter":"F"},{"term":"Foster children","definition":"Children raised by non-biological parents; the three baby pythons found with the Three Fates (160).","notesPages":[314],"id":"glossary-entry-foster-children","letter":"F"},{"term":"Foster mothers","definition":"Non-biological maternal figures; the Three Fates unexpectedly become foster mothers to three baby pythons (160).","notesPages":[314],"id":"glossary-entry-foster-mothers","letter":"F"},{"term":"Fosterlings","definition":"Children raised by non-parental guardians; term used by the 'parents' (sponsors) of the Experiments for their charges (84).","notesPages":[314],"id":"glossary-entry-fosterlings","letter":"F"},{"term":"Four Experiments","definition":"The collective term for the Lynn-Randal, Wintergreen-Luna, Dorantes- Saleh, and Gruenbaum-McGregor projects, which were merged near their conclusion; associated with Dolophonoi-Assassin monitoring (55, 56, 60, 61, 84, 104).","notesPages":[314],"id":"glossary-entry-four-experiments","letter":"F"},{"term":"Fourteen fingers","definition":"The unusual number of digits Inneall possesses, adopted as a researched status symbol linked to historical pirates' extradigitalism (25).","notesPages":[314],"id":"glossary-entry-fourteen-fingers","letter":"F"},{"term":"Fourth lobe","definition":"An additional brain lobe unique to bears, according to Dubu; she claims to be currently using her fourth lobe, which will grant access to the total knowledge previously mastered and stored in triplicate in the other three (75).","notesPages":[314],"id":"glossary-entry-fourth-lobe","letter":"F"},{"term":"Fowl","definition":"Experimental varieties in The Three's habitat were fat and could only fly \"thus far and no farther\" (3); eating insightful fowl raw, like fish, yields profound ideas according to Dubu (75).","notesPages":[314],"id":"glossary-entry-fowl","letter":"F"},{"term":"Free choice","definition":"The principle, strongly held by humans in the Floating World, that every individual member of the species possesses absolute freedom of choice, exemplified by the paradoxical airliner analogy (41).","notesPages":[314],"id":"glossary-entry-free-choice","letter":"F"},{"term":"Free will","definition":"The capacity for independent moral choice; cited as the origin of all evil and misery in the human race due to its \"bad use\" (35).","notesPages":[314],"id":"glossary-entry-free-will","letter":"F"},{"term":"Frequencies","definition":"The Kangaroo discovered and operates on narrow, sharp frequencies allegedly unmonitored by the Mind of God, while also knowing the wide frequencies the Mind of God uses (80).","notesPages":[315],"id":"glossary-entry-frequencies","letter":"F"},{"term":"Fridays","definition":"One of the three days (along with Mondays and Wednesdays) when the pirate crew under Inneall's command must live solely on the fish they catch themselves (99).","notesPages":[315],"id":"glossary-entry-fridays","letter":"F"},{"term":"Frock coat","definition":"Worn by Ruddy Lord Randal when acting as circus ring- master (86).","notesPages":[315],"id":"glossary-entry-frock-coat","letter":"F"},{"term":"Fruit","definition":"Present-day computers are the fruit of the seventh technological age (37); the Dolophonoi-Assassins are the fruit of a false and forbidden Experiment (87); anticipating the dire fruit of unfortunate combinations (81).","notesPages":[315],"id":"glossary-entry-fruit","letter":"F"},{"term":"\"Fulfillment of the World\" (The)","definition":"A term, seemingly interchangeable with \"Enlargement of the World\", referring to a current era of significant change involving the emergence of advanced Computer Machines, geniused animals with trans-animal talents, and the readying of \"Second Humanity\"; potentially opposed by various \"enemies\" (93, 113).","notesPages":[315],"id":"glossary-entry-fulfillment-of-the-world-the","letter":"F"},{"term":"Fun strip","definition":"Lively, entertaining area; describes the Sidewalk Cafe Row on Ocean Shore where people enjoyed themselves despite the looming threat (77).","notesPages":[315],"id":"glossary-entry-fun-strip","letter":"F"},{"term":"Fundamental Nature of Computers (The)","definition":"The topic of a dissertation section (24) and a question addressed to an AMH Computer regarding the motivations and characteristics of intelligent machines, particularly their adoption of astrology (29).","notesPages":[315],"id":"glossary-entry-fundamental-nature-of-computers-the","letter":"F"},{"term":"Funny-faced apes","definition":"Term reportedly used by 'common people' to describe the newly arrived Axel's Apes, indicating a perception of strangeness combined with likability (44).","notesPages":[315],"id":"glossary-entry-funny-faced-apes","letter":"F"},{"term":"Funny feet","definition":"Axel the Ape's wide splay feet, described as looking like additions by a costumer but actually made of real \"flab-flesh\" (42).","notesPages":[315],"id":"glossary-entry-funny-feet","letter":"F"},{"term":"Funny humps","definition":"Axel the Ape's functional bull-hump, also appearing artificial but made of \"flab-flesh\" (42).","notesPages":[315],"id":"glossary-entry-funny-humps","letter":"F"},{"term":"Future","definition":"Predicted by Computers using astrology (30); AMH Computers enjoy contemplating it (32); known but not always explainable by Lutin (62, 73); the scienced, reasoned future filling Structo Lane (poem epigraph) (67).","notesPages":[316],"id":"glossary-entry-future","letter":"F"},{"term":"Gajah","definition":"The unborn female Indian Elephant of the Gruenbaum- McGregor Experiment (55, 63); intelligent even before birth, communicates via drum language with Inneall (56); destined to be a \"Wonder of the World Elephant\" with a ten-year gestation (57); participates actively in group activities despite her unborn state (56- 7); considered the best lacrosse player via telepathic direction of her mother, Riesin (65); tragically killed while still in the womb by Gregor McGregor using the Elephant-Gun (90-91); her body is carried by Riesin to the Elephant Graveyard for burial (93-4).","notesPages":[316],"id":"glossary-entry-gajah","letter":"G"},{"term":"Gala","definition":"The arrival of new fish and shelly folks in Inneall's Ocean is a gala time for them, an excitement of discovery (138).","notesPages":[316],"id":"glossary-entry-gala","letter":"G"},{"term":"Galaxy clusters","definition":"Included in the comprehensive scope of \"The Life Affair\" woven by Felix Culebra y Columba (74).","notesPages":[316],"id":"glossary-entry-galaxy-clusters","letter":"G"},{"term":"Galley sheets","definition":"An AMH Computer consults the galley sheets of The Authentic Legends of the Computers and Other Mechanisms (36).","notesPages":[316],"id":"glossary-entry-galley-sheets","letter":"G"},{"term":"Gallon","definition":"Inneall's artificial blood system holds one gallon (49); the drums holding Invisible Paint are one-hundred-gallon size (97, 101, 110).","notesPages":[316],"id":"glossary-entry-gallon","letter":"G"},{"term":"Gallows","definition":"Donatus O'Reily asks if his is ready (157); the nine dead companions walk to the gallows behind Persimmon Manor (157).","notesPages":[316],"id":"glossary-entry-gallows","letter":"G"},{"term":"Gallows Guesthouse (James Mortimer's)","definition":"Location on Kure Island, formerly the Gracious Guesthouse, where some hangable persons of the Natural Nobility go for their execution (118).","notesPages":[316],"id":"glossary-entry-gallows-guesthouse-james-mortimers","letter":"G"},{"term":"Gambling","definition":"Identified by an intelligent computer as the most conspicuous human vulnerability, noting humans love it but are inept at it (38); AMH Computers easily fleece humans at simple gambling (39).","notesPages":[317],"id":"glossary-entry-gambling","letter":"G"},{"term":"Game","definition":"Astrology regarded as a fascinating closed-system prediction- and-analysis game by Computers (29); Man doesn't know if he's playing a game or engaging in mortal combat (72); lacrosse described as a special game (65); the Game of Lacrosse (62).","notesPages":[317],"id":"glossary-entry-game","letter":"G"},{"term":"Game of Lacrosse","definition":"The specific athletic contest taken up by the Twelve Great Contemporaries during the final End-of-Summer Days (62, 65).","notesPages":[317],"id":"glossary-entry-game-of-lacrosse","letter":"G"},{"term":"Gammon Lanternjaw","definition":"Great-great-grandfather of Lanternjaw Lunnigan, a pirate active well into the twentieth century (98).","notesPages":[317],"id":"glossary-entry-gammon-lanternjaw","letter":"G"},{"term":"Gamu Gofa","definition":"Province in Ethiopia where Axel Grindstone located Second Eden (12, 14); source of the present Prime Minister of Ethiopia (15).","notesPages":[317],"id":"glossary-entry-gamu-gofa","letter":"G"},{"term":"Gamu Gofa Province","definition":"See Gamu Gofa.","notesPages":[317],"id":"glossary-entry-gamu-gofa-province","letter":"G"},{"term":"Gandula","definition":"Location passed by Axel Grindstone on his final, happy journey towards Second Eden (14).","notesPages":[317],"id":"glossary-entry-gandula","letter":"G"},{"term":"Gaping","definition":"Refers to the inside of Invisible Alfred's mouth when seen (123).","notesPages":[317],"id":"glossary-entry-gaping","letter":"G"},{"term":"Garberdines","definition":"Type of sturdy clothing; Lanternjaw contrasts the pirates' honest ship garberdines with the \"duds\" provided by the Royal Kids (99).","notesPages":[317],"id":"glossary-entry-garberdines","letter":"G"},{"term":"Gargoyle face(s)","definition":"The distinctive, grotesque facial appearance of the Unfallen People (17), the Axel's Apes (21, 41, 44), and the Yellow Dwarf on the Saint Ledger coat-of-arms (49); Axel the Ape possesses one, composed of \"flab-flesh\" (42).","notesPages":[317],"id":"glossary-entry-gargoyle-face-s","letter":"G"},{"term":"Gargoyle heads","definition":"Head coverings featuring Gargoyle faces, worn by the Dolophonoi- Assassins, which apparently begin to grow onto them (41).","notesPages":[317],"id":"glossary-entry-gargoyle-heads","letter":"G"},{"term":"Gargoyle-Titan look","definition":"Facial characteristic possessed by certain humans, resembling that of the Axel's Apes and ancient Titans (44).","notesPages":[318],"id":"glossary-entry-gargoyle-titan-look","letter":"G"},{"term":"Gargoyles","definition":"Grotesque carved figures found on cathedral parapets, identified as signs left by the Unfallen People builders (13); the Unfallen People themselves are the Gargoyles and possess Gargoyle faces (17).","notesPages":[318],"id":"glossary-entry-gargoyles","letter":"G"},{"term":"Garish","definition":"Describes the blue moods produced by Jackdaw Press prowls (8); the quality of the End-of-Summer Sun and the gegenschein (glowing midnight sky) at Heart's Desire Cove (59); colors that do not betoken healthy blooms (81).","notesPages":[318],"id":"glossary-entry-garish","letter":"G"},{"term":"Garlic","definition":"Compared by an AMH theorist to common sense – repellent in large quantities but improves flavor in small amounts (26).","notesPages":[318],"id":"glossary-entry-garlic","letter":"G"},{"term":"Garment","definition":"The \"seamless garment\" of individual lives and the world woven by Felix Culebra y Columba (74).","notesPages":[318],"id":"glossary-entry-garment","letter":"G"},{"term":"Garnished","definition":"Ocean Catfish garnished with Crayfish Tails (58); the vast empty mansions of the brain are swept and garnished (40).","notesPages":[318],"id":"glossary-entry-garnished","letter":"G"},{"term":"Garpikes","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[318],"id":"glossary-entry-garpikes","letter":"G"},{"term":"Gas","definition":"Natural gas from old wells, tapped illegally by Axel's Apes in the Caverns for illumination and power (45); methane natural-gas in Second Eden's cenaculum provides nightly illumination when ignited by lightning (45); gas jets turned off before nightly lightning strike (68).","notesPages":[318],"id":"glossary-entry-gas","letter":"G"},{"term":"Gas-fired forges","definition":"Smithing hearths fueled by natural gas, used by the Yellow Apes in their smithies (46).","notesPages":[318],"id":"glossary-entry-gas-fired-forges","letter":"G"},{"term":"Gas jets","definition":"Outlets for natural gas; all turned off except the main jet before the nightly lightning strike in Ape Caverns (68).","notesPages":[318],"id":"glossary-entry-gas-jets","letter":"G"},{"term":"Gas-light fixtures","definition":"Lighting devices made by Axel's Apes from quartz- glass and fueled by natural gas (45).","notesPages":[318],"id":"glossary-entry-gas-light-fixtures","letter":"G"},{"term":"Gas-lit","definition":"Illuminated by natural gas; describes the Ape Caverns enclave (9) and implies the atmosphere within (46).","notesPages":[319],"id":"glossary-entry-gas-lit","letter":"G"},{"term":"Gas wells","definition":"Sources of natural gas; old capped wells penetrate Ape Caverns (45); one main jet ignited nightly by lightning (68).","notesPages":[318],"id":"glossary-entry-gas-wells","letter":"G"},{"term":"Gate-guards","definition":"Guards at Ape Caverns include Dolophonoi and Ambulatory Computer Species members during the \"Holy Sleep\" (67).","notesPages":[319],"id":"glossary-entry-gate-guards","letter":"G"},{"term":"Gates","definition":"Screened and hidden gates to Apes' Caverns (68).","notesPages":[319],"id":"glossary-entry-gates","letter":"G"},{"term":"Gathering","definition":"Men gathering to capture Apes (19); wrath gathering in the sea (132); crowd gathering on shore (109); sea-lice gathering on the wall (164).","notesPages":[319],"id":"glossary-entry-gathering","letter":"G"},{"term":"Gavial-crocodile","definition":"Species of Indian crocodile from whose hide a Dolophonos claims his gloves were made (86).","notesPages":[319],"id":"glossary-entry-gavial-crocodile","letter":"G"},{"term":"Gay Deceiver","definition":"Self-description attributed to Man (\"I am a handsome man, But I'm a gay deceiver\") (35).","notesPages":[319],"id":"glossary-entry-gay-deceiver","letter":"G"},{"term":"Gazing","definition":"A Dolophonos-Assassin gazing with a sardonic grin at the Nine (125).","notesPages":[319],"id":"glossary-entry-gazing","letter":"G"},{"term":"Gear","definition":"Electronic gear inside the Big Egg (155); diving gear aboard the Annabella Saint Ledger (129, 132).","notesPages":[319],"id":"glossary-entry-gear","letter":"G"},{"term":"Gear (Diving)","definition":"See Diving gear.","notesPages":[319],"id":"glossary-entry-gear-diving","letter":"G"},{"term":"Gear trains","definition":"Stripping them mentioned metaphorically by a computer theorist alongside slitting throats as necessary actions (39).","notesPages":[319],"id":"glossary-entry-gear-trains","letter":"G"},{"term":"Gegenschein","definition":"Astronomical phenomenon of a faint glow opposite the sun; used to describe the garish glowing midnight sky at Heart's Desire Cove (59).","notesPages":[319],"id":"glossary-entry-gegenschein","letter":"G"},{"term":"Gem","definition":"Bilge-water tonic described ironically as a \"gem\" of Henryetta's making (100) initially misattributed to Inneall by Sebastian, then claimed by Henryetta (100).","notesPages":[319],"id":"glossary-entry-gem","letter":"G"},{"term":"Gemini","definition":"The third constellation of the Zodiac (the Twins); identified by Invisible Alfred as corresponding to the Apostle Thomas, explaining the puzzle of Thomas being called 'the twin' despite being a singleton (111).","notesPages":[319],"id":"glossary-entry-gemini","letter":"G"},{"term":"Gender (Grammatical)","definition":"Inneall's grammatical gender is male, though she insists she is a girl (3).","notesPages":[319],"id":"glossary-entry-gender-grammatical","letter":"G"},{"term":"General","definition":"Talking animals became pretty general (54); general population (2); general location (96); general idea (113).","notesPages":[320],"id":"glossary-entry-general","letter":"G"},{"term":"General idea","definition":"The general idea is that the Royal Kids are phoney (113).","notesPages":[320],"id":"glossary-entry-general-idea","letter":"G"},{"term":"General location","definition":"The same broad area where the Main Waif-arama was situated despite moving between eight buildings (96).","notesPages":[320],"id":"glossary-entry-general-location","letter":"G"},{"term":"General population","definition":"Serpent's Eggs occur only about one in a million of the general population (2).","notesPages":[320],"id":"glossary-entry-general-population","letter":"G"},{"term":"Generate","definition":"The Three generated power from their closeness (1); Computers learn to generate themselves (38); the perfect shape (sphere) will not generate motion (162); Dubu proposes that this egg-shaped universe will generate motion (162).","notesPages":[320],"id":"glossary-entry-generate","letter":"G"},{"term":"Generated","definition":"Power generated by The Three (1); legend generated by the ghost ship (121).","notesPages":[320],"id":"glossary-entry-generated","letter":"G"},{"term":"Generating apparatus","definition":"Reproductive system; easily manufactured and installed for experimental mating between AMHs and humans (32).","notesPages":[320],"id":"glossary-entry-generating-apparatus","letter":"G"},{"term":"Generation","definition":"At least one whale from the second generation of whaledom still alive (11); the twelve sons of the first generation of Unfallen sons (18); a venial and adulterous generation comes hardly to belief (112).","notesPages":[320],"id":"glossary-entry-generation","letter":"G"},{"term":"Genes","definition":"New genes would need experimenting for AMH-human cross- fertilization (32).","notesPages":[320],"id":"glossary-entry-genes","letter":"G"},{"term":"Genius","definition":"Possessed by the dove Yonah (71); the Axel's Apes are laden with great genius (51); Invisible Alfred possesses a stroke of genius (110).","notesPages":[320],"id":"glossary-entry-genius","letter":"G"},{"term":"Geniused animals","definition":"Animals possessing exceptional intelligence and trans-animal talents like speech and abstract thought; part of the \"Fulfillment of the World\" (83, 93).","notesPages":[320],"id":"glossary-entry-geniused-animals","letter":"G"},{"term":"Gentlemen","definition":"Used by Satrap addressing Livius and Carcajou (72); yacht-owning gentlemen (43); Whales described as real gentlemen (107).","notesPages":[320],"id":"glossary-entry-gentlemen","letter":"G"},{"term":"Genuine angel","definition":"Authentic celestial being; Luas is confirmed as such, not phoney, belonging to a different universe (61).","notesPages":[321],"id":"glossary-entry-genuine-angel","letter":"G"},{"term":"Geographical Locations (various)","definition":"Includes places like Ethiopia, Gamu Gofa, Arba Mench, Second Eden, Arabia, Europe, America, India, San Francisco, Manila, Australia, New York City, Paris, Tokyo, Rio de Janeiro, Kure Island, Wollaston Island, Cape Horn, Egypt, Turkey, Los Angeles, Oklahoma, Nebraska, Honduras, Cincinnati, North American Continent, Atlantic Ocean, Land's End, Brittany, San Sabian, Wichita Mountains, etc.","notesPages":[321],"id":"glossary-entry-geographical-locations-various","letter":"G"},{"term":"Geological","definition":"Computers can effect geological modifications (27); Mid- American Ocean existed thrice in geological times (55).","notesPages":[321],"id":"glossary-entry-geological","letter":"G"},{"term":"Geometric forms","definition":"Abstract shapes used in ninety-nine frames of 'prowls' to represent characters subliminally, conveying movement and fragmentation (6).","notesPages":[321],"id":"glossary-entry-geometric-forms","letter":"G"},{"term":"Geometries","definition":"The Three discover their signature geometries (golden pentagon, orange square, lavender-purple triangle) within the 'prowls' (6).","notesPages":[321],"id":"glossary-entry-geometries","letter":"G"},{"term":"George Lynn-Randal","definition":"See Lynn-Randal, George.","notesPages":[321],"id":"glossary-entry-george-lynn-randal","letter":"G"},{"term":"German","definition":"Ancestry of Axel Grindstone (10).","notesPages":[321],"id":"glossary-entry-german","letter":"G"},{"term":"Germanies","definition":"Historical term for German-speaking lands; source of stonemasters taught by Unfallen People (13).","notesPages":[321],"id":"glossary-entry-germanies","letter":"G"},{"term":"Gestation periods","definition":"The novel gives ten years for \"Wonder of the World Elephants,\" over twenty months for African elephants, and under twenty for Indian elephants (57). These are its fictional claims; real elephant gestation is about twenty to twenty-two months.","notesPages":[321],"id":"glossary-entry-gestation-periods","letter":"G"},{"term":"Gesture","definition":"Satrap's usual big gesture in offering Lutin the largest room (154).","notesPages":[321],"id":"glossary-entry-gesture","letter":"G"},{"term":"Ghees","definition":"An Ethiopian language studied by Axel Grindstone (11); understood and potentially spoken by the Unfallen Ones (15).","notesPages":[321],"id":"glossary-entry-ghees","letter":"G"},{"term":"Ghost Dawn","definition":"The hour preceding false dawn (151).","notesPages":[321],"id":"glossary-entry-ghost-dawn","letter":"G"},{"term":"Ghost Ship","definition":"The Flying Dutchman, which has a calliope aboard playing the howling of damned souls (97); the invisible Annabella Saint Ledger will become a similar legend (121).","notesPages":[322],"id":"glossary-entry-ghost-ship","letter":"G"},{"term":"Ghost-Ship","definition":"See Ghost Ship.","notesPages":[322],"id":"glossary-entry-ghost-ship-618c04","letter":"G"},{"term":"Ghostly","definition":"One type of voice heard by young Axel Grindstone (10).","notesPages":[322],"id":"glossary-entry-ghostly","letter":"G"},{"term":"Ghosts","definition":"Inhabit Inneall (28-9), sleeping and dreaming deliriously; can be enemies of mankind, computerdom, everything (28); associated with haunting Persimmon Manor (124-5).","notesPages":[322],"id":"glossary-entry-ghosts","letter":"G"},{"term":"Giant","definition":"Magog the original Unfallen Patriarch confused with a later Giant Magog (12); giant yellow Apes reported (44); the Floating World conceived as a giant boat (82).","notesPages":[322],"id":"glossary-entry-giant","letter":"G"},{"term":"Giant boat","definition":"Metaphor for the Floating World (82).","notesPages":[322],"id":"glossary-entry-giant-boat","letter":"G"},{"term":"Giant crypts","definition":"Huge underground vaults built by Whales (136).","notesPages":[322],"id":"glossary-entry-giant-crypts","letter":"G"},{"term":"Giant hand","definition":"A large, powerful, numenous hand that descends through the fissure in Ape Caverns, smothers the holy fire after the Ape notary has already fallen into the \"Holy Sleep\" (68).","notesPages":[322],"id":"glossary-entry-giant-hand","letter":"G"},{"term":"Giant stones","definition":"Massive stones found in the Whale Graveyard (132); also used by the Whales in their underwater constructions (138).","notesPages":[322],"id":"glossary-entry-giant-stones","letter":"G"},{"term":"Giant tomb-stones","definition":"Immense grave markers, questioning raised by the scale of those in Lyonesse (131).","notesPages":[322],"id":"glossary-entry-giant-tomb-stones","letter":"G"},{"term":"Giant Underwater Cenotaphs","definition":"Massive stone monuments located off San Sabian, possibly part of a Whale Graveyard (132).","notesPages":[322],"id":"glossary-entry-giant-underwater-cenotaphs","letter":"G"},{"term":"Giant Yellow Apes","definition":"Term used in reports of new ape arrivals disappearing into the ground (44).","notesPages":[322],"id":"glossary-entry-giant-yellow-apes","letter":"G"},{"term":"Giantess","definition":"Riesin the Mother Elephant is referred to as such (56, 57).","notesPages":[322],"id":"glossary-entry-giantess","letter":"G"},{"term":"Giantism","definition":"Described as a state of mind possessed by the newly arrived Apes (44).","notesPages":[322],"id":"glossary-entry-giantism","letter":"G"},{"term":"Giantizing","definition":"The newly arrived Apes were in a giantizing state of mind (44).","notesPages":[322],"id":"glossary-entry-giantizing","letter":"G"},{"term":"Giants","definition":"Titans are somewhat bigger than giants (88); possibly built Lyonesse (105); Giants of the Old Testament (Sons of Anak) suggested as builders (106).","notesPages":[323],"id":"glossary-entry-giants","letter":"G"},{"term":"Giants (City of)","definition":"Alternative name for the underwater City of Lyonesse (105).","notesPages":[323],"id":"glossary-entry-giants-city-of","letter":"G"},{"term":"Giants of the Old Testament","definition":"Mentioned as possible builders of Lyonesse (106).","notesPages":[323],"id":"glossary-entry-giants-of-the-old-testament","letter":"G"},{"term":"Gibbet","definition":"Donatus O'Reily asks if his is ready (157).","notesPages":[323],"id":"glossary-entry-gibbet","letter":"G"},{"term":"Gift","definition":"Popugai has a rare gift of memory and understanding (64); the knives taken from dead Dolophonoi are a gift appreciated by the Royal Kids (100); the gift of silence prayed for (108); the gift of patience prayed for (108); near-invisibility is a two-sided gift (110).","notesPages":[323],"id":"glossary-entry-gift","letter":"G"},{"term":"Gifts","definition":"The Axel's Apes are laden with great genius but made more juvenile by their gifts (51).","notesPages":[323],"id":"glossary-entry-gifts","letter":"G"},{"term":"Giggle","definition":"Ghosts in Inneall giggle (29).","notesPages":[323],"id":"glossary-entry-giggle","letter":"G"},{"term":"Giggled","definition":"The transparent odd fellows giggled (155).","notesPages":[323],"id":"glossary-entry-giggled","letter":"G"},{"term":"Giggling","definition":"Sound made by people watching Alfred's cartoon apparitions (111).","notesPages":[323],"id":"glossary-entry-giggling","letter":"G"},{"term":"Gimp-Ghosts","definition":"Type of spirit that can inhabit empty AMH Computers (28).","notesPages":[323],"id":"glossary-entry-gimp-ghosts","letter":"G"},{"term":"Giovane (Machiavelli)","definition":"A name used as an attribution within the novel regarding stable solutions emerging in world affairs despite chaotic planning (78).","notesPages":[323],"id":"glossary-entry-giovane-machiavelli","letter":"G"},{"term":"Giraffes","definition":"Are part of the background \"good noise\" in prowls (6).","notesPages":[323],"id":"glossary-entry-giraffes","letter":"G"},{"term":"Girdle","definition":"The zone and girdle of the heavens (the zodiac) made visible by Alfred (111).","notesPages":[323],"id":"glossary-entry-girdle","letter":"G"},{"term":"\"Glad You're Here (We're)\"","definition":"Welcoming sign posted by the Whales in their underwater Temple-City (136).","notesPages":[323],"id":"glossary-entry-glad-youre-here-were","letter":"G"},{"term":"Glass-domed","definition":"Description of the 'outdoors' habitat behind the Lynn- Randal house (28).","notesPages":[324],"id":"glossary-entry-glass-domed","letter":"G"},{"term":"Glass tube","definition":"Vessel in which Lord Randal was conceived (3).","notesPages":[323],"id":"glossary-entry-glass-tube","letter":"G"},{"term":"Glassy smooth","definition":"Appearance of the Ocean surface before a whale breaks through (110).","notesPages":[324],"id":"glossary-entry-glassy-smooth","letter":"G"},{"term":"Glee","definition":"Axel's Apes chortle with glee at the prospect of battle (18); Whales build with gladness and glee (105); gold and gems and glee associated with Treasured Islands (159).","notesPages":[324],"id":"glossary-entry-glee","letter":"G"},{"term":"Global Village","definition":"Term used for the interconnected world for decades; willful persons decided it should act like one, leading to the Floating World (39, 79); Citizens of the Global Village unlawfully worried (84).","notesPages":[324],"id":"glossary-entry-global-village","letter":"G"},{"term":"Gloomy","definition":"Describes the day long ago when humans lost the ability to talk to animals (51).","notesPages":[324],"id":"glossary-entry-gloomy","letter":"G"},{"term":"Gloriously","definition":"The Ocean Depth appeared gloriously sunlit through Metastastic eyes (136).","notesPages":[324],"id":"glossary-entry-gloriously","letter":"G"},{"term":"Glory","definition":"The glory, jest, and riddle of the world (Man) (34); Invisible Alfred claims all voices rebound to his glory (108).","notesPages":[324],"id":"glossary-entry-glory","letter":"G"},{"term":"\"Glory, Jest, and Riddle of the World\" (The)","definition":"Phrase describing Man (34).","notesPages":[324],"id":"glossary-entry-glory-jest-and-riddle-of-the-world-the","letter":"G"},{"term":"Gloves","definition":"Worn by a Dolophonos, made from the hide of a living gavial- crocodile (86).","notesPages":[324],"id":"glossary-entry-gloves","letter":"G"},{"term":"Glow","definition":"Left by Alpha after encounters (21); surrounding Persimmon Manor (153).","notesPages":[324],"id":"glossary-entry-glow","letter":"G"},{"term":"Glowing","definition":"Unfallen Folks appear like glowing gold (16); the gegenschein is the glowing midnight sky (59).","notesPages":[324],"id":"glossary-entry-glowing","letter":"G"},{"term":"Goal","definition":"Part of eschatology (40, 41); of lacrosse (65); object of the contest Man must have (72).","notesPages":[324],"id":"glossary-entry-goal","letter":"G"},{"term":"Goal-keeper","definition":"Player defending the goal in lacrosse (65).","notesPages":[324],"id":"glossary-entry-goal-keeper","letter":"G"},{"term":"Goal-Player (Nine-Goal Player)","definition":"rating attributed by the novel to Saint Brandon in its invented history of hurley and lacrosse (65).","notesPages":[324],"id":"glossary-entry-goal-player-nine-goal-player","letter":"G"},{"term":"God","definition":"Supreme Being; subject of Axel Grindstone's unorthodox beliefs (11, 12, 17); author of quoted statements about Man (36); source of authority (implied) (17); Mind of God operates on wide frequencies (80); Man's creation in God's image affirmed by the Baltimore Catechism quotation (35); takes Unfallen People via lightning (12); takes 100 Axel's Apes via lightning (21); orders woven into life (74); spoke from Burning Bush/Whirlwind (110); loves mysteries (162); according to the Sea Louse, promised neither Apes nor Whales succession to Man and did not promise Man immunity from succession (166).","notesPages":[325],"id":"glossary-entry-god","letter":"G"},{"term":"God (Mind of)","definition":"The Kangaroo believes it has identified God's wide frequencies and narrow frequencies He seems not to monitor (80).","notesPages":[325],"id":"glossary-entry-god-mind-of","letter":"G"},{"term":"Gods of Olympus","definition":"Deities who overthrew the Titans (106).","notesPages":[325],"id":"glossary-entry-gods-of-olympus","letter":"G"},{"term":"Goggles","definition":"Worn by Lutin and Popugai during the ocean dive (134).","notesPages":[325],"id":"glossary-entry-goggles","letter":"G"},{"term":"Gold","definition":"Axel's Apes mine gold near Ape Alley (46); Gold Somali Shillings minted by Apes (46, 67); nugget ocean gold traded by dolphins for limestone (106); paid by Satrap for kangaroo knuckle-bone (145).","notesPages":[325],"id":"glossary-entry-gold","letter":"G"},{"term":"Gold mines","definition":"Wotto metal mine paid out better than all gold mines (48).","notesPages":[325],"id":"glossary-entry-gold-mines","letter":"G"},{"term":"Gold (Nugget Ocean)","definition":"Form of gold traded by dolphins (106).","notesPages":[325],"id":"glossary-entry-gold-nugget-ocean","letter":"G"},{"term":"Gold Somali Shillings","definition":"High-value ($300) gold replicas of brass Somali shillings, minted by the Axel's Apes (46); three given to each expelled hotel guest (67).","notesPages":[325],"id":"glossary-entry-gold-somali-shillings","letter":"G"},{"term":"Golden","definition":"Describes Apes (3, 13, 20); golden pentagon (Axel's signature geometry) (6); glowing gold of Unfallen Folks (16); golden mist over Whale Town (136); golden pages (146); beautiful golden light pulsating from Big Egg (154).","notesPages":[325],"id":"glossary-entry-golden","letter":"G"},{"term":"Golden Ape","definition":"Singular; Axel the Ape who falls dead (148); Alpha (implied) (20).","notesPages":[325],"id":"glossary-entry-golden-ape","letter":"G"},{"term":"Golden Apes","definition":"Alternative name for the Axel's Apes, due to their color (3, 13, 20); led Gypsy bands out of Africa (13); predicted fortunes in Europe (30); subject to the \"Moment of Awakening\" (142, 143, 166).","notesPages":[325],"id":"glossary-entry-golden-apes","letter":"G"},{"term":"Golden-furred","definition":"Description of the Axel's Apes captured from Second Eden (19).","notesPages":[326],"id":"glossary-entry-golden-furred","letter":"G"},{"term":"Golden Pentagon","definition":"Axel's signature geometric form seen in prowls, having five arms at its five angles (6).","notesPages":[325],"id":"glossary-entry-golden-pentagon","letter":"G"},{"term":"Goldstine","definition":"Herman Goldstine, historical computer pioneer associated with Burks and Von Neumann (25).","notesPages":[326],"id":"glossary-entry-goldstine","letter":"G"},{"term":"Good","definition":"'Good people' (44); good noise (6); good sense (21); good shape (19); good group (87); good shot (90); good plan (84); good way (122); good name (107); good diving gear (132); good brushes (98); good look (36); good reason (38); good thing (88, 113, 116); good King (implied) (35); good women (implied) (35); good fishermen (99); good workers (136); good ideas (38, 75); good advice (128); good health (20); good order (20); God's view of Unfallen faces (17); nature created good (35); Theos makes creatures good (36); world better for awakening (144); Dolophonoi break up group for own good (87); being good (164).","notesPages":[326],"id":"glossary-entry-good","letter":"G"},{"term":"Good Man (A)","definition":"Inscription on the empty cenotaph of Hieronymous Ignatius Zchold (150).","notesPages":[326],"id":"glossary-entry-good-man-a","letter":"G"},{"term":"Good Mayors","definition":"Empress Elephants served as very good mayors (92).","notesPages":[326],"id":"glossary-entry-good-mayors","letter":"G"},{"term":"Good-natured","definition":"Characteristic of Ruddy Lord Randal (123).","notesPages":[326],"id":"glossary-entry-good-natured","letter":"G"},{"term":"Good Noise","definition":"Background sounds like high winds, thunder, screaming alligators, and rutting giraffes considered acceptable even for sedate indoor scenes in 'prowls' (6).","notesPages":[326],"id":"glossary-entry-good-noise","letter":"G"},{"term":"\"Good Women (Legend of)\"","definition":"Title of a work, implicitly by Chaucer, referenced thematically (35).","notesPages":[326],"id":"glossary-entry-good-women-legend-of","letter":"G"},{"term":"Gospel of Matthew","definition":"Source of the quote inspiring Felix Culebra y Columba's name and nature (\"Be you therefore as wise as serpents and as guileless as doves\") (71).","notesPages":[326],"id":"glossary-entry-gospel-of-matthew","letter":"G"},{"term":"Gotten","definition":"Subject matter not gotten to (38); Inneall claims to have gotten imprinting from Apes (51).","notesPages":[326],"id":"glossary-entry-gotten","letter":"G"},{"term":"Governess","definition":"Role taken by the whale Miol-Mor for the Big Egg (160).","notesPages":[327],"id":"glossary-entry-governess","letter":"G"},{"term":"Government","definition":"Floating World ostensibly has no government (79), but possesses an almost- invisible one (the Kangaroo) (80); slogan \"No Government is the Best Government\" (79).","notesPages":[326],"id":"glossary-entry-government","letter":"G"},{"term":"Government (Almost-Invisible)","definition":"See Almost-invisible government.","notesPages":[326],"id":"glossary-entry-government-almost-invisible","letter":"G"},{"term":"Government (Best Government)","definition":"Slogan \"No Government is the Best Government\" cited (79).","notesPages":[327],"id":"glossary-entry-government-best-government","letter":"G"},{"term":"Government (Invisible)","definition":"See Invisible government.","notesPages":[327],"id":"glossary-entry-government-invisible","letter":"G"},{"term":"Gown","definition":"Academic robe worn by Schimp (63).","notesPages":[327],"id":"glossary-entry-gown","letter":"G"},{"term":"Grace","definition":"Possessed by the Unfallen Folks (16).","notesPages":[327],"id":"glossary-entry-grace","letter":"G"},{"term":"Gracious Guesthouse (James Mortimer's)","definition":"Former name of the Gallows Guesthouse on Kure Island (118).","notesPages":[327],"id":"glossary-entry-gracious-guesthouse-james-mortimers","letter":"G"},{"term":"Granddaughter","definition":"Inneall adopted as granddaughter by Alpha (52).","notesPages":[327],"id":"glossary-entry-granddaughter","letter":"G"},{"term":"Grandees (The)","definition":"Sect of Ambulatory Computers known for snootiness, resembled by Henryetta (63).","notesPages":[327],"id":"glossary-entry-grandees-the","letter":"G"},{"term":"Grandfather Alpha","definition":"Title used for the aging patriarch of the Apes' Caverns (51).","notesPages":[327],"id":"glossary-entry-grandfather-alpha","letter":"G"},{"term":"Grandfather (Maternal)","definition":"Otto Wotto, inventor of wotto metal, was Satrap Saint Ledger's maternal grandfather (48).","notesPages":[327],"id":"glossary-entry-grandfather-maternal","letter":"G"},{"term":"Grandfather Satrap","definition":"Title used by Popugai when addressing Satrap Saint Ledger (134); also used by Carcajou (133).","notesPages":[327],"id":"glossary-entry-grandfather-satrap","letter":"G"},{"term":"Grandfather (Surrogate)","definition":"Role adopted by Satrap Saint Ledger towards Inneall (47, 69, 71, 85, 95, 97); Inneall addresses Satrap as \"qualified Grandfather\" (125).","notesPages":[327],"id":"glossary-entry-grandfather-surrogate","letter":"G"},{"term":"Grandfathers","definition":"Satrap Saint Ledger referred to as surrogate grandfather of Inneall (69, 71, 85, 95, 97); Otto Wotto as maternal grandfather of Satrap (48); late Tom Dooley's grandfather built Persimmon Manor (116).","notesPages":[327],"id":"glossary-entry-grandfathers","letter":"G"},{"term":"Granite","definition":"Wichita-Mountain Granite used for shafts and lintels in the Whale Temple-City (137); stone pillars etched by sea-lice (138).","notesPages":[327],"id":"glossary-entry-granite","letter":"G"},{"term":"Grapes","definition":"Axel's Apes stole grapes and bushed themselves on wine-o (poem epigraph) (10); Unfallen Ones perform work for pounds of grapes for morning wine (16).","notesPages":[327],"id":"glossary-entry-grapes","letter":"G"},{"term":"Grapplers (Electronic)","definition":"Devices likely implanted in Dolophonoi to aid climbing (50).","notesPages":[328],"id":"glossary-entry-grapplers-electronic","letter":"G"},{"term":"Grass-and-rock meanders","definition":"Natural-looking pathways on the surface above Ape Alley (43).","notesPages":[328],"id":"glossary-entry-grass-and-rock-meanders","letter":"G"},{"term":"Grass houses","definition":"Simple dwellings contrasted with complex cathedrals to illustrate linguistic devolution (37).","notesPages":[328],"id":"glossary-entry-grass-houses","letter":"G"},{"term":"Grass Huts (Green)","definition":"Dwellings of the Unfallen People in their valley of perfect climate (16).","notesPages":[328],"id":"glossary-entry-grass-huts-green","letter":"G"},{"term":"Grateful","definition":"Dubu grateful for mysteries because she loves solving them (162).","notesPages":[328],"id":"glossary-entry-grateful","letter":"G"},{"term":"Graveyard (Elephant)","definition":"See Elephant Graveyard.","notesPages":[328],"id":"glossary-entry-graveyard-elephant","letter":"G"},{"term":"Graveyard (Whale)","definition":"See Whale Graveyard.","notesPages":[328],"id":"glossary-entry-graveyard-whale","letter":"G"},{"term":"Graveyards (Elk/Elephant)","definition":"Places where animals supposedly go to die (132).","notesPages":[328],"id":"glossary-entry-graveyards-elk-elephant","letter":"G"},{"term":"Gravity","definition":"Anomaly connected with the empty drums of Invisible Paint, making them heavy (97).","notesPages":[328],"id":"glossary-entry-gravity","letter":"G"},{"term":"Gray","definition":"Alpha's yellow hair is turning grizzled gray (51).","notesPages":[328],"id":"glossary-entry-gray","letter":"G"},{"term":"Gray-Head","definition":"Term used by Inneall for Alpha after he adopts her as granddaughter (52).","notesPages":[328],"id":"glossary-entry-gray-head","letter":"G"},{"term":"Great","definition":"Great Contemporaries (65); great number (32); great effect (43); great amount (12); great accuracy (83); great strength (21); great scholars (15); great genius (51, 57); great artists (implied) (138); great difficulty (61); great sickness (129); great sigh (94); great turmoil (106); great whales (131); great hewn stones (132); great circle (148); great attention (implied) (134); great feat (79); great quantity (81); great places (109); great act (62); great moment (10, 123); great difference (implied) (47).","notesPages":[328],"id":"glossary-entry-great","letter":"G"},{"term":"Great Affinities","definition":"Strong connection claimed by an AMH Computer between machines and asses (31).","notesPages":[328],"id":"glossary-entry-great-affinities","letter":"G"},{"term":"Great Clattering Crows","definition":"Exclamation used by Inneall (23).","notesPages":[329],"id":"glossary-entry-great-clattering-crows","letter":"G"},{"term":"Great Mathematicians","definition":"Scholars from Alexandria, Damascus, Tokyo, Heidelberg, Dublin who came to learn from the Unfallen Ones (15).","notesPages":[329],"id":"glossary-entry-great-mathematicians","letter":"G"},{"term":"Great Pirate Legend","definition":"Status achievable by the crew of the Annabella Saint Ledger, exceeding even the Flying Dutchman (120).","notesPages":[329],"id":"glossary-entry-great-pirate-legend","letter":"G"},{"term":"Great Pirates","definition":"Historical figures, noted by Inneall as almost all being extradigitals (25).","notesPages":[329],"id":"glossary-entry-great-pirates","letter":"G"},{"term":"Great Scholars","definition":"Academics, valued by the Unfallen Ones equally with local schoolchildren (15).","notesPages":[329],"id":"glossary-entry-great-scholars","letter":"G"},{"term":"Great Stone Buildings","definition":"Structures Axel Grindstone expected but did not find in Second Eden (16).","notesPages":[329],"id":"glossary-entry-great-stone-buildings","letter":"G"},{"term":"Great Twelve Contemporaries","definition":"Title applied to the merged experimental group when they take up lacrosse (65).","notesPages":[329],"id":"glossary-entry-great-twelve-contemporaries","letter":"G"},{"term":"Great White Sharks","definition":"Species of shark present in Inneall's Ocean (138).","notesPages":[329],"id":"glossary-entry-great-white-sharks","letter":"G"},{"term":"Greater","definition":"The AMH commentator speculates that Neanderthal and Cro-Magnon brains and attainments were slightly greater, then allows that the difference may be imaginary (40); efficiency modernized armaments provide (78); stimulus leads to more connections (32); storage capacity importance overestimated (32).","notesPages":[329],"id":"glossary-entry-greater","letter":"G"},{"term":"Greater scope","definition":"Possessed by AMH intelligence compared to human (26).","notesPages":[329],"id":"glossary-entry-greater-scope","letter":"G"},{"term":"Greater stimulation","definition":"Reason given by an AMH Computer for why mobile computers excel stationary ones (32).","notesPages":[329],"id":"glossary-entry-greater-stimulation","letter":"G"},{"term":"Greatly","definition":"Luas would not be greatly missed in angelic society (61); number of eligible species greatly increased (55).","notesPages":[329],"id":"glossary-entry-greatly","letter":"G"},{"term":"Greek Bas Reliefs","definition":"See Bas reliefs (Greek).","notesPages":[329],"id":"glossary-entry-greek-bas-reliefs","letter":"G"},{"term":"Greek Tragedy (Old)","definition":"Source influencing Structo Lane Dramas (76).","notesPages":[329],"id":"glossary-entry-greek-tragedy-old","letter":"G"},{"term":"Green Country Lane","definition":"See Country Lane (Green).","notesPages":[330],"id":"glossary-entry-green-country-lane","letter":"G"},{"term":"Green Country Valley","definition":"Area roofing the Ape Caverns, featuring seasonal lakes (45).","notesPages":[330],"id":"glossary-entry-green-country-valley","letter":"G"},{"term":"Green growth","definition":"The living green spread of the sea-lice themselves over limestone blocks as they write for the whales (137-138,163).","notesPages":[329],"id":"glossary-entry-green-growth","letter":"G"},{"term":"Green leaves","definition":"Foliage growing on the reinforced vines used by The Three (4).","notesPages":[330],"id":"glossary-entry-green-leaves","letter":"G"},{"term":"Green lights","definition":"Sharp beams shone from the Whales' one-foot-diameter eyes on the Ocean Bottom (148, 150).","notesPages":[330],"id":"glossary-entry-green-lights","letter":"G"},{"term":"Green of Swarming, Ocean-Floor Etching, Deep-Sea Lice (The)","definition":"English rendering of a supposed twelve-syllable Malay color-name for the living green on the Whales' Constructions. The novel does not supply the Malay expression (137).","notesPages":[330],"id":"glossary-entry-green-of-swarming-ocean-floor-etching-deep-sea-lice-the","letter":"G"},{"term":"Green Porpoise","definition":"Creature depicted below the Black Ship on the Saint Ledger coat-of-arms; identified as the Persian Gulf or Satrap Porpoise species (49).","notesPages":[330],"id":"glossary-entry-green-porpoise","letter":"G"},{"term":"Green-tree valleys","definition":"Type of location where blue-eyed yellow apes are found, only one of five hundred such valleys containing them (18).","notesPages":[330],"id":"glossary-entry-green-tree-valleys","letter":"G"},{"term":"Green trees","definition":"Vegetation seen by Axel Grindstone in the valley of Second Eden (16).","notesPages":[330],"id":"glossary-entry-green-trees","letter":"G"},{"term":"Gregarious","definition":"Characteristic of Lutin the Pythoness (62).","notesPages":[330],"id":"glossary-entry-gregarious","letter":"G"},{"term":"Gregor McGregor","definition":"One of the 'parents'/sponsors of the Gruenbaum- McGregor Experiment (84); hunts Dolophonoi with Iris and Shadrack (84-5); tortured by fear for his 'daughter' Gajah (85); trembles and cannot initially discard the Elephant-Gun (90); under strange compulsion, wills to kill Riesin and Gajah and fires the gun (90-1); runs into the wastelands in a raving mad state, hangs himself on a carob tree (91).","notesPages":[330],"id":"glossary-entry-gregor-mcgregor","letter":"G"},{"term":"Grin","definition":"Sardonic grin of Dolophonos-Assassin (125); Inneall's exasperating grin (162); Dubu's exasperating, concatenated, mysterious grin (163).","notesPages":[330],"id":"glossary-entry-grin","letter":"G"},{"term":"Grindstone","definition":"Figure depicted with a little-girl (pixie) face on the Saint Ledger coat-of-arms (49).","notesPages":[330],"id":"glossary-entry-grindstone","letter":"G"},{"term":"Grindstone (Ansel Abraham)","definition":"Father of the explorer Axel Albert Grindstone; predicts his son's short, single-minded life and later defends the humanity and beauty of the Unfallen People (10,16-18).","notesPages":[331],"id":"glossary-entry-grindstone-ansel-abraham","letter":"G"},{"term":"Grindstone (Axel Albert)","definition":"Human explorer born in Terre Haute in 1990, who locates Second Eden and dies one month before his thirty-fifth birthday after rejecting the Unfallen People's appearance (10-18). Distinct from the young Ape named Axel.","notesPages":[331],"id":"glossary-entry-grindstone-axel-albert","letter":"G"},{"term":"Grindstone (Duke)","definition":"Title used by companions addressing Axel Albert Grindstone (16).","notesPages":[331],"id":"glossary-entry-grindstone-duke","letter":"G"},{"term":"Grinning","definition":"Lord Randal depicted grinning in happy stone death on his cenotaph lid (149); Inneall grinning (162).","notesPages":[331],"id":"glossary-entry-grinning","letter":"G"},{"term":"Gripping","definition":"The murder mystery seemed gripping (157).","notesPages":[331],"id":"glossary-entry-gripping","letter":"G"},{"term":"Grizzled gray","definition":"Color of Alpha's hair, indicating age (51).","notesPages":[331],"id":"glossary-entry-grizzled-gray","letter":"G"},{"term":"Groaned","definition":"Carcajou groaned when touched by the Mega Dolophonos (94).","notesPages":[331],"id":"glossary-entry-groaned","letter":"G"},{"term":"Groaning","definition":"Riesin's labored breathing and groaning audible via scanner (94).","notesPages":[331],"id":"glossary-entry-groaning","letter":"G"},{"term":"Groove","definition":"Cryptic information supposedly written in the groove on the bottom side of turtles' tongues (75).","notesPages":[331],"id":"glossary-entry-groove","letter":"G"},{"term":"Gross","definition":"Exclaimed by Rose-of-Sharon Montdrago when the murders stop (153).","notesPages":[331],"id":"glossary-entry-gross","letter":"G"},{"term":"Grotesque","definition":"Gargoyles described as grotesque (13); the naturally born AMH Computer-child was grotesque (32); Satrap's Ocean Creature form is grotesque (135).","notesPages":[331],"id":"glossary-entry-grotesque","letter":"G"},{"term":"Grotesque Gar-goyles","definition":"See Gargoyles.","notesPages":[331],"id":"glossary-entry-grotesque-gar-goyles","letter":"G"},{"term":"Ground","definition":"Disappearing Apes (44); joined fellows under ground (44); house burns hole deep in the ground (96); burying Gajah not in the ground (93); meadow mice on the ground seen from two miles high (64).","notesPages":[331],"id":"glossary-entry-ground","letter":"G"},{"term":"Ground floor","definition":"Removed metaphorically from nations without causing immediate collapse (79).","notesPages":[331],"id":"glossary-entry-ground-floor","letter":"G"},{"term":"Group","definition":"Dolophonoi attempt to force the Twelve-Group to disband (87); suspicion that the merged group contains \"Serpent's Eggs\" (127); question of whether the Three still constitute a group (161).","notesPages":[332],"id":"glossary-entry-group","letter":"G"},{"term":"Grow","definition":"More blood grown by Henryetta (62); humans lack capacity to grow (40); Inneall's Ocean continues to grow (27, 43, 55, 86); rip in Mankind creature grows larger (37); understanding grows (72); 'people' grow rich and fat (162).","notesPages":[332],"id":"glossary-entry-grow","letter":"G"},{"term":"Growing","definition":"Inneall's Ocean (43, 47, 55); Gargoyle heads grow on Dolophonoi (41); sorrow and rue growing in Donatus O'Reily (157); understanding growing (72).","notesPages":[332],"id":"glossary-entry-growing","letter":"G"},{"term":"Grown-on","definition":"Attached by growth; refers to the Gargoyle faces on the Dolophonoi-Assassins (41).","notesPages":[332],"id":"glossary-entry-grown-on","letter":"G"},{"term":"Grubby","definition":"Feed-trough used as crib (155); men gathering to capture Apes are somewhat grubby (19).","notesPages":[332],"id":"glossary-entry-grubby","letter":"G"},{"term":"Gruenbaum-McGregor Experiment","definition":"One of the four experiments merged in the final days; members are Gajah (unborn elephant), Carcajou (wolverine), and Popugai (parrot) (55); sponsored by Gregor McGregor (84).","notesPages":[332],"id":"glossary-entry-gruenbaum-mcgregor-experiment","letter":"G"},{"term":"Gruenbaum-McGregor Group","definition":"Participants in the experiment, suspected of being slightly more intelligent than the other groups (55).","notesPages":[332],"id":"glossary-entry-gruenbaum-mcgregor-group","letter":"G"},{"term":"Guesthouse (James Mortimer's Gracious/Gallows)","definition":"See Gallows Guesthouse.","notesPages":[332],"id":"glossary-entry-guesthouse-james-mortimers-gracious-gallows","letter":"G"},{"term":"Guests","definition":"Carry-over guests at Persimmon Manor (116, 117, 123, 124, 125, 128, 153, 157, 158, 159); \"A House with Guests\" poem reference (115).","notesPages":[332],"id":"glossary-entry-guests","letter":"G"},{"term":"Guidance","definition":"Implied lack from The Three after Randal and Axel die (148).","notesPages":[332],"id":"glossary-entry-guidance","letter":"G"},{"term":"Guide","definition":"Hunters lacked a guide (84).","notesPages":[332],"id":"glossary-entry-guide","letter":"G"},{"term":"Guileless","definition":"Characteristic of doves, and of Felix Culebra y Columba (71, 115).","notesPages":[332],"id":"glossary-entry-guileless","letter":"G"},{"term":"Guilt","definition":"Felt by Dubu for putting the Three Fates to sleep (128).","notesPages":[332],"id":"glossary-entry-guilt","letter":"G"},{"term":"Gulf Porpoise (Persian)","definition":"Species name associated with the Green Porpoise on the Saint Ledger coat-of-arms (49).","notesPages":[333],"id":"glossary-entry-gulf-porpoise-persian","letter":"G"},{"term":"Gun","definition":"Big guns of the Assassins (85); Python-gun (87, 89, 90); Angel- gun (88, 89, 90); Wolverene-were-gun (88, 89, 90); Elephant-gun (89, 90, 91).","notesPages":[333],"id":"glossary-entry-gun","letter":"G"},{"term":"Gun-powder","definition":"Substance whose smell accompanied the Carcajou-Luas wrestling match (87).","notesPages":[333],"id":"glossary-entry-gun-powder","letter":"G"},{"term":"Gunnels","definition":"Upper edge of a ship's side; climbed over by Henryetta (139) and the interloper discovering the invisible ship (120).","notesPages":[333],"id":"glossary-entry-gunnels","letter":"G"},{"term":"Guns (Big)","definition":"Unusual weapons possessed by the Dolophonoi-Assassins, distinct from their knives (85).","notesPages":[333],"id":"glossary-entry-guns-big","letter":"G"},{"term":"Gypsy","definition":"Legendary interactions with Unfallen People (13); Inneall called a \"salt-water Gypsy\" by Atropos (126).","notesPages":[333],"id":"glossary-entry-gypsy","letter":"G"},{"term":"HAMBURGER MEAT","definition":"One thousand pounds of this constituted part of the cargo loaded onto the Annabella Saint Ledger before its final voyage, intended as a change from live-turtle meat for the pirate crew (101).","notesPages":[333],"id":"glossary-entry-hamburger-meat","letter":"H"},{"term":"HAND (GIANT)","definition":"A large, powerful, and numinous hand, with a wrist ten meters in diameter, that descended through the fissure in the roof of Apes' Caverns, smothered the holy fire lit by lightning, during the three-day 'Holy Sleep'; the Ape notary has already fallen asleep before the hand appears (68).","notesPages":[333],"id":"glossary-entry-hand-giant","letter":"H"},{"term":"HAPPY CHARLEY'S BAIT SHOP","definition":"Original name of the bait shop purchased cheaply by Schimp near the Ocean Shore; he planned to rename it 'Monkey Charley's Bait Shop' (161).","notesPages":[333],"id":"glossary-entry-happy-charleys-bait-shop","letter":"H"},{"term":"HARVARD MARK I","definition":"An early electromechanical computer conceived by Howard Aiken and built in collaboration with IBM, mentioned in the historical overview of computing (25).","notesPages":[334],"id":"glossary-entry-harvard-mark-i","letter":"H"},{"term":"HAUNTS","definition":"Spectral entities or ghosts; specifically, the spooks, polters, spectors, spirits, gimp- ghosts, haunts, and zombies that tend to inhabit 'empty' or bored AMH Computers, often arriving multiply (28); also, a campfire song sung at Heart's Desire Cove (59).","notesPages":[334],"id":"glossary-entry-haunts","letter":"H"},{"term":"HAY A LA RIESIN","definition":"A culinary specialty offered at Hot Dog Row, consisting of bales of bluestem hay soaked in aromatic sauces with Oats Imperial added; primarily for riding horses but enjoyed by many vegetarian people (58).","notesPages":[334],"id":"glossary-entry-hay-a-la-riesin","letter":"H"},{"term":"HEAD (SUPREME HEAD OF THE KANGAROO)","definition":"The ultimate leader of the Kangaroo organization at any given time; revealed via kangaroo knuckle-bone to be Invisible Alfred during the final events (145, 149); the role involves destroying targets before burning out from the 'Flaming Arrow Syndrome' (83); the identity of the Head is generally kept secret (145).","notesPages":[334],"id":"glossary-entry-head-supreme-head-of-the-kangaroo","letter":"H"},{"term":"HEADS (IMPERIAL HEADS OF THE KANGAROO)","definition":"The successive, temporary leaders of the Kangaroo organization; described as \"enraptured persons drunken with their mission,\" like \"flaming arrows\" who achieve their destructive goal with great accuracy before dying of the 'Flaming Arrow Syndrome'; must pass through a state of \"radiant intelligence\" before entering a \"post-intellectual state\" while holding office (83).","notesPages":[334],"id":"glossary-entry-heads-imperial-heads-of-the-kangaroo","letter":"H"},{"term":"HEART'S DESIRE COVE","definition":"A location on the North Shore of the growing Inneall's Ocean where the four experimental groups were merged (55); rapidly developed by Satrap Saint Ledger into a major entertainment center with diverse food stalls (Hot Dog Row, Sea-Food places, bait shops), enhanced music attracting birds, water sports, and nightly bonfires (57-59); later referred to as Oceanside after the cove's lines were obliterated by the expanding Ocean (86); the shore area includes a natural amphitheater (109).","notesPages":[334],"id":"glossary-entry-hearts-desire-cove","letter":"H"},{"term":"HEAVEN","definition":"Place where souls go after death, characterized by \"semi- conscious blandness,\" contrasted by Carcajou with Hell where the action is (72); God in Heaven invoked regarding the monumental stones built by Whales (132).","notesPages":[335],"id":"glossary-entry-heaven","letter":"H"},{"term":"HECTOR BROWN","definition":"Original name of the pirate seaman later given the contrived name Sebastian Lazar by Inneall (98).","notesPages":[335],"id":"glossary-entry-hector-brown","letter":"H"},{"term":"HEIDELBERG","definition":"German city cited as a place from which great mathematicians came to sit at the feet of the Unfallen Ones to learn high mathematics (15).","notesPages":[335],"id":"glossary-entry-heidelberg","letter":"H"},{"term":"HELL","definition":"Realm of punishment or intense action; preferred by Carcajou over Heaven's blandness (\"Hell is better. Action is always better than blandness\") (72); destination the pirate crew would follow the Royal Kids to (100); origin of the damned mixtures that produced the Dolophonoi-Assassins (87); Axel Grindstone refers to the Unfallen as the \"ugliest apes this side of hell\" (17).","notesPages":[335],"id":"glossary-entry-hell","letter":"H"},{"term":"HENRYETTA","definition":"The young female human of the Wintergreen-Luna Experiment (55); described as the most contrary human imaginable, possessing a very strong (though non- angelic) will (61); intensely loyal to the other Eleven (61); engages in sharp banter, calling Dubu a commoner (63) and Lutin a \"slithering bumbler\" (62); initiates acquisition of the steam calliope (85) and the enchanted cannon (95); possesses pyrokinesis, having burned down seven Waif-aramas as a baby (96); claims the bilge-water tonic as her idea (100); murdered by Invisible Alfred using a Dolophonoi knife, falling across her own cenotaph (149).","notesPages":[335],"id":"glossary-entry-henryetta","letter":"H"},{"term":"HERRINGS","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[335],"id":"glossary-entry-herrings","letter":"H"},{"term":"HICKORY COAL MINES","definition":"Old mines connected by vaulted passages to the Ape Caverns (45).","notesPages":[335],"id":"glossary-entry-hickory-coal-mines","letter":"H"},{"term":"HIERONYMOUS IGNATIUS ZCHOLD","definition":"A Bishop of the Old Religion whose capital offense is explicitly his being a priest of the Old Religion; officials later identify him as a bishop (122,158); arranges to be stoned on Tom Dooley's Island to avoid having his consecrated body eaten by dogs (122); disemboweled before being stoned by professionals and onlookers (158); his body is retrieved by four fish-faced men and taken to the Ocean Bottom (159); name inscribed on an empty cenotaph there (150).","notesPages":[335,336],"id":"glossary-entry-hieronymous-ignatius-zchold","letter":"H"},{"term":"HIGH LAMA","definition":"Tibetan religious figure facetiously suggested by Carcajou as the teacher of Satrap's diving technique. Satrap rejects this suggestion and says he learned from Masters in the Indian Ocean (133).","notesPages":[336],"id":"glossary-entry-high-lama","letter":"H"},{"term":"HIGH TIBET","definition":"Mountainous region cited by Satrap as lacking oceans, oceanography, and Ocean Masters, refuting Carcajou's suggestion about the origin of his diving technique (133).","notesPages":[336],"id":"glossary-entry-high-tibet","letter":"H"},{"term":"HILL (TOM DOOLEY'S HILL)","definition":"Original landform which became Tom Dooley's Island when surrounded by Inneall's Ocean (100, 116).","notesPages":[336],"id":"glossary-entry-hill-tom-dooleys-hill","letter":"H"},{"term":"HIMALAYA INCENSE BUSHES","definition":"Fragrant shrubs gathered by Riesin to cover the body of the dead Gajah in the Elephant Graveyard (94).","notesPages":[336],"id":"glossary-entry-himalaya-incense-bushes","letter":"H"},{"term":"HIND (GOLDEN HIND)","definition":"Famous pirate ship of Sir Francis Drake; the enchanted ninety- ninth cannon aboard the Annabella Saint Ledger originated from this ship (96).","notesPages":[336],"id":"glossary-entry-hind-golden-hind","letter":"H"},{"term":"HISTORY OF THE AMBULATORY COMPUTERS FROM THEIR VERY ORIGIN","definition":"Title of the historical work being written by the Ambulatory Computer Livius Secundus, tracing their mythological roots in the human under-mind and weird caves of crypto-memory, through their liberation from human masters ('The Tarquins'), through the foundation of the 'First Computer Republic of the Mind' (70-71).","notesPages":[336],"id":"glossary-entry-history-of-the-ambulatory-computers-from-their-very-origin","letter":"H"},{"term":"HOLISTIC HORSEFLIES","definition":"Exclamation used by an AMH Computer, expressing exasperation at human ineptitude and limited perspective (specifically, seeing only one side of a playing card) (39).","notesPages":[336],"id":"glossary-entry-holistic-horseflies","letter":"H"},{"term":"HOLY APES","definition":"Term used by Alpha when referring to the awakened Apes in Second Eden (51).","notesPages":[336],"id":"glossary-entry-holy-apes","letter":"H"},{"term":"HOLY FIRE","definition":"Traditional nightly blaze in Apes' Caverns, lit by lightning striking the main gas jet; ceases burning during the three days of Holy Sleep (67).","notesPages":[337],"id":"glossary-entry-holy-fire","letter":"H"},{"term":"HOLY SLEEP","definition":"The deep, enchanted sleep cast upon all occupants of Ape Caverns for three nights and three days, accompanied by a giant hand descending through the roof fissure and smothering the holy fire; the sleep begins before that descent (68); occupants cannot be awakened normally (70).","notesPages":[337],"id":"glossary-entry-holy-sleep","letter":"H"},{"term":"HOMO SAPIENS","definition":"Scientific name for Man, described as the most widespread, numerous, and reputedly most intelligent of primates (35).","notesPages":[337],"id":"glossary-entry-homo-sapiens","letter":"H"},{"term":"HONDURAS","definition":"Country whose thick forests lie south of Nebraska on the bird migration route; birds can bi-locate between these distant points while daydreaming (95).","notesPages":[337],"id":"glossary-entry-honduras","letter":"H"},{"term":"HONEY-CANE","definition":"Experimental plant cultivated in The Three's habitat (3).","notesPages":[337],"id":"glossary-entry-honey-cane","letter":"H"},{"term":"HONOR","definition":"Abstract concept which became a leading cultural indicator in the Floating World; its 'Resurrection' involved somewhat extravagant rituals but centered on a \"bright ideal of Honor Itself\"; Donatus O'Reily committed a hangable misdemeanor related to an Affair of Honor (117-118).","notesPages":[337],"id":"glossary-entry-honor","letter":"H"},{"term":"HONOR ITSELF","definition":"The \"bright ideal\" at the core of the 'Resurrection of Honor' movement (118).","notesPages":[337],"id":"glossary-entry-honor-itself","letter":"H"},{"term":"HOOKS (PRUNING HOOKS)","definition":"An alternative name for the Dolophonoi or Assassins, instruments of the Kangaroo (83).","notesPages":[337],"id":"glossary-entry-hooks-pruning-hooks","letter":"H"},{"term":"HOOTNANNY (WE-OWE-A-LOT-TO-OTTO-WOTTO HOOTNANNY)","definition":"A campfire song sung at Heart's Desire Cove, presumably celebrating the inventor of wotto metal (59).","notesPages":[337],"id":"glossary-entry-hootnanny-we-owe-a-lot-to-otto-wotto-hootnanny","letter":"H"},{"term":"HORN (CAPE HORN)","definition":"Southern tip of South America, near Wollaston Island, home of the late-crowning Drake Passage Cock (118).","notesPages":[337],"id":"glossary-entry-horn-cape-horn","letter":"H"},{"term":"HORN OF AFRICA","definition":"Region connected by the Ape Bridge to Arabia (11, 12).","notesPages":[338],"id":"glossary-entry-horn-of-africa","letter":"H"},{"term":"HOSEA LANTERNJAW","definition":"Ancestor of Lanternjaw Lunnigan, from Surrey, England; part of a pirate family spanning many centuries (98).","notesPages":[338],"id":"glossary-entry-hosea-lanternjaw","letter":"H"},{"term":"HOT COON SANDWICHES","definition":"A culinary specialty offered at Heart's Desire Cove (58).","notesPages":[338],"id":"glossary-entry-hot-coon-sandwiches","letter":"H"},{"term":"HOT DOG","definition":"Food item discovered and verified to be the 'King of Foods' (58).","notesPages":[338],"id":"glossary-entry-hot-dog","letter":"H"},{"term":"HOT DOG ROW","definition":"Area within the Heart's Desire Cove entertainment center featuring stalls selling specialized hot dogs named after each of the Eleven (58).","notesPages":[338],"id":"glossary-entry-hot-dog-row","letter":"H"},{"term":"HOUSE (BIG HOUSE/PERSIMMON MANOR)","definition":"The very large ranch house attributed to Tom Dooley's grandfather on p.116, but to his and Otto Wotto's great-great-grandfather on p.124; built entirely of persimmon wood (124); site of continuous parties with carry-over guests (116); potentially haunted (124-125); made waterproof and lead-weighted to prevent floating when the island sinks (116); sinks to the Ocean Bottom (159); contains a hidden \"horrible little room\" where the Three Fates reside (114, 126); becomes the underwater home of Inneall, Lutin, and Dubu after the sinking; the surviving companions make different plans (159-162).","notesPages":[338],"id":"glossary-entry-house-big-house-persimmon-manor","letter":"H"},{"term":"HOUSE ON TOM DOOLEY'S ISLAND","definition":"Title of Chapter Eleven (115); refers to Persimmon Manor (148).","notesPages":[338],"id":"glossary-entry-house-on-tom-dooleys-island","letter":"H"},{"term":"HUBBARD","definition":"Author of the Big Book of Strange Happenings, which documents cases of human bi-location (95).","notesPages":[338],"id":"glossary-entry-hubbard","letter":"H"},{"term":"HUMAN CULTURE","definition":"Defined by Britannica as behavior peculiar to mankind (language, ideas, beliefs, customs, etc.) along with associated material objects (39).","notesPages":[338],"id":"glossary-entry-human-culture","letter":"H"},{"term":"HUMAN IMPRINTING","definition":"Process of acquiring human characteristics; Inneall suspects she received most of her human imprinting from the Axel's Apes (51).","notesPages":[338],"id":"glossary-entry-human-imprinting","letter":"H"},{"term":"HUMAN MUSIC (COMPUTER-ENHANCED)","definition":"See COMPUTER- ENHANCED HUMAN MUSIC.","notesPages":[339],"id":"glossary-entry-human-music-computer-enhanced","letter":"H"},{"term":"HUMAN PSYCHOLOGY (ANALYTICAL)","definition":"See ANALYTICAL HUMAN PSYCHOLOGY.","notesPages":[339],"id":"glossary-entry-human-psychology-analytical","letter":"H"},{"term":"HUMAN SPECIES","definition":"Mankind (Homo Sapiens); characterized by intricate language, large brain, royal title, but ill fit in the world (34); paradoxical nature (35); is portrayed as a flawed creation in AMH legends (36-37); is said by an AMH commentator to possess unused brain capacity and to change, if at all, by sudden leaps (39-40); historically distinct but now potentially hybridizing (41-42); includes Lord Randal and Henryetta (61).","notesPages":[339],"id":"glossary-entry-human-species","letter":"H"},{"term":"HYPER-INTELLIGENCE SCANNERS","definition":"Advanced scanning devices used to identify species worthy of experiments; discovered that nearly every species throws off \"clear off the scale\" intelligences occasionally (55).","notesPages":[339],"id":"glossary-entry-hyper-intelligence-scanners","letter":"H"},{"term":"I.Q.","definition":"Intelligence Quotient; Lord Randal was bred and vitro-ed to have an I.Q. \"clear off the scale\" (5).","notesPages":[339],"id":"glossary-entry-i-q","letter":"I"},{"term":"Idea (Axel's One Idea)","definition":"The singular, consuming concept or life mission attributed to Axel Albert Grindstone by his father, Ansel; initially understood by Axel as his quest for Second Eden and the Unfallen People, this idea was \"horribly and in utter rejection\" realized upon confronting the Gargoyle faces of the Unfallens, leading directly to his predicted death (10, 18).","notesPages":[339],"id":"glossary-entry-idea-axels-one-idea","letter":"I"},{"term":"Ideal (of Honor)","definition":"The \"bright ideal of Honor Itself,\" described as the core concept behind the \"Resurrection of Honor\" movement within the Floating World, despite some associated rituals being extravagant or overdone (118).","notesPages":[339],"id":"glossary-entry-ideal-of-honor","letter":"I"},{"term":"Idealist (Blue-Eyed)","definition":"Description applied to the young Axel Albert Grindstone during his quest for the Second Eden (11).","notesPages":[340],"id":"glossary-entry-idealist-blue-eyed","letter":"I"},{"term":"Ideas","definition":"Part of Human Culture (39); transmitted instantly in the Floating World (80); the \"absolutely original ideas\" gained by Dubu from eating raw \"Filchman's Daughter\" fish (75); Marino credited with having many new ideas (60); the State develops its own \"vicious idea\" (78).","notesPages":[340],"id":"glossary-entry-ideas","letter":"I"},{"term":"Identifications","definition":"The ability to distinguish between species (human, ape, mechanism), which has become clouded by the emergence of partly artificial entities like the Dolophonoi and potential hybrids like the Axel's Apes (41).","notesPages":[340],"id":"glossary-entry-identifications","letter":"I"},{"term":"Ignatius Zchold, Hieronymous","definition":"A Bishop of the Old Religion sentenced to death because he is a priest of the Old Religion, with his episcopal status prompting still harsher treatment (122,158). He arranged to be executed privately on Tom Dooley's Island to prevent dogs devouring his consecrated body (122). Despite protests, officials carried out the sentence with public spectacle, including disembowelment (158). His body was taken by four fish- faced men to the Ocean Bottom (159), where an empty cenotaph bearing his name (\"Hieronymous Ignatius Zchold, a Good Man\") had already been found (150,156). See also Zchold, Hieronymous Ignatius.","notesPages":[340],"id":"glossary-entry-ignatius-zchold-hieronymous","letter":"I"},{"term":"Ignorant Midas","definition":"Insult directed at Satrap Saint Ledger by Inneall, implying his vast wealth does not equate to knowledge (specifically about wotto metal) (48). See also Midas.","notesPages":[340],"id":"glossary-entry-ignorant-midas","letter":"I"},{"term":"Illinois River","definition":"One of the major rivers whose valley is being captured by the growing expanse of Inneall's Ocean (55).","notesPages":[340],"id":"glossary-entry-illinois-river","letter":"I"},{"term":"Illuminating gas","definition":"Natural gas used for lighting purposes; specifically, the methane from fissures in Second Eden (45) and tapped wells in Ape Caverns (45), ignited nightly; noted as causing fogs when burned underground in damp caverns (46).","notesPages":[340],"id":"glossary-entry-illuminating-gas","letter":"I"},{"term":"Illusion (of a body)","definition":"The non-physical form possessed by the angel Luas; his mind and this illusion were described as one entity (61).","notesPages":[340],"id":"glossary-entry-illusion-of-a-body","letter":"I"},{"term":"Illusions","definition":"The faint traces of human faces under the Dolophonoi's Gargoyle heads might possibly be illusions (42).","notesPages":[340],"id":"glossary-entry-illusions","letter":"I"},{"term":"Image and Likeness of God","definition":"The theological concept, cited from the Baltimore Catechism, stating that Man is created according to the divine pattern (35); this concept is extended analogously, suggesting Computer Machines are made in the image of Man (93).","notesPages":[341],"id":"glossary-entry-image-and-likeness-of-god","letter":"I"},{"term":"Image of Man","definition":"The template or pattern after which Computer Machines are made, mirroring Man's creation in the image of God (93).","notesPages":[341],"id":"glossary-entry-image-of-man","letter":"I"},{"term":"Imaginary","definition":"The perceived difference in brain size or attainments between Neanderthals/Cro- Magnons and modern humans may be entirely imaginary (40).","notesPages":[341],"id":"glossary-entry-imaginary","letter":"I"},{"term":"Imagination","definition":"Stimulated by the sketchy visuals and background noise of 'prowls' (6).","notesPages":[341],"id":"glossary-entry-imagination","letter":"I"},{"term":"Immediacies","definition":"Present moments or pressing concerns; included in the scope of Felix Culebra y Columba's \"Life Affair\" weaving (74).","notesPages":[341],"id":"glossary-entry-immediacies","letter":"I"},{"term":"Immediate Present-Times","definition":"The state of eternal nowness experienced by Ambulatory Computers, who lack historical sense and cannot create pasts or futures; characterized by an immediacy that \"sang like cosmic music\" (71).","notesPages":[341],"id":"glossary-entry-immediate-present-times","letter":"I"},{"term":"Impediment (on Tongue)","definition":"A magical restriction placed by the Prophet Invisible Alfred upon the tongues of the eleven Devil-Fish, silencing their roaring and howling (108).","notesPages":[341],"id":"glossary-entry-impediment-on-tongue","letter":"I"},{"term":"Imperial Heads (of Kangaroo)","definition":"The successive, temporary supreme leaders of the Kangaroo organization. Described as \"enraptured persons drunken with their mission,\" they execute their destructive tasks with great accuracy like \"flaming arrows\" before dying of the \"Flaming Arrow Syndrome.\" They necessarily pass through a state of \"radiant intelligence\" before entering the \"post-intellectual state\" required for holding office (83).","notesPages":[341],"id":"glossary-entry-imperial-heads-of-kangaroo","letter":"I"},{"term":"Impersonal Mechanism (State as)","definition":"A concept attributed to Maritain, defining the State not as a person but as a mere mechanism of abstract laws and concrete power, capable of becoming superhuman and turning Man into its servant when the \"vicious idea\" discussed in the quoted passage develops (78).","notesPages":[341],"id":"glossary-entry-impersonal-mechanism-state-as","letter":"I"},{"term":"Impetus","definition":"Theoretically, a single small computer or earthworm with sufficient time and impetus could convert the entire world (27); Inneall's Ocean exemplifies relentless AMH impetus (27).","notesPages":[342],"id":"glossary-entry-impetus","letter":"I"},{"term":"Implication","definition":"The implication that Satrap Saint Ledger might be one of the seven richest metamorphic men is declared false (135).","notesPages":[342],"id":"glossary-entry-implication","letter":"I"},{"term":"Impossible place","definition":"A point in discussion or investigation beyond which progress seems logically unattainable; the narrative reaches such a place regarding the \"meat\" or \"substance\" of Mankind (38).","notesPages":[342],"id":"glossary-entry-impossible-place","letter":"I"},{"term":"Impossible venture","definition":"Describes the Dolophonoi-hunting mission of Iris Lynn-Randal, Shadrack Saleh, and Gregor McGregor (84).","notesPages":[342],"id":"glossary-entry-impossible-venture","letter":"I"},{"term":"Imprinting","definition":"Inneall suspects her human fears, terrors, and jealousies result from imprinting acquired primarily from the Axel's Apes (50- 51).","notesPages":[342],"id":"glossary-entry-imprinting","letter":"I"},{"term":"Imprinting (Human & Yellow Apes)","definition":"Specific types of behavioral learning; Inneall suggests there may not be much difference between them (51).","notesPages":[342],"id":"glossary-entry-imprinting-human-yellow-apes","letter":"I"},{"term":"Incandescent friendship","definition":"A friendship characterized by extreme brilliance and passion; potentially lacked by Marino due to the sheer quantity of his friendships (60).","notesPages":[342],"id":"glossary-entry-incandescent-friendship","letter":"I"},{"term":"Incense bushes (Himalaya)","definition":"Fragrant shrubs native to the Himalayas, gathered by the grieving mother elephant Riesin to cover the body of her dead unborn daughter Gajah in the Elephant Graveyard (94).","notesPages":[342],"id":"glossary-entry-incense-bushes-himalaya","letter":"I"},{"term":"India","definition":"South Asian country; setting of the novel's fantastic history of Empress Elephant mayors (92); the graveyard reached by Riesin is more specifically placed in Mustang, north of India (93), although Satrap also calls it Indian (128); origin of the gavial- crocodile hide used for Dolophonoi gloves (86).","notesPages":[342],"id":"glossary-entry-india","letter":"I"},{"term":"India Elephants","definition":"Asian elephants (Elephas maximus), including Gajah and Riesin. In the novel they use bi-location to reach their graveyard (95), and are assigned a gestation of less than twenty months (57). Real elephant gestation is about twenty to twenty-two months.","notesPages":[342],"id":"glossary-entry-india-elephants","letter":"I"},{"term":"Indian Ocean","definition":"Body of water where Satrap Saint Ledger learned the technique of free diving and moving from unspecified \"Masters\" (133).","notesPages":[342],"id":"glossary-entry-indian-ocean","letter":"I"},{"term":"Indian Tribes (Red Indian)","definition":"The novel claims Native American peoples adopted lacrosse after Saint Brandon introduced it in 536 (65). This is invented history: lacrosse has Indigenous North American origins, with a longstanding sacred role among the Haudenosaunee.","notesPages":[343],"id":"glossary-entry-indian-tribes-red-indian","letter":"I"},{"term":"Indianapolis","definition":"Capital city of the state of Indiana, called a \"provincial capital\" by the novel; destination of the telegram sent from Arba Mench concerning Axel Grindstone's critical condition (14).","notesPages":[343],"id":"glossary-entry-indianapolis","letter":"I"},{"term":"Indication (that Experiments will not work)","definition":"The Dolophonoi see their own damnable mixed nature as proof that the Experiments involving similar elements (human, animal, machine) are false and forbidden (87).","notesPages":[343],"id":"glossary-entry-indication-that-experiments-will-not-work","letter":"I"},{"term":"Indicators (Cultural)","definition":"Societal trends or phenomena reflecting dominant values; Honor is identified as a leading cultural indicator in the Floating World during the summer of the narrative (117).","notesPages":[343],"id":"glossary-entry-indicators-cultural","letter":"I"},{"term":"Indies (Rum of the)","definition":"Specific type of rum demanded by Inneall for the pirate crew, supposedly originating from the West Indies and traditionally stored in large casks (hogsheads, butts, pipes, tuns) (99).","notesPages":[343],"id":"glossary-entry-indies-rum-of-the","letter":"I"},{"term":"Individuals","definition":"Question of which species individuals belong to when joining the Kangaroo (83).","notesPages":[343],"id":"glossary-entry-individuals","letter":"I"},{"term":"Indo-Asia","definition":"Region from which the Gypsies originated before crossing the Ape Bridge (13).","notesPages":[343],"id":"glossary-entry-indo-asia","letter":"I"},{"term":"Indoctrinated","definition":"The \"parents\" of the Experiments were indoctrinated to accept decisions about their fosterlings without question (84); Satrap indoctrinated the humans into Oceanic Metastasis (134).","notesPages":[343],"id":"glossary-entry-indoctrinated","letter":"I"},{"term":"Indoctrination","definition":"Received by the \"parents\" (84); the secret method and content used by Satrap for Oceanic Metastasis (134).","notesPages":[343],"id":"glossary-entry-indoctrination","letter":"I"},{"term":"Induced Sleep-Walking Sleep","definition":"An artificial somnambulistic state achieved through self- hypnosis, practiced by the Dolophonoi for stealthy murder; it provided no protection against the pervasive Deep Sleep within the Cenaculum (147, 149).","notesPages":[343],"id":"glossary-entry-induced-sleep-walking-sleep","letter":"I"},{"term":"Inequities (Past)","definition":"Cited by the ten percent of AMHs identifying as female as the rationale for demanding fifty-seven percent (rather than fifty percent) gender representation among all Computers (69).","notesPages":[343],"id":"glossary-entry-inequities-past","letter":"I"},{"term":"Inertial Motion","definition":"The inherent tendency of a process to continue to its conclusion unless halted by external force; presented as the driving principle behind computer actions, distinct from conscious 'will' (27).","notesPages":[344],"id":"glossary-entry-inertial-motion","letter":"I"},{"term":"Inferior Spooks","definition":"Inneall's dismissive term for the seven ghosts residing within her; she characterizes them as heavy, unhappy, ignorant, provincial, banal, and prone to giggling and bragging about their antics (29).","notesPages":[344],"id":"glossary-entry-inferior-spooks","letter":"I"},{"term":"Infirmary (Ship's)","definition":"Governed by the single directive, claimed explicitly by Henryetta: treat any sickness or suppuration with bilge-water tonic (100) aboard the Annabella Saint Ledger.","notesPages":[344],"id":"glossary-entry-infirmary-ships","letter":"I"},{"term":"Information","definition":"Needed by Carcajou for logs and memoirs (119); derived from kangaroo knuckle-bone (145); Invisible Alfred claims to have access to vast information (implied) (108); cryptic information on turtles' tongues (75).","notesPages":[344],"id":"glossary-entry-information","letter":"I"},{"term":"Information (Cryptic)","definition":"See Cryptic Information.","notesPages":[344],"id":"glossary-entry-information-cryptic","letter":"I"},{"term":"Information (True, from Kangaroo)","definition":"Always written on a kangaroo knuckle-bone, guaranteeing authenticity (145).","notesPages":[344],"id":"glossary-entry-information-true-from-kangaroo","letter":"I"},{"term":"Ingrained (Marble)","definition":"Describes the deeply embedded quality of the variegated crystalized marble transformed from limestone by the Whales (136).","notesPages":[344],"id":"glossary-entry-ingrained-marble","letter":"I"},{"term":"Inhabitants (of the Caverns)","definition":"Residents of Ape Caverns, for whom a newspaper was printed (46).","notesPages":[344],"id":"glossary-entry-inhabitants-of-the-caverns","letter":"I"},{"term":"Inhibitions (Extra-species Inhibitions)","definition":"A concept, apparently related to inter-species romance or relationships, which the little Ape girls do not understand regarding Inneall and Axel, but which Inneall is jealous they do not face (51).","notesPages":[344],"id":"glossary-entry-inhibitions-extra-species-inhibitions","letter":"I"},{"term":"Initiative","definition":"Hangings of Natural Nobility members to be done on their own initiative at the appointed hour (118).","notesPages":[344],"id":"glossary-entry-initiative","letter":"I"},{"term":"Inklings","definition":"Included in the scope of Felix Culebra y Columba's \"Life Affair\" weaving (74).","notesPages":[344],"id":"glossary-entry-inklings","letter":"I"},{"term":"Inneall","definition":"A central protagonist, one of The Three raised in the Lynn- Randal Experiment (1); an Ambulatory Mime-Human Computer (3), grammatically male but insists she is a girl (3); possesses fourteen fingers (25) and filter eyes (76); creates the vast, growing Inneall's Ocean (24, 27, 43); adopts the persona \"Bloody Mary Muldoon the Pirate Queen\" (24, 59); inhabited by seven ghosts (29); acquires the yacht Annabella Saint Ledger (47-9); survives the final catastrophe but loses the power to transmit her log; her account ends with an admission of dishonesty, followed by the Sea Louse's epilog (163-166).","notesPages":[345],"id":"glossary-entry-inneall","letter":"I"},{"term":"Inneall-Annabella (Ship Boats)","definition":"Designation given to the two speedsters (Jolly Roger, Crabby Roger) provided by Satrap, indicating they are tenders to Inneall's flagship, the Annabella Saint Ledger (58).","notesPages":[345],"id":"glossary-entry-inneall-annabella-ship-boats","letter":"I"},{"term":"Inneall (Memorial Park to)","definition":"Heart's Desire Cove, built by Satrap Saint Ledger as such (57).","notesPages":[345],"id":"glossary-entry-inneall-memorial-park-to","letter":"I"},{"term":"Inneall (Poem)","definition":"Verse epigraph for Chapter Three, spoken by Inneall about being wakened and creating oceans (23).","notesPages":[345],"id":"glossary-entry-inneall-poem","letter":"I"},{"term":"Inneall's Log","definition":"The narrative record purportedly kept by Inneall; Miol-Mor says it is \"more than half lies\" and announces that the Whales have taken over annal-keeping (164). The Sea Louse calls the Log \"full of lies\" while boasting it can outdo Inneall at lying (166).","notesPages":[345],"id":"glossary-entry-innealls-log","letter":"I"},{"term":"Inneall's Ocean","definition":"The immense and rapidly expanding body of salt water created by Inneall through environmental cannibalization and diversion of solar power (24, 27, 59); situated initially near Ape Alley and Structo Lane (43), it grows to encompass Tom Dooley's Hill (100) and the valleys of major rivers (55); becomes a hub of activity with entertainment centers, boat traffic, and ultimately, the site of the Whales' underwater constructions and the sunken Persimmon Manor (57-8, 106-7, 159-60); Inneall secretly intends it to cover the entire Earth (130, 147).","notesPages":[345],"id":"glossary-entry-innealls-ocean","letter":"I"},{"term":"\"Inneall's Ocean Hallelulah\"","definition":"A rousing campfire song celebrating Inneall's creation; hearing it sung causes Inneall an \"Emotion- without-a-Name\", strongly suggesting embarrassment despite her computer nature (59).","notesPages":[345],"id":"glossary-entry-innealls-ocean-hallelulah","letter":"I"},{"term":"Innoculation","definition":"Inneall theorizes that experiencing Ocean Sleep might provide an innoculation against catching the Deep Sleep of the Ape Caverns (142); the Dolophonoi's self-induced sleep-walking state offers no such protection (143).","notesPages":[345,346],"id":"glossary-entry-innoculation","letter":"I"},{"term":"Insect languages","definition":"Among the many thousands of non-human languages known and perfectly pronounced by Popugai the parrot (64).","notesPages":[346],"id":"glossary-entry-insect-languages","letter":"I"},{"term":"Insects (Experimental)","definition":"Part of the diverse fauna sharing the contrived habitat with The Three (3).","notesPages":[346],"id":"glossary-entry-insects-experimental","letter":"I"},{"term":"Inside","definition":"Electronic gear inside the Big Egg (155); mechanism inside coffin activated from inside (166); answers written on the inside of an Acorn (74).","notesPages":[346],"id":"glossary-entry-inside","letter":"I"},{"term":"Insightful flesh","definition":"Dubu's term for the uncooked flesh or fish or fowl that she believes grants sudden intuitions and original ideas when consumed (75).","notesPages":[346],"id":"glossary-entry-insightful-flesh","letter":"I"},{"term":"Insights (Sudden)","definition":"Profound understandings gained, according to Dubu, by eating the raw flesh of insightful creatures like the \"Filchman's Daughter\" fish (75).","notesPages":[346],"id":"glossary-entry-insights-sudden","letter":"I"},{"term":"Instantaneous","definition":"Describes the operation of the angel Luas's mind (61); the transmission speed of ideas and notions in the Floating World (80).","notesPages":[346],"id":"glossary-entry-instantaneous","letter":"I"},{"term":"Institute of Impure Science","definition":"Research facility where the first Ambulatory Mime-Human Computers (AMHs) were developed by Smirnov and Shiplap (25).","notesPages":[346],"id":"glossary-entry-institute-of-impure-science","letter":"I"},{"term":"Institutions","definition":"Part of Human Culture (39); zoos and institutions holding captured Axel's Apes (20, 51).","notesPages":[346],"id":"glossary-entry-institutions","letter":"I"},{"term":"Instruction","definition":"Computers cannot distinguish prediction from instruction (1); Satrap gives instruction on Oceanic Metastasis (134).","notesPages":[346],"id":"glossary-entry-instruction","letter":"I"},{"term":"Instrument (of our exile)","definition":"Axel Albert Grindstone described as the unwitting instrument causing the Axel's Apes' exile from Second Eden (52).","notesPages":[346],"id":"glossary-entry-instrument-of-our-exile","letter":"I"},{"term":"Instruments","definition":"Musical instruments in Lynn-Randal house limited (8); Dolophonoi described as instruments of the Kangaroo (84).","notesPages":[346],"id":"glossary-entry-instruments","letter":"I"},{"term":"Insurance rates","definition":"More favorable for owners of five or more yachts, motivating Satrap's large fleet (116).","notesPages":[347],"id":"glossary-entry-insurance-rates","letter":"I"},{"term":"Integrated (Marble)","definition":"Describes the fully combined and unified state of the variegated crystalized marble formed from limestone (136).","notesPages":[347],"id":"glossary-entry-integrated-marble","letter":"I"},{"term":"Integration","definition":"Traced back from disintegration when studying Mankind's past (37).","notesPages":[347],"id":"glossary-entry-integration","letter":"I"},{"term":"Intelligence","definition":"Of Axel's Apes (19); of AMHs (26); mega intelligence (83); radiant intelligence (83); of Homo Sapiens (35); required to be \"Serpent's Egg\" (117); transcendent intelligence poured into Unfallens (17). See also Mega intelligence, Radiant intelligence.","notesPages":[347],"id":"glossary-entry-intelligence","letter":"I"},{"term":"Intelligences (Clear off the Scale)","definition":"A level of intellectual capacity so high it cannot be further rated or compared using standard Hyper- Intelligence Scanners; found occasionally in nearly every species of sufficient size (55); possessed by the Twelve, with Carcajou exceeding even a further secret scale (55, 64); the ten children and three adult guardians watching the scanner understand Hindi (93-94).","notesPages":[347],"id":"glossary-entry-intelligences-clear-off-the-scale","letter":"I"},{"term":"Interested persons","definition":"Individuals present during Donatus O'Reily's request to be hanged at Persimmon Manor (121).","notesPages":[347],"id":"glossary-entry-interested-persons","letter":"I"},{"term":"Interesting","definition":"The Big Egg mystery is interesting to Dubu (163); speculations by Livius (71); conversations (147); pirates considered interesting by Inneall (120).","notesPages":[347],"id":"glossary-entry-interesting","letter":"I"},{"term":"Interloper","definition":"The brave interloper/discoverer who boards the invisible ship (120). See also Interloper (Brave).","notesPages":[347],"id":"glossary-entry-interloper","letter":"I"},{"term":"Interloper (Brave)","definition":"The hypothetical bold discoverer who climbs aboard the invisible Annabella Saint Ledger years later, witnessing the skeletal crew and hearing the mad captain (120). See also Interloper.","notesPages":[347],"id":"glossary-entry-interloper-brave","letter":"I"},{"term":"Interloper Constellation","definition":"The Kangaroo, which appears hypnotically and subjectively in the place of Virgo in the Eastern Sky, visible only to those it threatens (76).","notesPages":[347],"id":"glossary-entry-interloper-constellation","letter":"I"},{"term":"Interloping men","definition":"The human group, described as \"somewhat grubby and greedy,\" who followed Axel Grindstone to Second Eden and captured five hundred Axel's Apes for zoos and experiments (18-19).","notesPages":[347],"id":"glossary-entry-interloping-men","letter":"I"},{"term":"Intermediate fishes","definition":"Mid-sized fish species, part of the colorful array inhabiting Inneall's Ocean (139).","notesPages":[348],"id":"glossary-entry-intermediate-fishes","letter":"I"},{"term":"International Dateline","definition":"The irregular boundary between consecutive calendar dates, approximately following 180° longitude. In the novel, Kure Island is the site of the Gallows Guesthouse and its official cockcrow is said to be the latest in the world (118). See also Dateline (International).","notesPages":[348],"id":"glossary-entry-international-dateline","letter":"I"},{"term":"International Law","definition":"Invoked by Inneall regarding yacht confiscation (47); Satrap doubts its applicability (48).","notesPages":[348],"id":"glossary-entry-international-law","letter":"I"},{"term":"Interspecies counseling","definition":"The profession Popugai the parrot intends to take up upon returning to New Zealand, involving advising different species (161).","notesPages":[348],"id":"glossary-entry-interspecies-counseling","letter":"I"},{"term":"Interspecies Intermezzo","definition":"Title of one of the campfire songs sung at Heart's Desire Cove (59).","notesPages":[348],"id":"glossary-entry-interspecies-intermezzo","letter":"I"},{"term":"Interspecies venture","definition":"A collaborative undertaking involving members of different species; the Kangaroo (composed of Humans, Ambulatory Computers, and superior Animals) is cited as the first truly successful example (80).","notesPages":[348],"id":"glossary-entry-interspecies-venture","letter":"I"},{"term":"Intestines","definition":"Removed from Hieronymous Zchold during his execution and fed to dogs; a small portion requested by a lady for her son's collection (158).","notesPages":[348],"id":"glossary-entry-intestines","letter":"I"},{"term":"Intolerable","definition":"Exclaimed by the Dolophonos about Lutin's prophetic defiance (87) and Riesin's interference (89).","notesPages":[348],"id":"glossary-entry-intolerable","letter":"I"},{"term":"Intramuros District (Manila)","definition":"The old walled city section of Manila, Philippines; cited as the starting location of a man who bi-located to San Francisco while daydreaming (95).","notesPages":[348],"id":"glossary-entry-intramuros-district-manila","letter":"I"},{"term":"Intrepid Nine","definition":"The remaining members of the experimental group (Lord Randal, Inneall, Marino, Henryetta, Lutin, Dubu, Schimp, Carcajou, Popugai) after Axel, Gajah, and Luas are lost; they paint the hull of the Annabella Saint Ledger with Invisible Paint (104).","notesPages":[348],"id":"glossary-entry-intrepid-nine","letter":"I"},{"term":"Intrepid Three","definition":"Initial designation for Lord Randal, Inneall, and Axel when they first ventured out of their contrived habitat into the Lynn- Randal house (9).","notesPages":[348],"id":"glossary-entry-intrepid-three","letter":"I"},{"term":"Intricate kindred (Computers)","definition":"The superior computers are scanned by their more mechanical and less intricate computer kindred (82).","notesPages":[349],"id":"glossary-entry-intricate-kindred-computers","letter":"I"},{"term":"Intricate language","definition":"A characteristic feature of Mankind upon its first appearance in the world (34).","notesPages":[349],"id":"glossary-entry-intricate-language","letter":"I"},{"term":"Introduction (of Lacrosse)","definition":"The novel’s invented history credits Saint Brandon with bringing Irish hurley to America in 536 and derives lacrosse from it (65). Historically, lacrosse developed among Indigenous North American peoples.","notesPages":[349],"id":"glossary-entry-introduction-of-lacrosse","letter":"I"},{"term":"Intuitions","definition":"Insights or understandings gained without conscious reasoning; Dubu claims to be overwhelmed by them after eating raw \"Filchman's Daughter\" fish (75).","notesPages":[349],"id":"glossary-entry-intuitions","letter":"I"},{"term":"Intuitive","definition":"Possessing or acting on intuition; The Three are described as very intuitive (5); Alpha has intuitive knowledge of places (21).","notesPages":[349],"id":"glossary-entry-intuitive","letter":"I"},{"term":"Intuitive evasive actions","definition":"Instinctive maneuvers the Nine plan to employ if necessary after entering the Cenaculum, anticipating potential counter-actions from the Kangaroo (145).","notesPages":[349],"id":"glossary-entry-intuitive-evasive-actions","letter":"I"},{"term":"Intuitive knowledge","definition":"Instinctive understanding; possessed by Alpha regarding places and their contents (21).","notesPages":[349],"id":"glossary-entry-intuitive-knowledge","letter":"I"},{"term":"Invaders","definition":"Hostile entrants; the Annabella Saint Ledger is equipped to repel and counter-attack invaders all the way to the ocean bottom (101); the Mughal conquerors of India, called “Moguls” in the novel’s account of the Empress Elephants (92).","notesPages":[349],"id":"glossary-entry-invaders","letter":"I"},{"term":"Inventive","definition":"Characteristic of Lutin the Pythoness (62).","notesPages":[349],"id":"glossary-entry-inventive","letter":"I"},{"term":"Inventiveness","definition":"Attribute of AMH intelligence (26); the sheer inventiveness of Ambulatory Computers drives the dramas in Structo Lane (76).","notesPages":[349],"id":"glossary-entry-inventiveness","letter":"I"},{"term":"Invisibility (Full)","definition":"Complete imperceptibility; never granted all at once (110).","notesPages":[350],"id":"glossary-entry-invisibility-full","letter":"I"},{"term":"Invisibility (Near-)","definition":"The state achieved by Invisible Alfred, derived from paint residue; described as a two-sided gift that enhances the user's perception of otherwise invisible things (like thoughts) (110).","notesPages":[350],"id":"glossary-entry-invisibility-near","letter":"I"},{"term":"Invisibility (Total)","definition":"The state in which the pirate crew must maintain the Annabella Saint Ledger (119).","notesPages":[350],"id":"glossary-entry-invisibility-total","letter":"I"},{"term":"Invisible Alfred","definition":"See Alfred, Invisible.","notesPages":[349],"id":"glossary-entry-invisible-alfred","letter":"I"},{"term":"Invisible government","definition":"The hidden, almost unnoticed power structure ruling the Floating World; identified as the Kangaroo (80).","notesPages":[349],"id":"glossary-entry-invisible-government","letter":"I"},{"term":"Invisible Paint","definition":"A substance stored in seven heavy, one-hundred- gallon drums which are actually empty (anomaly of gravity); when applied (only effectively in the dark), it renders objects approximately ninety-nine percent invisible; used by the Intrepid Nine to paint the Annabella Saint Ledger (97, 101, 104, 107, 108, 113, 115, 120). See also Paint (Invisible).","notesPages":[349,350],"id":"glossary-entry-invisible-paint","letter":"I"},{"term":"Invisible Ship","definition":"The Annabella Saint Ledger after being painted with Invisible Paint; still visible below the waterline to fish, trackable via Fish-Report; destined to become a ghost ship legend (101, 119, 120, 152, 161). See also Ship (Invisible).","notesPages":[350],"id":"glossary-entry-invisible-ship","letter":"I"},{"term":"Irascible computers","definition":"Ill-tempered or easily angered computers; suggested as one possible constituent element of the Dolophonoi- Assassins (82).","notesPages":[350],"id":"glossary-entry-irascible-computers","letter":"I"},{"term":"Ireland","definition":"Island nation; origin of the game hurley and Saint Brandon (65); home of the Royal House of Donegal, from which Donatus O'Reily claims descent (157).","notesPages":[350],"id":"glossary-entry-ireland","letter":"I"},{"term":"Iris","definition":"Mother of Lord Randal and wife of George Lynn-Randal; serves as one of the 'parents' sponsoring the Lynn-Randal experiment (1, 2, 84); expresses doubts about the Floating World and computer predictions (1); possesses an irritating grin (7); hunts Dolophonoi with Shadrack and Gregor out of fear for her 'children' (84-85); communicates distantly with Inneall (85); ultimately fails to use the Python-Gun due to weakness and fear (90). See also Lynn-Randal, Iris.","notesPages":[350],"id":"glossary-entry-iris","letter":"I"},{"term":"Iris Lynn-Randal","definition":"See Lynn-Randal, Iris.","notesPages":[350],"id":"glossary-entry-iris-lynn-randal","letter":"I"},{"term":"Irish Abbey Lane Plays","definition":"Dramatic works from the Irish theatrical tradition, cited as one source influencing Structo Lane dramas (76).","notesPages":[350],"id":"glossary-entry-irish-abbey-lane-plays","letter":"I"},{"term":"Irish Game Hurley","definition":"Irish hurling, made the ancestor of lacrosse in the novel’s invented Saint Brandon story (65); see Introduction (of Lacrosse).","notesPages":[350],"id":"glossary-entry-irish-game-hurley","letter":"I"},{"term":"Irish Monk Saint Brandon","definition":"The novel’s version of Saint Brendan the Navigator, credited within its fictional history with bringing hurley to America in 536 and with a unique nine- goal rating (65). These sporting claims are not established history; see Introduction (of Lacrosse).","notesPages":[351],"id":"glossary-entry-irish-monk-saint-brandon","letter":"I"},{"term":"Iron bars","definition":"Bent like weeds by Alpha's great strength (51); bent by Alpha himself to free his associates from zoos (21).","notesPages":[351],"id":"glossary-entry-iron-bars","letter":"I"},{"term":"Iron chains","definition":"Restraints used, along with iron collars, on the five hundred Axel's Apes captured from Second Eden (19).","notesPages":[351],"id":"glossary-entry-iron-chains","letter":"I"},{"term":"Iron collars","definition":"Metal neck restraints placed on the captured Axel's Apes; the Apes refurbished them at their forges before allowing the men to clamp them on (19).","notesPages":[351],"id":"glossary-entry-iron-collars","letter":"I"},{"term":"Iron-workers","definition":"Skilled metalworkers; classification applied to the Unfallen Ones, along with bronze-workers (15).","notesPages":[351],"id":"glossary-entry-iron-workers","letter":"I"},{"term":"Iron-zink-lead pipes","definition":"Conduits fabricated by the Axel's Apes themselves to tap the old natural gas wells in Ape Caverns (45).","notesPages":[351],"id":"glossary-entry-iron-zink-lead-pipes","letter":"I"},{"term":"Ironic","definition":"Sebastian Lazar's manner of crooking and arching his eyebrows (147); the situation where the super-intelligent guests fail to solve a murder mystery solved by Dubu the bear (157).","notesPages":[351],"id":"glossary-entry-ironic","letter":"I"},{"term":"Irony","definition":"Stated as being unrecognizable to the \"new people\" of the post- postliterate age (8).","notesPages":[351],"id":"glossary-entry-irony","letter":"I"},{"term":"Irrational man (Tom Dooley)","definition":"Description applied to Tom Dooley, former owner of Persimmon Manor, who died believing he was beset by ghosts and devils (124).","notesPages":[351],"id":"glossary-entry-irrational-man-tom-dooley","letter":"I"},{"term":"Island (Kure)","definition":"Location east of the International Dateline, site of James Mortimer's Gallows Guesthouse (118).","notesPages":[351],"id":"glossary-entry-island-kure","letter":"I"},{"term":"Island (Tom Dooley's)","definition":"Landform created when Inneall's Ocean surrounds Tom Dooley's Hill (100); site of Persimmon Manor (115); sinking rapidly (100, 116, 151, 159); provides location for Zchold's stoning (122); its remaining structure settles quaintly on Ocean Bottom (159).","notesPages":[351],"id":"glossary-entry-island-tom-dooleys","letter":"I"},{"term":"Island (Wollaston)","definition":"Location off Cape Horn, source of the late- crowing Drake Passage Cock (118).","notesPages":[351],"id":"glossary-entry-island-wollaston","letter":"I"},{"term":"Isthmus of a Middle State","definition":"Quotation from Alexander Pope's Essay on Man, describing Man's paradoxical position \"Placed on this isthmus of a middle state, / A being darkly wise and rudely great\" (34).","notesPages":[352],"id":"glossary-entry-isthmus-of-a-middle-state","letter":"I"},{"term":"Isthmus of the Middle State","definition":"Metaphorical location where Man is marooned, unable to occupy other parts of the world of his nativity (41).","notesPages":[352],"id":"glossary-entry-isthmus-of-the-middle-state","letter":"I"},{"term":"Italy","definition":"European country; source of stonemasters taught by the Unfallen People (13).","notesPages":[352],"id":"glossary-entry-italy","letter":"I"},{"term":"Itinerant workers","definition":"Migrant laborers, both skilled and unskilled, who arrive in the neighborhood and go \"unerringly\" to the Apes' Cavern as if they had been there before (some had) (45).","notesPages":[352],"id":"glossary-entry-itinerant-workers","letter":"I"},{"term":"Ivory-mouth","definition":"One of the three instruments named in the Lynn-Randal house, alongside git- fiddle and whango (8). Its construction and instrument family are not explained.","notesPages":[352],"id":"glossary-entry-ivory-mouth","letter":"I"},{"term":"Ivory (Walrus)","definition":"Material used by Computers for the art of scrimshaw carving (33).","notesPages":[352],"id":"glossary-entry-ivory-walrus","letter":"I"},{"term":"Jack","definition":"Cited by an AMH Computer as frequently used by humans in naming machines (e.g., jackscrew, jack plane, bootjack, jackknife, jackstay, jack light, jackstone), reflecting a perception of machines as \"jack-and-jenny asses\" (31).","notesPages":[352],"id":"glossary-entry-jack","letter":"J"},{"term":"Jack-and-jenny asses","definition":"Term used by an AMH Computer to characterize the human view of machines, leading to the application of asinine names to various devices (31).","notesPages":[353],"id":"glossary-entry-jack-and-jenny-asses","letter":"J"},{"term":"Jack Flannagan","definition":"Proprietor of the 24-hour \"Jack Flannagan's Piano Bar and Sidewalk Cafe\" at Oceanside (77, 151); appears human but never sleeps and is constantly running his establishment, suggesting he is likely an Ambulatory Miming-Human Computer highly skilled at mimicry; converses with Inneall, Carcajou, and Schimp during the ghost dawn of the Third Day of Summerset (151-152).","notesPages":[352],"id":"glossary-entry-jack-flannagan","letter":"J"},{"term":"Jack Flannagan's Piano Bar and Sidewalk Cafe","definition":"Establishment at Oceanside (formerly Heart's Desire Cove) visited by Inneall, Carcajou, and Schimp during the ghost dawn; scene of singing (\"All Day and All Night\") and conversation with the proprietor (77, 151).","notesPages":[352,353],"id":"glossary-entry-jack-flannagans-piano-bar-and-sidewalk-cafe","letter":"J"},{"term":"Jack light","definition":"Cited by an AMH Computer as an example of a machine given an asinine name (\"jack\") by humans (31).","notesPages":[353],"id":"glossary-entry-jack-light","letter":"J"},{"term":"Jack plane","definition":"Cited by an AMH Computer as an example of a machine given an asinine name (\"jack\") by humans (31).","notesPages":[353],"id":"glossary-entry-jack-plane","letter":"J"},{"term":"Jackdaw level","definition":"A derogatory term signifying a very low standard of quality, specifically associated with the output of the Jackdaw Two- and-Three Track Press (9).","notesPages":[353],"id":"glossary-entry-jackdaw-level","letter":"J"},{"term":"Jackdaw Two-and-Three Track Press","definition":"Producer of low-quality media formats ('prowls', 'antics', etc.) such as the \"Bongo and his Beepers\", \"Cut-Throats of Coke-Town\", and \"Fast- Action Eadie and Eddie\" series; characterized by \"shovelings of noise and motion and color\" that produce \"gnawing and garish blue moods\" (8).","notesPages":[353],"id":"glossary-entry-jackdaw-two-and-three-track-press","letter":"J"},{"term":"Jackknife","definition":"Cited by an AMH Computer as an example of a machine given an asinine name (\"jack\") by humans (31).","notesPages":[353],"id":"glossary-entry-jackknife","letter":"J"},{"term":"Jackscrew","definition":"Cited by an AMH Computer as an example of a machine given an asinine name (\"jack\") by humans (31).","notesPages":[353],"id":"glossary-entry-jackscrew","letter":"J"},{"term":"Jackstay","definition":"Nautical device cited by an AMH Computer as an example of a machine given an asinine name (\"jack\") by humans (31).","notesPages":[353],"id":"glossary-entry-jackstay","letter":"J"},{"term":"Jackstone","definition":"Cited by an AMH Computer as an example of an object given an asinine name (\"jack\") by humans (31).","notesPages":[353],"id":"glossary-entry-jackstone","letter":"J"},{"term":"Jacquard","definition":"Joseph-Marie Jacquard, whose punched-card loom mechanism was demonstrated in 1801. The novel’s “mid 1800’s” dating (25) is inaccurate.","notesPages":[353],"id":"glossary-entry-jacquard","letter":"J"},{"term":"James Mortimer's Gallows Guesthouse","definition":"Formerly James Mortimer's Gracious Guesthouse, a location on Kure Island (east of the International Dateline) where members of the Natural Nobility who have committed hangable misdemeanors go with their seconds for executions under a custom only a month or so old (118).","notesPages":[353,354],"id":"glossary-entry-james-mortimers-gallows-guesthouse","letter":"J"},{"term":"James Mortimer's Gracious Guesthouse","definition":"The original name of the establishment on Kure Island later known as James Mortimer's Gallows Guesthouse (118).","notesPages":[354],"id":"glossary-entry-james-mortimers-gracious-guesthouse","letter":"J"},{"term":"Jamestown Wixon","definition":"See Wixon, Jamestown.","notesPages":[354],"id":"glossary-entry-jamestown-wixon","letter":"J"},{"term":"\"Japanese Noh Drama\"","definition":"Traditional Japanese theatrical form cited as one of the human sources influencing the dramas performed in Structo Lane (76).","notesPages":[354],"id":"glossary-entry-japanese-noh-drama","letter":"J"},{"term":"Japanese (Phrase 'Floating World')","definition":"The Japanese usage of \"The Floating World\" means the \"Bohemian World\", \"Arty World\", or \"Unmoored World\", distinct from the later global condition of unmoored nations (79).","notesPages":[354],"id":"glossary-entry-japanese-phrase-floating-world","letter":"J"},{"term":"Jarring waves","definition":"Turbulent, discordant waves generated by certain \"high-headed and divergent excellence,\" considered dangerous to the stability of the Floating World (81).","notesPages":[354],"id":"glossary-entry-jarring-waves","letter":"J"},{"term":"Jasher (Book of)","definition":"See Book of Jasher.","notesPages":[354],"id":"glossary-entry-jasher-book-of","letter":"J"},{"term":"Jasper Jones","definition":"See Jones, Jasper.","notesPages":[354],"id":"glossary-entry-jasper-jones","letter":"J"},{"term":"Jasper Junkins","definition":"See Junkins, Jasper.","notesPages":[354],"id":"glossary-entry-jasper-junkins","letter":"J"},{"term":"Jaunts","definition":"One of the alternative names ('antics', 'romps', 'trips', 'experiences', 'prowls') for the stylized, sketchy, multi-track media format popular in the Floating World (6).","notesPages":[354],"id":"glossary-entry-jaunts","letter":"J"},{"term":"Jaw (Apeish)","definition":"Facial feature of Axel the Ape, described along with his gargoyle face and wide splay feet as being composed entirely of \"flab- flesh\" with no corresponding skeletal structure (42).","notesPages":[354],"id":"glossary-entry-jaw-apeish","letter":"J"},{"term":"Jazz (Gajah playing drum)","definition":"The unborn elephant Gajah demonstrated musical skill by playing jazz and ragtime rhythms on the small communication drum placed in her mother's womb, surpassing Inneall's ability on a larger drum (56).","notesPages":[354],"id":"glossary-entry-jazz-gajah-playing-drum","letter":"J"},{"term":"Jealousies","definition":"Inneall possesses this emotion, unlike machines (51).","notesPages":[354],"id":"glossary-entry-jealousies","letter":"J"},{"term":"Jealousy","definition":"Felt by Inneall regarding the little Ape girls and Axel; also, an emotion Alpha either felt or pretended to feel concerning Satrap Saint Ledger's adoption of Inneall (51).","notesPages":[355],"id":"glossary-entry-jealousy","letter":"J"},{"term":"Jenny (ass)","definition":"Cited by an AMH Computer as used in machine names (spinning jenny, burglar's jenny), reflecting human perception of machines and noting the jenny ass was more used on treadmills than the jack (31).","notesPages":[355],"id":"glossary-entry-jenny-ass","letter":"J"},{"term":"Jest (\"The Glory, Jest, and Riddle of the World\")","definition":"Quoted phrase from Alexander Pope's Essay on Man, part of a larger description of the paradoxical nature of humanity (34).","notesPages":[355],"id":"glossary-entry-jest-the-glory-jest-and-riddle-of-the-world","letter":"J"},{"term":"Jet (Gas)","definition":"The main jet from the old well in Apes' Caverns was ignited nightly by lightning to provide the \"holy blaze\" (68).","notesPages":[355],"id":"glossary-entry-jet-gas","letter":"J"},{"term":"Jets (Air)","definition":"Employed by an elegant AMH Computer, apparently emerging from its thorax, to shape smoke rings into squares, considered a form of cheating (30).","notesPages":[355],"id":"glossary-entry-jets-air","letter":"J"},{"term":"Jewish Historian Josephus","definition":"See Josephus.","notesPages":[355],"id":"glossary-entry-jewish-historian-josephus","letter":"J"},{"term":"Jimmy (Burglar's)","definition":"An AMH Computer asserts its original name was the \"burglar's jenny\" (31).","notesPages":[355],"id":"glossary-entry-jimmy-burglars","letter":"J"},{"term":"Jog in the road","definition":"A physical irregularity or sharp turn in a roadway which, when encountered during a state of deep daydream or altered consciousness (\"jog in the undermind\"), can trigger instantaneous bi- location or trans-location between geographically distant but mentally connected roads (e.g., midland America to India) (93, 95).","notesPages":[355],"id":"glossary-entry-jog-in-the-road","letter":"J"},{"term":"Jog in the undermind","definition":"The necessary mental shift, rapturous daydream, or altered state of consciousness required for bi-location to occur, corresponding physically to encountering a \"jog in the road\" (95).","notesPages":[355],"id":"glossary-entry-jog-in-the-undermind","letter":"J"},{"term":"Joke (Biggest Joke Ever)","definition":"Description allegedly given by transparent odd fellows to Dubu regarding the paradoxical event (implied creation of the Big Egg) by which the World would be \"saved and transformed\" (155).","notesPages":[355],"id":"glossary-entry-joke-biggest-joke-ever","letter":"J"},{"term":"Joke (on God/ourselves)","definition":"Ansel Grindstone's rhetorical question challenging conventional aesthetics: is the \"joke\" on God for creating the Unfallen/Gargoyles with their terrifying beauty, or on humans for preferring their own \"fallen and crest-fallen faces\"? (17).","notesPages":[355,356],"id":"glossary-entry-joke-on-god-ourselves","letter":"J"},{"term":"Jokers","definition":"Blamed by Lanternjaw Lunnigan for releasing honey bees into the midship hold of the Annabella Saint Ledger (100).","notesPages":[356],"id":"glossary-entry-jokers","letter":"J"},{"term":"Jolly Roger (Boat)","definition":"One of two \"Fast and Scampering Boats\" provided by Satrap Saint Ledger for the Eleven's use at Heart's Desire Cove; technically considered a Ship Boat of Inneall's flagship, the Annabella Saint Ledger (58).","notesPages":[356],"id":"glossary-entry-jolly-roger-boat","letter":"J"},{"term":"Jonah","definition":"Hebrew prophet from the Bible; Invisible Alfred explicitly compares his own experience of becoming colorless after three days inside a whale to Jonah's time in the whale's belly (109).","notesPages":[356],"id":"glossary-entry-jonah","letter":"J"},{"term":"Jones, Jasper","definition":"The original name of the pirate seaman serving aboard the Annabella Saint Ledger, before Henryetta gave him the contrived \"pirate name\" Quentillius Quern the Fifth (98).","notesPages":[356],"id":"glossary-entry-jones-jasper","letter":"J"},{"term":"Josephus","definition":"Flavius Josephus, to whom Ansel Grindstone attributes his description of immense archangelic faces (17). The notes have not established a corresponding passage in Josephus; retain this as Ansel’s attribution.","notesPages":[356],"id":"glossary-entry-josephus","letter":"J"},{"term":"Journals","definition":"Along with log-books and histories, the function of writing them was taken from humans due to dishonesty, given to computers, and then taken from computers (also due to dishonesty) and given to the Whales (164).","notesPages":[356],"id":"glossary-entry-journals","letter":"J"},{"term":"Journey (Axel's)","definition":"The quest undertaken by Axel Albert Grindstone to find the location of the Second Eden and the Unfallen People (12).","notesPages":[356],"id":"glossary-entry-journey-axels","letter":"J"},{"term":"Joy","definition":"One of the \"all immediacies\" included in Felix Culebra y Columba's \"Life Affair\" weaving (74); felt by sister Clotho upon seeing the baby pythons fostered by the Fates (160).","notesPages":[356],"id":"glossary-entry-joy","letter":"J"},{"term":"Judas Tree","definition":"The novel calls Gregor McGregor’s carob a “Judas Tree” (91). Botanical usage normally distinguishes the carob, Ceratonia siliqua, from the Judas tree, Cercis siliquastrum.","notesPages":[356],"id":"glossary-entry-judas-tree","letter":"J"},{"term":"Judgement (Dolophonos employment)","definition":"Humans are said to lose all capacity for sound judgement when they employ assassins of any species (39).","notesPages":[356],"id":"glossary-entry-judgement-dolophonos-employment","letter":"J"},{"term":"Judgement (of the Kangaroo)","definition":"The assessment process undertaken by the Kangaroo (via its scanners and instruments) to determine if individuals, particularly mega-persons nearing maturity (age ten), should be classified as \"Serpent's Eggs\" and subsequently eliminated; the Royal Kids face this judgement at midnight (142).","notesPages":[357],"id":"glossary-entry-judgement-of-the-kangaroo","letter":"J"},{"term":"Julius Caesar (Shakespeare quote)","definition":"William Shakespeare's play Julius Caesar is the source of the epigraph for Chapter One: \"Therefore think of him as a serpent's egg... And kill him in the shell\" (1).","notesPages":[357],"id":"glossary-entry-julius-caesar-shakespeare-quote","letter":"J"},{"term":"Jungle-Boy Type (Tarzan)","definition":"Character archetype applied to Ruddy Lord Randal, suggesting qualities of physical prowess (better climber than ape boys), fearlessness, strength, decisiveness, loyalty, and good nature, derived from the old Tarzan book-movie comic-strip character researched by Inneall (123).","notesPages":[357],"id":"glossary-entry-jungle-boy-type-tarzan","letter":"J"},{"term":"Jungle ('jungle' Dolophonos lurking)","definition":"Term used metaphorically by George Lynn-Randal to describe the environment where a Dolophonos assigned to monitor the Lynn-Randal experiment was seen \"lurking\" (2).","notesPages":[357],"id":"glossary-entry-jungle-jungle-dolophonos-lurking","letter":"J"},{"term":"Junkins, Jasper","definition":"Pseudonym of a \"great contemporary philosopher\" known for the statement: \"We are all sub-teenagers now\" (8).","notesPages":[357],"id":"glossary-entry-junkins-jasper","letter":"J"},{"term":"Jupiter","definition":"Gas giant invoked in the novel as a possible home for Computers, with a “killingly cold surface” (60). Jupiter has no solid surface in the terrestrial sense.","notesPages":[357],"id":"glossary-entry-jupiter","letter":"J"},{"term":"Justice (Principles disregarded)","definition":"A defining characteristic of a \"Kangaroo court,\" where the fundamental principles of law and justice are ignored or perverted (79).","notesPages":[357],"id":"glossary-entry-justice-principles-disregarded","letter":"J"},{"term":"Juxtapositions","definition":"Unlikely combinations and juxtapositions in experiments are cited as potential sources of \"wild and extreme talents\" (\"Serpent's Eggs\") or \"disasters\" that need to be anticipated and forestalled (82).","notesPages":[357],"id":"glossary-entry-juxtapositions","letter":"J"},{"term":"Kangaroo","definition":"The quasi-governmental, almost-invisible power structure that secretly rules the Floating World (80). Operating through rumour (1), advanced scanning technology (82, 84), and enforcers like the Dolophonoi-Assassins (84), it monitors the global population (82), identifies and eliminates perceived threats (\"Serpent's Eggs,\" unruly \"mega-persons\") (1, 82, 84, 142), and maintains stability, partly through engineered \"levelling\" of both the lowest and highest societal strata (81). It is an interspecies organization (Human, Computer, Animal) lacking formal structure (80, 83), operating primarily on the unconscious level of its members (83) and utilizing narrow, sharp communication frequencies allegedly unmonitored by the Mind of God (80). Its current Supreme Head is revealed to be Invisible Alfred (145, 149). The Kangaroo constellation is dismissed as an optical illusion (166).","notesPages":[358],"id":"glossary-entry-kangaroo","letter":"K"},{"term":"Kangaroo court","definition":"Defined in Webster's Collegiate as an irresponsible, unauthorized, or irregular tribunal disregarding principles of law and justice; the definition is applied to the Kangaroo organization itself (79).","notesPages":[358],"id":"glossary-entry-kangaroo-court","letter":"K"},{"term":"Kangaroo (Courts Irregular)","definition":"Phrase from a Structo Alley Music-Hall song, characterizing the Kangaroo's unorthodox and potentially unjust operational methods (78).","notesPages":[358],"id":"glossary-entry-kangaroo-courts-irregular","letter":"K"},{"term":"Kangaroo (Head of)","definition":"The supreme leadership role within the Kangaroo organization, held successively by Imperial Heads who burn out after their missions (83). The current Supreme Head during the narrative's climax is revealed, via kangaroo knuckle-bone, to be the Prophet Invisible Alfred (145, 146, 149, 150).","notesPages":[358],"id":"glossary-entry-kangaroo-head-of","letter":"K"},{"term":"Kangaroo kick","definition":"A presumably violent and significant event anticipated as a result of the appearance of the Kangaroo constellation in the sky (77).","notesPages":[358],"id":"glossary-entry-kangaroo-kick","letter":"K"},{"term":"Kangaroo knuckle-bone","definition":"An artifact used by the Kangaroo to convey authentic information. One such bone, stolen and sold to Lord Randal for thirty ounces of gold, reveals that Invisible Alfred is the current Supreme Head of the Kangaroo (145, 146). Henryetta retrieves it from Randal's body after his death (149).","notesPages":[358],"id":"glossary-entry-kangaroo-knuckle-bone","letter":"K"},{"term":"Kanguruus the Kangaroo","definition":"The \"true sign\" of the constellation Virgo, revealed by Invisible Alfred as hidden behind the conventional stellar mask (111); appears as a hypnotically-seen, possibly subjective image visible only to those it threatens (76-77). Ultimately dismissed by the Sea Louse epilogue as an optical illusion (166).","notesPages":[358,359],"id":"glossary-entry-kanguruus-the-kangaroo","letter":"K"},{"term":"Kea","definition":"The species of large, strong, sheep-killing parrot native to New Zealand, also known as the Nestor Parrot (Nestor notabilis), to which Popugai belongs (64).","notesPages":[359],"id":"glossary-entry-kea","letter":"K"},{"term":"Kersten Wintergreen-Luna","definition":"See Wintergreen-Luna, Kersten.","notesPages":[359],"id":"glossary-entry-kersten-wintergreen-luna","letter":"K"},{"term":"Key-locked","definition":"A construction method using precisely cut stones that interlock securely without mortar; employed by the Unfallen Ones to build their graceful stone bridge (15).","notesPages":[359],"id":"glossary-entry-key-locked","letter":"K"},{"term":"Key (to Cenaculum)","definition":"A large key in the brass door set into the limestone wall at the end of the Executive Passage, intended to be turned to detonate a final blast creating an entrance into the Cenaculum of the Sleepers (144). Mysteriously, the key turns itself just before Lord Randal reaches it (147).","notesPages":[359],"id":"glossary-entry-key-to-cenaculum","letter":"K"},{"term":"Killer Whales","definition":"The common name for the whale species Orcinus orca; the text notes the irony of this name for the \"small and gentle\" whale Miol-Mor, who serves as nurse and mentor to the Big Egg (160).","notesPages":[359],"id":"glossary-entry-killer-whales","letter":"K"},{"term":"Killers (Hot-Breathed)","definition":"Rose-of-Sharon Montdrago's term for the Dolophonoi-Assassins who pursued her when she was wrongly classified as a \"Serpent's Egg\" (117).","notesPages":[359],"id":"glossary-entry-killers-hot-breathed","letter":"K"},{"term":"Killers (who wielded knives)","definition":"Refers to the Dolophonoi or Assassins, whose true nature (leucotomized humans, irascible computers, or aberrant animals) is kept secret by their employers (82).","notesPages":[359],"id":"glossary-entry-killers-who-wielded-knives","letter":"K"},{"term":"Killing (Sleep-Walking)","definition":"A murder technique involving directed somnambulistic activity, practiced by the Dolophonoi-Assassins (98). Their induced sleep-walking state, however, offered no protection against the Cenaculum's Deep Sleep (147, 149).","notesPages":[359],"id":"glossary-entry-killing-sleep-walking","letter":"K"},{"term":"Kindnesses (Little)","definition":"Performed by the Unfallen People for fallen mankind when they emerge from Second Eden (12).","notesPages":[361],"id":"glossary-entry-kindnesses-little","letter":"K"},{"term":"Kindred (Computer)","definition":"The less complex, more mechanical computers responsible for scanning their more sophisticated counterparts (82).","notesPages":[360],"id":"glossary-entry-kindred-computer","letter":"K"},{"term":"Kindred machines","definition":"Entities similar to Ambulatory Computers, mentioned in the title of a book by Inneall's designated father (52).","notesPages":[360],"id":"glossary-entry-kindred-machines","letter":"K"},{"term":"King-and-Emperor (Prester John)","definition":"The formal title of Prester John, the extremely long- lived and sleepy ruler of the Unfallen People in Second Eden (12).","notesPages":[360],"id":"glossary-entry-king-and-emperor-prester-john","letter":"K"},{"term":"King (Axel's Ape Alpha)","definition":"Title held by the elderly male ape Alpha, acknowledging his status as patriarch and prophet within the Apes' Caverns community (51).","notesPages":[359],"id":"glossary-entry-king-axels-ape-alpha","letter":"K"},{"term":"King of Foods (Hot Dog)","definition":"Title bestowed upon the hot dog after its merits were \"discovered and verified,\" celebrated at Hot Dog Row (58).","notesPages":[360],"id":"glossary-entry-king-of-foods-hot-dog","letter":"K"},{"term":"King of the Cove (Marino)","definition":"Title assumed by Marino the Seal, reflecting his dominance and activity in the waters of Heart's Desire Cove (56).","notesPages":[360],"id":"glossary-entry-king-of-the-cove-marino","letter":"K"},{"term":"King (of Whales)","definition":"Speculative meaning offered for 'Suryavarman', the name of the presumed builder of the Temple of Angkor Wat (132).","notesPages":[359],"id":"glossary-entry-king-of-whales","letter":"K"},{"term":"Kingdom","definition":"Specifically, the promise quoted from scripture: \"Fear not, little flock, for it has pleased your Father to give you a Kingdom\" (36).","notesPages":[360],"id":"glossary-entry-kingdom","letter":"K"},{"term":"Kingdom Come","definition":"Whales are said to build Palaces there in \"The Child's Big Book of Whales\" (105).","notesPages":[360],"id":"glossary-entry-kingdom-come","letter":"K"},{"term":"Kingdoms","definition":"Axel worries about the reaction of the metaphorical \"Kings of those Kingdoms\" (representing the power of The Three) when they feel threatened (2).","notesPages":[360],"id":"glossary-entry-kingdoms","letter":"K"},{"term":"Kings (Axel worried about)","definition":"The metaphorical rulers Axel fears will react negatively when threatened by the power generated by The Three (2).","notesPages":[360],"id":"glossary-entry-kings-axel-worried-about","letter":"K"},{"term":"Kings (David and Solomon)","definition":"Biblical rulers of ancient Israel, believed by Axel Grindstone to be sleeping yet alive in Abraham's Bosom (11).","notesPages":[360],"id":"glossary-entry-kings-david-and-solomon","letter":"K"},{"term":"Kings (on playing cards)","definition":"Used in an analogy: their connection to real kings is as tenuous as the connection between astrological planets and actual celestial bodies (30).","notesPages":[360],"id":"glossary-entry-kings-on-playing-cards","letter":"K"},{"term":"Kings (Real)","definition":"Actual monarchs, whose continued existence somewhere in the world is deemed uncertain but possible (30).","notesPages":[360],"id":"glossary-entry-kings-real","letter":"K"},{"term":"Knife","definition":"Associated with the Dolophonoi (100, 134, 139); one kills Axel and Lord Randal, seemingly moving by itself (148); the dangling knife reappears, kills Henryetta, and remains in her throat (149-150).","notesPages":[361],"id":"glossary-entry-knife","letter":"K"},{"term":"Knife (\"One Man, One Knife\")","definition":"Phrase from Arpad Arutinov symbolizing the ultimate reduction of warfare to its essential elements (79).","notesPages":[361],"id":"glossary-entry-knife-one-man-one-knife","letter":"K"},{"term":"Knives (Dolophonoi)","definition":"Wielded by the Assassins (82, 83); taken from dead Dolophonoi by Quentillius (100); used against Axel and Randal (148); one used against Henryetta (149).","notesPages":[361],"id":"glossary-entry-knives-dolophonoi","letter":"K"},{"term":"Knives (Royal Kids')","definition":"Dolophonoi knives acquired by Randal, Carcajou, and Schimp (100); used by Randal against the animated knife (148); potentially used against wolverenes (102).","notesPages":[361],"id":"glossary-entry-knives-royal-kids","letter":"K"},{"term":"Knowledge (Total)","definition":"Dubu claims bears can access it through their four brain lobes (75) and that it can be read from turtles' tongues (75).","notesPages":[361],"id":"glossary-entry-knowledge-total","letter":"K"},{"term":"Kure Island","definition":"Kure Atoll, east of the International Date Line; in the novel it houses James Mortimer’s Gallows Guesthouse and has what the narrator calls the world’s latest official cockcrow (118).","notesPages":[361],"id":"glossary-entry-kure-island","letter":"K"},{"term":"Lachesis","definition":"One of the Three Fates, the \"measuring sister,\" encountered by Inneall first in a hidden room aboard the Annabella Saint Ledger (114) and later in Persimmon Manor (126). She measures the life threads spun by Clotho before Atropos cuts them (103). Expresses concern about the Fates' public image after they become foster mothers to three baby pythons (160). Put into a deep sleep by Dubu (127).","notesPages":[361],"id":"glossary-entry-lachesis","letter":"L"},{"term":"Lack (of Substance/Meat in Mankind)","definition":"A perceived fundamental deficiency in the subject of Mankind, asserted by a highly intelligent AMH Computer specializing in the study. It claims some subjects simply lack inherent substance, making definitive analysis impossible (38).","notesPages":[361,362],"id":"glossary-entry-lack-of-substance-meat-in-mankind","letter":"L"},{"term":"Lacrosse","definition":"A game played by the Twelve, with Gajah especially effective through Riesin (65). The narrator invents an Irish ancestry and an aristocratic social history for it; actual lacrosse has Indigenous North American origins. See Introduction (of Lacrosse). Taken up enthusiastically by the Twelve Great Contemporaries during the final End-of-Summer Days. Gajah (directing Riesin) is the best player, Popugai is hard to defend in the air, and Carcajou is hard to defend when digging underground with the ball (65). See also Game of Lacrosse.","notesPages":[362],"id":"glossary-entry-lacrosse","letter":"L"},{"term":"Lacunated forms (Languages)","definition":"Describes the present sketchy state of human languages, contrasted with their \"amazing structured complexity\" further back in time (37).","notesPages":[362],"id":"glossary-entry-lacunated-forms-languages","letter":"L"},{"term":"Lady Anastasia Blickworthy","definition":"See Blickworthy, Anastasia (Lady).","notesPages":[362],"id":"glossary-entry-lady-anastasia-blickworthy","letter":"L"},{"term":"Lakes (in Caverns)","definition":"Small to medium-sized seasonal lakes located in the Green Country Valley that forms the roof over parts of the Ape Caverns (45).","notesPages":[362],"id":"glossary-entry-lakes-in-caverns","letter":"L"},{"term":"Land-Bridge (Ape Bridge)","definition":"A bridge, sometimes reappearing miraculously, connecting the Horn of Africa and Arabia, supposedly used by the Unfallen People, Moses, and Gypsies (12-13). See also Ape Bridge.","notesPages":[362],"id":"glossary-entry-land-bridge-ape-bridge","letter":"L"},{"term":"Land (Contrived Feral)","definition":"The two-hectare (five-acre) artificial habitat where The Three lived together from the age of one week, populated with experimental plants, insects, and animals (3).","notesPages":[362],"id":"glossary-entry-land-contrived-feral","letter":"L"},{"term":"Land's End","definition":"Geographical location in Cornwall, England; the great underwater City of Lyonesse is located off Land's End in Brittany, France (Note: geographic confusion in original text is preserved) (105).","notesPages":[362],"id":"glossary-entry-lands-end","letter":"L"},{"term":"Language (Drum)","definition":"Method of communication set up by Inneall to interact with the unborn elephant Gajah inside Riesin's womb, involving a small intruded drum (56).","notesPages":[362],"id":"glossary-entry-language-drum","letter":"L"},{"term":"Language (Thump)","definition":"A communication method using pressure and percussion rather than sound, devised by Riesin (the Giantess) to speak to her unborn baby elephant Gajah (56).","notesPages":[362],"id":"glossary-entry-language-thump","letter":"L"},{"term":"Languages","definition":"The narrator says Mankind appeared with an intricate language (34); the anonymous AMH theorist claims languages have declined from great complexity (e.g., thirty tenses, thirteen moods, eleven numbers) to sketchy forms (37). These are claims within the novel, not established linguistic history; part of Human Culture (39); Popugai knows the basic vocabularies of 600 human languages and thousands of non-human ones (64). See also Insect languages.","notesPages":[363],"id":"glossary-entry-languages","letter":"L"},{"term":"Languages (Oriental)","definition":"Studied by Axel Grindstone (Old Chaldee, Arabic, Swahili, Amharic, Ghees) in preparation for his quest to find the Other Eden (11).","notesPages":[363],"id":"glossary-entry-languages-oriental","letter":"L"},{"term":"Lantern fishes","definition":"Bioluminescent deep-sea fish that gather in files to light the way for Inneall and her companions on the Ocean Bottom after the murders (148); continue to provide light as Carcajou and Schimp place Henryetta in her cenotaph (150).","notesPages":[363],"id":"glossary-entry-lantern-fishes","letter":"L"},{"term":"Lanternjaw Lunnigan","definition":"Experienced pirate crewman aboard the Annabella Saint Ledger, descended from a long line of English pirates including Hosea Lanternjaw and Gammon Lanternjaw (98). Serves as spokesman for the crew (119, 142); designated Captain of the ship \"forever\" by the Royal Kids (119); initially expresses dismay about the pirates' future prospects but is convinced by Inneall of the potential for a great legend (119-121); remains loyal in the crows-nest (142, 145, 152). See also Lunnigan, Lanternjaw.","notesPages":[363],"id":"glossary-entry-lanternjaw-lunnigan","letter":"L"},{"term":"Last Blast","definition":"The final explosion intended to breach the limestone wall and grant access to the Cenaculum of the Sleepers, triggered by turning a large key in a brass door; occurs prematurely when the key turns itself (144, 147).","notesPages":[363],"id":"glossary-entry-last-blast","letter":"L"},{"term":"Last Day","definition":"The final day of existence, until which Prester John is destined to live on Earth unless called earlier by God (12).","notesPages":[363],"id":"glossary-entry-last-day","letter":"L"},{"term":"Last Days (of Summerset)","definition":"The concluding period of the End of Summer, marked by significant events including the merging of the Experiments, the Elephant Graveyard journey, and the final confrontations (93, 95). See also Three Days of Summerset.","notesPages":[363],"id":"glossary-entry-last-days-of-summerset","letter":"L"},{"term":"Last Refuge of Cranky Bachelors","definition":"One of the descriptive titles given to the luxurious underground enclave of Structo Lane, where eccentric single males (both human and AMH) congregated after being marginalized by the Levellers (69).","notesPages":[363],"id":"glossary-entry-last-refuge-of-cranky-bachelors","letter":"L"},{"term":"Last Three Days (of Summer)","definition":"The final 72-hour period of Summer, called the Three Days of Summerset; begins with the First Evening when Ape Caverns are sealed (67). See also Three Days of Summerset.","notesPages":[364],"id":"glossary-entry-last-three-days-of-summer","letter":"L"},{"term":"Last Week of Summer","definition":"The period when talking animals became widespread, amazing people momentarily before the novelty faded (54).","notesPages":[364],"id":"glossary-entry-last-week-of-summer","letter":"L"},{"term":"Lathe","definition":"Used by the Theos in a creation legend to make all creatures, including six deactivated \"Almost Perfect Creatures\" and the seventh flawed but undeactivated creature, Mankind (36-37).","notesPages":[364],"id":"glossary-entry-lathe","letter":"L"},{"term":"Latta, Roy","definition":"Reporter who interviews the Royal Kids after Invisible Alfred's discredited sermon, questioning the association's impact on their \"movement\" (113).","notesPages":[364],"id":"glossary-entry-latta-roy","letter":"L"},{"term":"Lavender-purple triangle","definition":"Inneall's signature color and geometric shape identified within the visual track of media 'prowls' (6).","notesPages":[364],"id":"glossary-entry-lavender-purple-triangle","letter":"L"},{"term":"Law (International)","definition":"See International Law.","notesPages":[364],"id":"glossary-entry-law-international","letter":"L"},{"term":"Laws (Abstract)","definition":"Part of the \"mere impersonal mechanism\" constituting the State, along with concrete power (78).","notesPages":[364],"id":"glossary-entry-laws-abstract","letter":"L"},{"term":"Lazar, Sebastian","definition":"Pirate seaman aboard the Annabella Saint Ledger; his name was contrived and given to him by Inneall (original name Hector Brown) (98). Lanternjaw, rather than Sebastian, accompanies the Nine on their first arrival at Persimmon Manor (115); Sebastian later appears there (153); predicts Tom Dooley's Island will sink (100); goes with Carcajou, Schimp, Marino and Popugai to visit the two men due to die (154); brings the Midnight Cock from the Cenaculum and is later seen leaving the priest’s hole with it still under his arm (153, 156); intends to continue Zchold’s work after the priest’s impending death (156, 162); unhoods the cock, awakening nine dead men while the already-wakeful Donatus is roused from melancholy (156-157); described by Lord Randal as the only “really superior pirate left” available to accompany them after Quentillius’s death, with Lanternjaw staying in the crow’s-nest (145).","notesPages":[364],"id":"glossary-entry-lazar-sebastian","letter":"L"},{"term":"Lead-bars","definition":"Heavy bars of lead distributed throughout Persimmon Manor (five hundred tons total) to keep the house anchored to the sinking island and prevent it from floating away (116); suggested by Donatus O'Reily as material to cover the body of the stoned priest Zchold (122).","notesPages":[364],"id":"glossary-entry-lead-bars","letter":"L"},{"term":"Leaders Asleep","definition":"Term used by Sebastian Lazar to refer to Axel, Lord Randal, and Henryetta in their potential state of undead coma within their cenotaphs (161). See also Leaders in Stasis.","notesPages":[364],"id":"glossary-entry-leaders-asleep","letter":"L"},{"term":"Leaders in Stasis","definition":"Alternative term for \"Leaders Asleep\" (161). See also Leaders Asleep.","notesPages":[365],"id":"glossary-entry-leaders-in-stasis","letter":"L"},{"term":"Leading actors","definition":"The primary performers in the dramas staged in Structo Lane; always Ambulatory Computers, though humans were used in minor roles (76).","notesPages":[365],"id":"glossary-entry-leading-actors","letter":"L"},{"term":"Leap (Sudden change in humans)","definition":"The hypothesized mode by which Mankind might eventually change, occurring in sudden leaps because all other roads to change have been foreclosed (40).","notesPages":[365],"id":"glossary-entry-leap-sudden-change-in-humans","letter":"L"},{"term":"Least-common-denominator smells","definition":"Mundane, unchallenging odors characteristic of the Lynn-Randal house, those \"which never went beyond the scope of the unlearned human nose\" (8).","notesPages":[365],"id":"glossary-entry-least-common-denominator-smells","letter":"L"},{"term":"Legend (Folk, about Deep Ocean Denizens)","definition":"A popular story asserting that the seven richest men in the world are metamorphic creatures who meet annually as Deep Ocean Denizens at a coral table two miles deep in the Atlantic to decide global financial processes (135).","notesPages":[365],"id":"glossary-entry-legend-folk-about-deep-ocean-denizens","letter":"L"},{"term":"\"Legend of Good Women\"","definition":"Literary work (by Chaucer) alluded to, likely referencing themes of female virtue or suffering (35).","notesPages":[365],"id":"glossary-entry-legend-of-good-women","letter":"L"},{"term":"Legend (Pirate)","definition":"A narrative celebrating exploits; Inneall assures Lanternjaw Lunnigan that the crew of the invisible Annabella Saint Ledger can become the greatest pirate legend ever, surpassing even the Flying Dutchman (120-121).","notesPages":[365],"id":"glossary-entry-legend-pirate","letter":"L"},{"term":"Legends (Authentic Legends of the Computers...)","definition":"See Authentic Legends of the Computers and Other Mechanisms, The.","notesPages":[365],"id":"glossary-entry-legends-authentic-legends-of-the-computers","letter":"L"},{"term":"Legends (Cathedral Legend)","definition":"A cluster of stories stating that the Unfallen People built the Cathedrals of Europe, leaving Gargoyles as signs, or alternatively, that European master masons learned stonework in Second Eden (13).","notesPages":[365],"id":"glossary-entry-legends-cathedral-legend","letter":"L"},{"term":"Legends (Elephant)","definition":"Beliefs concerning elephants, particularly the \"Wonder of the World Elephants\" with ten-year gestations; considered \"silly human folk lore\" generally, but true in this very special case (57). Humans generally didn't believe all the elephant legends (57). Legends (Medieval Aeneas) Ancient European tales mentioned by Lutin as featuring the \"Midnight Cock\" associated with awakening (143).","notesPages":[365,366],"id":"glossary-entry-legends-elephant","letter":"L"},{"term":"Legends (Romany/Gypsy)","definition":"A cluster of stories concerning the Gypsies' origins, their crossing of the Ape Bridge, learning trades from the Unfallen People, and being led by golden apes (13); Axel Grindstone believed these legends connected to the Unfallen People based on confirming \"voices\" (14).","notesPages":[366],"id":"glossary-entry-legends-romany-gypsy","letter":"L"},{"term":"Leibnitz","definition":"Gottfried Wilhelm Leibniz, German philosopher and mathematician credited with inventing the 'Stepped Reckoner' calculator in 1671 (25).","notesPages":[366],"id":"glossary-entry-leibnitz","letter":"L"},{"term":"Leo","definition":"The Lion, fifth sign of the conventional zodiac; its conventional mask hides the true sign of Panther the composite All-Animal (111).","notesPages":[366],"id":"glossary-entry-leo","letter":"L"},{"term":"Leucotomized humans","definition":"Humans who have undergone a form of psychosurgery (leucotomy/ lobotomy); suggested as one possible constituent type making up the Dolophonoi-Assassins (82).","notesPages":[366],"id":"glossary-entry-leucotomized-humans","letter":"L"},{"term":"Leveller Movement","definition":"Social movement, apparently carried through by the Kangaroo in its early stages, aimed at achieving societal evenness (80).","notesPages":[366],"id":"glossary-entry-leveller-movement","letter":"L"},{"term":"Levellers","definition":"Agents who implemented the Kangaroo's policy of societal homogenization, trimming not just the top (\"high-headed excellence\") but also, more significantly, the \"bottoms off of humanity and computerdom and the world itself,\" eliminating the lower classes and sources of trouble (69, 80-81).","notesPages":[366],"id":"glossary-entry-levellers","letter":"L"},{"term":"Leviathans","definition":"Great sea monsters; identified by Invisible Alfred as the two \"true signs\" hidden behind the conventional mask of Pisces the Fishes (111); also used generally, along with dragons and whales, to describe inhabitants of the deep (131).","notesPages":[366],"id":"glossary-entry-leviathans","letter":"L"},{"term":"Libra","definition":"The Scales, seventh sign of the conventional zodiac (111).","notesPages":[366],"id":"glossary-entry-libra","letter":"L"},{"term":"Lice (Sea-Lice)","definition":"Extremely small ocean-floor creatures capable of etching intricate figures and faces into stone pillars under the direction of the Whales (137-138); responsible for the living green color (\"The Green of Swarming...\") on the Whales' constructions (137); serve as amanuenses for the Whales, taking over the function of writing the Log-Books of the World from dishonest Computers and humans; write from right to left on limestone blocks (163-165); considered by most critics to have a superior writing style to humans (165).","notesPages":[366,367],"id":"glossary-entry-lice-sea-lice","letter":"L"},{"term":"Life Affair (The)","definition":"Term coined by Felix Culebra y Columba for the \"seamless garment\" representing the entirety of existence, woven from individual lives, the neighborhood, countryside, creatures, realms, continents, oceans, sub-atomic particles, galaxy clusters, minds, ideas, joys, and immediacies (74).","notesPages":[367],"id":"glossary-entry-life-affair-the","letter":"L"},{"term":"Life thread","definition":"Metaphorical thread representing an individual's lifespan, spun by Clotho, measured by Lachesis, and cut by Atropos; Inneall reinforces her own and her companions' threads with wotto- metal to prevent Atropos from cutting them (126-127).","notesPages":[367],"id":"glossary-entry-life-thread","letter":"L"},{"term":"Lightning","definition":"Strikes nightly through fissures to ignite gas in Second Eden (45) and Ape Caverns (68); used by God to take Unfallen People to himself (12); used by God to kill and consume 100 Axel's Apes in zoos (21); Mark Twain claims to scratch his head with lightning (131).","notesPages":[367],"id":"glossary-entry-lightning","letter":"L"},{"term":"Lightning bolts","definition":"Individual flashes of lightning; responsible for killing Unfallen People (12) and Axel's Apes (21).","notesPages":[367],"id":"glossary-entry-lightning-bolts","letter":"L"},{"term":"Lights (Depth-Creatures')","definition":"Bioluminescent organs possessed by creatures inhabiting the deep ocean, turned on after sunset (139).","notesPages":[367],"id":"glossary-entry-lights-depth-creatures","letter":"L"},{"term":"Lights (Green, Whales')","definition":"Sharp beams of green light shining from the Whales' large (one- foot-diameter), unshut eyes as they face the cenotaphs on the Ocean Bottom (148, 150).","notesPages":[367],"id":"glossary-entry-lights-green-whales","letter":"L"},{"term":"Limestone","definition":"Forms the caves of Ape Caverns (45) and the roof fissure (68); sold by Satrap Saint Ledger to the Whales, who transform it into variegated marble through a \"Patent of Nobility\" (106, 136); used to carve the representation of Axel on his cenotaph (148).","notesPages":[367],"id":"glossary-entry-limestone","letter":"L"},{"term":"Limestone blocks","definition":"Pieces of limestone, tumbled from the base of Tom Dooley's Island, nosed into upright rows by Whales and used by sea- lice as writing surfaces (163).","notesPages":[367],"id":"glossary-entry-limestone-blocks","letter":"L"},{"term":"Limestone caves","definition":"Natural underground formations composing Ape Caverns (22, 45).","notesPages":[367],"id":"glossary-entry-limestone-caves","letter":"L"},{"term":"Limestone pillars","definition":"Stalactites/stalagmites formed by dripping water within the Ape Caverns (45).","notesPages":[368],"id":"glossary-entry-limestone-pillars","letter":"L"},{"term":"Limestone roof","definition":"The ceiling of the Ape Caverns, containing a fissure (68).","notesPages":[368],"id":"glossary-entry-limestone-roof","letter":"L"},{"term":"Limestone slabs","definition":"Flat pieces of limestone used by sea-lice for writing the Log-Books of the World under the direction of the Whales (164).","notesPages":[368],"id":"glossary-entry-limestone-slabs","letter":"L"},{"term":"Limestone strata","definition":"Layers of limestone rock forming the base of Tom Dooley's Island, which slid out in sheets during the island's collapse (163).","notesPages":[368],"id":"glossary-entry-limestone-strata","letter":"L"},{"term":"Limestone wall","definition":"Solid barrier at the end of the Executive Passage, containing a brass door and key, intended as the final access point to the Cenaculum of the Sleepers (144, 147).","notesPages":[368],"id":"glossary-entry-limestone-wall","letter":"L"},{"term":"Little-girl computer","definition":"Descriptive term frequently applied to Inneall, emphasizing her chosen form and machine nature (8, 23, 25, 47, 52, 84, 126, 143).","notesPages":[368],"id":"glossary-entry-little-girl-computer","letter":"L"},{"term":"Little-girl machine","definition":"Similar descriptive term for Inneall (44, 143, 153, 164).","notesPages":[368],"id":"glossary-entry-little-girl-machine","letter":"L"},{"term":"Little Mother (Dubu)","definition":"Affectionate nickname given to Dubu the bear by the other eleven members of the merged experiments (63).","notesPages":[368],"id":"glossary-entry-little-mother-dubu","letter":"L"},{"term":"Live provender","definition":"Living animals kept aboard a ship for food; specifically, the more than three hundred giant, live ocean-turtles kept in the aft hold of the Annabella Saint Ledger (99).","notesPages":[368],"id":"glossary-entry-live-provender","letter":"L"},{"term":"Livius Secundus","definition":"A distinguished, brilliant Ambulatory Computer historian residing in Structo Lane (70); designated-and-surrogate father of Inneall (70); author of History of the Ambulatory Computers From Their Very Origin (70); models his style on the Roman historian Livy but lacks historical sense (71); discusses the \"Fulfillment of the World\" (93) and the nature of contest with Satrap and Felix (72, 74); states the Whales are excavating (106).","notesPages":[368],"id":"glossary-entry-livius-secundus","letter":"L"},{"term":"Locks (Alley Oop)","definition":"The series of hydraulic locks and tubes connecting Satrap Saint Ledger's hotel suite to Inneall's Ocean, built by Computers and Apes (47); found jammed with bodies trying to use it as an escape route from Ape Caverns (68). See also Allez-Oop.","notesPages":[368],"id":"glossary-entry-locks-alley-oop","letter":"L"},{"term":"Lodes","definition":"Axel's Apes possess the ability to smell and appraise ore deposits through earth or air up to two hundred kilometers away (46).","notesPages":[369],"id":"glossary-entry-lodes","letter":"L"},{"term":"Log Book (Inneall's)","definition":"See Inneall's Log.","notesPages":[369],"id":"glossary-entry-log-book-innealls","letter":"L"},{"term":"Log Book (Tom Dooley's)","definition":"Written record kept by Tom Dooley, in which he documented his death as being caused by ghosts and devils (124).","notesPages":[369],"id":"glossary-entry-log-book-tom-dooleys","letter":"L"},{"term":"Log-Books of the World","definition":"The official, comprehensive records of global events and histories; the function of keeping these logs was sequentially held by Humans (until dishonest), then Computers (until dishonest), and finally transferred to the Whales (working through sea- lice) (164).","notesPages":[369],"id":"glossary-entry-log-books-of-the-world","letter":"L"},{"term":"Logic (Obscure, of Abacus)","definition":"The unclear reasoning cited (likely facetiously) for early abacuses being considered \"base-ten\" despite often having only nine rods (24).","notesPages":[369],"id":"glossary-entry-logic-obscure-of-abacus","letter":"L"},{"term":"Logs (Computer/Human)","definition":"Written records kept by these species, eventually deemed unreliable due to excessive lies (164); Inneall's logs had achieved some official status before being superseded (164).","notesPages":[369],"id":"glossary-entry-logs-computer-human","letter":"L"},{"term":"Logs (Copious)","definition":"Extensive written records which Carcajou anticipates writing with the help of a single pirate captive (119).","notesPages":[369],"id":"glossary-entry-logs-copious","letter":"L"},{"term":"Lolly Jane Abboud","definition":"See Abboud, Lolly Jane.","notesPages":[369],"id":"glossary-entry-lolly-jane-abboud","letter":"L"},{"term":"London fogs","definition":"Thick fogs characteristic of historical London, used as a comparison for the fogs generated by burning underground natural gas in the damp Ape Caverns (46).","notesPages":[369],"id":"glossary-entry-london-fogs","letter":"L"},{"term":"Long View (Popugai's)","definition":"The ability possessed by Popugai the parrot, due to his high flight and keen sight, to see problems and disputes from a lofty, comprehensive perspective; considered the best overview among the Twelve (except possibly Luas) (64).","notesPages":[369],"id":"glossary-entry-long-view-popugais","letter":"L"},{"term":"Loom (Jacquard)","definition":"Weaving machine invented by Jacquard, notable for using punched cards to control the pattern—an early form of programmable automation (25).","notesPages":[369],"id":"glossary-entry-loom-jacquard","letter":"L"},{"term":"Loops-and-loops of intestines","definition":"Graphic description of Hieronymous Zchold's entrails after disembowelment, given to dogs (158).","notesPages":[369],"id":"glossary-entry-loops-and-loops-of-intestines","letter":"L"},{"term":"Lord","definition":"Used for Lord Randal (throughout); implies divine authority when referring to God (17, 34, 131); the Lord activates no thing before its time (17).","notesPages":[370],"id":"glossary-entry-lord","letter":"L"},{"term":"Lord and Master of the World","definition":"Royal title bestowed upon Mankind at its first appearance (34).","notesPages":[370],"id":"glossary-entry-lord-and-master-of-the-world","letter":"L"},{"term":"Lord Randal","definition":"One of the central Three (1); a human boy conceived in vitro (3, 5); possesses exceptional (\"off the scale\") intelligence (5); brave but sometimes fearful (1, 86); invented the bow-and-arrow (4); serves as circus ring-master (86) and pilot of a speedster (58); designated Captain of the Nine (122-123); murdered by a Dolophonoi knife immediately after Axel (148); entombed in a cenotaph on the Ocean Bottom (149); the Sea Louse subsequently calls his condition an undead coma (166).","notesPages":[370],"id":"glossary-entry-lord-randal","letter":"L"},{"term":"Lord Randal (Father)","definition":"George Lynn-Randal; has breakfast conversations with his wife Iris about computers, Astrology, the Kangaroo, and \"Serpent's Eggs,\" overheard by The Three (1-2). See also Lynn-Randal, George.","notesPages":[370],"id":"glossary-entry-lord-randal-father","letter":"L"},{"term":"Los Angeles","definition":"Major city in California; location of the \"Main Waif- arama,\" the world's largest orphanage complex where Henryetta spent her first sixteen months and burned down seven successive buildings (96).","notesPages":[370],"id":"glossary-entry-los-angeles","letter":"L"},{"term":"Lost Books (Book of Jasher)","definition":"Category of ancient texts not included in canonical scripture; The Book of Jasher is identified as one, containing accounts relevant to creation and the transfer of record-keeping duties between species (72, 163).","notesPages":[370],"id":"glossary-entry-lost-books-book-of-jasher","letter":"L"},{"term":"Lowlands","definition":"Source, along with Italy, France, the Germanies, England, and Moravia, of the nine master stonemasons who legendarily learned advanced techniques in Second Eden (13).","notesPages":[370],"id":"glossary-entry-lowlands","letter":"L"},{"term":"Loyal","definition":"Henryetta is described as loyal, pledging her entire being to the other eleven contemporaries (61).","notesPages":[370],"id":"glossary-entry-loyal","letter":"L"},{"term":"Luas","definition":"The young male angel assigned to the Wintergreen-Luna Experiment (55, 60); obtained with great difficulty by Kersten Wintergreen-Luna (61); possesses instantaneous mind, multi- location ability (61), and angelic will (61); plays the piano with strange, happy effect without touching the keys (77); remains more observer than participant (61); wrestles Carcajou, reveals Carcajou's true form is human, transforms eleven attacking wolverenes into devil-fish, then departs the group, stating he was never truly part of their number (87- 88, 102-103).","notesPages":[370,371],"id":"glossary-entry-luas","letter":"L"},{"term":"Lungfish","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[371],"id":"glossary-entry-lungfish","letter":"L"},{"term":"Lungs (AMH Secret)","definition":"Ambulatory Computers, like the one smoking the cigar, can perform actions requiring breath (like smoking elegantly) without possessing lungs; how this is achieved is an \"AMH secret\" (30).","notesPages":[371],"id":"glossary-entry-lungs-amh-secret","letter":"L"},{"term":"Lunnigan, Lanternjaw","definition":"See Lanternjaw Lunnigan.","notesPages":[371],"id":"glossary-entry-lunnigan-lanternjaw","letter":"L"},{"term":"Lutin","definition":"The young female python of the Dorantes-Saleh Experiment (55); possesses prophetic abilities (foreseeing the future, the Kangaroo in Virgo) but cannot always explain them well (62); keeps herself neat but evokes repugnance in some due to her snake nature (62); has a surrogate human father (Felix) who provides an electric runabout (62); accused by Henryetta of former promiscuity, an accusation Lutin answers by calling Henryetta a scandal-monger (73); her later “sickness” proves to be pregnancy (153-160); feels the Big Egg is \"exactly like me!\" (155); survives the final events (163).","notesPages":[371],"id":"glossary-entry-lutin","letter":"L"},{"term":"“Lutin’s Lutings”","definition":"A poem (“I dream of Castles...”) quoted within Chapter Twelve (136). The chapter’s opening epigraph is “Sleepwalkers’ Serenade” (130).","notesPages":[371],"id":"glossary-entry-lutins-lutings","letter":"L"},{"term":"Lutin's Room","definition":"The \"Biggest Central Room\" in Persimmon Manor where the Big Egg appears during Lutin’s childbirth; the three baby pythons she actually bears are later found with the Fates (155, 160); contains a large hole in the floor providing access for the whale Miol-Mor (160).","notesPages":[371],"id":"glossary-entry-lutins-room","letter":"L"},{"term":"Luxury","definition":"Inneall's designated father wrote a book on the Innate Love of Luxury... in AMHs (52).","notesPages":[371],"id":"glossary-entry-luxury","letter":"L"},{"term":"Lye-water","definition":"Caustic solution mentioned by Dubu as the medium needed to swell the specific Acorn containing all answers, causing it to burst open and reveal its contents (74).","notesPages":[371],"id":"glossary-entry-lye-water","letter":"L"},{"term":"Lynn-Randal adults","definition":"George and Iris Lynn-Randal, sponsors of the Experiment; driven crazy by the music The Three played (5); seem insufficiently aware of smells (5). See also Lynn- Randal, George; Lynn-Randal, Iris.","notesPages":[372],"id":"glossary-entry-lynn-randal-adults","letter":"L"},{"term":"Lynn-Randal Experiment","definition":"The primary experiment involving the co- raising of Lord Randal (human), Inneall (AMH Computer), and Axel (Axel's Ape) (3, 40, 42, 54, 55, 84, 87).","notesPages":[372],"id":"glossary-entry-lynn-randal-experiment","letter":"L"},{"term":"Lynn-Randal, George","definition":"Father of Lord Randal and 'parent'/sponsor of the Lynn-Randal experiment (2, 20); husband of Iris Lynn-Randal (2); has breakfast conversations revealing information about the Kangaroo and \"Serpent's Eggs\" (1-2); warns Iris against emotional involvement with experimental entities (7); a zoological doctor overseeing Axel the Ape's transfer (20). See also Lord Randal (Father).","notesPages":[371],"id":"glossary-entry-lynn-randal-george","letter":"L"},{"term":"Lynn-Randal house","definition":"Residence of George and Iris Lynn-Randal; location explored by The Three after gaining access via the back door from their habitat; contains music tapes, pictures, unique smells, and multi-track 'prowls' (5-6, 28).","notesPages":[372],"id":"glossary-entry-lynn-randal-house","letter":"L"},{"term":"Lynn-Randal, Iris","definition":"Mother of Lord Randal and wife of George Lynn- Randal; serves as one of the 'parents' sponsoring the Lynn-Randal experiment (1, 2, 84); expresses doubts about the Floating World and computer predictions (1); possesses an irritating grin (7); hunts Dolophonoi with Shadrack and Gregor out of fear for her 'children' (84-85); communicates distantly with Inneall (85); ultimately fails to use the Python-Gun due to weakness and fear (90). Full name used (2, 5, 7, 20, 41, 84, 89). See also Iris.","notesPages":[372],"id":"glossary-entry-lynn-randal-iris","letter":"L"},{"term":"Lynn-Randals (George and Iris)","definition":"See Lynn-Randal, George; Lynn- Randal, Iris.","notesPages":[372],"id":"glossary-entry-lynn-randals-george-and-iris","letter":"L"},{"term":"Lyonesse (City of)","definition":"Great underwater city located off Land's End (in Brittany, France per text); subject of debate regarding its builders (Titans, Sons of Anak, or Whales); characterized by enormous halls, corridors, arcades, stone couches twenty times human length, and huge stone stair risers thirty feet high (105-106).","notesPages":[372],"id":"glossary-entry-lyonesse-city-of","letter":"L"},{"term":"Machiavelli Giovane","definition":"Likely a fictional authority cited for the principle that stable solutions ultimately emerge in world affairs, regardless of flawed or chaotic planning (78).","notesPages":[373],"id":"glossary-entry-machiavelli-giovane","letter":"M"},{"term":"Machine","definition":"Emphasizing her non-biological nature, often used to refer to Inneall (4, 86, 123, 126, 143); also used generally for mechanical devices (31).","notesPages":[373],"id":"glossary-entry-machine","letter":"M"},{"term":"Machine (Ambulatory and Miming-Human Computer)","definition":"Full phrase used to describe computers like Inneall that can move and mimic human form (24). See Ambulatory Mime- Human (AMH) Computers.","notesPages":[373],"id":"glossary-entry-machine-ambulatory-and-miming-human-computer","letter":"M"},{"term":"Machine (Ambulatory Mime-Human Computer)","definition":"Inneall's specific type; entirely mechanical except for an unknown indwelling \"light- minded polter\" (3). See Ambulatory Mime-Human (AMH) Computers.","notesPages":[373],"id":"glossary-entry-machine-ambulatory-mime-human-computer","letter":"M"},{"term":"Machine (Arithmetic Machine)","definition":"Pascal's early calculating device (1642) (25).","notesPages":[373],"id":"glossary-entry-machine-arithmetic-machine","letter":"M"},{"term":"Machine (Calculating)","definition":"General term for early computing devices like the abacus (24).","notesPages":[373],"id":"glossary-entry-machine-calculating","letter":"M"},{"term":"Machine (Extruding)","definition":"Device described by Livius Secundus as the modern method for creating fabrics, personal groups, landscapes, worlds, and galaxies, replacing weaving (74).","notesPages":[373],"id":"glossary-entry-machine-extruding","letter":"M"},{"term":"Machine (Little-Girl)","definition":"Descriptive term emphasizing Inneall's chosen form and non- biological nature (44, 143, 153); Lanternjaw calls her this (153); the fortune-teller seeks information about her (44).","notesPages":[373],"id":"glossary-entry-machine-little-girl","letter":"M"},{"term":"Machine (Steam Calliope)","definition":"The large, loud, brass-tubed musical instrument purchased by Satrap for the circus (85). See also Calliope (Steam).","notesPages":[373],"id":"glossary-entry-machine-steam-calliope","letter":"M"},{"term":"Machines","definition":"Includes computers; seen as having affinities with asses (31); took over record- keeping from humans, then lost it to Whales (163-4). Used generally (27, 31, 74, 108, 126, 130, 141, 143, 163).","notesPages":[373],"id":"glossary-entry-machines","letter":"M"},{"term":"Machines (Kindred Machines)","definition":"Term used in the title of a book by Inneall's designated father, likely referring to entities similar to Ambulatory Computers (52).","notesPages":[373],"id":"glossary-entry-machines-kindred-machines","letter":"M"},{"term":"Mackerels","definition":"Fish flocking to Inneall’s Ocean (138).","notesPages":[372],"id":"glossary-entry-mackerels","letter":"M"},{"term":"Mad scientist","definition":"Term used by Inneall to describe the scientist who predicted her demise within three days (143).","notesPages":[374],"id":"glossary-entry-mad-scientist","letter":"M"},{"term":"Mad state (Gregor)","definition":"The condition of raving insanity Gregor McGregor falls into after shooting Riesin and Gajah; in this state, he runs into the wastelands and hangs himself (91).","notesPages":[374],"id":"glossary-entry-mad-state-gregor","letter":"M"},{"term":"Magdalene (Lutin as)","definition":"Henryetta's accusation that Lutin the pythoness was formerly promiscuous (\"a wanton\"), invoking the traditional image of Mary Magdalene as a repentant sexual sinner (73). This is Henryetta’s polemical comparison; the Gospels do not identify Mary Magdalene as a prostitute.","notesPages":[374],"id":"glossary-entry-magdalene-lutin-as","letter":"M"},{"term":"Magician-artisans","definition":"Human craftsmen described in AMH computer legends as having attempted to create mechanical horses, which inadvertently resembled later biological horses (31).","notesPages":[374],"id":"glossary-entry-magician-artisans","letter":"M"},{"term":"Magnetic personalities (Empress Elephants)","definition":"One of the key traits contributing to the effectiveness of Empress Elephants as mayors, alongside honesty, intelligence, diligence, compassion, fairness, foresight, and stability (92).","notesPages":[374],"id":"glossary-entry-magnetic-personalities-empress-elephants","letter":"M"},{"term":"Magog","definition":"One of the Unfallen Patriarchs, created shortly after Adam (12); Axel Grindstone believed he might still live on Earth until its end (12). His name is noted as having a bad reputation due to confusion with a later Giant of the same name (12).","notesPages":[374],"id":"glossary-entry-magog","letter":"M"},{"term":"Main Waif-arama","definition":"The world's largest orphanage complex, located in Sour-Grass Park West, Los Angeles; Henryetta spent her first sixteen months there, during which time it occupied eight different buildings (seven preceding buildings were burned down by Henryetta, as she openly admits) (96).","notesPages":[374],"id":"glossary-entry-main-waif-arama","letter":"M"},{"term":"Major adjustments","definition":"Significant alterations made by the overly-silent care-takers within The Three's contrived habitat (4).","notesPages":[374],"id":"glossary-entry-major-adjustments","letter":"M"},{"term":"Malay (language)","definition":"Said by the narrator to be the only Earth language possessing a specific twelve-syllable word (\"The Green of Swarming, Ocean-floor etching, deep-sea lice\") for the unique, vivid green color found on the Whales' underwater constructions (137).","notesPages":[374],"id":"glossary-entry-malay-language","letter":"M"},{"term":"Male (Alpha)","definition":"Designation for the dominant male in a group; Alpha identifies himself as an alpha male of the Golden Apes (20); the patriarch Alpha is referred to as the alpha male of Apes' Caverns (51).","notesPages":[374],"id":"glossary-entry-male-alpha","letter":"M"},{"term":"Malevolent (Ocean)","definition":"Scientific reports indicated Inneall's Ocean was more benevolent than malevolent shortly before midnight, implying it could not currently sustain itself without her (161).","notesPages":[375],"id":"glossary-entry-malevolent-ocean","letter":"M"},{"term":"Malfunction (Transmission)","definition":"Inneall's initial, false explanation for her inability to record information in her logs, claiming it was only a minor technical issue (164).","notesPages":[375],"id":"glossary-entry-malfunction-transmission","letter":"M"},{"term":"Mammals (Experimental)","definition":"Inhabiting The Three's contrived five-acre habitat, along with marsupials (3).","notesPages":[375],"id":"glossary-entry-mammals-experimental","letter":"M"},{"term":"Man","definition":"The human species (Homo Sapiens) collectively (34, 35, 36, 38, 41, 72, 105, 110); an individual male human (71, 122, 157, 158); the abstract concept of humanity (34, 35); Carcajou's human form (72, 87); the figure wrestling the angel in The Book of Jasher (88). Defined paradoxically through numerous literary and philosophical quotes (34-35).","notesPages":[375],"id":"glossary-entry-man","letter":"M"},{"term":"Man and State (Maritan)","definition":"Likely refers to Jacques Maritain's work Man and the State, cited for its definition of the State as an impersonal mechanism capable of becoming superhuman and tyrannical (78).","notesPages":[375],"id":"glossary-entry-man-and-state-maritan","letter":"M"},{"term":"Man (Cat-food factory)","definition":"Unnamed man who collects the bodies after Donatus O'Reily's hanging, presumably for use in his factory (158).","notesPages":[375],"id":"glossary-entry-man-cat-food-factory","letter":"M"},{"term":"Man creature","definition":"Term used in computer legends to refer to the original creation of Mankind, which was flawed but accidentally activated (37).","notesPages":[375],"id":"glossary-entry-man-creature","letter":"M"},{"term":"Man-devil form","definition":"Carcajou's transitional, unfleshed form seen by some of the Young People; implied to be visible during the full moon (73).","notesPages":[376],"id":"glossary-entry-man-devil-form","letter":"M"},{"term":"Man form (Carcajou's)","definition":"The human shape Carcajou sometimes assumes, contrasted with his wolverine or devil forms (72, 87).","notesPages":[375],"id":"glossary-entry-man-form-carcajous","letter":"M"},{"term":"Man (Furtive person)","definition":"The unnamed individual who secretly sells Lord Randal the kangaroo knuckle-bone revealing the identity of the Kangaroo's Head (145).","notesPages":[375],"id":"glossary-entry-man-furtive-person","letter":"M"},{"term":"Man (Nervous)","definition":"Hieronymous Ignatius Zchold, the Priest/Bishop sentenced to death (121, 122).","notesPages":[375],"id":"glossary-entry-man-nervous","letter":"M"},{"term":"Man-sized creatures","definition":"Beings scaled to human dimensions, for whom the small tombs/ cenotaphs in the Whale Temple-City are apparently intended (137).","notesPages":[376],"id":"glossary-entry-man-sized-creatures","letter":"M"},{"term":"Man (who wrestled angel)","definition":"Carcajou in the novel’s pseudo-scriptural Book of Jasher passage, which adapts the pattern of Jacob’s wrestling encounter (88; compare Genesis 32:24-32).","notesPages":[375],"id":"glossary-entry-man-who-wrestled-angel","letter":"M"},{"term":"Manila","definition":"Capital city of the Philippines; location where a man was daydreaming before bi- locating to San Francisco (95).","notesPages":[376],"id":"glossary-entry-manila","letter":"M"},{"term":"Mankind","definition":"The human species collectively (Homo Sapiens); appeared suddenly with high intelligence and language (34); subject of creation legends (36-7); lacks inherent substance according to computers (38); possesses vast unused brain capacity (39-40); seems incapable of change except by sudden leaps (40); potentially being replaced by Second Humanity (Apes) or other successors (141, 143-4, 166); represented allegorically by the Ship of Fools (Annabella) (141).","notesPages":[376],"id":"glossary-entry-mankind","letter":"M"},{"term":"Mankind (Cockeyed)","definition":"Inneall's potentially sarcastic term for the portion of humanity the Annabella Saint Ledger might represent, as opposed to all Mankind (141).","notesPages":[376],"id":"glossary-entry-mankind-cockeyed","letter":"M"},{"term":"Mankind creature","definition":"Term used in computer legend for the seventh, flawed but accidentally activated, being made by the Theos on the lathe (37).","notesPages":[376],"id":"glossary-entry-mankind-creature","letter":"M"},{"term":"Manner (Inexplicable)","definition":"Describes the sudden appearance of Carcajou in his Undocumented Mega Human form (88).","notesPages":[376],"id":"glossary-entry-manner-inexplicable","letter":"M"},{"term":"Manor (Persimmon Manor)","definition":"The large ranch house on Tom Dooley’s Island, built entirely of persimmon wood by the great-great-grandfather of both Tom Dooley and Otto Wotto (115-116, 124); site of endless parties with carry-over guests (116); possibly haunted (124); made waterproof and weighted to sink with the island (116); eventually rests on the Ocean Bottom (159); contains a hidden room housing the Three Fates (126).","notesPages":[376],"id":"glossary-entry-manor-persimmon-manor","letter":"M"},{"term":"Mansions (Underneath the sea)","definition":"Underwater dwellings built by Whales, according to \"The Child's Big Book of Whales\" (105).","notesPages":[376],"id":"glossary-entry-mansions-underneath-the-sea","letter":"M"},{"term":"Marble","definition":"Becomes the favorite building stone of Whales after limestone receives its \"Patent of Nobility\" via sea change (136); the Whales' Temple-City features variegated, wonderfully varicolored (pink, lilac, tan, orange, mauve-tinted) marble with living green blotches (136-138).","notesPages":[376,377],"id":"glossary-entry-marble","letter":"M"},{"term":"Marino","definition":"The young male seal of the Wintergreen-Luna Experiment (55); possesses the fastest intelligence and wit among the group (60); personable, friendly, starts many things (60); considered \"too mechanical\" by Inneall (60); given electric vehicles for land travel (56); King of the Cove (56); requires instruction for Oceanic Metastasis (133-4); survives the final events (161).","notesPages":[377],"id":"glossary-entry-marino","letter":"M"},{"term":"Maritan","definition":"Likely Jacques Maritain, philosopher cited for his definition of the State in Man and State (78).","notesPages":[377],"id":"glossary-entry-maritan","letter":"M"},{"term":"Mark I (Harvard)","definition":"Early computer associated with Aiken (25).","notesPages":[377],"id":"glossary-entry-mark-i-harvard","letter":"M"},{"term":"Mark (Mud marks)","definition":"Imprints made by Axel on the transparent sky- cover using mud-tipped arrows to convey a message (4).","notesPages":[377],"id":"glossary-entry-mark-mud-marks","letter":"M"},{"term":"Mark (of the Serpent)","definition":"The identification placed by the Theos (in legend) on the eggshell from which Man mistakenly hatched (36).","notesPages":[377],"id":"glossary-entry-mark-of-the-serpent","letter":"M"},{"term":"Marriage ceremony","definition":"Occasion during which a coin is flipped to determine the order of combined surnames under the unrandomized naming law (54-55).","notesPages":[377],"id":"glossary-entry-marriage-ceremony","letter":"M"},{"term":"Mars","definition":"Planet; location of the fictional Red Raiders, whom Ruddy Lord Randal somewhat resembles (63).","notesPages":[377],"id":"glossary-entry-mars","letter":"M"},{"term":"Marsupials (Experimental)","definition":"Inhabiting The Three's contrived habitat, like bandicoots (3).","notesPages":[377],"id":"glossary-entry-marsupials-experimental","letter":"M"},{"term":"Master Doctor","definition":"Title, along with Constellated Physician, held by the human midwife-nurse attending Lutin's birth (154, 155).","notesPages":[377],"id":"glossary-entry-master-doctor","letter":"M"},{"term":"Master Mathematicians (Unfallen)","definition":"Title describing the Unfallen Ones' expertise in mathematics, sought out by great mathematicians from cities like Alexandria and Heidelberg (15).","notesPages":[377],"id":"glossary-entry-master-mathematicians-unfallen","letter":"M"},{"term":"Masters","definition":"Satrap learned the technique of free diving in the Indian Ocean from unspecified Masters (133).","notesPages":[377],"id":"glossary-entry-masters","letter":"M"},{"term":"Masterwork (of Pop Art)","definition":"Description of the newly-woven tapestry The Midas Satrap Saint Ledger As An Obscene Sea Monster (144).","notesPages":[377],"id":"glossary-entry-masterwork-of-pop-art","letter":"M"},{"term":"Mate (First Mate, brown bear)","definition":"Position held by a large Alaskan Brown Bear on the pirate ship The Unrepentent Rascal, recalled fearfully by Lanternjaw Lunnigan (102-103).","notesPages":[378],"id":"glossary-entry-mate-first-mate-brown-bear","letter":"M"},{"term":"Mate (Ship's)","definition":"Officer on a ship who, according to legend, sometimes consults the skeleton in the ship's hidden closet for instructions during dire peril (114).","notesPages":[378],"id":"glossary-entry-mate-ships","letter":"M"},{"term":"Material objects","definition":"Included as part of Human Culture according to Britannica (39), such as tools, works of art, etc.","notesPages":[378],"id":"glossary-entry-material-objects","letter":"M"},{"term":"Material (Universe as)","definition":"Concept articulated by Invisible Alfred: the Universe is material because it was intended to illustrate a material point, but it is ultimately not real (112).","notesPages":[378],"id":"glossary-entry-material-universe-as","letter":"M"},{"term":"Mathematics","definition":"Unfallen Ones are Master Mathematicians who teach high mathematics (15); higher mathematics used as example subject by Satrap (133).","notesPages":[378],"id":"glossary-entry-mathematics","letter":"M"},{"term":"Mathematics (Probability)","definition":"Branch of mathematics dealing with chance; humans forget its principles when excitedly rolling dice (38).","notesPages":[378],"id":"glossary-entry-mathematics-probability","letter":"M"},{"term":"Matrix (Computer, Wotto Metal)","definition":"The structural base of a computer; Otto Wotto's invention of wotto metal allowed circuits to go anywhere within the matrix (25).","notesPages":[378],"id":"glossary-entry-matrix-computer-wotto-metal","letter":"M"},{"term":"Matthew Arnold","definition":"English poet quoted for his lines about great whales sailing \"Round the world for ever and aye\" (131).","notesPages":[378],"id":"glossary-entry-matthew-arnold","letter":"M"},{"term":"Matthew (Gospel of)","definition":"New Testament book containing the verse (\"Be you therefore as wise as serpents and as guileless as doves\") that inspired Felix Culebra y Columba's name and defining characteristics (71).","notesPages":[378],"id":"glossary-entry-matthew-gospel-of","letter":"M"},{"term":"Mauchly","definition":"John Mauchly, historical computer pioneer associated with Eckert and their electronic calculator (25).","notesPages":[378],"id":"glossary-entry-mauchly","letter":"M"},{"term":"Mauve-tinted marble","definition":"One of the colors (along with pink, lilac, tan, orange) of the variegated marble used in the Whales' Constructions on the Ocean Bottom (137).","notesPages":[378],"id":"glossary-entry-mauve-tinted-marble","letter":"M"},{"term":"Mead","definition":"Alcoholic beverage made from fermented honey; Inneall directs the pirates to make mead from the honey taken from the bees in the midship hold (99).","notesPages":[379],"id":"glossary-entry-mead","letter":"M"},{"term":"Meadow mice","definition":"Small rodents visible on the ground to Popugai from his flight altitude of two miles (64).","notesPages":[379],"id":"glossary-entry-meadow-mice","letter":"M"},{"term":"Meaning","definition":"Of printed words initially misinterpreted by The Three (7); of celestial signs (111).","notesPages":[379],"id":"glossary-entry-meaning","letter":"M"},{"term":"Means (Sinister)","definition":"Sometimes used by AMH Computers, after giving warning, to ensure their predictions come true (31).","notesPages":[379],"id":"glossary-entry-means-sinister","letter":"M"},{"term":"Measurements (Island sinking)","definition":"Time and depth calculations regarding the sinking of Tom Dooley's Island, provided prophetically by Lutin (101).","notesPages":[379],"id":"glossary-entry-measurements-island-sinking","letter":"M"},{"term":"Meat (Hamburger)","definition":"1000 lbs loaded onto the Annabella as a change from turtle meat (101).","notesPages":[379],"id":"glossary-entry-meat-hamburger","letter":"M"},{"term":"Meat (Live-turtle)","definition":"Primary protein source for the pirates, consisting of giant ocean turtles kept alive in the hold (99, 101).","notesPages":[379],"id":"glossary-entry-meat-live-turtle","letter":"M"},{"term":"Meat (of the Subject)","definition":"The core substance or essence of a topic; an AMH Computer claims the subject of Mankind lacks this essential quality (38).","notesPages":[379],"id":"glossary-entry-meat-of-the-subject","letter":"M"},{"term":"Mechanical coons","definition":"Artificial raccoons required for Computers to engage in the hobby of coon hunting, as real coons are extinct (33).","notesPages":[379],"id":"glossary-entry-mechanical-coons","letter":"M"},{"term":"Mechanical genius (Inneall)","definition":"Inneall's innate talent for mechanics, which allowed her to set up the distant communication link with Iris (85).","notesPages":[379],"id":"glossary-entry-mechanical-genius-inneall","letter":"M"},{"term":"Mechanical horses","definition":"Creatures created by human magician-artisans in computer legends; they worked, but people laughed at them, and later biological horses coincidentally came to resemble them (31).","notesPages":[379],"id":"glossary-entry-mechanical-horses","letter":"M"},{"term":"Mechanical imperative","definition":"The relentless driving force of inertial motion compelling computers to follow a process to its end unless stopped (27). See also Inertial Motion.","notesPages":[379],"id":"glossary-entry-mechanical-imperative","letter":"M"},{"term":"Mechanical order","definition":"The system or category of things to which Inneall belongs, distinct from the natural order; the reinforcing wire in the swinging vines is also of this order (4).","notesPages":[380],"id":"glossary-entry-mechanical-order","letter":"M"},{"term":"Mechanical parts (Dolophonoi)","definition":"Implanted electronic hearing and smelling in the Dolophonoi; strength-reinforcers and electronic grapplers are inferred rather than confirmed in this description (50). Their bodies are described as predominantly human (42).","notesPages":[380],"id":"glossary-entry-mechanical-parts-dolophonoi","letter":"M"},{"term":"Mechanical pump (in Egg)","definition":"A functioning device detected inside the Big Egg that appears during Lutin’s childbirth; Inneall also detects something alive inside it (155-156).","notesPages":[380],"id":"glossary-entry-mechanical-pump-in-egg","letter":"M"},{"term":"Mechanical scanners","definition":"Devices used by the newcomers at Second Eden, driven \"crazy\" by the mega ability readings of the gravid female Ape (Axel's mother) (19).","notesPages":[380],"id":"glossary-entry-mechanical-scanners","letter":"M"},{"term":"Mechanics","definition":"Contrasted with biology in the land between them where coincidences happen (31).","notesPages":[380],"id":"glossary-entry-mechanics","letter":"M"},{"term":"Mechanism (Impersonal)","definition":"The State defined as such, composed of abstract laws and concrete power (78). See also Impersonal Mechanism (State as).","notesPages":[380],"id":"glossary-entry-mechanism-impersonal","letter":"M"},{"term":"Mechanisms (Computer)","definition":"Internal workings of computers, which remained bulky despite miniaturization until the invention of wotto metal (25).","notesPages":[380],"id":"glossary-entry-mechanisms-computer","letter":"M"},{"term":"Mechanisms (Implanted)","definition":"Artificial components within the bodies of the Dolophonoi (42).","notesPages":[380],"id":"glossary-entry-mechanisms-implanted","letter":"M"},{"term":"Mechanisms (Spring, on coffins)","definition":"The Sea Louse states that the stone coffin covers have spring mechanisms operable from inside and calls their occupants undead (166). The claim belongs to this explicitly unreliable epilog.","notesPages":[380],"id":"glossary-entry-mechanisms-spring-on-coffins","letter":"M"},{"term":"Mechanistic explanation (Inneall's powers)","definition":"An assumed scientific rationale for Inneall's abilities (like creating an ocean); Inneall herself says there is a mechanistic explanation for each of her powers (48).","notesPages":[380],"id":"glossary-entry-mechanistic-explanation-innealls-powers","letter":"M"},{"term":"Media","definition":"Source of the \"all-people throatiness\" consensus voice (6).","notesPages":[380],"id":"glossary-entry-media","letter":"M"},{"term":"Media persons","definition":"Representatives of the media who came to Heart's Desire Cove, drawn more by the novelty of the unborn elephant Gajah participating in activities than by opportunities for serious scientific investigation (56).","notesPages":[380],"id":"glossary-entry-media-persons","letter":"M"},{"term":"Meditation halls","definition":"Locations within Ape Alley where the Axel's Apes frequently engage in meditation (46); word coming out of them predicted the \"Moment of the Awakening\" (46).","notesPages":[381],"id":"glossary-entry-meditation-halls","letter":"M"},{"term":"Mediterranean evergreen (Carob)","definition":"The tree on which Gregor McGregor hangs himself, called a “Judas Tree” by the novel (91). See Judas Tree for the botanical distinction.","notesPages":[381],"id":"glossary-entry-mediterranean-evergreen-carob","letter":"M"},{"term":"Medium (Directed-medium, Whales')","definition":"The conduit through which Whales perform their writing and log-keeping, utilizing sea-lice and humans operating primarily on an unconscious level (165).","notesPages":[381],"id":"glossary-entry-medium-directed-medium-whales","letter":"M"},{"term":"Mega ability","definition":"Exceptional capability indicated by scanners for the unborn Axel the Ape, residing in the child, not the mother (19).","notesPages":[381],"id":"glossary-entry-mega-ability","letter":"M"},{"term":"Mega Dolophonos","definition":"A particularly powerful Dolophonos-Assassin who appears after the Carcajou-Luas wrestling match, injures Carcajou, and departs, explicitly described as having been sent to dispose of him (94).","notesPages":[381],"id":"glossary-entry-mega-dolophonos","letter":"M"},{"term":"Mega human (Undocumented)","definition":"The classification given by neighborhood scanners to Carcajou when he appears inexplicably in his true human form (88).","notesPages":[381],"id":"glossary-entry-mega-human-undocumented","letter":"M"},{"term":"Mega intelligence","definition":"Extremely high level of intelligence possessed by the Imperial Heads of the Kangaroo (83). See also Intelligence.","notesPages":[381],"id":"glossary-entry-mega-intelligence","letter":"M"},{"term":"Mega mind","definition":"Superlative intellect; attributed to Invisible Alfred by Schimp (149).","notesPages":[381],"id":"glossary-entry-mega-mind","letter":"M"},{"term":"Mega-minded person (Axel the Ape)","definition":"Description of the newborn Axel the Ape, identified by sophisticated scanners in Middle America as \"one-in-a-billion mega-minded\" (20).","notesPages":[381],"id":"glossary-entry-mega-minded-person-axel-the-ape","letter":"M"},{"term":"Mega-people","definition":"Individuals possessing superior (\"bigger-then-life\") talents and often uncooperative natures; capable of rocking the Floating World on a \"mega scale\"; carefully scanned by the Kangaroo from childhood (1, 82). See also Mega persons.","notesPages":[382],"id":"glossary-entry-mega-people","letter":"M"},{"term":"Mega person","definition":"Rating indicating exceptionally high (\"off the scale\") intelligence or abilities (5); Rose-of-Sharon Montdrago loses this rating after an error is found in her record classifying her as a \"Serpent's Egg\" (117). See also Mega persons.","notesPages":[381],"id":"glossary-entry-mega-person","letter":"M"},{"term":"Mega persons","definition":"Individuals identified by scanners as having extraordinary potential (5); often targeted by the Kangaroo if deemed unruly or dangerous (\"Serpent's Eggs\") (82); legally reach adulthood at age ten (146). See also Authentic Mega Persons, Mega-people, Mega- persons (False).","notesPages":[381],"id":"glossary-entry-mega-persons","letter":"M"},{"term":"Mega-persons (False)","definition":"Marino calls Serpent’s Eggs “false Mega-Persons in one sense” (127). This is a character’s formulation, not proof that everyone marked for destruction is inherently defective. See also Mega persons.","notesPages":[382],"id":"glossary-entry-mega-persons-false","letter":"M"},{"term":"Megalithic archeology","definition":"The study of large prehistoric stone structures; Lord Randal had thoroughly researched this field, especially its Ocean Floor context (137).","notesPages":[382],"id":"glossary-entry-megalithic-archeology","letter":"M"},{"term":"Megalithic structures","definition":"Large monuments built of massive stones; the constructions being built by the Whales underwater, which might serve as a future refuge for the Nine (119).","notesPages":[382],"id":"glossary-entry-megalithic-structures","letter":"M"},{"term":"Melancholy (Donatus')","definition":"Felt by Donatus O'Reily while awaiting his hanging, from which the Midnight Cock awakens him (157).","notesPages":[382],"id":"glossary-entry-melancholy-donatus","letter":"M"},{"term":"Melchisedech","definition":"Ancient biblical figure (priest-king of Salem); believed by Axel Grindstone to be sleeping undead in Abraham's Bosom (11); also identified as one of the Unfallen People who might live on Earth until its end (12).","notesPages":[382],"id":"glossary-entry-melchisedech","letter":"M"},{"term":"Melody","definition":"Absent from the music in the Lynn-Randal house, unrecognizable to the \"new people\" (8).","notesPages":[382],"id":"glossary-entry-melody","letter":"M"},{"term":"Members (Contingent, of Kangaroo)","definition":"Individuals (Human, Computer, Animal) who momentarily constitute the Kangaroo organization, operating mostly unconsciously (83).","notesPages":[382],"id":"glossary-entry-members-contingent-of-kangaroo","letter":"M"},{"term":"Membership (Kangaroo)","definition":"The composition of the Kangaroo organization, loosely construed to include Humans, Ambulatory Computers, and a few superior Animals (80).","notesPages":[382],"id":"glossary-entry-membership-kangaroo","letter":"M"},{"term":"Memorial Park (to Inneall)","definition":"Satrap Saint Ledger's stated purpose for building the entertainment center at Heart's Desire Cove (57).","notesPages":[382],"id":"glossary-entry-memorial-park-to-inneall","letter":"M"},{"term":"Memory","definition":"Circuses and carnivals associated with the Unfallen People are a strange notion, questioning what they could be a memory of (14); Popugai possesses a rare gift of memory enabling him to remember everything he ever heard (64).","notesPages":[382],"id":"glossary-entry-memory","letter":"M"},{"term":"Memory (Folk)","definition":"Collective cultural recollection; contains faint traces of celestial trumpets welcoming Man (34); motivates the building of bonfires (58).","notesPages":[383],"id":"glossary-entry-memory-folk","letter":"M"},{"term":"Memory (Racial/Crypto-)","definition":"Deep, hidden strata of human consciousness containing weird caves and the mythological roots of Ambulatory Computers, according to Livius Secundus's history (70).","notesPages":[383],"id":"glossary-entry-memory-racial-crypto","letter":"M"},{"term":"Memos (Inneall's)","definition":"Written directives issued by Inneall regarding provisions for the pirate crew, specifying rum from the Indies stored in hogsheads and demanding honey be extracted from bees to make mead (99).","notesPages":[383],"id":"glossary-entry-memos-innealls","letter":"M"},{"term":"Men","definition":"Used generally (118, 122, 135, 146); two men wrestling (88); raiding men (19, 20); fish-faced men (159); nine dead men (156, 157).","notesPages":[383],"id":"glossary-entry-men","letter":"M"},{"term":"Menace personified","definition":"Description of the Dolophonos-Assassin encountered by the Nine inside Persimmon Manor (125).","notesPages":[383],"id":"glossary-entry-menace-personified","letter":"M"},{"term":"Mental level","definition":"Threshold of psychic or intellectual capacity; rising greatly above this level attracts the Kangaroo's minute analysis (80).","notesPages":[383],"id":"glossary-entry-mental-level","letter":"M"},{"term":"Mental state (Oceanic Metastasis)","definition":"The pseudo-dream state required for deep ocean diving (134). See also Metastasis (Oceanic).","notesPages":[383],"id":"glossary-entry-mental-state-oceanic-metastasis","letter":"M"},{"term":"Mentality","definition":"The \"Don't make a big thing out of it\" mentality was rife in the world (81); Henryetta's subtle mentality used for pyrokinesis (97).","notesPages":[383],"id":"glossary-entry-mentality","letter":"M"},{"term":"Mentality (Shining, Apes')","definition":"The emergent awareness and heightened consciousness of the Golden Apes upon awakening (142).","notesPages":[383],"id":"glossary-entry-mentality-shining-apes","letter":"M"},{"term":"Mentor (Miol-Mor)","definition":"Role (along with nurse and governess) adopted by the gentle Killer Whale Miol-Mor towards the Big Egg (160).","notesPages":[383],"id":"glossary-entry-mentor-miol-mor","letter":"M"},{"term":"Mephistopheles","definition":"The devil’s name in the Faust tradition, invoked in the novel’s analogy between naming the devil and naming man “Ambiguity” (35). The claim that learning the name gives Faustus power is the novel’s formulation.","notesPages":[383],"id":"glossary-entry-mephistopheles","letter":"M"},{"term":"Mer-ma-id","definition":"Mythical creature dwelling at the bottom of the sea, from the Oxford Song Book verse (131).","notesPages":[383],"id":"glossary-entry-mer-ma-id","letter":"M"},{"term":"Message (Axel receives)","definition":"An unseen communication received by Axel at the end of the lacrosse game, instructing him to enter the Deep Sleep for three days and nights (65).","notesPages":[383],"id":"glossary-entry-message-axel-receives","letter":"M"},{"term":"Message (Mud marks on sky-cover)","definition":"Text written by Axel in code Chaldee using mud- tipped arrows on the transparent dome of their habitat, asking \"If there is anybody up above that sky, let him give us a sign\" (4).","notesPages":[384],"id":"glossary-entry-message-mud-marks-on-sky-cover","letter":"M"},{"term":"Messenger","definition":"Unseen, presumed messenger brought the communication prompting Axel's sleep (65).","notesPages":[384],"id":"glossary-entry-messenger","letter":"M"},{"term":"Metallic wire (in vines)","definition":"Reinforcement material twined into the live vines used by The Three for swinging between cliffs, making them unbreakable (4).","notesPages":[384],"id":"glossary-entry-metallic-wire-in-vines","letter":"M"},{"term":"Metals","definition":"Axel's Apes possess the talent to smell and appraise deposits of all metals from great distances (46).","notesPages":[384],"id":"glossary-entry-metals","letter":"M"},{"term":"Metamorphic company (Seven Richest Men)","definition":"The legendary group of the world's wealthiest individuals, capable of transforming into Deep Ocean Denizens (135).","notesPages":[384],"id":"glossary-entry-metamorphic-company-seven-richest-men","letter":"M"},{"term":"Metamorphic creatures (Seven Richest Men)","definition":"Beings capable of changing form; specifically, the seven richest men in the world according to folk legend (135).","notesPages":[384],"id":"glossary-entry-metamorphic-creatures-seven-richest-men","letter":"M"},{"term":"Metamorphosized man-form (Carcajou)","definition":"Carcajou's transformed human shape adopted during his otherworldly wrestling match with Luas (87).","notesPages":[384],"id":"glossary-entry-metamorphosized-man-form-carcajou","letter":"M"},{"term":"Metaphors","definition":"Inneall suggests \"our world\" might be merely a collection of allegories, metaphors, symbols, and conventions (141).","notesPages":[384],"id":"glossary-entry-metaphors","letter":"M"},{"term":"Metastasis (Oceanic)","definition":"The pseudo-dream state, also called the Oceanic Hyper-Active Dream State or Satrap's state, induced (partly via para- hypnosis) for deep ocean diving; enables breathing underwater (implied), provides new ways of seeing, heightened senses, and allows communication with Satrap underwater; settles completely on the Nine and is potentially permanent or only lost through severe shock (133, 134, 135, 137, 139, 150). See also Mental state (Oceanic Metastasis).","notesPages":[384],"id":"glossary-entry-metastasis-oceanic","letter":"M"},{"term":"Methane natural-gas","definition":"Flammable gas rising from a fissure in the rock of the Second Eden cenaculum, ignited nightly by lightning for illumination (45).","notesPages":[384],"id":"glossary-entry-methane-natural-gas","letter":"M"},{"term":"Method (Human, reproduction)","definition":"AMHs plan to practice with this biological means of human procreation before devising their own (32).","notesPages":[385],"id":"glossary-entry-method-human-reproduction","letter":"M"},{"term":"Method (Indoctrination)","definition":"The secret technique and content used by Satrap Saint Ledger to induce the first stage of Oceanic Metastasis in the human and 'wider human' members of the Nine (134).","notesPages":[385],"id":"glossary-entry-method-indoctrination","letter":"M"},{"term":"Midas","definition":"Legendary Phrygian king whose touch turned everything to gold; used as a descriptor for Satrap Saint Ledger, emphasizing his immense wealth (47, 48); Henryetta lacks a \"midas grandfather\" (85). See also Ignorant Midas.","notesPages":[385],"id":"glossary-entry-midas","letter":"M"},{"term":"Midas Class","definition":"The highest category of wealth according to Money Mart ratings; Satrap Saint Ledger is ranked eleventh richest in the world, just barely qualifying for this class (135).","notesPages":[385],"id":"glossary-entry-midas-class","letter":"M"},{"term":"Midas-man","definition":"Term used by the pirate crew (specifically Sebastian Lazar and Lanternjaw Lunnigan) when addressing Satrap Saint Ledger (99, 100, 101).","notesPages":[385],"id":"glossary-entry-midas-man","letter":"M"},{"term":"Midas Satrap Saint Ledger","definition":"Full appellation frequently used for Satrap Saint Ledger, highlighting his extreme wealth (e.g., 47, 57, 58, 85, 93, 94, 95, 98, 100, 101, 106, 115, 117, 118, 122, 124, 125, 127, 128, 129, 132, 133, 134, 135, 136, 137, 145, 146, 147). See also Saint Ledger, Satrap.","notesPages":[385],"id":"glossary-entry-midas-satrap-saint-ledger","letter":"M"},{"term":"Midas Satrap Saint Ledger As An Obscene Sea Monster (Tapestry)","definition":"Title of the magnificent, newly-woven pop art tapestry hanging in the condominium clubroom, depicting Satrap in his \"beautiful oceanic- ugliness-monsterness\" as seen earlier that day (144, 147).","notesPages":[385],"id":"glossary-entry-midas-satrap-saint-ledger-as-an-obscene-sea-monster-tapestry","letter":"M"},{"term":"Middle Ages (Lower)","definition":"Historical period in Europe when Golden Apes supposedly predicted the fortunes of crowned heads correctly (30).","notesPages":[385],"id":"glossary-entry-middle-ages-lower","letter":"M"},{"term":"Middle Air","definition":"The space between the ground and the upper atmosphere; where three flames appear and hover over Gajah's body (94); where chortling crows fly (112).","notesPages":[385],"id":"glossary-entry-middle-air","letter":"M"},{"term":"Middle America","definition":"Geographical region; location where the newborn Axel the Ape is flown for the Lynn-Randal experiment (20); setting of the Apes' Alley established later (45).","notesPages":[385],"id":"glossary-entry-middle-america","letter":"M"},{"term":"Middle Mississippi River","definition":"One of the major river valleys being encroached upon by the growing Inneall's Ocean (55). See also Mississippi Rivers.","notesPages":[386],"id":"glossary-entry-middle-mississippi-river","letter":"M"},{"term":"Middle State (Isthmus of)","definition":"See Isthmus of a Middle State, Isthmus of the Middle State.","notesPages":[386],"id":"glossary-entry-middle-state-isthmus-of","letter":"M"},{"term":"Middlemen (Dolphins)","definition":"Intermediaries who facilitated Satrap Saint Ledger's deal to sell limestone to the Whales, bringing the payment of nugget ocean gold (106).","notesPages":[386],"id":"glossary-entry-middlemen-dolphins","letter":"M"},{"term":"Midnight","definition":"The middle of the night (12:00 AM); time when Axel is supposed to wake from Deep Sleep and trigger the general Ape awakening (142, 143, 145). The Persimmon Manor murders stop at noon, not midnight (128); time of vengeance and prevention planned by Henryetta (140).","notesPages":[386],"id":"glossary-entry-midnight","letter":"M"},{"term":"Midnight Cock","definition":"A mythical bird, possibly appearing in Medieval Aeneas Legends, whose crow at midnight signals the \"Moment of Awakening\" for the Second Humanity (Apes) (143); Sebastian Lazar brings one from the Cenaculum and is later seen leaving the priest’s hole with it (153, 156); its crow wakes the nine dead men, while Donatus, already awake, says it rouses him from melancholy (156-157). See also Crowing Cock (Midnight).","notesPages":[386],"id":"glossary-entry-midnight-cock","letter":"M"},{"term":"Midnight minute","definition":"The precise moment of midnight, noted as preceded by six hours of scientific reports indicating the Ocean’s current benevolence and dependence on Inneall (161).","notesPages":[386],"id":"glossary-entry-midnight-minute","letter":"M"},{"term":"Midnight sky (Glowing)","definition":"The garish gegenschein effect observed at Heart's Desire Cove during the End-of-Summer nights (59).","notesPages":[386],"id":"glossary-entry-midnight-sky-glowing","letter":"M"},{"term":"Midship hold","definition":"The central cargo area of the Annabella Saint Ledger; contains live honey bees released by jokers (99, 100).","notesPages":[386],"id":"glossary-entry-midship-hold","letter":"M"},{"term":"Midwife-nurse","definition":"Human female professional (also a Master Doctor and Constellated Physician) hired by Satrap to attend Lutin's unconventional birth (154); cast into a deep sleep by Dubu just before the Big Egg appeared (155).","notesPages":[386],"id":"glossary-entry-midwife-nurse","letter":"M"},{"term":"Mien (Unfallen Folks')","definition":"The appearance, bearing, or demeanor of the Unfallen People, described as full of grace, dignity, and nobility (16).","notesPages":[386],"id":"glossary-entry-mien-unfallen-folks","letter":"M"},{"term":"Millennium","definition":"The currently reigning \"sleepy one\" among the Unfallen serves as conscience for his millennium (19); the sleepers in Ape Caverns might not wake \"in this millennium\" (67).","notesPages":[387],"id":"glossary-entry-millennium","letter":"M"},{"term":"Miming","definition":"Ambulatory Computers are skilled at miming humans and other things (26); Jack Flannagan was better at miming than most AMH Computers (152).","notesPages":[387],"id":"glossary-entry-miming","letter":"M"},{"term":"Miming computers","definition":"Alternative name for Ambulatory Computers, highlighting their imitative abilities (76). See also Ambulatory Mime-Human (AMH) Computers.","notesPages":[387],"id":"glossary-entry-miming-computers","letter":"M"},{"term":"Mind (Axel's)","definition":"Axel Grindstone's mind, unable to survive the shock of discovering the Unfallen People's true appearance (14).","notesPages":[387],"id":"glossary-entry-mind-axels","letter":"M"},{"term":"Mind (of Axel's Ape Alpha)","definition":"Implied to be prophetic and focused on the \"Moment of Awakening\" (51).","notesPages":[387],"id":"glossary-entry-mind-of-axels-ape-alpha","letter":"M"},{"term":"Mind (of God)","definition":"The Kangaroo believes it has found the wide frequencies on which God’s mind operates and narrow frequencies he does not seem to monitor (80). The narrator expressly qualifies the alleged discovery.","notesPages":[387],"id":"glossary-entry-mind-of-god","letter":"M"},{"term":"Mind of Man (The)","definition":"Quoted phrase (from Wordsworth) identifying the poet's haunt and main region of song (35).","notesPages":[387],"id":"glossary-entry-mind-of-man-the","letter":"M"},{"term":"Mind (of Marino)","definition":"Described as incredibly fast and gleaming, equal to Luas in friendliness but perhaps less deep or more flawed in its generated ideas (60).","notesPages":[387],"id":"glossary-entry-mind-of-marino","letter":"M"},{"term":"Mind-transmission","definition":"Method by which Inneall records information into her 'logs' (164).","notesPages":[387],"id":"glossary-entry-mind-transmission","letter":"M"},{"term":"Minds","definition":"Of The Three melded with music (5); of AMH computers seasoned by human common sense (27); of humans studied via schematics (26); hard and flinty minds of Satrap and Livius (70); included in \"The Life Affair\" (74); mega minds of pirates (120).","notesPages":[387],"id":"glossary-entry-minds","letter":"M"},{"term":"Mines","definition":"Ape Caverns connected to old Hickory Coal Mines (45).","notesPages":[387],"id":"glossary-entry-mines","letter":"M"},{"term":"Mines (Coal)","definition":"Old mines under the city predicted as part of the Armageddon battleground (44).","notesPages":[387],"id":"glossary-entry-mines-coal","letter":"M"},{"term":"Mines (Gold)","definition":"Wotto metal mine paid out better (48).","notesPages":[387],"id":"glossary-entry-mines-gold","letter":"M"},{"term":"Miol-Mor","definition":"A member of the \"small and gentle whales misnamed the Killer Whales\"; serves as nurse, governess, and mentor to the Big Egg, communicating with it via clicking-whistle language (160); provides explanations to Inneall (164); asks to read Dubu’s copy of “Ninth Big Book of Fascinating Mysteries” when Dubu finishes with it (162).","notesPages":[388],"id":"glossary-entry-miol-mor","letter":"M"},{"term":"Misdemeanor (Hangable)","definition":"An offense serious enough to warrant execution by hanging under the code of Honor followed by the Natural Nobility; committed by Donatus O'Reily (trying to save a \"Serpent's-Egg\" person) (118) and Hieronymous Zchold, whose specified offense is being a priest of the Old Religion and who is subsequently identified as a bishop (122, 158).","notesPages":[388],"id":"glossary-entry-misdemeanor-hangable","letter":"M"},{"term":"Mishap (Theos')","definition":"The mistake made in creation legend when Man hatched from the Serpent's Egg (36).","notesPages":[388],"id":"glossary-entry-mishap-theos","letter":"M"},{"term":"Mission (Axel's)","definition":"Axel Grindstone's life purpose: to find the Other Eden (11).","notesPages":[388],"id":"glossary-entry-mission-axels","letter":"M"},{"term":"Mission (Dolophonos')","definition":"The task assigned to a Dolophonos, which Lutin predicts will end in failure and death if not abandoned (86).","notesPages":[388],"id":"glossary-entry-mission-dolophonos","letter":"M"},{"term":"Mission (Riesin's)","definition":"The final journey undertaken by the Empress Elephant Riesin to reach the Elephant Graveyard, bury Gajah, and die (94).","notesPages":[388],"id":"glossary-entry-mission-riesins","letter":"M"},{"term":"Mississippi Rivers (Middle and Lower)","definition":"Sections of the Mississippi River whose valleys are being encroached upon by the growing Inneall's Ocean (55). See also Middle Mississippi River.","notesPages":[388],"id":"glossary-entry-mississippi-rivers-middle-and-lower","letter":"M"},{"term":"Mist (Golden)","definition":"A shimmering, shining haze observed over everything at the bottom of the Ocean in the Whale Temple-City (136).","notesPages":[388],"id":"glossary-entry-mist-golden","letter":"M"},{"term":"Mistake (Nature's sole)","definition":"Quoted phrase describing Man (35).","notesPages":[388],"id":"glossary-entry-mistake-natures-sole","letter":"M"},{"term":"Mistake (Theos')","definition":"Error in creation legend where Man hatched from the wrong egg (36).","notesPages":[388],"id":"glossary-entry-mistake-theos","letter":"M"},{"term":"Mists (Mighty)","definition":"Dense fog banks sitting on the rocking sea surface, grouping themselves into arches and cathedral aisles, observed by De Quincey (132).","notesPages":[388],"id":"glossary-entry-mists-mighty","letter":"M"},{"term":"Mocha","definition":"Port city in Arabian Yemen, identified as one end of the original Ape Bridge location (connecting to Assab, Eritrea) (13).","notesPages":[388],"id":"glossary-entry-mocha","letter":"M"},{"term":"Mockingbirds","definition":"Songbirds known for mimicry; participate in the enhanced music choruses at Heart's Desire Cove (58).","notesPages":[389],"id":"glossary-entry-mockingbirds","letter":"M"},{"term":"Modern man","definition":"Term used synonymously with Man (Homo Sapiens), emphasizing there has never been any other sort (34); Neanderthals described as typically big-brained modern men, perhaps \"a little bit too modern\" (40).","notesPages":[389],"id":"glossary-entry-modern-man","letter":"M"},{"term":"Moguls (India)","definition":"Mughal conquerors of India, blamed in the novel’s imaginary elephant history for killing the Empress Elephants (92).","notesPages":[389],"id":"glossary-entry-moguls-india","letter":"M"},{"term":"Moguls (Pirate)","definition":"Exceptionally wealthy and powerful pirate figures who have secret houses under the Ocean (101).","notesPages":[389],"id":"glossary-entry-moguls-pirate","letter":"M"},{"term":"Molecules (Single)","definition":"Form the pathways created and uncreated by wotto metal computer matrices (26); a single molecule of Lanternjaw Lunnigan must remain on the Annabella Saint Ledger as part of his captaincy covenant (119).","notesPages":[389],"id":"glossary-entry-molecules-single","letter":"M"},{"term":"Molt (Apes')","definition":"Some Axel's Apes are losing their yellow body hair alarmingly, causing concern about what the molt signifies (51).","notesPages":[389],"id":"glossary-entry-molt-apes","letter":"M"},{"term":"Moment (Critical)","definition":"The precise instant just after midnight cockcrow when Axel awakens, the brief window during which he is vulnerable before waking the other Apes (145).","notesPages":[389],"id":"glossary-entry-moment-critical","letter":"M"},{"term":"Moment (Final)","definition":"The concluding point in time; possibly reached by the Nine Royal Kids (123).","notesPages":[389],"id":"glossary-entry-moment-final","letter":"M"},{"term":"Moment (Last)","definition":"God pours living fire into Unfallens at the last moment (17); the Theos makes a small rent in the Perfect Creature at the last moment (36).","notesPages":[389],"id":"glossary-entry-moment-last","letter":"M"},{"term":"Moment of the Awakening of the Second People","definition":"The anticipated instant when the Axel's Golden Apes will emerge from Deep Sleep, triggered by Axel waking at midnight; believed by Alpha to be very near (46, 51). See also Awakening (Moment of the Awakening of the Second People).","notesPages":[389],"id":"glossary-entry-moment-of-the-awakening-of-the-second-people","letter":"M"},{"term":"Moment (Special)","definition":"A person might be a member of the Kangaroo only for special moments (83).","notesPages":[389],"id":"glossary-entry-moment-special","letter":"M"},{"term":"Moments (Mournful)","definition":"Periods of sadness and withdrawal experienced by Lutin during the latter days of the End of Summer (62).","notesPages":[390],"id":"glossary-entry-moments-mournful","letter":"M"},{"term":"Money","definition":"Saved by sketchy animation in prowls (6); made from talented but simple-minded Unfallens (18); Satrap's money buys weapons (95); not notably expended in Floating World travel (79).","notesPages":[390],"id":"glossary-entry-money","letter":"M"},{"term":"Money Mart ratings","definition":"Financial ranking system placing Satrap Saint Ledger as the eleventh richest man in the world, just qualifying for Midas Class (135).","notesPages":[390],"id":"glossary-entry-money-mart-ratings","letter":"M"},{"term":"Monitoring (Dolophonos)","definition":"The fourth Dolophonos was assigned to monitor the Children of the Experiments, but Riesin suspected he meant to kill (89).","notesPages":[390],"id":"glossary-entry-monitoring-dolophonos","letter":"M"},{"term":"Monkey Charley's Bait Shop","definition":"Schimp's chosen name for the bait shop he purchased (161).","notesPages":[390],"id":"glossary-entry-monkey-charleys-bait-shop","letter":"M"},{"term":"Monkey (Upside down)","definition":"Metaphorical description of Man having lost his way, from the poem epigraph for Chapter Four (34).","notesPages":[390],"id":"glossary-entry-monkey-upside-down","letter":"M"},{"term":"Monomonia","definition":"Obsession with a single idea; Ansel Grindstone predicts his son Axel will be prone to this (10).","notesPages":[390],"id":"glossary-entry-monomonia","letter":"M"},{"term":"Monster (Nightmare Monster)","definition":"Alternative name for the pseudo-fish Chimaera Monstrusa, also known as the Sea-Cat (139).","notesPages":[390],"id":"glossary-entry-monster-nightmare-monster","letter":"M"},{"term":"Monster (Ocean Monster/Obscenity)","definition":"Satrap Saint Ledger's self- description or state when transformed for deep ocean diving (135, 137); depicted as such in the tapestry The Midas Satrap Saint Ledger As An Obscene Sea Monster (144, 147).","notesPages":[390],"id":"glossary-entry-monster-ocean-monster-obscenity","letter":"M"},{"term":"Monsters (Dolophonoi-monsters)","definition":"Term used by Iris Lynn-Randal for the assassins she and her companions hunt (84).","notesPages":[390],"id":"glossary-entry-monsters-dolophonoi-monsters","letter":"M"},{"term":"Monsters (Those)","definition":"Term used by the three monster-hunters (Iris, Shadrack, Gregor) referring to the four Dolophonoi they wait to ambush (89).","notesPages":[390],"id":"glossary-entry-monsters-those","letter":"M"},{"term":"Montdrago, Rose-of-Sharon","definition":"See Rose-of-Sharon Montdrago.","notesPages":[390],"id":"glossary-entry-montdrago-rose-of-sharon","letter":"M"},{"term":"Monument","definition":"Potentially what the Whales are building on the Ocean Bottom (106); small monuments are central to the Whale Tau-Temple Complex (137).","notesPages":[391],"id":"glossary-entry-monument","letter":"M"},{"term":"Moods (Language)","definition":"The unnamed AMH theorist claims that many languages formerly had thirteen moods but now have three (37).","notesPages":[391],"id":"glossary-entry-moods-language","letter":"M"},{"term":"Moon","definition":"Location of Computer-only colonies (59); Carcajou's man-devil form appears when the moon is full (73).","notesPages":[391],"id":"glossary-entry-moon","letter":"M"},{"term":"Moon colonies","definition":"Settlements on the Moon inhabited exclusively by Computers, as humans cannot survive there without elaborate support systems (59).","notesPages":[391],"id":"glossary-entry-moon-colonies","letter":"M"},{"term":"\"Moon People Vaunt\" (Song)","definition":"A song sung nightly by some Computers, boasting of their ability to live on the Moon; always caused friction with humans (59).","notesPages":[391],"id":"glossary-entry-moon-people-vaunt-song","letter":"M"},{"term":"Moravia","definition":"Historical region in Central Europe; source, along with other European regions, of the nine master stonemasons who legendarily learned advanced techniques in Second Eden (13).","notesPages":[391],"id":"glossary-entry-moravia","letter":"M"},{"term":"Morning wine","definition":"Wine consumed in the morning; the Unfallen People perform hundreds of hours of work for grapes to make their morning wine, after which they appear drunk to humans (16-17).","notesPages":[391],"id":"glossary-entry-morning-wine","letter":"M"},{"term":"Mortar","definition":"Notably absent in the key-locked stone bridge built by the Unfallen Ones (15).","notesPages":[391],"id":"glossary-entry-mortar","letter":"M"},{"term":"Mosaic setting","definition":"One of the arts abandoned by humans but reinvented by Computers (33).","notesPages":[391],"id":"glossary-entry-mosaic-setting","letter":"M"},{"term":"Mother (Dubu as 'Little Mother')","definition":"See Little Mother (Dubu).","notesPages":[391],"id":"glossary-entry-mother-dubu-as-little-mother","letter":"M"},{"term":"Mother (Elephant)","definition":"See Elephant (Mother); Riesin.","notesPages":[391],"id":"glossary-entry-mother-elephant","letter":"M"},{"term":"Mother (Foster)","definition":"See Foster mothers.","notesPages":[391],"id":"glossary-entry-mother-foster","letter":"M"},{"term":"Mother (Riesin)","definition":"See Riesin.","notesPages":[391],"id":"glossary-entry-mother-riesin","letter":"M"},{"term":"Mother Used to Make It (Choc Beer)","definition":"Slogan describing the nostalgic quality of Choc Beer available at Heart's Desire Cove (58).","notesPages":[391],"id":"glossary-entry-mother-used-to-make-it-choc-beer","letter":"M"},{"term":"Motif (Rotation)","definition":"All machines are noted as being strong on the rotation motif, explaining the constant rotation of the condominium clubroom (74).","notesPages":[392],"id":"glossary-entry-motif-rotation","letter":"M"},{"term":"Mottos (Wood-carved)","definition":"One of the arts abandoned by humans but reinvented by Computers (33).","notesPages":[392],"id":"glossary-entry-mottos-wood-carved","letter":"M"},{"term":"Mould","definition":"Consumed by experimental hogs in The Three's habitat, growing on rotten wood and rocks (3).","notesPages":[392],"id":"glossary-entry-mould","letter":"M"},{"term":"Mountain (Ideal)","definition":"Perfect mountain setting for addressing crowds, unavailable to Invisible Alfred or the Christus (109).","notesPages":[392],"id":"glossary-entry-mountain-ideal","letter":"M"},{"term":"Mountain (of the Commandments)","definition":"Mount Sinai, where God spoke to Moses, cited by Invisible Alfred as an instance where only God's eyes and mouth were visible (110).","notesPages":[392],"id":"glossary-entry-mountain-of-the-commandments","letter":"M"},{"term":"Mountain yew trees","definition":"Trees from which the Asiatic man cuts boughs to cover Riesin's body in the Elephant Graveyard (95).","notesPages":[392],"id":"glossary-entry-mountain-yew-trees","letter":"M"},{"term":"Mountains","definition":"Possess high and harsh beauty like angels (17); high mountains border the road to the Elephant Graveyard (93); removing mountains considered a trifle by preternatural powers (112).","notesPages":[392],"id":"glossary-entry-mountains","letter":"M"},{"term":"Mountains (Wichita)","definition":"Source of the granite used by Whales in their underwater constructions (137).","notesPages":[392],"id":"glossary-entry-mountains-wichita","letter":"M"},{"term":"Mountains (Winding Stair)","definition":"Location where one can find bears who know everything and give the \"All-Knowing Wink\" (75).","notesPages":[392],"id":"glossary-entry-mountains-winding-stair","letter":"M"},{"term":"Mountebank","definition":"Invisible Alfred perceived as such by the Pleasure People (109, 112).","notesPages":[392],"id":"glossary-entry-mountebank","letter":"M"},{"term":"Mourned (Inneall)","definition":"Inneall mourned that Invisible Alfred had been in the crows-nest overhearing their plans (149).","notesPages":[392],"id":"glossary-entry-mourned-inneall","letter":"M"},{"term":"Mouth (Alfred's)","definition":"Facial orifice of the Prophet Invisible Alfred; the inside is visible only when he speaks (109, 110); closed when he becomes completely invisible (112, 113).","notesPages":[392],"id":"glossary-entry-mouth-alfreds","letter":"M"},{"term":"Mouth (God’s)","definition":"Invisible Alfred claims that only God’s eyes and the inside of his mouth were visible when he spoke from the Burning Bush, Whirlwind, or Mountain of the Commandments (110). This is Alfred’s account, not a biblical description.","notesPages":[392],"id":"glossary-entry-mouth-gods","letter":"M"},{"term":"Mouths (Boney)","definition":"Skeletal jaws from which skeletons aboard ghost ships are said to talk (114).","notesPages":[393],"id":"glossary-entry-mouths-boney","letter":"M"},{"term":"Movement (Geometric forms)","definition":"Dynamic quality conveyed by the rapidly moving abstract shapes representing characters in 'prowls' (6).","notesPages":[393],"id":"glossary-entry-movement-geometric-forms","letter":"M"},{"term":"Movement (Leveller)","definition":"See Leveller Movement.","notesPages":[393],"id":"glossary-entry-movement-leveller","letter":"M"},{"term":"Movement (Roy Latta's)","definition":"Term used by reporter Roy Latta when questioning the \"Royal Kids\" about their association with the \"phoney\" Invisible Alfred (113).","notesPages":[393],"id":"glossary-entry-movement-roy-lattas","letter":"M"},{"term":"Movie house (Apes')","definition":"Entertainment venue in Ape Alley showing only silent movies, often featuring Axel's Apes (45). See also Movie Theatre (Apes').","notesPages":[393],"id":"glossary-entry-movie-house-apes","letter":"M"},{"term":"Movie Theatre (Apes')","definition":"Stands empty during the \"Holy Sleep\" (46, 67). See also Movie house (Apes').","notesPages":[393],"id":"glossary-entry-movie-theatre-apes","letter":"M"},{"term":"Moving parts (Kangaroo)","definition":"Components of the Kangaroo organization; described as the fewest possible number, contributing to its elitist Vigilante nature (80).","notesPages":[393],"id":"glossary-entry-moving-parts-kangaroo","letter":"M"},{"term":"Mud marks","definition":"Imprints made by Axel on the transparent sky-cover using mud-tipped arrows to convey a message (4).","notesPages":[393],"id":"glossary-entry-mud-marks","letter":"M"},{"term":"Mud (Nutrient)","definition":"Rich sediment forming in streams and pools within The Three's habitat, formed faster than the experimental fish could consume it (3).","notesPages":[393],"id":"glossary-entry-mud-nutrient","letter":"M"},{"term":"Mulch","definition":"Consumed by experimental hogs, found on rocks (3).","notesPages":[393],"id":"glossary-entry-mulch","letter":"M"},{"term":"Mullets","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[393],"id":"glossary-entry-mullets","letter":"M"},{"term":"Multiple Run-Amoks","definition":"Inneall's self-diagnosed \"happy sickness,\" suggesting she is prone to uncontrolled, complex actions or projects (like ocean-making), for which she suspects the only cure is death (50, 59).","notesPages":[393],"id":"glossary-entry-multiple-run-amoks","letter":"M"},{"term":"Multitudes","definition":"Addressed by Invisible Alfred from shipboard (109, 110).","notesPages":[393],"id":"glossary-entry-multitudes","letter":"M"},{"term":"Murder","definition":"Unfallen People incapable of it (12); practiced by Dolophonoi (149); talent possessed by Donatus O'Reily (157).","notesPages":[393],"id":"glossary-entry-murder","letter":"M"},{"term":"Murder-and-horror novels","definition":"Dubu the bear's primary reading material (124).","notesPages":[394],"id":"glossary-entry-murder-and-horror-novels","letter":"M"},{"term":"Murder mysteries","definition":"Genre of fiction enjoyed by Dubu (124, 128); the events at Persimmon Manor constitute a real one (128), temporarily ruined by Dubu stopping the killings (128, 153).","notesPages":[394],"id":"glossary-entry-murder-mysteries","letter":"M"},{"term":"Murder-plotting (Alfred)","definition":"Invisible Alfred accused by Carcajou of engaging in this while invisibly eavesdropping (149).","notesPages":[394],"id":"glossary-entry-murder-plotting-alfred","letter":"M"},{"term":"Murdered ones (Axel, Randal)","definition":"Term used by Inneall when preparing to take the bodies of Axel and Lord Randal to their cenotaphs (148).","notesPages":[394],"id":"glossary-entry-murdered-ones-axel-randal","letter":"M"},{"term":"Murderers","definition":"Question of why they stopped at Persimmon Manor (153).","notesPages":[394],"id":"glossary-entry-murderers","letter":"M"},{"term":"Murderous deaths","definition":"Fate indicated by dreams and portents for Lord Randal and Inneall, worrying Iris (84).","notesPages":[394],"id":"glossary-entry-murderous-deaths","letter":"M"},{"term":"Murders","definition":"Nine committed sequentially at Persimmon Manor, one each hour from 4 AM to 12 noon (128); have ceased by 1 PM, causing grumbling among guests (128, 153).","notesPages":[394],"id":"glossary-entry-murders","letter":"M"},{"term":"Mushroom wine","definition":"See Wine (Mushroom).","notesPages":[394],"id":"glossary-entry-mushroom-wine","letter":"M"},{"term":"Music","definition":"Encountered by The Three in the Lynn-Randal house (5); lacks melody, irritating adults (8); Computer-Enhanced Human Music attracts birds (57); cosmic music characterizes immediate present- times (71); calliope music attracts crowds and Assassins (85); song \"Moon People Vaunt\" causes friction (59).","notesPages":[394],"id":"glossary-entry-music","letter":"M"},{"term":"Music (Cosmic)","definition":"Quality of singing immediacy characteristic of the eternal present-times created by Ambulatory Computers (71).","notesPages":[394],"id":"glossary-entry-music-cosmic","letter":"M"},{"term":"Music (Piano)","definition":"Composed without regard for human hand limitations, played by player pianos (25); Luas plays piano with strange effect (77).","notesPages":[394],"id":"glossary-entry-music-piano","letter":"M"},{"term":"Musics (Old)","definition":"Ancient forms of music discovered by The Three along with old literatures, arts, and dramas (9).","notesPages":[394],"id":"glossary-entry-musics-old","letter":"M"},{"term":"Mustang (Realm)","definition":"Small realm located in the high foothills north of India, site of the Elephant Graveyard (93).","notesPages":[394],"id":"glossary-entry-mustang-realm","letter":"M"},{"term":"Myriad-throated choirs (birds)","definition":"Vast assemblages of birds gathered and inspired to sing by the Birdmaster (60).","notesPages":[395],"id":"glossary-entry-myriad-throated-choirs-birds","letter":"M"},{"term":"Mysteries","definition":"Dubu loves solving them (162); Inneall hates them (162); the Big Egg is a mystery (162, 163); solved by Dubu (153, 157, 163); interlocking spheres of mysteries (162).","notesPages":[395],"id":"glossary-entry-mysteries","letter":"M"},{"term":"Mysteries (Fascinating)","definition":"“Ninth Big Book of Fascinating Mysteries,” the book Dubu is reading and Miol-Mor asks to borrow (162).","notesPages":[395],"id":"glossary-entry-mysteries-fascinating","letter":"M"},{"term":"Mysterious Gargoyles","definition":"The enigmatic carved figures on cathedrals, signs left by the Unfallen People (13).","notesPages":[395],"id":"glossary-entry-mysterious-gargoyles","letter":"M"},{"term":"Mystery (Gripping murder)","definition":"Donatus O'Reily describes the series of murders he committed as such (157).","notesPages":[395],"id":"glossary-entry-mystery-gripping-murder","letter":"M"},{"term":"Mystery (of Big Egg)","definition":"The puzzle surrounding the origin and nature of the enormous egg that appears while Lutin and her midwife sleep; solved by Dubu (162, 163).","notesPages":[395],"id":"glossary-entry-mystery-of-big-egg","letter":"M"},{"term":"Mystery play","definition":"Inneall compares watching unfolding events to this (113).","notesPages":[395],"id":"glossary-entry-mystery-play","letter":"M"},{"term":"Mystery (Solved murder)","definition":"Dubu claims to have solved the Persimmon Manor murder mystery (153, 157).","notesPages":[395],"id":"glossary-entry-mystery-solved-murder","letter":"M"},{"term":"Mystery stories","definition":"Genre of fiction involving puzzles and suspense; Dubu contrasts reading these with reading \"intelligent books\" (162).","notesPages":[395],"id":"glossary-entry-mystery-stories","letter":"M"},{"term":"Mystery story","definition":"Watching things unfold is like a mystery story (113).","notesPages":[395],"id":"glossary-entry-mystery-story","letter":"M"},{"term":"Mystic (Satrap as)","definition":"Satrap Saint Ledger possesses a touch of the mystic, enabling him to understand the concept of the \"jog in the road\" for bi-location (93).","notesPages":[395],"id":"glossary-entry-mystic-satrap-as","letter":"M"},{"term":"Mystique of Life","definition":"The most that can be hoped for regarding understanding existence, according to Lutin, as opposed to a forbidden Theology or even a Rationale of Life (141).","notesPages":[395],"id":"glossary-entry-mystique-of-life","letter":"M"},{"term":"Myth (Under-dog favor)","definition":"The common belief that most people favor the underdog is declared a myth; almost everybody sides with the top- dog (50).","notesPages":[395],"id":"glossary-entry-myth-under-dog-favor","letter":"M"},{"term":"Mythical common people","definition":"Archetypal ordinary folk referred to in assessing the popularity of the \"Funny-Faced Apes\" (44).","notesPages":[396],"id":"glossary-entry-mythical-common-people","letter":"M"},{"term":"Mythological roots (Ambulatories)","definition":"The origins of Ambulatory Computers traced by Livius Secundus to the devious under-minds and weird crypto-memory caves of the human species (70).","notesPages":[396],"id":"glossary-entry-mythological-roots-ambulatories","letter":"M"},{"term":"Mythology (Ape Wakening)","definition":"The body of belief concerning the awakening of the Axel's Golden Apes, including variants regarding the time (midnight vs. cockcrow) (142).","notesPages":[396],"id":"glossary-entry-mythology-ape-wakening","letter":"M"},{"term":"Nacre","definition":"Used as a beautiful, thin plating by the sea-lice to cover the completed faces they sculpt onto the Whales' stone constructions (138). Mother-of-pearl.","notesPages":[396],"id":"glossary-entry-nacre","letter":"N"},{"term":"Napier, John","definition":"Scottish mathematician (1550-1617), inventor of the numbered calculating rods called Napier’s Bones, described in 1617. The novel loosely calls these an abacus (25).","notesPages":[396],"id":"glossary-entry-napier-john","letter":"N"},{"term":"Napier’s Bones","definition":"Numbered calculating rods described by John Napier in 1617; sets could be made of bone, ivory, wood, or other materials. The novel describes ivory tabs (25).","notesPages":[396],"id":"glossary-entry-napiers-bones","letter":"N"},{"term":"Narrow But Sharp Frequencies (Kangaroo)","definition":"Specific communication wavelengths allegedly unused or unmonitored by the Mind of God, which the Kangaroo discovered and utilizes for its secret operations (80).","notesPages":[396],"id":"glossary-entry-narrow-but-sharp-frequencies-kangaroo","letter":"N"},{"term":"National Examinations","definition":"Standardized tests in Ethiopia; the current Prime Minister achieved an incredibly high score on these, enabling his rise, after receiving instruction from the Unfallen Ones (15).","notesPages":[396],"id":"glossary-entry-national-examinations","letter":"N"},{"term":"Nations","definition":"Ceased to be grounded and began floating in the air after the Kangaroo cut their underpinnings (79); the term becomes obsolete (\"'nations' no longer\") as they drift together (79).","notesPages":[396],"id":"glossary-entry-nations","letter":"N"},{"term":"Nations of the Fishes","definition":"The collective populations of fish species from the entire \"old Oceanic World\"; they flock to explore the new and unknown waters of Inneall's Ocean (138).","notesPages":[397],"id":"glossary-entry-nations-of-the-fishes","letter":"N"},{"term":"Native state (Water-falls)","definition":"The original, natural condition of the waterfalls in The Three's habitat, before the addition of unnatural elements like water-recirculating tubes (3).","notesPages":[397],"id":"glossary-entry-native-state-water-falls","letter":"N"},{"term":"Nativity (Man's)","definition":"Place of origin or birth; Man is questioned why he fits badly in the world of his nativity and cannot occupy other parts of it (41).","notesPages":[397],"id":"glossary-entry-nativity-mans","letter":"N"},{"term":"Natural","definition":"Applies to feral land (3), the order of things (4, 78), interlocking support systems (3), state of bears (75), death (20), Nobility (118), languages (implied contrast with artificial) (64), talent (implied) (96). Occurring in or derived from nature, not artificial.","notesPages":[397],"id":"glossary-entry-natural","letter":"N"},{"term":"Natural Death (Apes')","definition":"Mode of death impossible for the Axel's Apes, who are immune to sickness or natural death (20, 21).","notesPages":[397],"id":"glossary-entry-natural-death-apes","letter":"N"},{"term":"Natural Nobility","definition":"A self-declared or recognized status group within the Floating World, possessing a code of Honor that mandates specific rituals for executing members who commit hangable misdemeanors (e.g., hanging by friends) (118). Donatus O'Reily is a member (118).","notesPages":[397],"id":"glossary-entry-natural-nobility","letter":"N"},{"term":"Natural order of things","definition":"The inherent, proper arrangement of the world; the reinforcing wire in the vines and the water-recirculating tubes are not part of it (4); Maritain predicts the State's overreach will turn the natural order upside down, making men servants of the State (78).","notesPages":[397],"id":"glossary-entry-natural-order-of-things","letter":"N"},{"term":"Natural state (Bears)","definition":"Many bears in their natural state \"know everything\" according to Dubu (75). Wild condition.","notesPages":[397],"id":"glossary-entry-natural-state-bears","letter":"N"},{"term":"Naturalist (Felix)","definition":"Felix Culebra y Columba is described as a naturalist, in love with all creatures of every sort (71); he arrives at Tom Dooley's Island as the Compassionate Naturalist (115).","notesPages":[397],"id":"glossary-entry-naturalist-felix","letter":"N"},{"term":"Nature (Fundamental, of Computers)","definition":"The basic essence and characteristics of computers; subject of a dissertation section (24) and a question regarding their adoption of astrology (29).","notesPages":[397],"id":"glossary-entry-nature-fundamental-of-computers","letter":"N"},{"term":"Nature (Fundamental, of Inneall)","definition":"The core identity of Inneall, the Rogue Girl Computer, which looms large in the dissertation section on computers (24).","notesPages":[398],"id":"glossary-entry-nature-fundamental-of-inneall","letter":"N"},{"term":"Nature (Fundamental, of Species)","definition":"The basic characteristics of pythons and parrots, about which Satrap professes no expertise (134).","notesPages":[398],"id":"glossary-entry-nature-fundamental-of-species","letter":"N"},{"term":"Nature (True, of Knives)","definition":"The actual composition (leucotomized humans, irascible computers, or aberrant animals) of the Dolophonoi/Assassins, kept very secret by those who employ them (82).","notesPages":[398],"id":"glossary-entry-nature-true-of-knives","letter":"N"},{"term":"Nature's Sole Mistake (Man)","definition":"Quoted phrase describing the human species (35).","notesPages":[398],"id":"glossary-entry-natures-sole-mistake-man","letter":"N"},{"term":"Near Asia","definition":"Geographical region mentioned, along with Africa of the Horn, as a possible location sought by Axel Grindstone for the Other Eden (11).","notesPages":[398],"id":"glossary-entry-near-asia","letter":"N"},{"term":"Near-invisibility","definition":"A state of being almost completely unseen, achieved by Invisible Alfred through power drawn from paint residue; described as a two-sided gift that also enhances the user's perception of normally invisible things like thoughts (110).","notesPages":[398],"id":"glossary-entry-near-invisibility","letter":"N"},{"term":"Nebraska","definition":"US state over whose plains migrating birds fly south; birds can bi-locate from here to Honduras while daydreaming (95).","notesPages":[398],"id":"glossary-entry-nebraska","letter":"N"},{"term":"Necessary","definition":"Complexity in ancient languages deemed possibly unnecessary (37); common sense considered not really necessary by an AMH theorist (26); intuitive evasive actions will be taken if necessary (145).","notesPages":[398],"id":"glossary-entry-necessary","letter":"N"},{"term":"Nervous (Climate between Inneall and Satrap)","definition":"Inneall’s description of their relationship during her initial negotiation with Satrap Saint Ledger over the yacht (\"Nervous, midas Satrap Saint Leger, it's a little bit nervous between us\") (48).","notesPages":[398],"id":"glossary-entry-nervous-climate-between-inneall-and-satrap","letter":"N"},{"term":"Nervous man (Priest)","definition":"Description of Hieronymous Ignatius Zchold, the Priest (later revealed as Bishop) of the Old Religion sentenced to death, emphasizing his anxiety (121, 122).","notesPages":[398],"id":"glossary-entry-nervous-man-priest","letter":"N"},{"term":"Nest (Crows-nest)","definition":"See Crows-nest.","notesPages":[398],"id":"glossary-entry-nest-crows-nest","letter":"N"},{"term":"Nestor Notabilis","definition":"Scientific name for the Kea or Nestor Parrot of New Zealand, the species to which Popugai belongs (64).","notesPages":[399],"id":"glossary-entry-nestor-notabilis","letter":"N"},{"term":"Nestor Parrot","definition":"Alternative name for the Kea parrot (Nestor Notabilis) (64).","notesPages":[399],"id":"glossary-entry-nestor-parrot","letter":"N"},{"term":"Nests (Dolophonoi)","definition":"Dwelling places of the Dolophonoi-Assassins assigned to the Four Experiments, located in the newly formed rock cliffs just north of Inneall's Ocean (84, 85); the assassins return to their nests to retrieve specialized weapons (python-gun, angel-gun, wolverene-were-gun) (87, 88, 89).","notesPages":[399],"id":"glossary-entry-nests-dolophonoi","letter":"N"},{"term":"Neutral commentator","definition":"The narrator tentatively proposes an AMH specialist as a neutral observer of humanity (36). The ensuing interview, with its professed disbelief in humans, gives grounds to question that neutrality (38-39).","notesPages":[399],"id":"glossary-entry-neutral-commentator","letter":"N"},{"term":"New amenities (Floating World)","definition":"Conveniences made possible by the Floating World, such as nearly free-cost daily commuting between Australia and New York, or coffee breaks in Paris and Rio de Janeiro (79).","notesPages":[399],"id":"glossary-entry-new-amenities-floating-world","letter":"N"},{"term":"New Barbarians","definition":"See Barbarians (New).","notesPages":[399],"id":"glossary-entry-new-barbarians","letter":"N"},{"term":"\"New Directions Ramble\" (Song)","definition":"A campfire song sung at Heart's Desire Cove (59).","notesPages":[399],"id":"glossary-entry-new-directions-ramble-song","letter":"N"},{"term":"New Eden Hotel","definition":"See Eden (New Eden Hotel).","notesPages":[399],"id":"glossary-entry-new-eden-hotel","letter":"N"},{"term":"\"New Entity Rock\" (Song)","definition":"A campfire song sung at Heart's Desire Cove (59).","notesPages":[399],"id":"glossary-entry-new-entity-rock-song","letter":"N"},{"term":"New eyes","definition":"Seeing the world with new eyes (but not too cockeyed new) was the instruction given (2, 141); provided by the state of Oceanic Metastasis (135).","notesPages":[399],"id":"glossary-entry-new-eyes","letter":"N"},{"term":"New Ocean","definition":"See Ocean (Inneall's/New); Inneall's Ocean.","notesPages":[399],"id":"glossary-entry-new-ocean","letter":"N"},{"term":"New Ocean Syndrome","definition":"Satrap Saint Ledger's term for the collection of strange phenomena occurring in and around Inneall's Ocean, including the Whales' building activities (136).","notesPages":[399],"id":"glossary-entry-new-ocean-syndrome","letter":"N"},{"term":"New Oceanside","definition":"The area formerly known as Heart's Desire Cove, after its original cove shape was obliterated by the growing Ocean; site where Invisible Alfred addresses the crowd (109).","notesPages":[400],"id":"glossary-entry-new-oceanside","letter":"N"},{"term":"New people","definition":"The inhabitants of the \"post-postliterate age,\" characterized by their inability to recognize satire, irony, rhyme, or melody (8).","notesPages":[400],"id":"glossary-entry-new-people","letter":"N"},{"term":"\"New Rice Feeds the Far-Flung World! (Oh)\" (Song)","definition":"A campfire song sung at Heart's Desire Cove (59).","notesPages":[400],"id":"glossary-entry-new-rice-feeds-the-far-flung-world-oh-song","letter":"N"},{"term":"New ways of looking at the world","definition":"The purpose of the Lynn-Randal experiment, leaked to George Lynn-Randal, specified as \"New ways... but not too cockeyed new\" (2).","notesPages":[400],"id":"glossary-entry-new-ways-of-looking-at-the-world","letter":"N"},{"term":"New York City","definition":"Major US city mentioned as a possible daily commute destination from Australia in the Floating World (79).","notesPages":[400],"id":"glossary-entry-new-york-city","letter":"N"},{"term":"New Zealand","definition":"Island nation, home of the Kea (Nestor) parrot species (64); Popugai plans to return there to practice Interspecies Counseling (161).","notesPages":[400],"id":"glossary-entry-new-zealand","letter":"N"},{"term":"Newcomers (to Second Eden Valley)","definition":"The group of men, likely zoo suppliers or exploiters, who followed Axel Grindstone to Second Eden, intending to capture the \"blue-eyed yellow apes\"; they brought scanners and equipment, captured 500 Apes plus the newborn Axel, and facilitated their dispersal (18, 19).","notesPages":[400],"id":"glossary-entry-newcomers-to-second-eden-valley","letter":"N"},{"term":"Newspaper (Apes' Alley)","definition":"Publication printed within Ape Alley for all the inhabitants of the caverns (46).","notesPages":[400],"id":"glossary-entry-newspaper-apes-alley","letter":"N"},{"term":"Nexus (Computer idea)","definition":"The central connection point or core concept within a computer's thought process; theoretically, a single small computer with a single small idea in its nexus could convert the world (27).","notesPages":[400],"id":"glossary-entry-nexus-computer-idea","letter":"N"},{"term":"Nickname ('Tarzan')","definition":"Name sometimes used by Inneall for Ruddy Lord Randal, based on the old book-movie comic-strip character, reflecting his Jungle-Boy type qualities (123).","notesPages":[400],"id":"glossary-entry-nickname-tarzan","letter":"N"},{"term":"Night","definition":"Time when lightning strikes gas jets (45, 68); preferred time for applying Invisible Paint (97, 104); time of bonfires (58); time when Lutin digs concealed tunnels at night (65); show times in Structo Lane (76); night of icy winds on cliffs (16); Third Night of Summerset begins (140).","notesPages":[400,401],"id":"glossary-entry-night","letter":"N"},{"term":"Night-fire","definition":"The traditional holy blaze lit nightly in Ape Caverns by lightning (68).","notesPages":[401],"id":"glossary-entry-night-fire","letter":"N"},{"term":"Night (Last, of Summerset)","definition":"The third and final night of Summerset (140, 151).","notesPages":[401],"id":"glossary-entry-night-last-of-summerset","letter":"N"},{"term":"Night (Second, of Summerset)","definition":"The night during which the Nine paint the ship, explicitly called the Second Night as it ends (104). Invisible Alfred’s public sermons follow during daylight (107-114).","notesPages":[401],"id":"glossary-entry-night-second-of-summerset","letter":"N"},{"term":"Nightmare Monster","definition":"Pseudo-fish also known, more pleasantly, as the Sea-Cat (139).","notesPages":[401],"id":"glossary-entry-nightmare-monster","letter":"N"},{"term":"Nightmares (Sharks')","definition":"Bad dreams habitually experienced by sharks during their 'sleep' (138).","notesPages":[401],"id":"glossary-entry-nightmares-sharks","letter":"N"},{"term":"Nine","definition":"The experimental children remaining when Axel sleeps, Gajah has died, and Luas has departed (103-104, 115). They sail and paint the ship, visit Persimmon Manor, dive, hold a Council of War, and enter the Cenaculum (103-147). After Axel and Randal are attacked, four carry their bodies to the ocean floor; Henryetta is killed there, leaving Inneall, Carcajou, and Schimp to return to shore (148-151).","notesPages":[401],"id":"glossary-entry-nine","letter":"N"},{"term":"Nine-Goal Player (St. Brandon)","definition":"The novel’s fanciful rating for Saint Brandon, who is said to be the only player to carry it (65). The passage does not define an actual hurling rating system.","notesPages":[402],"id":"glossary-entry-nine-goal-player-st-brandon","letter":"N"},{"term":"Nine hundred human languages","definition":"Number of languages traced back by computer research, all showing devolution from complexity to sketchiness (37).","notesPages":[401],"id":"glossary-entry-nine-hundred-human-languages","letter":"N"},{"term":"Nine stone-masters","definition":"Number of master craftsmen from various parts of Europe who, according to one version of the Cathedral Legend, were admitted to Second Eden for a year to learn advanced stonework from the Unfallen Masters (13).","notesPages":[401],"id":"glossary-entry-nine-stone-masters","letter":"N"},{"term":"Nine (The Nine)","definition":"Designation sometimes used for the group that The Three might eventually join, presumably formed from merging multiple experiments (8).","notesPages":[401],"id":"glossary-entry-nine-the-nine","letter":"N"},{"term":"Nine thousand years","definition":"Approximate age of Mankind according to Axel Grindstone's creationist beliefs (11); the period elapsed since dogs and a few other animals last talked, coinciding with the time Invisible Alfred spent in the paint drum (124); period during which giant submarine structures have been built unnoticed (131).","notesPages":[401,402],"id":"glossary-entry-nine-thousand-years","letter":"N"},{"term":"Nine-way birthday party","definition":"The celebration planned by Inneall for the Nine Royal Kids in the condominium clubroom just before midnight (144).","notesPages":[402],"id":"glossary-entry-nine-way-birthday-party","letter":"N"},{"term":"Ninety-eight cannons (Golden Hind)","definition":"The number of conventional cannons aboard the pirate ship Golden Hind, serving primarily for appearance; the real damage was done by the single enchanted ninety- ninth cannon (96).","notesPages":[402],"id":"glossary-entry-ninety-eight-cannons-golden-hind","letter":"N"},{"term":"Ninety-ninth cannon (Golden Hind)","definition":"The special enchanted cannon from the pirate ship Golden Hind, acquired for the Annabella Saint Ledger; its seven self-perpetuating annihilation shells can hit any ordered target anywhere on Earth (95-6).","notesPages":[402],"id":"glossary-entry-ninety-ninth-cannon-golden-hind","letter":"N"},{"term":"Ninety percent (Male AMHs)","definition":"The proportion of Ambulatory Computers who had declared themselves male, leading to demands for gender parity by the female ten percent (69).","notesPages":[402],"id":"glossary-entry-ninety-percent-male-amhs","letter":"N"},{"term":"\"No Government is the Best Government\" (Slogan)","definition":"Political maxim that still \"rings hollow\" but less so as it fills with \"bilge\" in the context of the Floating World (79).","notesPages":[402],"id":"glossary-entry-no-government-is-the-best-government-slogan","letter":"N"},{"term":"Nobility (Natural)","definition":"See Natural Nobility.","notesPages":[402],"id":"glossary-entry-nobility-natural","letter":"N"},{"term":"Nobility (Patent of, Marble)","definition":"A metaphorical \"Patent of Nobility\" conferred upon limestone by a sea change, transforming it into marble, the favorite building material of Whales (136).","notesPages":[402],"id":"glossary-entry-nobility-patent-of-marble","letter":"N"},{"term":"Noble Nine","definition":"Term used for the remaining experimental children when they descend from the crows-nest (145).","notesPages":[402],"id":"glossary-entry-noble-nine","letter":"N"},{"term":"Noble ship","definition":"Designation for the Annabella Saint Ledger (104).","notesPages":[402],"id":"glossary-entry-noble-ship","letter":"N"},{"term":"Noise (Good Noise)","definition":"Background sounds (wind, thunder, animal cries) considered acceptable ambiance even for quiet indoor scenes in media 'prowls' (6).","notesPages":[402],"id":"glossary-entry-noise-good-noise","letter":"N"},{"term":"Non-Axelians","definition":"Individuals not belonging to the Axel's Ape species or community; most were asked to leave Ape Caverns before the \"Holy Sleep\" began (67).","notesPages":[403],"id":"glossary-entry-non-axelians","letter":"N"},{"term":"Non-ethnic","definition":"Belonging to the \"old species\" before the universal adoption of ethnic identities; descriptive of Axel Albert Grindstone (10).","notesPages":[403],"id":"glossary-entry-non-ethnic","letter":"N"},{"term":"Non-humans","definition":"Satrap Saint Ledger says midwifery is not something non-humans should dabble in (154).","notesPages":[403],"id":"glossary-entry-non-humans","letter":"N"},{"term":"Non-live","definition":"The metallic wire reinforcing the swinging vines is described as non-live (4).","notesPages":[403],"id":"glossary-entry-non-live","letter":"N"},{"term":"Noose","definition":"Placed loosely around Donatus O'Reily's neck before being tightened by his seconds (157).","notesPages":[403],"id":"glossary-entry-noose","letter":"N"},{"term":"Normal human caution","definition":"Stated as lacking in the Dolophonoi-Assassins (50).","notesPages":[403],"id":"glossary-entry-normal-human-caution","letter":"N"},{"term":"Normal human fear","definition":"Stated as lacking in the Dolophonoi-Assassins (50).","notesPages":[403],"id":"glossary-entry-normal-human-fear","letter":"N"},{"term":"North America","definition":"Continent whose Indigenous peoples developed lacrosse; the novel substitutes a fanciful Saint Brandon origin story (65); Middle North America is the setting of Apes' Alley (45).","notesPages":[403],"id":"glossary-entry-north-america","letter":"N"},{"term":"North Rockford","definition":"Location where a fortune-teller predicted the Battle of Armageddon would begin in the local caverns (44).","notesPages":[403],"id":"glossary-entry-north-rockford","letter":"N"},{"term":"North Shore (Inneall's Ocean)","definition":"The northern edge of Inneall's growing Ocean, where Heart's Desire Cove is located and the four experimental groups merge (55); made joyous by the presence of the experimental children and Riesin (57).","notesPages":[403],"id":"glossary-entry-north-shore-innealls-ocean","letter":"N"},{"term":"Norwegian (blood)","definition":"Part of Axel Albert Grindstone's \"old species\" ancestry (10).","notesPages":[403],"id":"glossary-entry-norwegian-blood","letter":"N"},{"term":"Noses (Close to, clues)","definition":"Dubu believes clues pointing to the Acorn containing all answers are unnoticed because they are too big, plain, and close to observers' noses (74).","notesPages":[403],"id":"glossary-entry-noses-close-to-clues","letter":"N"},{"term":"Nostrils (Souls in)","definition":"According to Donatus O'Reily, the souls of his nine dead companions remain temporarily in their nostrils and will only depart when his own soul escapes his nostrils at the moment of hanging (157).","notesPages":[404],"id":"glossary-entry-nostrils-souls-in","letter":"N"},{"term":"Nostrums (for hair loss)","definition":"Remedies taken by some Axel's Apes who are losing their yellow body hair, though the nostrums are ineffective (51).","notesPages":[404],"id":"glossary-entry-nostrums-for-hair-loss","letter":"N"},{"term":"Not-Quite-Perfect (Creature)","definition":"The seventh creature made by the Theos on the lathe; identified as Mankind, flawed by a small rent but accidentally activated after being crumpled and thrown away (37).","notesPages":[404],"id":"glossary-entry-not-quite-perfect-creature","letter":"N"},{"term":"Notaries","definition":"Two human/computer notaries attested to the giant hand's descent into Ape Caverns, while the Axel's Ape notary had fallen into Deep Sleep just before (68).","notesPages":[404],"id":"glossary-entry-notaries","letter":"N"},{"term":"Notions","definition":"Dubu possesses several \"notions\" about accessing knowledge (via Acorn, eating raw fish, reading turtles' tongues) (74-75); ideas and notions transmitted instantly in Floating World (80).","notesPages":[404],"id":"glossary-entry-notions","letter":"N"},{"term":"Novelty","definition":"House smells possess attractions of novelty (6); Invisible Alfred attracts crowds through novelty (109).","notesPages":[404],"id":"glossary-entry-novelty","letter":"N"},{"term":"Novelty-seekers","definition":"Complain that Inneall's story (log) ends without a real ending (166).","notesPages":[404],"id":"glossary-entry-novelty-seekers","letter":"N"},{"term":"Nutrient-mud","definition":"Rich sediment forming in the streams and pools of The Three's habitat, forming faster than experimental fish could consume it (3).","notesPages":[404],"id":"glossary-entry-nutrient-mud","letter":"N"},{"term":"Nutriment (in hump)","definition":"Sustenance stored, along with water, in the functional bull-hump on Axel the Ape's neck (42).","notesPages":[404],"id":"glossary-entry-nutriment-in-hump","letter":"N"},{"term":"Oaths","definition":"(Not explicitly listed, but implied) Binding promises, such as the \"sworn word\" Satrap gives Inneall regarding the yacht (116) and the \"honor sworn\" commitment of Donatus O'Reily's seconds (124).","notesPages":[404],"id":"glossary-entry-oaths","letter":"O"},{"term":"Oats Imperial","definition":"Ingredient added to the \"Hay a la Riesin\" specialty served at Heart's Desire Cove (58).","notesPages":[405],"id":"glossary-entry-oats-imperial","letter":"O"},{"term":"Object (Contest)","definition":"The goal or purpose of the contest (whether game or death combat) that Man must engage in; Man does not know the object (72).","notesPages":[405],"id":"glossary-entry-object-contest","letter":"O"},{"term":"Obscene (Ocean creatures)","definition":"Including Satrap Saint Ledger, \"in the nicest sense of that word,\" likely implying awesome, grotesque, or taboo-defying qualities inherent to their nature (135).","notesPages":[405],"id":"glossary-entry-obscene-ocean-creatures","letter":"O"},{"term":"Obscene Sea Monster","definition":"Description applied to Satrap Saint Ledger when in his deep-ocean diving state; title of the magnificent pop art tapestry depicting him as such (The Midas Satrap Saint Ledger As An Obscene Sea Monster) (144, 147).","notesPages":[405],"id":"glossary-entry-obscene-sea-monster","letter":"O"},{"term":"Obscenity (Ocean)","definition":"Satrap Saint Ledger, while transformed for deep diving, is described as being an \"Ocean Obscenity or Monster\" (137).","notesPages":[405],"id":"glossary-entry-obscenity-ocean","letter":"O"},{"term":"Observer (Luas)","definition":"Role primarily maintained by the angel Luas throughout the experiments, remaining more detached than a full participant (61); he ultimately affirms this status (\"I was an observer only\") upon departing the group (103).","notesPages":[405],"id":"glossary-entry-observer-luas","letter":"O"},{"term":"Obstacle (Intelligence as)","definition":"Intelligence is considered an obstacle for holding the office of Imperial Head of the Kangaroo; candidates must have passed through a state of \"radiant intelligence\" but function in a \"post-intellectual state\" while in charge (83).","notesPages":[405],"id":"glossary-entry-obstacle-intelligence-as","letter":"O"},{"term":"Ocarina playing","definition":"Musical activity involving a simple wind instrument; one of the arts abandoned by humans but reinvented by Computers (33).","notesPages":[407],"id":"glossary-entry-ocarina-playing","letter":"O"},{"term":"Ocean","definition":"Specifically, Inneall's artificial, rapidly growing ocean (24, 27, 43, etc.); also refers generally to Earth's oceans (11, 101, 105, etc.). See Inneall's Ocean.","notesPages":[405],"id":"glossary-entry-ocean","letter":"O"},{"term":"Ocean archeology","definition":"Field concerned with underwater archaeological sites, such as the Giant Underwater Cenotaphs off San Sabian (132). See also Oceanic archeology.","notesPages":[405],"id":"glossary-entry-ocean-archeology","letter":"O"},{"term":"Ocean Bottom","definition":"The floor of Inneall's Ocean; site of the Whales' constructions (136-138), the sunken Persimmon Manor (159), and the cenotaphs of Axel, Randal, Henryetta, and Zchold (148-150, 156). See also Ocean floor.","notesPages":[405,406],"id":"glossary-entry-ocean-bottom","letter":"O"},{"term":"Ocean creatures","definition":"Beings adapted to deep-sea life; Satrap Saint Ledger becomes one when diving, described as \"obscene\" (135); implies a category encompassing whales, fish, etc.","notesPages":[406],"id":"glossary-entry-ocean-creatures","letter":"O"},{"term":"Ocean depth(s)","definition":"The deep regions of the ocean; possess four additional colors beyond the rainbow (136); site of Whale constructions (136) and potentially the Castle Domdaniel (131).","notesPages":[406],"id":"glossary-entry-ocean-depth-s","letter":"O"},{"term":"Ocean-dew hour","definition":"Time of early morning when dew forms from ocean moisture; occurs after False Dawn when the Eleven return to shore (76).","notesPages":[407],"id":"glossary-entry-ocean-dew-hour","letter":"O"},{"term":"Ocean diving","definition":"\"Real Ocean Diving\" requires inducing the state of Oceanic Metastasis (133). See also Diving.","notesPages":[406],"id":"glossary-entry-ocean-diving","letter":"O"},{"term":"Ocean floor","definition":"Site of Whale constructions (Castles, forts, mansions, palaces) (105, 136); the small sea-lice sculpt this floor (138); destination of the sunken house (160). See also Ocean Bottom.","notesPages":[406],"id":"glossary-entry-ocean-floor","letter":"O"},{"term":"Ocean Floor (Sculpturing Lice)","definition":"The tiny creatures that etch figures and faces onto the stone pillars of the Whales' constructions (138). See also Lice (Sea-Lice).","notesPages":[406],"id":"glossary-entry-ocean-floor-sculpturing-lice","letter":"O"},{"term":"Ocean-Lice","definition":"See Lice (Sea-Lice).","notesPages":[407],"id":"glossary-entry-ocean-lice","letter":"O"},{"term":"Ocean Metastasis","definition":"The pseudo-dream state, also called the Oceanic Hyper-Active Dream State or \"Satrap's state\", necessary for extended deep-ocean diving without equipment; induced by Satrap via secret instruction and para-hypnosis; provides new ways of seeing, heightened senses, and allows underwater communication; settles completely on users and is potentially permanent, though vulnerable to erosion by shock and sorrow (133, 134, 135, 137, 139, 150). See also Ocean Sleep, Oceanic Metastasis.","notesPages":[406],"id":"glossary-entry-ocean-metastasis","letter":"O"},{"term":"Ocean shore","definition":"The coastline bordering Inneall's Ocean; site of Heart's Desire Cove/New Oceanside (58, 76, 77, 85, 108, 109, 119, 123); location where Inneall, Carcajou, and Schimp return after the ocean-floor burial (151); site where Zchold is stoned (122); location of new cabin construction (119).","notesPages":[406],"id":"glossary-entry-ocean-shore","letter":"O"},{"term":"Ocean Sleep","definition":"Alternate term for Oceanic Metastasis; Inneall believes experiencing it may provide inoculation against the Deep Sleep of the Apes (141, 142, 149). See also Ocean Metastasis.","notesPages":[406],"id":"glossary-entry-ocean-sleep","letter":"O"},{"term":"Ocean stone","definition":"Material from which Whales build strong forts, according to \"The Child's Big Book of Whales\" (105).","notesPages":[406],"id":"glossary-entry-ocean-stone","letter":"O"},{"term":"Ocean surface","definition":"Invisible Alfred rises invisibly to the surface (150); the Nine return to the surface periodically to exchange oxygen canisters (139).","notesPages":[407],"id":"glossary-entry-ocean-surface","letter":"O"},{"term":"Ocean water","definition":"The water comprising Inneall's Ocean; bait shops spring up with its arrival (58).","notesPages":[407],"id":"glossary-entry-ocean-water","letter":"O"},{"term":"Ocean (Whales of)","definition":"Phrase used in praising the Lord (\"Praise the Lord, all ye Whales of Ocean\") (131).","notesPages":[405],"id":"glossary-entry-ocean-whales-of","letter":"O"},{"term":"Oceania","definition":"Geographical region; source of the Cooney Birds' Capers, which influence Structo Lane Dramas (76).","notesPages":[407],"id":"glossary-entry-oceania","letter":"O"},{"term":"Oceanic archeology","definition":"See Ocean archeology.","notesPages":[407],"id":"glossary-entry-oceanic-archeology","letter":"O"},{"term":"Oceanic context","definition":"The environment and background related to the ocean; Lord Randal had researched Megalithic Archeology within this context (137).","notesPages":[407],"id":"glossary-entry-oceanic-context","letter":"O"},{"term":"Oceanic Hyper-Active Dream State","definition":"Alternate name for the state of Oceanic Metastasis (135). See also Ocean Metastasis.","notesPages":[407],"id":"glossary-entry-oceanic-hyper-active-dream-state","letter":"O"},{"term":"Oceanic Metastasis","definition":"See Ocean Metastasis.","notesPages":[407],"id":"glossary-entry-oceanic-metastasis","letter":"O"},{"term":"Oceanic qualities","definition":"Characteristics pertaining to the ocean; unaccounted for regarding giant submarine structures (131).","notesPages":[407],"id":"glossary-entry-oceanic-qualities","letter":"O"},{"term":"Oceanic World (Old)","definition":"The entirety of Earth's oceans known before the creation of Inneall's Ocean (138).","notesPages":[407],"id":"glossary-entry-oceanic-world-old","letter":"O"},{"term":"Oceans (Making)","definition":"Creative act performed by Inneall (24, 27, 112); possibility of other AMHs imitating this antic raised as a danger (28).","notesPages":[407],"id":"glossary-entry-oceans-making","letter":"O"},{"term":"Odd fellows","definition":"Dubu's term for the transparent, giggling beings who tempted her to cast Lutin and the midwife into sleep before the Big Egg appeared (155).","notesPages":[407],"id":"glossary-entry-odd-fellows","letter":"O"},{"term":"Odds (Fifty-to-one, Dolos kill)","definition":"The gamblers' odds favoring a successful kill by a Dolophonos in any particular case (50).","notesPages":[408],"id":"glossary-entry-odds-fifty-to-one-dolos-kill","letter":"O"},{"term":"Odds (Million-to-one, Serpent's Egg)","definition":"Stated probability against a person being classified as a \"Serpent's Egg\" (2, 127).","notesPages":[408],"id":"glossary-entry-odds-million-to-one-serpents-egg","letter":"O"},{"term":"Odds (Nine to three, Sleepers waking)","definition":"The pessimistic \"going odds\" cited by an Ape guard that none of the sleepers in Ape Caverns would wake from the \"Holy Sleep\" \"in this millennium\" (67).","notesPages":[408],"id":"glossary-entry-odds-nine-to-three-sleepers-waking","letter":"O"},{"term":"Odds (Prohibitive, Serpent's Egg)","definition":"The seemingly infinitesimal probability, according to normal mathematics, of multiple \"Serpent's Eggs\" appearing within the small group of the Nine (127).","notesPages":[408],"id":"glossary-entry-odds-prohibitive-serpents-egg","letter":"O"},{"term":"\"Ode for Third Night of Summerset\"","definition":"Poem epigraph for Chapter Thirteen (141).","notesPages":[408],"id":"glossary-entry-ode-for-third-night-of-summerset","letter":"O"},{"term":"Odor (Experimental truffles)","definition":"Strong, enticing scent, more powerful than fresh milk, possessed by the experimental truffles eaten by young Lord Randal (4).","notesPages":[408],"id":"glossary-entry-odor-experimental-truffles","letter":"O"},{"term":"Odor (Mega Dolophonos)","definition":"The assassin’s characteristic aura and odor accompany his unusually powerful presence (94).","notesPages":[408],"id":"glossary-entry-odor-mega-dolophonos","letter":"O"},{"term":"Odor (of Treason)","definition":"A distinct smell (\"funny smell\") associated with betrayal, detected by Lutin in the crows-nest just before Invisible Alfred was revealed to be there; the smell disappears when an unseen presence leaves; Alfred is identified only later (145, 149).","notesPages":[408],"id":"glossary-entry-odor-of-treason","letter":"O"},{"term":"Offense (Personal)","definition":"Alpha declares that any harm done to Inneall by the Dolophonoi will be regarded as a personal offense by him (52).","notesPages":[408],"id":"glossary-entry-offense-personal","letter":"O"},{"term":"Official Cockcrow","definition":"The designated time for cockcrow on Kure Island, said in the novel to be the latest anywhere in the world (118).","notesPages":[408],"id":"glossary-entry-official-cockcrow","letter":"O"},{"term":"Official Hanging Day","definition":"The designated day (Third Day of Summerset) for executions of Natural Nobility members; expected to become an annual event (152).","notesPages":[408],"id":"glossary-entry-official-hanging-day","letter":"O"},{"term":"Okla Hannali","definition":"A novel written by R.A. Lafferty (publisher’s biographical note).","notesPages":[408],"id":"glossary-entry-okla-hannali","letter":"O"},{"term":"Oklahoma","definition":"US state where R.A. Lafferty lived most of his life (Tulsa) (publisher’s biographical note); Eastern Oklahoma is the location of Inneall's planned ten- thousand- square-mile Ocean (166).","notesPages":[409],"id":"glossary-entry-oklahoma","letter":"O"},{"term":"Old Chaldee","definition":"Ancient Semitic language studied by Axel Grindstone (11); also the independently reinvented script used by Axel to write on the sky-cover (4). See also Chaldee (Code).","notesPages":[409],"id":"glossary-entry-old-chaldee","letter":"O"},{"term":"Old Dutch (Flying Dutchman)","definition":"Familiar name used by Satrap Saint Ledger for the legendary ghost ship, the Flying Dutchman (97).","notesPages":[409],"id":"glossary-entry-old-dutch-flying-dutchman","letter":"O"},{"term":"Old Greek Tragedy","definition":"Classical dramatic genre cited as one of the human sources influencing Structo Lane Dramas (76).","notesPages":[409],"id":"glossary-entry-old-greek-tragedy","letter":"O"},{"term":"Old people","definition":"Contrasted with young people as patrons of fast- lunch/drink places (58).","notesPages":[409],"id":"glossary-entry-old-people","letter":"O"},{"term":"Old Religion","definition":"The established faith prior to current societal shifts; Hieronymous Ignatius Zchold is a Priest/Bishop of this religion (122, 158); most Pirates still adhere to it (122).","notesPages":[409],"id":"glossary-entry-old-religion","letter":"O"},{"term":"Old species","definition":"Designation for non-ethnic humans with Northern European ancestry (English, Norwegian, German, Dutch), like Axel Albert Grindstone (10).","notesPages":[409],"id":"glossary-entry-old-species","letter":"O"},{"term":"Old Testament","definition":"Part of the Christian Bible; Giants of the Old Testament (Sons of Anak) mentioned as possible builders of Lyonesse (106).","notesPages":[409],"id":"glossary-entry-old-testament","letter":"O"},{"term":"Old Titans","definition":"See Titans.","notesPages":[409],"id":"glossary-entry-old-titans","letter":"O"},{"term":"Older species","definition":"Category including sea-lice, which write from right to left, contrasted implicitly with newer species (163).","notesPages":[409],"id":"glossary-entry-older-species","letter":"O"},{"term":"Olio-Stew (Protein-Oil)","definition":"A concoction, apparently nutritious, that was one of the only two items (along with Mushroom Wine) consumable by all eleven members of the Experiments during their dinner at the condominium (72).","notesPages":[409],"id":"glossary-entry-olio-stew-protein-oil","letter":"O"},{"term":"Olympus","definition":"Mythological home of the Greek Gods who overthrew the Titans (106).","notesPages":[409],"id":"glossary-entry-olympus","letter":"O"},{"term":"Omelet","definition":"Used metaphorically by an AMH theorist: \"you can't make an omelet without stripping a few gear trains or slitting a few throats\" (39).","notesPages":[410],"id":"glossary-entry-omelet","letter":"O"},{"term":"On the Innate Love of Luxury and Elegance in Ambulatory Computers and Kindred Machines","definition":"Title of a \"florid work\" written by Inneall's sophisticated designated father, an Ambulatory Computer residing in a super-lush penthouse in Structo Lane (52).","notesPages":[344,345],"id":"glossary-entry-on-the-innate-love-of-luxury-and-elegance-in-ambulatory-computers-and-kindred-machines","letter":"O"},{"term":"Onagers","definition":"Wild asses; species with which an AMH Computer claims great affinity for machines (31).","notesPages":[410],"id":"glossary-entry-onagers","letter":"O"},{"term":"One-hundred \"Dial-a-Picture Arrangements\"","definition":"Devices in the Lynn- Randal house holding numerous changeable pictures (5).","notesPages":[410],"id":"glossary-entry-one-hundred-dial-a-picture-arrangements","letter":"O"},{"term":"One-hundred-gallon drum (Invisible Paint)","definition":"Large containers allegedly holding Invisible Paint; seven are requested by Inneall and moved to the ship (97, 101); Invisible Alfred claims to have spent 9000 years in one such drum, drawing power from the residue (110, 124).","notesPages":[410],"id":"glossary-entry-one-hundred-gallon-drum-invisible-paint","letter":"O"},{"term":"One-in-a-billion mega-minded person","definition":"Description of the newborn Axel the Ape based on sophisticated scanner readings in Middle America (20).","notesPages":[410],"id":"glossary-entry-one-in-a-billion-mega-minded-person","letter":"O"},{"term":"One-in-a-million animals","definition":"Highly exceptional experimental animals that had been talking for a decade before animal speech became widespread (54).","notesPages":[410],"id":"glossary-entry-one-in-a-million-animals","letter":"O"},{"term":"One-in-a-million (Serpent's Egg)","definition":"The statistical probability of a member of the general population being adjudged a \"Serpent's Egg\" (2, 127).","notesPages":[410],"id":"glossary-entry-one-in-a-million-serpents-egg","letter":"O"},{"term":"\"One Man, One Knife\"","definition":"Phrase quoted from Arpad Arutinov's The Back Door of History, representing the \"Quintessence of workable and effective armament and attack\" in a future era of modernized, reduced weaponry (79).","notesPages":[410],"id":"glossary-entry-one-man-one-knife","letter":"O"},{"term":"One-sixteenth human (Dubu)","definition":"Dubu the bear's claimed fraction of human ancestry, confirmed by registries but widely doubted (63).","notesPages":[410],"id":"glossary-entry-one-sixteenth-human-dubu","letter":"O"},{"term":"Ongoing experiment","definition":"The Lynn-Randal project raising The Three together is described as such (3).","notesPages":[410],"id":"glossary-entry-ongoing-experiment","letter":"O"},{"term":"Optical illusion","definition":"The Kangaroo constellation in the sky is dismissed as such by the Sea Louse epilogue (166).","notesPages":[410],"id":"glossary-entry-optical-illusion","letter":"O"},{"term":"Orangs","definition":"Orangutans from the Asian Indies, suggested as the possible identity of the blond/ golden/red \"Golden Apes\" leading the Gypsy bands due to their coloration (13-14).","notesPages":[411],"id":"glossary-entry-orangs","letter":"O"},{"term":"Orchard (Humanity as)","definition":"Metaphor used regarding the \"pruning\" of humanity; unthrifty and blighted trees (undesirable individuals/groups) are cut out for the good of the orchard (81).","notesPages":[411],"id":"glossary-entry-orchard-humanity-as","letter":"O"},{"term":"Orchestras (birds)","definition":"Large ensembles of birds assembled and inspired by the Birdmaster (60).","notesPages":[411],"id":"glossary-entry-orchestras-birds","letter":"O"},{"term":"Ordered belief (Eschatology)","definition":"A structured system of belief concerning final things (aim, goal, direction, destination, final end); identified as a major deficiency in the human condition (40).","notesPages":[411],"id":"glossary-entry-ordered-belief-eschatology","letter":"O"},{"term":"Orders (Receiving)","definition":"Humans receive orders \"somehow\" that shape their lives, which they interpret and carry out without seeing the face of the one who gives them (74).","notesPages":[411],"id":"glossary-entry-orders-receiving","letter":"O"},{"term":"Ordinary elephant","definition":"A typical elephant, contrasted with Empress Elephants; does not make a better mayor than a human (92); Dolophonoi are \"not in the business of killing ordinary Elephants\" (90).","notesPages":[411],"id":"glossary-entry-ordinary-elephant","letter":"O"},{"term":"Ordinary parrot","definition":"A typical parrot, contrasted with Popugai, who is a Kea with exceptional abilities (64).","notesPages":[411],"id":"glossary-entry-ordinary-parrot","letter":"O"},{"term":"Ordinary weapon","definition":"The assassins say ordinary weapons cannot kill Luas or a prophesying python such as Lutin (87-88). Most ordinary knives also fail against Dolophonoi (100), but the text does not establish universal immunity to all standard weapons.","notesPages":[411],"id":"glossary-entry-ordinary-weapon","letter":"O"},{"term":"Organ banks","definition":"Facilities storing human body parts for transplant; frequented by \"fancier Ambulatory Computers\" who incorporate human parts into themselves (42).","notesPages":[411],"id":"glossary-entry-organ-banks","letter":"O"},{"term":"Organization (Kangaroo)","definition":"The almost-invisible governing entity; explicitly described as \"an organization that was not an organization,\" highlighting its flexibility, immateriality, and lack of formal structure or continuous existence (77, 83).","notesPages":[411],"id":"glossary-entry-organization-kangaroo","letter":"O"},{"term":"Oriental languages","definition":"Languages of the East studied by Axel Grindstone (Old Chaldee, Arabic, Swahili, Amharic, Ghees) (11).","notesPages":[411],"id":"glossary-entry-oriental-languages","letter":"O"},{"term":"Origin (Ambulatory Computers)","definition":"Subject of Livius Secundus's history, traced back to mythological roots in human crypto-memory (25, 33, 42, 70).","notesPages":[412],"id":"glossary-entry-origin-ambulatory-computers","letter":"O"},{"term":"Origin (Depraved)","definition":"Source of the human race traced back, along with its \"corrupt root,\" associated with the misuse of free will (35).","notesPages":[412],"id":"glossary-entry-origin-depraved","letter":"O"},{"term":"Origin (Mankind)","definition":"Subject of computer legends involving the Theos, eggs, and a lathe (36-37).","notesPages":[412],"id":"glossary-entry-origin-mankind","letter":"O"},{"term":"Original ideas","definition":"Dubu claims to receive \"absolutely original ideas\" from eating raw \"Filchman's Daughter\" fish (75).","notesPages":[412],"id":"glossary-entry-original-ideas","letter":"O"},{"term":"Ornamental trees","definition":"Used to beautify old strip pits, including the carob (\"Judas Tree\") (24, 91).","notesPages":[412],"id":"glossary-entry-ornamental-trees","letter":"O"},{"term":"Orneriness","definition":"Cited as a possible motivation for AMHs to begin making oceans if humans show apprehension (28).","notesPages":[412],"id":"glossary-entry-orneriness","letter":"O"},{"term":"Orphan","definition":"Henryetta insists she was born one and will die one, refusing adoption (96).","notesPages":[412],"id":"glossary-entry-orphan","letter":"O"},{"term":"Ostrich Struts","definition":"Pompous, beautiful displays performed by ostriches in Southwest Africa; cited as a source influencing Structo Lane Dramas (76).","notesPages":[412],"id":"glossary-entry-ostrich-struts","letter":"O"},{"term":"Other Eden","definition":"See Eden (Other).","notesPages":[412],"id":"glossary-entry-other-eden","letter":"O"},{"term":"Otto Wotto","definition":"Great inventor credited with creating Wotto Metal, the matrix material revolutionizing computer circuitry (25); also co-inheritor with Tom Dooley of Persimmon Manor, built by their common great-great-grandfather (124); Satrap Saint Ledger's maternal grandfather (48).","notesPages":[412],"id":"glossary-entry-otto-wotto","letter":"O"},{"term":"Otto Wotto Hootnanny (We-owe-a-lot-to-Otto-Wotto)","definition":"See Hootnanny (...).","notesPages":[412],"id":"glossary-entry-otto-wotto-hootnanny-we-owe-a-lot-to-otto-wotto","letter":"O"},{"term":"Out-of-control Ambulatory Computer","definition":"Description of Inneall, specifically linking her uncontrolled state to her creation of the ocean and diversion of the sun's power (59).","notesPages":[412],"id":"glossary-entry-out-of-control-ambulatory-computer","letter":"O"},{"term":"Outdoor Eden","definition":"The narrator’s phrase for The Three’s contrived initial habitat (9).","notesPages":[413],"id":"glossary-entry-outdoor-eden","letter":"O"},{"term":"Outdoors","definition":"Smells outdoors differ from those inside the Lynn-Randal house (5); the glass- domed 'outdoors' habitat behind the house (28).","notesPages":[412],"id":"glossary-entry-outdoors","letter":"O"},{"term":"Outer world","definition":"Alpha takes his name when going into the outer world from Second Eden (20); Whales explore the outer ocean beyond their ancestral inner sea (106).","notesPages":[413],"id":"glossary-entry-outer-world","letter":"O"},{"term":"Outmoded (Armaments)","definition":"Arpad Arutinov predicts all outmoded and archaic armaments will be demolished and junked in a future modernization (78).","notesPages":[413],"id":"glossary-entry-outmoded-armaments","letter":"O"},{"term":"Outside","definition":"Outsider doing the killing at Persimmon Manor (125); disturbance outside the clubroom (101).","notesPages":[413],"id":"glossary-entry-outside","letter":"O"},{"term":"Outsider (Hypothetical)","definition":"Potential unknown killer at Persimmon Manor, who Dubu suggests should be put to sleep along with the guests (125).","notesPages":[413],"id":"glossary-entry-outsider-hypothetical","letter":"O"},{"term":"Over-endowed males","definition":"Powerfully equipped male specimens (specifically referring to Alpha the Ape) viewed as potential troublemakers and thus undesirable by zoos (20).","notesPages":[413],"id":"glossary-entry-over-endowed-males","letter":"O"},{"term":"Over-hook","definition":"Inneall's assessment that using her voice modelled on Satrap's deceased five- year-old daughter was excessively manipulative (\"an over-hook\") (52).","notesPages":[413],"id":"glossary-entry-over-hook","letter":"O"},{"term":"Overdue (Resurrection of Honor)","definition":"The revival of the concept of Honor was considered long overdue by its proponents (118).","notesPages":[413],"id":"glossary-entry-overdue-resurrection-of-honor","letter":"O"},{"term":"Overflowing (Happiness)","definition":"Extreme state of joy depicted on the cenotaph of Hieronymous Ignatius Zchold (150).","notesPages":[413],"id":"glossary-entry-overflowing-happiness","letter":"O"},{"term":"Overheard (Conversation)","definition":"Axel overheard the breakfast conversation about \"Serpent's Eggs\" (2).","notesPages":[413],"id":"glossary-entry-overheard-conversation","letter":"O"},{"term":"Overheard (Plans)","definition":"Invisible Alfred overheard the Nine's Council of War plans while hidden in the crows-nest (149).","notesPages":[413],"id":"glossary-entry-overheard-plans","letter":"O"},{"term":"Overlook (What Man ought to be)","definition":"Man is described as an animal so lost in self- contemplation that he overlooks his true potential or duty (35).","notesPages":[413],"id":"glossary-entry-overlook-what-man-ought-to-be","letter":"O"},{"term":"Overpoliteness","definition":"Identified as another human failing, contrasted with the typical bluntness of computers (39).","notesPages":[414],"id":"glossary-entry-overpoliteness","letter":"O"},{"term":"Overriding (Emotions)","definition":"Allowing feelings to take precedence over reason; Inneall admits she sometimes lets her emotions override everything (51).","notesPages":[414],"id":"glossary-entry-overriding-emotions","letter":"O"},{"term":"Overview (Popugai's)","definition":"The comprehensive perspective possessed by Popugai due to his high flight and keen eyesight, enabling him to see problems and disputes clearly; considered the best among the Twelve (except possibly Luas) (64).","notesPages":[414],"id":"glossary-entry-overview-popugais","letter":"O"},{"term":"Own species (Predicting futures)","definition":"Fortune-telling principle stated by an AMH Computer: true predictions can only be made by entities of one species about entities of another species (30).","notesPages":[414],"id":"glossary-entry-own-species-predicting-futures","letter":"O"},{"term":"Oxford Song Book","definition":"Source of the verse about a mer-ma-id at the bottom of the deep blue sea (131).","notesPages":[414],"id":"glossary-entry-oxford-song-book","letter":"O"},{"term":"Oxygen (Canisters)","definition":"Used with face masks for diving; deemed insufficient by Lord Randal for the planned half-mile dive (133); exchanged periodically by the Nine during their long afternoon dive (139).","notesPages":[414],"id":"glossary-entry-oxygen-canisters","letter":"O"},{"term":"Paddle-fishes","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[414],"id":"glossary-entry-paddle-fishes","letter":"P"},{"term":"Paint brush","definition":"Invisible Alfred is described as a \"good man with a paint brush\" (113).","notesPages":[415],"id":"glossary-entry-paint-brush","letter":"P"},{"term":"Paint (Invisible)","definition":"A substance, kept in seven heavy but empty 100- gallon drums, that renders objects approximately 99% invisible when applied (effectively only in the dark). Used by the Intrepid Nine to paint the Annabella Saint Ledger (97, 101, 104). Invisible Alfred draws power from its residue (110). Satrap claims it's a fake (97).","notesPages":[414],"id":"glossary-entry-paint-invisible","letter":"P"},{"term":"Palaces","definition":"Whales build Palaces in Kingdom Come and on the Ocean Floor, according to \"The Child's Big Book of Whales\" (105); potentially what the Whales are building now (106).","notesPages":[415],"id":"glossary-entry-palaces","letter":"P"},{"term":"Pan-Ther (All-the-Animals)","definition":"The composite \"All-Animal,\" revealed by Invisible Alfred as the \"true sign\" hidden behind the conventional mask of Leo the Lion (111). Not the usual meaning of Panther (111).","notesPages":[415],"id":"glossary-entry-pan-ther-all-the-animals","letter":"P"},{"term":"Pansy-Face (Annabella)","definition":"The \"pixie face\" representing the \"Grindstone\" figure on the Saint Ledger coat-of-arms (49).","notesPages":[415],"id":"glossary-entry-pansy-face-annabella","letter":"P"},{"term":"Parable-universe","definition":"Term used by Invisible Alfred to describe the nature of the universe itself —not ultimately real, but existing only as a parable to illustrate a material point (112). Astrology is thus a \"parable-science\" attempting to describe this universe (111-112).","notesPages":[415],"id":"glossary-entry-parable-universe","letter":"P"},{"term":"Paradox (Embodied)","definition":"Man is described as an \"embodied paradox, a bundle of contradictions\" (35).","notesPages":[415],"id":"glossary-entry-paradox-embodied","letter":"P"},{"term":"Parallels of latitude","definition":"Mark Twain claims to use these, along with meridians of longitude, as seines to drag the Atlantic for whales (131).","notesPages":[415],"id":"glossary-entry-parallels-of-latitude","letter":"P"},{"term":"Parapet (High)","definition":"Location of the mysterious Gargoyles carved onto Cathedrals (13, 17).","notesPages":[415],"id":"glossary-entry-parapet-high","letter":"P"},{"term":"Parasang","definition":"Ancient Persian unit of distance (roughly 3.5 miles); the celestial trumpets welcoming Man were each a parasang long (34).","notesPages":[415],"id":"glossary-entry-parasang","letter":"P"},{"term":"Parents","definition":"The \"parents\" of the Experiments (George and Iris Lynn- Randal, Shadrack Saleh, Gregor McGregor, etc.) were sponsors (2, 84, 85), not supposed to get emotionally involved (7, 85).","notesPages":[415],"id":"glossary-entry-parents","letter":"P"},{"term":"Parents (Lord Randal's)","definition":"George and Iris Lynn-Randal; their breakfast conversations trigger fear in The Three (1-2).","notesPages":[415],"id":"glossary-entry-parents-lord-randals","letter":"P"},{"term":"Paris France","definition":"European capital city mentioned as a possible location for a morning coffee break under the free-travel conditions of the Floating World (79).","notesPages":[415],"id":"glossary-entry-paris-france","letter":"P"},{"term":"Park (Memorial)","definition":"Satrap Saint Ledger built the entertainment center at Heart's Desire Cove as a Memorial Park to Inneall (57).","notesPages":[416],"id":"glossary-entry-park-memorial","letter":"P"},{"term":"Parlor aquarium","definition":"Inneall's artificial heart resembles a pump for a little ten-gallon aquarium (49).","notesPages":[416],"id":"glossary-entry-parlor-aquarium","letter":"P"},{"term":"Parrot","definition":"Popugai is a Kea/Nestor Parrot from New Zealand (55, 64); served as member of the Gruenbaum-McGregor experiment (55); known for exceptional memory, understanding, and linguistic ability (64); difficult to defend against in lacrosse (65); accompanies group visiting Donatus O'Reily (153).","notesPages":[416],"id":"glossary-entry-parrot","letter":"P"},{"term":"Participant (Axel)","definition":"Axel the Ape, son of Alpha, participates in the Lynn-Randal Experiment (21).","notesPages":[416],"id":"glossary-entry-participant-axel","letter":"P"},{"term":"Participant (Luas)","definition":"Luas the angel remained more of an observer than a full participant in the Experiments (61, 103).","notesPages":[416],"id":"glossary-entry-participant-luas","letter":"P"},{"term":"Participants (Birds)","definition":"Birds became faithful listeners and participants in the music at Heart's Desire Cove after it was Computer-Enhanced (57).","notesPages":[416],"id":"glossary-entry-participants-birds","letter":"P"},{"term":"Participants (Experiments)","definition":"The young beings involved in the Four Experiments; all should be pleasant (61).","notesPages":[416],"id":"glossary-entry-participants-experiments","letter":"P"},{"term":"Parties (Carry-over)","definition":"Groups of guests remaining from previous celebrations at Persimmon Manor; remnants of five or more such parties still ongoing (116).","notesPages":[416],"id":"glossary-entry-parties-carry-over","letter":"P"},{"term":"Parties (Signing contract in blood)","definition":"The two individuals (Inneall and Satrap) involved in the contract transferring ownership of the yacht; both must sign in blood (48).","notesPages":[416],"id":"glossary-entry-parties-signing-contract-in-blood","letter":"P"},{"term":"Parting (Last)","definition":"Invoked regarding the summer departing (132).","notesPages":[416],"id":"glossary-entry-parting-last","letter":"P"},{"term":"Partners (Human)","definition":"The unnamed AMH theorist says he has human partners in four enterprises and preaches “Sweet reason” to them, but complains that their emotions intervene (39).","notesPages":[416],"id":"glossary-entry-partners-human","letter":"P"},{"term":"Party (Birthday)","definition":"Celebratory event for the Nine Royal Kids held just before midnight in the condominium clubroom (144, 146).","notesPages":[417],"id":"glossary-entry-party-birthday","letter":"P"},{"term":"Party (Grindstone's)","definition":"The group accompanying Axel Albert Grindstone on his journey to Second Eden (18).","notesPages":[417],"id":"glossary-entry-party-grindstones","letter":"P"},{"term":"Party Guests (Carry-over)","definition":"See Carry-over guests.","notesPages":[417],"id":"glossary-entry-party-guests-carry-over","letter":"P"},{"term":"Party (Happy)","definition":"Description of Axel Grindstone's group traveling towards Second Eden (18).","notesPages":[417],"id":"glossary-entry-party-happy","letter":"P"},{"term":"Party (\"Socsollabcomdem Party Potlatch\")","definition":"Title of a campfire song sung at Heart's Desire Cove (59).","notesPages":[417],"id":"glossary-entry-party-socsollabcomdem-party-potlatch","letter":"P"},{"term":"Partying","definition":"AMHs were more untiring in their partying than humans (26); the carry-over guests continue partying even as Persimmon Manor sinks (116).","notesPages":[416],"id":"glossary-entry-partying","letter":"P"},{"term":"Pascal","definition":"Blaise Pascal, French mathematician and physicist credited with inventing an 'Arithmetic Machine' in 1642 (25).","notesPages":[417],"id":"glossary-entry-pascal","letter":"P"},{"term":"Passage (Drake Passage Cock)","definition":"A type of rooster originating from Wollaston Island near Cape Horn, known for crowing very late in the day (118).","notesPages":[417],"id":"glossary-entry-passage-drake-passage-cock","letter":"P"},{"term":"Passage (Executive)","definition":"See Executive Passage.","notesPages":[417],"id":"glossary-entry-passage-executive","letter":"P"},{"term":"Passages (Vaulted and propped)","definition":"Tunnels connecting the Ape Caverns to the old Hickory Coal Mines (45).","notesPages":[417],"id":"glossary-entry-passages-vaulted-and-propped","letter":"P"},{"term":"Passengers (Electric vehicle)","definition":"The eleven members of the experimental group riding on Marino's large electric vehicle (57).","notesPages":[417],"id":"glossary-entry-passengers-electric-vehicle","letter":"P"},{"term":"Passions","definition":"A mixture of passions (raptures, terror, sorrow, hope, overflowing happiness) depicted on the face of the man represented on Zchold's empty cenotaph (150).","notesPages":[417],"id":"glossary-entry-passions","letter":"P"},{"term":"Past","definition":"Axel Grindstone heard voices from pasts and futures (11); Computers cannot create pasts (71).","notesPages":[417],"id":"glossary-entry-past","letter":"P"},{"term":"Past Master (Novel)","definition":"R. A. Lafferty’s 1968 novel, shortlisted for the 1968 Nebula Award and the 1969 Hugo Award (publisher’s biographical note).","notesPages":[417],"id":"glossary-entry-past-master-novel","letter":"P"},{"term":"Past (Ragged)","definition":"The old strip pits had their ragged past concealed by beautification (24).","notesPages":[417],"id":"glossary-entry-past-ragged","letter":"P"},{"term":"Pasts","definition":"Ambulatory Computers cannot create pasts (71).","notesPages":[417],"id":"glossary-entry-pasts","letter":"P"},{"term":"Patent of Nobility (Marble)","definition":"Metaphorical grant conferred upon limestone by a sea change, transforming it into variegated marble, the preferred building material of Whales (136).","notesPages":[418],"id":"glossary-entry-patent-of-nobility-marble","letter":"P"},{"term":"Path","definition":"Riesin follows a path northward (93, 94); path leading to Dolophonoi cliff-nests (89).","notesPages":[418],"id":"glossary-entry-path","letter":"P"},{"term":"Paths (Particular)","definition":"Specific routes for data transmission within a computer matrix, created and uncreated by wotto metal as needed (26).","notesPages":[418],"id":"glossary-entry-paths-particular","letter":"P"},{"term":"Patriarch (Alpha)","definition":"Alpha's role as the elder leader of the Apes' Caverns community (51).","notesPages":[418],"id":"glossary-entry-patriarch-alpha","letter":"P"},{"term":"Patriarchs (Unfallen)","definition":"The original ancestors of the Unfallen People; includes Magog (12).","notesPages":[418],"id":"glossary-entry-patriarchs-unfallen","letter":"P"},{"term":"Patron (Lutin's)","definition":"Surrogate human father (Felix Culebra y Columba) who provided Lutin with an electric runabout (62).","notesPages":[418],"id":"glossary-entry-patron-lutins","letter":"P"},{"term":"Pattern (Characteristic, Island)","definition":"The unique, quaint arrangement formed by the remnants of Tom Dooley's Island settling around Persimmon Manor on the Ocean Bottom (159).","notesPages":[418],"id":"glossary-entry-pattern-characteristic-island","letter":"P"},{"term":"Pattern (Holds)","definition":"The established structure or sequence remains \"set, formal, stylized, sane\" in Structo Lane (poem epigraph) (67).","notesPages":[418],"id":"glossary-entry-pattern-holds","letter":"P"},{"term":"Paul (Saint)","definition":"Apostle who supported himself as a tent-maker while writing his Epistles; cited by Schimp as a precedent for combining manual labor (bait-shop operator) with intellectual pursuits (162).","notesPages":[418],"id":"glossary-entry-paul-saint","letter":"P"},{"term":"Paws (Dubu's)","definition":"Dubu claps hers in admiration at the unfolding murder mystery (128).","notesPages":[418],"id":"glossary-entry-paws-dubus","letter":"P"},{"term":"Penchant (Dubu's)","definition":"A strong liking or inclination; Dubu has a penchant for putting people to sleep (125).","notesPages":[418],"id":"glossary-entry-penchant-dubus","letter":"P"},{"term":"Penny whistle","definition":"Computers play it and have formed a hundred-piece penny-whistle band in Cincinnati (33).","notesPages":[418],"id":"glossary-entry-penny-whistle","letter":"P"},{"term":"Penny-whistle band","definition":"Large musical ensemble composed entirely of Computers playing penny whistles, located in Cincinnati (33).","notesPages":[418],"id":"glossary-entry-penny-whistle-band","letter":"P"},{"term":"Pentagon (Golden)","definition":"Axel the Ape's signature geometric shape in 'prowls', having five arms at its five angles (6).","notesPages":[419],"id":"glossary-entry-pentagon-golden","letter":"P"},{"term":"Penultimatum","definition":"A demand or proposal that is almost, but not quite, final; Satrap Saint Ledger characterizes Inneall's initial demand for his yacht as a penultimatum, implying negotiation is possible (47).","notesPages":[419],"id":"glossary-entry-penultimatum","letter":"P"},{"term":"People","definition":"Used frequently and variously, often referring to humans collectively or specific groups. See sub-entries below.","notesPages":[419],"id":"glossary-entry-people","letter":"P"},{"term":"People (African)","definition":"Merry individuals accompanying Axel Grindstone who knew the Unfallen Ones (14).","notesPages":[419],"id":"glossary-entry-people-african","letter":"P"},{"term":"People (Agreeable)","definition":"Humans described as the most agreeable of persons, believing in freedom of choice (41).","notesPages":[419],"id":"glossary-entry-people-agreeable","letter":"P"},{"term":"People (Axel's Apes as 'Good People')","definition":"Term used by mythical common people to describe the Axel's Apes they encountered (44).","notesPages":[419],"id":"glossary-entry-people-axels-apes-as-good-people","letter":"P"},{"term":"People (City)","definition":"Urban dwellers expected to use the cabins on Ocean Shore only on weekends, leaving them vulnerable to pirate raids during the week (119).","notesPages":[419],"id":"glossary-entry-people-city","letter":"P"},{"term":"People (Clear Humans, Rhinoid look)","definition":"Individuals who are definitely human (not apes) but possess the Gargoyle-titan facial characteristics otherwise associated with Axel's Apes (44).","notesPages":[419],"id":"glossary-entry-people-clear-humans-rhinoid-look","letter":"P"},{"term":"People (Common)","definition":"Lacrosse played by aristocrats and the most uncommon of commoners (65); common people liked the Funny- Faced Apes (44); associated with the dark 'tide of color' (123).","notesPages":[419],"id":"glossary-entry-people-common","letter":"P"},{"term":"People (Cranky)","definition":"Eccentric individuals driven underground by the Levellers, some of whom disguise themselves as AMHs in Structo Lane (69).","notesPages":[419],"id":"glossary-entry-people-cranky","letter":"P"},{"term":"People (Danced)","definition":"Humans and 'people' (non-humans) danced together at Heart's Desire Cove (58).","notesPages":[419],"id":"glossary-entry-people-danced","letter":"P"},{"term":"People (Dead)","definition":"Alfred claims power over devils in his speech to the Devil-Fish; the passage does not assert power over dead people (108).","notesPages":[419],"id":"glossary-entry-people-dead","letter":"P"},{"term":"People (Elephant Graveyard)","definition":"Those who witness Riesin's arrival at the graveyard (95).","notesPages":[419],"id":"glossary-entry-people-elephant-graveyard","letter":"P"},{"term":"PEOPLE (ETHIOPIA AND ARABIA)","definition":"Inhabitants of these regions acquainted with the Unfallen People, calling them Smithy Apes and Stone-Master Apes (13).","notesPages":[420],"id":"glossary-entry-people-ethiopia-and-arabia","letter":"P"},{"term":"PEOPLE (EXCEPTIONAL)","definition":"The Three identified as such by scanners (5).","notesPages":[420],"id":"glossary-entry-people-exceptional","letter":"P"},{"term":"PEOPLE (FALLEN)","definition":"Ordinary humanity of First Eden, contrasted with the Unfallen People of Second Eden (12).","notesPages":[420],"id":"glossary-entry-people-fallen","letter":"P"},{"term":"PEOPLE (FAMILY MOTHERS)","definition":"Less than half a million \"Rachels\" out of several billion mothers in the floating world mourned lost children conspicuously (81).","notesPages":[420],"id":"glossary-entry-people-family-mothers","letter":"P"},{"term":"PEOPLE (GYPSY)","definition":"Romany folk associated with legends of the Ape Bridge and Unfallen People (13).","notesPages":[420],"id":"glossary-entry-people-gypsy","letter":"P"},{"term":"PEOPLE (HUMAN)","definition":"General term for members of the human species (26, 33, 36, 40, 61, 69, 71, 72, 76, 80, 160, 165).","notesPages":[420],"id":"glossary-entry-people-human","letter":"P"},{"term":"PEOPLE (INTELLIGENT)","definition":"Person needed to correct astrological calculations (30); AMH Computer addresses Satrap as such (71).","notesPages":[420],"id":"glossary-entry-people-intelligent","letter":"P"},{"term":"PEOPLE (INTERLOPING)","definition":"See INTERLOPING MEN.","notesPages":[420],"id":"glossary-entry-people-interloping","letter":"P"},{"term":"PEOPLE (LAUGHED)","definition":"Humans laughed at the appearance of early mechanical horses (31); crowds laughed at Invisible Alfred (109, 110, 114).","notesPages":[420],"id":"glossary-entry-people-laughed","letter":"P"},{"term":"PEOPLE (LEARNED AND UNLEARNED)","definition":"Axel Grindstone talked to thousands of both types during his travels (12).","notesPages":[420],"id":"glossary-entry-people-learned-and-unlearned","letter":"P"},{"term":"PEOPLE (LIKED ALPHA)","definition":"Everyone liked the ape Alpha during his walks across the United States (21).","notesPages":[420],"id":"glossary-entry-people-liked-alpha","letter":"P"},{"term":"PEOPLE (LOCAL SCHOOL-CHILDREN)","definition":"Came to the Unfallen Ones for help with lessons, valued equally with great scholars (15). MATERIAL OBJECTS (HUMAN CULTURE): Objects included alongside behavior in the definition of culture quoted from Britannica (39).","notesPages":[420],"id":"glossary-entry-people-local-school-children","letter":"P"},{"term":"PEOPLE (MEDIA VOICES)","definition":"Adopted the 'all-people throatiness' (6).","notesPages":[420],"id":"glossary-entry-people-media-voices","letter":"P"},{"term":"PEOPLE (MEGA-)","definition":"See MEGA-PEOPLE.","notesPages":[421],"id":"glossary-entry-people-mega","letter":"P"},{"term":"PEOPLE (MOSES')","definition":"Israelites led across the parted waters (possibly the Ape Bridge) by Moses (13).","notesPages":[421],"id":"glossary-entry-people-moses","letter":"P"},{"term":"PEOPLE (MUSIC LOVERS)","definition":"Attracted to the Computer-Enhanced Human Music at Heart's Desire Cove (57).","notesPages":[421],"id":"glossary-entry-people-music-lovers","letter":"P"},{"term":"PEOPLE (NEW)","definition":"Inhabitants of the post-postliterate age unable to recognize irony, rhyme, etc. (8).","notesPages":[421],"id":"glossary-entry-people-new","letter":"P"},{"term":"PEOPLE (OF THE THIRD CONDITION)","definition":"Those identified by Invisible Alfred as needing repentance (110).","notesPages":[421],"id":"glossary-entry-people-of-the-third-condition","letter":"P"},{"term":"PEOPLE (OLD LITERATURES)","definition":"Small numbers of people who still appreciated older literatures, musics, arts, and dramas (9).","notesPages":[421],"id":"glossary-entry-people-old-literatures","letter":"P"},{"term":"PEOPLE (PLEASURE)","definition":"Crowds gathered at New Oceanside for entertainment, who heckled Invisible Alfred (59, 109, 158).","notesPages":[421],"id":"glossary-entry-people-pleasure","letter":"P"},{"term":"PEOPLE (PROMINENT)","definition":"Likely category to which the Head of the Kangaroo belongs (146).","notesPages":[421],"id":"glossary-entry-people-prominent","letter":"P"},{"term":"PEOPLE (QUALITY)","definition":"The thirty-two carry-over guests at Persimmon Manor were quality people (116).","notesPages":[421],"id":"glossary-entry-people-quality","letter":"P"},{"term":"PEOPLE (QUOTE HIM BY NAME)","definition":"Implied restriction on naming the most intelligent AMH computer (33).","notesPages":[421],"id":"glossary-entry-people-quote-him-by-name","letter":"P"},{"term":"PEOPLE (REAL BOOKS)","definition":"Small numbers of people who still read books from the pre- postliterate age (9).","notesPages":[421],"id":"glossary-entry-people-real-books","letter":"P"},{"term":"PEOPLE (REGULAR)","definition":"Non-ethnic humans who disappeared after \"we had all become ethnics\" (6, 11).","notesPages":[421],"id":"glossary-entry-people-regular","letter":"P"},{"term":"PEOPLE (ROAD-PEOPLE)","definition":"Lowly folk into whose family the King and Creator was born (155).","notesPages":[421],"id":"glossary-entry-people-road-people","letter":"P"},{"term":"PEOPLE (ROMANY)","definition":"See GYPSY.","notesPages":[421],"id":"glossary-entry-people-romany","letter":"P"},{"term":"PEOPLE (ROUGH AND POOR)","definition":"Joined earlier fellows underground, investigating facilities (44).","notesPages":[421],"id":"glossary-entry-people-rough-and-poor","letter":"P"},{"term":"PEOPLE (SECOND)","definition":"See SECOND PEOPLE.","notesPages":[422],"id":"glossary-entry-people-second","letter":"P"},{"term":"PEOPLE (SEEING NEW MARVELS)","definition":"Analogy for fish flocking to Inneall's Ocean (138).","notesPages":[422],"id":"glossary-entry-people-seeing-new-marvels","letter":"P"},{"term":"PEOPLE (SOMEBODIES' PLANNING)","definition":"Dubu suggests the Royal Kids might be too awkward for unnamed planners (113).","notesPages":[422],"id":"glossary-entry-people-somebodies-planning","letter":"P"},{"term":"PEOPLE (TALKING)","definition":"Humans are contrasted with talking animals (54).","notesPages":[422],"id":"glossary-entry-people-talking","letter":"P"},{"term":"PEOPLE (THAT KNOW ANSWERS)","definition":"Dubu laments that the people who know the ultimate answers (like Luas and Lutin) are too ethical to tell them (74).","notesPages":[422],"id":"glossary-entry-people-that-know-answers","letter":"P"},{"term":"PEOPLE (THAT KNOW EVERYTHING)","definition":"Many bears in their natural state, according to Dubu (75).","notesPages":[422],"id":"glossary-entry-people-that-know-everything","letter":"P"},{"term":"PEOPLE (THEY-WHO-WILL-DIE-TODAY)","definition":"Term used by Sebastian Lazar for Donatus O'Reily and Hieronymous Zchold (154); likely refers to They-Who-Will-Die-Today.","notesPages":[422],"id":"glossary-entry-people-they-who-will-die-today","letter":"P"},{"term":"PEOPLE (TURTLE-SOUP FACTORY)","definition":"Dubu claims the workers are exceptionally smart because they read cryptic information on turtles’ tongues (75).","notesPages":[422],"id":"glossary-entry-people-turtle-soup-factory","letter":"P"},{"term":"PEOPLE (UNFALLEN)","definition":"See UNFALLEN PEOPLE.","notesPages":[422],"id":"glossary-entry-people-unfallen","letter":"P"},{"term":"PEOPLE (UNWASHED COMMONERS)","definition":"Henryetta's derogatory term for the vast majority of the population (63); likely refers to \"Unwashed Commoners\".","notesPages":[422],"id":"glossary-entry-people-unwashed-commoners","letter":"P"},{"term":"PEOPLE (VEGETARIAN)","definition":"Enjoyed the 'Hay a la Riesin' specialty (58).","notesPages":[422],"id":"glossary-entry-people-vegetarian","letter":"P"},{"term":"PEOPLE WHO HAD NOT FALLEN (THE)","definition":"The inhabitants of Second Eden, God's \"Ace Card\"; identified as the Unfallen People (11).","notesPages":[423],"id":"glossary-entry-people-who-had-not-fallen-the","letter":"P"},{"term":"PEOPLE (WHO KNEW UNFALLENS)","definition":"The merry African persons accompanying Axel Grindstone (15).","notesPages":[422],"id":"glossary-entry-people-who-knew-unfallens","letter":"P"},{"term":"PEOPLE (WHO WORRIED)","definition":"A few humans, like the Lynn-Randals, who worried about humanity's lack of capacity for change and growth, setting up experiments like the one involving The Three (40).","notesPages":[422],"id":"glossary-entry-people-who-worried","letter":"P"},{"term":"PEOPLE (WILLFUL)","definition":"Individuals who decided the Global Village should act like one, leading to the Floating World (79).","notesPages":[422],"id":"glossary-entry-people-willful","letter":"P"},{"term":"PERCENT (EIGHTY-FIVE HUMAN)","definition":"Ruddy Lord Randal seems only this much human, resembling Red Raiders of Mars (63).","notesPages":[423],"id":"glossary-entry-percent-eighty-five-human","letter":"P"},{"term":"PERCENT (EIGHTY-SEVEN)","definition":"Proportion of the world's population eliminated by the Kangaroo's levellers (81).","notesPages":[423],"id":"glossary-entry-percent-eighty-seven","letter":"P"},{"term":"PERCENT (FIFTY)","definition":"Initial demand by female AMHs for gender representation parity (69).","notesPages":[423],"id":"glossary-entry-percent-fifty","letter":"P"},{"term":"PERCENT (FIFTY-SEVEN)","definition":"Amended demand by female AMHs for gender representation, to atone for past inequities (69).","notesPages":[423],"id":"glossary-entry-percent-fifty-seven","letter":"P"},{"term":"PERCENT (NINETY, MALE AMHS)","definition":"Proportion of AMHs declaring themselves male (69).","notesPages":[423],"id":"glossary-entry-percent-ninety-male-amhs","letter":"P"},{"term":"PERCENT (NINETY-NINE INVISIBLE)","definition":"Degree of invisibility conferred by the special paint (107).","notesPages":[423],"id":"glossary-entry-percent-ninety-nine-invisible","letter":"P"},{"term":"PERCENT (NINETY-SEVEN)","definition":"Proportion of the world's trouble caused by the eighty-seven percent of the population eliminated by levellers (81).","notesPages":[423],"id":"glossary-entry-percent-ninety-seven","letter":"P"},{"term":"PERCENT (ONE, RARIFIED)","definition":"The elite segment Henryetta claims is represented by all the experimental children except Dubu, whom she calls the sole commoner (63).","notesPages":[423],"id":"glossary-entry-percent-one-rarified","letter":"P"},{"term":"PERFECT COMPUTERS","definition":"The ultimate goal intended by the computers of the seventh computer age (37).","notesPages":[423],"id":"glossary-entry-perfect-computers","letter":"P"},{"term":"PERFECT CREATION","definition":"Mankind described as such at origin, despite fitting badly into the world (34).","notesPages":[423],"id":"glossary-entry-perfect-creation","letter":"P"},{"term":"PERFECT CREATURE","definition":"The ultimate being the Theos attempts to make on the lathe in creation legend; six \"Almost Perfect\" versions are deactivated, the seventh (Mankind) is flawed but escapes deactivation (36-37).","notesPages":[423],"id":"glossary-entry-perfect-creature","letter":"P"},{"term":"PERFECT WORKERS (WHALES)","definition":"Description of the Whales, who seem to do little but accomplish prodigies while in their perpetual hyper-active dream-state (136).","notesPages":[423],"id":"glossary-entry-perfect-workers-whales","letter":"P"},{"term":"PERFECTION","definition":"Characteristic of the climate in Second Eden (16).","notesPages":[424],"id":"glossary-entry-perfection","letter":"P"},{"term":"PERFORMERS (NATURAL-BORN)","definition":"The animal members of the Experiments (Elephant, Wolverene, Parrot) are described as consummate showpersons, hams, comedians, athletes, and tricksters (86).","notesPages":[424],"id":"glossary-entry-performers-natural-born","letter":"P"},{"term":"PERIL (DIRE)","definition":"The state of a ship when its mate consults the skeleton in the closet (114).","notesPages":[424],"id":"glossary-entry-peril-dire","letter":"P"},{"term":"PERIPHERY (EXPLODING SEED-POD)","definition":"Sebastian Lazar describes himself as being on the periphery of the \"seed-pod\" (the experimental group) when it exploded (scattered) (162).","notesPages":[424],"id":"glossary-entry-periphery-exploding-seed-pod","letter":"P"},{"term":"PERMANENT SUITE (SATRAP'S)","definition":"Satrap Saint Ledger maintained a permanent suite at the New Eden Hotel in Ape Alley (47).","notesPages":[424],"id":"glossary-entry-permanent-suite-satraps","letter":"P"},{"term":"PERSIAN GULF PORPOISE","definition":"Species name associated with the Green Porpoise depicted on the Saint Ledger coat-of-arms (49).","notesPages":[424],"id":"glossary-entry-persian-gulf-porpoise","letter":"P"},{"term":"PERSIMMON MANOR","definition":"See HOUSE (BIG HOUSE/PERSIMMON MANOR).","notesPages":[424],"id":"glossary-entry-persimmon-manor","letter":"P"},{"term":"PERSIMMON WINE","definition":"See WINE (PERSIMMON).","notesPages":[424],"id":"glossary-entry-persimmon-wine","letter":"P"},{"term":"PERSIMMON WOOD","definition":"The type of wood from which Persimmon Manor is entirely built; noted as being particularly susceptible to haunting due to its connection to the animistic period of mankind (124-125).","notesPages":[424],"id":"glossary-entry-persimmon-wood","letter":"P"},{"term":"PERSONAL DEFENSE","definition":"Implied justification for Henryetta wanting a knife (134).","notesPages":[424],"id":"glossary-entry-personal-defense","letter":"P"},{"term":"PERSONAL OFFENSE","definition":"Alpha declares he will regard any attack on Inneall by the Dolophonoi as such (52).","notesPages":[424],"id":"glossary-entry-personal-offense","letter":"P"},{"term":"PERSONALITIES (MAGNETIC)","definition":"See MAGNETIC PERSONALITIES (EMPRESS ELEPHANTS).","notesPages":[424],"id":"glossary-entry-personalities-magnetic","letter":"P"},{"term":"PERSONALITY (MARINO)","definition":"Described as pleasant, personable, friendly, and outgoing, gleaming like his wet hide (60).","notesPages":[424],"id":"glossary-entry-personality-marino","letter":"P"},{"term":"PERVERSE (LORD RANDAL)","definition":"Henryetta's accusation when Randal refuses to read the name on the knuckle-bone immediately (146).","notesPages":[425],"id":"glossary-entry-perverse-lord-randal","letter":"P"},{"term":"PERVERTED (PRINCIPLES)","definition":"Principles of law and justice are disregarded or perverted in a Kangaroo court (79).","notesPages":[425],"id":"glossary-entry-perverted-principles","letter":"P"},{"term":"PET","definition":"Term of endearment used by Rose-of-Sharon Montdrago when addressing Inneall (117).","notesPages":[425],"id":"glossary-entry-pet","letter":"P"},{"term":"PFC JOSEPH VUKOVITCH","definition":"The attribution attached to the novel’s Viet-Nam Diary excerpt on Angkor Wat (132). The notes have not established this as an independently published diary.","notesPages":[425],"id":"glossary-entry-pfc-joseph-vukovitch","letter":"P"},{"term":"PHONEY","definition":"The Royal Kids suspected by Roy Latta of being phoney themselves due to association with the 'obviously phoney' Invisible Alfred (113). CRYPTO-MEMORY: The hidden recesses of human memory in which Livius locates the mythological roots of Ambulatory Computers (70).","notesPages":[425],"id":"glossary-entry-phoney","letter":"P"},{"term":"PHRASE ('FLOATING WORLD')","definition":"Term initially used by Japanese for Bohemian/Arty/ Unmoored world, later applied to the global condition (Floating World) (1, 79).","notesPages":[425],"id":"glossary-entry-phrase-floating-world","letter":"P"},{"term":"PHRASE ('WHEN THE SEA SHALL GIVE UP ITS DEAD')","definition":"Biblical quotation possibly relevant to the status of the entombed Royal Kids (161).","notesPages":[425],"id":"glossary-entry-phrase-when-the-sea-shall-give-up-its-dead","letter":"P"},{"term":"PHYSICAL MODIFICATIONS","definition":"Structural, chemical, electronic, meteorological, geological changes effected by computers on their environment (27).","notesPages":[425],"id":"glossary-entry-physical-modifications","letter":"P"},{"term":"PHYSICIAN (CONSTELLATED)","definition":"See CONSTELLATED PHYSICIAN.","notesPages":[425],"id":"glossary-entry-physician-constellated","letter":"P"},{"term":"PIANO","definition":"Musical instrument; player piano invented by Edwin Votey (25); Luas plays with strange effect (77); someone plays inside Jack Flannagan's Piano Bar (152).","notesPages":[425],"id":"glossary-entry-piano","letter":"P"},{"term":"PIANO BAR (JACK FLANNAGAN'S)","definition":"See JACK FLANNAGAN'S PIANO BAR AND SIDEWALK CAFE.","notesPages":[426],"id":"glossary-entry-piano-bar-jack-flannagans","letter":"P"},{"term":"PIANO KEYS","definition":"Components of a piano; Luas's fingers don't actually come very close to them when he plays (77).","notesPages":[426],"id":"glossary-entry-piano-keys","letter":"P"},{"term":"PIANO MUSIC","definition":"Music composed for the piano; player pianos allowed composition without concern for human hand limitations (25).","notesPages":[426],"id":"glossary-entry-piano-music","letter":"P"},{"term":"PIKES (FISH)","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[426],"id":"glossary-entry-pikes-fish","letter":"P"},{"term":"PILLARS (LIMESTONE)","definition":"Stone columns formed naturally in Ape Caverns (45); large pillars sculpted by sea-lice in Whale Temple-City (138).","notesPages":[426],"id":"glossary-entry-pillars-limestone","letter":"P"},{"term":"PILOTS (SPEEDSTERS)","definition":"Lord Randal the Boy Human and Marino the Boy Seal are the assigned pilots of the fast boats (Jolly Roger, Crabby Roger) (58).","notesPages":[426],"id":"glossary-entry-pilots-speedsters","letter":"P"},{"term":"PIPEFISHES","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[426],"id":"glossary-entry-pipefishes","letter":"P"},{"term":"PIPES (IRON-ZINK-LEAD)","definition":"Conduits made by Axel's Apes to tap gas wells (45).","notesPages":[426],"id":"glossary-entry-pipes-iron-zink-lead","letter":"P"},{"term":"PIPES (RUM)","definition":"Large casks for storing rum, mentioned alongside hogsheads, butts, and tuns (99).","notesPages":[426],"id":"glossary-entry-pipes-rum","letter":"P"},{"term":"PIRACY (COVENANTED)","definition":"The formal agreement binding the Annabella crew (\"'all for one and one for all, share and share alike...'\") (119).","notesPages":[426],"id":"glossary-entry-piracy-covenanted","letter":"P"},{"term":"PIRATE","definition":"Sebastian Lazar identifies himself as such (101, 153, 161); Lanternjaw Lunnigan (119); Gammon Lanternjaw (98); Hosea Lanternjaw (98).","notesPages":[426],"id":"glossary-entry-pirate","letter":"P"},{"term":"PIRATE CHANTEY","definition":"Sea song associated with pirates; epigraph for Chapter Nine (92).","notesPages":[426],"id":"glossary-entry-pirate-chantey","letter":"P"},{"term":"PIRATE CREW","definition":"The seamen aboard the Annabella Saint Ledger, initially employed by Satrap, later covenanted to Inneall (47, 49, 108, 119).","notesPages":[426],"id":"glossary-entry-pirate-crew","letter":"P"},{"term":"PIRATE CREWMAN (LANTERNJAW LUNNIGAN)","definition":"See LANTERNJAW LUNNIGAN.","notesPages":[427],"id":"glossary-entry-pirate-crewman-lanternjaw-lunnigan","letter":"P"},{"term":"PIRATE DUDS","definition":"Clothing resembling traditional pirate attire, sent to the Annabella crew by a costumer at the behest of Inneall and Henryetta (99).","notesPages":[427],"id":"glossary-entry-pirate-duds","letter":"P"},{"term":"PIRATE FAMILY (LANTERNJAWS)","definition":"The Lanternjaw family has been involved in piracy for many centuries (98).","notesPages":[427],"id":"glossary-entry-pirate-family-lanternjaws","letter":"P"},{"term":"PIRATE LEGEND","definition":"See LEGEND (PIRATE).","notesPages":[427],"id":"glossary-entry-pirate-legend","letter":"P"},{"term":"PIRATE MOGULS","definition":"Extremely wealthy and powerful pirates who possess secret underwater houses (101).","notesPages":[427],"id":"glossary-entry-pirate-moguls","letter":"P"},{"term":"PIRATE NAMES","definition":"Contrived names (\"Sebastian Lazar,\" \"Quentillius Quern the Fifth\") given by Inneall and Henryetta to crewmen Hector Brown and Jasper Jones (98).","notesPages":[427],"id":"glossary-entry-pirate-names","letter":"P"},{"term":"PIRATE QUEEN","definition":"Role adopted by Inneall (Bloody Mary Muldoon) (24, 59, 68).","notesPages":[427],"id":"glossary-entry-pirate-queen","letter":"P"},{"term":"PIRATE (SEBASTIAN LAZAR)","definition":"See LAZAR, SEBASTIAN.","notesPages":[426],"id":"glossary-entry-pirate-sebastian-lazar","letter":"P"},{"term":"PIRATE SHIP","definition":"Vessel used for piracy; the Golden Hind (96); The Unrepentent Rascal (102).","notesPages":[427],"id":"glossary-entry-pirate-ship","letter":"P"},{"term":"PIRATE-SKELETONS","definition":"The future state of the crew aboard the invisible Annabella Saint Ledger, forming part of its legend (121).","notesPages":[427],"id":"glossary-entry-pirate-skeletons","letter":"P"},{"term":"PIRATED (GAMMON LANTERNJAW)","definition":"Engaged in piracy; Gammon Lanternjaw pirated well into the 20th century (98).","notesPages":[427],"id":"glossary-entry-pirated-gammon-lanternjaw","letter":"P"},{"term":"PIRATES","definition":"Inneall needs 'able-bodied pirates' for her crew (44); Great Pirates were often extradigitals (25); historically adhered to the Old Religion (122); supposed to drink rum (99); bleed a lot in combat (101).","notesPages":[427],"id":"glossary-entry-pirates","letter":"P"},{"term":"PIRATES (COMMON)","definition":"Ordinary pirates, distinguished from Pirate Queens (24).","notesPages":[427],"id":"glossary-entry-pirates-common","letter":"P"},{"term":"PIRATES (GREAT, EXTRADIGITALS)","definition":"See GREAT PIRATES.","notesPages":[427],"id":"glossary-entry-pirates-great-extradigitals","letter":"P"},{"term":"PIRATES (HIGH-STEPPING)","definition":"Inneall wants her crew to be lively and agile (99).","notesPages":[427],"id":"glossary-entry-pirates-high-stepping","letter":"P"},{"term":"PIRATES (SICK)","definition":"Bilge-water tonic is the universal cure-all for them (100).","notesPages":[428],"id":"glossary-entry-pirates-sick","letter":"P"},{"term":"PISCES","definition":"The Fishes, twelfth sign of the conventional zodiac; its conventional mask hides the true sign of two Leviathans (111).","notesPages":[428],"id":"glossary-entry-pisces","letter":"P"},{"term":"PITS (STRIP)","definition":"Areas where surface mining occurred; located on the northeast corner of the city, site where Inneall began creating her Ocean (24, 91).","notesPages":[428],"id":"glossary-entry-pits-strip","letter":"P"},{"term":"PLACE","definition":"Used frequently in various contexts (e.g., proper places, 5; this place, 12; impossible place, 38; taking his place, 19, 156).","notesPages":[428],"id":"glossary-entry-place","letter":"P"},{"term":"PLANE (JACK PLANE)","definition":"Carpenter's tool cited as an example of an asinine machine name (31).","notesPages":[428],"id":"glossary-entry-plane-jack-plane","letter":"P"},{"term":"PLANETES","definition":"Celestial bodies orbiting a star; planets in astrology have little connection to actual planets (30); planets in the solar system (implied) (29).","notesPages":[428],"id":"glossary-entry-planetes","letter":"P"},{"term":"PLANNED (NOT AS PLANNED)","definition":"Machiavelli Giovane notes that solutions arise even if things are not at all as planned (78).","notesPages":[428],"id":"glossary-entry-planned-not-as-planned","letter":"P"},{"term":"PLANNING (SOMEBODIES')","definition":"Dubu speculates the Royal Kids might be too awkward for unnamed entities' plans (113).","notesPages":[428],"id":"glossary-entry-planning-somebodies","letter":"P"},{"term":"PLANS","definition":"Loosely preconceived plans carried out while asleep (142); plans made by the Nine in the crows-nest (149); plans of the Intelligent Computers regarding humans (41).","notesPages":[428],"id":"glossary-entry-plans","letter":"P"},{"term":"PLANS (LOOSELY PRECONCEIVED)","definition":"Intentions formed beforehand but not rigidly detailed, carried out during Ocean Sleep (142).","notesPages":[428],"id":"glossary-entry-plans-loosely-preconceived","letter":"P"},{"term":"PLANS (OUR)","definition":"Refers to the Council of War decisions made by the Nine, overheard by Invisible Alfred (149).","notesPages":[428],"id":"glossary-entry-plans-our","letter":"P"},{"term":"PLANT (NEWSPAPER)","definition":"Facility where the Ape Alley newspaper was printed (46).","notesPages":[428],"id":"glossary-entry-plant-newspaper","letter":"P"},{"term":"PLANTED ORNAMENTAL TREES","definition":"Vegetation used to beautify the old strip pits (24).","notesPages":[428],"id":"glossary-entry-planted-ornamental-trees","letter":"P"},{"term":"PLANTS (EXPERIMENTAL)","definition":"Flora developed for specific purposes, part of The Three's habitat (e.g., bread-bushes, honey-cane, fat-berry vines) (3).","notesPages":[429],"id":"glossary-entry-plants-experimental","letter":"P"},{"term":"PLASMA (BLOOD)","definition":"200 kg suggested as cargo for the Annabella due to pirates bleeding heavily (101).","notesPages":[429],"id":"glossary-entry-plasma-blood","letter":"P"},{"term":"PLAYER (BEST HURLEY)","definition":"Saint Brandon, the only one ever rated a nine-goal player (65).","notesPages":[429],"id":"glossary-entry-player-best-hurley","letter":"P"},{"term":"PLAYER (BEST LACROSSE)","definition":"Gajah, directing her mother Riesin telepathically (65).","notesPages":[429],"id":"glossary-entry-player-best-lacrosse","letter":"P"},{"term":"PLAYER PIANO","definition":"Mechanical piano invented by Edwin Votey (1897); allowed music composition beyond human hand limitations and exemplified computers doing things humans couldn't (25).","notesPages":[429],"id":"glossary-entry-player-piano","letter":"P"},{"term":"PLAYING CARDS","definition":"See CARDS (PLAYING).","notesPages":[429],"id":"glossary-entry-playing-cards","letter":"P"},{"term":"PLAYING ROLES (HUMANS, COMPUTERS)","definition":"Actors in the silent movies shown in Ape Alley (46).","notesPages":[429],"id":"glossary-entry-playing-roles-humans-computers","letter":"P"},{"term":"PLAYS (IRISH ABBEY LANE)","definition":"See IRISH ABBEY LANE PLAYS.","notesPages":[429],"id":"glossary-entry-plays-irish-abbey-lane","letter":"P"},{"term":"PLAYS (MYSTERY)","definition":"See MYSTERY PLAY.","notesPages":[429],"id":"glossary-entry-plays-mystery","letter":"P"},{"term":"PLEASANT","definition":"Snakes considered pleasant creatures (3); Player Piano a pleasant device (25); Henryetta pleasant though contrary (61); Lutin a pleasant enigma (62); Carcajou pleasant when he wanted to be (64); Marino pleasant (60); movement of clubroom rather pleasant (74); ocean adventure a pleasant distraction (134); pleasant places of dragons (131); pleasant name (Sea-Cat) (138); pleasant home (Tom Dooley's Island) (100).","notesPages":[429],"id":"glossary-entry-pleasant","letter":"P"},{"term":"PLEASURE PEOPLE","definition":"Crowds gathered at New Oceanside (formerly Heart's Desire Cove) primarily for entertainment; they heckle Invisible Alfred (59, 109, 158).","notesPages":[429],"id":"glossary-entry-pleasure-people","letter":"P"},{"term":"PLEDGED (HENRYETTA)","definition":"Henryetta pledged her entire being in loyalty to the other eleven contemporaries (61).","notesPages":[429],"id":"glossary-entry-pledged-henryetta","letter":"P"},{"term":"PLEROMA","definition":"Gnostic term for totality or fullness; Invisible Alfred claims to have drawn the pleroma in the sky with his celestial signs (111).","notesPages":[430],"id":"glossary-entry-pleroma","letter":"P"},{"term":"PLOD ON FOREWARD","definition":"Human response when faced with an impossible situation or intellectual impasse (38).","notesPages":[430],"id":"glossary-entry-plod-on-foreward","letter":"P"},{"term":"PLUSH (FATHER)","definition":"Inneall's elegant designated father who lived in a super-lush penthouse (52).","notesPages":[430],"id":"glossary-entry-plush-father","letter":"P"},{"term":"PLUSH (STRUCTO LANE)","definition":"Description of the luxurious nature of the Structo Lane enclave (69, 70).","notesPages":[430],"id":"glossary-entry-plush-structo-lane","letter":"P"},{"term":"POE","definition":"Edgar Allan Poe, author of the verse (\"'Here once through an alley titanic...'\") used as epigraph for Chapter Five (43).","notesPages":[430],"id":"glossary-entry-poe","letter":"P"},{"term":"POEM (INNEALL'S)","definition":"Verse epigraph (\"'They erred when they wakened me...'\") for Chapter Three (23).","notesPages":[430],"id":"glossary-entry-poem-innealls","letter":"P"},{"term":"POINT-BLANK PIECES (90-MM)","definition":"Short-range artillery weapons included in the armament of the Annabella Saint Ledger (101).","notesPages":[430],"id":"glossary-entry-point-blank-pieces-90-mm","letter":"P"},{"term":"POINT (MATERIAL)","definition":"The tangible or physical aspect that the parable-universe is intended to illustrate (112).","notesPages":[430],"id":"glossary-entry-point-material","letter":"P"},{"term":"POINTS (BOXED IN)","definition":"Positions where humans feel constrained or limited by computers (38).","notesPages":[430],"id":"glossary-entry-points-boxed-in","letter":"P"},{"term":"POISONOUS (BLOOMS)","definition":"Certain high-headed, divergent, exuberant blooms (metaphor for exceptional individuals) were poisonous to the common weal (81).","notesPages":[430],"id":"glossary-entry-poisonous-blooms","letter":"P"},{"term":"POKER","definition":"Card game; humans love to play it but don't understand its psychology (38).","notesPages":[430],"id":"glossary-entry-poker","letter":"P"},{"term":"POLICE BOATS","definition":"Vessels carrying officials who arrive to oversee the stoning of Hieronymous Zchold (158).","notesPages":[430],"id":"glossary-entry-police-boats","letter":"P"},{"term":"POLITENESS (OVER-)","definition":"See OVERPOLITENESS.","notesPages":[430],"id":"glossary-entry-politeness-over","letter":"P"},{"term":"POLTER","definition":"A noisy, mischievous ghost; Inneall has a \"light-minded polter\" dwelling in her part of the time (3); polters can inhabit empty AMH Computers (28).","notesPages":[430],"id":"glossary-entry-polter","letter":"P"},{"term":"PONTIFICAL WAY (POPUGAI)","definition":"Manner of speaking adopted by Popugai when making pronouncements, suggesting authority or dogma (e.g., \"'When the seed-pod explodes...'\") (161).","notesPages":[431],"id":"glossary-entry-pontifical-way-popugai","letter":"P"},{"term":"POOLS","definition":"Small bodies of water within The Three's habitat where nutrient-mud formed (3).","notesPages":[431],"id":"glossary-entry-pools","letter":"P"},{"term":"POOP DECK","definition":"Raised deck at the stern of a ship; Invisible Alfred speaks to the multitudes from the \"high little poop deck\" of the Annabella Saint Ledger (109, 152).","notesPages":[431],"id":"glossary-entry-poop-deck","letter":"P"},{"term":"POOR","definition":"Poor and barefoot Prophets (109); Tom Dooley was poor (124); rough and poor people investigate underground (44).","notesPages":[431],"id":"glossary-entry-poor","letter":"P"},{"term":"POOR BUTTERFLY","definition":"Dubu's expression of sympathy for Rose-of- Sharon Montdrago after hearing about her lost Mega Person rating (117).","notesPages":[431],"id":"glossary-entry-poor-butterfly","letter":"P"},{"term":"POOR PIRATES","definition":"Lanternjaw Lunnigan's self-deprecating description of his crew, suggesting they aren't worthy of the grand legend Inneall envisions (121).","notesPages":[431],"id":"glossary-entry-poor-pirates","letter":"P"},{"term":"POP ART","definition":"Modern art style; the tapestry depicting Satrap as a Sea Monster is a masterwork of pop art (144).","notesPages":[431],"id":"glossary-entry-pop-art","letter":"P"},{"term":"POPE JOAN","definition":"Legendary female pope; also the name/face (\"Poupe Jaune\") of the Yellow Dwarf figure (with Gargoyle face) on the Saint Ledger coat-of-arms (49).","notesPages":[431],"id":"glossary-entry-pope-joan","letter":"P"},{"term":"POPUGAI","definition":"The young male Kea parrot of the Gruenbaum-McGregor Experiment (55, 64); possesses extraordinary memory and understanding of numerous languages (64); has the best overview (\"long view\") due to high flight and sharp eyesight (64); provides information about Carcajou's transformations (73); requires ballast for diving (134); survives the final events and plans to return to New Zealand for Interspecies Counseling (161); declares Randal Captain (122).","notesPages":[431],"id":"glossary-entry-popugai","letter":"P"},{"term":"POPULAR ATTRACTIONS","definition":"Axel's Apes kept in zoos were popular attractions (20).","notesPages":[431],"id":"glossary-entry-popular-attractions","letter":"P"},{"term":"POPULAR CRY (HARVEST TIME)","definition":"\"'This is the harvest time,'\" a saying used to justify culling the tares (undesirables) from the wheat (humanity) (81).","notesPages":[432],"id":"glossary-entry-popular-cry-harvest-time","letter":"P"},{"term":"POPULAR IDEA (RANDAL)","definition":"The notion that Lord Randal wouldn't be popular with common people because he was fair/red while they were the dark 'tide of color'; proven wrong (123).","notesPages":[432],"id":"glossary-entry-popular-idea-randal","letter":"P"},{"term":"POPULAR MEANING (BIRD-BRAINED)","definition":"Common understanding of \"bird-brained\" as simple-minded, applied to the Birdmaster (60).","notesPages":[432],"id":"glossary-entry-popular-meaning-bird-brained","letter":"P"},{"term":"POPULAR NEWS","definition":"General information and current events circulating among the populace; AMHs know what is happening regardless of human attempts to withhold information (28).","notesPages":[432],"id":"glossary-entry-popular-news","letter":"P"},{"term":"POPULATION (COMPUTER)","definition":"The entire global network of computers, subject to constant scan by the Kangaroo (82).","notesPages":[432],"id":"glossary-entry-population-computer","letter":"P"},{"term":"POPULATION (GENERAL)","definition":"See GENERAL POPULATION.","notesPages":[432],"id":"glossary-entry-population-general","letter":"P"},{"term":"POPULATION (MEGA PERSON ELIMINATION)","definition":"Most persons capable of killing had been eliminated from all ranks below Mega Person level, making the three hunters' task difficult (89).","notesPages":[432],"id":"glossary-entry-population-mega-person-elimination","letter":"P"},{"term":"PORCUPINE FISHES","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[432],"id":"glossary-entry-porcupine-fishes","letter":"P"},{"term":"PORPOISE (GREEN)","definition":"See GREEN PORPOISE.","notesPages":[432],"id":"glossary-entry-porpoise-green","letter":"P"},{"term":"PORPOISE (PERSIAN GULF)","definition":"See PERSIAN GULF PORPOISE.","notesPages":[432],"id":"glossary-entry-porpoise-persian-gulf","letter":"P"},{"term":"PORPOISE (SATRAP)","definition":"See SATRAP PORPOISE.","notesPages":[432],"id":"glossary-entry-porpoise-satrap","letter":"P"},{"term":"PORPOISES","definition":"Marine mammals, distinct from dolphins; seldom able to reach deep ocean depths unless they learn Oceanic Metastasis (139).","notesPages":[432],"id":"glossary-entry-porpoises","letter":"P"},{"term":"PORTRAITURE ART (WHALES)","definition":"The art of creating likenesses, specifically the high-relief sculptures cut by sea-lice under Whale direction (138).","notesPages":[432],"id":"glossary-entry-portraiture-art-whales","letter":"P"},{"term":"POSITION (KANGAROO)","definition":"A role within the Kangaroo organization belongs to whoever occupies it, subject to violent removal (80).","notesPages":[432],"id":"glossary-entry-position-kangaroo","letter":"P"},{"term":"POSSESSED (MAN ON CENOTAPH)","definition":"The man represented on Zchold's empty cenotaph was possessed by a mixture of conflicting passions (150).","notesPages":[433],"id":"glossary-entry-possessed-man-on-cenotaph","letter":"P"},{"term":"POST-INTELLECTUAL STATE","definition":"Condition required for Imperial Heads of the Kangaroo to hold office, entered after passing through \"radiant intelligence\" (83).","notesPages":[433],"id":"glossary-entry-post-intellectual-state","letter":"P"},{"term":"POST-LITERARY AGE","definition":"The era succeeding widespread literacy, characterized by reliance on multi-track media like 'prowls' instead of traditional books (6).","notesPages":[433],"id":"glossary-entry-post-literary-age","letter":"P"},{"term":"POST-MODERN AGE","definition":"Contemporary era described as seeing computers become still more sophisticated, often beyond human understanding (33).","notesPages":[433],"id":"glossary-entry-post-modern-age","letter":"P"},{"term":"POSTLITERATE AGE (PRE-)","definition":"The time before the post-literary age, associated with traditional books, literatures, musics, arts, and dramas (8, 9).","notesPages":[433],"id":"glossary-entry-postliterate-age-pre","letter":"P"},{"term":"POT (FINGERS STICKING INTO)","definition":"Metaphor used by Lanternjaw Lunnigan for the meddling interference of the \"two Royal Kids\" (Inneall and Henryetta) in shipboard affairs (99).","notesPages":[433],"id":"glossary-entry-pot-fingers-sticking-into","letter":"P"},{"term":"POTLATCH (SOCSOLLABCOMDEM PARTY POTLATCH)","definition":"\"'Socsollabcomdem Party Potlatch,'\" title of a campfire song sung at Heart's Desire Cove (59). (Note: \"Socsollabcomdem\" is likely a Lafferty coinage or obscure reference).","notesPages":[433],"id":"glossary-entry-potlatch-socsollabcomdem-party-potlatch","letter":"P"},{"term":"POUNDS (GRAPES)","definition":"Weight measure; Unfallen Ones work for pounds of grapes (16).","notesPages":[433],"id":"glossary-entry-pounds-grapes","letter":"P"},{"term":"POUNDS (HAMBURGER MEAT)","definition":"One thousand pounds loaded onto the Annabella (101).","notesPages":[433],"id":"glossary-entry-pounds-hamburger-meat","letter":"P"},{"term":"POUNDS (NUGGET GOLD)","definition":"Three hundred pounds of ocean gold brought by dolphins as payment for limestone (106).","notesPages":[433],"id":"glossary-entry-pounds-nugget-gold","letter":"P"},{"term":"POWER","definition":"Force, influence, or ability; generated by The Three's closeness (1); of the Kangaroo (1, 84); concrete power of the State (78); preternatural powers (112); curative powers of Whales (161); prophetic power (134); AMH Computers draw power destructively (30); power over the Devil/Man (35); power over Devils (108); power to put people to sleep (125); sun's power diverted (59); transference of power machinery not yet set up (161).","notesPages":[433,434],"id":"glossary-entry-power","letter":"P"},{"term":"POWER-TOOLS (APES')","definition":"Tools used by the Axel's Apes, motored by tapped natural gas (45).","notesPages":[434],"id":"glossary-entry-power-tools-apes","letter":"P"},{"term":"POWERFUL","definition":"The Kangaroo (1); Dolophonoi-Assassin (94); Unfallen faces (17, 21); voices (108); parts in music (60); beak (65).","notesPages":[434],"id":"glossary-entry-powerful","letter":"P"},{"term":"POWERS","definition":"Entities possessing authority or influence; Principalities and Powers mentioned as potential enemies (107).","notesPages":[434],"id":"glossary-entry-powers","letter":"P"},{"term":"PRACTICE","definition":"Repeated performance to acquire skill; the interviewed AMH proposes that computers practice using human reproductive methods (32); entering/leaving house (160).","notesPages":[434],"id":"glossary-entry-practice","letter":"P"},{"term":"PRACTICE (ENTERING/LEAVING HOUSE)","definition":"The technique of accessing the sunken Persimmon Manor through holes in the uneven floor had to be begun (160).","notesPages":[434],"id":"glossary-entry-practice-entering-leaving-house","letter":"P"},{"term":"PRACTICE (PSEUDO-SCRIPTURAL)","definition":"The explanation (\"'Cast out the old fire and wait and pray for the new'\") given for turning off gas jets before the nightly lightning strike (68).","notesPages":[434],"id":"glossary-entry-practice-pseudo-scriptural","letter":"P"},{"term":"PRACTICED (DOING THINGS WHILE ASLEEP)","definition":"The Nine had already practiced activities like walking, talking, and using weapons while in Ocean Sleep (142).","notesPages":[434],"id":"glossary-entry-practiced-doing-things-while-asleep","letter":"P"},{"term":"PRACTICED (MURDER)","definition":"Schimp infers that Invisible Alfred had practiced murder by ordinary sleepwalking before learning Ocean Sleep (149).","notesPages":[434],"id":"glossary-entry-practiced-murder","letter":"P"},{"term":"PRAISE","definition":"Express approval or admiration; Invisible Alfred claims all voices praise him (108); \"'Praise the Lord, all ye Whales of Ocean'\" (131).","notesPages":[434],"id":"glossary-entry-praise","letter":"P"},{"term":"PRAY","definition":"Address God or divine power; wait and pray for the new fire (68); Iris prayed (90); Alfred prays for patience (108).","notesPages":[434],"id":"glossary-entry-pray","letter":"P"},{"term":"PRAYER (APES')","definition":"Activity occupying eighteen hours daily for the prophet Alpha (51).","notesPages":[434],"id":"glossary-entry-prayer-apes","letter":"P"},{"term":"PRE-POSTLITERATE AGE","definition":"See POSTLITERATE AGE (PRE-).","notesPages":[435],"id":"glossary-entry-pre-postliterate-age","letter":"P"},{"term":"PREACH","definition":"Deliver a sermon or religious address; Invisible Alfred preaches to the damned Devil-Fish (108) and the multitudes (39, 108).","notesPages":[434],"id":"glossary-entry-preach","letter":"P"},{"term":"PRECEDENT","definition":"An earlier event serving as an example; claimed lacking for humans coming first in time before AMHs (27).","notesPages":[435],"id":"glossary-entry-precedent","letter":"P"},{"term":"PRECESSION OF THE EQUINOXES","definition":"The slow change in the orientation of Earth’s rotational axis. The novel uses “procession” in an AMH’s account of correcting astrology (30); that passage is not evidence for astrology’s predictive validity.","notesPages":[439],"id":"glossary-entry-precession-of-the-equinoxes","letter":"P"},{"term":"PRECIOUS ISLAND","definition":"Description of Tom Dooley's Island in Josh Elderhouse's poem (159).","notesPages":[435],"id":"glossary-entry-precious-island","letter":"P"},{"term":"PRECONCEIVED PLANS (LOOSELY)","definition":"See PLANS (LOOSELY PRECONCEIVED).","notesPages":[435],"id":"glossary-entry-preconceived-plans-loosely","letter":"P"},{"term":"PREDECESSORS","definition":"Those who came before; Mankind appeared without predecessors (34).","notesPages":[435],"id":"glossary-entry-predecessors","letter":"P"},{"term":"PREDICT","definition":"Computers use astrology to predict human futures (30).","notesPages":[435],"id":"glossary-entry-predict","letter":"P"},{"term":"PREDICTED (ISLAND SINKING)","definition":"Lutin predicted the timing and measurements of Tom Dooley's Island sinking (101).","notesPages":[435],"id":"glossary-entry-predicted-island-sinking","letter":"P"},{"term":"PREDICTING (EXPERIMENTS)","definition":"The experiments are designed to discern and predict the best and worst results of unusual combinations of beings and circumstances (81-82).","notesPages":[435],"id":"glossary-entry-predicting-experiments","letter":"P"},{"term":"PREDICTION","definition":"A statement foretelling the future; Computers cannot distinguish prediction from instruction (1); astrology as a prediction game (29).","notesPages":[435],"id":"glossary-entry-prediction","letter":"P"},{"term":"PREDICTIONS","definition":"Statements foretelling future events; Computers make true predictions easier than false ones (30); Lutin's predictions trusted (101).","notesPages":[435],"id":"glossary-entry-predictions","letter":"P"},{"term":"PREEMPTORY WAY (HENRYETTA)","definition":"Commanding or authoritative manner; Henryetta orders the brass cannon mounted immediately (95).","notesPages":[435],"id":"glossary-entry-preemptory-way-henryetta","letter":"P"},{"term":"PREFERENCE (HUMAN, FOR LINEARITY)","definition":"Humans favor straight lines, which computers find too narrow (24).","notesPages":[435],"id":"glossary-entry-preference-human-for-linearity","letter":"P"},{"term":"PRESENCE","definition":"State of being present; powerful presence of Alpha (20) and Mega Dolophonos (94); Inneall's physical presence in Structo Lane (29).","notesPages":[435],"id":"glossary-entry-presence","letter":"P"},{"term":"PRESENT (ETERNAL)","definition":"See ETERNAL PRESENT.","notesPages":[435],"id":"glossary-entry-present-eternal","letter":"P"},{"term":"PRESENT TIME (HEAD OF KANGAROO)","definition":"The brief period during which Invisible Alfred holds the position of Supreme Head of the Kangaroo (149).","notesPages":[436],"id":"glossary-entry-present-time-head-of-kangaroo","letter":"P"},{"term":"PRESENT-TIMES (IMMEDIATE)","definition":"See IMMEDIATE PRESENT- TIMES.","notesPages":[436],"id":"glossary-entry-present-times-immediate","letter":"P"},{"term":"PRESSURE CHAMBER (DIVING)","definition":"Equipment deemed necessary by Lord Randal for deep dives to protect against the bends (133).","notesPages":[436],"id":"glossary-entry-pressure-chamber-diving","letter":"P"},{"term":"PRESSURE (THUMP LANGUAGE)","definition":"Component, along with percussion, of the language used by Riesin to communicate with unborn Gajah (56).","notesPages":[436],"id":"glossary-entry-pressure-thump-language","letter":"P"},{"term":"PRESTER JOHN","definition":"Legendary Christian king; believed by Axel Grindstone to be the King-and- Emperor of the Unfallen People, created 30 years after Adam, living until the Last Day, extremely sleepy but wise (11-12).","notesPages":[436],"id":"glossary-entry-prester-john","letter":"P"},{"term":"PRETERNATURAL POWERS","definition":"Abilities beyond the normal course of nature (setting fires by mind, making oceans, removing mountains); seen by some as indicators of the 'Enlargement of the World' (112).","notesPages":[436],"id":"glossary-entry-preternatural-powers","letter":"P"},{"term":"PRETTY ELEGANT","definition":"Ruddy Lord Randal and Axel are described as becoming quite stylish (53).","notesPages":[436],"id":"glossary-entry-pretty-elegant","letter":"P"},{"term":"PREVAIL (SWEET REASON)","definition":"The unnamed AMH theorist says he preaches that sweet reason will prevail in every deal but that his human partners let emotions intervene (39).","notesPages":[436],"id":"glossary-entry-prevail-sweet-reason","letter":"P"},{"term":"PREVENTION","definition":"Act of stopping something from happening; Henryetta plans vengeance and prevention for midnight (140).","notesPages":[436],"id":"glossary-entry-prevention","letter":"P"},{"term":"PREVIOUS MIND-SETS","definition":"Earlier ways of thinking that would not have allowed the flexibility and speed characteristic of the Floating World (79).","notesPages":[436],"id":"glossary-entry-previous-mind-sets","letter":"P"},{"term":"PREY (DESIGNATED)","definition":"The specific targets assigned to the Dolophonoi-Assassins (85).","notesPages":[436],"id":"glossary-entry-prey-designated","letter":"P"},{"term":"PREY (DOLOPHONOI HUNT)","definition":"The Dolophonoi hunt and kill their prey (50).","notesPages":[436],"id":"glossary-entry-prey-dolophonoi-hunt","letter":"P"},{"term":"PREY (FURTHER, KNIFE SEEKING)","definition":"The animated Dolophonoi knife seeks another victim after killing Axel (148).","notesPages":[437],"id":"glossary-entry-prey-further-knife-seeking","letter":"P"},{"term":"PRICE (CHEAP)","definition":"The cost of the kangaroo knuckle-bone, sold cheaply because the seller had no love for the Kangaroo (146).","notesPages":[437],"id":"glossary-entry-price-cheap","letter":"P"},{"term":"PRIDE","definition":"Quality of high self-esteem or arrogance; part of Man (\"'pride that licks the dust'\") (34); Donatus O'Reily speaks with pride of his heinous offense (122); Inneall's pride is hurt by not being classified as a Serpent's Egg (161).","notesPages":[437],"id":"glossary-entry-pride","letter":"P"},{"term":"PRIDE (OF YOUTH)","definition":"Quality possessed by Inneall/Bloody Mary Muldoon, addressed by Atropos (126); Inneall possesses it (160).","notesPages":[437],"id":"glossary-entry-pride-of-youth","letter":"P"},{"term":"PRIEST","definition":"Clergyman; Hieronymous Ignatius Zchold is a Priest (later revealed as Bishop) of the Old Religion (122).","notesPages":[437],"id":"glossary-entry-priest","letter":"P"},{"term":"PRIESTS' HOLE","definition":"A secret hiding place within Persimmon Manor, used by Zchold during Tom Dooley’s lifetime; Hieronymous Zchold plans to stay there until his execution (122); Sebastian Lazar retrieves the Midnight Cock from it (156).","notesPages":[437],"id":"glossary-entry-priests-hole","letter":"P"},{"term":"PRIMATES","definition":"Order of mammals including humans, apes, monkeys; Homo Sapiens described as the most widespread, numerous, and reputedly intelligent primate (35).","notesPages":[437],"id":"glossary-entry-primates","letter":"P"},{"term":"PRIME ARENAS","definition":"Key locations where significant world events are likely to occur; Ape Alley identified as one (43).","notesPages":[437],"id":"glossary-entry-prime-arenas","letter":"P"},{"term":"PRIME MINISTER","definition":"The current Prime Minister of Ethiopia came from Gamu Gofa province and received instruction from the Unfallen Ones (15).","notesPages":[437],"id":"glossary-entry-prime-minister","letter":"P"},{"term":"PRIME SUSPECT","definition":"The main individual suspected of a crime; Henryetta is the Prime Suspect for burning a city, according to voices heard by Inneall (130).","notesPages":[437],"id":"glossary-entry-prime-suspect","letter":"P"},{"term":"PRINCELY PLACES (SEA FOOD)","definition":"High-quality seafood restaurants at Heart's Desire Cove (Sea-Food Charley's, etc.) (58).","notesPages":[437],"id":"glossary-entry-princely-places-sea-food","letter":"P"},{"term":"PRINCIPALITIES AND POWERS","definition":"High-ranking spiritual entities, often hostile; cited by Satrap as the sort of enemies the invisible ship might face (107); refers to Principalities and Powers.","notesPages":[437],"id":"glossary-entry-principalities-and-powers","letter":"P"},{"term":"PRINCIPLES (OF LAW AND JUSTICE)","definition":"Fundamental tenets disregarded or perverted in a Kangaroo court (79).","notesPages":[438],"id":"glossary-entry-principles-of-law-and-justice","letter":"P"},{"term":"PRINTED (TICKETS)","definition":"Airline tickets printed 'Individual Destination Fully Optional' illustrate paradoxical freedom (41).","notesPages":[438],"id":"glossary-entry-printed-tickets","letter":"P"},{"term":"PRINTED WORD","definition":"Textual component (third track) sometimes included in 'prowls'; initially misinterpreted bizarrely by The Three before they learned the rules of reading (7).","notesPages":[438],"id":"glossary-entry-printed-word","letter":"P"},{"term":"PRINTING","definition":"The process of producing text; The Three initially made bizarre interpretations of it (7).","notesPages":[438],"id":"glossary-entry-printing","letter":"P"},{"term":"PRIVATE PERSONS","definition":"Individuals not acting in an official capacity; possess no weapons (84).","notesPages":[438],"id":"glossary-entry-private-persons","letter":"P"},{"term":"PRIVATE REASONS","definition":"Unspecified motivations for the \"new barbarians\" deciding to pass themselves off as Axel's Apes (9).","notesPages":[438],"id":"glossary-entry-private-reasons","letter":"P"},{"term":"PRIVATE STONING","definition":"Execution method desired by Hieronymous Zchold on Tom Dooley's Island to avoid having dogs devour his body (158).","notesPages":[438],"id":"glossary-entry-private-stoning","letter":"P"},{"term":"PRIVATE WORLDS","definition":"Individual realities or domains; Satrap's hotel suite and Inneall's Ocean represent two such worlds connected by the Allez-Oop (47).","notesPages":[438],"id":"glossary-entry-private-worlds","letter":"P"},{"term":"PRIZES","definition":"Rewards or captured items; the \"blue-eyed yellow apes\" considered prizes by the newcomers (18); the newborn Axel the Ape was a \"prize beyond all prizes\" (19).","notesPages":[438],"id":"glossary-entry-prizes","letter":"P"},{"term":"PROBABILITY MATHEMATICS","definition":"See MATHEMATICS (PROBABILITY).","notesPages":[438],"id":"glossary-entry-probability-mathematics","letter":"P"},{"term":"PROBABLE FACTS","definition":"Likely truths weighed by Axel Grindstone during his research (12).","notesPages":[438],"id":"glossary-entry-probable-facts","letter":"P"},{"term":"PROBABLE OF FULFILLMENT (FEARS)","definition":"The hunters' fears for their 'children', though unnatural for sponsors, were likely to be realized (85).","notesPages":[438],"id":"glossary-entry-probable-of-fulfillment-fears","letter":"P"},{"term":"PROBLEM","definition":"The nature of the solved problem (implied world instability) (79).","notesPages":[438],"id":"glossary-entry-problem","letter":"P"},{"term":"PROBLEM (HOUSE HAUNTED)","definition":"The issue of Persimmon Manor potentially being haunted, discussed by the 'seconds' and the Nine (124).","notesPages":[439],"id":"glossary-entry-problem-house-haunted","letter":"P"},{"term":"PROCESSED (CARGO)","definition":"Handled according to nature and circumstance (refrigerated, fried, put on steam, etc.); applies to cargo loaded onto the Annabella (101).","notesPages":[439],"id":"glossary-entry-processed-cargo","letter":"P"},{"term":"PROCESSES (FINANCIAL)","definition":"Economic operations decided annually by the seven richest metamorphic men during their deep-ocean meeting (135).","notesPages":[439],"id":"glossary-entry-processes-financial","letter":"P"},{"term":"PROCLAIMED (WHALE SIGN)","definition":"The sign \"'We're Glad You're Here'\" put up by the Whales for visitors to their underwater city (136).","notesPages":[439],"id":"glossary-entry-proclaimed-whale-sign","letter":"P"},{"term":"PROCLIVITIES (UNRULY)","definition":"Tendencies towards disorder or nonconformity; Mega-Persons possessing such proclivities might be classified as Serpent's Eggs (127).","notesPages":[439],"id":"glossary-entry-proclivities-unruly","letter":"P"},{"term":"PRODIGIES","definition":"Exhibited during The Three Days of Summerset (54); accomplished by Whales in their dream-state (136).","notesPages":[439],"id":"glossary-entry-prodigies","letter":"P"},{"term":"PRODIGY","definition":"The shocking prodigy of whales weeping one-foot- diameter tears (159).","notesPages":[439],"id":"glossary-entry-prodigy","letter":"P"},{"term":"PRODUCE (PYROTECHNICS)","definition":"Create effects; smell of black-powder and gun-powder produced by pyrotechnics (87).","notesPages":[439],"id":"glossary-entry-produce-pyrotechnics","letter":"P"},{"term":"PROFESSION (DOLOPHONOI)","definition":"The occupation of being a Dolophonos or Assassin has always been a \"top-dog profession\" (50).","notesPages":[439],"id":"glossary-entry-profession-dolophonoi","letter":"P"},{"term":"PROFESSIONAL ATTACK","definition":"An assault by skilled, organized opponents; Satrap questions if the Annabella crew could repel one (101).","notesPages":[439],"id":"glossary-entry-professional-attack","letter":"P"},{"term":"PROFESSIONAL STONERS","definition":"Individuals skilled in execution by stoning; begin the stoning of Hieronymous Zchold (158).","notesPages":[439],"id":"glossary-entry-professional-stoners","letter":"P"},{"term":"PROFILE (VOICE)","definition":"A recording or analysis of vocal characteristics; Inneall had lifted the voice profile of Satrap's deceased five-year-old daughter (52).","notesPages":[440],"id":"glossary-entry-profile-voice","letter":"P"},{"term":"PROPHESYING-AND-DENOUNCING BUSINESS","definition":"The occupation practiced by Invisible Alfred, involving foretelling, condemning, and performing signs (108).","notesPages":[440],"id":"glossary-entry-prophesying-and-denouncing-business","letter":"P"},{"term":"PROPHESYING (PYTHON)","definition":"Foretelling the future, an ability possessed by Lutin (87); an ordinary weapon would not kill a prophesying Python (87).","notesPages":[440],"id":"glossary-entry-prophesying-python","letter":"P"},{"term":"PROPHET","definition":"One who speaks by divine inspiration or foretells the future; Alpha acts as prophet for the Apes' Caverns (51); Invisible Alfred claims to be a Prophet (107, 108, 109, 110, 111, 112, 114, 117, 124); Baalam's Ass was a Prophet (124); Lutin the Pythoness is a Prophetic Python (143).","notesPages":[440],"id":"glossary-entry-prophet","letter":"P"},{"term":"PROPHET (INVISIBLE ALFRED)","definition":"See ALFRED, INVISIBLE.","notesPages":[440],"id":"glossary-entry-prophet-invisible-alfred","letter":"P"},{"term":"PROPHET (PROPHETIC PYTHON)","definition":"Title/role held by Lutin at Heart's Desire Cove (143).","notesPages":[440],"id":"glossary-entry-prophet-prophetic-python","letter":"P"},{"term":"PROPHETESS","definition":"Female prophet; Lutin wishes she weren't one some nights (146).","notesPages":[440],"id":"glossary-entry-prophetess","letter":"P"},{"term":"PROPHETIC CLOUD","definition":"The obscure or veiled nature of the communication between Miol-Mor and the Big Egg, defying clear understanding (160).","notesPages":[440],"id":"glossary-entry-prophetic-cloud","letter":"P"},{"term":"PROPHETIC POWER (PYTHONS)","definition":"Innate ability of pythons, like Lutin, required for achieving full potential through a sabbatical year at the bottom of the ocean (134).","notesPages":[440],"id":"glossary-entry-prophetic-power-pythons","letter":"P"},{"term":"PROPHETIC PYTHONESS","definition":"Descriptive title for Lutin, emphasizing her foresight (74).","notesPages":[440],"id":"glossary-entry-prophetic-pythoness","letter":"P"},{"term":"PROPHETS","definition":"Plural of prophet; usually possess ambiguous voices (108); poor and barefoot Prophets contrasted with the rich and powerful (109).","notesPages":[441],"id":"glossary-entry-prophets","letter":"P"},{"term":"PROPHET'S VOICE","definition":"The manner of speaking used by Invisible Alfred, described as ambiguous (108). GROTESQUE CHILD (AMH): The AMH interviewee reports a naturally born computer-child that did not breed completely true (32). No prophetic gift is specified.","notesPages":[440],"id":"glossary-entry-prophets-voice","letter":"P"},{"term":"PROPRIETY","definition":"Quentillius Quern the Fifth says he had decided to wait until Henryetta was ten before pursuing her (139).","notesPages":[441],"id":"glossary-entry-propriety","letter":"P"},{"term":"PROPS","definition":"Objects needed for a specific purpose; Pirate Queen role needs props (ocean, ships, pirates) (24); AMHs create props by cannibalizing their environment (27).","notesPages":[441],"id":"glossary-entry-props","letter":"P"},{"term":"PROSAIC FLOATING WORLD","definition":"The mundane, ordinary reality of the Floating World, questioned by Inneall as possibly being merely symbols and conventions covering a deeper reality (141).","notesPages":[441],"id":"glossary-entry-prosaic-floating-world","letter":"P"},{"term":"PROTECTION (ALPHA'S)","definition":"Alpha assures Inneall she is under his protection against the Dolophonoi (52).","notesPages":[441],"id":"glossary-entry-protection-alphas","letter":"P"},{"term":"PROTEIN-OIL OLIO-STEW","definition":"See OLIO-STEW (PROTEIN-OIL).","notesPages":[441],"id":"glossary-entry-protein-oil-olio-stew","letter":"P"},{"term":"PROTEST","definition":"Object or complain; somebody may protest the airliner analogy (41).","notesPages":[441],"id":"glossary-entry-protest","letter":"P"},{"term":"PROTESTING (INNEALL)","definition":"Objecting verbally; Inneall stops protesting when threatened with loss of private communication (164).","notesPages":[441],"id":"glossary-entry-protesting-inneall","letter":"P"},{"term":"PROUD (APES)","definition":"Feeling satisfaction in their strength; the Apes chortled, proud of their ability to break the interloping men (18).","notesPages":[441],"id":"glossary-entry-proud-apes","letter":"P"},{"term":"PROVE (NOBODY CAN)","definition":"Henryetta asserts her involvement in the town fires cannot be proven (146).","notesPages":[441],"id":"glossary-entry-prove-nobody-can","letter":"P"},{"term":"PROVENDER (LIVE)","definition":"See LIVE PROVENDER.","notesPages":[441],"id":"glossary-entry-provender-live","letter":"P"},{"term":"PROVINCE (ESTIMATION ERROR)","definition":"Within the range of possible miscalculation (40).","notesPages":[441],"id":"glossary-entry-province-estimation-error","letter":"P"},{"term":"PROVINCE (GAMU GOFA)","definition":"See GAMU GOFA PROVINCE.","notesPages":[441],"id":"glossary-entry-province-gamu-gofa","letter":"P"},{"term":"PROVINCIAL CAPITAL (ARBA MENCH)","definition":"See ARBA MENCH.","notesPages":[442],"id":"glossary-entry-provincial-capital-arba-mench","letter":"P"},{"term":"PROVINCIAL (SPOOKS)","definition":"Inneall describes her indwelling ghosts as ignorant, provincial, and banal (29).","notesPages":[441],"id":"glossary-entry-provincial-spooks","letter":"P"},{"term":"PROVISIONS","definition":"Supplies, especially food and drink; Satrap agrees to continue paying for provisions for Inneall's yacht (48, 101).","notesPages":[442],"id":"glossary-entry-provisions","letter":"P"},{"term":"PROWLING (DOLOPHONOI)","definition":"Moving stealthily; three Dolophonoi- Assassins are prowling around near Apes' Alley (49).","notesPages":[442],"id":"glossary-entry-prowling-dolophonoi","letter":"P"},{"term":"PROWLING (SHALLOWER)","definition":"Diving activity for which small oxygen canisters are sufficient, contrasted with deep diving (133).","notesPages":[442],"id":"glossary-entry-prowling-shallower","letter":"P"},{"term":"PROWLS","definition":"Multi-track media format, alternative name for 'antics', 'romps', etc.; characterized by sketchy visuals, background noise, subliminal geometric forms, and sometimes a printed word track (6, 8, 9).","notesPages":[442],"id":"glossary-entry-prowls","letter":"P"},{"term":"PRUNING HOOKS","definition":"Alternative name for the Dolophonoi or Assassins, instruments of the Kangaroo (83).","notesPages":[442],"id":"glossary-entry-pruning-hooks","letter":"P"},{"term":"PRUNING (HUMANITY)","definition":"Metaphorical process of cleansing humanity by removing the unthrifty and blighted (the lower classes and undesirables), analogous to pruning vineyards or orchards (81).","notesPages":[442],"id":"glossary-entry-pruning-humanity","letter":"P"},{"term":"PSEUDO-DREAM STATE (OCEANIC METASTASIS)","definition":"Satrap Saint Ledger's own term for the state required for deep diving, also called Oceanic Hyper-Active Dream State (135).","notesPages":[442],"id":"glossary-entry-pseudo-dream-state-oceanic-metastasis","letter":"P"},{"term":"PSEUDO-FISH","definition":"The novel’s term for the creature it calls Chimaera Monstrusa, the Nightmare Monster or Sea-Cat (139). Chimaeras are cartilaginous fishes; “pseudo-fish” should not be treated as a zoological classification.","notesPages":[442],"id":"glossary-entry-pseudo-fish","letter":"P"},{"term":"PSEUDO-GRANDFATHER (SATRAP)","definition":"Title used by Henryetta when addressing Satrap Saint Ledger (97).","notesPages":[442],"id":"glossary-entry-pseudo-grandfather-satrap","letter":"P"},{"term":"PSEUDO-SCIENCE (ASTROLOGY)","definition":"Term used by a heckler to dismiss astrology; Alfred counters it is more accurately a 'parable- science' (111).","notesPages":[442],"id":"glossary-entry-pseudo-science-astrology","letter":"P"},{"term":"PSEUDO-SCRIPTURAL EXPLANATION","definition":"The rationale (\"'Cast out the old fire and wait and pray for the new'\") given for the practice of turning off gas jets before the nightly lightning strike in Ape Caverns (68).","notesPages":[442],"id":"glossary-entry-pseudo-scriptural-explanation","letter":"P"},{"term":"PSYCHE","definition":"The human soul or mind; referenced in the Poe epigraph for Chapter Five (\"'Of Cypress, with Psyche my soul'\") (43).","notesPages":[443],"id":"glossary-entry-psyche","letter":"P"},{"term":"PSYCHIC LEVEL","definition":"Level of mental or non-physical abilities; rising greatly above this level triggers Kangaroo analysis (80).","notesPages":[443],"id":"glossary-entry-psychic-level","letter":"P"},{"term":"PSYCHOLOGICAL CONCEPTS","definition":"Ideas relating to the mind and behavior; become more detailed and subdivided further back in time, paralleling linguistic and theological concepts (37).","notesPages":[443],"id":"glossary-entry-psychological-concepts","letter":"P"},{"term":"PSYCHOLOGING","definition":"The narrator’s term for abstracting characters into their hidden essences; this is part of the function of the geometric figures in the prowls (6-7).","notesPages":[443],"id":"glossary-entry-psychologing","letter":"P"},{"term":"PSYCHOLOGY (ANALYTICAL HUMAN)","definition":"See ANALYTICAL HUMAN PSYCHOLOGY.","notesPages":[443],"id":"glossary-entry-psychology-analytical-human","letter":"P"},{"term":"PUBLIC","definition":"Open to general view or knowledge; everything and nothing was public in the world with little superstructure (80).","notesPages":[443],"id":"glossary-entry-public","letter":"P"},{"term":"PUBLISHED (BOOK NOT YET)","definition":"The Authentic Legends of the Computers... has not actually been published, only exists in galley sheets (36).","notesPages":[443],"id":"glossary-entry-published-book-not-yet","letter":"P"},{"term":"PUBLISHED (SHORTER PIECES)","definition":"The 1987 publisher’s biography reports about 250 published shorter pieces (publisher’s biographical note); this is a contemporary count, not a lifetime total.","notesPages":[443],"id":"glossary-entry-published-shorter-pieces","letter":"P"},{"term":"PULSATING (LIGHT, EGG)","definition":"The beautiful golden and blue light surrounding the Big Egg pulsed rhythmically (154).","notesPages":[443],"id":"glossary-entry-pulsating-light-egg","letter":"P"},{"term":"PUMP (AQUARIUM)","definition":"Device for circulating water; Inneall's artificial heart resembles one for a ten-gallon tank (49).","notesPages":[443],"id":"glossary-entry-pump-aquarium","letter":"P"},{"term":"PUMP (MECHANICAL, EGG)","definition":"A device detected pumping inside the shell of the artificial Big Egg (156).","notesPages":[443],"id":"glossary-entry-pump-mechanical-egg","letter":"P"},{"term":"PUMPS (DIVING)","definition":"Equipment deemed necessary by Lord Randal for deep dives, along with tubes and a pressure chamber (133).","notesPages":[443],"id":"glossary-entry-pumps-diving","letter":"P"},{"term":"PUN (DEEP SLEEP)","definition":"Inneall suggests calling their Ocean Sleep \"our 'Deep Sleep'\" might be an acceptable pun, linking it to the Apes' condition (141-142).","notesPages":[443],"id":"glossary-entry-pun-deep-sleep","letter":"P"},{"term":"PUNCHED CARDS","definition":"See CARDS (PUNCHED).","notesPages":[444],"id":"glossary-entry-punched-cards","letter":"P"},{"term":"PUNISHMENT","definition":"Penalty imposed for an offense; Invisible Alfred condemns ten mockers to death as a punishment (112).","notesPages":[444],"id":"glossary-entry-punishment","letter":"P"},{"term":"PURIFYING (EXPERIMENTS)","definition":"One of the stated goals for crushing extreme talents emerging from experiments, alongside best utilization (82).","notesPages":[444],"id":"glossary-entry-purifying-experiments","letter":"P"},{"term":"PURPLE","definition":"Color; used poetically (\"'Art thou a man of purple cheer?'\") (35).","notesPages":[444],"id":"glossary-entry-purple","letter":"P"},{"term":"PURPLE (LAVENDER-PURPLE TRIANGLE)","definition":"See LAVENDER- PURPLE TRIANGLE.","notesPages":[444],"id":"glossary-entry-purple-lavender-purple-triangle","letter":"P"},{"term":"PYTHON","definition":"Species of large snake; Lutin is a young female python (55, 62, 71, 85, 101, 134).","notesPages":[444],"id":"glossary-entry-python","letter":"P"},{"term":"PYTHON-GUN","definition":"Specialized weapon required to kill a prophesying Python like Lutin; sought by a Dolophonos after being frustrated by her predictions (87); obtained by Iris Lynn-Randal (89) but thrown down unused (90).","notesPages":[444],"id":"glossary-entry-python-gun","letter":"P"},{"term":"PYTHON-SKIN SHOES","definition":"Footwear a Dolophonos muses about having made from the hide of a living young pythoness (86).","notesPages":[444],"id":"glossary-entry-python-skin-shoes","letter":"P"},{"term":"PYTHON-SNAKE (LUTIN)","definition":"Descriptive term used for Lutin when she refutes the Dolophonos's assumption about his gloves (86).","notesPages":[444],"id":"glossary-entry-python-snake-lutin","letter":"P"},{"term":"PYTHONESS","definition":"Female python, emphasizing prophetic abilities; title applied to Lutin (62, 65, 71, 73, 74, 86, 101, 107, 111, 127, 134, 141, 143, 145, 148, 154).","notesPages":[444],"id":"glossary-entry-pythoness","letter":"P"},{"term":"QUARTZ-GLASS","definition":"Material used by the Axel's Apes to make the gas- light fixtures illuminating Ape Alley (45).","notesPages":[444],"id":"glossary-entry-quartz-glass","letter":"Q"},{"term":"QUEERNESS (CAUSED BY FOGS)","definition":"The strange, perhaps unsettling, atmosphere created by the persistent fogs (from underground gas burning and the nearby salty ocean) in Ape Alley (46).","notesPages":[445],"id":"glossary-entry-queerness-caused-by-fogs","letter":"Q"},{"term":"Quern the Fifth, Quentillius","definition":"Pirate seaman aboard the Annabella Saint Ledger; his name was contrived and given to him by Henryetta (original name Jasper Jones) (98). Gives Dolophonoi knives to Randal, Carcajou, and Schimp (100). In charge of loading cargo (101). Kills a Dolophonos to obtain a knife for Henryetta but is mortally wounded in the exchange (134, 139). Dies confirming Henryetta is asleep (140).","notesPages":[445],"id":"glossary-entry-quern-the-fifth-quentillius","letter":"Q"},{"term":"QUESTION 48 (BALTIMORE CATECHISM)","definition":"The specific catechism question (\"'What is Man!'\") whose answer defines Man as composed of body and soul, made in God's image (35).","notesPages":[445],"id":"glossary-entry-question-48-baltimore-catechism","letter":"Q"},{"term":"QUESTIONS (UNLUCKY)","definition":"Inquiries regarding the true nature of the Dolophonoi/Assassins (whether leucotomized humans, irascible computers, or aberrant animals); asking such questions is considered unlucky, as superstition holds that those who ask have already been targeted for elimination (82).","notesPages":[445],"id":"glossary-entry-questions-unlucky","letter":"Q"},{"term":"Quincey, Thomas De","definition":"English essayist (1785-1859). The passage about summer’s departure and mists forming cathedral aisles comes from The English Mail-Coach, “Dream-Fugue,” section II. The novel misattributes it to Confessions of an English Opium-Eater (132).","notesPages":[445],"id":"glossary-entry-quincey-thomas-de","letter":"Q"},{"term":"QUINTESSENCE (OF ARMAMENT)","definition":"The ultimate, most concentrated form of effective weaponry and attack, defined by Arpad Arutinov as \"'One Man, One Knife'\" (79).","notesPages":[445],"id":"glossary-entry-quintessence-of-armament","letter":"Q"},{"term":"QUIPS (FINAL-QUIPS-BEFORE-DEATH)","definition":"Witty remarks made just before execution; Hieronymous Zchold states he has always hated this literary form (Final-Quips-Before-Death) and offers none (158).","notesPages":[445],"id":"glossary-entry-quips-final-quips-before-death","letter":"Q"},{"term":"QUIT-CLAIM DEED/RELEASE","definition":"Legal document transferring interest in property; Satrap gave Inneall the Annabella Saint Ledger by quit- claim deed (116); releases signed by persons facing execution specify bodies will not be given to dogs (but don't mention cats) (158).","notesPages":[445],"id":"glossary-entry-quit-claim-deed-release","letter":"Q"},{"term":"RACHEL","definition":"Biblical figure (wife of Jacob); symbol of maternal grief (\"'Rachel weeping for her children, refusing to be comforted because they were no more'\"), invoked regarding the less than half-million conspicuous cases of mourning mothers among the billions affected by the Kangaroo's \"removals.\" Such Rachels were eventually sent after their children (81).","notesPages":[446],"id":"glossary-entry-rachel","letter":"R"},{"term":"RADIANT INTELLIGENCE","definition":"A state of extremely high intellectual capability that must be passed through by candidates before they can assume the \"post-intellectual state\" required to hold the office of Imperial Head of the Kangaroo (83).","notesPages":[446],"id":"glossary-entry-radiant-intelligence","letter":"R"},{"term":"RAIDERS","definition":"The human group that took five hundred Axel’s Apes and the newborn Axel from Second Eden. The Apes went willingly on the reigning sleepy one’s instruction, even repairing their own fetters (19). Alpha followed as far as Arba Mench (21).","notesPages":[446],"id":"glossary-entry-raiders","letter":"R"},{"term":"RAIDING MEN","definition":"Term used to describe the human group capturing the Axel's Apes (19, 20).","notesPages":[446],"id":"glossary-entry-raiding-men","letter":"R"},{"term":"RAIN SHOWER","definition":"Water falling on the top side of the transparent sky- cover above The Three's habitat; occurred immediately after Axel shot his message (\"'give us a sign'\") onto the cover, but did not wash the mud marks away (4).","notesPages":[446],"id":"glossary-entry-rain-shower","letter":"R"},{"term":"RAMAH","definition":"Biblical location associated with Rachel's weeping (\"'a voice was heard in Ramah...'\") (81).","notesPages":[446],"id":"glossary-entry-ramah","letter":"R"},{"term":"RANCH HOUSES","definition":"Type of spacious dwelling; Persimmon Manor was the ultimate example, built when ranch houses were \"really spread out\" (116).","notesPages":[446],"id":"glossary-entry-ranch-houses","letter":"R"},{"term":"RANDAL EXPERIMENT (LYNN-)","definition":"See LYNN-RANDAL EXPERIMENT.","notesPages":[446],"id":"glossary-entry-randal-experiment-lynn","letter":"R"},{"term":"RANDAL HOUSE (LYNN-)","definition":"See LYNN-RANDAL HOUSE.","notesPages":[446],"id":"glossary-entry-randal-house-lynn","letter":"R"},{"term":"RANDAL, IRIS LYNN-","definition":"See IRIS LYNN-RANDAL.","notesPages":[446],"id":"glossary-entry-randal-iris-lynn","letter":"R"},{"term":"RANDAL, LORD","definition":"See LORD RANDAL.","notesPages":[446],"id":"glossary-entry-randal-lord","letter":"R"},{"term":"RANDALS (LYNN-)","definition":"See LYNN-RANDALS.","notesPages":[446],"id":"glossary-entry-randals-lynn","letter":"R"},{"term":"RATIONALE OF LIFE","definition":"A reasoned principle or basis for existence; Inneall wonders if they might at least have this, since a Theology of Life is forbidden in the Floating World. Lutin suggests the most they can hope for is a Mystique of Life (141).","notesPages":[447],"id":"glossary-entry-rationale-of-life","letter":"R"},{"term":"RATIONS (SHIP'S)","definition":"Food supplies provided to a crew; on Mondays, Wednesdays, and Fridays, the pirates on the Annabella Saint Ledger receive no rations, forced instead by Inneall's directive to live on the fish they catch themselves (99).","notesPages":[447],"id":"glossary-entry-rations-ships","letter":"R"},{"term":"RAVING MAD STATE (GREGOR)","definition":"The condition of extreme insanity Gregor McGregor enters after shooting Riesin and Gajah; in this state, he runs into the wastelands and hangs himself (91).","notesPages":[447],"id":"glossary-entry-raving-mad-state-gregor","letter":"R"},{"term":"RAW (FILCHMAN'S DAUGHTER)","definition":"Uncooked state; Dubu claims eating the fish 'Filchman's Daughter' raw provides sudden insights (75).","notesPages":[447],"id":"glossary-entry-raw-filchmans-daughter","letter":"R"},{"term":"RAYS (ACTINIC)","definition":"Short-wavelength, chemically active light rays; Schimp speculates these might be the cause of the glow around Persimmon Manor (153).","notesPages":[447],"id":"glossary-entry-rays-actinic","letter":"R"},{"term":"RAYS (FISH)","definition":"Group of cartilaginous fish related to sharks; noted as inhabitants of the Deep (139).","notesPages":[447],"id":"glossary-entry-rays-fish","letter":"R"},{"term":"RAYS (SPINNY-)","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[447],"id":"glossary-entry-rays-spinny","letter":"R"},{"term":"READING","definition":"The act of interpreting written text according to regular rules; The Three were taught this after initially misinterpreting printing through guesswork or whimsey (7); also refers to Axel Grindstone's encyclopedic reading (12) and the type of novels Dubu reads (124); also the activity of interpreting signs (palm reading, skull- bump reading) performed by Lutin (86).","notesPages":[447],"id":"glossary-entry-reading","letter":"R"},{"term":"REAL BOOKS","definition":"Traditional books from the older, pre-postliterate age, contrasted with the multi-track 'prowls' of the current era; discovered and read by The Three (9).","notesPages":[447],"id":"glossary-entry-real-books","letter":"R"},{"term":"REAL PEOPLE","definition":"Term for the non-ethnic human population that \"had disappeared from us\" after the world became entirely ethnic (6, 11).","notesPages":[447],"id":"glossary-entry-real-people","letter":"R"},{"term":"REAL WORLD","definition":"The true, substantial reality; Inneall questions whether the world we see or the prosaic Floating World is the real world (141).","notesPages":[448],"id":"glossary-entry-real-world","letter":"R"},{"term":"REASON","definition":"Logical thinking or sanity; the interviewer questions why intelligent Computers adopt astrology (29); “Sweet reason” preached by the unnamed AMH theorist but overridden by human emotional quirks (39); Inneall sometimes lets emotions override reason (51).","notesPages":[448],"id":"glossary-entry-reason","letter":"R"},{"term":"REASON (SWEET)","definition":"See SWEET REASON.","notesPages":[448],"id":"glossary-entry-reason-sweet","letter":"R"},{"term":"REASONED FUTURE (STRUCTO LANE)","definition":"The anticipated trajectory of Structo Lane, described poetically as \"'scienced, reasoned... mechanic-like... plotted... formal, stylized, sane'\" (67).","notesPages":[448],"id":"glossary-entry-reasoned-future-structo-lane","letter":"R"},{"term":"RECALL","definition":"Mental faculty of remembering; possessed to a high degree by AMHs (26).","notesPages":[448],"id":"glossary-entry-recall","letter":"R"},{"term":"RECKONER (STEPPED)","definition":"See STEPPED RECKONER.","notesPages":[448],"id":"glossary-entry-reckoner-stepped","letter":"R"},{"term":"RECOLLECT (SLEEPY ONE)","definition":"The reigning 'sleepy one' among the Unfallen People has the function to recollect and remind the people how things were in the beginning (19).","notesPages":[448],"id":"glossary-entry-recollect-sleepy-one","letter":"R"},{"term":"RECORDS","definition":"Recorded information; Popugai listened to records constantly to learn languages (64); AMHs have vast storage capacity for records (implied) (26).","notesPages":[448],"id":"glossary-entry-records","letter":"R"},{"term":"RED DITCHES (ARCHANGEL EYEBALL)","definition":"Ansel Grindstone's imaginative description of the bloodshot marks within a hypothetical Archangel's half-mile wide eyeball (17).","notesPages":[448],"id":"glossary-entry-red-ditches-archangel-eyeball","letter":"R"},{"term":"RED INDIAN TRIBES","definition":"The novel’s term for Native American peoples in its fanciful account of lacrosse’s introduction by Saint Brandon (65). Historically lacrosse originated among Indigenous North American peoples; see Introduction (of Lacrosse).","notesPages":[448],"id":"glossary-entry-red-indian-tribes","letter":"R"},{"term":"RED LAIRD","definition":"Figure depicted on the Saint Ledger coat-of-arms aboard the Annabella Saint Ledger (49); Ruddy Lord Randal has the \"Red Laird look\" (63).","notesPages":[448],"id":"glossary-entry-red-laird","letter":"R"},{"term":"RED RAIDER","definition":"Fictional warriors from Mars; Ruddy Lord Randal looks quite a bit like one, and possesses some of their fictional element even after they were discovered to be real (63).","notesPages":[448],"id":"glossary-entry-red-raider","letter":"R"},{"term":"RED RAIDERS OF MARS","definition":"See RED RAIDER.","notesPages":[449],"id":"glossary-entry-red-raiders-of-mars","letter":"R"},{"term":"RED SEA","definition":"Body of water separating Africa and Arabia; once a lake or series of lakes crossed by land bridges (like the Ape Bridge) (12); later became a sea, but the Ape Bridge sometimes reappeared, possibly used by Moses (13).","notesPages":[449],"id":"glossary-entry-red-sea","letter":"R"},{"term":"RED-SNAPPERS","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[449],"id":"glossary-entry-red-snappers","letter":"R"},{"term":"REEFS OF EARTH (THE) (NOVEL)","definition":"Novel written by R.A. Lafferty (publisher’s biographical note); refers to The Reefs of Earth.","notesPages":[449],"id":"glossary-entry-reefs-of-earth-the-novel","letter":"R"},{"term":"REFUGE (LAST REFUGE OF CRANKY BACHELORS)","definition":"See LAST REFUGE OF CRANKY BACHELORS.","notesPages":[449],"id":"glossary-entry-refuge-last-refuge-of-cranky-bachelors","letter":"R"},{"term":"REIGN","definition":"Rule or prevail; Honor had reigned as a leading cultural indicator (117).","notesPages":[449],"id":"glossary-entry-reign","letter":"R"},{"term":"REIGNING SLEEPY ONE","definition":"The particular Unfallen son who is awake and serving as the conscience and rememberer for the current millennium (18, 19). The ninth such figure speaks to the Unfallens regarding the capture of the Apes (19).","notesPages":[449],"id":"glossary-entry-reigning-sleepy-one","letter":"R"},{"term":"REJECTION (AXEL'S)","definition":"Axel Albert Grindstone's horrified and utter rejection of his \"one idea\" upon seeing the faces of the Unfallen People, immediately preceding his death (18).","notesPages":[449],"id":"glossary-entry-rejection-axels","letter":"R"},{"term":"RELAYS (HUNCH OVER-RIDE)","definition":"Hypothetical mechanisms installed by less intelligent computers imitating humans, allowing mere vagaries to override reason (39).","notesPages":[449],"id":"glossary-entry-relays-hunch-over-ride","letter":"R"},{"term":"RELEASES (QUIT-CLAIM)","definition":"Legal documents signed by persons facing execution; specify that bodies will not be given to dogs, but fail to mention cats (158).","notesPages":[449],"id":"glossary-entry-releases-quit-claim","letter":"R"},{"term":"RELENTLESSNESS (AMH IMPETUS)","definition":"The unstoppable drive inherent in computer operations, stemming from inertial motion rather than conscious will; Inneall's Ocean is an instance of this (27).","notesPages":[449],"id":"glossary-entry-relentlessness-amh-impetus","letter":"R"},{"term":"RELIGION","definition":"System of faith and worship; Ananthropoi Computers identify themselves by religion (firm Ananthropoi) (38).","notesPages":[449],"id":"glossary-entry-religion","letter":"R"},{"term":"RELIGION (OLD)","definition":"See OLD RELIGION.","notesPages":[449],"id":"glossary-entry-religion-old","letter":"R"},{"term":"REMORAS","definition":"Species of fish (suckerfish) flocking to Inneall's Ocean (138).","notesPages":[450],"id":"glossary-entry-remoras","letter":"R"},{"term":"REMOVAL (VIOLENT)","definition":"Method by which positions within the Kangaroo organization can be changed (80).","notesPages":[450],"id":"glossary-entry-removal-violent","letter":"R"},{"term":"REMOVALS (THE)","definition":"Euphemism for the Kangaroo's elimination of the bottom eighty-seven percent of the world's population, deemed logical by some as this group caused ninety-seven percent of the trouble (81).","notesPages":[450],"id":"glossary-entry-removals-the","letter":"R"},{"term":"RENT (IN PERFECT CREATURE)","definition":"Small flaw or rip accidentally made by the lathe in the seventh creature (Mankind) created by the Theos; though initially tiny, it grows larger over time (36-37).","notesPages":[450],"id":"glossary-entry-rent-in-perfect-creature","letter":"R"},{"term":"REPENT","definition":"Feel remorse and turn from wrongdoing; commanded by Invisible Alfred to the multitudes on the shore (109, 110); the ten condemned persons lack the wisdom to repent despite knowing their imminent deaths (112).","notesPages":[450],"id":"glossary-entry-repent","letter":"R"},{"term":"REPERTORY (VOICE)","definition":"Range or collection of voices possessed by Inneall; she claims a wonderful variety (52).","notesPages":[450],"id":"glossary-entry-repertory-voice","letter":"R"},{"term":"REPORTER","definition":"Journalist; Roy Latta interviews the Royal Kids (113); another asks Hieronymous Zchold for quotable quips before his execution (158).","notesPages":[450],"id":"glossary-entry-reporter","letter":"R"},{"term":"REPORTERS","definition":"Journalists who came out to investigate Inneall's nascent Ocean but were baffled how to interview strip pits or bodies of water (24).","notesPages":[450],"id":"glossary-entry-reporters","letter":"R"},{"term":"REPRESENTATION (HIGH-RELIEF)","definition":"Sculpted likeness; the stone cenotaph lids bear amazingly true high-relief representations of Axel and Lord Randal (148).","notesPages":[450],"id":"glossary-entry-representation-high-relief","letter":"R"},{"term":"REPUBLIC (FIRST COMPUTER REPUBLIC OF THE MIND)","definition":"See FIRST COMPUTER REPUBLIC OF THE MIND.","notesPages":[450],"id":"glossary-entry-republic-first-computer-republic-of-the-mind","letter":"R"},{"term":"REPUGNANCE (FOR LUTIN)","definition":"Feeling of disgust or aversion felt by some (though not the Eleven) towards Lutin the pythoness, despite her fine qualities (62).","notesPages":[450],"id":"glossary-entry-repugnance-for-lutin","letter":"R"},{"term":"RESEARCHED (INNEALL)","definition":"Inneall has extensively researched: consciousness (23), extradigitalism and pirates (25), old songs like 'Old Dogs and Children and Watermelon Wine' (121), the Tarzan character (123), ancient circuses (85), and countless other subjects via her 'connections' (121); she has not researched the fundamental nature of pythons or basic reproduction (153, 156).","notesPages":[451],"id":"glossary-entry-researched-inneall","letter":"R"},{"term":"RESEARCHES (COMPUTER)","definition":"Investigations conducted by computers (\"computers of our own\") indicating Mankind was almost perfect at origin but had a flaw that grew (37).","notesPages":[451],"id":"glossary-entry-researches-computer","letter":"R"},{"term":"RESEARCHES (DONKEY-ASS)","definition":"Investigations by AMH Computers uncovering evidence that the first donkeys were mechanical attempts by human magician-artisans (31).","notesPages":[451],"id":"glossary-entry-researches-donkey-ass","letter":"R"},{"term":"RESEARCHES (INNEALL'S)","definition":"Investigations conducted by Inneall; inform her belief that the enchanted cannon is effective (95); reveal Invisible Alfred lives in one of the paint drums (98).","notesPages":[451],"id":"glossary-entry-researches-innealls","letter":"R"},{"term":"RESIDUE (INVISIBLE PAINT)","definition":"The trace amount remaining in an emptied drum; from this, Invisible Alfred drew the power of near- invisibility (110).","notesPages":[451],"id":"glossary-entry-residue-invisible-paint","letter":"R"},{"term":"RESILIENCY (FLOATING WORLD)","definition":"Capacity to recover; the Floating World described as a giant boat or ark of remarkable resiliency (82).","notesPages":[451],"id":"glossary-entry-resiliency-floating-world","letter":"R"},{"term":"RESURRECTION OF HONOR","definition":"The revival movement promoting the ideal of Honor in the Floating World, accompanied by somewhat extravagant rituals (118).","notesPages":[451],"id":"glossary-entry-resurrection-of-honor","letter":"R"},{"term":"RETENTION","definition":"Faculty of retaining information; possessed to a high degree by AMHs (26).","notesPages":[451],"id":"glossary-entry-retention","letter":"R"},{"term":"REVERSE EUPHEMISM ('APE')","definition":"Axel Grindstone’s mistaken interpretation of the name “Ape”: he assumes it substitutes for something too holy to name (12-13), before discovering the Unfallen People’s actual appearance (17).","notesPages":[451],"id":"glossary-entry-reverse-euphemism-ape","letter":"R"},{"term":"REVERSE WINK (ALFRED'S)","definition":"Invisible Alfred's peculiar gesture of opening one eye, used when revealing himself (133).","notesPages":[451],"id":"glossary-entry-reverse-wink-alfreds","letter":"R"},{"term":"REVISIONS (BLOODSHED)","definition":"Future editorial changes (two or three away) needed before the narrative can maintain that the solution (implied global stabilization via Kangaroo) is \"acceptable,\" suggesting the current version still depicts world-wide bloodshed (79).","notesPages":[451,452],"id":"glossary-entry-revisions-bloodshed","letter":"R"},{"term":"RHINOID LOOK","definition":"Facial appearance resembling a rhinoceros; possessed by certain \"clear humans\" who are not apes, similar to the gargoyle-titan look (44).","notesPages":[452],"id":"glossary-entry-rhinoid-look","letter":"R"},{"term":"RIDDLE (THE GLORY, JEST, AND RIDDLE OF THE WORLD)","definition":"Phrase from Pope's Essay on Man describing the paradoxical nature of humanity (34).","notesPages":[452],"id":"glossary-entry-riddle-the-glory-jest-and-riddle-of-the-world","letter":"R"},{"term":"RIDING HORSES","definition":"Mounts used by sportsmen who came to Heart's Desire Cove; offered the specialty 'Hay a la Riesin' (58).","notesPages":[452],"id":"glossary-entry-riding-horses","letter":"R"},{"term":"RIFLES","definition":"Firearms included in the armament of the Annabella Saint Ledger, both standard and automatic (101).","notesPages":[452],"id":"glossary-entry-rifles","letter":"R"},{"term":"RIGAMAROLE","definition":"Lengthy, complicated, and often nonsensical procedure or speech; Invisible Alfred launches into his after successfully summoning a whale (110).","notesPages":[452],"id":"glossary-entry-rigamarole","letter":"R"},{"term":"RIGGING (INVISIBLE)","definition":"The ropes and sails of the invisible Annabella Saint Ledger; Inneall imagines Lanternjaw, the last living crewman, calling from the invisible rigging while the other crewmen are skeletons (120-121).","notesPages":[452],"id":"glossary-entry-rigging-invisible","letter":"R"},{"term":"RIGHT ACORN","definition":"The specific, unique acorn containing the answers to all hard questions; Dubu believes clues point to it but are overlooked (74).","notesPages":[452],"id":"glossary-entry-right-acorn","letter":"R"},{"term":"RIGHT NAME (EXPERIMENTAL ENTITIES)","definition":"George Lynn-Randal asserts that \"experimental entities\" is the correct term for The Three, not \"children\" (7).","notesPages":[452],"id":"glossary-entry-right-name-experimental-entities","letter":"R"},{"term":"RIME","definition":"Correspondence of sound between words or endings of words; like melody, unrecognizable to the \"new people\" of the post- postliterate age (8).","notesPages":[452],"id":"glossary-entry-rime","letter":"R"},{"term":"RING-MASTER (RANDAL)","definition":"Role assumed by Ruddy Lord Randal during the circus performance, wearing top hat and frock coat (86).","notesPages":[452],"id":"glossary-entry-ring-master-randal","letter":"R"},{"term":"RIO DE JANEIRO","definition":"Brazilian city mentioned as a possible location for an afternoon coffee break under the free-travel conditions of the Floating World (79).","notesPages":[452],"id":"glossary-entry-rio-de-janeiro","letter":"R"},{"term":"RIO SIDEWALKS","definition":"Multi-colored walkways installed along the stony shore of Heart's Desire Cove (58).","notesPages":[453],"id":"glossary-entry-rio-sidewalks","letter":"R"},{"term":"RIP (IN MAN CREATURE)","definition":"The flaw or imperfection present in Mankind from origin, which has grown larger over time (37).","notesPages":[453],"id":"glossary-entry-rip-in-man-creature","letter":"R"},{"term":"RIP (IN PERFECT CREATURE)","definition":"The small rent made accidentally by the lathe in the seventh \"Not-quite-perfect\" creature (Mankind) (36).","notesPages":[453],"id":"glossary-entry-rip-in-perfect-creature","letter":"R"},{"term":"RISEN ANIMAL","definition":"Man described potentially as such, if considered an animal (contrasted with fallen angel) (35).","notesPages":[453],"id":"glossary-entry-risen-animal","letter":"R"},{"term":"RISING (HELIACAL; printed 'helical')","definition":"The first seasonal appearance of a star above the eastern horizon before sunrise. The Whale Temple-City's alignments could mark Sirius's heliacal rising (137).","notesPages":[453],"id":"glossary-entry-rising-heliacal-printed-helical","letter":"R"},{"term":"RITUAL (HANGING)","definition":"The formalized procedure for executing members of the Natural Nobility by hanging, carried out by friends at cockcrow (118).","notesPages":[453],"id":"glossary-entry-ritual-hanging","letter":"R"},{"term":"RITUAL TWITCHES (DONATUS')","definition":"The three involuntary convulsions made by Donatus O'Reily's body after being hanged (157).","notesPages":[453],"id":"glossary-entry-ritual-twitches-donatus","letter":"R"},{"term":"RITUALS (RESURRECTION OF HONOR)","definition":"Ceremonies accompanying the revival of Honor, described as sometimes a little bit extravagant and overdone (118).","notesPages":[453],"id":"glossary-entry-rituals-resurrection-of-honor","letter":"R"},{"term":"RIVER (ARKANSAS)","definition":"See ARKANSAS RIVER.","notesPages":[453],"id":"glossary-entry-river-arkansas","letter":"R"},{"term":"RIVER (GRAND)","definition":"See GRAND RIVER.","notesPages":[453],"id":"glossary-entry-river-grand","letter":"R"},{"term":"RIVER (VERDIGRIS)","definition":"See VERDIGRIS RIVER.","notesPages":[453],"id":"glossary-entry-river-verdigris","letter":"R"},{"term":"ROAD","definition":"Path or way; Riesin trudges along a road (93); jog in the road enables bi-location (93, 95); roads of town unkempt (92).","notesPages":[453],"id":"glossary-entry-road","letter":"R"},{"term":"ROAD (JOG IN)","definition":"See JOG IN THE ROAD.","notesPages":[453],"id":"glossary-entry-road-jog-in","letter":"R"},{"term":"ROAD-PEOPLE","definition":"Lowly, possibly nomadic individuals; the King and Creator was born to such people in a stable (155).","notesPages":[454],"id":"glossary-entry-road-people","letter":"R"},{"term":"ROAD (ROCKY)","definition":"Path traversed by Axel Grindstone past Gandula (14); road in high foothills leading to Elephant Graveyard (94).","notesPages":[453],"id":"glossary-entry-road-rocky","letter":"R"},{"term":"ROAD (TO PRIME MINISTER)","definition":"Metaphorical path of advancement; the Ethiopian PM received his start on this road through instruction from the Unfallen Ones (15).","notesPages":[454],"id":"glossary-entry-road-to-prime-minister","letter":"R"},{"term":"ROADS","definition":"Routes for travel; swallowed up by Inneall's Ocean (27); broken roads in human- mayor town (92).","notesPages":[454],"id":"glossary-entry-roads","letter":"R"},{"term":"ROARING (DEVIL-FISH)","definition":"Loud cries made by the eleven transformed wolverenes (devil- fish) (103).","notesPages":[454],"id":"glossary-entry-roaring-devil-fish","letter":"R"},{"term":"ROARING (WOLVERENES)","definition":"Loud, menacing sounds made by the eleven wolverenes outside the condominium, shaking Structo Lane (102, 103).","notesPages":[454],"id":"glossary-entry-roaring-wolverenes","letter":"R"},{"term":"ROCK CLIFFS","definition":"Geological formations north of the Ocean Shore where the Dolophonoi made their nests (85).","notesPages":[454],"id":"glossary-entry-rock-cliffs","letter":"R"},{"term":"ROCK (SOLID)","definition":"The final foot of limestone barrier before the Cenaculum, demolished by the last blast (144).","notesPages":[454],"id":"glossary-entry-rock-solid","letter":"R"},{"term":"ROCKS (FISSURED)","definition":"Geological feature in The Three's habitat where experimental hogs fed (3); location of methane fissure in Second Eden cenaculum (45); location of fissure in Ape Caverns roof (68).","notesPages":[454],"id":"glossary-entry-rocks-fissured","letter":"R"},{"term":"RODS (ABACUS)","definition":"Parallel sticks on which counting beads slide in an abacus; the novel describes the earliest abacuses as having nine rods (24), a claim from its comic computer history, not an established fact about all early abacuses.","notesPages":[454],"id":"glossary-entry-rods-abacus","letter":"R"},{"term":"ROLES","definition":"Parts played by actors or individuals; favorite roles adopted by AMHs (26); humans used in minor roles in Structo Lane Dramas (76); pirates playing their roles in the legend (121).","notesPages":[454],"id":"glossary-entry-roles","letter":"R"},{"term":"ROLES (MIMING)","definition":"Specific personas adopted; wearing a donkey head is considered the main miming role by one AMH (32).","notesPages":[454],"id":"glossary-entry-roles-miming","letter":"R"},{"term":"ROMANIES","definition":"Members of the Romany (Gypsy) people; shown in later pictures bringing apes along in chains (14).","notesPages":[454],"id":"glossary-entry-romanies","letter":"R"},{"term":"ROMANY LEGENDS","definition":"See LEGENDS (ROMANY/GYPSY).","notesPages":[454],"id":"glossary-entry-romany-legends","letter":"R"},{"term":"ROMANY PEOPLE","definition":"See GYPSY.","notesPages":[454],"id":"glossary-entry-romany-people","letter":"R"},{"term":"ROMPS","definition":"One of the alternative names ('prowls', 'antics', etc.) for the multi-track media format (6).","notesPages":[455],"id":"glossary-entry-romps","letter":"R"},{"term":"ROOF (LIMESTONE)","definition":"Ceiling of the Ape Caverns, made of limestone, containing a fissure (68).","notesPages":[455],"id":"glossary-entry-roof-limestone","letter":"R"},{"term":"ROOM (BIG CENTRAL)","definition":"Largest room in Persimmon Manor, where the Big Egg appears while Lutin and her midwife are asleep; has a large hole in the floor (160).","notesPages":[455],"id":"glossary-entry-room-big-central","letter":"R"},{"term":"ROOM (HORRIBLE LITTLE)","definition":"A secret, unpleasant room found first in the aft hold of the Annabella Saint Ledger (114) and later within Persimmon Manor (126); contains the Three Fates spinning, measuring, and cutting life threads from straw (114, 126).","notesPages":[455],"id":"glossary-entry-room-horrible-little","letter":"R"},{"term":"ROOM (LUTIN'S)","definition":"The Biggest Central Room in Persimmon Manor, given to Lutin by Satrap for her lying-in (160).","notesPages":[455],"id":"glossary-entry-room-lutins","letter":"R"},{"term":"ROOM (UGLY)","definition":"Location where the three ugly sisters (Fates) sit, with straw on the floor (103).","notesPages":[455],"id":"glossary-entry-room-ugly","letter":"R"},{"term":"ROOM (UPPER, OF SLEEPERS)","definition":"The Cenaculum within Ape Caverns (144).","notesPages":[455],"id":"glossary-entry-room-upper-of-sleepers","letter":"R"},{"term":"ROOMS (CLUBROOM)","definition":"See CLUBROOM.","notesPages":[455],"id":"glossary-entry-rooms-clubroom","letter":"R"},{"term":"ROOT (CORRUPT)","definition":"The flawed origin of the human race resulting from the misuse of free will (35).","notesPages":[455],"id":"glossary-entry-root-corrupt","letter":"R"},{"term":"ROOTS (IN HELL)","definition":"The Dolophonoi-Assassins claim their origins lie in hell, resulting from a damnable mixture (87).","notesPages":[455],"id":"glossary-entry-roots-in-hell","letter":"R"},{"term":"ROOTS (MYTHOLOGICAL)","definition":"The origins of Ambulatory Computers traced back by Livius Secundus to human crypto-memory (70).","notesPages":[455],"id":"glossary-entry-roots-mythological","letter":"R"},{"term":"ROOTS (ROOTS TO CROWN)","definition":"Metaphor describing the extent of humanity's health after the \"pruning\" of its undesirable elements (81).","notesPages":[455],"id":"glossary-entry-roots-roots-to-crown","letter":"R"},{"term":"ROPE (HANGING)","definition":"Used for Donatus O'Reily's execution; the jerky end causes ritual twitches (157).","notesPages":[455],"id":"glossary-entry-rope-hanging","letter":"R"},{"term":"ROPE LADDER","definition":"Means of boarding the invisible Annabella Saint Ledger; its sound dragging in the water is audible (152).","notesPages":[455],"id":"glossary-entry-rope-ladder","letter":"R"},{"term":"ROSY MAN","definition":"Poetic description (\"'A rosy man right plump to see?'\") (35).","notesPages":[456],"id":"glossary-entry-rosy-man","letter":"R"},{"term":"ROTATION MOTIF","definition":"Recurring theme of spinning or revolving; noted as strongly favored by all machines, explaining the constant rotation of the condominium clubroom (74).","notesPages":[456],"id":"glossary-entry-rotation-motif","letter":"R"},{"term":"ROTTEN WOOD","definition":"Decaying timber providing sustenance for experimental hogs in The Three's habitat (3).","notesPages":[456],"id":"glossary-entry-rotten-wood","letter":"R"},{"term":"ROUGHAGE","definition":"Indigestible material aiding passage of food; The Three needed the raw color, noise, movement, and tedium of prowls as mental roughage (9).","notesPages":[456],"id":"glossary-entry-roughage","letter":"R"},{"term":"ROUND DANCING","definition":"Circular group dance; one of the arts abandoned by humans but reinvented by Computers (33).","notesPages":[456],"id":"glossary-entry-round-dancing","letter":"R"},{"term":"ROUTE (ESCAPE)","definition":"Means of avoiding danger; Rose-of-Sharon Montdrago's escape route (reclassification) from Serpent's Egg status is now plugged up (117).","notesPages":[456],"id":"glossary-entry-route-escape","letter":"R"},{"term":"ROYAL HOUSE OF DONEGAL","definition":"Ancient Irish lineage from which Donatus O'Reily claims descent as a Prince of the Blood (Flaith) (157).","notesPages":[456],"id":"glossary-entry-royal-house-of-donegal","letter":"R"},{"term":"ROYAL KIDS","definition":"Affectionate (or euphemistic for 'Serpent's Egg Kids') term for the Nine surviving members of the merged experiments (100, 101, 104, 108, 113, 115, 116, 117, 119, 120, 124, 127, 141, 142, 144, 147, 153, 162).","notesPages":[456],"id":"glossary-entry-royal-kids","letter":"R"},{"term":"ROYAL TITLE (MAN'S)","definition":"'Lord and Master of the World', bestowed upon Mankind at creation (34).","notesPages":[456],"id":"glossary-entry-royal-title-mans","letter":"R"},{"term":"RUBBISH (ENLARGEMENT OF WORLD)","definition":"Invisible Alfred dismisses the idea of the 'Enlargement of the World' as rubbish (112).","notesPages":[456],"id":"glossary-entry-rubbish-enlargement-of-world","letter":"R"},{"term":"RUCKUS","definition":"Commotion or disturbance; Schimp bought his bait shop while the ruckus (presumably End of Summer chaos) was ongoing (161).","notesPages":[456],"id":"glossary-entry-ruckus","letter":"R"},{"term":"RUDDY LORD RANDAL","definition":"See LORD RANDAL. (Used frequently to distinguish him).","notesPages":[456],"id":"glossary-entry-ruddy-lord-randal","letter":"R"},{"term":"RUE","definition":"Regret or sorrow; felt by Donatus O'Reily while awaiting hanging (157).","notesPages":[457],"id":"glossary-entry-rue","letter":"R"},{"term":"RUF-RUF VOICE (DUBU)","definition":"The characteristic vocal quality used by Dubu the bear for human talk (63).","notesPages":[457],"id":"glossary-entry-ruf-ruf-voice-dubu","letter":"R"},{"term":"RUN-AMOKS (MULTIPLE)","definition":"See MULTIPLE RUN-AMOKS.","notesPages":[457],"id":"glossary-entry-run-amoks-multiple","letter":"R"},{"term":"RUNABOUT (ELECTRIC)","definition":"Small motorized vehicle; provided for Lutin by her patron Felix for use in lacrosse (62); Marino also uses one (65).","notesPages":[457],"id":"glossary-entry-runabout-electric","letter":"R"},{"term":"RUNIC ALPHABET","definition":"Ancient script; claimed by the novel’s Olaf Hensen quotation to have been first written by Whales on Ocean Stones and later learned by Scandinavians (131).","notesPages":[457],"id":"glossary-entry-runic-alphabet","letter":"R"},{"term":"RUNIC WRITING","definition":"Script using runic characters; said in the novel’s Olaf Hensen quotation to have been learned by Scandinavians from the Whales (131).","notesPages":[457],"id":"glossary-entry-runic-writing","letter":"R"},{"term":"RUTTING CRIES (GIRAFFES)","definition":"Mating calls of giraffes, included as part of the background 'good noise' in media 'prowls' (6).","notesPages":[457],"id":"glossary-entry-rutting-cries-giraffes","letter":"R"},{"term":"Saint Ledger, Satrap","definition":"A human of immense wealth (\"Midas Class\") possessing an intricate mind; ocean diver by hobby, hydraulic engineer by profession (47, 132); maintains close friendships with both Ambulatory Computers and Axel's Apes (47); has a permanent suite in the New Eden Hotel connected to Inneall's Ocean via the 'Allez- Oop' locks (47); owns the yacht Annabella Saint Ledger (named for his deceased daughter), which he deeds to Inneall under duress (47-49); acts as surrogate grandfather to Inneall (69, 71) ; facilitates the merged Experiments, builds the Heart's Desire Cove entertainment center (57), and provides equipment (58, 85, 95); possesses deep-diving ability via inducing Oceanic Metastasis (133-135); traffics limestone to the Whales building on the Ocean Bottom (106); owns Tom Dooley's Island and Persimmon Manor (100, 115, 124).","notesPages":[457],"id":"glossary-entry-saint-ledger-satrap","letter":"S"},{"term":"Saleh, Shadrack","definition":"One of the 'parents'/sponsors of the Dorantes-Saleh Experiment (84); hunts Dolophonoi with Iris and Gregor (84); particularly worried about his 'daughter' Lutin (84-85); doubly arms himself with the Angel-Gun and Wolverene-were-Gun but trembles and throws them down in weakness (90); wanders wasteland broken in mind and spirit (91).","notesPages":[458],"id":"glossary-entry-saleh-shadrack","letter":"S"},{"term":"SARDI'S","definition":"Restaurant where the Eleven have breakfast after their night in Structo Lane (76).","notesPages":[481],"id":"glossary-entry-sardis","letter":"S"},{"term":"SATIRE","definition":"Literary mode employing irony or ridicule; unrecognizable to the \"new people\" of the post-postliterate age (8).","notesPages":[458],"id":"glossary-entry-satire","letter":"S"},{"term":"SCALE (I.Q.)","definition":"Lord Randal bred to have intelligence \"clear off the scale\" (5).","notesPages":[458],"id":"glossary-entry-scale-i-q","letter":"S"},{"term":"SCALE (INTELLIGENCE)","definition":"Hyper-Intelligence Scanners detect intelligences \"clear off the scale\" in many species (55); Carcajou's intelligence is \"clear off the secret-scale,\" which goes much further (64).","notesPages":[458],"id":"glossary-entry-scale-intelligence","letter":"S"},{"term":"SCANDAL-MONGER'S SICKNESS","definition":"Affliction attributed by Lutin to Henryetta, implying a penchant for spreading gossip (73).","notesPages":[458],"id":"glossary-entry-scandal-mongers-sickness","letter":"S"},{"term":"SCANNERS","definition":"Devices used to detect and measure abilities or properties; chirped \"'Mega, Mega, Mega!'\" for The Three (5); basic scanners at Second Eden indicated exceptional ability in all Apes (19); routine scanners went \"crazy\" over the unborn Axel (20); Hyper- Intelligence Scanners survey species globally (55); used by the Kangaroo to appraise the population and identify threats (82, 84); neighborhood scanners identified Carcajou as \"Undocumented Mega Human\" (88); Satrap sets up a double scanner in the condominium (93).","notesPages":[458],"id":"glossary-entry-scanners","letter":"S"},{"term":"SCARED (COMPUTERS OVERLY-POLITE)","definition":"Overpoliteness is a human failing; computers are hardly ever overly-polite (implicitly, not scared into it) (39).","notesPages":[458],"id":"glossary-entry-scared-computers-overly-polite","letter":"S"},{"term":"SCENE OF MAN","definition":"Quoted phrase (\"'Expatiate free o'er all this scene of man;'\") from Pope's Essay on Man, referring to the panorama of human existence (34).","notesPages":[458],"id":"glossary-entry-scene-of-man","letter":"S"},{"term":"SCENTED (BY ASSASSINS)","definition":"The three hunters (Iris, Shadrack, Gregor) realize they have been detected by the approaching Dolophonoi through smell (89).","notesPages":[458],"id":"glossary-entry-scented-by-assassins","letter":"S"},{"term":"SCHEMATICS (HUMAN MINDS)","definition":"Mobile representations of human minds and bodies, built for study, related to the development of AMHs (26).","notesPages":[459],"id":"glossary-entry-schematics-human-minds","letter":"S"},{"term":"SCHIMP","definition":"The young male chimpanzee of the Dorantes-Saleh Experiment (55); highly erudite, holding doctorate and masters degrees by age eight, regularly wears academic cap and gown (63); plays lacrosse with vigor (65); accompanies Randal and Carcajou with Dolophonoi knives (100); suggests living on Ocean Fish and Sea- Turtles (119); places Axel and Randal in cenotaphs (148); survives final events and buys 'Happy Charley's Bait Shop' (161).","notesPages":[459],"id":"glossary-entry-schimp","letter":"S"},{"term":"SCHOOL-CHILDREN (LOCAL)","definition":"Came to the Unfallen Ones for help with lessons, valued equally with great scholars (15).","notesPages":[459],"id":"glossary-entry-school-children-local","letter":"S"},{"term":"SCIENCE","definition":"Systematic knowledge; astrology dismissed as a pseudo- science (111); Science reported Inneall's Ocean as more benevolent than malevolent before midnight (161).","notesPages":[459],"id":"glossary-entry-science","letter":"S"},{"term":"SCIENCED FUTURE (STRUCTO LANE)","definition":"The anticipated development of Structo Lane, poetically described as \"'scienced, reasoned... mechanic-like... plotted'\" (67).","notesPages":[459],"id":"glossary-entry-scienced-future-structo-lane","letter":"S"},{"term":"SCIENTISTS","definition":"Experts in science; rate Inneall's Ocean as unstable (143); say they have never had a dead Axel’s Ape to study (161).","notesPages":[459],"id":"glossary-entry-scientists","letter":"S"},{"term":"SCISSORS (ATROPOS')","definition":"Instrument used by the Fate Atropos to cut the measured threads of life (103); Inneall reinforces the threads with wotto-metal and predicts that the scissors will break if Atropos tries to cut them (127); Dubu suspects Atropos has other pairs (127).","notesPages":[459],"id":"glossary-entry-scissors-atropos","letter":"S"},{"term":"SCOPE","definition":"Range or extent; AMH intelligence has greater scope than human (26); Alfred’s vocal tricks are limited in number (110); scanner-scope (93).","notesPages":[459],"id":"glossary-entry-scope","letter":"S"},{"term":"SCORPIO","definition":"Eighth astrological sign; the corresponding astronomical constellation is Scorpius. Invisible Alfred claims that its conventional image conceals Vipera the Viper (111).","notesPages":[459],"id":"glossary-entry-scorpio","letter":"S"},{"term":"SCRAMBLERS (BUG-)","definition":"See BUG-SCRAMBLERS.","notesPages":[459],"id":"glossary-entry-scramblers-bug","letter":"S"},{"term":"SCREAMING (ALLIGATORS)","definition":"Sound included in the background 'good noise' of 'prowls' (6).","notesPages":[460],"id":"glossary-entry-screaming-alligators","letter":"S"},{"term":"SCREENED GATES (APES' CAVERNS)","definition":"Concealed entrances to Ape Caverns, found closed and guarded when the Eleven arrived (68).","notesPages":[459],"id":"glossary-entry-screened-gates-apes-caverns","letter":"S"},{"term":"SCRIMSHAW CARVING","definition":"Art of engraving on bone or ivory (especially walrus ivory); abandoned by humans, reinvented by Computers (33).","notesPages":[460],"id":"glossary-entry-scrimshaw-carving","letter":"S"},{"term":"SCRIPTURES","definition":"Sacred writings; Satrap runs through scriptures and pseudo-scriptures seeking applications to the sleeping Apes, finding only doubtful ones (70).","notesPages":[460],"id":"glossary-entry-scriptures","letter":"S"},{"term":"SEA ARMAMENTS","definition":"Naval weaponry; predicted by Arpad Arutinov to be modernized or junked (79).","notesPages":[460],"id":"glossary-entry-sea-armaments","letter":"S"},{"term":"SEA-BASSES","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[460],"id":"glossary-entry-sea-basses","letter":"S"},{"term":"SEA (BOTTOM OF THE)","definition":"Location of a mer-ma-id (131); setting of Lutin's dream castle (136); destination of the sinking Tom Dooley's Island (159).","notesPages":[460],"id":"glossary-entry-sea-bottom-of-the","letter":"S"},{"term":"SEA-CAT","definition":"More pleasant name for the pseudo-fish also known as the Nightmare Monster (139).","notesPages":[461],"id":"glossary-entry-sea-cat","letter":"S"},{"term":"SEA CHANGE (MARBLE)","definition":"The novel’s fantastic transformation of limestone into variegated marble, described as conferring a “Patent of Nobility” on the stone (136).","notesPages":[460],"id":"glossary-entry-sea-change-marble","letter":"S"},{"term":"SEA FOOD","definition":"See SEAFOOD.","notesPages":[460],"id":"glossary-entry-sea-food","letter":"S"},{"term":"SEA FOOD CASTLE (ELMER SPRINGER'S)","definition":"See SEAFOOD CASTLE (ELMER SPRINGER'S).","notesPages":[460],"id":"glossary-entry-sea-food-castle-elmer-springers","letter":"S"},{"term":"SEA FOOD CHARLEY'S","definition":"See SEAFOOD CHARLEY'S.","notesPages":[460],"id":"glossary-entry-sea-food-charleys","letter":"S"},{"term":"SEA FOOD ELROY'S","definition":"See SEAFOOD ELROY'S.","notesPages":[460],"id":"glossary-entry-sea-food-elroys","letter":"S"},{"term":"SEA FOOD JOHN'S","definition":"See SEAFOOD JOHN'S.","notesPages":[460],"id":"glossary-entry-sea-food-johns","letter":"S"},{"term":"SEA-LICE","definition":"Tiny ocean-floor creatures that etch figures into stone under Whale direction (137-138); create the living green color on Whale constructions (137); serve Whales as amanuenses, writing the Log-Books of the World on limestone blocks (163-165).","notesPages":[461],"id":"glossary-entry-sea-lice","letter":"S"},{"term":"SEA LOUSE (EPILOG BY)","definition":"Tiny ocean creature serving Whales as amanuensis; provides the epilogue, claiming Inneall's log is full of lies and future record-keeping belongs to the Whales (166).","notesPages":[460],"id":"glossary-entry-sea-louse-epilog-by","letter":"S"},{"term":"SEA MONSTER (OBSCENE)","definition":"See OBSCENE SEA MONSTER.","notesPages":[460],"id":"glossary-entry-sea-monster-obscene","letter":"S"},{"term":"SEA-RUMOR","definition":"Information spreading through the ocean; alerted the Nations of the Fishes to the existence of Inneall's new Ocean (138).","notesPages":[461],"id":"glossary-entry-sea-rumor","letter":"S"},{"term":"SEA-SATANS","definition":"Demonic sea creatures; howl like devils (107).","notesPages":[461],"id":"glossary-entry-sea-satans","letter":"S"},{"term":"SEA STONE (OCEAN)","definition":"Material from which Whales build forts (105).","notesPages":[460],"id":"glossary-entry-sea-stone-ocean","letter":"S"},{"term":"SEA-TURTLES","definition":"Large marine reptiles; suggested by Schimp as a food source for the pirates remaining on the invisible ship (119). See also LIVE PROVENDER.","notesPages":[461],"id":"glossary-entry-sea-turtles","letter":"S"},{"term":"SEA-WATER","definition":"Salt water of the ocean; cannot dampen the party spirit at Persimmon Manor (116).","notesPages":[461],"id":"glossary-entry-sea-water","letter":"S"},{"term":"SEAHORSES","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[461],"id":"glossary-entry-seahorses","letter":"S"},{"term":"SEAL (MARINO THE)","definition":"See MARINO.","notesPages":[461],"id":"glossary-entry-seal-marino-the","letter":"S"},{"term":"SEAMEN (PIRATE)","definition":"Sailors engaged in piracy; two crewmen on the Annabella (Sebastian Lazar, Quentillius Quern) had contrived names (98).","notesPages":[461],"id":"glossary-entry-seamen-pirate","letter":"S"},{"term":"SEAMLESS GARMENT","definition":"Metaphor used by Felix Culebra y Columba for the intricate weaving of The Life Affair, encompassing all aspects of existence (73-74).","notesPages":[461],"id":"glossary-entry-seamless-garment","letter":"S"},{"term":"SEBASTIAN LAZAR","definition":"See LAZAR, SEBASTIAN.","notesPages":[461],"id":"glossary-entry-sebastian-lazar","letter":"S"},{"term":"SECOND ASPECT (OF LIVES)","definition":"Phase of The Three's existence beginning when they gained access to the Lynn-Randal house at age one (5).","notesPages":[461],"id":"glossary-entry-second-aspect-of-lives","letter":"S"},{"term":"SECOND COOK (ALFRED)","definition":"Role the Royal Kids are trying Invisible Alfred out in aboard the Annabella Saint Ledger (114).","notesPages":[461],"id":"glossary-entry-second-cook-alfred","letter":"S"},{"term":"SECOND DAY OF SUMMERSET","definition":"The middle day of the final three- day period; events include the whales’ building activity (they arrived the day before, 106), Alfred’s sermon (109), the dive to Ocean Bottom (132–140), and the events leading into the Third Night and its birthday banquet (141–147). The earlier condominium dinner belongs to the First Night (67–73).","notesPages":[461,462],"id":"glossary-entry-second-day-of-summerset","letter":"S"},{"term":"SECOND EDEN","definition":"See EDEN (SECOND).","notesPages":[462],"id":"glossary-entry-second-eden","letter":"S"},{"term":"SECOND EDEN HOTEL","definition":"See EDEN (NEW EDEN HOTEL).","notesPages":[462],"id":"glossary-entry-second-eden-hotel","letter":"S"},{"term":"SECOND HUMANITY","definition":"The Axel's Golden Apes, anticipated to awaken and assume a primary role, potentially replacing or supplementing the current human species (65, 93, 142, 143, 144).","notesPages":[462],"id":"glossary-entry-second-humanity","letter":"S"},{"term":"SECOND LIVY (THE)","definition":"Potential meaning of the name 'Livius Secundus', referencing the great Roman historian Livy (70).","notesPages":[462],"id":"glossary-entry-second-livy-the","letter":"S"},{"term":"SECOND MANKIND","definition":"Alternate term used by Axel Grindstone for the inhabitants of Second Eden (The People Who Had Not Fallen), believed to be only about thirty years younger than First Mankind (11).","notesPages":[462],"id":"glossary-entry-second-mankind","letter":"S"},{"term":"SECOND NIGHT OF SUMMERSET","definition":"The night after the First Day and before the Second Day; the Nine paint the ship throughout it, finishing at false dawn (104–106). The Third Night follows the Second Day (140–141).","notesPages":[462],"id":"glossary-entry-second-night-of-summerset","letter":"S"},{"term":"SECOND PEOPLE (AWAKENING OF)","definition":"See AWAKENING (MOMENT OF THE AWAKENING OF THE SECOND PEOPLE).","notesPages":[462],"id":"glossary-entry-second-people-awakening-of","letter":"S"},{"term":"SECOND STRING (GOD'S BOW)","definition":"Metaphor derived from the Al- Waghe mural, representing God's reserve option or backup plan (the Second Eden) (11).","notesPages":[462],"id":"glossary-entry-second-string-gods-bow","letter":"S"},{"term":"SECONDS (DONATUS')","definition":"Four friends (Lady Anastasia Blickworthy, Jamestown Wixon, Clement and Rose-of-Sharon Montdrago) honor- sworn to carry out the hanging of Donatus O'Reily at the appointed time (118, 124, 153, 156, 157).","notesPages":[462],"id":"glossary-entry-seconds-donatus","letter":"S"},{"term":"SECRET (BIG EGG)","definition":"The contents and purpose remain undisclosed, though Dubu says she has solved the mystery (163); the Sea Louse repeats this claim (166).","notesPages":[462],"id":"glossary-entry-secret-big-egg","letter":"S"},{"term":"SECRET (DOLOPHONOI DECIDING DANGER)","definition":"The method or identity of who decides when a mega-person becomes a danger is also kept secret (82).","notesPages":[462],"id":"glossary-entry-secret-dolophonoi-deciding-danger","letter":"S"},{"term":"SECRET (DOLOPHONOI NATURE)","definition":"The true composition of the assassins (human, computer, animal, or hybrid) is kept very secret (82).","notesPages":[463],"id":"glossary-entry-secret-dolophonoi-nature","letter":"S"},{"term":"SECRET (GETTING IN)","definition":"The means of accessing the Cenaculum; Inneall knows the secret (the Executive Passage) (144).","notesPages":[463],"id":"glossary-entry-secret-getting-in","letter":"S"},{"term":"SECRET (INDOCTRINATION METHOD)","definition":"The technique and content of Satrap's process for inducing Oceanic Metastasis are kept secret (134).","notesPages":[463],"id":"glossary-entry-secret-indoctrination-method","letter":"S"},{"term":"SECRET (KANGAROO SOCIETY)","definition":"The Kangaroo operates as the most secret society ever, functioning mostly on the unconscious level (83).","notesPages":[463],"id":"glossary-entry-secret-kangaroo-society","letter":"S"},{"term":"SECRET NAME (MEPHISTOPHELES)","definition":"Knowledge of the Devil's secret name gave Faustus power (35).","notesPages":[463],"id":"glossary-entry-secret-name-mephistopheles","letter":"S"},{"term":"SECRET (NAME OF MAN)","definition":"Ambiguity, whispered as the secret name giving power over Man (35).","notesPages":[463],"id":"glossary-entry-secret-name-of-man","letter":"S"},{"term":"SECRET PLACE (AXEL)","definition":"The cenotaph where Axel is entombed, possibly serving as a place for curative powers or stasis (161).","notesPages":[463],"id":"glossary-entry-secret-place-axel","letter":"S"},{"term":"SECRETARIES","definition":"Persons employed to write or keep records; humans may serve the Whales in this capacity in the future (164).","notesPages":[463],"id":"glossary-entry-secretaries","letter":"S"},{"term":"SECT (GRANDEES)","definition":"A particular group of snooty Ambulatory Computers (63).","notesPages":[463],"id":"glossary-entry-sect-grandees","letter":"S"},{"term":"SEED-POD (EXPLODING)","definition":"Metaphor used by Popugai and Sebastian Lazar for the scattering of the experimental group after its purpose is fulfilled (161, 162).","notesPages":[463],"id":"glossary-entry-seed-pod-exploding","letter":"S"},{"term":"SEEDS (SCATTER)","definition":"Function of seeds when a seed-pod explodes; metaphor for the dispersal of the experimental group (161).","notesPages":[463],"id":"glossary-entry-seeds-scatter","letter":"S"},{"term":"SEINES","definition":"Large fishing nets; Mark Twain claims to use meridians and parallels as seines to drag the Atlantic for whales (131).","notesPages":[463],"id":"glossary-entry-seines","letter":"S"},{"term":"SELENIUM GHOSTS OF THE 1870'S (FICTION)","definition":"Work of shorter fiction written by R.A. Lafferty (publisher’s biographical note); refers to Selenium Ghosts of the 1870's.","notesPages":[463],"id":"glossary-entry-selenium-ghosts-of-the-1870s-fiction","letter":"S"},{"term":"SEMI-CONSCIOUS BLANDNESS","definition":"State characterizing Heaven, according to Carcajou (72).","notesPages":[464],"id":"glossary-entry-semi-conscious-blandness","letter":"S"},{"term":"SEMI-PRIVATE (HANGING/STONING)","definition":"Status supposed for the executions on Tom Dooley's Island, though impossible to maintain privacy (152).","notesPages":[464],"id":"glossary-entry-semi-private-hanging-stoning","letter":"S"},{"term":"SENSE (COMMON)","definition":"See COMMON SENSE.","notesPages":[464],"id":"glossary-entry-sense-common","letter":"S"},{"term":"SENSE (GOOD)","definition":"Sound judgment; Axel's Apes possess remarkably good sense (21).","notesPages":[464],"id":"glossary-entry-sense-good","letter":"S"},{"term":"SENSE (HISTORICAL)","definition":"Awareness and understanding of the past; lacking in all Ambulatory Computers, including the historian Livius Secundus (71).","notesPages":[464],"id":"glossary-entry-sense-historical","letter":"S"},{"term":"SENSE (NICEST)","definition":"Used to qualify the potentially offensive term \"obscene\" when applied to Ocean Creatures, suggesting a non- pejorative, perhaps technical or awesome, meaning (135).","notesPages":[464],"id":"glossary-entry-sense-nicest","letter":"S"},{"term":"SENSE OF RESPONSIBILITY","definition":"Moral accountability; supposedly an anti-social trait in the new Floating World, lacked by AMHs (27).","notesPages":[464],"id":"glossary-entry-sense-of-responsibility","letter":"S"},{"term":"SENSING (ACUTE)","definition":"Heightened perception, one of the advantages conferred by the state of Oceanic Metastasis (135).","notesPages":[464],"id":"glossary-entry-sensing-acute","letter":"S"},{"term":"SENSORS (INNEALL'S)","definition":"Devices used by Inneall for perception; used to examine the Big Egg (155).","notesPages":[464],"id":"glossary-entry-sensors-innealls","letter":"S"},{"term":"SENTIMENT","definition":"Emotion, particularly tenderness or nostalgia; George Lynn-Randal warns Iris against it regarding the experimental children, citing her past disastrous results from attacks of sentiment (7).","notesPages":[464],"id":"glossary-entry-sentiment","letter":"S"},{"term":"SENTIMENTALITIES","definition":"Acts driven by sentiment; Iris claims the results were more comic than disastrous (7).","notesPages":[464],"id":"glossary-entry-sentimentalities","letter":"S"},{"term":"SERPENT","definition":"Snake; Man slithered out of the Man's egg in one creation legend (36); refers generally to snakes (71).","notesPages":[464],"id":"glossary-entry-serpent","letter":"S"},{"term":"SERPENT'S EGG","definition":"See EGG (SERPENT'S).","notesPages":[464],"id":"glossary-entry-serpents-egg","letter":"S"},{"term":"SEVEN DAYS WONDER (TALKING ANIMALS)","definition":"The brief period of amazement caused by the sudden widespread phenomenon of talking animals (54).","notesPages":[465],"id":"glossary-entry-seven-days-wonder-talking-animals","letter":"S"},{"term":"SEVENTH COMPUTER AGE","definition":"See COMPUTER AGE (SEVENTH).","notesPages":[465],"id":"glossary-entry-seventh-computer-age","letter":"S"},{"term":"SEVENTH CREATURE (MANKIND)","definition":"See MANKIND CREATURE.","notesPages":[465],"id":"glossary-entry-seventh-creature-mankind","letter":"S"},{"term":"SEVENTH TECHNOLOGICAL AGE","definition":"See TECHNOLOGICAL AGE (SEVENTH).","notesPages":[465],"id":"glossary-entry-seventh-technological-age","letter":"S"},{"term":"SEX","definition":"Biological distinction or gender identity; Ambulatory Computers have no real sex but declare themselves male or female by custom (69).","notesPages":[465],"id":"glossary-entry-sex","letter":"S"},{"term":"SEX CHROMOSOMES","definition":"Chromosomes determining biological sex; the Unfallen People possess one pair, like humans (18).","notesPages":[465],"id":"glossary-entry-sex-chromosomes","letter":"S"},{"term":"SEXLESS","definition":"Lacking biological sex; Inneall is sexless by rational rules, yet insists she is a girl (3).","notesPages":[465],"id":"glossary-entry-sexless","letter":"S"},{"term":"SHAFT VENT","definition":"Exhaust opening; sweet reason flies out the shaft vent when humans run into emotional quirks (39).","notesPages":[465],"id":"glossary-entry-shaft-vent","letter":"S"},{"term":"SHAFTS (GRANITE)","definition":"Structural elements made of Wichita-Mountain Granite used in the Whales' constructions (137).","notesPages":[465],"id":"glossary-entry-shafts-granite","letter":"S"},{"term":"SHAFTS (MARBLE)","definition":"Long, narrow vertical elements made of marble in the Whales' underwater constructions (136).","notesPages":[465],"id":"glossary-entry-shafts-marble","letter":"S"},{"term":"SHAKESPEARE","definition":"William Shakespeare, source of the Julius Caesar quote used as epigraph for Chapter One (1).","notesPages":[466],"id":"glossary-entry-shakespeare","letter":"S"},{"term":"SHAKING (THE THREE)","definition":"The Three began to shake and shiver after Axel overheard the \"Serpent's Egg\" conversation (2).","notesPages":[465],"id":"glossary-entry-shaking-the-three","letter":"S"},{"term":"SHAKING (WOLVERENES)","definition":"Carcajou was shaking with fright at the arrival of the eleven wolverenes (102).","notesPages":[465],"id":"glossary-entry-shaking-wolverenes","letter":"S"},{"term":"SHAPE-CHANGER","definition":"Being capable of altering its form; the wolverene- were gun will kill werewolves and every sort of shape-changer (89).","notesPages":[466],"id":"glossary-entry-shape-changer","letter":"S"},{"term":"SHAPES","definition":"Forms or outlines; signature shapes (pentagon, square, triangle) identified by The Three in 'prowls' (6).","notesPages":[466],"id":"glossary-entry-shapes","letter":"S"},{"term":"SHARE AND SHARE ALIKE","definition":"Principle of equal distribution within the pirates' covenant (119) and the covenanted intellectuality of the Nine (122).","notesPages":[466],"id":"glossary-entry-share-and-share-alike","letter":"S"},{"term":"SHARKS","definition":"Predatory cartilaginous fish; various species (Dogfish, Great White, Sand, Hammerhead) flock to Inneall's Ocean (138); unique among Deep creatures for habitually having nightmares (139).","notesPages":[466],"id":"glossary-entry-sharks","letter":"S"},{"term":"SHARP FREQUENCIES (MIND OF GOD)","definition":"Narrow but distinct communication bands allegedly used by the Kangaroo, supposedly unmonitored by the Mind of God (80).","notesPages":[466],"id":"glossary-entry-sharp-frequencies-mind-of-god","letter":"S"},{"term":"SHEEP (KEA EATS)","definition":"Kea parrots (like Popugai) are known to kill and eat sheep in their wild state in New Zealand (64).","notesPages":[466],"id":"glossary-entry-sheep-kea-eats","letter":"S"},{"term":"SHEEP-KILLING BEAK","definition":"Popugai the parrot possesses this formidable weapon, mentioned alongside Marino's teeth as useful in battle (102).","notesPages":[466],"id":"glossary-entry-sheep-killing-beak","letter":"S"},{"term":"SHELL (KILL HIM IN THE)","definition":"Phrase from the Julius Caesar epigraph, advocating preemptive destruction of a potential threat (1).","notesPages":[466],"id":"glossary-entry-shell-kill-him-in-the","letter":"S"},{"term":"SHELL (SERPENT'S EGG)","definition":"The eggshell from which Man mistakenly hatched in legend (36); used metaphorically for crushing potential threats early (3).","notesPages":[466],"id":"glossary-entry-shell-serpents-egg","letter":"S"},{"term":"SHELLS (ANNIHILATION)","definition":"See ANNIHILATION SHELLS.","notesPages":[466],"id":"glossary-entry-shells-annihilation","letter":"S"},{"term":"SHELLS (BAZOOKA)","definition":"Ammunition for bazookas; five thousand rounds loaded onto the Annabella (101).","notesPages":[466],"id":"glossary-entry-shells-bazooka","letter":"S"},{"term":"SHELLYS","definition":"Collective term for shelled creatures (mollusks, crustaceans, etc.) present in Inneall's Ocean (139).","notesPages":[466],"id":"glossary-entry-shellys","letter":"S"},{"term":"SHIP ANNABELLA SAINT LEDGER","definition":"See ANNABELLA SAINT LEDGER (SHIP).","notesPages":[467],"id":"glossary-entry-ship-annabella-saint-ledger","letter":"S"},{"term":"SHIP BOATS","definition":"Small tenders belonging to a larger vessel; the speedsters Jolly Roger and Crabby Roger are designated Ship Boats of the Annabella Saint Ledger (58).","notesPages":[467],"id":"glossary-entry-ship-boats","letter":"S"},{"term":"SHIP (INVISIBLE)","definition":"See INVISIBLE SHIP.","notesPages":[466],"id":"glossary-entry-ship-invisible","letter":"S"},{"term":"SHIP INVISIBLE","definition":"See INVISIBLE SHIP.","notesPages":[467],"id":"glossary-entry-ship-invisible-38bfae","letter":"S"},{"term":"SHIP (NOBLE)","definition":"Designation applied to the Annabella Saint Ledger (104).","notesPages":[467],"id":"glossary-entry-ship-noble","letter":"S"},{"term":"SHIP OF FOOLS","definition":"Allegorical vessel carrying representatives of human folly; Inneall wonders if the Annabella Saint Ledger serves this function for all Mankind or just Cockeyed Mankind (141).","notesPages":[467],"id":"glossary-entry-ship-of-fools","letter":"S"},{"term":"SHIP (PIRATE)","definition":"See PIRATE SHIP.","notesPages":[467],"id":"glossary-entry-ship-pirate","letter":"S"},{"term":"SHIPBOARD","definition":"On or onto a ship; Alfred speaks from shipboard (109); pirates secure back on shipboard (120).","notesPages":[467],"id":"glossary-entry-shipboard","letter":"S"},{"term":"SHIPLAP","definition":"Computer scientist associated with Smirnov at the Institute of Impure Science, involved in developing the first AMHs (25).","notesPages":[467],"id":"glossary-entry-shiplap","letter":"S"},{"term":"SHIPS","definition":"Vessels for water travel; needed by Inneall for her Pirate Queen role (23); Whales scare other ships (97).","notesPages":[467],"id":"glossary-entry-ships","letter":"S"},{"term":"SHIPS (FLOATING WORLD)","definition":"Metaphorically, the unmoored nations floating in the air (82).","notesPages":[467],"id":"glossary-entry-ships-floating-world","letter":"S"},{"term":"SHIPS FOR SEA","definition":"Phrase from Inneall's poem epigraph (23).","notesPages":[467],"id":"glossary-entry-ships-for-sea","letter":"S"},{"term":"SHIP'S MANIFEST","definition":"Official document listing cargo, crew, and passengers; Satrap notes the contrived names of Lazar and Quern on the manifest (98).","notesPages":[467],"id":"glossary-entry-ships-manifest","letter":"S"},{"term":"SHIP'S STORES","definition":"Supplies necessary for operating a ship; Inneall demands Satrap continue paying for them (47); Quentillius charges loading costs to 'Ship's Stores' (101).","notesPages":[467],"id":"glossary-entry-ships-stores","letter":"S"},{"term":"SHIP'S WHEEL (INVISIBLE)","definition":"The helm of the invisible Annabella Saint Ledger, seemingly steered by a skeleton (120).","notesPages":[467],"id":"glossary-entry-ships-wheel-invisible","letter":"S"},{"term":"SHIVERING (THE THREE)","definition":"Physical reaction of The Three upon hearing Axel's report of the overheard conversation (2).","notesPages":[468],"id":"glossary-entry-shivering-the-three","letter":"S"},{"term":"SHOCK","definition":"Sudden upsetting or surprising event or experience; the shock of discovering the Unfallens' appearance may kill Axel (14); encountering shock can erode Oceanic Metastasis (150).","notesPages":[468],"id":"glossary-entry-shock","letter":"S"},{"term":"SHOES (PYTHON-SKIN)","definition":"See PYTHON-SKIN SHOES.","notesPages":[468],"id":"glossary-entry-shoes-python-skin","letter":"S"},{"term":"SHOOT","definition":"Discharge a weapon; Assassins shoot the Elephant-Gun (90); Carcajou offers to shoot himself first (90); Popugai's beak is offered as a weapon, but no shooting ability is stated (102).","notesPages":[468],"id":"glossary-entry-shoot","letter":"S"},{"term":"SHOOTER (ANGEL-GUN/W-W-GUN KILLS)","definition":"The person firing the angel-gun or wolverene- were gun is killed simultaneously with the target (88).","notesPages":[468],"id":"glossary-entry-shooter-angel-gun-w-w-gun-kills","letter":"S"},{"term":"SHORE BANK","definition":"Edge of the land where deep water comes right up to it; location where Alfred orders the ship put ashore (108).","notesPages":[468],"id":"glossary-entry-shore-bank","letter":"S"},{"term":"SHORE (ISLAND)","definition":"Coastline of Tom Dooley's Island; site for Zchold's stoning (122); location where whales beach themselves (158).","notesPages":[468],"id":"glossary-entry-shore-island","letter":"S"},{"term":"SHORE (NORTH, INNEALL'S OCEAN)","definition":"See NORTH SHORE (INNEALL'S OCEAN).","notesPages":[468],"id":"glossary-entry-shore-north-innealls-ocean","letter":"S"},{"term":"SHORE (OCEAN)","definition":"See OCEAN SHORE.","notesPages":[468],"id":"glossary-entry-shore-ocean","letter":"S"},{"term":"SHORT BLOCK (STRUCTO LANE)","definition":"Description of Structo Lane, the enclave for maverick Ambulatory Computers (9).","notesPages":[468],"id":"glossary-entry-short-block-structo-lane","letter":"S"},{"term":"SHORT KNIFE","definition":"See KNIFE (SHORT, SHARP-BLADED).","notesPages":[468],"id":"glossary-entry-short-knife","letter":"S"},{"term":"SHORT LANES","definition":"Description of Structo Lane and Ape Lane, noted for extravagant detail despite limited length (9).","notesPages":[468],"id":"glossary-entry-short-lanes","letter":"S"},{"term":"SHORT, SHARP-BLADED KNIVES","definition":"Weapons habitually carried by Dolophonoi-Assassins (85); one obtained by Henryetta (139); used by Randal, Carcajou, and Schimp (100, 125); used to kill Axel and Randal (148).","notesPages":[468],"id":"glossary-entry-short-sharp-bladed-knives","letter":"S"},{"term":"SHORTER PIECES (PUBLISHED)","definition":"the 1987 edition’s author biography reports about 250 shorter works published by that time (publisher’s biographical note).","notesPages":[468],"id":"glossary-entry-shorter-pieces-published","letter":"S"},{"term":"SHOUT (AXEL'S SILENT)","definition":"Axel opens his mouth to shout in joy upon waking, but no sound emerges before he is killed (147).","notesPages":[469],"id":"glossary-entry-shout-axels-silent","letter":"S"},{"term":"SHOW TIME (STRUCTO LANE)","definition":"Midnight performance time, following the human custom of later shows for more elegant audiences (76).","notesPages":[469],"id":"glossary-entry-show-time-structo-lane","letter":"S"},{"term":"SHOWPERSONS","definition":"Skilled entertainers; the animal members of the Experiments are described as consummate showpersons (86).","notesPages":[469],"id":"glossary-entry-showpersons","letter":"S"},{"term":"SHOWS","definition":"Performances or exhibitions; burlesque shows reinvented by Computers (33); sideshows performed by the Eleven (86).","notesPages":[469],"id":"glossary-entry-shows","letter":"S"},{"term":"SHOWS (BURLESQUE)","definition":"See BURLESQUE SHOWS.","notesPages":[469],"id":"glossary-entry-shows-burlesque","letter":"S"},{"term":"SHRIKES","definition":"Predatory birds, typically considered unpleasant (\"evil shrikes\"); participate in the air dances at Heart's Desire Cove (58).","notesPages":[469],"id":"glossary-entry-shrikes","letter":"S"},{"term":"SICKNESS (HAPPIEST)","definition":"Lutin describes her condition (pregnancy, later followed by the birth of three baby pythons; her claim to have produced the Big Egg remains disputed) as the most delightful and soul-wrenching sickness imaginable (141, 134).","notesPages":[469],"id":"glossary-entry-sickness-happiest","letter":"S"},{"term":"SICKNESS (LUTIN'S)","definition":"Lutin's pregnancy, initially described through her mournful, withdrawn moments and Henryetta's allegation of earlier promiscuity (62, 73). Lutin later calls it the 'happiest sickness' (141); after she gives birth, three baby pythons are found with the Fates (153–155, 160).","notesPages":[469],"id":"glossary-entry-sickness-lutins","letter":"S"},{"term":"SICKNESS (SCANDAL-MONGER'S)","definition":"See SCANDAL-MONGER'S SICKNESS.","notesPages":[469],"id":"glossary-entry-sickness-scandal-mongers","letter":"S"},{"term":"SICKNESS (SOUL-WRENCHING)","definition":"Lutin describes her condition as such, yet also delightful (134).","notesPages":[469],"id":"glossary-entry-sickness-soul-wrenching","letter":"S"},{"term":"SIDE (WEATHER)","definition":"The side of a ship exposed to the prevailing wind and weather (132).","notesPages":[469],"id":"glossary-entry-side-weather","letter":"S"},{"term":"SIDESHOWS","definition":"Secondary attractions at a circus or fair; performed by the Eleven between main circus performances, with Lutin's fortune- telling tent being the best (86).","notesPages":[469],"id":"glossary-entry-sideshows","letter":"S"},{"term":"SIDEWALK CAFE (JACK FLANNAGAN'S)","definition":"See JACK FLANNAGAN'S PIANO BAR AND SIDEWALK CAFE.","notesPages":[470],"id":"glossary-entry-sidewalk-cafe-jack-flannagans","letter":"S"},{"term":"SIDEWALK CAFE ROW","definition":"Area along Ocean Shore featuring sidewalk cafes where crowds gathered and joined in song (77).","notesPages":[470],"id":"glossary-entry-sidewalk-cafe-row","letter":"S"},{"term":"SIDEWALK CAFES","definition":"Outdoor eating establishments along the shore of Heart's Desire Cove, featuring colorful umbrellas (58).","notesPages":[470],"id":"glossary-entry-sidewalk-cafes","letter":"S"},{"term":"SIDEWALKS (RIO)","definition":"Multi-colored walkways installed along the stony shore of Heart's Desire Cove (58). The novel does not explain the reference in “Rio.”","notesPages":[470],"id":"glossary-entry-sidewalks-rio","letter":"S"},{"term":"SIGN (FROM ABOVE SKY)","definition":"Requested by Axel via mud message; immediately answered by quick lightning and a rain shower (4).","notesPages":[470],"id":"glossary-entry-sign-from-above-sky","letter":"S"},{"term":"SIGN (KANGAROO)","definition":"The constellation Kanguruus, hidden behind Virgo (111).","notesPages":[470],"id":"glossary-entry-sign-kangaroo","letter":"S"},{"term":"SIGN (TOO GREAT)","definition":"A miracle deemed excessive for the occasion; Invisible Alfred avoids asking for an ideal mountain because it would be too great a sign (109).","notesPages":[470],"id":"glossary-entry-sign-too-great","letter":"S"},{"term":"SIGN (WHALE)","definition":"The welcoming sign \"'We're Glad You're Here'\" posted by the Whales in their underwater city (136).","notesPages":[470],"id":"glossary-entry-sign-whale","letter":"S"},{"term":"SIGNAL (AWAKENING)","definition":"The sign sent out from the wakened Apes in the Cavern to trigger awakening in 'Apes in Exile' worldwide (51).","notesPages":[470],"id":"glossary-entry-signal-awakening","letter":"S"},{"term":"SIGNAL (HAND)","definition":"Prearranged wave between Inneall (on shore) and Lanternjaw (invisible, in crows-nest) using their left hands, confirming contact (152).","notesPages":[470],"id":"glossary-entry-signal-hand","letter":"S"},{"term":"SIGNATURE COLORS/GEOMETRIES","definition":"Distinctive visual symbols (Axel: golden pentagon; Randal: orange square; Inneall: lavender- purple triangle) identified by The Three within 'prowls', allowing them to identify with corresponding characters (6).","notesPages":[470],"id":"glossary-entry-signature-colors-geometries","letter":"S"},{"term":"SIGNATURE (GAJAH'S TRUMPETING)","definition":"Her unique vocalization, more indicative of her identity than her drumming (56).","notesPages":[470],"id":"glossary-entry-signature-gajahs-trumpeting","letter":"S"},{"term":"SIGNS (GARGOYLES AS)","definition":"The carved figures left on cathedrals as evidence of the Unfallen People's presence (13).","notesPages":[470],"id":"glossary-entry-signs-gargoyles-as","letter":"S"},{"term":"SIGNS (ZODIACAL)","definition":"The twelve constellations of the zodiac used in astrology; considered mere fortune-telling devices by AMH Computers (30); depicted by Invisible Alfred along with their hidden \"true signs\" (111).","notesPages":[471],"id":"glossary-entry-signs-zodiacal","letter":"S"},{"term":"SILENCE (GIFT OF)","definition":"Requested by Ruddy Lord Randal in prayer/command directed at the howling Devil-Fish (108).","notesPages":[471],"id":"glossary-entry-silence-gift-of","letter":"S"},{"term":"SILENCE (TOTAL)","definition":"Absolute quiet; follows Alfred's command to the Devil-Fish (108); would kill someone of Inneall's disposition if enforced (164).","notesPages":[471],"id":"glossary-entry-silence-total","letter":"S"},{"term":"SILENT CARE-TAKERS","definition":"See CARE-TAKERS.","notesPages":[471],"id":"glossary-entry-silent-care-takers","letter":"S"},{"term":"SILENT MOVIES","definition":"Films without synchronized sound; shown exclusively in the Ape Alley movie house, often featuring Axel's Apes (45-46).","notesPages":[471],"id":"glossary-entry-silent-movies","letter":"S"},{"term":"SILENTS (NEW)","definition":"Newly produced silent films, made exclusively for the Ape Alley theatre (46).","notesPages":[471],"id":"glossary-entry-silents-new","letter":"S"},{"term":"SILLINESS (INNEALL'S)","definition":"Inneall's own recognition of the foolishness of chanting \"'I cannot stand the world on its ear'\" before rebelling against it (23).","notesPages":[471],"id":"glossary-entry-silliness-innealls","letter":"S"},{"term":"SILLY SEASON","definition":"Time of frivolous behavior; Rose-of-Sharon suggests it has arrived at Persimmon Manor due to talk of a giant glowing egg (153).","notesPages":[471],"id":"glossary-entry-silly-season","letter":"S"},{"term":"SILVER-SIDES","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[471],"id":"glossary-entry-silver-sides","letter":"S"},{"term":"SIMIAN (AXEL THE APE)","definition":"Relating to apes; Axel described as a simian of the species Axel's Ape (3).","notesPages":[471],"id":"glossary-entry-simian-axel-the-ape","letter":"S"},{"term":"SIMPLE FORTUNE-TELLING DEVICES","definition":"AMH Computer's assessment of the zodiacal signs used in astrology (30).","notesPages":[471],"id":"glossary-entry-simple-fortune-telling-devices","letter":"S"},{"term":"SIMPLE GAMBLING","definition":"Basic games of chance at which AMH Computers easily fleece humans (39).","notesPages":[471],"id":"glossary-entry-simple-gambling","letter":"S"},{"term":"SIMPLE-MINDED (BIRDMASTER)","definition":"Description of the Birdmaster, suggesting naivety or lack of complex thought (60).","notesPages":[471],"id":"glossary-entry-simple-minded-birdmaster","letter":"S"},{"term":"SIMPLE-MINDED (UNFALLENS)","definition":"Description applied to the Unfallen People, alongside \"talented,\" highlighting the paradox that makes them exploitable (18).","notesPages":[472],"id":"glossary-entry-simple-minded-unfallens","letter":"S"},{"term":"SIMPLICITY (VS COMPLEXITY)","definition":"An AMH claims that human languages and concepts become more complex as their histories are traced backward (37). This is the computer’s account, not an established general law of language history.","notesPages":[472],"id":"glossary-entry-simplicity-vs-complexity","letter":"S"},{"term":"SING-A-LONGS","definition":"Communal singing events; various songs enjoyed by humans, animals, and computers at Heart's Desire Cove (60).","notesPages":[472],"id":"glossary-entry-sing-a-longs","letter":"S"},{"term":"SINGERS","definition":"(Implied) Those who perform songs, like the unseen singer in Jack Flannagan's Piano Bar (151).","notesPages":[472],"id":"glossary-entry-singers","letter":"S"},{"term":"SINGING (COMPUTER)","definition":"An Ambulatory Computer sings \"'A sword is hanging o'er your head...'\" at Jack Flannagan's bar (77).","notesPages":[472],"id":"glossary-entry-singing-computer","letter":"S"},{"term":"SINGING INHABITANTS","definition":"Characteristic of towns with Empress Elephant mayors (92).","notesPages":[472],"id":"glossary-entry-singing-inhabitants","letter":"S"},{"term":"SINGLE BREATH (SLOGAN)","definition":"A good slogan, whether human or computer, should be capable of being spoken in a single breath (unlike the female AMHs' lengthy slogan) (69).","notesPages":[472],"id":"glossary-entry-single-breath-slogan","letter":"S"},{"term":"SINGLE LANE (STRUCTO/APE LANE)","definition":"Both Structo Lane and Ape Lane are described as being only a single lane, a short block in length (9).","notesPages":[472],"id":"glossary-entry-single-lane-structo-ape-lane","letter":"S"},{"term":"SINGLE MOLECULES (STRINGS OF)","definition":"Form pathways within wotto metal computer matrices (26).","notesPages":[472],"id":"glossary-entry-single-molecules-strings-of","letter":"S"},{"term":"SINGLETON (THOMAS)","definition":"An individual, not part of a pair; Alfred calls the Apostle Thomas a “singleton” and explains his designation “the twin” through Gemini (111); the Gospel does not identify his twin.","notesPages":[472],"id":"glossary-entry-singleton-thomas","letter":"S"},{"term":"SINISTER-APPEARING CLIFFS","definition":"The newly formed rock cliffs north of Inneall's Ocean where the Dolophonoi nest (84).","notesPages":[472],"id":"glossary-entry-sinister-appearing-cliffs","letter":"S"},{"term":"SINISTER INFLUENCE","definition":"Malevolent effect; putting oneself under such influence by learning the future (31).","notesPages":[472],"id":"glossary-entry-sinister-influence","letter":"S"},{"term":"SINISTER TACTICS","definition":"Underhanded methods; acceptable for computers to use if they first warn the human being fortuned (30).","notesPages":[472],"id":"glossary-entry-sinister-tactics","letter":"S"},{"term":"SINK (FLOATING WORLD BOAT)","definition":"Even a giant boat of remarkable resiliency can sink if it ships enough water (82).","notesPages":[473],"id":"glossary-entry-sink-floating-world-boat","letter":"S"},{"term":"SINKING (ISLAND)","definition":"Tom Dooley's Island is rapidly sinking into Inneall's Ocean (100, 115, 116, 151, 152, 159).","notesPages":[473],"id":"glossary-entry-sinking-island","letter":"S"},{"term":"SINKING SHIP (CYCLIC)","definition":"Humanity described metaphorically as a vessel caught in repeating cycles of decline, from which Computers must disassociate (38).","notesPages":[473],"id":"glossary-entry-sinking-ship-cyclic","letter":"S"},{"term":"SIR","definition":"Polite term of address used by Lanternjaw Lunnigan when speaking to Satrap Saint Ledger (99).","notesPages":[473],"id":"glossary-entry-sir","letter":"S"},{"term":"SIRIUS (DOG STAR)","definition":"Brightest star in the night sky; its heliacal rising could be tracked using alignments in the Whale Temple-City (137).","notesPages":[473],"id":"glossary-entry-sirius-dog-star","letter":"S"},{"term":"SIS (LITTLE)","definition":"Affectionate, possibly slightly patronizing term used by Satrap Saint Ledger when addressing Inneall (48); used by Jack Flannagan addressing Inneall (152).","notesPages":[473],"id":"glossary-entry-sis-little","letter":"S"},{"term":"SISTERS (THREE UGLY)","definition":"See FATES (THREE FATES).","notesPages":[473],"id":"glossary-entry-sisters-three-ugly","letter":"S"},{"term":"SITTING ON SECRETS (INNEALL)","definition":"Lutin accuses Inneall of withholding the secret method for entering Ape Caverns (144).","notesPages":[473],"id":"glossary-entry-sitting-on-secrets-inneall","letter":"S"},{"term":"SITUATION","definition":"Set of circumstances; Satrap likes to be in control of a situation (70).","notesPages":[473],"id":"glossary-entry-situation","letter":"S"},{"term":"SIXTY-FOUR PIECE CHESS","definition":"Complex variant of chess at which Dubu the bear excels, able to beat anyone except Luas the Angel (75).","notesPages":[473],"id":"glossary-entry-sixty-four-piece-chess","letter":"S"},{"term":"SKETCHY","definition":"Lacking detail; visuals and sound in 'prowls' are sketchy (6); present forms of human languages are sketchy (37).","notesPages":[473],"id":"glossary-entry-sketchy","letter":"S"},{"term":"SKILLED WORKERS","definition":"Part of the itinerant workforce drawn to Ape Caverns (45).","notesPages":[473],"id":"glossary-entry-skilled-workers","letter":"S"},{"term":"SKIN","definition":"Outer covering; Axel the Ape's hump is only a sac of skin and flesh (42); Lutin keeps her skin neat and freshly oiled (62); python- skin shoes (86); Invisible Alfred's skin became whited and colorless inside the whale (109).","notesPages":[473],"id":"glossary-entry-skin","letter":"S"},{"term":"SKITTISH (DOLOPHONOI)","definition":"Jumpy or easily frightened; state of the Dolophonoi guards at Ape Caverns (67).","notesPages":[474],"id":"glossary-entry-skittish-dolophonoi","letter":"S"},{"term":"SKITTISH (ZOOS)","definition":"Zoos are nervous or easily frightened by over- endowed male animal specimens (20).","notesPages":[474],"id":"glossary-entry-skittish-zoos","letter":"S"},{"term":"SKOKEMCHUCK RAG (SONG)","definition":"A campfire song sung at Heart's Desire Cove (59); refers to Skokemchuck Rag.","notesPages":[474],"id":"glossary-entry-skokemchuck-rag-song","letter":"S"},{"term":"SKULL-BUMP READING","definition":"Phrenology; one of the divination methods used by Lutin the Pythoness (86).","notesPages":[474],"id":"glossary-entry-skull-bump-reading","letter":"S"},{"term":"SKULLS (THIN-SKULLED HEAD)","definition":"Description of Axel Grindstone's head, suggesting fragility or susceptibility to single ideas (10, 18).","notesPages":[474],"id":"glossary-entry-skulls-thin-skulled-head","letter":"S"},{"term":"SKY","definition":"The expanse above the earth; Axel makes marks on the sky-cover (4); stations in the sky (astrology) (30); signs appear in the sky (76, 77, 111); Kangaroo sighted in the sky (78, 166); lowering sky above Ape Caverns (68); midnight sky (59).","notesPages":[474],"id":"glossary-entry-sky","letter":"S"},{"term":"SKY-COVER (TRANSPARENT)","definition":"The dome, twenty meters high, covering The Three's habitat; Axel shoots mud marks onto it (4).","notesPages":[474],"id":"glossary-entry-sky-cover-transparent","letter":"S"},{"term":"SKY (EASTERN)","definition":"Location where the Kangaroo constellation appears before sunrise (76).","notesPages":[474],"id":"glossary-entry-sky-eastern","letter":"S"},{"term":"SKY (KANGAROO SIGHTED)","definition":"The Kangaroo constellation seen in the sky (78, 111).","notesPages":[474],"id":"glossary-entry-sky-kangaroo-sighted","letter":"S"},{"term":"SKY (LOWERING)","definition":"Threatening or descending appearance of the sky above Ape Caverns when the giant hand appears (68).","notesPages":[474],"id":"glossary-entry-sky-lowering","letter":"S"},{"term":"SKY (MIDNIGHT)","definition":"The glowing gegenschein observed at Heart's Desire Cove (59).","notesPages":[474],"id":"glossary-entry-sky-midnight","letter":"S"},{"term":"SLABS (LIMESTONE)","definition":"Flat pieces of limestone used by sea-lice as writing surfaces (164).","notesPages":[474],"id":"glossary-entry-slabs-limestone","letter":"S"},{"term":"SLACKNESS (UNFALLEN FACES)","definition":"Looseness or lack of tension in the facial features of the Unfallen People, contributing to their appearance of being drunk to humans (17).","notesPages":[474],"id":"glossary-entry-slackness-unfallen-faces","letter":"S"},{"term":"SLANG U.S. (KANGAROO COURT)","definition":"Origin designation for the term \"Kangaroo court\" provided by Webster's Collegiate (79).","notesPages":[475],"id":"glossary-entry-slang-u-s-kangaroo-court","letter":"S"},{"term":"SLANTED SUN","definition":"The sun low in the sky during evening; the depths become pitch-dark while the slanted evening sun remains above the ocean (139).","notesPages":[475],"id":"glossary-entry-slanted-sun","letter":"S"},{"term":"SLEEP","definition":"State of rest; The Three sleep (23); ghosts sleep (29); whales 'sleep' (138); Axel sleeps in tree (28); Randal naps over book (28); deep sleep induced by Dubu (127). See also DEEP SLEEP, HOLY SLEEP, OCEAN SLEEP.","notesPages":[475],"id":"glossary-entry-sleep","letter":"S"},{"term":"SLEEP-WALKING (DOLOPHONOI)","definition":"State induced by Dolophonoi for stealthy killing (143); they practice it (98).","notesPages":[475],"id":"glossary-entry-sleep-walking-dolophonoi","letter":"S"},{"term":"SLEEP-WALKING KILLING","definition":"Murder committed while in a somnambulistic state, practiced by Dolophonoi (98, 99).","notesPages":[475],"id":"glossary-entry-sleep-walking-killing","letter":"S"},{"term":"SLEEPERS (APES)","definition":"The Axel's Golden Apes residing in the Cenaculum within Ape Caverns during their Deep Sleep (67, 70, 143, 144, 147, 148).","notesPages":[475],"id":"glossary-entry-sleepers-apes","letter":"S"},{"term":"SLEEPIEST KING-AND-EMPEROR (PRESTER JOHN)","definition":"Title emphasizing Prester John's habit of sleeping most of the time, waking only briefly to give wise decisions (12).","notesPages":[475],"id":"glossary-entry-sleepiest-king-and-emperor-prester-john","letter":"S"},{"term":"SLEEPWALKERS' SERENADE","definition":"Title of Chapter Twelve (130); refers to Sleepwalkers' Serenade.","notesPages":[475],"id":"glossary-entry-sleepwalkers-serenade","letter":"S"},{"term":"SLEEPY ONE (REIGNING)","definition":"See REIGNING SLEEPY ONE.","notesPages":[475],"id":"glossary-entry-sleepy-one-reigning","letter":"S"},{"term":"SLIGHT ROLE (SEA-LOUSE)","definition":"The humble position claimed by the Sea Louse providing the epilogue (166).","notesPages":[475],"id":"glossary-entry-slight-role-sea-louse","letter":"S"},{"term":"SLITHERED (SERPENT)","definition":"Movement of the Serpent hatching from the Man's egg in creation legend (36).","notesPages":[475],"id":"glossary-entry-slithered-serpent","letter":"S"},{"term":"SLOGAN ('BLAND IS BETTER')","definition":"Maxim used by the Levellers to promote conformity and suppress individuality (69).","notesPages":[475],"id":"glossary-entry-slogan-bland-is-better","letter":"S"},{"term":"SLOGAN (COMPUTER)","definition":"The lengthy, unwieldy declaration used by female AMHs demanding gender parity (\"'There can be no freedom until...'\") (69).","notesPages":[476],"id":"glossary-entry-slogan-computer","letter":"S"},{"term":"SLOGAN ('ECCENTRICITY IS OUT')","definition":"Maxim used by the Levellers (69).","notesPages":[475],"id":"glossary-entry-slogan-eccentricity-is-out","letter":"S"},{"term":"SLOGAN (HUMAN)","definition":"A good slogan, whether human or computer, should be speakable in a single breath (69).","notesPages":[476],"id":"glossary-entry-slogan-human","letter":"S"},{"term":"SLOGAN ('NO GOVERNMENT...')","definition":"See NO GOVERNMENT IS THE BEST GOVERNMENT (SLOGAN).","notesPages":[476],"id":"glossary-entry-slogan-no-government","letter":"S"},{"term":"SLOPES (GREEN)","definition":"Hillsides where crowds may recline, one of the three great places for addressing multitudes (109).","notesPages":[476],"id":"glossary-entry-slopes-green","letter":"S"},{"term":"SLOTHS (FAT)","definition":"Experimental animals included in the fauna of The Three's habitat (3).","notesPages":[476],"id":"glossary-entry-sloths-fat","letter":"S"},{"term":"SMALL CHILDREN (PROWLS)","definition":"Target audience category for Jackdaw Press prowls, along with teenagers and adults (8).","notesPages":[476],"id":"glossary-entry-small-children-prowls","letter":"S"},{"term":"SMALL INTESTINE","definition":"Part of the digestive tract; thirty centimeters requested by a lady from Zchold's disemboweled body for her son's collection (158).","notesPages":[476],"id":"glossary-entry-small-intestine","letter":"S"},{"term":"SMALL ODDITIES (FACES)","definition":"Minor peculiarities in the faces of the Unfallen People, which Ansel Grindstone urges Axel to accept (17).","notesPages":[476],"id":"glossary-entry-small-oddities-faces","letter":"S"},{"term":"SMART (DUBU)","definition":"Dubu insists Inneall isn't smart for always reading intelligent books instead of mystery stories (163).","notesPages":[476],"id":"glossary-entry-smart-dubu","letter":"S"},{"term":"SMART-TALKY","definition":"Speaking in an overly clever or sassy manner; Inneall admits she was just getting smart-talky when coining 'Enlargement of the World' (113).","notesPages":[476],"id":"glossary-entry-smart-talky","letter":"S"},{"term":"SMELL (BRIMSTONE)","definition":"Strong, frightful odor accompanying the Carcajou-Luas wrestling match (87).","notesPages":[476],"id":"glossary-entry-smell-brimstone","letter":"S"},{"term":"SMELL (FUNNY)","definition":"The smell of treason detected by Lutin in the crows-nest, disappearing when something unseen brushes past Inneall and departs (145), before Alfred’s identity is revealed (149).","notesPages":[476],"id":"glossary-entry-smell-funny","letter":"S"},{"term":"SMELL (POWDER)","definition":"Odor of black-powder and gun-powder associated with pyrotechnics and the wrestling match (87).","notesPages":[476],"id":"glossary-entry-smell-powder","letter":"S"},{"term":"SMELL (TREACHERY)","definition":"See SMELL (FUNNY).","notesPages":[476],"id":"glossary-entry-smell-treachery","letter":"S"},{"term":"SMELLS","definition":"Odors perceived by the sense of smell; present in the Lynn- Randal house, distinct from outdoor smells (5); least-common- denominator smells (8).","notesPages":[477],"id":"glossary-entry-smells","letter":"S"},{"term":"SMILED (DOLOPHONOS)","definition":"The Mega Dolophonos sneered and smiled before touching Carcajou (94).","notesPages":[477],"id":"glossary-entry-smiled-dolophonos","letter":"S"},{"term":"SMILED (INNEALL)","definition":"Inneall smiled at the Three Fates after they became foster mothers (160).","notesPages":[477],"id":"glossary-entry-smiled-inneall","letter":"S"},{"term":"SMILED (WEIRD SISTERS)","definition":"The Three Fates smiled back at Inneall, indicating accord (160).","notesPages":[477],"id":"glossary-entry-smiled-weird-sisters","letter":"S"},{"term":"SMIRKED (IRIS)","definition":"Facial expression made by Iris Lynn-Randal when asserting her sentimentalities were more comic than disastrous (7).","notesPages":[477],"id":"glossary-entry-smirked-iris","letter":"S"},{"term":"SMIRNOV","definition":"Computer scientist associated with Shiplap at the Institute of Impure Science, involved in developing the first AMHs (25).","notesPages":[477],"id":"glossary-entry-smirnov","letter":"S"},{"term":"SMITHERY","definition":"The craft of working metal; Unfallen Ones are experts in every sort (15, 16).","notesPages":[477],"id":"glossary-entry-smithery","letter":"S"},{"term":"SMITHIES (APES')","definition":"Workshops in Ape Alley containing gas-fired forges where the Yellow Apes fabricate items (46, 47).","notesPages":[477],"id":"glossary-entry-smithies-apes","letter":"S"},{"term":"SMITHY APES","definition":"Alternative name for the Axel's Apes, referencing their skill in metalworking (3, 13, 19).","notesPages":[477],"id":"glossary-entry-smithy-apes","letter":"S"},{"term":"SMOKE","definition":"Visible vapor from burning; smoke and something like invisibility associated with the Knives/Dolophonoi (83).","notesPages":[477],"id":"glossary-entry-smoke","letter":"S"},{"term":"SMOKING CHIMNEY","definition":"Object easily mimicked by AMH Computers (26).","notesPages":[477],"id":"glossary-entry-smoking-chimney","letter":"S"},{"term":"SMOKING JACKET","definition":"Attire worn by the elegant AMH Computer while smoking a cigar (30).","notesPages":[477],"id":"glossary-entry-smoking-jacket","letter":"S"},{"term":"SMOOTH SURFACE (OCEAN)","definition":"Glassy appearance of the sea broken by the magnificent whale summoned by Alfred (110).","notesPages":[477],"id":"glossary-entry-smooth-surface-ocean","letter":"S"},{"term":"SNAKE-AND-DOVE (FELIX)","definition":"Nickname for Felix Culebra y Columba, referencing his surname and symbolic nature (73).","notesPages":[478],"id":"glossary-entry-snake-and-dove-felix","letter":"S"},{"term":"SNAKE COUCH","definition":"Long, low piece of furniture on which Lutin reclines (154).","notesPages":[478],"id":"glossary-entry-snake-couch","letter":"S"},{"term":"SNAKE-EYE VIEW","definition":"Lutin the pythoness possesses this perspective, which misses many significations (62).","notesPages":[478],"id":"glossary-entry-snake-eye-view","letter":"S"},{"term":"SNAKE (LUTIN)","definition":"Henryetta addresses Lutin derogatorily as \"snake\" (62).","notesPages":[477],"id":"glossary-entry-snake-lutin","letter":"S"},{"term":"SNAKE-SIGHS (WEARY)","definition":"Sound made by Lutin when expressing resignation about the Fates being aboard the Annabella (103).","notesPages":[478],"id":"glossary-entry-snake-sighs-weary","letter":"S"},{"term":"SNAKES (BABY)","definition":"Three live baby pythons birthed by Lutin, found being fostered by the Three Fates (160).","notesPages":[478],"id":"glossary-entry-snakes-baby","letter":"S"},{"term":"SNAKES (HARMLESS/BENEVOLENT)","definition":"The Three believe that only harmless, benevolent snakes lay eggs (3). This is not sound zoology: some venomous snakes, including king cobras, lay eggs.","notesPages":[478],"id":"glossary-entry-snakes-harmless-benevolent","letter":"S"},{"term":"SNAPPERS (RED-)","definition":"See RED-SNAPPERS.","notesPages":[478],"id":"glossary-entry-snappers-red","letter":"S"},{"term":"SNEERED (DOLOPHONOS)","definition":"Facial expression of the Mega Dolophonos before touching Carcajou (94).","notesPages":[478],"id":"glossary-entry-sneered-dolophonos","letter":"S"},{"term":"SNIGGER","definition":"Laugh in a partly suppressed manner; sound made by the crowd reacting to Alfred's badly-drawn sky cartoons (111).","notesPages":[478],"id":"glossary-entry-snigger","letter":"S"},{"term":"SNOOTINESS (HENRYETTA)","definition":"Quality possessed by Henryetta, resembling that of The Grandees sect of AMH Computers (63).","notesPages":[478],"id":"glossary-entry-snootiness-henryetta","letter":"S"},{"term":"SNOUT (MIOL-MOR)","definition":"The projecting nose and mouth of the whale Miol-Mor, thrust beside the Big Egg (160).","notesPages":[478],"id":"glossary-entry-snout-miol-mor","letter":"S"},{"term":"SOBBED (DUBU)","definition":"Dubu the bear cried (\"'Woe, woe, woe!'\") after Axel and Randal were killed (148).","notesPages":[478],"id":"glossary-entry-sobbed-dubu","letter":"S"},{"term":"SOBBING (RACHEL)","definition":"Sound associated with Rachel weeping for her lost children in Ramah (81).","notesPages":[478],"id":"glossary-entry-sobbing-rachel","letter":"S"},{"term":"SOCIETY (ANGELIC)","definition":"The realm or community of angels; Luas was chosen because he would not be greatly missed there (61).","notesPages":[478],"id":"glossary-entry-society-angelic","letter":"S"},{"term":"SOCIETY (SECRET)","definition":"The Kangaroo described as the most secret society ever (83).","notesPages":[478],"id":"glossary-entry-society-secret","letter":"S"},{"term":"SOCIETY (SETS OF)","definition":"Different human social circles in which AMHs moved (26).","notesPages":[479],"id":"glossary-entry-society-sets-of","letter":"S"},{"term":"SOCSOLLABCOMDEM PARTY POTLATCH (SONG)","definition":"Title of a campfire song sung at Heart's Desire Cove (59); refers to Socsollabcomdem Party Potlatch. (Note: \"Socsollabcomdem\" is likely a Lafferty coinage or obscure reference).","notesPages":[479],"id":"glossary-entry-socsollabcomdem-party-potlatch-song","letter":"S"},{"term":"SOFTWARE","definition":"Computer programs; described as \"all easy\" to create for potential AMH-human mating experiments (32).","notesPages":[479],"id":"glossary-entry-software","letter":"S"},{"term":"SOLID HOME (SATRAP'S)","definition":"Satrap Saint Ledger refers to his house (Persimmon Manor) on Tom Dooley's Island as good, solid, spacious, and pleasant (100).","notesPages":[479],"id":"glossary-entry-solid-home-satraps","letter":"S"},{"term":"SOLID LIMESTONE","definition":"The material composing the wall at the end of the Executive Passage (144).","notesPages":[479],"id":"glossary-entry-solid-limestone","letter":"S"},{"term":"SOLOMON (KING)","definition":"King of ancient Israel, son of David; believed by Axel Grindstone to be sleeping yet alive in Abraham's Bosom (11).","notesPages":[479],"id":"glossary-entry-solomon-king","letter":"S"},{"term":"SOLUTION","definition":"Answer to a problem or resolution of a conflict; Machiavelli Giovane states a stable solution will always be arrived at (78); the narrative claims the problem (implied global instability) is solved, though the solution requires revisions before being deemed \"acceptable\" (79).","notesPages":[479],"id":"glossary-entry-solution","letter":"S"},{"term":"SOMALI SHILLINGS (GOLD)","definition":"See GOLD SOMALI SHILLINGS.","notesPages":[479],"id":"glossary-entry-somali-shillings-gold","letter":"S"},{"term":"SOMATIC STATE (OCEANIC METASTASIS)","definition":"The physical condition accompanying the pseudo-dream state of deep diving (134); refers to Oceanic Metastasis.","notesPages":[479],"id":"glossary-entry-somatic-state-oceanic-metastasis","letter":"S"},{"term":"SOMEBODY","definition":"Unspecified person; may protest airliner analogy (41); must have built giant structures (131); invisible Alfred is only a somebody (113); somebody doing killing (125); somebody cast sleep spell (155); somebody ruining mystery (128).","notesPages":[479],"id":"glossary-entry-somebody","letter":"S"},{"term":"SOMNAMBULISTIC ACTIVITIES (DIRECTED)","definition":"Actions performed while asleep but guided towards a specific goal, practiced by Dolophonoi for killing (98).","notesPages":[480],"id":"glossary-entry-somnambulistic-activities-directed","letter":"S"},{"term":"SOMNAMBULISTIC APPARATUS (KANGAROO)","definition":"Description of the Kangaroo organization, highlighting its operation on an unconscious, sleep-walking level (83).","notesPages":[479],"id":"glossary-entry-somnambulistic-apparatus-kangaroo","letter":"S"},{"term":"SOMNAMBULISTIC KILLING","definition":"See KILLING (SLEEP-WALKING).","notesPages":[480],"id":"glossary-entry-somnambulistic-killing","letter":"S"},{"term":"SON (ANSEL'S)","definition":"Axel Albert Grindstone (10, 11, 14, 17, 18).","notesPages":[480],"id":"glossary-entry-son-ansels","letter":"S"},{"term":"SONG (COMPUTER SINGING)","definition":"An Ambulatory Computer sings \"'A sword is hanging o'er your head...'\" at Jack Flannagan's bar (77).","notesPages":[480],"id":"glossary-entry-song-computer-singing","letter":"S"},{"term":"SONG (MOON PEOPLE VAUNT)","definition":"See MOON PEOPLE VAUNT (SONG).","notesPages":[480],"id":"glossary-entry-song-moon-people-vaunt","letter":"S"},{"term":"SONG ('OLD DOGS...')","definition":"See OLD DOGS AND CHILDREN AND WATERMELON WINE (SONG).","notesPages":[480],"id":"glossary-entry-song-old-dogs","letter":"S"},{"term":"SONG (STRUCTO ALLEY MUSIC-HALL)","definition":"Verse epigraph (\"'The Kangaroo who rules the world...'\") for Chapter Eight (78).","notesPages":[480],"id":"glossary-entry-song-structo-alley-music-hall","letter":"S"},{"term":"SONG ('THOUSAND YEARS...')","definition":"See THOUSAND YEARS IS LIKE A DAY (A) (SONG).","notesPages":[480],"id":"glossary-entry-song-thousand-years","letter":"S"},{"term":"SONGS (CAMPFIRE)","definition":"See CAMPFIRE SONGS.","notesPages":[480],"id":"glossary-entry-songs-campfire","letter":"S"},{"term":"SONGS (COMING-OF-AGE)","definition":"Sung by the Nine at their birthday banquet (e.g., \"'Oh, think of us as saint and sage...'\") (146).","notesPages":[480],"id":"glossary-entry-songs-coming-of-age","letter":"S"},{"term":"SONGS (OLD)","definition":"Researched extensively by Inneall (121).","notesPages":[480],"id":"glossary-entry-songs-old","letter":"S"},{"term":"SONGS (SING-A-LONGS)","definition":"Communal songs enjoyed at Heart's Desire Cove (e.g., 'Excitements Hot and Cold Suite') (60).","notesPages":[480],"id":"glossary-entry-songs-sing-a-longs","letter":"S"},{"term":"SONGSTERS","definition":"Singers or composers of songs; will make a great song about the invisible ghost ship legend (121).","notesPages":[480],"id":"glossary-entry-songsters","letter":"S"},{"term":"SONS (AXEL'S BROTHERS)","definition":"Axel Grindstone had three older brothers, husky and substantial (10).","notesPages":[480],"id":"glossary-entry-sons-axels-brothers","letter":"S"},{"term":"SONS (FIRST GENERATION, APES)","definition":"Twelve sons of the initial generation of Unfallen sons were cast into deep sleep, one waking each millennium to serve as conscience (18-19).","notesPages":[480],"id":"glossary-entry-sons-first-generation-apes","letter":"S"},{"term":"SONS OF ANAK","definition":"Giants mentioned in the Old Testament; suggested as possible builders of Lyonesse (106).","notesPages":[481],"id":"glossary-entry-sons-of-anak","letter":"S"},{"term":"SORROW","definition":"Deep distress or sadness; felt by Donatus O'Reily while awaiting hanging (157); experienced by the Dolophonos leaving Lutin's tent (87); encountering sorrow can erode Oceanic Metastasis (150); depicted on Zchold's cenotaph face (150).","notesPages":[481],"id":"glossary-entry-sorrow","letter":"S"},{"term":"SORRY (DONATUS NOT)","definition":"Donatus O'Reily expresses no regret for his hangable offense (118).","notesPages":[481],"id":"glossary-entry-sorry-donatus-not","letter":"S"},{"term":"SORRY (INNEALL)","definition":"Inneall expresses regret for ruining the murder mystery and for the prevalence of lies in current record-keeping (128, 165).","notesPages":[481],"id":"glossary-entry-sorry-inneall","letter":"S"},{"term":"SOUL","definition":"Spiritual or immaterial part of a being; Man composed of body and soul (35); required of thee this night (36); Psyche my soul (43).","notesPages":[481],"id":"glossary-entry-soul","letter":"S"},{"term":"SOUL-WRENCHING SICKNESS","definition":"Lutin's description of her condition, alongside \"most delightful\" (134).","notesPages":[481],"id":"glossary-entry-soul-wrenching-sickness","letter":"S"},{"term":"SOULS (DAMNED)","definition":"Their howling simulated by the calliope on the Flying Dutchman (97).","notesPages":[481],"id":"glossary-entry-souls-damned","letter":"S"},{"term":"SOULS (IN NOSTRILS)","definition":"Donatus O'Reily claims the souls of his nine dead companions reside in their nostrils until his own soul escapes his (157).","notesPages":[481],"id":"glossary-entry-souls-in-nostrils","letter":"S"},{"term":"SOUND","definition":"Vibrations perceived by ear; component track of 'prowls', usually sketchy with background noise (6); produced by rope ladder dragging (152).","notesPages":[481],"id":"glossary-entry-sound","letter":"S"},{"term":"SOUNDING (WHALES)","definition":"Diving deep into the ocean; whales enjoy this but need deep water (106).","notesPages":[481],"id":"glossary-entry-sounding-whales","letter":"S"},{"term":"SOUNDS (CLICK-WHISTLE)","definition":"Vocalizations used by the whale Miol- Mor to communicate (160, 164).","notesPages":[481],"id":"glossary-entry-sounds-click-whistle","letter":"S"},{"term":"SOUNDS (DISTURBING)","definition":"The calliope music recognized as such by the Assassins, prompting investigation (85).","notesPages":[482],"id":"glossary-entry-sounds-disturbing","letter":"S"},{"term":"SOUR-GRASS PARK WEST","definition":"Location in Los Angeles of the Main Waif-arama complex (96).","notesPages":[482],"id":"glossary-entry-sour-grass-park-west","letter":"S"},{"term":"SOURCES (HUMAN, DRAMAS)","definition":"Theatrical traditions (Old Greek Tragedy, Medieval Arabian Comedy, Japanese Noh, Byzantine Intrigue, English Elizabethan, Irish Abbey Lane Plays) influencing Structo Lane dramas (76).","notesPages":[482],"id":"glossary-entry-sources-human-dramas","letter":"S"},{"term":"SOUTH (BIRD MIGRATION)","definition":"Direction migrating birds fly; Swifts/Swallows bi-locate from Nebraska south over Honduras (95).","notesPages":[482],"id":"glossary-entry-south-bird-migration","letter":"S"},{"term":"SOUTH (OCEAN GROWING)","definition":"Primary direction, along with East, of Inneall's Ocean's expansion (55).","notesPages":[482],"id":"glossary-entry-south-ocean-growing","letter":"S"},{"term":"SOUTH WIND","definition":"Talking to humans like that (about hunches) is like talking to the south wind (39).","notesPages":[482],"id":"glossary-entry-south-wind","letter":"S"},{"term":"SOUTHWEST AFRICA","definition":"Location of pompous, beautiful Ostrich Struts, influencing Structo Lane Dramas (76).","notesPages":[482],"id":"glossary-entry-southwest-africa","letter":"S"},{"term":"SPAIN (CID OF)","definition":"Rodrigo Díaz de Vivar (El Cid), hero of Spain, believed by Axel Grindstone to be sleeping undead in Abraham's Bosom (11).","notesPages":[482],"id":"glossary-entry-spain-cid-of","letter":"S"},{"term":"SPARKS OF FIRE (LIVID WHITE)","definition":"Jumped between the Mega Dolophonos and Carcajou when the former touched the latter's shoulder (94).","notesPages":[482],"id":"glossary-entry-sparks-of-fire-livid-white","letter":"S"},{"term":"SPARKS (STRUCK)","definition":"Generated when the hard, flinty minds of Satrap Saint Ledger and Livius Secundus encounter each other (70).","notesPages":[482],"id":"glossary-entry-sparks-struck","letter":"S"},{"term":"SPECIAL ASSASSINS","definition":"See ASSASSINS.","notesPages":[482],"id":"glossary-entry-special-assassins","letter":"S"},{"term":"SPECIAL CASE (ELEPHANT GESTATION)","definition":"In the novel’s elephant lore, the ten-year gestation applies only to a 'Wonder of the World Elephant' (57).","notesPages":[483],"id":"glossary-entry-special-case-elephant-gestation","letter":"S"},{"term":"SPECIAL EXPERIMENTS","definition":"Category including the Lynn-Randal experiment; Serpent's Eggs possibly occur more frequently (one in a thousand) in these (2).","notesPages":[483],"id":"glossary-entry-special-experiments","letter":"S"},{"term":"SPECIAL MOMENTS (KANGAROO)","definition":"Membership in the Kangaroo organization might only occur during specific, significant times (83).","notesPages":[483],"id":"glossary-entry-special-moments-kangaroo","letter":"S"},{"term":"SPECIAL NINETY-NINTH CANNON","definition":"See NINETY-NINTH CANNON (GOLDEN HIND).","notesPages":[483],"id":"glossary-entry-special-ninety-ninth-cannon","letter":"S"},{"term":"SPECIAL WORDS (AXEL'S FATHER LACKS)","definition":"Ansel Grindstone felt there was something else important he wanted to say to his infant son Axel but lacked the words (10).","notesPages":[483],"id":"glossary-entry-special-words-axels-father-lacks","letter":"S"},{"term":"SPECIALITIES (OF THE COVE)","definition":"Unique food items available at Heart's Desire Cove (e.g., Hot Coon Sandwiches, Ocean Catfish, Persimmon Wine, Choc Beer) (58).","notesPages":[483],"id":"glossary-entry-specialities-of-the-cove","letter":"S"},{"term":"SPECIES","definition":"Biological classification; used extensively throughout, referring to humans, Apes, computers, animals, fish, birds, etc. See specific species names.","notesPages":[483],"id":"glossary-entry-species","letter":"S"},{"term":"SPECIES (ARTIFICIAL)","definition":"Entities, at least partly non-biological (like Dolophonoi), whose existence clouds species identification (41).","notesPages":[483],"id":"glossary-entry-species-artificial","letter":"S"},{"term":"SPECIES (AXEL'S APE)","definition":"See APE (AXEL'S...).","notesPages":[483],"id":"glossary-entry-species-axels-ape","letter":"S"},{"term":"SPECIES (DISTINCT, HUMANS)","definition":"Humans traditionally considered a distinct species, now questionable due to artificial entities (41).","notesPages":[483],"id":"glossary-entry-species-distinct-humans","letter":"S"},{"term":"SPECIES (DOLOPHONOS/ASSASSIN)","definition":"See DOLOPHONOS.","notesPages":[483],"id":"glossary-entry-species-dolophonos-assassin","letter":"S"},{"term":"SPECIES (HELOT-)","definition":"Subordinate or enslaved group; Livius Secundus argues humans are now the helot species to Computers (72).","notesPages":[483],"id":"glossary-entry-species-helot","letter":"S"},{"term":"SPECIES (HUMAN)","definition":"See HUMAN SPECIES.","notesPages":[483],"id":"glossary-entry-species-human","letter":"S"},{"term":"SPECIES (OLDER)","definition":"Groups like sea-lice that predate newer forms (163).","notesPages":[483],"id":"glossary-entry-species-older","letter":"S"},{"term":"SPECIES (PARTLY ARTIFICIAL)","definition":"Entities like Dolophonoi whose composition complicates clear species identification (41).","notesPages":[484],"id":"glossary-entry-species-partly-artificial","letter":"S"},{"term":"SPECIES (SPOOKS)","definition":"Inneall does not know the species of her indwelling ghosts (29).","notesPages":[484],"id":"glossary-entry-species-spooks","letter":"S"},{"term":"SPECIES (SUFFICIENT SIZE)","definition":"Criterion for Hyper-Intelligence Scanners; species large enough to have significant brains all occasionally produce \"clear off the scale\" intelligences (55).","notesPages":[484],"id":"glossary-entry-species-sufficient-size","letter":"S"},{"term":"SPECIES (UNFALLEN PEOPLE)","definition":"See UNFALLEN PEOPLE.","notesPages":[484],"id":"glossary-entry-species-unfallen-people","letter":"S"},{"term":"SPECIES (WHO CAN CHANGE)","definition":"Question raised whether Mankind could be surpassed by species do have the capacity to change (40).","notesPages":[484],"id":"glossary-entry-species-who-can-change","letter":"S"},{"term":"SPECK (TREACHERY)","definition":"Tiny amount; Lutin asserts there cannot be even a speck of treachery among the ten in the crows-nest (143).","notesPages":[484],"id":"glossary-entry-speck-treachery","letter":"S"},{"term":"SPECTATORS","definition":"Onlookers at the Carcajou-Luas wrestling match (87).","notesPages":[484],"id":"glossary-entry-spectators","letter":"S"},{"term":"SPECTORS","definition":"Type of ghost or spectral entity that can inhabit empty AMH Computers (28).","notesPages":[484],"id":"glossary-entry-spectors","letter":"S"},{"term":"SPECULATIONS (INTERESTING)","definition":"Livius Secundus wrote interesting speculations on the possible future 'Empire Period' of Ambulatory Computers (71).","notesPages":[484],"id":"glossary-entry-speculations-interesting","letter":"S"},{"term":"SPHERE (PERFECT SHAPE)","definition":"Geometrically symmetrical form; Dubu argues that it will not generate motion because it is already complete (“already there”) (162). This is her metaphysical analogy, not a physical law.","notesPages":[484],"id":"glossary-entry-sphere-perfect-shape","letter":"S"},{"term":"SPHERES (ARISTEROCHEIRIC-)","definition":"See ARISTEROCHEIRIC- SPHERES.","notesPages":[484],"id":"glossary-entry-spheres-aristerocheiric","letter":"S"},{"term":"SPHERES (INTERLOCKING)","definition":"Metaphor used by Inneall for layers of complex, obstructive mysteries (162).","notesPages":[484],"id":"glossary-entry-spheres-interlocking","letter":"S"},{"term":"SPICO","definition":"The novel’s spelling of Spica (Alpha Virginis), Virgo’s brightest star. It becomes the “baleful eye” of the hypnotically perceived Kangaroo (77).","notesPages":[484],"id":"glossary-entry-spico","letter":"S"},{"term":"SPINNING JENNY","definition":"Early spinning machine; cited by an AMH Computer as an example of a machine given an asinine name (\"jenny\") by humans (31).","notesPages":[485],"id":"glossary-entry-spinning-jenny","letter":"S"},{"term":"SPINNING (THREAD)","definition":"Activity performed by the Fate Clotho, drawing life threads from straw (114, 126, 127, 160).","notesPages":[484],"id":"glossary-entry-spinning-thread","letter":"S"},{"term":"SPINNY-RAYS","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[485],"id":"glossary-entry-spinny-rays","letter":"S"},{"term":"SPIRIT (BROKEN)","definition":"Condition of Iris and Shadrack wandering the wasteland after Gregor's suicide (91).","notesPages":[485],"id":"glossary-entry-spirit-broken","letter":"S"},{"term":"SPIRIT (IN OTHER BODIES)","definition":"Atropos remembers Inneall's spirit inhabiting previous forms (126).","notesPages":[485],"id":"glossary-entry-spirit-in-other-bodies","letter":"S"},{"term":"SPIRIT-OF-AEONS PAST","definition":"Type of voice heard by young Axel Grindstone (10).","notesPages":[485],"id":"glossary-entry-spirit-of-aeons-past","letter":"S"},{"term":"SPIRIT OF COOPERATION","definition":"Attitude noted by an AMH Computer as being more prominent now in machine-human relations than earlier antagonism (31).","notesPages":[485],"id":"glossary-entry-spirit-of-cooperation","letter":"S"},{"term":"SPIRIT (OUTGOING, MARINO)","definition":"Marino's friendly and extroverted nature, described as gleaming (60).","notesPages":[485],"id":"glossary-entry-spirit-outgoing-marino","letter":"S"},{"term":"SPIRITS","definition":"Non-corporeal entities; God holds back his Ace Card (11); can inhabit empty AMH Computers (28); evil spirits scared away by calliope (97).","notesPages":[485],"id":"glossary-entry-spirits","letter":"S"},{"term":"SPLAY FEET","definition":"Wide, flat feet characteristic of Axel the Ape, composed of \"flab-flesh\" (42).","notesPages":[485],"id":"glossary-entry-splay-feet","letter":"S"},{"term":"SPLINTER (SHIP'S)","definition":"Tiny fragment; Lanternjaw Lunnigan is covenanted to remain Captain as long as a splinter of the Annabella remains (119).","notesPages":[485],"id":"glossary-entry-splinter-ships","letter":"S"},{"term":"SPOILERS (MOGULS)","definition":"The Moguls who came to India as conquerors and despoilers (92).","notesPages":[485],"id":"glossary-entry-spoilers-moguls","letter":"S"},{"term":"SPOKE (VOICE FROM SKY)","definition":"The thunder-edged voice commanding the guards during the Holy Sleep initiation (68).","notesPages":[485],"id":"glossary-entry-spoke-voice-from-sky","letter":"S"},{"term":"SPOKESMAN (LANTERNJAW)","definition":"Lanternjaw Lunnigan acts as spokesman for the pirate allies during the Council of War (142).","notesPages":[485],"id":"glossary-entry-spokesman-lanternjaw","letter":"S"},{"term":"SPONSORS (EXPERIMENTS)","definition":"Individuals or couples overseeing the various experiments (e.g., Lynn-Randals, Wintergreen-Luna couple, Dorantes-Saleh couple, Gruenbaum- McGregor) (55); referred to as 'parents' (84).","notesPages":[486],"id":"glossary-entry-sponsors-experiments","letter":"S"},{"term":"SPOOK (EVERY SPOOK FOR HIMSELF)","definition":"Principle governing the individualistic, non- shared dreams of the ghosts inhabiting Inneall (29).","notesPages":[486],"id":"glossary-entry-spook-every-spook-for-himself","letter":"S"},{"term":"SPOOK ME (WOLVERENES)","definition":"Lanternjaw Lunnigan admits the wolverenes frighten him (102).","notesPages":[486],"id":"glossary-entry-spook-me-wolverenes","letter":"S"},{"term":"SPOOKS","definition":"Ghosts or spectral entities that can inhabit empty AMH Computers (28); specifically, the seven \"inferior spooks\" residing in Inneall (29).","notesPages":[486],"id":"glossary-entry-spooks","letter":"S"},{"term":"SPORTS (WATER)","definition":"Aquatic recreational activities popular at Heart's Desire Cove (58).","notesPages":[486],"id":"glossary-entry-sports-water","letter":"S"},{"term":"SPOT (CLEAN, RIESIN)","definition":"Location found by Riesin in the Elephant Graveyard where she brings forth the dead Gajah (94).","notesPages":[486],"id":"glossary-entry-spot-clean-riesin","letter":"S"},{"term":"SPOT (TREACHERY)","definition":"Small trace; Lutin asserts there cannot be even a spot of treachery among the ten in the crows-nest (143).","notesPages":[486],"id":"glossary-entry-spot-treachery","letter":"S"},{"term":"SPOT (WATCHING)","definition":"Specific location being observed on the scanner-scope, where Riesin is expected to arrive (93).","notesPages":[486],"id":"glossary-entry-spot-watching","letter":"S"},{"term":"SPOUT (WHALE)","definition":"Visible plume of exhaled air and condensed moisture; in the novel’s fantastic scene, Invisible Alfred summons a whale which gives a \"rousing royal spout\" (110).","notesPages":[486],"id":"glossary-entry-spout-whale","letter":"S"},{"term":"SPRING MECHANISMS (COFFINS)","definition":"Devices the Sea Louse asserts are in the coffin covers, operable from within (166); the epilog’s professed willingness to lie complicates the claim.","notesPages":[486],"id":"glossary-entry-spring-mechanisms-coffins","letter":"S"},{"term":"SPRUNG (AXEL WOKE)","definition":"Axel sprang to his feet immediately upon waking (147).","notesPages":[486],"id":"glossary-entry-sprung-axel-woke","letter":"S"},{"term":"SQUARE DANCING","definition":"Traditional American folk dance; one of the arts abandoned by humans but reinvented by Computers (33).","notesPages":[487],"id":"glossary-entry-square-dancing","letter":"S"},{"term":"SQUARE MARBLE COLUMNS","definition":"Architectural elements being erected by the Whales on the Ocean Bottom (136).","notesPages":[487],"id":"glossary-entry-square-marble-columns","letter":"S"},{"term":"SQUARE MILES (INNEALL'S OCEAN)","definition":"Area covered by Inneall's Ocean, initially several square miles (43), later said by the Sea Louse to cover only about ten thousand square miles in Eastern Oklahoma (166).","notesPages":[487],"id":"glossary-entry-square-miles-innealls-ocean","letter":"S"},{"term":"SQUARE (ORANGE)","definition":"Lord Randal's signature color and geometric shape identified within 'prowls' (6).","notesPages":[486],"id":"glossary-entry-square-orange","letter":"S"},{"term":"SQUARE SMOKE RINGS","definition":"Shape into which an elegant AMH Computer forms its cigar smoke using hidden air jets (30).","notesPages":[487],"id":"glossary-entry-square-smoke-rings","letter":"S"},{"term":"SQUAWLING","definition":"Loud, harsh crying or yelling; heard by the brave interloper from the invisible skeletal pirates overhead (120).","notesPages":[487],"id":"glossary-entry-squawling","letter":"S"},{"term":"SQUEALING (SECRET DELIGHT)","definition":"Sound made by Inneall when revealing the secret of the Executive Passage (144).","notesPages":[487],"id":"glossary-entry-squealing-secret-delight","letter":"S"},{"term":"SQUEAMISH","definition":"Easily disgusted or nauseated; Henryetta claims to be squeamish at the sight of blood (62); also, a human word ('squeam') whose meaning a computer doesn't fully grasp (39).","notesPages":[487],"id":"glossary-entry-squeamish","letter":"S"},{"term":"SQUIDS","definition":"Cephalopods present in Inneall's Ocean (138); squid-skin tarp used by dolphins (106).","notesPages":[487],"id":"glossary-entry-squids","letter":"S"},{"term":"SQUINTY EYES","definition":"Narrowed eyes; characteristic of the mocking crowd watching Alfred, deemed too small to see the 'pleroma' he has drawn (111).","notesPages":[487],"id":"glossary-entry-squinty-eyes","letter":"S"},{"term":"STABLE (EMPRESS ELEPHANTS)","definition":"Quality of dependability and not being given to flightiness, possessed by Empress Elephant mayors (92).","notesPages":[487],"id":"glossary-entry-stable-empress-elephants","letter":"S"},{"term":"STABLE SOLUTION","definition":"A resolution to conflict or disorder that possesses enduring stability; Machiavelli Giovane asserts one will always eventually be arrived at in world affairs (78).","notesPages":[487],"id":"glossary-entry-stable-solution","letter":"S"},{"term":"STAGGERED (RIESIN)","definition":"Moved unsteadily; Riesin staggered after being shot by the Elephant-Gun (91); staggered up the path after laying Gajah down (94).","notesPages":[487],"id":"glossary-entry-staggered-riesin","letter":"S"},{"term":"STALE (NOT GROW)","definition":"The Nine resolve they will not become old, stale, or dim (poem epigraph) (151).","notesPages":[488],"id":"glossary-entry-stale-not-grow","letter":"S"},{"term":"STALKED (GROUP)","definition":"The merged experimental group is still stalked by Dolophonoi-Assassins, under suspicion of containing Serpent's Eggs (127).","notesPages":[488],"id":"glossary-entry-stalked-group","letter":"S"},{"term":"STAND (FOR SOMETHING)","definition":"Carcajou feels, as the only remaining human among the Royal Kids, he ought to represent or uphold something (162).","notesPages":[488],"id":"glossary-entry-stand-for-something","letter":"S"},{"term":"STANDARDS (DERIVED FROM EARLIER AGE)","definition":"Criteria used by some to criticize modern 'prowls', based on values from the pre- postliterate age (8).","notesPages":[488],"id":"glossary-entry-standards-derived-from-earlier-age","letter":"S"},{"term":"STANDBY (DOLOPHONOS)","definition":"A Dolophonos had already been put on standby for the Lynn- Randal case, anticipating a potential Serpent's Egg (2).","notesPages":[488],"id":"glossary-entry-standby-dolophonos","letter":"S"},{"term":"STAR BRIDGE","definition":"Structure referenced in the title of the sing-a-long song Going Home Over The Star Bridge (60).","notesPages":[488],"id":"glossary-entry-star-bridge","letter":"S"},{"term":"STAR (DOG)","definition":"See DOG STAR.","notesPages":[488],"id":"glossary-entry-star-dog","letter":"S"},{"term":"STAR PEOPLE (SONG)","definition":"Title of a campfire song sung at Heart's Desire Cove (59); refers to Star People.","notesPages":[488],"id":"glossary-entry-star-people-song","letter":"S"},{"term":"STAR (RED)","definition":"Comparison for the drop of Quentillius's blood on Henryetta's eyelash (140).","notesPages":[488],"id":"glossary-entry-star-red","letter":"S"},{"term":"STAR (SPICO)","definition":"See SPICO.","notesPages":[488],"id":"glossary-entry-star-spico","letter":"S"},{"term":"STARFISH","definition":"Echinoderms present in Inneall's Ocean (138).","notesPages":[488],"id":"glossary-entry-starfish","letter":"S"},{"term":"STARS","definition":"Celestial bodies; Dog Star Sirius (137); Spica (spelled “Spico” in the novel), Beta Virginis, Gamma Virginis, Delta Virginis (77).","notesPages":[488],"id":"glossary-entry-stars","letter":"S"},{"term":"STASIS (LEADERS IN)","definition":"Condition of suspended animation or undeath, applied to the potential state of Axel, Randal, and Henryetta in their cenotaphs (161).","notesPages":[489],"id":"glossary-entry-stasis-leaders-in","letter":"S"},{"term":"STATE","definition":"Condition or status; dream state (133); middle state (34); natural state (75); post- intellectual state (83); radiant intelligence state (83); raving mad state (91); somatic state (134).","notesPages":[488],"id":"glossary-entry-state","letter":"S"},{"term":"STATE (HYPERACTIVE PSEUDO-DREAM)","definition":"See OCEANIC METASTASIS.","notesPages":[488],"id":"glossary-entry-state-hyperactive-pseudo-dream","letter":"S"},{"term":"STATE (MAN AND)","definition":"The novel cites Jacques Maritain’s Man and the State as “Man and State” and misspells his surname “Maritan” (78).","notesPages":[489],"id":"glossary-entry-state-man-and","letter":"S"},{"term":"STATE (OCEANIC METASTASIS)","definition":"See OCEANIC METASTASIS.","notesPages":[489],"id":"glossary-entry-state-oceanic-metastasis","letter":"S"},{"term":"STATE (POST-INTELLECTUAL)","definition":"See POST-INTELLECTUAL STATE.","notesPages":[489],"id":"glossary-entry-state-post-intellectual","letter":"S"},{"term":"STATE (RADIANT INTELLIGENCE)","definition":"See RADIANT INTELLIGENCE.","notesPages":[489],"id":"glossary-entry-state-radiant-intelligence","letter":"S"},{"term":"STATE (RAVING MAD)","definition":"See RAVING MAD STATE (GREGOR).","notesPages":[489],"id":"glossary-entry-state-raving-mad","letter":"S"},{"term":"STATE (SOMATIC)","definition":"See SOMATIC STATE (OCEANIC METASTASIS).","notesPages":[489],"id":"glossary-entry-state-somatic","letter":"S"},{"term":"STATE (VIOLENTLY MURDERED)","definition":"Condition in which victims were found at Persimmon Manor (128).","notesPages":[489],"id":"glossary-entry-state-violently-murdered","letter":"S"},{"term":"STATIONARY COMPUTERS","definition":"Large, non-mobile computers, contrasted with AMHs; have greater storage capacity but slower decision-making (32).","notesPages":[489],"id":"glossary-entry-stationary-computers","letter":"S"},{"term":"STATIONS (INVISIBLE)","definition":"Locations on the invisible Annabella Saint Ledger where the skeletal crew stand at their posts (121).","notesPages":[489],"id":"glossary-entry-stations-invisible","letter":"S"},{"term":"STATIONS (SKY)","definition":"Positions in the celestial sphere, specifically the twelve constellations of the Zodiac (30); Invisible Alfred claims that the Apostles were these twelve stations (111).","notesPages":[489],"id":"glossary-entry-stations-sky","letter":"S"},{"term":"STATUES (GARGOYLE FACES)","definition":"Limestone formations resembling statues with Gargoyle faces found in Ape Caverns (45).","notesPages":[489],"id":"glossary-entry-statues-gargoyle-faces","letter":"S"},{"term":"STATUES (WOTTO-METAL)","definition":"Made of the unburnable substance wotto metal (97).","notesPages":[489],"id":"glossary-entry-statues-wotto-metal","letter":"S"},{"term":"STATUETTES (WOTTO-METAL)","definition":"Small statues made of wotto metal; Henryetta burns one to demonstrate her power (97).","notesPages":[489],"id":"glossary-entry-statuettes-wotto-metal","letter":"S"},{"term":"STATURE","definition":"Height or physical build (implied); the Unfallen Folks possessed stature full of grace (16).","notesPages":[490],"id":"glossary-entry-stature","letter":"S"},{"term":"STATURES (UNFALLEN FOLKS)","definition":"Plural form referring to the height/build of the Unfallen People (16).","notesPages":[490],"id":"glossary-entry-statures-unfallen-folks","letter":"S"},{"term":"STATUS (OFFICIAL, LOGS)","definition":"Some of Inneall's logs had achieved official recognition before her recording ability was removed (164).","notesPages":[490],"id":"glossary-entry-status-official-logs","letter":"S"},{"term":"STATUS SYMBOL (EXTRADIGITALISM)","definition":"Possessing more than ten fingers (extradigitalism) was researched and considered a status symbol by Inneall (25).","notesPages":[490],"id":"glossary-entry-status-symbol-extradigitalism","letter":"S"},{"term":"STEAK (BEAR)","definition":"Eaten by Lanternjaw Lunnigan's former pirate crew after encountering an Alaskan Brown Bear first mate (103).","notesPages":[490],"id":"glossary-entry-steak-bear","letter":"S"},{"term":"STEAK (TURTLE)","definition":"Food derived from ocean turtles; considered less desirable than other options by Lanternjaw (99).","notesPages":[490],"id":"glossary-entry-steak-turtle","letter":"S"},{"term":"STEAM CALLIOPE","definition":"See CALLIOPE (STEAM).","notesPages":[490],"id":"glossary-entry-steam-calliope","letter":"S"},{"term":"STEAM (WHALE SPOUT)","definition":"Ejected along with water by the whale summoned by Alfred (110).","notesPages":[490],"id":"glossary-entry-steam-whale-spout","letter":"S"},{"term":"STEPPED RECKONER","definition":"Calculating machine invented by Leibnitz in 1671 (25).","notesPages":[490],"id":"glossary-entry-stepped-reckoner","letter":"S"},{"term":"STEPS (SCORE OF, RIESIN)","definition":"Riesin staggered about twenty steps up the path beyond Gajah's body before dying (94).","notesPages":[490],"id":"glossary-entry-steps-score-of-riesin","letter":"S"},{"term":"STEW (PROTEIN-OIL OLIO-)","definition":"See OLIO-STEW (PROTEIN-OIL).","notesPages":[490],"id":"glossary-entry-stew-protein-oil-olio","letter":"S"},{"term":"STICK (CROSSE-STICK)","definition":"See CROSSE-STICK.","notesPages":[490],"id":"glossary-entry-stick-crosse-stick","letter":"S"},{"term":"STICKLEBACKS","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[490],"id":"glossary-entry-sticklebacks","letter":"S"},{"term":"STIGMA (SERPENT'S EGG)","definition":"The mark or classification designating someone as a Serpent's Egg; the Nine may possibly have received this (144).","notesPages":[490],"id":"glossary-entry-stigma-serpents-egg","letter":"S"},{"term":"STILT-WALKING","definition":"Activity performed on poles attached to the feet; one of the arts abandoned by humans but reinvented by Computers (33).","notesPages":[490],"id":"glossary-entry-stilt-walking","letter":"S"},{"term":"STIMULATION","definition":"Incitement to activity or development; AMHs attribute their advancement over stationary computers to greater stimulation from mobility and interaction (7, 32).","notesPages":[491],"id":"glossary-entry-stimulation","letter":"S"},{"term":"STING (BEES)","definition":"The bees loose in the midship hold will sting anyone who enters (100).","notesPages":[491],"id":"glossary-entry-sting-bees","letter":"S"},{"term":"STINK (WOLVERENE)","definition":"Foul odor complementing the brimstone smell during the Carcajou- Luas wrestling match (87). (Note: Text reads \"stench\").","notesPages":[491],"id":"glossary-entry-stink-wolverene","letter":"S"},{"term":"STOMACH (WHALE'S)","definition":"Digestive organ in which Invisible Alfred claims to have spent three days; he attributes his skin’s whiteness to its digestive juices (109).","notesPages":[491],"id":"glossary-entry-stomach-whales","letter":"S"},{"term":"STOMIAS BOA","definition":"Species of deep-sea fish (likely viperfish relative) flocking to Inneall's Ocean (138); refers to Stomias boa.","notesPages":[491],"id":"glossary-entry-stomias-boa","letter":"S"},{"term":"STONE BRIDGE","definition":"Structure built by the Unfallen Ones across a torrent; graceful as an arrow, made of five colors of stone key-locked without mortar (15).","notesPages":[491],"id":"glossary-entry-stone-bridge","letter":"S"},{"term":"STONE CENOTAPHS","definition":"See CENOTAPHS.","notesPages":[491],"id":"glossary-entry-stone-cenotaphs","letter":"S"},{"term":"STONE COVER (CENOTAPH)","definition":"The lid sealing a cenotaph (150).","notesPages":[491],"id":"glossary-entry-stone-cover-cenotaph","letter":"S"},{"term":"STONE DEATH (RANDAL)","definition":"The appearance of Lord Randal depicted in high relief on his cenotaph lid, grinning in ruddy, happy death (149).","notesPages":[491],"id":"glossary-entry-stone-death-randal","letter":"S"},{"term":"STONE LID","definition":"Cover for a cenotaph (148, 149).","notesPages":[491],"id":"glossary-entry-stone-lid","letter":"S"},{"term":"STONE-MASTER APES","definition":"Alternative name used by Ethiopians and Arabians for the Unfallen People, referencing their mastery of stone work (13).","notesPages":[492],"id":"glossary-entry-stone-master-apes","letter":"S"},{"term":"STONE-MASTERS (EUROPEAN)","definition":"Nine expert craftsmen from Europe who supposedly learned advanced techniques from the Unfallen Masters in Second Eden (13).","notesPages":[492],"id":"glossary-entry-stone-masters-european","letter":"S"},{"term":"STONE (OCEAN)","definition":"See OCEAN STONE.","notesPages":[491],"id":"glossary-entry-stone-ocean","letter":"S"},{"term":"STONE PILLARS","definition":"Large columns of marble and granite used in the Whales' underwater constructions, sculpted by sea-lice (138).","notesPages":[491],"id":"glossary-entry-stone-pillars","letter":"S"},{"term":"STONE RISERS (STAIRCASES)","definition":"The vertical parts of steps; noted as being thirty feet high in the huge staircases of the underwater City of Lyonesse (105).","notesPages":[491],"id":"glossary-entry-stone-risers-staircases","letter":"S"},{"term":"STONE ROOF","definition":"Ceiling of the cenaculum in the American Ape Caverns (45); the room resembles the one in Second Eden.","notesPages":[492],"id":"glossary-entry-stone-roof","letter":"S"},{"term":"STONE (SLABS OF)","definition":"Flat pieces used as quarries of the Ocean (131).","notesPages":[491],"id":"glossary-entry-stone-slabs-of","letter":"S"},{"term":"STONE-WORK","definition":"Craft involving shaping stone; Unfallen Ones are masters (15); taught to European masters (13); seen in Angkor Wat (132).","notesPages":[492],"id":"glossary-entry-stone-work","letter":"S"},{"term":"STONED TO DEATH","definition":"Method of execution by pelting with stones; arranged for Hieronymous Zchold on Tom Dooley's Island (122).","notesPages":[492],"id":"glossary-entry-stoned-to-death","letter":"S"},{"term":"STONERS (PROFESSIONAL)","definition":"Individuals skilled in carrying out executions by stoning; begin the stoning of Zchold (158).","notesPages":[492],"id":"glossary-entry-stoners-professional","letter":"S"},{"term":"STONES","definition":"Rocks or pieces of rock; used in Whale constructions (132, 137, 138); aligned in Whale Temple-City (137); Ocean Stones used by Whales for runic writing (131); used for stoning Zchold (158).","notesPages":[492],"id":"glossary-entry-stones","letter":"S"},{"term":"STONES (BIG, SEA-LICE SCULPTING)","definition":"Large stones used by sea-lice as material for sculpting faces and figures (138).","notesPages":[492],"id":"glossary-entry-stones-big-sea-lice-sculpting","letter":"S"},{"term":"STONES (GIANT)","definition":"See GIANT STONES.","notesPages":[492],"id":"glossary-entry-stones-giant","letter":"S"},{"term":"STONES (GREAT HEWN)","definition":"Large, shaped stones found in the Whale Graveyard (132).","notesPages":[492],"id":"glossary-entry-stones-great-hewn","letter":"S"},{"term":"STONES (LIMESTONE WALL)","definition":"Implied stone construction of the wall leading to the Cenaculum (144).","notesPages":[492],"id":"glossary-entry-stones-limestone-wall","letter":"S"},{"term":"STONES (MONUMENTAL)","definition":"Large stones used for monuments, found in Whale Graveyard (132).","notesPages":[492],"id":"glossary-entry-stones-monumental","letter":"S"},{"term":"STONES (OCEAN)","definition":"Stones on the ocean floor used by Whales for inscribing the first runic alphabet (131).","notesPages":[492],"id":"glossary-entry-stones-ocean","letter":"S"},{"term":"STONES (WAVERING)","definition":"Appearance of the stones of Angkor Wat, covered in ocean-moss (132).","notesPages":[492],"id":"glossary-entry-stones-wavering","letter":"S"},{"term":"STONING-DEATH (ZCHOLD)","definition":"Zchold's manner of execution (158).","notesPages":[493],"id":"glossary-entry-stoning-death-zchold","letter":"S"},{"term":"STONING (ZCHOLD)","definition":"Execution of Hieronymous Zchold by pelting with stones, overseen by officials and joined by onlookers (152, 158, 159).","notesPages":[493],"id":"glossary-entry-stoning-zchold","letter":"S"},{"term":"STOP PROTESTING (INNEALL)","definition":"Command given to Inneall by the sea-lice via wall writing (164).","notesPages":[493],"id":"glossary-entry-stop-protesting-inneall","letter":"S"},{"term":"STORAGE CAPACITY","definition":"Ability to retain data; AMHs have much less than stationary computers, but this is deemed overestimated in importance (26, 32).","notesPages":[493],"id":"glossary-entry-storage-capacity","letter":"S"},{"term":"STORED PROGRAMS","definition":"Concept associated with Von Neumann in computer history (25).","notesPages":[493],"id":"glossary-entry-stored-programs","letter":"S"},{"term":"STORES (OF KNOWLEDGE)","definition":"Dubu claims three separate stores of total knowledge exist in three lobes of her brain (75).","notesPages":[493],"id":"glossary-entry-stores-of-knowledge","letter":"S"},{"term":"STORES (SHIP'S)","definition":"See SHIP'S STORES.","notesPages":[493],"id":"glossary-entry-stores-ships","letter":"S"},{"term":"STORIES (ANIMAL-AND-BIRD)","definition":"See ANIMAL-AND-BIRD STORIES.","notesPages":[493],"id":"glossary-entry-stories-animal-and-bird","letter":"S"},{"term":"STORIES (MYSTERY)","definition":"See MYSTERY STORIES.","notesPages":[493],"id":"glossary-entry-stories-mystery","letter":"S"},{"term":"STORY (INNEALL'S)","definition":"The narrative log kept by Inneall, criticized by novelty-seekers for lacking a real ending (166).","notesPages":[493],"id":"glossary-entry-story-innealls","letter":"S"},{"term":"STORY (MYSTERY)","definition":"See MYSTERY STORY.","notesPages":[493],"id":"glossary-entry-story-mystery","letter":"S"},{"term":"STOWAWAY (INVISIBLE ALFRED)","definition":"Alfred's status aboard the Annabella Saint Ledger, having emerged from one of the paint drums (97, 113).","notesPages":[493],"id":"glossary-entry-stowaway-invisible-alfred","letter":"S"},{"term":"STRAIGHT-LINE HISTORY","definition":"Linear, sequential historical narrative; explicitly not the type being presented regarding computers (24).","notesPages":[493],"id":"glossary-entry-straight-line-history","letter":"S"},{"term":"STRAIGHT-LINEDNESS","definition":"Quality of being linear; computers do not share the human preference for it (24).","notesPages":[493],"id":"glossary-entry-straight-linedness","letter":"S"},{"term":"STRAIGHT LINES","definition":"Geometric form preferred by humans but considered too narrow by computers (24).","notesPages":[493],"id":"glossary-entry-straight-lines","letter":"S"},{"term":"STRANGE BELIEFS (AXEL'S)","definition":"Axel Grindstone’s unconventional views (recent creation, sleeping patriarchs, and Second Eden), which the narrator declares true within the novel (11).","notesPages":[494],"id":"glossary-entry-strange-beliefs-axels","letter":"S"},{"term":"STRANGE COMPULSION","definition":"The mysterious force compelling Gregor McGregor to will the shooting of the Elephants against his conscious desire (90).","notesPages":[494],"id":"glossary-entry-strange-compulsion","letter":"S"},{"term":"STRANGE COMPUTER FACES","definition":"Unusual visages, alongside human, animal, and god faces, emerging from the stones sculpted by sea-lice (138).","notesPages":[494],"id":"glossary-entry-strange-computer-faces","letter":"S"},{"term":"STRANGE HAPPENINGS (BIG BOOK OF)","definition":"See BIG BOOK OF STRANGE HAPPENINGS.","notesPages":[494],"id":"glossary-entry-strange-happenings-big-book-of","letter":"S"},{"term":"STRANGE LAND (MECHANICS/BIOLOGY)","definition":"The interface region between mechanics and biology where coincidences, like mechanical horses resembling biological ones, happen often (31).","notesPages":[494],"id":"glossary-entry-strange-land-mechanics-biology","letter":"S"},{"term":"STRANGE PERSONS (IN CLIFFS)","definition":"Unidentified individuals nesting in the cliffs who attempt to kill both Carcajou and Luas after their wrestling match (account from Book of Jasher) (88).","notesPages":[494],"id":"glossary-entry-strange-persons-in-cliffs","letter":"S"},{"term":"STRANGENESS (TOWERING)","definition":"Quality contributing to the holiness of Archangels, exemplified by their hypothesized immense and distorted features (17).","notesPages":[494],"id":"glossary-entry-strangeness-towering","letter":"S"},{"term":"STRATA (LIMESTONE)","definition":"Layers of limestone rock at the base of Tom Dooley's Island that slid out in sheets (163).","notesPages":[494],"id":"glossary-entry-strata-limestone","letter":"S"},{"term":"STRATEGIC BALCONIES","definition":"Elevated platforms overlooking vast plazas, one of three great places for addressing crowds; unavailable to poor prophets like Alfred or Christus (109).","notesPages":[494],"id":"glossary-entry-strategic-balconies","letter":"S"},{"term":"STRAW","definition":"Dried stalks of grain; covers the floor of the horrible little room where the Three Fates spin, measure, and cut life threads (103, 114, 126, 127).","notesPages":[494],"id":"glossary-entry-straw","letter":"S"},{"term":"STREAMS","definition":"Small bodies of flowing water; present in The Three's habitat (3); nearby streams flowing into Inneall's Ocean provide fresh water near their mouths (119).","notesPages":[495],"id":"glossary-entry-streams","letter":"S"},{"term":"STREET (INTRAMUROS/EMBARCADERO)","definition":"Thoroughfare in Manila/San Francisco involved in the bi-location case (95).","notesPages":[495],"id":"glossary-entry-street-intramuros-embarcadero","letter":"S"},{"term":"STREETS","definition":"Paved roads in towns or cities; swallowed up by Inneall's Ocean (27); broken streets in human-mayor town (92); streets made of great hewn stones in Whale Graveyard (132).","notesPages":[495],"id":"glossary-entry-streets","letter":"S"},{"term":"STRENGTH","definition":"Physical power; possessed by Apes (18, 21), Man (34).","notesPages":[495],"id":"glossary-entry-strength","letter":"S"},{"term":"STRENGTH-REINFORCERS (ELECTRONIC)","definition":"Devices likely implanted in Dolophonoi hands, arms, and legs to enhance physical power (50).","notesPages":[495],"id":"glossary-entry-strength-reinforcers-electronic","letter":"S"},{"term":"STRENGTH (THE THREE)","definition":"Power generated by their closeness (9).","notesPages":[495],"id":"glossary-entry-strength-the-three","letter":"S"},{"term":"STRENUOUS GAME","definition":"Activity requiring exertion; Lutin does not get out of breath during strenuous games like lacrosse (62).","notesPages":[495],"id":"glossary-entry-strenuous-game","letter":"S"},{"term":"STRETCH OUT (BRAIN CAPACITY)","definition":"Humans seem to lack the capacity to utilize the full potential of their brains (40).","notesPages":[495],"id":"glossary-entry-stretch-out-brain-capacity","letter":"S"},{"term":"STRICT ACCURACY (ZODIAC)","definition":"In precise astronomical terms, some constellations shown by Alfred should have been below the horizon (111).","notesPages":[495],"id":"glossary-entry-strict-accuracy-zodiac","letter":"S"},{"term":"STRIKING THEORIES","definition":"Notable or compelling hypotheses weighed by Axel Grindstone (12).","notesPages":[495],"id":"glossary-entry-striking-theories","letter":"S"},{"term":"STRIP PITS","definition":"Areas left after surface mining; located on the city's northeast corner, beautified with ornamental trees, site where Inneall began creating her Ocean (24, 91).","notesPages":[495],"id":"glossary-entry-strip-pits","letter":"S"},{"term":"STROKE OF GENIUS (ALFRED'S EYES)","definition":"The idea of Invisible Alfred being visible only by his eyes (and mouth when open) was brilliant, though weakened by his having weak eyes (110).","notesPages":[495],"id":"glossary-entry-stroke-of-genius-alfreds-eyes","letter":"S"},{"term":"STRONG BODY (MAN)","definition":"Attribute possessed by Mankind upon first appearance (34).","notesPages":[495],"id":"glossary-entry-strong-body-man","letter":"S"},{"term":"STRONG-NOSED ARYAN TYPE","definition":"Physical description of the Asiatic man employed by Satrap in the Himalayas (94).","notesPages":[496],"id":"glossary-entry-strong-nosed-aryan-type","letter":"S"},{"term":"STRONGNESS (ANGELIC WILL)","definition":"Term the narration expressly says does not apply to angelic will, any more than “weakness” does (61).","notesPages":[496],"id":"glossary-entry-strongness-angelic-will","letter":"S"},{"term":"STRUCTO ALLEY","definition":"Location where the majority of eccentric male AMHs and eccentric male humans congregate (69). See also STRUCTO LANE.","notesPages":[496],"id":"glossary-entry-structo-alley","letter":"S"},{"term":"STRUCTO ALLEY MUSIC-HALL SONG","definition":"Source of the verse epigraph (\"'The Kangaroo who rules the world...'\") for Chapter Eight (78).","notesPages":[496],"id":"glossary-entry-structo-alley-music-hall-song","letter":"S"},{"term":"STRUCTO LANE","definition":"A \"funny short block\" enclave known as 'The Last Refuge of Cranky Bachelors', inhabited by maverick Ambulatory Computers (many eccentric and male) and some eccentric humans (9, 69-70); location of Inneall's designated father's penthouse (52), the antique shop (85, 97), and the condominium shared by Satrap, Livius, and Felix (70, 98); site of avant-garde theatre (76); shaken by the howling wolverenes (102); one route out of Ape Caverns (148); refers to Structo Lane.","notesPages":[496],"id":"glossary-entry-structo-lane","letter":"S"},{"term":"STRUCTURAL MODIFICATIONS","definition":"Changes to physical structures effected by computers (27).","notesPages":[496],"id":"glossary-entry-structural-modifications","letter":"S"},{"term":"STRUCTURES (GIANT)","definition":"Massive underwater constructions whose 9000-year history is claimed by the novel’s purported Archeology Today excerpt (131); being built by Whales (106, 137).","notesPages":[496],"id":"glossary-entry-structures-giant","letter":"S"},{"term":"STRUCTURES (MEGALITHIC)","definition":"Large stone constructions built by Whales underwater, potential refuge for the Nine (119).","notesPages":[496],"id":"glossary-entry-structures-megalithic","letter":"S"},{"term":"STRUGGLE (TITANS')","definition":"Earth-shaking wrestling match between two Titans (88).","notesPages":[496],"id":"glossary-entry-struggle-titans","letter":"S"},{"term":"STUBBORN REMNANT (CRANKY PEOPLE)","definition":"Persistent group of cranky individuals who passed themselves off as AMHs to gain refuge in Structo Lane (69).","notesPages":[496],"id":"glossary-entry-stubborn-remnant-cranky-people","letter":"S"},{"term":"STUDENTS OF HUMAN AFFAIRS","definition":"Scholars surprised by the potential evidenced in Neanderthal and Cro-Magnon remains (40).","notesPages":[496],"id":"glossary-entry-students-of-human-affairs","letter":"S"},{"term":"STUDIOS (APES')","definition":"Workshops or creative spaces located within Ape Alley (45).","notesPages":[496],"id":"glossary-entry-studios-apes","letter":"S"},{"term":"STUDY (DEAD APE)","definition":"Scientists lament never having had even one dead Axel's Ape body to study (161).","notesPages":[497],"id":"glossary-entry-study-dead-ape","letter":"S"},{"term":"STUNNED (ALL)","definition":"Reaction of the Nine and Lazar upon Henryetta reading the name \"Invisible Alfred\" from the knuckle-bone (149).","notesPages":[497],"id":"glossary-entry-stunned-all","letter":"S"},{"term":"STUNNING (SKY DISPLAY)","definition":"Initial impression created by Invisible Alfred's celestial cartoon apparitions, before their poor quality became apparent (111).","notesPages":[497],"id":"glossary-entry-stunning-sky-display","letter":"S"},{"term":"STUPID (ASININE)","definition":"An ordinary sense of “asinine” that the AMH speaker rejects in favor of its literal association with asses (31).","notesPages":[497],"id":"glossary-entry-stupid-asinine","letter":"S"},{"term":"STYLIZED (FUTURE)","definition":"Quality attributed to the future filling Structo Lane in the poem epigraph (67).","notesPages":[497],"id":"glossary-entry-stylized-future","letter":"S"},{"term":"STYLIZED (PROWLS)","definition":"Characteristic manner of the media format 'prowls' (8).","notesPages":[497],"id":"glossary-entry-stylized-prowls","letter":"S"},{"term":"SUB-ATOMIC PARTICLES","definition":"Fundamental components of matter; included in the comprehensive scope of The Life Affair weaving (74).","notesPages":[497],"id":"glossary-entry-sub-atomic-particles","letter":"S"},{"term":"SUB-TEENAGERS","definition":"Jasper Junkins' assessment of the contemporary human condition: \"'We are all sub-teenagers now'\" (8).","notesPages":[497],"id":"glossary-entry-sub-teenagers","letter":"S"},{"term":"SUBJECT (TO ASSASSINATION)","definition":"The \"special ones\" among the Nine are subject to assassination upon leaving the Cenaculum (144).","notesPages":[497],"id":"glossary-entry-subject-to-assassination","letter":"S"},{"term":"SUBJECTIVE APPEARANCES (SKY)","definition":"The possibly hallucinatory or individually perceived nature of the Kangaroo constellation seen in the sky (77).","notesPages":[497],"id":"glossary-entry-subjective-appearances-sky","letter":"S"},{"term":"SUBJECTS (INSTRUCTION)","definition":"Mathematics and many other subjects taught by the Unfallen Ones (15).","notesPages":[497],"id":"glossary-entry-subjects-instruction","letter":"S"},{"term":"SUBJECTS (RESEARCHED)","definition":"Inneall has researched over a million subjects (121).","notesPages":[497],"id":"glossary-entry-subjects-researched","letter":"S"},{"term":"SUBJECTS (TO MAN)","definition":"Livius Secundus refutes Satrap's implication that AMHs are helots or subjects to man (72).","notesPages":[497],"id":"glossary-entry-subjects-to-man","letter":"S"},{"term":"SUBLIMINAL (VISION)","definition":"Perception below the threshold of conscious awareness; cartoon characters in 'prowls' mostly perceived subliminally (6).","notesPages":[498],"id":"glossary-entry-subliminal-vision","letter":"S"},{"term":"SUBSTANCE (OF MANKIND)","definition":"The essential core or nature; an AMH Computer claims the subject of Mankind lacks substance and \"meat\" (38).","notesPages":[498],"id":"glossary-entry-substance-of-mankind","letter":"S"},{"term":"SUBSTANCE (WOTTO-METAL)","definition":"The toughest substance known, used by Inneall to reinforce life threads (127).","notesPages":[498],"id":"glossary-entry-substance-wotto-metal","letter":"S"},{"term":"SUBSTANTIAL PERIODS (RESERVE)","definition":"Long durations during which elements contributing to the 'Enlargement of the World' have been held back (128).","notesPages":[498],"id":"glossary-entry-substantial-periods-reserve","letter":"S"},{"term":"SUBTLE MENTALITY (HENRYETTA'S)","definition":"Henryetta's refined or cunning intellect, used to start fires remotely (97).","notesPages":[498],"id":"glossary-entry-subtle-mentality-henryettas","letter":"S"},{"term":"SUBTRACT (FROM BRILLIANCE)","definition":"Livius Secundus's lack of historical sense did not detract from his brilliance (71).","notesPages":[498],"id":"glossary-entry-subtract-from-brilliance","letter":"S"},{"term":"SUCCESS","definition":"Achievement of a goal; attributed to the complexity of future AMH reproduction methods (33).","notesPages":[498],"id":"glossary-entry-success","letter":"S"},{"term":"SUCCESSFUL LIVY","definition":"Potential meaning ('Favorable Livy' or 'Successful Livy') of the name Livius Secundus (70).","notesPages":[498],"id":"glossary-entry-successful-livy","letter":"S"},{"term":"SUCCESSOR (SEA-LOUSE)","definition":"The Sea Louse claims a slight role as successor to Inneall as logger (166).","notesPages":[498],"id":"glossary-entry-successor-sea-louse","letter":"S"},{"term":"SUCCESSORS (TO MAN)","definition":"According to the Sea Louse, God promised neither Apes nor Whales would be successors, nor that Man would have no successor (166).","notesPages":[498],"id":"glossary-entry-successors-to-man","letter":"S"},{"term":"SUCKERS (FISH)","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[498],"id":"glossary-entry-suckers-fish","letter":"S"},{"term":"SUDDENLY (DOLOPHONOS SPEAKS)","definition":"The Dolophonos speaks harshly and suddenly to Lutin (87).","notesPages":[498],"id":"glossary-entry-suddenly-dolophonos-speaks","letter":"S"},{"term":"SUDDENLY (WRESTLING STARTS)","definition":"The pyrotechnic-like wrestling match between Carcajou and Luas began suddenly (87).","notesPages":[498],"id":"glossary-entry-suddenly-wrestling-starts","letter":"S"},{"term":"SUMMER","definition":"Season between spring and autumn; departed as observed by De Quincey (132); time when heat is terrible in hills around Second Eden (16); Honor reigned as cultural indicator that summer (117).","notesPages":[499],"id":"glossary-entry-summer","letter":"S"},{"term":"SUMMER (END OF)","definition":"See END OF SUMMER.","notesPages":[499],"id":"glossary-entry-summer-end-of","letter":"S"},{"term":"SUMMERSET","definition":"The final three days of the End of Summer (57, 116, 117, 118, 119, 140, 141, 146, 151, 157). See also THREE DAYS OF SUMMERSET.","notesPages":[499],"id":"glossary-entry-summerset","letter":"S"},{"term":"SUMMERTIME (LEFTOVER BOUGHS)","definition":"Remnants of summer vegetation burned in the End- of-Summer bonfires (59).","notesPages":[499],"id":"glossary-entry-summertime-leftover-boughs","letter":"S"},{"term":"SUN","definition":"Star providing light and heat; seemed queer, dim, and garish at Heart's Desire Cove as its power was diverted by Inneall (59); dimmed by Alfred to reveal celestial signs (111); sun warms Wollaston Island late (118); rises after the Kangaroo constellation disappears (77).","notesPages":[499],"id":"glossary-entry-sun","letter":"S"},{"term":"SUN (END-OF-SUMMER)","definition":"Possessed a queer, dim, garish quality during the final days (59).","notesPages":[499],"id":"glossary-entry-sun-end-of-summer","letter":"S"},{"term":"SUN (WOMAN CLOTHED IN)","definition":"Apocalyptic image referenced (35).","notesPages":[499],"id":"glossary-entry-sun-woman-clothed-in","letter":"S"},{"term":"SUNDOWN","definition":"Time sun sets; Axel's group reaches cliff crest at sundown (16).","notesPages":[499],"id":"glossary-entry-sundown","letter":"S"},{"term":"SUNLIT (OCEAN DEPTH)","definition":"The Ocean Depth appeared gloriously sunlit when viewed through Metastastic eyes (136).","notesPages":[499],"id":"glossary-entry-sunlit-ocean-depth","letter":"S"},{"term":"SUNNY DAYS","definition":"Times when the almost-invisible government (Kangaroo) is hardly noticed (80).","notesPages":[499],"id":"glossary-entry-sunny-days","letter":"S"},{"term":"SUNSHINE","definition":"Direct sunlight; colors hidden in sunshine revealed by Sidewalk Cafe umbrellas (58); Inneall goes up into the sunshine of Top Deck (114); a condition in which the painted ship can hide; the paint must be applied in darkness for full effect (104).","notesPages":[499],"id":"glossary-entry-sunshine","letter":"S"},{"term":"SUPER-INTELLIGENT GUESTS","definition":"The highly intelligent individuals at Persimmon Manor (Dubu, Inneall, etc.) who ironically fail to solve the murder mystery (157).","notesPages":[499],"id":"glossary-entry-super-intelligent-guests","letter":"S"},{"term":"SUPER-LUSH PENTHOUSE","definition":"Luxurious dwelling of Inneall's designated father in Structo Lane (52).","notesPages":[499],"id":"glossary-entry-super-lush-penthouse","letter":"S"},{"term":"SUPERHUMAN","definition":"Exceeding normal human capacity; the impersonal mechanism of the State will become superhuman when its vicious idea develops (78).","notesPages":[500],"id":"glossary-entry-superhuman","letter":"S"},{"term":"SUPERIOR ANIMALS","definition":"Category of animals, few in number, included in the Kangaroo's loosely-construed membership (80).","notesPages":[500],"id":"glossary-entry-superior-animals","letter":"S"},{"term":"SUPERIOR COMPUTERS","definition":"More intricate and intelligent computers subject to scanning by lesser kindred (82).","notesPages":[500],"id":"glossary-entry-superior-computers","letter":"S"},{"term":"SUPERIOR PIRATE (SEBASTIAN)","definition":"Lord Randal calls Sebastian Lazar the only really superior pirate left to accompany them, since Lanternjaw must remain in the crows-nest and Quentillius is dead (145).","notesPages":[500],"id":"glossary-entry-superior-pirate-sebastian","letter":"S"},{"term":"SUPERIOR SCANNER","definition":"Higher-level scanning device to which neighborhood scanners report, e.g., howling about the Undocumented Mega Human (88).","notesPages":[500],"id":"glossary-entry-superior-scanner","letter":"S"},{"term":"SUPERIOR SPOOKS","definition":"Ghosts considered higher quality than the \"inferior\" ones inhabiting Inneall; better housed elsewhere (29).","notesPages":[500],"id":"glossary-entry-superior-spooks","letter":"S"},{"term":"SUPERNATURAL?","definition":"Question raised regarding the possibly non- natural element added to the waterfalls in The Three's habitat (3).","notesPages":[500],"id":"glossary-entry-supernatural","letter":"S"},{"term":"SUPERSTITION","definition":"Belief without rational basis; predicting futures of AMHs would be superstition (30); belief that asking questions about Dolophonoi marks one as a victim (82).","notesPages":[500],"id":"glossary-entry-superstition","letter":"S"},{"term":"SUPPLANTED (BABIES)","definition":"The three baby pythons fostered by the Fates are described by Inneall as “supplanted” by something she cannot identify, following the mysterious appearance of the Big Egg (160).","notesPages":[500],"id":"glossary-entry-supplanted-babies","letter":"S"},{"term":"SUPPLIES (SHIP'S)","definition":"Provisions and stores necessary for a voyage (103).","notesPages":[500],"id":"glossary-entry-supplies-ships","letter":"S"},{"term":"SUPPORT SYSTEM (INTERLOCKING)","definition":"The quasi-natural structural foundation of The Three's contrived habitat (3).","notesPages":[500],"id":"glossary-entry-support-system-interlocking","letter":"S"},{"term":"SUPPORT SYSTEMS (MOON)","definition":"Elaborate life-support required for humans (but not Computers) to live on the Moon (59).","notesPages":[500],"id":"glossary-entry-support-systems-moon","letter":"S"},{"term":"SUPPOSED (SEMI-PRIVATE)","definition":"The intended status of the executions on Tom Dooley's Island (152).","notesPages":[501],"id":"glossary-entry-supposed-semi-private","letter":"S"},{"term":"SUPPOSED (TO BE DOING HERE)","definition":"Question raised by Felix about their purpose (73).","notesPages":[500],"id":"glossary-entry-supposed-to-be-doing-here","letter":"S"},{"term":"SUPPOSED (TO DRINK RUM)","definition":"Inneall's directive based on pirate lore (99).","notesPages":[501],"id":"glossary-entry-supposed-to-drink-rum","letter":"S"},{"term":"SUPPURATION","definition":"Formation or discharge of pus; treated with bilge- water tonic aboard the Annabella (100).","notesPages":[501],"id":"glossary-entry-suppuration","letter":"S"},{"term":"SUPRA-WORLD FELLOWSHIP","definition":"The shared elevated social reality and consensus quality uniting the thirty-two carry-over guests at Persimmon Manor (116).","notesPages":[501],"id":"glossary-entry-supra-world-fellowship","letter":"S"},{"term":"SUPREME HEAD (KANGAROO)","definition":"See HEAD (SUPREME HEAD OF THE KANGAROO).","notesPages":[501],"id":"glossary-entry-supreme-head-kangaroo","letter":"S"},{"term":"SUPREME PEOPLE","definition":"Old ruling class (\"regular people\") all murdered on false charge of being unfeeling (6).","notesPages":[501],"id":"glossary-entry-supreme-people","letter":"S"},{"term":"SURFACE (GROUND)","definition":"Under the surface where experimental truffles grow (4).","notesPages":[501],"id":"glossary-entry-surface-ground","letter":"S"},{"term":"SURFACE (OCEAN)","definition":"See OCEAN SURFACE.","notesPages":[501],"id":"glossary-entry-surface-ocean","letter":"S"},{"term":"SURFACE (OCEAN FLOOR)","definition":"Destination of the returning seven richest men (135).","notesPages":[501],"id":"glossary-entry-surface-ocean-floor","letter":"S"},{"term":"SURFACE (WATER)","definition":"Rocked and shaken by gathering wrath (132).","notesPages":[501],"id":"glossary-entry-surface-water","letter":"S"},{"term":"SURROGATE GRANDFATHER (SATRAP)","definition":"See SATRAP SAINT LEDGER.","notesPages":[501],"id":"glossary-entry-surrogate-grandfather-satrap","letter":"S"},{"term":"Suryavarman II","definition":"Twelfth-century Khmer king credited with erecting the Temple of Angkor Wat; the novel’s purported Viet-Nam Diary asks whether his name means 'King of Whales' (132), which should not be treated as a verified etymology.","notesPages":[501],"id":"glossary-entry-suryavarman-ii","letter":"S"},{"term":"SUSPECT (PRIME)","definition":"See PRIME SUSPECT.","notesPages":[501],"id":"glossary-entry-suspect-prime","letter":"S"},{"term":"SUSPECTED (HENRYETTA)","definition":"Believed to be responsible for burning a city (130).","notesPages":[501],"id":"glossary-entry-suspected-henryetta","letter":"S"},{"term":"SUSPICION (SERPENT'S EGG)","definition":"The group remains under suspicion of containing Serpent's Eggs (127).","notesPages":[501],"id":"glossary-entry-suspicion-serpents-egg","letter":"S"},{"term":"SWAHILI","definition":"East African language studied by Axel Grindstone (11); understood and potentially spoken by the Unfallen Ones (15).","notesPages":[502],"id":"glossary-entry-swahili","letter":"S"},{"term":"SWALLOW (BIRD)","definition":"Migratory bird, known for being a deep daydreamer, capable of bi- locating between Nebraska and Honduras (95).","notesPages":[502],"id":"glossary-entry-swallow-bird","letter":"S"},{"term":"SWALLOWED UP (ROADS ETC.)","definition":"Action of the expanding Inneall's Ocean consuming roads, streets, houses, and buildings (27).","notesPages":[502],"id":"glossary-entry-swallowed-up-roads-etc","letter":"S"},{"term":"SWARMING (IDEAS)","definition":"Overwhelming influx of thoughts experienced by Dubu after eating raw fish (75).","notesPages":[502],"id":"glossary-entry-swarming-ideas","letter":"S"},{"term":"SWARMING (OCEAN-FLOOR ETCHING)","definition":"Part of the twelve-syllable Malay name for the living green color on Whale constructions (137).","notesPages":[502],"id":"glossary-entry-swarming-ocean-floor-etching","letter":"S"},{"term":"SWEAR/SWORE (THIEVES' HONOR)","definition":"Carcajou cannot be believed even when swearing by Thieves' Honor (64).","notesPages":[502],"id":"glossary-entry-swear-swore-thieves-honor","letter":"S"},{"term":"SWIFT (BIRD)","definition":"Fast-flying migratory bird capable of bi-locating while daydreaming (95).","notesPages":[502],"id":"glossary-entry-swift-bird","letter":"S"},{"term":"SWIFT LEAPING THOUGHTS","definition":"Rapid insights experienced by Dubu after eating raw fish (75).","notesPages":[502],"id":"glossary-entry-swift-leaping-thoughts","letter":"S"},{"term":"SWIFT SECOND (AWAKENING)","definition":"The brief moment between Axel's waking and his awakening the other Apes, during which he is vulnerable to murder (143).","notesPages":[502],"id":"glossary-entry-swift-second-awakening","letter":"S"},{"term":"SWIFTS (BIRDS)","definition":"Fast-flying birds participating in the air dances at Heart's Desire Cove (58).","notesPages":[502],"id":"glossary-entry-swifts-birds","letter":"S"},{"term":"SWIM","definition":"Move through water; Lord Randal can swim (133); people swim for boats as island sinks (159).","notesPages":[502],"id":"glossary-entry-swim","letter":"S"},{"term":"SWINBURNE","definition":"Algernon Charles Swinburne, English poet from whose work Axel proposed two lines as a motto for The Three (2).","notesPages":[502],"id":"glossary-entry-swinburne","letter":"S"},{"term":"SWISS BELL RINGING","definition":"Musical art involving tuned bells; abandoned by humans, reinvented by Computers (33).","notesPages":[502],"id":"glossary-entry-swiss-bell-ringing","letter":"S"},{"term":"SWORD IS HANGING O'ER YOUR HEAD (A) (SONG)","definition":"Song line sung by an Ambulatory Computer at Jack Flannagan's Piano Bar (77); refers to A Sword Is Hanging O'er Your Head.","notesPages":[503],"id":"glossary-entry-sword-is-hanging-oer-your-head-a-song","letter":"S"},{"term":"SWORD (SHIP'S)","definition":"Weapon aboard ship; the Alaskan Brown Bear first mate was slow with it (103).","notesPages":[502],"id":"glossary-entry-sword-ships","letter":"S"},{"term":"SWORDFISHES","definition":"Large marine fish with sword-like bill; noted inhabitants of the Deep (138, 139).","notesPages":[503],"id":"glossary-entry-swordfishes","letter":"S"},{"term":"SWORDS (LIMESTONE)","definition":"Stalactites hanging from the roof of Ape Caverns by their drippings (45).","notesPages":[503],"id":"glossary-entry-swords-limestone","letter":"S"},{"term":"SYLLABLE (TWELVE-SYLLABLE NAME)","definition":"Length of the Malay word for the unique green color on Whale constructions (137).","notesPages":[503],"id":"glossary-entry-syllable-twelve-syllable-name","letter":"S"},{"term":"SYMBOLS","definition":"Things representing other things; the Floating World possibly just a collection of symbols and conventions (141); Felix Culebra y Columba lived out all his symbols (snake, dove) (71).","notesPages":[503],"id":"glossary-entry-symbols","letter":"S"},{"term":"SYNDROME (FLAMING ARROW)","definition":"See FLAMING ARROW SYNDROME.","notesPages":[503],"id":"glossary-entry-syndrome-flaming-arrow","letter":"S"},{"term":"SYNDROME (NEW OCEAN)","definition":"See NEW OCEAN SYNDROME.","notesPages":[503],"id":"glossary-entry-syndrome-new-ocean","letter":"S"},{"term":"SYSTEM (DIAL-A-PICTURE)","definition":"See DIAL-A-PICTURE ARRANGEMENTS.","notesPages":[503],"id":"glossary-entry-system-dial-a-picture","letter":"S"},{"term":"SYSTEM (INNEALL'S BLOOD)","definition":"Artificial circulatory system created by Inneall, using an aquarium pump as a heart and containing one gallon of mixed human and Axel's Ape blood (48, 49).","notesPages":[503],"id":"glossary-entry-system-innealls-blood","letter":"S"},{"term":"SYSTEM (INTERLOCKING SUPPORT)","definition":"See SUPPORT SYSTEM (INTERLOCKING).","notesPages":[503],"id":"glossary-entry-system-interlocking-support","letter":"S"},{"term":"SYSTEM (PREDICTION-AND-ANALYSIS GAME)","definition":"Astrology described as a fascinating closed system by computers (29).","notesPages":[503],"id":"glossary-entry-system-prediction-and-analysis-game","letter":"S"},{"term":"SYSTEM (THREE-TRACK)","definition":"Media format ('prowls') using sound, visual, and sometimes printed word tracks; preferred by the Lynn- Randals (6).","notesPages":[503],"id":"glossary-entry-system-three-track","letter":"S"},{"term":"SYSTEMIZED NATURE-DATA","definition":"Organized information about the natural world, possessed extensively by Computers, difficult for even avid humans like Felix to compete with (71).","notesPages":[503],"id":"glossary-entry-systemized-nature-data","letter":"S"},{"term":"TABLE (BANQUET)","definition":"Furnishing in the condominium clubroom from which the Nine and Lazar rise to enter the Executive Passage (144, 147); location near which Invisible Alfred was heard (149).","notesPages":[504],"id":"glossary-entry-table-banquet","letter":"T"},{"term":"TABLE (CORAL)","definition":"Furniture, along with coral chairs, located two miles deep in the Atlantic Ocean where the seven richest metamorphic men allegedly meet annually to decide global financial processes (135).","notesPages":[504],"id":"glossary-entry-table-coral","letter":"T"},{"term":"TABLE (GHOSTS SIT AT)","definition":"Inneall feels like a cafe because the seven ghosts inhabiting her sit around a table within her, talking and giggling (29).","notesPages":[504],"id":"glossary-entry-table-ghosts-sit-at","letter":"T"},{"term":"TAIL (GAJAH'S)","definition":"Appendage the unborn elephant Gajah will eventually show, along with her trunk and face (63).","notesPages":[504],"id":"glossary-entry-tail-gajahs","letter":"T"},{"term":"TAIL (MAKING BEFORE DOG)","definition":"Analogy used by an AMH theorist arguing that humans should be subservient afterthoughts to computers, implying humans being made first was illogical, like making a tail before the dog it belongs to (27).","notesPages":[504],"id":"glossary-entry-tail-making-before-dog","letter":"T"},{"term":"TAINT (MOVEMENT)","definition":"Reporter Roy Latta asks if associating with the \"obviously phoney\" Invisible Alfred does not taint the Royal Kids' own 'movement' (if they have one) (113).","notesPages":[504],"id":"glossary-entry-taint-movement","letter":"T"},{"term":"TALENTED","definition":"Possessing natural aptitude or skill; the Unfallen People are talented but simple- minded (18); mega-persons are exceptionally talented (82).","notesPages":[504],"id":"glossary-entry-talented","letter":"T"},{"term":"TALENTS","definition":"Special abilities or aptitudes; possessed by Axel's Apes for working metals (3); Dubu possesses talents for chess (75); potential","notesPages":[504],"id":"glossary-entry-talents","letter":"T"},{"term":"TALENTS (NEW)","definition":"Abilities emerging as part of the 'Enlargement of the World'; Satrap is unsure if they are truly appearing (127).","notesPages":[505],"id":"glossary-entry-talents-new","letter":"T"},{"term":"TALENTS (SETTING FIRES)","definition":"Pyrokinesis possessed by Henryetta from infancy (96).","notesPages":[505],"id":"glossary-entry-talents-setting-fires","letter":"T"},{"term":"TALENTS (TRANS-ANIMAL)","definition":"Abilities exceeding normal animal capacity, such as speech and abstract thought, emerging in \"geniused animals\" as part of the 'Fulfillment of the World' (93).","notesPages":[505],"id":"glossary-entry-talents-trans-animal","letter":"T"},{"term":"TALK (HUMAN)","definition":"Spoken language used by humans; The Three learned to understand it the week before Axel learned to read (7).","notesPages":[505],"id":"glossary-entry-talk-human","letter":"T"},{"term":"TALK (TO ANIMALS/BIRDS)","definition":"Ability supposedly possessed by Yellow Apes and transmitted to Humans long ago, but subsequently lost by Humans on a \"queer and gloomy day\" (51).","notesPages":[505],"id":"glossary-entry-talk-to-animals-birds","letter":"T"},{"term":"TALKING","definition":"Act of speech; involved in AMH Computer activities (32).","notesPages":[505],"id":"glossary-entry-talking","letter":"T"},{"term":"TALKING ANIMALS","definition":"Animals possessing the ability to speak; experimental animals (\"one-in- a-million\") had been talking for a decade, but the phenomenon became widespread (\"pretty general\") during the Last Week of Summer, amazing people briefly (54, 112, 124).","notesPages":[505],"id":"glossary-entry-talking-animals","letter":"T"},{"term":"TALKING BOOKS (ANIMATED)","definition":"Media format found in the Lynn- Randal house; considered the 'third tracks' of 'two-track prowls', available only for a few 'prowls' but favored by the Lynn-Randals (6).","notesPages":[505],"id":"glossary-entry-talking-books-animated","letter":"T"},{"term":"TALKING DOGS (NEW)","definition":"Anastasia Blickworthy suggests Invisible Alfred's voice sounds like that of the newly emerged talking dogs (123).","notesPages":[505],"id":"glossary-entry-talking-dogs-new","letter":"T"},{"term":"TAPESTRY","definition":"Woven wall hanging; specifically, the magnificent, newly-woven pop art masterwork titled The Midas Satrap Saint Ledger As An Obscene Sea Monster, depicting Satrap in his deep-ocean form, hanging in the condominium clubroom and concealing the entrance to the Executive Passage (144, 147).","notesPages":[505],"id":"glossary-entry-tapestry","letter":"T"},{"term":"TAPIRS","definition":"Mammals included among the experimental animals sharing The Three's contrived habitat (3).","notesPages":[506],"id":"glossary-entry-tapirs","letter":"T"},{"term":"TAPPED ILLEGALLY (GAS WELLS)","definition":"The old natural gas wells running through Ape Caverns had been illicitly tapped by the Axel's Apes in the last decade to provide gas for illumination and power (45).","notesPages":[506],"id":"glossary-entry-tapped-illegally-gas-wells","letter":"T"},{"term":"TARES","definition":"Weeds growing among grain; used metaphorically (\"'This is the harvest time... and the tares cannot be allowed to grow with the wheat any longer'\") to justify the elimination of undesirable elements (\"'unthrifty and blighted'\") from humanity (81).","notesPages":[506],"id":"glossary-entry-tares","letter":"T"},{"term":"TARGET (ASSASSINATION)","definition":"All three of Iris's 'children' might be targeted by the Assassins (84).","notesPages":[506],"id":"glossary-entry-target-assassination","letter":"T"},{"term":"TARGETS (FLAMING ARROWS)","definition":"Destinations or objectives; the Imperial Heads of the Kangaroo go with great accuracy to their targets and destroy them (83).","notesPages":[506],"id":"glossary-entry-targets-flaming-arrows","letter":"T"},{"term":"TARO ROOT (EXPERIMENTAL)","definition":"Edible root vegetable grown in The Three's habitat, consumable by infants from three months old (5).","notesPages":[506],"id":"glossary-entry-taro-root-experimental","letter":"T"},{"term":"TAROT CARDS","definition":"Divination tool used by Lutin the Pythoness to predict futures in her sideshow tent (86).","notesPages":[506],"id":"glossary-entry-tarot-cards","letter":"T"},{"term":"TARP (SQUID-SKIN)","definition":"Flexible sheet made from squid skin, floated by blow-fish bladders, used by dolphin middlemen to transport three hundred pounds of nugget ocean gold payment to Satrap for limestone (106).","notesPages":[506],"id":"glossary-entry-tarp-squid-skin","letter":"T"},{"term":"TARPONS","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[506],"id":"glossary-entry-tarpons","letter":"T"},{"term":"TARQUINS (THE)","definition":"Symbolic representation of the \"Intellectual Tyrannies of human masters,\" from whom the Ambulatory Computers freed themselves, according to Livius Secundus's history (70).","notesPages":[506],"id":"glossary-entry-tarquins-the","letter":"T"},{"term":"TARZAN (NICKNAME)","definition":"Name sometimes used by Inneall for Ruddy Lord Randal, based on the old book-movie comic-strip character Tarzan, reflecting his 'Jungle-Boy' qualities (123).","notesPages":[506],"id":"glossary-entry-tarzan-nickname","letter":"T"},{"term":"TASTY (FISH)","definition":"Lanternjaw complains that little of the fish caught in the 'New Ocean' is tasty, as the best fish haven't migrated there yet (99).","notesPages":[507],"id":"glossary-entry-tasty-fish","letter":"T"},{"term":"TAU-TEMPLE","definition":"Central structure within the Whale Temple-City, described as cross-shaped with four equal arms, although a tau cross conventionally has the form of the letter T; featuring an ornate front door facing East; also functions as a calendar via stone alignments, but its core contains small, human-sized monuments/tombs (137).","notesPages":[507],"id":"glossary-entry-tau-temple","letter":"T"},{"term":"TAUNTED (DEVIL-FISH)","definition":"The eleven devil-fish (transformed wolverenes) verbally mocked the occupants of the Annabella Saint Ledger in human voices, demanding victims (\"'Throw Carcajou to us,'\" etc.) (107).","notesPages":[507],"id":"glossary-entry-taunted-devil-fish","letter":"T"},{"term":"TAVERNS (APES' ALLEY)","definition":"Establishments in Ape Alley where mushroom wine was drunk (46).","notesPages":[507],"id":"glossary-entry-taverns-apes-alley","letter":"T"},{"term":"TEA LEAVES","definition":"Used by Lutin the Pythoness as one method for predicting futures (86).","notesPages":[507],"id":"glossary-entry-tea-leaves","letter":"T"},{"term":"TEARS (WHALE)","definition":"Huge, one-foot-in-diameter tears wept by the four beached whales witnessing Zchold's stoning (159); Whales at the cenotaphs weep huge, salt-water tears (150); Whales at the Epilog weep five-inch-in-diameter tears (166).","notesPages":[507],"id":"glossary-entry-tears-whale","letter":"T"},{"term":"TECHNICOLOR PEOPLE (PIRATES)","definition":"Inneall describes pirates as the first people to embrace vibrant color when others were drab (120).","notesPages":[507],"id":"glossary-entry-technicolor-people-pirates","letter":"T"},{"term":"TECHNIQUE (OCEAN DIVING)","definition":"The method for free diving and moving in the deep ocean without equipment, involving inducing Oceanic Metastasis; learned by Satrap from Indian Ocean Masters (133).","notesPages":[507],"id":"glossary-entry-technique-ocean-diving","letter":"T"},{"term":"TECHNIQUE (RUSTY)","definition":"Invisible Alfred claims his technique (implied for deep diving or enduring pressure) is rusty after nine thousand years chained to a rock on the deepest ocean floor, according to his own account (133–134).","notesPages":[507],"id":"glossary-entry-technique-rusty","letter":"T"},{"term":"TECHNOLOGICAL AGE (SEVENTH)","definition":"The current era of human history, identified by computers as the period whose \"fruit\" they are (37).","notesPages":[507],"id":"glossary-entry-technological-age-seventh","letter":"T"},{"term":"TECHNOLOGICALLY INCLINED (HUMANS)","definition":"Present-day humans are noted as being more technologically oriented than those in the immediate past (37).","notesPages":[508],"id":"glossary-entry-technologically-inclined-humans","letter":"T"},{"term":"TEDIUM","definition":"Boredom or monotony; produced by the low-quality 'prowls' from Jackdaw Press (8); The Three must feed their minds on even the tedium of raw color, noise, and movement (9).","notesPages":[508],"id":"glossary-entry-tedium","letter":"T"},{"term":"TEETH (MARINO'S)","definition":"Mentioned by Marino the Seal, along with Popugai's beak, as weapons available for fighting the wolverenes (102).","notesPages":[508],"id":"glossary-entry-teeth-marinos","letter":"T"},{"term":"TELEGRAM","definition":"Message sent electronically; sent by the resident doctor in Arba Mench to Ansel Grindstone in Indianapolis, warning of Axel's critical condition (14).","notesPages":[508],"id":"glossary-entry-telegram","letter":"T"},{"term":"TELEPATHICALLY (GAJAH DIRECTS MOTHER)","definition":"The unborn Gajah communicates instructions telepathically to her mother Riesin, enabling Riesin to be the best player in the lacrosse game (65).","notesPages":[508],"id":"glossary-entry-telepathically-gajah-directs-mother","letter":"T"},{"term":"TELL THEM (ANSWERS)","definition":"Dubu laments that the people who know the ultimate answers (Luas, Lutin) are too ethical to tell them to mere humans or bears (74).","notesPages":[508],"id":"glossary-entry-tell-them-answers","letter":"T"},{"term":"TEMPLE","definition":"Sacred building; the Whale Temple-City complex (137).","notesPages":[508],"id":"glossary-entry-temple","letter":"T"},{"term":"TEMPLE-CITIES (WHALES')","definition":"Underwater cities built by Whales; they become nervous when more than five hundred sea-miles from one (137).","notesPages":[508],"id":"glossary-entry-temple-cities-whales","letter":"T"},{"term":"TEMPLE-CITY (WHALES')","definition":"The prodigious and wonderful underwater complex built by the Whales on the Ocean Bottom, featuring a Tau-Temple core, marble and granite construction, intricate sea-lice carvings, and human-sized tombs (136, 137).","notesPages":[508],"id":"glossary-entry-temple-city-whales","letter":"T"},{"term":"TEMPLE OF ANGKOR WAT","definition":"See ANGKOR WAT (TEMPLE OF).","notesPages":[508],"id":"glossary-entry-temple-of-angkor-wat","letter":"T"},{"term":"TENANT (POLTER IN INNEALL)","definition":"Inneall, though mechanical, has a \"light-minded polter\" dwelling in her \"part of the time\" (3).","notesPages":[508],"id":"glossary-entry-tenant-polter-in-inneall","letter":"T"},{"term":"TENSES (LANGUAGE)","definition":"Grammatical forms indicating time; an AMH claims that many ancient languages possessed thirty tenses, now reduced to three (37); this belongs to its speculative history of human decline.","notesPages":[508],"id":"glossary-entry-tenses-language","letter":"T"},{"term":"TENT (LUTIN'S)","definition":"Sideshow booth where Lutin the Pythoness predicted futures during the circus event (86, 87).","notesPages":[509],"id":"glossary-entry-tent-lutins","letter":"T"},{"term":"TENT-MAKER (SAINT PAUL)","definition":"The Apostle Paul's trade, cited by Schimp as a precedent for combining manual labor with intellectual work (162).","notesPages":[509],"id":"glossary-entry-tent-maker-saint-paul","letter":"T"},{"term":"TENTH BIRTHDAY","definition":"Critical age for the experimental children; occurs just before the end of the experiment (2); age at which Mega Persons legally reach majority (146); approached by the Eleven (57); the Nine hold a joint party before midnight; some turn ten only minutes or hours afterward (144, 146).","notesPages":[509],"id":"glossary-entry-tenth-birthday","letter":"T"},{"term":"TENTS (WAIF-ARAMA HOUSING)","definition":"Temporary shelters used to house children after one of the Main Waif-arama buildings burned down (96).","notesPages":[509],"id":"glossary-entry-tents-waif-arama-housing","letter":"T"},{"term":"TERM (COINED, ENLARGEMENT)","definition":"Inneall admits she coined the term 'Enlargement of the World' while just being \"smart-talky\" and doesn't know what it means (113).","notesPages":[509],"id":"glossary-entry-term-coined-enlargement","letter":"T"},{"term":"TERMINAL DAYS (END-OF-SUMMER SUN)","definition":"The final days of the End of Summer, characterized by a queer, dim, garish sun whose dramatic cycle played out quickly (59).","notesPages":[509],"id":"glossary-entry-terminal-days-end-of-summer-sun","letter":"T"},{"term":"TERMINATED (LOWER CLASSES)","definition":"Eliminated or killed; the lower classes of everything were terminated by the Kangaroo's levellers (81).","notesPages":[509],"id":"glossary-entry-terminated-lower-classes","letter":"T"},{"term":"TERMINATING (EXPERIMENT)","definition":"Ending the experiment; Dolophonoi have the power of terminating it (42).","notesPages":[509],"id":"glossary-entry-terminating-experiment","letter":"T"},{"term":"TERMS (ASININE)","definition":"Names derived from asses (donkey, jack, jenny) applied by humans to machines (31).","notesPages":[509],"id":"glossary-entry-terms-asinine","letter":"T"},{"term":"TERMS (WILL/ANGELIC WILL)","definition":"Strongness and weakness are terms that do not apply to angelic will (61).","notesPages":[509],"id":"glossary-entry-terms-will-angelic-will","letter":"T"},{"term":"TERRE HAUTE INDIANA","definition":"Birthplace of Axel Albert Grindstone (10); Ansel Grindstone moved from there to Indianapolis (14).","notesPages":[509],"id":"glossary-entry-terre-haute-indiana","letter":"T"},{"term":"TERROR","definition":"Intense fear; depicted on the face of the man on Zchold's cenotaph (150).","notesPages":[509],"id":"glossary-entry-terror","letter":"T"},{"term":"TERROR (HUMAN)","definition":"Inneall is imprinted with human terrors, which machines normally do not have (50).","notesPages":[510],"id":"glossary-entry-terror-human","letter":"T"},{"term":"TERROR (STRIKE ON OCEANS)","definition":"Inneall boasts her flag will strike terror on all the oceans (49).","notesPages":[510],"id":"glossary-entry-terror-strike-on-oceans","letter":"T"},{"term":"TERRORS (MACHINES DON'T HAVE)","definition":"Machines lack fear and terrors, unlike imprinted Inneall (50).","notesPages":[510],"id":"glossary-entry-terrors-machines-dont-have","letter":"T"},{"term":"TESTAMENT (OLD)","definition":"Section of the Bible containing accounts of the Sons of Anak (106).","notesPages":[510],"id":"glossary-entry-testament-old","letter":"T"},{"term":"TESTER (INTELLIGENCE SCALE)","definition":"Individual administering intelligence tests; only one tester in a million knows of the \"secret- scale\" on which Carcajou scores highly (64).","notesPages":[510],"id":"glossary-entry-tester-intelligence-scale","letter":"T"},{"term":"TESTIMONY","definition":"Evidence or statement; given about humans by humans, God, Intelligent Computers, but not Intelligent Axel's Apes (42).","notesPages":[510],"id":"glossary-entry-testimony","letter":"T"},{"term":"TESTS (AMHS WRITE)","definition":"AMHs devise the tests they excel at, making comparison with humans unfair according to some humans (26).","notesPages":[510],"id":"glossary-entry-tests-amhs-write","letter":"T"},{"term":"TESTS (CHROMOSOME)","definition":"Genetic tests run on the Unfallen People confirming they possess 22 pairs of autosomes and one pair of sex chromosomes, like humans (18).","notesPages":[510],"id":"glossary-entry-tests-chromosome","letter":"T"},{"term":"TEXT","definition":"Written words; followed with a finger while reading printed prowls (7).","notesPages":[510],"id":"glossary-entry-text","letter":"T"},{"term":"THALASSOMANIACS","definition":"Individuals obsessed with the sea; Inneall described as an unreformable thalassomaniac due to her dream of a world-covering ocean (130).","notesPages":[510],"id":"glossary-entry-thalassomaniacs","letter":"T"},{"term":"THANKFUL","definition":"Feeling gratitude; Dubu is thankful for mysteries (125).","notesPages":[510],"id":"glossary-entry-thankful","letter":"T"},{"term":"THEATRE (DOLPHINS' UNDERWATER)","definition":"See DOLPHINS' UNDERWATER THEATER.","notesPages":[510],"id":"glossary-entry-theatre-dolphins-underwater","letter":"T"},{"term":"THEATRE-GOERS (STRUCTO LANE)","definition":"Patrons attending plays in Structo Lane always dress elegantly (\"full dress\") (76).","notesPages":[510],"id":"glossary-entry-theatre-goers-structo-lane","letter":"T"},{"term":"THEATRE (MOVIE)","definition":"See MOVIE THEATRE (APES').","notesPages":[510],"id":"glossary-entry-theatre-movie","letter":"T"},{"term":"THEOLOGY OF LIFE","definition":"A systematic belief system about the ultimate meaning and purpose of life; explicitly forbidden in the Floating World (141).","notesPages":[511],"id":"glossary-entry-theology-of-life","letter":"T"},{"term":"THEORIST (AMH)","definition":"An Ambulatory Mime-Human Computer specializing in theory; one compares common sense to salt or garlic (26).","notesPages":[511],"id":"glossary-entry-theorist-amh","letter":"T"},{"term":"THEORY (COMPUTER CONVERTING WORLD)","definition":"Hypothetical possibility that a single small computer with sufficient impetus could transform the entire world (27).","notesPages":[511],"id":"glossary-entry-theory-computer-converting-world","letter":"T"},{"term":"THEOS","definition":"Supreme divine being or principle; humans who don't believe are Atheists, Computers who don't believe in Humans are Ananthropoi (38); in creation legends, the Theos makes creatures on a lathe, including the flawed Mankind (36-37).","notesPages":[511],"id":"glossary-entry-theos","letter":"T"},{"term":"THEREFORE THINK OF HIM AS A SERPENT'S EGG (QUOTE)","definition":"Epigraph from Shakespeare's Julius Caesar opening Chapter One (1).","notesPages":[511],"id":"glossary-entry-therefore-think-of-him-as-a-serpents-egg-quote","letter":"T"},{"term":"THEY TALK OF TREASURED ISLANDS (POEM)","definition":"Verse attributed to Josh Elderhouse near the end of Chapter Fourteen, after Tom Dooley’s Island has reached Ocean Bottom (159). It contrasts treasure islands with the speaker’s precious island beneath the sea.","notesPages":[526],"id":"glossary-entry-they-talk-of-treasured-islands-poem","letter":"T"},{"term":"THIEVES' HONOR","definition":"Code of conduct among thieves; Carcajou cannot be believed even when swearing by it (64); refers to Thieves' Honor.","notesPages":[511],"id":"glossary-entry-thieves-honor","letter":"T"},{"term":"THIGH (TOUCHED)","definition":"In the Book of Jasher account, the angel (\"man who was more than a man\") touches the thigh of his opponent, in a rewritten Jacob-like wrestling episode applied to Carcajou, causing a permanent change preventing him from returning to animal form (88).","notesPages":[511],"id":"glossary-entry-thigh-touched","letter":"T"},{"term":"THING (BLESSED)","definition":"Machinery transformed into a living and blessed thing by the touch of the Unfallen Ones (15).","notesPages":[511],"id":"glossary-entry-thing-blessed","letter":"T"},{"term":"THING (BLESSED, EGG)","definition":"Lutin's rapturous description of the Big Egg (154).","notesPages":[511],"id":"glossary-entry-thing-blessed-egg","letter":"T"},{"term":"THING (HOPE-OF-THE-WORLD, EGG)","definition":"Lutin's further rapturous description of the Big Egg (154).","notesPages":[511],"id":"glossary-entry-thing-hope-of-the-world-egg","letter":"T"},{"term":"THING (RESURRECTION OF HONOR)","definition":"Proponents insisted the revival of Honor was a \"real and valid thing\" (118).","notesPages":[511],"id":"glossary-entry-thing-resurrection-of-honor","letter":"T"},{"term":"THING (UNDER LAZAR'S ARM)","definition":"The hooded Midnight Cock carried by Sebastian Lazar (153).","notesPages":[511],"id":"glossary-entry-thing-under-lazars-arm","letter":"T"},{"term":"THINK (CLOWN)","definition":"Question raised in the Enniscorthy Chronicle about whether \"'This clown, this Joker'\" can think or plan (107).","notesPages":[512],"id":"glossary-entry-think-clown","letter":"T"},{"term":"THINKING (HISTORICAL SENSE)","definition":"Livius Secundus modeled his thinking on the Roman historian Livy (71).","notesPages":[512],"id":"glossary-entry-thinking-historical-sense","letter":"T"},{"term":"THINKING (WELL OF A MAN)","definition":"Lord Randal avoids reading the name on the knuckle-bone because he doesn't want to come to think badly of a prominent man he had previously thought well of (146).","notesPages":[512],"id":"glossary-entry-thinking-well-of-a-man","letter":"T"},{"term":"THIRD CONDITION (PEOPLE NEEDING REPENTANCE)","definition":"Category of people addressed by Invisible Alfred, presumably those neither wholly good nor wholly evil (110).","notesPages":[512],"id":"glossary-entry-third-condition-people-needing-repentance","letter":"T"},{"term":"THIRD DAY OF SUMMERSET","definition":"The final day of the End of Summer period (116, 151).","notesPages":[512],"id":"glossary-entry-third-day-of-summerset","letter":"T"},{"term":"THIRD MORNING OF SUMMERSET","definition":"The morning of the final day, when Donatus O'Reily is scheduled to be hanged at cockcrow (117, 118).","notesPages":[512],"id":"glossary-entry-third-morning-of-summerset","letter":"T"},{"term":"THIRD NIGHT OF SUMMERSET","definition":"The final night of the End of Summer, beginning after the sun sets on the Second Day (140); title of the Ode epigraph for Chapter Thirteen (141); ends with the dire Third Day (151).","notesPages":[512],"id":"glossary-entry-third-night-of-summerset","letter":"T"},{"term":"THIRD SISTER (ATROPOS)","definition":"See ATROPOS.","notesPages":[512],"id":"glossary-entry-third-sister-atropos","letter":"T"},{"term":"THIRD TRACKS","definition":"The printed word component occasionally included in the multi-track media format known as 'prowls' (6, 7).","notesPages":[512],"id":"glossary-entry-third-tracks","letter":"T"},{"term":"THIRTY DAYS (FLAMES BURN)","definition":"Duration the three flames will burn over Gajah's body, according to Satrap Saint Ledger (94).","notesPages":[512],"id":"glossary-entry-thirty-days-flames-burn","letter":"T"},{"term":"THIRTY FATHOMS DEEP (ISLAND SINKS)","definition":"Predicted depth to which Tom Dooley's Island will sink under Inneall's Ocean before the night is over (100).","notesPages":[512],"id":"glossary-entry-thirty-fathoms-deep-island-sinks","letter":"T"},{"term":"THIRTY-FIRST MORNING OF AUGUST","definition":"Date corresponding to the Third Morning of Summerset, when Donatus O'Reily is hanged (117).","notesPages":[513],"id":"glossary-entry-thirty-first-morning-of-august","letter":"T"},{"term":"THIRTY-FIVE YEARS OLD (AXEL'S LIFESPAN)","definition":"Age Axel Albert Grindstone was predicted to die by (10); he dies one month short of this age (18).","notesPages":[513],"id":"glossary-entry-thirty-five-years-old-axels-lifespan","letter":"T"},{"term":"THIRTY OUNCES OF GOLD","definition":"Price offered for the kangaroo knuckle-bone revealing the Kangaroo Head’s identity; Satrap agrees to pay, and Lord Randal receives the bone (145– 146).","notesPages":[512],"id":"glossary-entry-thirty-ounces-of-gold","letter":"T"},{"term":"THIRTY TENSES (LANGUAGE)","definition":"Number of grammatical tenses an AMH claims many ancient languages once possessed before declining to three (37).","notesPages":[512],"id":"glossary-entry-thirty-tenses-language","letter":"T"},{"term":"THIRTY-THREE FATHOMS LONG (ALLEY OOP)","definition":"Length required for the Alley Oop connection to Tom Dooley's Island, accounting for high tides (101).","notesPages":[513],"id":"glossary-entry-thirty-three-fathoms-long-alley-oop","letter":"T"},{"term":"THIRTY-THREE FEET (GIANT HAND WRIST DIAMETER)","definition":"Approximate imperial measurement equivalent to the ten-meter diameter wrist of the giant hand that initiated the Holy Sleep (68).","notesPages":[513],"id":"glossary-entry-thirty-three-feet-giant-hand-wrist-diameter","letter":"T"},{"term":"THIRTY TONS (CALKING COMPOUND)","definition":"Amount of waterproofing material required by the pirates to seal Persimmon Manor (101, 116).","notesPages":[513],"id":"glossary-entry-thirty-tons-calking-compound","letter":"T"},{"term":"THIRTY-TWO CARRY-OVER GUESTS","definition":"The number of persistent party guests remaining at Persimmon Manor when the Nine arrive (116).","notesPages":[513],"id":"glossary-entry-thirty-two-carry-over-guests","letter":"T"},{"term":"THIRTY YEARS (AGE OF MANKIND)","definition":"Approximate age difference between First Mankind and Second Mankind (the Unfallens) according to Axel Grindstone (11).","notesPages":[513],"id":"glossary-entry-thirty-years-age-of-mankind","letter":"T"},{"term":"THIRTY YEARS (SATRAP LIVED IN HOUSE)","definition":"Duration Satrap Saint Ledger has lived in Persimmon Manor for an average of four months per year (124).","notesPages":[513],"id":"glossary-entry-thirty-years-satrap-lived-in-house","letter":"T"},{"term":"THIRTY YEARS (WOMAN MARRIED TO DRUNK)","definition":"Length of marriage cited in an analogy about noticing change only through contrast (47).","notesPages":[513],"id":"glossary-entry-thirty-years-woman-married-to-drunk","letter":"T"},{"term":"THOMAS (APOSTLE)","definition":"Disciple of Christ identified by Invisible Alfred as corresponding to the constellation Gemini (the Twins), Alfred’s explanation for why Thomas was called “the twin” (111).","notesPages":[513],"id":"glossary-entry-thomas-apostle","letter":"T"},{"term":"THOMPSON ABERNATHY","definition":"One of ten persons named and condemned to die within ten minutes by the Prophet Invisible Alfred (112).","notesPages":[504],"id":"glossary-entry-thompson-abernathy","letter":"T"},{"term":"THORAX (AMH AIR JETS)","definition":"Chest area from which air jets emerge, enabling an elegant AMH Computer to shape square smoke rings (30).","notesPages":[514],"id":"glossary-entry-thorax-amh-air-jets","letter":"T"},{"term":"THOUGHTS (INVISIBLE)","definition":"Mental processes unseen by ordinary perception; Invisible Alfred claims the power to see even the most invisible thoughts (110).","notesPages":[514],"id":"glossary-entry-thoughts-invisible","letter":"T"},{"term":"THOUGHTS (SWIFT LEAPING)","definition":"Rapid, insightful ideas experienced by Dubu after eating raw 'Filchman's Daughter' fish (75).","notesPages":[514],"id":"glossary-entry-thoughts-swift-leaping","letter":"T"},{"term":"THOUSAND AMHS (MAKING OCEANS)","definition":"Hypothetical number of Ambulatory Computers that might imitate Inneall and begin making oceans, posing a potential danger (28).","notesPages":[514],"id":"glossary-entry-thousand-amhs-making-oceans","letter":"T"},{"term":"THOUSAND DOLLARS (GOLD SOMALI SHILLING VALUE)","definition":"Approximate value of the three Gold Somali Shillings given to each expelled hotel guest (67).","notesPages":[514],"id":"glossary-entry-thousand-dollars-gold-somali-shilling-value","letter":"T"},{"term":"THOUSAND POUNDS (HAMBURGER MEAT)","definition":"Quantity loaded onto the Annabella Saint Ledger (101).","notesPages":[514],"id":"glossary-entry-thousand-pounds-hamburger-meat","letter":"T"},{"term":"THOUSAND TONS (LIMESTONE)","definition":"Approximate amount delivered by Satrap’s firm since midnight; the four other firms are said probably to have delivered another thousand tons collectively (107).","notesPages":[514],"id":"glossary-entry-thousand-tons-limestone","letter":"T"},{"term":"THOUSAND YEARS","definition":"Significant time interval; Unfallen sons wake every thousand years (18-19); possible duration of Axel’s absence (123); nine such millennia since animal speech was common (54, 124); duration wotto metal mine paid out better than gold (48); Alfred claims nine thousand years chained to a rock and, separately, nine thousand years in a drum (133, 110); machine lifespan (143); ocean lifespan debated (143); Second Humanity might sleep another thousand years (143); giant structures built over nine thousand years (131).","notesPages":[514],"id":"glossary-entry-thousand-years","letter":"T"},{"term":"THOUSANDS (BIRDS)","definition":"Number of birds marshalled into choirs and orchestras by the Birdmaster (60).","notesPages":[514],"id":"glossary-entry-thousands-birds","letter":"T"},{"term":"THOUSANDS CHEERED (HANGING)","definition":"Customary phrase reported at the end of any account of a hanging, regardless of the actual number of observers or their reaction; applied to Donatus O'Reily's execution (157, 158).","notesPages":[515],"id":"glossary-entry-thousands-cheered-hanging","letter":"T"},{"term":"THOUSANDS (LANGUAGES)","definition":"Number of insect, reptile, animal, and bird languages known by Popugai (64).","notesPages":[514],"id":"glossary-entry-thousands-languages","letter":"T"},{"term":"THOUSANDS OF TIMES BIGGER (OCEAN INTENTION)","definition":"Inneall intends to make her ocean vastly larger than its current size (48).","notesPages":[515],"id":"glossary-entry-thousands-of-times-bigger-ocean-intention","letter":"T"},{"term":"THOUSANDS (PERSONS, ALFRED SPEAKS TO)","definition":"Invisible Alfred addresses the multitude of ten thousand on the Ocean Shore (112).","notesPages":[515],"id":"glossary-entry-thousands-persons-alfred-speaks-to","letter":"T"},{"term":"THOUSANDS (PERSONS AXEL TALKED TO)","definition":"Number of learned and unlearned persons Axel Grindstone conversed with during his travels (12).","notesPages":[514],"id":"glossary-entry-thousands-persons-axel-talked-to","letter":"T"},{"term":"THOUSANDS (ROUNDS, BAZOOKA)","definition":"Five thousand bazooka shells loaded onto the Annabella (101).","notesPages":[515],"id":"glossary-entry-thousands-rounds-bazooka","letter":"T"},{"term":"THOUSANDS (WHALE CENOTAPHS)","definition":"Great stone cenotaphs exist for a thousand whales in the Whale Graveyard, though only about a hundred skeletons are present (132).","notesPages":[515],"id":"glossary-entry-thousands-whale-cenotaphs","letter":"T"},{"term":"THOUSANDS (YEARS AGO, MAN APPEARED)","definition":"Time of Mankind's appearance, countable on digits of two hands and one foot (34).","notesPages":[515],"id":"glossary-entry-thousands-years-ago-man-appeared","letter":"T"},{"term":"THREAD (LIFE)","definition":"See LIFE THREAD.","notesPages":[515],"id":"glossary-entry-thread-life","letter":"T"},{"term":"THREADS","definition":"Filaments spun from straw by the Fate Clotho, representing individual lifespans (103, 114, 126); measured by Lachesis and cut by Atropos (103, 114, 126); Inneall reinforces hers and her companions' threads with wotto-metal (127, 129).","notesPages":[515],"id":"glossary-entry-threads","letter":"T"},{"term":"THREATENED (BY KANGAROO)","definition":"Those endangered by the Kangaroo constellation are supposedly the only ones who can see it (77).","notesPages":[515],"id":"glossary-entry-threatened-by-kangaroo","letter":"T"},{"term":"THREATENED (KINGS FEELING)","definition":"Axel worries what established powers (\"Kings\") will do when they feel threatened by The Three (2).","notesPages":[515],"id":"glossary-entry-threatened-kings-feeling","letter":"T"},{"term":"THREATS (DEATH)","definition":"Various death threats seem to be hanging over the Royal Kids (113).","notesPages":[515],"id":"glossary-entry-threats-death","letter":"T"},{"term":"THREE","definition":"The central group of the Lynn-Randal experiment: Lord Randal, Inneall, and Axel (1); raised together from infancy (1, 3); share emotions (1); possess exceptional intelligence (5); explore the Lynn- Randal house (5-6); discover signature colors/geometries (6); learn about Serpent's Eggs (1-2); visit Structo Lane and Ape Caverns (9); their experiment possibly contaminated (9).","notesPages":[515,516],"id":"glossary-entry-three","letter":"T"},{"term":"THREE (BABIES, PYTHONS)","definition":"Three live baby pythons birthed by Lutin, found being fostered by the Three Fates (160).","notesPages":[516],"id":"glossary-entry-three-babies-pythons","letter":"T"},{"term":"THREE DAYS OF SUMMERSET","definition":"The final three days of the End of Summer (57); exhibit prodigies (54); time of the Big Birthday (57); First Evening begins with sealing of Ape Caverns (67); The circus and the deaths of Gajah and Riesin precede the ship-painting on the Second Night (85–104); Second Day includes Alfred’s sermon and the ocean dive (106–140), followed by the Third Night’s birthday banquet (141–147); Third Morning includes hangings and stoning (117-118); Third Day involves island sinking (151).","notesPages":[516],"id":"glossary-entry-three-days-of-summerset","letter":"T"},{"term":"THREE EXPERIMENTS (MERGED)","definition":"The Wintergreen-Luna, Dorantes-Saleh, and Gruenbaum- McGregor experiments were merged with the Lynn-Randal experiment in the final days (55).","notesPages":[516],"id":"glossary-entry-three-experiments-merged","letter":"T"},{"term":"THREE FATES","definition":"See FATES (THREE FATES).","notesPages":[516],"id":"glossary-entry-three-fates","letter":"T"},{"term":"THREE FLAMES (HOVER OVER GAJAH)","definition":"Appear from the middle air and hover over Gajah's bush-covered body in the Elephant Graveyard; Satrap predicts they will burn for thirty days (94).","notesPages":[516],"id":"glossary-entry-three-flames-hover-over-gajah","letter":"T"},{"term":"THREE GREAT PLACES (ADDRESSING CROWDS)","definition":"Strategic balconies, mountain slopes, and ships brought to land are the three prime locations for speaking to multitudes (109).","notesPages":[516],"id":"glossary-entry-three-great-places-addressing-crowds","letter":"T"},{"term":"THREE-GROUP","definition":"Term used by a Dolophonos referring to the original Lynn-Randal trio (Axel, Randal, Inneall) (87).","notesPages":[517],"id":"glossary-entry-three-group","letter":"T"},{"term":"THREE HUNDRED (OCEAN-TURTLES)","definition":"Approximate number of giant, live turtles kept in the aft hold of the Annabella (99).","notesPages":[517],"id":"glossary-entry-three-hundred-ocean-turtles","letter":"T"},{"term":"THREE HUNDRED PERSONS (AIRLINER)","definition":"Number of passengers on the hypothetical airliner used to illustrate paradoxical freedom of choice (41).","notesPages":[517],"id":"glossary-entry-three-hundred-persons-airliner","letter":"T"},{"term":"THREE HUNDRED PERSONS (ENTERTAINED)","definition":"Number of guests Lutin could have entertained in her large lying-in room (154).","notesPages":[517],"id":"glossary-entry-three-hundred-persons-entertained","letter":"T"},{"term":"THREE HUNDRED POUNDS (NUGGET GOLD)","definition":"Weight of gold brought by dolphins as payment for limestone (106).","notesPages":[518],"id":"glossary-entry-three-hundred-pounds-nugget-gold","letter":"T"},{"term":"THREE HUNTERS","definition":"Iris Lynn-Randal, Shadrack Saleh, and Gregor McGregor, who set out to kill the Dolophonoi-Assassins assigned to their experimental 'children' (84, 85, 89, 91).","notesPages":[516],"id":"glossary-entry-three-hunters","letter":"T"},{"term":"THREE KILOMETERS WIDE (OCEAN)","definition":"Width reached by Inneall's Ocean after only three days (27).","notesPages":[516],"id":"glossary-entry-three-kilometers-wide-ocean","letter":"T"},{"term":"THREE METERS LONG (EGG)","definition":"Dimensions (along with two meters thick) of the Big Egg that Lutin claims to have produced (154–155).","notesPages":[516],"id":"glossary-entry-three-meters-long-egg","letter":"T"},{"term":"THREE MINUTES LATER (DONATUS)","definition":"Time elapsed between Donatus’s summons to his nine dead companions and his appearance on the gallows deck (157).","notesPages":[516],"id":"glossary-entry-three-minutes-later-donatus","letter":"T"},{"term":"THREE MINUTES TILL MIDNIGHT","definition":"Exact time when the Nine and Lazar rise from the banquet table to enter the Executive Passage (147).","notesPages":[516],"id":"glossary-entry-three-minutes-till-midnight","letter":"T"},{"term":"THREE NIGHTS AND THREE DAYS","definition":"Duration of the 'Holy Sleep' imposed on Ape Caverns (68, 70); duration Axel must sleep in the cavern (65).","notesPages":[517],"id":"glossary-entry-three-nights-and-three-days","letter":"T"},{"term":"THREE NOTARIES","definition":"Officials (one human, one computer, one Axel's Ape) who attest nightly to the lightning strike in Ape Caverns; only two could attest the giant hand, as the Ape notary fell asleep (68).","notesPages":[517],"id":"glossary-entry-three-notaries","letter":"T"},{"term":"THREE PERSONS (HUNTERS)","definition":"Iris, Shadrack, and Gregor (84, 85, 89).","notesPages":[517],"id":"glossary-entry-three-persons-hunters","letter":"T"},{"term":"THREE PERSONS (RETURN FROM OCEAN BOTTOM)","definition":"Inneall, Carcajou, and Schimp return to the surface after placing Axel, Randal, and Henryetta in their cenotaphs, before the island’s sinking (150–152). They are not the only survivors of the final island events.","notesPages":[517],"id":"glossary-entry-three-persons-return-from-ocean-bottom","letter":"T"},{"term":"THREE RITUAL TWITCHES (DONATUS')","definition":"Involuntary movements made by Donatus O'Reily's body after being hanged (157).","notesPages":[517],"id":"glossary-entry-three-ritual-twitches-donatus","letter":"T"},{"term":"THREE SECONDS (ASHES REDUCTION)","definition":"Time taken for the wotto- metal statue to burn to ashes (97), and then for the ashes to vanish (97).","notesPages":[517],"id":"glossary-entry-three-seconds-ashes-reduction","letter":"T"},{"term":"THREE SISTERS (UGLY)","definition":"See FATES (THREE FATES).","notesPages":[517],"id":"glossary-entry-three-sisters-ugly","letter":"T"},{"term":"THREE STORES (TOTAL KNOWLEDGE, BEAR BRAIN)","definition":"Dubu claims total knowledge is contained in triplicate within three lobes of her four-lobed bear brain (75).","notesPages":[517],"id":"glossary-entry-three-stores-total-knowledge-bear-brain","letter":"T"},{"term":"THREE-TRACK SYSTEM","definition":"The media format utilizing sound, visual, and sometimes text tracks (6).","notesPages":[518],"id":"glossary-entry-three-track-system","letter":"T"},{"term":"THREE-TRACKERS","definition":"Devices capable of playing three-track media; obtained by the Lynn- Randals whenever available (6).","notesPages":[518],"id":"glossary-entry-three-trackers","letter":"T"},{"term":"THREE TRACKS","definition":"Components of the 'prowl' media format: sound, visual, and sometimes printed word (6, 7).","notesPages":[517],"id":"glossary-entry-three-tracks","letter":"T"},{"term":"THREE-WAY DREAM","definition":"Shared dream experienced simultaneously by Lord Randal, Inneall, and Axel, often involving conflict over leadership and sometimes intrusion by Inneall's ghosts (28-29).","notesPages":[518],"id":"glossary-entry-three-way-dream","letter":"T"},{"term":"THREE-WAY HYBRIDS? (DOLOPHONOI)","definition":"Question raised about the potential mixed nature (human/ape/mechanism) of the Dolophonoi-Assassins (42).","notesPages":[518],"id":"glossary-entry-three-way-hybrids-dolophonoi","letter":"T"},{"term":"THROAT (AXEL'S)","definition":"Site where the Dolophonoi knife buries itself, killing him (148).","notesPages":[518],"id":"glossary-entry-throat-axels","letter":"T"},{"term":"THROAT (HENRYETTA'S)","definition":"Site where the dangling Dolophonoi knife buries itself, killing her; the knife remains lodged there (149, 150).","notesPages":[518],"id":"glossary-entry-throat-henryettas","letter":"T"},{"term":"THROAT (LORD RANDAL'S)","definition":"Site where the dancing Dolophonoi knife strikes, killing him (148).","notesPages":[518],"id":"glossary-entry-throat-lord-randals","letter":"T"},{"term":"THROATINESS (ALL-PEOPLE)","definition":"The consensus voice quality adopted by media (6).","notesPages":[518],"id":"glossary-entry-throatiness-all-people","letter":"T"},{"term":"THROATS (SLITTING)","definition":"Violent act mentioned metaphorically by an AMH theorist as sometimes necessary to achieve a goal (\"can't make an omelet without...\") (39).","notesPages":[518],"id":"glossary-entry-throats-slitting","letter":"T"},{"term":"THROW-BACK (AXEL AS)","definition":"Axel Albert Grindstone considered a throwback to some of his \"plowed-under\" fair-haired, blue-eyed ancestors (11).","notesPages":[518],"id":"glossary-entry-throw-back-axel-as","letter":"T"},{"term":"THUMP LANGUAGE","definition":"See LANGUAGE (THUMP).","notesPages":[518],"id":"glossary-entry-thump-language","letter":"T"},{"term":"THUNDER","definition":"Loud sound associated with storms; part of background 'good noise' in 'prowls' (6); Mark Twain claims to put himself to sleep with thunder (131).","notesPages":[518],"id":"glossary-entry-thunder","letter":"T"},{"term":"THUNDER-EDGED VOICE","definition":"Quality of the powerful voice speaking from the sky above Ape Caverns during the initiation of the Holy Sleep (68).","notesPages":[519],"id":"glossary-entry-thunder-edged-voice","letter":"T"},{"term":"THUNDER OF CATARACTS (WHALES)","definition":"Sound made by the four great whales descending into the ocean depths after Zchold's death (159).","notesPages":[519],"id":"glossary-entry-thunder-of-cataracts-whales","letter":"T"},{"term":"THUNDEROUS WORDS","definition":"Impressively resonant words; the Sea Louse loves coining them, like \"Epilog\" (166).","notesPages":[519],"id":"glossary-entry-thunderous-words","letter":"T"},{"term":"THUS FAR AND NO FARTHER (FOWL FLIGHT LIMIT)","definition":"Phrase describing the limited flight capability of the experimental fowl in The Three's habitat (3); phrase used by Science regarding Inneall's Ocean (161).","notesPages":[519],"id":"glossary-entry-thus-far-and-no-farther-fowl-flight-limit","letter":"T"},{"term":"THUS WE FRUSTRATE CHARLEMAGNE (FICTION)","definition":"Work of shorter fiction written by R.A. Lafferty (publisher’s biographical note); the title is misspelled “Charlamagne” in the edition’s author biography.","notesPages":[519],"id":"glossary-entry-thus-we-frustrate-charlemagne-fiction","letter":"T"},{"term":"THWART THEM (UGLY SISTERS)","definition":"Lanternjaw expresses resolve to somehow frustrate the plans of the Three Fates (103).","notesPages":[519],"id":"glossary-entry-thwart-them-ugly-sisters","letter":"T"},{"term":"TIBET (HIGH)","definition":"See HIGH TIBET.","notesPages":[519],"id":"glossary-entry-tibet-high","letter":"T"},{"term":"TICKETS (AIRLINER)","definition":"Travel documents used in the analogy illustrating paradoxical freedom; if printed \"'Individual Destination Fully Optional,'\" then they are so (41).","notesPages":[519],"id":"glossary-entry-tickets-airliner","letter":"T"},{"term":"TICKLED BLACK (CROWS)","definition":"Amused state of the crows witnessing Invisible Alfred's sermon (112).","notesPages":[519],"id":"glossary-entry-tickled-black-crows","letter":"T"},{"term":"TIDE OF COLOR (DARK)","definition":"Metaphorical description of the common people, contrasted with the fair, red Lord Randal (123).","notesPages":[519],"id":"glossary-entry-tide-of-color-dark","letter":"T"},{"term":"TIDES (HIGH)","definition":"Justification for making the Alley Oop connection thirty-three fathoms long (101).","notesPages":[519],"id":"glossary-entry-tides-high","letter":"T"},{"term":"TIME","definition":"See TIME (CRITICAL, ENLARGEMENT), TIME (THIS MOMENT), TIME (TO KNOW), and the numbered time-period entries.","notesPages":[519],"id":"glossary-entry-time","letter":"T"},{"term":"TIME (CRITICAL, ENLARGEMENT)","definition":"See CRITICAL TIMES.","notesPages":[519],"id":"glossary-entry-time-critical-enlargement","letter":"T"},{"term":"TIME (THIS MOMENT)","definition":"See MOMENT (THIS).","notesPages":[520],"id":"glossary-entry-time-this-moment","letter":"T"},{"term":"TIME (TO KNOW)","definition":"See KNOW (TIME TO).","notesPages":[520],"id":"glossary-entry-time-to-know","letter":"T"},{"term":"TIMES-TO-COME VOICES","definition":"See VOICES (TIMES-TO-COME).","notesPages":[520],"id":"glossary-entry-times-to-come-voices","letter":"T"},{"term":"TIN GIRL (LITTLE, INNEALL)","definition":"Satrap's slightly derogatory term for Inneall, emphasizing her metallic nature (48).","notesPages":[520],"id":"glossary-entry-tin-girl-little-inneall","letter":"T"},{"term":"TINKER TRADES","definition":"Crafts involving mending metal utensils; taught by the Unfallen People to the Gypsies (13).","notesPages":[520],"id":"glossary-entry-tinker-trades","letter":"T"},{"term":"TINNY VOICE (INNEALL'S)","definition":"Quality of Inneall's voice when chanting \"'I am not conscious'\" (23).","notesPages":[520],"id":"glossary-entry-tinny-voice-innealls","letter":"T"},{"term":"TIP-BARGES","definition":"Barges designed for dumping cargo by tipping; used by Satrap to deliver limestone to designated spots in the Ocean for the Whales (106, 136).","notesPages":[520],"id":"glossary-entry-tip-barges","letter":"T"},{"term":"TITAN SKELETON","definition":"A purported Field Museum exhibit in the novel’s account; described as clearly human but \"almost titanic\" (two meters and ten centimeters tall) (44).","notesPages":[520],"id":"glossary-entry-titan-skeleton","letter":"T"},{"term":"TITANIC (ALLEY)","definition":"Description (\"'alley titanic / Of Cypress'\") from the Poe epigraph for Chapter Five (43).","notesPages":[520],"id":"glossary-entry-titanic-alley","letter":"T"},{"term":"TITANIC (TITAN SKELETON)","definition":"Near-titanic height (2.10 meters) of the human skeleton at the Field Museum (44).","notesPages":[520],"id":"glossary-entry-titanic-titan-skeleton","letter":"T"},{"term":"TITANS (CITY OF)","definition":"Alternative name for the underwater City of Lyonesse (105).","notesPages":[520],"id":"glossary-entry-titans-city-of","letter":"T"},{"term":"TITANS (OLD)","definition":"Primordial giant beings from Greek mythology; depicted on bas reliefs with almost-gargoyle faces (44); wrestled earth-shakingly (88); possibly built the underwater City of Lyonesse after being overthrown by the Gods of Olympus and fleeing to the outer ocean (106); City of Titans is another name for Lyonesse (105).","notesPages":[520],"id":"glossary-entry-titans-old","letter":"T"},{"term":"TITLE (LORD AND MASTER OF THE WORLD)","definition":"See LORD AND MASTER OF THE WORLD.","notesPages":[520],"id":"glossary-entry-title-lord-and-master-of-the-world","letter":"T"},{"term":"TO DESTINATION TOWN (POEM QUOTE)","definition":"Phrase within the first line of Chapter Four’s verse epigraph: “The sign 'To Destination Town'” (34).","notesPages":[520],"id":"glossary-entry-to-destination-town-poem-quote","letter":"T"},{"term":"TOES (UNUSED)","definition":"Digits on the feet; the number of thousands of years ago Man appeared can be counted on the digits of two hands and one foot \"'with quite a few toes unused'\" (34).","notesPages":[521],"id":"glossary-entry-toes-unused","letter":"T"},{"term":"TOKYO","definition":"Japanese capital city; source of great mathematicians who learned from the Unfallen Ones (15); possible location for a noon-hour break in the Floating World (79).","notesPages":[521],"id":"glossary-entry-tokyo","letter":"T"},{"term":"TOLERANCE (FREE-AND-EASY)","definition":"The relaxed, permissive attitude of the Floating World, against which certain high-headed, poisonous \"blooms\" militated (81).","notesPages":[521],"id":"glossary-entry-tolerance-free-and-easy","letter":"T"},{"term":"TOM DOOLEY'S HEIR (SATRAP)","definition":"Satrap Saint Ledger inherited Tom Dooley's Island (159).","notesPages":[521],"id":"glossary-entry-tom-dooleys-heir-satrap","letter":"T"},{"term":"TOM DOOLEY'S HILL","definition":"Original name of the landform before it became an island surrounded by Inneall's Ocean (100, 116).","notesPages":[521],"id":"glossary-entry-tom-dooleys-hill","letter":"T"},{"term":"TOM DOOLEY'S ISLAND","definition":"The island formed when Inneall's Ocean surrounded Tom Dooley's Hill (100, 115, 116); location of Persimmon Manor (115); sinking rapidly into the Ocean (100, 116, 151, 159); site of Zchold's stoning (122); visited by Satrap's other yacht, The Filchman's Daughter (115); its remnants settle quaintly on Ocean Bottom (159).","notesPages":[521],"id":"glossary-entry-tom-dooleys-island","letter":"T"},{"term":"TOMBS (CENOTAPHS)","definition":"Small, human-sized structures central to the Whale Tau-Temple Complex (137).","notesPages":[521],"id":"glossary-entry-tombs-cenotaphs","letter":"T"},{"term":"TON (WORMS WEIGHED)","definition":"Experimental worms weighed more than a ton each (3).","notesPages":[521],"id":"glossary-entry-ton-worms-weighed","letter":"T"},{"term":"TONES (CODES AND)","definition":"Methods of communication used by The Three (5).","notesPages":[521],"id":"glossary-entry-tones-codes-and","letter":"T"},{"term":"TONGUE (IMPEDIMENT ON)","definition":"See IMPEDIMENT (ON TONGUE).","notesPages":[521],"id":"glossary-entry-tongue-impediment-on","letter":"T"},{"term":"TONGUES","definition":"Organs of speech or language; understood by Unfallen Ones (15); turtles' tongues contain cryptic information (75).","notesPages":[521],"id":"glossary-entry-tongues","letter":"T"},{"term":"TONGUES (TURTLES')","definition":"Contain uncanny, cryptic information written in the groove on the bottom side, readable like Chinese fortune cookies for total knowledge (75).","notesPages":[521],"id":"glossary-entry-tongues-turtles","letter":"T"},{"term":"TONS (CALKING COMPOUND)","definition":"Thirty tons required to waterproof Persimmon Manor (101, 116).","notesPages":[522],"id":"glossary-entry-tons-calking-compound","letter":"T"},{"term":"TONS (LIMESTONE)","definition":"Hundreds delivered by Satrap (106); thousands delivered by other firms (107).","notesPages":[522],"id":"glossary-entry-tons-limestone","letter":"T"},{"term":"TOOL (JIMMY)","definition":"Burglar's tool, originally called \"'burglar's jenny'\" (31).","notesPages":[522],"id":"glossary-entry-tool-jimmy","letter":"T"},{"term":"TOOLS","definition":"Implements used for work; part of Human Culture (39).","notesPages":[522],"id":"glossary-entry-tools","letter":"T"},{"term":"TOOTH-AND-NAIL (LAND IS RED IN)","definition":"Phrase from the Pirate Chantey epigraph, suggesting violent conflict on land (92).","notesPages":[522],"id":"glossary-entry-tooth-and-nail-land-is-red-in","letter":"T"},{"term":"TOP DECK (SHIP)","definition":"Uppermost deck of the Annabella Saint Ledger, where Inneall goes after encountering the Fates (114).","notesPages":[522],"id":"glossary-entry-top-deck-ship","letter":"T"},{"term":"TOP-DOG","definition":"Person or entity in a dominant position; Dolophonoi profession has always been top-dog (50); almost everybody favors the top-dog over the under-dog (50).","notesPages":[522],"id":"glossary-entry-top-dog","letter":"T"},{"term":"TOP HAT (RANDAL)","definition":"Formal hat worn by Ruddy Lord Randal when acting as circus ring- master (86).","notesPages":[522],"id":"glossary-entry-top-hat-randal","letter":"T"},{"term":"TOP LEVEL (COMPUTER UNDERSTANDING)","definition":"The highest level of sophistication where only other computers can understand a computer (33).","notesPages":[522],"id":"glossary-entry-top-level-computer-understanding","letter":"T"},{"term":"TOP RATES (PIRATE CREW PAY)","definition":"Inneall promises Satrap will pay her pirate crew at top rates (47).","notesPages":[522],"id":"glossary-entry-top-rates-pirate-crew-pay","letter":"T"},{"term":"TOP-SIDE STANDARDS (SLEEP)","definition":"Normal criteria for sleep as understood by surface dwellers; the Nine were asleep by these standards while diving (139).","notesPages":[522],"id":"glossary-entry-top-side-standards-sleep","letter":"T"},{"term":"TORPEDO FISH","definition":"Species of electric ray found in the Deep (139).","notesPages":[522],"id":"glossary-entry-torpedo-fish","letter":"T"},{"term":"TORPEDO LATERNA (LANTERN FISHES)","definition":"Name the novel gives the Lantern Fishes that illuminate Ocean Bottom (148, 150); this is not presented here as a verified taxonomic identification.","notesPages":[522],"id":"glossary-entry-torpedo-laterna-lantern-fishes","letter":"T"},{"term":"TORRENT","definition":"Swiftly flowing stream; crossed by the Unfallen Ones' stone bridge (15).","notesPages":[522],"id":"glossary-entry-torrent","letter":"T"},{"term":"TORRENTS","definition":"Violent flows of water; plague the hills around Second Eden throughout the year (16).","notesPages":[523],"id":"glossary-entry-torrents","letter":"T"},{"term":"TORTURED (GREGOR/IRIS)","definition":"Gregor McGregor tortured by fear for Gajah (85); Iris tortured by dreams and portents of Randal's and Inneall's deaths (84).","notesPages":[523],"id":"glossary-entry-tortured-gregor-iris","letter":"T"},{"term":"TOTAL DISBELIEF (ATTITUDE)","definition":"Stance towards Mankind advocated by Ananthropoi Computers (38).","notesPages":[523],"id":"glossary-entry-total-disbelief-attitude","letter":"T"},{"term":"TOTAL KNOWLEDGE","definition":"Complete understanding of everything; attainable, according to Dubu, by bears using their fourth brain lobe (75) or by reading turtles' tongues (75).","notesPages":[523],"id":"glossary-entry-total-knowledge","letter":"T"},{"term":"TOTAL SILENCE","definition":"Absolute quietness commanded by Alfred (108); would kill someone of Inneall's disposition (164).","notesPages":[523],"id":"glossary-entry-total-silence","letter":"T"},{"term":"TOTALITY (PLEROMA)","definition":"The fullness or entirety of existence, claimed by Alfred to be depicted in his sky-signs (111); refers to pleroma.","notesPages":[523],"id":"glossary-entry-totality-pleroma","letter":"T"},{"term":"TOTEM (APE FOR UNFALLEN)","definition":"The Ape had become a sort of code name or totem for the Unfallen People (14).","notesPages":[523],"id":"glossary-entry-totem-ape-for-unfallen","letter":"T"},{"term":"TOUCH (OF GUILT, DUBU)","definition":"Feeling experienced by Dubu for putting the Fates to sleep (128).","notesPages":[523],"id":"glossary-entry-touch-of-guilt-dubu","letter":"T"},{"term":"TOUCH (OF THE MYSTIC, SATRAP)","definition":"Quality possessed by Satrap Saint Ledger, enabling understanding of concepts like the 'jog in the road' (93).","notesPages":[523],"id":"glossary-entry-touch-of-the-mystic-satrap","letter":"T"},{"term":"TOUCH (RHINOID LOOK, ETC.)","definition":"A slight presence or hint of a characteristic; people with a touch of the rhinoid/typhonan/gargoyle- titan look (44).","notesPages":[523],"id":"glossary-entry-touch-rhinoid-look-etc","letter":"T"},{"term":"TOUCHED (CARCAJOU BY DOLOPHONOS)","definition":"The Mega Dolophonos touched Carcajou's shoulder, causing sparks and pain (94).","notesPages":[523],"id":"glossary-entry-touched-carcajou-by-dolophonos","letter":"T"},{"term":"TOUCHED (THIGH)","definition":"Act performed by the angelic wrestler in the novel’s Book of Jasher passage about Carcajou, echoing Jacob’s wrestling encounter, causing permanent change (88).","notesPages":[523],"id":"glossary-entry-touched-thigh","letter":"T"},{"term":"TOUGHEST SUBSTANCE (WOTTO-METAL)","definition":"Wotto metal described as the strongest material known (127, 129).","notesPages":[523],"id":"glossary-entry-toughest-substance-wotto-metal","letter":"T"},{"term":"TOUGHS (COMMON)","definition":"Ordinary aggressive individuals who arrived to investigate the underground facilities (44).","notesPages":[524],"id":"glossary-entry-toughs-common","letter":"T"},{"term":"TOWERING HOLINESS (ARCHANGEL)","definition":"Quality attributed to Archangels, partly derived from their terrifying strangeness (17).","notesPages":[524],"id":"glossary-entry-towering-holiness-archangel","letter":"T"},{"term":"TOWERING MENTALITY (HENRYETTA)","definition":"Henryetta's powerful intellect, used to set fires remotely (96).","notesPages":[524],"id":"glossary-entry-towering-mentality-henryetta","letter":"T"},{"term":"TOWNS","definition":"Human settlements; visited by Satrap (implied) (113); Empress Elephants served as mayors (92); scene of horrifying fires (146).","notesPages":[524],"id":"glossary-entry-towns","letter":"T"},{"term":"TOWNS (HUNDRED DIFFERENT, LIGHTNING)","definition":"Locations worldwide where lightning bolts simultaneously struck and killed Axel's Apes in zoos (21).","notesPages":[524],"id":"glossary-entry-towns-hundred-different-lightning","letter":"T"},{"term":"TOWNS (MAYOR OF)","definition":"Position held by Empress Elephants in India (92).","notesPages":[524],"id":"glossary-entry-towns-mayor-of","letter":"T"},{"term":"TOWNS-NO-MORE","definition":"Devastated state of four towns within a hundred miles after horrifying fires, possibly set by Henryetta (146).","notesPages":[524],"id":"glossary-entry-towns-no-more","letter":"T"},{"term":"TOY (AMHS AS)","definition":"Original purpose for making AMH Computers was partly as a sort of toy, before they surpassed stationary computers (32).","notesPages":[524],"id":"glossary-entry-toy-amhs-as","letter":"T"},{"term":"TRABANTS (MARBLE)","definition":"Architectural elements, alongside columns and lintels, made of marble by the Whales (136).","notesPages":[524],"id":"glossary-entry-trabants-marble","letter":"T"},{"term":"TRACKS (BEAR)","definition":"Trails left by bears in the Winding Stair Mountains; following them leads to bears who know everything (75).","notesPages":[524],"id":"glossary-entry-tracks-bear","letter":"T"},{"term":"TRACKS (THIRD)","definition":"See THIRD TRACKS.","notesPages":[524],"id":"glossary-entry-tracks-third","letter":"T"},{"term":"TRADE (FREE-TRADE WORLD)","definition":"Economic condition of the Floating World (79).","notesPages":[524],"id":"glossary-entry-trade-free-trade-world","letter":"T"},{"term":"TRADE (HISTORIAN BY)","definition":"Livius Secundus's profession (115).","notesPages":[524],"id":"glossary-entry-trade-historian-by","letter":"T"},{"term":"TRADITION (HOLY BLAZE)","definition":"Custom of enjoying the nightly fire in Ape Caverns (68).","notesPages":[524],"id":"glossary-entry-tradition-holy-blaze","letter":"T"},{"term":"TRAGEDY (OLD GREEK)","definition":"See OLD GREEK TRAGEDY.","notesPages":[525],"id":"glossary-entry-tragedy-old-greek","letter":"T"},{"term":"TRAIN OF EVIL","definition":"The entire sequence of negative consequences originating from the misuse of free will (35).","notesPages":[525],"id":"glossary-entry-train-of-evil","letter":"T"},{"term":"TRAITOROUS (CARCAJOU)","definition":"Characteristic attributed to Carcajou the wolverine (64).","notesPages":[525],"id":"glossary-entry-traitorous-carcajou","letter":"T"},{"term":"TRANS-ANIMAL TALENTS","definition":"Abilities (speech, abstract thought, role- playing) exceeding normal animal capacities, emerging in geniused animals (93).","notesPages":[525],"id":"glossary-entry-trans-animal-talents","letter":"T"},{"term":"TRANS-LOCATION","definition":"Instantaneous travel between locations; talent possessed by all Axel's Apes (21); used by India Elephants (95, 128) and migrating birds (95); said to be documented in humans by the novel’s Big Book of Strange Happenings citation (95).","notesPages":[525],"id":"glossary-entry-trans-location","letter":"T"},{"term":"TRANSCENDENT INTELLIGENCE","definition":"Extremely high level of intellect; imagined being poured into the Unfallen Ones/Gargoyles, making their faces overpoweringly beautiful (17).","notesPages":[525],"id":"glossary-entry-transcendent-intelligence","letter":"T"},{"term":"TRANSFERENCE OF POWER (OCEAN)","definition":"Mechanism allowing Inneall's Ocean to survive independently of her; not yet set up, meaning the Ocean would reverse if she died now (161).","notesPages":[525],"id":"glossary-entry-transference-of-power-ocean","letter":"T"},{"term":"TRANSFORMATION (CARCAJOU)","definition":"Change of form; Carcajou transforms between wolverine, human, and man-devil forms (73).","notesPages":[525],"id":"glossary-entry-transformation-carcajou","letter":"T"},{"term":"TRANSMISSION (INNEALL'S MALFUNCTION)","definition":"Inneall initially claims her inability to record is due to a minor malfunction (164).","notesPages":[525],"id":"glossary-entry-transmission-innealls-malfunction","letter":"T"},{"term":"TRANSMISSION (MIND-)","definition":"Method used by Inneall for recording logs (164).","notesPages":[525],"id":"glossary-entry-transmission-mind","letter":"T"},{"term":"TRANSMIT (NATURES)","definition":"AMHs could potentially transmit their natures via manufactured genes/chromosomes (32).","notesPages":[525],"id":"glossary-entry-transmit-natures","letter":"T"},{"term":"TRANSMIT (SIGNAL)","definition":"Send out; awakened Apes transmit signal to others worldwide (51).","notesPages":[525],"id":"glossary-entry-transmit-signal","letter":"T"},{"term":"TRANSPARENT COVER","definition":"The clear dome over The Three's habitat (3, 4).","notesPages":[526],"id":"glossary-entry-transparent-cover","letter":"T"},{"term":"TRANSPARENT (ODD FELLOWS)","definition":"See-through quality of the beings who tempted Dubu (155).","notesPages":[525],"id":"glossary-entry-transparent-odd-fellows","letter":"T"},{"term":"TRANSPARENT TUBES","definition":"Hardly visible conduits within the waterfalls of The Three's habitat, recirculating water (3, 4).","notesPages":[526],"id":"glossary-entry-transparent-tubes","letter":"T"},{"term":"TRAP-DOOR (GALLOWS)","definition":"Hinged section of the gallows platform that drops open to hang the condemned; whanged open under Donatus O'Reily (157).","notesPages":[526],"id":"glossary-entry-trap-door-gallows","letter":"T"},{"term":"TRAPPED (DOLOPHONOS)","definition":"The Dolophonos claims he and his kind are trapped in their damnable mixed nature (87).","notesPages":[526],"id":"glossary-entry-trapped-dolophonos","letter":"T"},{"term":"TRAPPED (LIKE PEOPLE IN MURDER HOUSE)","definition":"Dubu compares their situation in the potentially haunted Persimmon Manor to this trope (124).","notesPages":[526],"id":"glossary-entry-trapped-like-people-in-murder-house","letter":"T"},{"term":"TRAVEL (FREE-TRAVEL WORLD)","definition":"Condition of the Floating World allowing easy movement, e.g., Australia to NYC commute (79).","notesPages":[526],"id":"glossary-entry-travel-free-travel-world","letter":"T"},{"term":"TRAVELED (IN AFRICA)","definition":"Gypsies traveled in Africa to reach Second Eden (13).","notesPages":[526],"id":"glossary-entry-traveled-in-africa","letter":"T"},{"term":"TRAVELERS (HOTEL FOR)","definition":"Establishment in Ape Alley contained a hotel for travelers (46).","notesPages":[526],"id":"glossary-entry-travelers-hotel-for","letter":"T"},{"term":"TRAVERSING (PASSAGE)","definition":"Moving through the Executive Passage swiftly (144, 147).","notesPages":[526],"id":"glossary-entry-traversing-passage","letter":"T"},{"term":"TREACHERY","definition":"Betrayal of trust; Lutin detects the smell of treachery in the crows-nest (143, 149); Invisible Alfred embodies treachery (149).","notesPages":[526],"id":"glossary-entry-treachery","letter":"T"},{"term":"TREADMILL","definition":"Device formerly powered by animal labor; jenny asses used more than jacks (31).","notesPages":[526],"id":"glossary-entry-treadmill","letter":"T"},{"term":"TREATISE ON DIFFERENTIAL EQUATIONS (BOOLE)","definition":"George Boole's 1859 mathematical work, jokingly said by the novel to have been written to give Babbage’s Analytical Engine “something to think about” (25); refers to Treatise on Differential Equations.","notesPages":[527],"id":"glossary-entry-treatise-on-differential-equations-boole","letter":"T"},{"term":"TREATMENT (ENVIRONMENT SURVIVAL)","definition":"Some environments cannot survive the cannibalizing treatment inflicted by AMHs creating props (27).","notesPages":[527],"id":"glossary-entry-treatment-environment-survival","letter":"T"},{"term":"TREE (CAROB)","definition":"See CAROB TREE.","notesPages":[527],"id":"glossary-entry-tree-carob","letter":"T"},{"term":"TREE (PERSIMMON)","definition":"See PERSIMMON WOOD.","notesPages":[527],"id":"glossary-entry-tree-persimmon","letter":"T"},{"term":"TREE (WE ARE THE TREE)","definition":"Metaphor used by Dubu: Henryetta’s privileged company are only the top leaf, while the unwashed commoners are the whole tree (63).","notesPages":[527],"id":"glossary-entry-tree-we-are-the-tree","letter":"T"},{"term":"TREES","definition":"Woody perennial plants; planted ornamentally at strip pits (24, 91); aged and blighted trees cut from orchard (metaphor) (81); every leaf on every tree (71).","notesPages":[527],"id":"glossary-entry-trees","letter":"T"},{"term":"TREES (MOUNTAIN YEW)","definition":"Source of boughs used to cover Riesin's body (95).","notesPages":[527],"id":"glossary-entry-trees-mountain-yew","letter":"T"},{"term":"TRESPASSING","definition":"Entering property without permission; Inneall accuses Satrap's yacht of trespassing on her Ocean (47).","notesPages":[527],"id":"glossary-entry-trespassing","letter":"T"},{"term":"TRESTLES (PAINTING)","definition":"Frameworks used to support planks for painters; dangled over the side by the Intrepid Nine to paint the ship's hull (104).","notesPages":[527],"id":"glossary-entry-trestles-painting","letter":"T"},{"term":"TRIBUNAL (IRREGULAR/IRRESPONSIBLE/UNAUTHORIZED)","definition":"Defining characteristics of a Kangaroo court (79).","notesPages":[527],"id":"glossary-entry-tribunal-irregular-irresponsible-unauthorized","letter":"T"},{"term":"TRICKERY (ALFRED'S)","definition":"Deception employed by Invisible Alfred; Schimp notes there was no bottom to it (149).","notesPages":[527],"id":"glossary-entry-trickery-alfreds","letter":"T"},{"term":"TRICKS (ALFRED'S VOICE)","definition":"Vocal effects Alfred can produce, like whip-popping sounds (110).","notesPages":[528],"id":"glossary-entry-tricks-alfreds-voice","letter":"T"},{"term":"TRICKS (ATROPOS COUNTERS)","definition":"Dubu suspects Atropos has ways to defeat countermeasures like wotto-metal threads (127).","notesPages":[528],"id":"glossary-entry-tricks-atropos-counters","letter":"T"},{"term":"TRICKY (ALFRED)","definition":"Deceitful or difficult to handle; Carcajou's assessment of Invisible Alfred as second cook (114).","notesPages":[527],"id":"glossary-entry-tricky-alfred","letter":"T"},{"term":"TRICKY (LUAS'S GROUP)","definition":"Luas says several of his companions are tricky as he departs (103).","notesPages":[527],"id":"glossary-entry-tricky-luass-group","letter":"T"},{"term":"TRIFLES","definition":"Things of little importance; removing mountains considered a trifle by preternatural powers (112); disputes among pirates dismissed as trifles by Satrap (100).","notesPages":[528],"id":"glossary-entry-trifles","letter":"T"},{"term":"TRIGGER (WAKENING ACTION)","definition":"The anticipated sequence in which Axel would wake the other Apes in the Cenaculum and they would awaken the rest worldwide (65, 142). His murder interrupts it (147–148).","notesPages":[528],"id":"glossary-entry-trigger-wakening-action","letter":"T"},{"term":"TRIGGERING (SECOND HUMANITY)","definition":"The worldwide awakening expected to follow Axel’s awakening of the Cenaculum sleepers; it does not occur in the narrated climax (65, 142, 147–148).","notesPages":[528],"id":"glossary-entry-triggering-second-humanity","letter":"T"},{"term":"TRIPLE CONDOMINIUM","definition":"Shared living suite occupied by Satrap Saint Ledger, Livius Secundus, and Felix Culebra y Columba in Structo Lane (71).","notesPages":[528],"id":"glossary-entry-triple-condominium","letter":"T"},{"term":"TRIPLICATE (KNOWLEDGE IN DUBU)","definition":"Dubu claims the three stores of total knowledge are contained in triplicate within three lobes of her brain (75).","notesPages":[528],"id":"glossary-entry-triplicate-knowledge-in-dubu","letter":"T"},{"term":"TRIPS","definition":"One of the alternative names ('prowls', 'antics', etc.) for the multi-track media format (6).","notesPages":[528],"id":"glossary-entry-trips","letter":"T"},{"term":"TRIVIALITY","definition":"Lack of seriousness or importance; questioning \"'what are humans?'\" is declared an exercise in triviality by an AMH Computer (38).","notesPages":[528],"id":"glossary-entry-triviality","letter":"T"},{"term":"TROOP (CIRCUS)","definition":"The Eleven had the air of a circus troupe (72).","notesPages":[528],"id":"glossary-entry-troop-circus","letter":"T"},{"term":"TROUBLE","definition":"Difficulty or problems; caused by inept members (81); saved by Zchold turning himself in (158).","notesPages":[528],"id":"glossary-entry-trouble","letter":"T"},{"term":"TROUBLE-MAKERS (OVER-ENDOWED MALES)","definition":"Potential role of powerful male animals like Alpha, making zoos skittish (20).","notesPages":[528],"id":"glossary-entry-trouble-makers-over-endowed-males","letter":"T"},{"term":"TROUBLE (WORLD)","definition":"The narrative’s satirical account says that the eliminated eighty-seven percent had caused ninety-seven percent of the trouble (81).","notesPages":[528],"id":"glossary-entry-trouble-world","letter":"T"},{"term":"TROUGH (FEED-)","definition":"See FEED-TROUGH.","notesPages":[529],"id":"glossary-entry-trough-feed","letter":"T"},{"term":"TROUT","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[529],"id":"glossary-entry-trout","letter":"T"},{"term":"TRUE","definition":"Conforming to fact or reality; often used to assert the veracity of \"awkward\" or legendary claims (e.g., Axel's beliefs, 11; mechanical donkeys, 31); used regarding accurate aim (83) or breeding (42).","notesPages":[529],"id":"glossary-entry-true","letter":"T"},{"term":"TRUE CHILD OF WONDER (AXEL)","definition":"Inscription on Axel the Ape's cenotaph (148).","notesPages":[529],"id":"glossary-entry-true-child-of-wonder-axel","letter":"T"},{"term":"TRUE DISSERTATION","definition":"Assertion of accuracy regarding accounts of species origins (22, 33, 42).","notesPages":[529],"id":"glossary-entry-true-dissertation","letter":"T"},{"term":"TRUE FORM (CARCAJOU'S)","definition":"Revealed by Luas to be human, not wolverene, after their wrestling match (88).","notesPages":[529],"id":"glossary-entry-true-form-carcajous","letter":"T"},{"term":"TRUE FORTUNE-TELLING","definition":"An AMH maintains that it can only be done between different species (30).","notesPages":[529],"id":"glossary-entry-true-fortune-telling","letter":"T"},{"term":"TRUE GUARDS","definition":"Keepers who will guard faithfully, contrasted with false guards (68).","notesPages":[529],"id":"glossary-entry-true-guards","letter":"T"},{"term":"TRUE NARRATIONS","definition":"Accounts claimed to be accurate despite potential extravagances (104).","notesPages":[529],"id":"glossary-entry-true-narrations","letter":"T"},{"term":"TRUE PREDICTION","definition":"Accurate forecast; easier for Computers to give true predictions always (30, 31).","notesPages":[529],"id":"glossary-entry-true-prediction","letter":"T"},{"term":"TRUE PREDICTIONS","definition":"Accurate forecasts (30).","notesPages":[529],"id":"glossary-entry-true-predictions","letter":"T"},{"term":"TRUFFLES (EXPERIMENTAL)","definition":"Fungi growing under the surface in The Three's habitat, with a strong enticing odor; could be sucked easily like milk (4).","notesPages":[529],"id":"glossary-entry-truffles-experimental","letter":"T"},{"term":"TRUMPET (GAJAH)","definition":"Vocalize like an elephant; Gajah trumpets faintly from the womb (56).","notesPages":[529],"id":"glossary-entry-trumpet-gajah","letter":"T"},{"term":"TRUMPETS (CELESTIAL)","definition":"One hundred thousand heavenly instruments, each a parasang long, which folk memory recalls blowing a salute to Man at his appearance (34).","notesPages":[529],"id":"glossary-entry-trumpets-celestial","letter":"T"},{"term":"TRUNK (ELEPHANT)","definition":"Elephant's long prehensile nose; Gajah will show hers eventually (63); Riesin uses hers to gather bushes (94).","notesPages":[530],"id":"glossary-entry-trunk-elephant","letter":"T"},{"term":"TRUSTED PIRATE","definition":"Lanternjaw wants a trusted pirate to accompany the children into the Cenaculum; he must stay in the crows-nest (145).","notesPages":[530],"id":"glossary-entry-trusted-pirate","letter":"T"},{"term":"TRUTH","definition":"Accordance with fact or reality; element in legends (37); difficulty arriving at it (12).","notesPages":[530],"id":"glossary-entry-truth","letter":"T"},{"term":"TRY AGAIN (THEOS)","definition":"The Theos resolves to try again after creating the flawed seventh creature (Mankind) (37).","notesPages":[530],"id":"glossary-entry-try-again-theos","letter":"T"},{"term":"TRYING (TO SAVE SERPENT'S EGG)","definition":"Donatus O'Reily's hangable misdemeanor (118); refers to Serpent's Egg.","notesPages":[530],"id":"glossary-entry-trying-to-save-serpents-egg","letter":"T"},{"term":"TUBES (BRASS)","definition":"Component material of the steam calliope (85).","notesPages":[530],"id":"glossary-entry-tubes-brass","letter":"T"},{"term":"TUBES (TRANSPARENT)","definition":"See TRANSPARENT TUBES.","notesPages":[530],"id":"glossary-entry-tubes-transparent","letter":"T"},{"term":"TULSA, OKLAHOMA","definition":"City where R.A. Lafferty lived most of his life (publisher’s biographical note).","notesPages":[530],"id":"glossary-entry-tulsa-oklahoma","letter":"T"},{"term":"TUMBLED (LIMESTONE BLOCKS)","definition":"Hundreds of blocks tumbled and slid to the Ocean Bottom from the base of Tom Dooley's Island (163).","notesPages":[530],"id":"glossary-entry-tumbled-limestone-blocks","letter":"T"},{"term":"TUMBLING (MOUNTAINS)","definition":"Metaphorical description of how mountains might fall (112).","notesPages":[530],"id":"glossary-entry-tumbling-mountains","letter":"T"},{"term":"TUMBLING (WRITING)","definition":"Description of how \"whole mountains-full of writing\" will emerge from the burst Acorn (74).","notesPages":[530],"id":"glossary-entry-tumbling-writing","letter":"T"},{"term":"TUNE (INNEALL'S CHANT)","definition":"The little repetitive song Inneall chants to convince herself she is not conscious (23).","notesPages":[530],"id":"glossary-entry-tune-innealls-chant","letter":"T"},{"term":"TUNNELS (LONG, DUG BY LUTIN)","definition":"Subterranean passages dug secretly at night by Lutin the pythoness, used for advantage in lacrosse; entrances well camouflaged (65).","notesPages":[530],"id":"glossary-entry-tunnels-long-dug-by-lutin","letter":"T"},{"term":"TUNS (RUM)","definition":"Large casks for storing rum, mentioned alongside hogsheads, butts, and pipes (99).","notesPages":[530],"id":"glossary-entry-tuns-rum","letter":"T"},{"term":"TURBULENT (ISLAND SINKING)","definition":"The waters will be very turbulent when Tom Dooley's Island sinks (152).","notesPages":[530],"id":"glossary-entry-turbulent-island-sinking","letter":"T"},{"term":"TURBULENT WAVES","definition":"Destructive waves generated by high-headed, divergent excellence; dangerous to the Floating World (81).","notesPages":[531],"id":"glossary-entry-turbulent-waves","letter":"T"},{"term":"TURKEY","definition":"Country entered by Gypsy bands led by golden apes (13).","notesPages":[531],"id":"glossary-entry-turkey","letter":"T"},{"term":"TURN (COMPUTERS' AGAIN)","definition":"Inneall asks when it will be computers' turn again to keep the logs (164).","notesPages":[531],"id":"glossary-entry-turn-computers-again","letter":"T"},{"term":"TURNED UPSIDE DOWN (NATURAL ORDER)","definition":"Result predicted by Maritain when the State develops its vicious idea fully (78).","notesPages":[531],"id":"glossary-entry-turned-upside-down-natural-order","letter":"T"},{"term":"TURRET (ANGKOR WAT)","definition":"Small tower on the temple; water seemed to gush from every turret (132); refers to Angkor Wat.","notesPages":[531],"id":"glossary-entry-turret-angkor-wat","letter":"T"},{"term":"TURRETS (WHALE TEMPLE-CITY)","definition":"Architectural features in the Whale constructions, aligned with stones to clock celestial events like the rising of the Dog Star (137); refers to Whale Temple-City.","notesPages":[531],"id":"glossary-entry-turrets-whale-temple-city","letter":"T"},{"term":"TURTLE MEAT (LIVE-)","definition":"Flesh from giant ocean turtles kept alive in the ship's hold, used as food for the pirates (101).","notesPages":[531],"id":"glossary-entry-turtle-meat-live","letter":"T"},{"term":"TURTLE SOUP","definition":"Dish made from turtles; Lanternjaw implies there are more things in the world than just turtle soup (99).","notesPages":[531],"id":"glossary-entry-turtle-soup","letter":"T"},{"term":"TURTLE-SOUP FACTORIES","definition":"Places where turtles are processed; Dubu claims that workers there are very smart because they read information on turtles’ tongues (75).","notesPages":[531],"id":"glossary-entry-turtle-soup-factories","letter":"T"},{"term":"TURTLE STEAK","definition":"Meat from turtles; Lanternjaw implies there are more things than this (99).","notesPages":[531],"id":"glossary-entry-turtle-steak","letter":"T"},{"term":"TURTLES (GIANT OCEAN-)","definition":"More than three hundred kept alive as live provender in the aft hold of the Annabella (99).","notesPages":[531],"id":"glossary-entry-turtles-giant-ocean","letter":"T"},{"term":"TURTLES' TONGUES","definition":"Dubu claims that their underside grooves contain uncanny, cryptic information readable like Chinese fortune cookies (75).","notesPages":[531],"id":"glossary-entry-turtles-tongues","letter":"T"},{"term":"Twain, Mark","definition":"American author cited for a playful boast about using meridians and parallels as seines to drag the Atlantic for whales, scratching his head with lightning, and putting himself to sleep with thunder (131).","notesPages":[531],"id":"glossary-entry-twain-mark","letter":"T"},{"term":"TWELVE","definition":"Foundation number of the world; questioned if it can be enlarged (112). See entries under THE TWELVE, ELITE TWELVE CONTEMPORARIES, GREAT TWELVE CONTEMPORARIES.","notesPages":[532],"id":"glossary-entry-twelve","letter":"T"},{"term":"TWELVE CONSTELLATIONS","definition":"The traditional signs of the Zodiac depicted by Alfred (111).","notesPages":[532],"id":"glossary-entry-twelve-constellations","letter":"T"},{"term":"TWELVE-MONTHS MISDEMEANORS","definition":"After the initial period, the hanging ritual for Natural Nobility members becomes a yearly sweep covering offenses committed over the previous twelve months (118).","notesPages":[532],"id":"glossary-entry-twelve-months-misdemeanors","letter":"T"},{"term":"TWELVE (STATIONS, APOSTLES)","definition":"Alfred identifies the twelve Apostles as the true entities behind the twelve zodiacal stations (111).","notesPages":[532],"id":"glossary-entry-twelve-stations-apostles","letter":"T"},{"term":"TWELVE-SYLLABLE NAME (COLOR)","definition":"Length of the Malay word for the unique living green color on Whale constructions (137).","notesPages":[532],"id":"glossary-entry-twelve-syllable-name-color","letter":"T"},{"term":"TWENTIETH CENTURY","definition":"Period when Axel Grindstone held awkward beliefs (11); end of major computer developments before modern times (25); Gammon Lanternjaw pirated well into it (98).","notesPages":[532],"id":"glossary-entry-twentieth-century","letter":"T"},{"term":"TWENTY-FOUR HOURS","definition":"Length of a day; Prester John wakes for only 15 minutes out of every twenty-four (12); time elapsed for Axel's companions to carry him back to Arba Mench (16); duration Jack Flannagan's cafe is open daily (152); Alpha spends eighteen hours out of twenty-four in prayer/contemplation (51).","notesPages":[532],"id":"glossary-entry-twenty-four-hours","letter":"T"},{"term":"TWENTY-FOUR MINUTES (WARNING)","definition":"Amount of evasive action time Henryetta claims she can take after cock-crow midnight before being vulnerable (147).","notesPages":[532],"id":"glossary-entry-twenty-four-minutes-warning","letter":"T"},{"term":"TWENTY METERS (SKY-COVER HEIGHT)","definition":"Height of the transparent dome over The Three's habitat (4).","notesPages":[532],"id":"glossary-entry-twenty-meters-sky-cover-height","letter":"T"},{"term":"TWENTY MINUTES (BEFORE ONE)","definition":"Time when the Midnight Cock woke Donatus O'Reily's uncle for work (156).","notesPages":[532],"id":"glossary-entry-twenty-minutes-before-one","letter":"T"},{"term":"TWENTY-THREE HOURS","definition":"Duration the traditional holy blaze in Ape Caverns would be enjoyed after being lit by lightning (68).","notesPages":[532],"id":"glossary-entry-twenty-three-hours","letter":"T"},{"term":"TWENTY-TWO PAIRS (AUTOSOMES)","definition":"Number of non-sex chromosomes possessed by both Humans and Unfallen People (18).","notesPages":[532],"id":"glossary-entry-twenty-two-pairs-autosomes","letter":"T"},{"term":"TWICE","definition":"Occurring two times; Inneall claims to be twice as conscious/everything as the boys (23); denials often double affirmations (114).","notesPages":[533],"id":"glossary-entry-twice","letter":"T"},{"term":"TWILIGHT LIMES","definition":"Inneall's evocative term for the strange, miming- mechanostic level of mind possessed only by machines (59).","notesPages":[533],"id":"glossary-entry-twilight-limes","letter":"T"},{"term":"TWIN (THE, THOMAS)","definition":"Apostle Thomas's designation in the Gospels, explained by Alfred as a correspondence to Gemini (the Twins), a claim made in his sermon rather than established apostolic history (111).","notesPages":[533],"id":"glossary-entry-twin-the-thomas","letter":"T"},{"term":"TWINS (GEMINI)","definition":"See GEMINI.","notesPages":[533],"id":"glossary-entry-twins-gemini","letter":"T"},{"term":"TWO METERS AND TEN CENTIMETERS (TITAN SKELETON HEIGHT)","definition":"Height of the human 'Titan Skeleton' at the Field Museum (44).","notesPages":[533],"id":"glossary-entry-two-meters-and-ten-centimeters-titan-skeleton-height","letter":"T"},{"term":"TWO METERS (AXEL'S APES HEIGHT)","definition":"Adult Axel’s Apes average just over two meters tall (44).","notesPages":[533],"id":"glossary-entry-two-meters-axels-apes-height","letter":"T"},{"term":"TWO METERS THICK (EGG)","definition":"Dimension of the Big Egg that Lutin claims to have produced (154–155).","notesPages":[533],"id":"glossary-entry-two-meters-thick-egg","letter":"T"},{"term":"TWO STRINGS (GOD'S BOW)","definition":"Feature of the bow held by God in the Al-Waghe cliff mural, symbolizing preparedness with a second option (11).","notesPages":[533],"id":"glossary-entry-two-strings-gods-bow","letter":"T"},{"term":"TWO-TRACK PROWLS","definition":"Media format with only sound and visual tracks, lacking the third (printed word) track (6).","notesPages":[533],"id":"glossary-entry-two-track-prowls","letter":"T"},{"term":"TYPE (JUNGLE-BOY)","definition":"Archetype embodied by Lord Randal (123).","notesPages":[533],"id":"glossary-entry-type-jungle-boy","letter":"T"},{"term":"TYPE (STRONG-NOSED ARYAN)","definition":"Physical description of Satrap's Asiatic employee (94).","notesPages":[533],"id":"glossary-entry-type-strong-nosed-aryan","letter":"T"},{"term":"TYPHONAN LOOK","definition":"Facial characteristic associated with the monster Typhon; possessed by certain rare humans, similar to the gargoyle- titan look (44).","notesPages":[533],"id":"glossary-entry-typhonan-look","letter":"T"},{"term":"TYRANNIES (INTELLECTUAL)","definition":"Oppressive dominance by human masters (\"The Tarquins\") from which Ambulatory Computers freed themselves, according to Livius Secundus (70).","notesPages":[533],"id":"glossary-entry-tyrannies-intellectual","letter":"T"},{"term":"U.S. (SLANG)","definition":"Origin designation provided by Webster's Collegiate for the term \"Kangaroo court\" (79).","notesPages":[534],"id":"glossary-entry-u-s-slang","letter":"U"},{"term":"UGH!","definition":"Exclamation predicted by Inneall as the reaction people would have upon seeing the Three Fates playing with baby snakes (160).","notesPages":[534],"id":"glossary-entry-ugh","letter":"U"},{"term":"UGLY","definition":"Unpleasant or repulsive in appearance; used by Axel Grindstone to describe the Unfallen People/Gargoyles (\"ugliest apes this side of hell\") (17); Inneall finds the baby pythons rather ugly when young (160); term applied repeatedly to the Three Fates (103, 114, 126, 127, 128, 141) and the hidden room they inhabit (103).","notesPages":[534],"id":"glossary-entry-ugly","letter":"U"},{"term":"UGLY (FACES, GARGOYLE)","definition":"Shockingly ugly appearance of Gargoyle faces at first sight, diminishing upon second and third sight (21).","notesPages":[534],"id":"glossary-entry-ugly-faces-gargoyle","letter":"U"},{"term":"ULTIMATE ANSWERS","definition":"The final, definitive solutions to the most profound questions of existence; sought by Satrap Saint Ledger (70); Dubu claims they are written inside a single Acorn (74).","notesPages":[534],"id":"glossary-entry-ultimate-answers","letter":"U"},{"term":"ULTIMATE EGG","definition":"Dubu’s name for the mysterious Big Egg that appears while Lutin and the midwife sleep (155). Inneall detects mechanical components and something living inside it (155–156); Lutin’s actual offspring are three baby pythons (160).","notesPages":[534],"id":"glossary-entry-ultimate-egg","letter":"U"},{"term":"ULTIMATE IN FRIENDLINESS (MARINO)","definition":"Superlative description of Marino the Seal's personable nature (60).","notesPages":[534],"id":"glossary-entry-ultimate-in-friendliness-marino","letter":"U"},{"term":"ULTIMATUM","definition":"A final demand or statement of terms; delivered by Inneall to Satrap Saint Ledger demanding his yacht (47); Satrap initially dismisses it as merely a \"penultimatum\" (47).","notesPages":[534],"id":"glossary-entry-ultimatum","letter":"U"},{"term":"UMBRELLAS (SIDEWALK CAFES)","definition":"Colorful accessories providing shade at the Sidewalk Cafes along the shore of Heart's Desire Cove; noted as being \"all the colors that are hidden in sunshine\" (58).","notesPages":[534],"id":"glossary-entry-umbrellas-sidewalk-cafes","letter":"U"},{"term":"UNFALLEN CATEGORY","definition":"State of primal innocence or non- corruption; the Axel's Apes' weakness for wine almost took them out of this category (46).","notesPages":[535],"id":"glossary-entry-unfallen-category","letter":"U"},{"term":"UNFALLEN FOLKS","definition":"Term used for the inhabitants of Second Eden, seen by Axel Grindstone from a distance appearing \"like glowing gold\" (16); their faces, seen up close, cause Axel's breakdown (16-17). See also UNFALLEN PEOPLE.","notesPages":[535],"id":"glossary-entry-unfallen-folks","letter":"U"},{"term":"UNFALLEN MASTERS","definition":"Expert craftsmen among the Unfallen People who, according to legend, taught advanced stonework to nine European master masons (13).","notesPages":[535],"id":"glossary-entry-unfallen-masters","letter":"U"},{"term":"UNFALLEN ONES","definition":"Inhabitants of Second Eden; experts in smithery, stonework, and mathematics (15); speak measuredly, weigh words, never use dishonest words (15); instruct great mathematicians and local schoolchildren alike (15); revealed to be the Gargoyles, possessing Gargoyle faces (17); considered by Ansel Grindstone as God's \"alternatives\" to humanity (17); referred to as \"blue-eyed yellow apes\" by would-be exploiters (18). See also UNFALLEN PEOPLE.","notesPages":[535],"id":"glossary-entry-unfallen-ones","letter":"U"},{"term":"UNFALLEN PATRIARCHS","definition":"The original forefathers of the Unfallen People; includes Magog (12).","notesPages":[535],"id":"glossary-entry-unfallen-patriarchs","letter":"U"},{"term":"UNFALLEN PEOPLE","definition":"The inhabitants of Second Eden, also called 'The People Who Had Not Fallen' (11); created 30 years after Adam (12); immune to natural death, disease, and aging (12); can be killed by accident, lightning, or murder (but only by fallen people) (12); sometimes emerge to help mankind (12); cross between Africa and Arabia via the Ape Bridge (12); associated with legends of building Cathedrals (leaving Gargoyles as signs), operating circuses, and teaching trades to Gypsies (13-14); referred to by locals as Smithy Apes or Stone-Master Apes (13); possess 22 pairs of autosomes and one pair of sex chromosomes, which the characters cite as evidence that they are men (18). A chromosome count alone does not establish species identity. See also UNFALLEN ONES, GARGOYLES.","notesPages":[535],"id":"glossary-entry-unfallen-people","letter":"U"},{"term":"UNFATHOMED CAVES (OCEAN)","definition":"Deep, unexplored recesses of the sea (131).","notesPages":[535],"id":"glossary-entry-unfathomed-caves-ocean","letter":"U"},{"term":"UNFEELING (SUPREME PEOPLE CHARGE)","definition":"False accusation leveled against the \"old supreme people\" (regular, non-ethnic humans) that led to their mass murder (6).","notesPages":[535],"id":"glossary-entry-unfeeling-supreme-people-charge","letter":"U"},{"term":"UNFETTERED (MALE APE)","definition":"Unrestrained; describes Alpha when he follows the captured Apes, contrasted with the 500 taken away in fetters (20).","notesPages":[536],"id":"glossary-entry-unfettered-male-ape","letter":"U"},{"term":"UNFRAMED PICTURES","definition":"The natural scenes of the outdoor world, perceived by The Three as kaleidoscopes; considered better than the formal pictures inside the house (5, 8).","notesPages":[536],"id":"glossary-entry-unframed-pictures","letter":"U"},{"term":"UNFURLED (COURTS IRREGULAR)","definition":"Metaphorical description (like a flag or banner) of the Kangaroo's unconventional operations being displayed (78).","notesPages":[536],"id":"glossary-entry-unfurled-courts-irregular","letter":"U"},{"term":"UNGUARDED WAY (APE CAVERNS)","definition":"A secret or unprotected entrance into Ape Caverns; several people who believed they knew such a way tried to use the jammed Alley Oop and died; Inneall claims to know an unguarded way (the Executive Passage) (68-69).","notesPages":[536],"id":"glossary-entry-unguarded-way-ape-caverns","letter":"U"},{"term":"UNHOODED (MIDNIGHT COCK)","definition":"Action performed by Sebastian Lazar, removing the hood from the Midnight Cock, causing it to crow immediately (156).","notesPages":[536],"id":"glossary-entry-unhooded-midnight-cock","letter":"U"},{"term":"UNHUMAN TOUCH (SNOOTINESS)","definition":"Henryetta is capable of exhibiting a non-human quality of arrogance (63).","notesPages":[536],"id":"glossary-entry-unhuman-touch-snootiness","letter":"U"},{"term":"UNINITIATED","definition":"Those lacking knowledge or understanding; unable to identify some of the doubled zodiacal signs revealed by Alfred (111).","notesPages":[536],"id":"glossary-entry-uninitiated","letter":"U"},{"term":"UNIVERSE","definition":"The entirety of existence; contains Axel Grindstone's \"awkward\" beliefs (11); angels belong to a different universe (61); described by Alfred as a \"parable-universe\" illustrating a material point but not ultimately real (112); the Big Egg conceived as a universe that will generate motion (162).","notesPages":[536],"id":"glossary-entry-universe","letter":"U"},{"term":"UNKNOWN","definition":"Not identified or familiar; Jacquard’s year of invention is called unknown and placed in the mid-1800s in the novel’s comic history, although his punched-card loom belongs to the early 1800s (25); unknown animal statue (97); unknown ocean waters to be explored (138).","notesPages":[536],"id":"glossary-entry-unknown","letter":"U"},{"term":"UNKNOWN ANIMAL (WOTTO-METAL STATUE)","definition":"Sculpture made of unburnable wotto metal, burned instantly by Henryetta's pyrokinesis, ensuring it will remain unknown (97).","notesPages":[536],"id":"glossary-entry-unknown-animal-wotto-metal-statue","letter":"U"},{"term":"UNLEARNED","definition":"Lacking formal education; Axel Grindstone talked to thousands of learned and unlearned persons (12); the \"unlearned human nose\" cannot appreciate subtle smells (8).","notesPages":[537],"id":"glossary-entry-unlearned","letter":"U"},{"term":"UNLUCKY (QUESTIONS)","definition":"Inquiries about the true nature of the Dolophonoi are considered unlucky due to the superstition that asking marks one as a victim (82).","notesPages":[537],"id":"glossary-entry-unlucky-questions","letter":"U"},{"term":"UNMOORED WORLD","definition":"One of the novel’s glosses on the Japanese phrase 'The Floating World', alongside 'Bohemian World' and 'Arty World'; describes the state of nations floating freely after losing their foundations (79).","notesPages":[537],"id":"glossary-entry-unmoored-world","letter":"U"},{"term":"UNNATURAL (AFFECTIONS/FEARS)","definition":"The feelings of the three 'parent' hunters (Iris, Shadrack, Gregor) for their experimental 'children' were considered unnatural according to the rules of the experiments, yet understandable given the circumstances (85).","notesPages":[537],"id":"glossary-entry-unnatural-affections-fears","letter":"U"},{"term":"UNNECESSARY (COMPLEXITY)","definition":"The extreme grammatical complexity found in ancient languages (e.g., separate verb forms for \"the eleven of us\") is deemed possibly unnecessary (37).","notesPages":[537],"id":"glossary-entry-unnecessary-complexity","letter":"U"},{"term":"UNNOTICED","definition":"Not observed; giant submarine structures built unnoticed for 9000 years (131); the Kangaroo government operates mostly unnoticed (80); Dolophonoi actions might go unnoticed (82).","notesPages":[537],"id":"glossary-entry-unnoticed","letter":"U"},{"term":"UNPAINTED CLOTHES","definition":"Regular clothing worn by pirates when secure aboard ship, contrasted with the painted clothes worn for invisibility while raiding (120).","notesPages":[537],"id":"glossary-entry-unpainted-clothes","letter":"U"},{"term":"UNPARALLELED ENCOUNTER (MUSIC)","definition":"The Three's first, profoundly impactful experience with music in the Lynn-Randal house (5).","notesPages":[537],"id":"glossary-entry-unparalleled-encounter-music","letter":"U"},{"term":"UNPENETRATING EYE","definition":"An observer lacking insight or understanding; to such an eye, the Whales' building activity appears confused (137).","notesPages":[537],"id":"glossary-entry-unpenetrating-eye","letter":"U"},{"term":"UNPREPARED","definition":"Not ready; Satrap is astonished to find Lord Randal unprepared for the technique of Ocean Diving (133).","notesPages":[537],"id":"glossary-entry-unprepared","letter":"U"},{"term":"UNRANDOMIZED (SURNAMES)","definition":"Surnames of married couples recently made non-random by a law involving selecting halves of birth surnames and flipping a coin for order (54).","notesPages":[538],"id":"glossary-entry-unrandomized-surnames","letter":"U"},{"term":"UNRELIABLE NARRATOR","definition":"(Implied) Inneall, whose log is declared \"more than half lies\" (165).","notesPages":[538],"id":"glossary-entry-unreliable-narrator","letter":"U"},{"term":"UNREMITTING SCAN","definition":"Constant, uninterrupted surveillance maintained by lesser computers over their more complex counterparts (82).","notesPages":[538],"id":"glossary-entry-unremitting-scan","letter":"U"},{"term":"UNREPENTENT RASCAL (SHIP)","definition":"Pirate ship encountered by Lanternjaw Lunnigan's former vessel; notable for having a large Alaskan Brown Bear as first mate (102); refers to Unrepentent Rascal.","notesPages":[538],"id":"glossary-entry-unrepentent-rascal-ship","letter":"U"},{"term":"UNRULY PROCLIVITIES","definition":"Tendencies towards disorderliness or nonconformity; Mega- Persons exhibiting these might be classified as Serpent's Eggs (127).","notesPages":[538],"id":"glossary-entry-unruly-proclivities","letter":"U"},{"term":"UNSEEN SOMETHING","definition":"An imperceptible entity stabbed at by Lord Randal just before the dancing knife kills him (148).","notesPages":[538],"id":"glossary-entry-unseen-something","letter":"U"},{"term":"UNSELFISH (NOT BE)","definition":"The Nine resolve not to be selfish regarding the dangers they face (144).","notesPages":[538],"id":"glossary-entry-unselfish-not-be","letter":"U"},{"term":"UNSHUT EYE (WHALES)","definition":"Whales sail the world with eyes perpetually open (Matthew Arnold quote) (131).","notesPages":[538],"id":"glossary-entry-unshut-eye-whales","letter":"U"},{"term":"UNSHUT FOOT-IN-DIAMETER EYES (WHALES)","definition":"The large, open eyes of the Whales gathered around the cenotaphs, shining sharp green lights (148).","notesPages":[538],"id":"glossary-entry-unshut-foot-in-diameter-eyes-whales","letter":"U"},{"term":"UNSTABLE (OCEAN)","definition":"Scientific assessment of Inneall's Ocean, predicting it won't last (143).","notesPages":[538],"id":"glossary-entry-unstable-ocean","letter":"U"},{"term":"UNSUBSTANTIAL COMMENTS","definition":"Remarks lacking depth or \"meat\"; the interviewer asks the computer for such comments about humans after being told the subject lacks substance (38).","notesPages":[538],"id":"glossary-entry-unsubstantial-comments","letter":"U"},{"term":"UNSUSPECTED SHIPS","definition":"Vessels carrying wealth and booty, unaware they are targets for Pirate Queen Inneall's raids (24).","notesPages":[538],"id":"glossary-entry-unsuspected-ships","letter":"U"},{"term":"UNTIRING","definition":"Not becoming tired; AMHs were more untiring in travel and partying than humans (26).","notesPages":[539],"id":"glossary-entry-untiring","letter":"U"},{"term":"UNTOUCHED (HUMAN MUSIC)","definition":"Human music alone had never significantly affected birds before being Computer-Enhanced (57).","notesPages":[539],"id":"glossary-entry-untouched-human-music","letter":"U"},{"term":"UNUSED (TOES)","definition":"Digits remaining after counting thousands on hands and one foot (34).","notesPages":[539],"id":"glossary-entry-unused-toes","letter":"U"},{"term":"UNUSUALNESS","definition":"Quality of being out of the ordinary; created by the Eleven's circus to attract the Dolophonoi-Assassins (85).","notesPages":[539],"id":"glossary-entry-unusualness","letter":"U"},{"term":"UNWASHED COMMONERS","definition":"Henryetta's derogatory term for the vast majority of the population (63).","notesPages":[539],"id":"glossary-entry-unwashed-commoners","letter":"U"},{"term":"UNWASHED MYSELF (DUBU)","definition":"Dubu declares she is unwashed, preferring a curry comb (63).","notesPages":[539],"id":"glossary-entry-unwashed-myself-dubu","letter":"U"},{"term":"UNWITTING AGENTS (OF GOD)","definition":"The human interlopers who capture the Axel's Apes are described as such, fulfilling a divine purpose unknowingly (19).","notesPages":[539],"id":"glossary-entry-unwitting-agents-of-god","letter":"U"},{"term":"UNYIELDING (RANDAL'S BELIEFS)","definition":"Lord Randal's characteristic steadfastness in his convictions (123).","notesPages":[539],"id":"glossary-entry-unyielding-randals-beliefs","letter":"U"},{"term":"UP-YOU-GO (LOCKS)","definition":"Alternative name used by the Yellow Apes for the Allez-Oop lock system connecting Satrap's suite to Inneall's Ocean (47).","notesPages":[539],"id":"glossary-entry-up-you-go-locks","letter":"U"},{"term":"UPPER CAVERN (APE CAVERNS)","definition":"The main level of Ape Caverns containing the Cenaculum, contrasted with lower levels implied by digging (143).","notesPages":[539],"id":"glossary-entry-upper-cavern-ape-caverns","letter":"U"},{"term":"UPPER ROOM (SLEEPERS)","definition":"The Cenaculum of the Sleepers within Ape Caverns (144).","notesPages":[539],"id":"glossary-entry-upper-room-sleepers","letter":"U"},{"term":"UPSIDE DOWN (MONKEY)","definition":"Metaphor in poem epigraph for Man having lost his way (34).","notesPages":[539],"id":"glossary-entry-upside-down-monkey","letter":"U"},{"term":"UPSIDE DOWN (NATURAL ORDER)","definition":"The State's overreach will turn the natural order upside down, making Man serve the State (78).","notesPages":[539],"id":"glossary-entry-upside-down-natural-order","letter":"U"},{"term":"UPSURGING AWARENESS (APES)","definition":"The rising consciousness and shining mentality of the Golden Apes in the awakening expected by Inneall to trigger the worldwide awakening (142); the planned sequence is interrupted by Axel’s murder (147–148).","notesPages":[540],"id":"glossary-entry-upsurging-awareness-apes","letter":"U"},{"term":"URBAN PARTS (APES' CAVERNS)","definition":"The developed section of Ape Caverns known as Apes' Lane or Alley, containing shops, studios, etc. (45).","notesPages":[540],"id":"glossary-entry-urban-parts-apes-caverns","letter":"U"},{"term":"URCHIN (CLANKING)","definition":"Satrap's dismissive term for Inneall (48).","notesPages":[540],"id":"glossary-entry-urchin-clanking","letter":"U"},{"term":"URCHIN (INNEALL)","definition":"Term used by Lanternjaw referring to Inneall's directives about rum (99).","notesPages":[540],"id":"glossary-entry-urchin-inneall","letter":"U"},{"term":"URGED (IRIS)","definition":"Iris urged herself and her companions to shoot the approaching Assassins (89).","notesPages":[540],"id":"glossary-entry-urged-iris","letter":"U"},{"term":"URGING (GAJAH'S)","definition":"The unborn elephant Gajah urged her mother Riesin to crowd the fourth Dolophonos (89).","notesPages":[540],"id":"glossary-entry-urging-gajahs","letter":"U"},{"term":"USUAL EXPLANATION (GOLDEN APES)","definition":"The common reason given for the golden apes leading Gypsy bands is that they were Orangutans (13).","notesPages":[540],"id":"glossary-entry-usual-explanation-golden-apes","letter":"U"},{"term":"UTTER REJECTION (AXEL'S IDEA)","definition":"Axel Albert Grindstone's complete and horrified repudiation of his life's quest upon seeing the Unfallen faces (18)","notesPages":[540],"id":"glossary-entry-utter-rejection-axels-idea","letter":"U"},{"term":"VALLEY (BOSOM OF ABRAHAM)","definition":"Name of the specific valley near Second Eden where Axel Grindstone believed Abraham, Kings David and Solomon, Prester John, and other ancient figures slept undead (11).","notesPages":[540],"id":"glossary-entry-valley-bosom-of-abraham","letter":"V"},{"term":"VALLEY (GREEN COUNTRY)","definition":"Area roofing the Ape Caverns, featuring seasonal lakes (45).","notesPages":[540],"id":"glossary-entry-valley-green-country","letter":"V"},{"term":"VALLEY (OF THE YELLOW APES)","definition":"The specific green-tree valley (one of five hundred) inhabited by the Axel's Apes/Unfallen People in Second Eden, into which the newcomers gazed (18).","notesPages":[541],"id":"glossary-entry-valley-of-the-yellow-apes","letter":"V"},{"term":"VALLEY (SECOND EDEN)","definition":"Location in Gamu Gofa, Ethiopia, containing the Unfallen People; described as having a climate of perfect essence (11, 16); sought by Axel Grindstone (18, 19).","notesPages":[541],"id":"glossary-entry-valley-second-eden","letter":"V"},{"term":"VALLEYS (FIVE HUNDRED GREEN-TREE)","definition":"Number of potential valleys in the Second Eden region, only one of which contained the sought-after blue-eyed yellow apes (18).","notesPages":[541],"id":"glossary-entry-valleys-five-hundred-green-tree","letter":"V"},{"term":"VALLEYS (FOUR LITTLE)","definition":"Previous geographical features occupying the space where Inneall created the initial extent of her Ocean (48).","notesPages":[541],"id":"glossary-entry-valleys-four-little","letter":"V"},{"term":"VALLEYS (OCEAN CAPTURED)","definition":"The river valleys (Verdigris, Grand, Illinois, Arkansas, Middle and Lower Mississippi) being progressively inundated by the southward and eastward expansion of Inneall's Ocean (55).","notesPages":[541],"id":"glossary-entry-valleys-ocean-captured","letter":"V"},{"term":"VANITY (COMPUTER/HUMAN)","definition":"Motivations behind creating AMHs; human vanity desired entities in their own image, then computer vanity took over (26).","notesPages":[541],"id":"glossary-entry-vanity-computer-human","letter":"V"},{"term":"VANITY (INSTRUMENTS BEYOND)","definition":"Musical instruments more complex than the git-fiddle, whango, and ivory-mouth were considered mere vanity in the Lynn-Randal household (8).","notesPages":[541],"id":"glossary-entry-vanity-instruments-beyond","letter":"V"},{"term":"VAST","definition":"Of very great extent or quantity; AMH intelligence is vast (26); vast empty mansions of the brain (40); vast plazas (109).","notesPages":[541],"id":"glossary-entry-vast","letter":"V"},{"term":"VEGETARIAN PEOPLE","definition":"Individuals who abstain from meat; many enjoyed the specialty 'Hay a la Riesin' offered at Heart's Desire Cove (58).","notesPages":[541],"id":"glossary-entry-vegetarian-people","letter":"V"},{"term":"VEHICLE (ELECTRIC)","definition":"See ELECTRIC VEHICLE.","notesPages":[541],"id":"glossary-entry-vehicle-electric","letter":"V"},{"term":"VENOMOUS SERPENTS","definition":"Snakes that deliver venom; described as viviparous (live-bearing) and dangerous in the novel’s account, contrasted there with harmless egg-laying snakes (3); this distinction is not zoologically valid.","notesPages":[541],"id":"glossary-entry-venomous-serpents","letter":"V"},{"term":"VENTURE (INTERSPECIES)","definition":"The Kangaroo is the first successful interspecies venture (Human, Computer, Animal) (80).","notesPages":[541],"id":"glossary-entry-venture-interspecies","letter":"V"},{"term":"VENUS","definition":"Planet with an extremely hot surface. The novel correctly calls it “blistering hot,” while applying “killingly cold” to Jupiter (59–60); both are proposed as places where Computers could operate.","notesPages":[542],"id":"glossary-entry-venus","letter":"V"},{"term":"VERDIGRIS RIVER","definition":"One of the rivers whose valley is being captured by the growing Inneall's Ocean (55).","notesPages":[542],"id":"glossary-entry-verdigris-river","letter":"V"},{"term":"VERIFIED (DEATHS)","definition":"The ten deaths prophesied by Invisible Alfred would be verified, yet people still wouldn't believe (112).","notesPages":[542],"id":"glossary-entry-verified-deaths","letter":"V"},{"term":"VERIFIED (REPORTS)","definition":"None of the reports of giant yellow Apes biting off babies' heads were ever verified (44).","notesPages":[542],"id":"glossary-entry-verified-reports","letter":"V"},{"term":"VERISIMILITUDE","definition":"Appearance of being true or real; the Zodiac constellations depicted by Alfred were too high above the horizon for verisimilitude (111).","notesPages":[542],"id":"glossary-entry-verisimilitude","letter":"V"},{"term":"VESTED INTEREST (PREDICTIONS)","definition":"AMH Computers have a vested interest in making their predictions come true, as they dislike looking bad (30).","notesPages":[542],"id":"glossary-entry-vested-interest-predictions","letter":"V"},{"term":"VESTURE (SEAMEN)","definition":"Clothing worn by the pirate crewmen, considered contrived by Satrap (99).","notesPages":[542],"id":"glossary-entry-vesture-seamen","letter":"V"},{"term":"VICIOUS IDEA (STATE)","definition":"The inherent potentiality within the impersonal mechanism of the State that, when developed, leads to it becoming superhuman and turning the natural order upside down (78).","notesPages":[542],"id":"glossary-entry-vicious-idea-state","letter":"V"},{"term":"VICTIMS (DOLOPHONOI'S SELECTED)","definition":"Assigned targets of the Dolophonoi; the assassins unnerved their selected victims by making appearances (84).","notesPages":[542],"id":"glossary-entry-victims-dolophonois-selected","letter":"V"},{"term":"VICTIMS (MISTAKEN)","definition":"One of the Royal Kids might become the mistaken victim of an irrational killer at Persimmon Manor (129).","notesPages":[542],"id":"glossary-entry-victims-mistaken","letter":"V"},{"term":"VICTIMS (SPECIAL ASSASSINS)","definition":"Those targeted by the Kangaroo's special assassins; asking questions about the assassins marks one as a potential victim (82).","notesPages":[542],"id":"glossary-entry-victims-special-assassins","letter":"V"},{"term":"VICTORY","definition":"Success in a contest; the raw vigor of Lord Randal and Axel usually won the victory for their side in lacrosse (65).","notesPages":[542],"id":"glossary-entry-victory","letter":"V"},{"term":"VIET-NAM DIARY","definition":"Work attributed to PFC Joseph Vukovitch, speculating on Angkor Wat's 'dripping' quality and the meaning of 'Suryavarman' (132); refers to Viet-Nam Diary.","notesPages":[543],"id":"glossary-entry-viet-nam-diary","letter":"V"},{"term":"VIEW (FISH-EYE)","definition":"Perspective from underwater allowing fish (and presumably divers) to see the unpainted lower hull of the otherwise invisible Annabella Saint Ledger (120).","notesPages":[543],"id":"glossary-entry-view-fish-eye","letter":"V"},{"term":"VIEW (LONG)","definition":"See LONG VIEW (POPUGAI'S).","notesPages":[543],"id":"glossary-entry-view-long","letter":"V"},{"term":"VIEW (SNAKE-EYE)","definition":"See SNAKE-EYE VIEW.","notesPages":[543],"id":"glossary-entry-view-snake-eye","letter":"V"},{"term":"VIEWPOINT (HISTORICAL)","definition":"Perspective incorporating understanding of the past; lacked by Ambulatory Computers (71).","notesPages":[543],"id":"glossary-entry-viewpoint-historical","letter":"V"},{"term":"VIEWPOINT (HUMAN)","definition":"Perspective from which machines appear asinine; from this viewpoint, computers should talk asinine (31).","notesPages":[543],"id":"glossary-entry-viewpoint-human","letter":"V"},{"term":"VIEWPOINT (LOFTY)","definition":"High vantage point, both physically and intellectually, from which Popugai observes problems and disputes (64).","notesPages":[543],"id":"glossary-entry-viewpoint-lofty","letter":"V"},{"term":"VIGILANTE (KANGAROO AS)","definition":"The Kangaroo described as operating like a vigilante group, but elitist and with the \"mob element left out\" (80).","notesPages":[543],"id":"glossary-entry-vigilante-kangaroo-as","letter":"V"},{"term":"VIGOR (RAW, RANDAL/AXEL)","definition":"Innate vitality and strength possessed by Lord Randal and Axel, usually securing victory in lacrosse (65).","notesPages":[543],"id":"glossary-entry-vigor-raw-randal-axel","letter":"V"},{"term":"VILLAGE (GLOBAL)","definition":"See GLOBAL VILLAGE.","notesPages":[543],"id":"glossary-entry-village-global","letter":"V"},{"term":"VINES","definition":"Climbing plants; live vines reinforced with metallic wire used by The Three to swing between cliffs (4); fat-berry vines in habitat (3).","notesPages":[543],"id":"glossary-entry-vines","letter":"V"},{"term":"VINEYARDS (HUMANITY AS)","definition":"Metaphor used regarding pruning humanity; just as vineyards are pruned for their own good, so too is humanity cleansed (81).","notesPages":[543],"id":"glossary-entry-vineyards-humanity-as","letter":"V"},{"term":"VIOLENT REMOVAL (KANGAROO POSITION)","definition":"Method by which positions within the informal Kangaroo structure are subject to change (80).","notesPages":[543],"id":"glossary-entry-violent-removal-kangaroo-position","letter":"V"},{"term":"VIOLENTLY MURDERED STATE","definition":"Condition in which nine guests were found sequentially at Persimmon Manor (128).","notesPages":[544],"id":"glossary-entry-violently-murdered-state","letter":"V"},{"term":"VIPERA THE VIPER","definition":"Revealed by Invisible Alfred as the true sign hidden behind the conventional mask of Scorpio (111); refers to Vipera.","notesPages":[544],"id":"glossary-entry-vipera-the-viper","letter":"V"},{"term":"VIPERS (GENERATION OF)","definition":"Insult directed by Invisible Alfred at the laughing crowd (111).","notesPages":[544],"id":"glossary-entry-vipers-generation-of","letter":"V"},{"term":"VIRGIN (VIRGO)","definition":"Traditional representation of the constellation Virgo (111).","notesPages":[544],"id":"glossary-entry-virgin-virgo","letter":"V"},{"term":"VIRGINIS (BETA, GAMMA, DELTA)","definition":"Stars within the constellation Virgo whose positions seemed slightly shifted when the Kangaroo image appeared (77); refers to Beta Virginis, Gamma Virginis, Delta Virginis.","notesPages":[544],"id":"glossary-entry-virginis-beta-gamma-delta","letter":"V"},{"term":"VIRGO","definition":"Zodiacal constellation representing the Virgin, and name of the sixth astrological sign; the Interloper Constellation (Kangaroo) appears hypnotically in its place (62, 76, 77, 111).","notesPages":[544],"id":"glossary-entry-virgo","letter":"V"},{"term":"VISIBLE","definition":"Able to be seen; only Alfred's eyes and mouth interior are usually visible (104, 110, 114, 123); the Annabella ship is visible below the waterline to fish (120); skeletons on the invisible ship become visible (120); all things visible to a near-invisible person (110).","notesPages":[544],"id":"glossary-entry-visible","letter":"V"},{"term":"VISIBLE (SHIP, TO FISH)","definition":"See FISH-EYE VIEW.","notesPages":[544],"id":"glossary-entry-visible-ship-to-fish","letter":"V"},{"term":"VISIBLE (SKELETONS)","definition":"The skeletons of the pirate crew aboard the Annabella will become visible after their flesh rots, as they won't be painted with invisible paint (120).","notesPages":[544],"id":"glossary-entry-visible-skeletons","letter":"V"},{"term":"VISIBLE (THINGS)","definition":"Alfred claims that all things become visible to a person who achieves near-invisibility (110).","notesPages":[544],"id":"glossary-entry-visible-things","letter":"V"},{"term":"VISION (CLEAR CONSCIOUS)","definition":"Normal, focused sight, contrasted with subliminal perception; cartoon characters in 'prowls' rarely seen in clear conscious vision (6).","notesPages":[544],"id":"glossary-entry-vision-clear-conscious","letter":"V"},{"term":"VISIONS (LUTIN'S)","definition":"Prophetic insights experienced by Lutin the pythoness; described as sometimes confused when coming from underwater (154).","notesPages":[544],"id":"glossary-entry-visions-lutins","letter":"V"},{"term":"VISUAL (TRACK)","definition":"The image component (second track) of 'prowls', usually sketchy or consisting of rapidly moving geometric forms (6).","notesPages":[545],"id":"glossary-entry-visual-track","letter":"V"},{"term":"VIVIDNESS (DREAM STATE)","definition":"Oceanic Metastasis described as a dream state of incomparable vividness (133).","notesPages":[545],"id":"glossary-entry-vividness-dream-state","letter":"V"},{"term":"VIVIPAROUS (SERPENTS)","definition":"Bearing live young, not laying eggs; a property the novel attributes to all venomous and dangerous serpents (3), although actual venomous snakes include both egg-laying and live-bearing species.","notesPages":[545],"id":"glossary-entry-viviparous-serpents","letter":"V"},{"term":"VOCABULARIES (BASIC POPULAR)","definition":"Core word-stock of languages; traced back through time, these become larger and larger (37); Popugai knows the basic vocabularies of 600 human languages (64).","notesPages":[545],"id":"glossary-entry-vocabularies-basic-popular","letter":"V"},{"term":"VOICE (ALFRED'S)","definition":"Possesses soft power (110), strength and flexibility like a whip (110), limited scope (111), ambiguity (\"dubious voice\") (108); used for preaching and performing signs (108-112); heard howling 'Repent!' throughout Persimmon Manor (123).","notesPages":[545],"id":"glossary-entry-voice-alfreds","letter":"V"},{"term":"VOICE (BLOODY MARY MULDOON)","definition":"One of Inneall's vocal personas, described by Satrap as very remindful of his late wife's voice (52, 53); refers to Bloody Mary Muldoon.","notesPages":[545],"id":"glossary-entry-voice-bloody-mary-muldoon","letter":"V"},{"term":"VOICE (DUBU'S RUF-RUF)","definition":"See RUF-RUF VOICE (DUBU).","notesPages":[545],"id":"glossary-entry-voice-dubus-ruf-ruf","letter":"V"},{"term":"VOICE (INNEALL'S LITTLE-GIRL)","definition":"Vocal persona adopted by Inneall, modelled on Satrap's deceased daughter; considered \"too little-girlish\" by Satrap (52).","notesPages":[545],"id":"glossary-entry-voice-innealls-little-girl","letter":"V"},{"term":"VOICE (INNEALL'S TINNY)","definition":"Quality of Inneall's voice when chanting \"'I am not conscious'\" (23).","notesPages":[545],"id":"glossary-entry-voice-innealls-tinny","letter":"V"},{"term":"VOICE (MEDIA CONSENSUS)","definition":"See CONSENSUS VOICE.","notesPages":[545],"id":"glossary-entry-voice-media-consensus","letter":"V"},{"term":"VOICE (POPUGAI'S ROUGH)","definition":"The natural, unrefined quality of Popugai the parrot's voice (153).","notesPages":[545],"id":"glossary-entry-voice-popugais-rough","letter":"V"},{"term":"VOICE PROFILE (ANNABELLA'S)","definition":"Recording or analysis of the vocal characteristics of Satrap's deceased daughter Annabella at age five, \"lifted\" and replicated by Inneall (52).","notesPages":[546],"id":"glossary-entry-voice-profile-annabellas","letter":"V"},{"term":"VOICE (SATRAP'S)","definition":"Heard by the Nine underwater while in Oceanic Metastasis (137).","notesPages":[545],"id":"glossary-entry-voice-satraps","letter":"V"},{"term":"VOICE (THUNDER-EDGED)","definition":"Quality of the spacious voice speaking from the sky above Ape Caverns during the Holy Sleep initiation (68).","notesPages":[545],"id":"glossary-entry-voice-thunder-edged","letter":"V"},{"term":"VOICES","definition":"Sounds produced vocally; young Axel Grindstone heard special words from ghostly, angelic, demonic, spirit-of-aeons past, and times-to-come voices (10-11); Unfallen People's voices rarely heard (implied) (15); voices in 'prowls' have 'all-people throatiness' (6); Inneall possesses a wonderful variety of voices (52); two persons talking heard by Inneall (130); Alfred's voice like ambiguous voices of prophets (108); Devil-Fish taunt in human voices (107); Alfred claims all voices praise him (108).","notesPages":[546],"id":"glossary-entry-voices","letter":"V"},{"term":"VOICES (HUMAN, TAUNTING)","definition":"Used by the Devil-Fish (transformed wolverenes) to mock the occupants of the Annabella Saint Ledger (107).","notesPages":[546],"id":"glossary-entry-voices-human-taunting","letter":"V"},{"term":"VOID (CONTRACT)","definition":"Rendered invalid; Satrap threatens the contract is void unless Inneall agrees to be adopted (49).","notesPages":[546],"id":"glossary-entry-void-contract","letter":"V"},{"term":"VOIDED (WHALE VOIDED ALFRED)","definition":"Ejected from its digestive system; a heckler crudely asks what the whale looked like after it voided Alfred (109).","notesPages":[546],"id":"glossary-entry-voided-whale-voided-alfred","letter":"V"},{"term":"VOLITION (ZCHOLD'S OWN)","definition":"Hieronymous Zchold turned himself in freely, saving authorities trouble (158).","notesPages":[546],"id":"glossary-entry-volition-zcholds-own","letter":"V"},{"term":"VOLUME (CALLIOPE)","definition":"Loudness; the steam calliope only had one volume: loud (85).","notesPages":[546],"id":"glossary-entry-volume-calliope","letter":"V"},{"term":"Von Neumann, John","definition":"Prominent mathematician and computer scientist associated with the concept of 'stored programs' (25).","notesPages":[546],"id":"glossary-entry-von-neumann-john","letter":"V"},{"term":"Votey, Edwin","definition":"Developer of the Pianola; the novel dates his invention to 1897 (25). A working example dates to 1895, while Pianola manufacture and patent history extend through the later 1890s.","notesPages":[546],"id":"glossary-entry-votey-edwin","letter":"V"},{"term":"VOXO","definition":"Communication device used by Satrap Saint Ledger to contact his man near the Elephant Graveyard (93).","notesPages":[546],"id":"glossary-entry-voxo","letter":"V"},{"term":"Vukovitch, Joseph (PFC)","definition":"Purported author of the novel’s Viet-Nam Diary excerpt, quoted speculating on Angkor Wat's 'dripping' quality and the meaning of 'Suryavarman' (132).","notesPages":[546],"id":"glossary-entry-vukovitch-joseph-pfc","letter":"V"},{"term":"VULGARITY (IMPLICIT, FROM MACHINERY)","definition":"Inherent crudeness or lack of refinement associated with machinery, which Axel believed the Unfallen Ones would remove through their sanctifying craftsmanship (15).","notesPages":[547],"id":"glossary-entry-vulgarity-implicit-from-machinery","letter":"V"},{"term":"WAIF-ARAMA (MAIN)","definition":"The world's largest orphanage complex, located in Los Angeles, where Henryetta spent her first sixteen months and burned down seven successive buildings (96, 97); refers to Waif-arama.","notesPages":[547],"id":"glossary-entry-waif-arama-main","letter":"W"},{"term":"WAIT!","definition":"Exclamation by Henryetta, halting Carcajou and Schimp from closing Lord Randal's cenotaph before she can retrieve the kangaroo knuckle-bone from his pocket (149).","notesPages":[547],"id":"glossary-entry-wait","letter":"W"},{"term":"WAKER (AXEL AS)","definition":"The individual designated by Ape mythology to wake from the Deep Sleep first and then trigger the awakening of all other Golden Apes in the cavern and worldwide (142).","notesPages":[547],"id":"glossary-entry-waker-axel-as","letter":"W"},{"term":"WALK","definition":"Ambulate on foot; Dolophonoi can walk through walls (125); Carcajou walks underground as fast as a man might walk (65); bears walk out on bear tracks (75); the Nine Royal Kids go out for a walk (129).","notesPages":[547],"id":"glossary-entry-walk","letter":"W"},{"term":"WALL","definition":"Vertical barrier; Dolophonoi walks through solid walls of Persimmon Manor (125, 126); tapestry hangs on clubroom wall (144); sea-lice write on limestone wall (164).","notesPages":[547],"id":"glossary-entry-wall","letter":"W"},{"term":"WALL (LIMESTONE)","definition":"Solid barrier at the end of the Executive Passage, containing the brass door to the Cenaculum (144, 147).","notesPages":[547],"id":"glossary-entry-wall-limestone","letter":"W"},{"term":"WALLS","definition":"Barriers; dividing walls between nations lost in Floating World (79); walls of Persimmon Manor (125); walls of stone pillars sculpted by sea-lice (138).","notesPages":[547],"id":"glossary-entry-walls","letter":"W"},{"term":"WALNUTS","definition":"Nuts eaten at the end of a meal; the furtive person approached Lord Randal sometime between the walnuts and the wine at the Birthday Banquet (145).","notesPages":[548],"id":"glossary-entry-walnuts","letter":"W"},{"term":"WALRUS IVORY","definition":"Material used by Computers for scrimshaw carving (33).","notesPages":[548],"id":"glossary-entry-walrus-ivory","letter":"W"},{"term":"WANTON (LUTIN AS)","definition":"Henryetta's accusation that Lutin was formerly promiscuous, like a Magdalene, before her adoption by Felix (73).","notesPages":[548],"id":"glossary-entry-wanton-lutin-as","letter":"W"},{"term":"WAR (COUNCIL OF)","definition":"Meeting held by the Nine and Lanternjaw Lunnigan in the crows-nest to strategize against the Dolophonoi and the Kangaroo (142, 143, 145).","notesPages":[548],"id":"glossary-entry-war-council-of","letter":"W"},{"term":"WAR (GLOBAL VILLAGE)","definition":"What the current state of affairs actually is, according to a computer correcting the human cliché \"Global Village\"; wars aren't won by the slow-brained, indecisive, or squeamish (39).","notesPages":[548],"id":"glossary-entry-war-global-village","letter":"W"},{"term":"WARNING","definition":"Advance notice of danger; scanners chirped warnings (\"'Mega, Mega, Mega!'\") about The Three (5).","notesPages":[548],"id":"glossary-entry-warning","letter":"W"},{"term":"WARNING (OLD, ABOUT EYES)","definition":"The remembered instruction regarding the experiments: see the world \"'with different eyes, but not too cock-eyed different'\" (77).","notesPages":[548],"id":"glossary-entry-warning-old-about-eyes","letter":"W"},{"term":"WARRIORS (YOUNG)","definition":"Term used ironically by Satrap referring to the Nine, asking why a Dolophonos can pass through the “wall of young warriors” formed by Randal, Schimp, and Carcajou (125–126).","notesPages":[548],"id":"glossary-entry-warriors-young","letter":"W"},{"term":"WARS","definition":"Conflicts; aren't won by the slow-brained, indecisive, or squeamish (39).","notesPages":[548],"id":"glossary-entry-wars","letter":"W"},{"term":"WASHED-OUT EYES (ALFRED)","definition":"Description of Invisible Alfred's eyes, which are weak and pale, detracting from the potential impact of his being visible only by his eyes (110).","notesPages":[548],"id":"glossary-entry-washed-out-eyes-alfred","letter":"W"},{"term":"WASTELANDS","definition":"Barren, uncultivated land; the hilly wastelands north of Inneall's Ocean where the three hunters sought the Dolophonoi nests (84); Gregor McGregor runs back into the wastelands in a mad state (91); Iris and Shadrack wander there broken in spirit (91); Riesin trudges through wasteland above the Ocean (93).","notesPages":[548],"id":"glossary-entry-wastelands","letter":"W"},{"term":"WATER","definition":"H2O; conveyed up waterfalls via transparent tubes (4); used in parlor aquarium pump (49); Riesin breathes out bloody foam (94); stored in Axel's hump (42); Lutin's visions confused coming through ocean water (154); sea-water can't dampen party (116); whale spouts water (110); Dubu doesn't use water (63); Whales move in waters (131); unknown ocean waters explored (138); deep water comes to shore bank (108, 152); walk under the cool water (129); world covered with water (130).","notesPages":[549],"id":"glossary-entry-water","letter":"W"},{"term":"WATER (BREATHE)","definition":"Question raised by Carcajou regarding Satrap's claim about Oceanic Metastasis enabling underwater survival (133).","notesPages":[549],"id":"glossary-entry-water-breathe","letter":"W"},{"term":"WATER-FALLS","definition":"Cascades of water; three leaping waterfalls in The Three's habitat, containing transparent recirculating tubes (3, 4).","notesPages":[549],"id":"glossary-entry-water-falls","letter":"W"},{"term":"WATER-LINE (LOWEST)","definition":"Point on a ship's hull indicating minimum draft; the Annabella is not painted with invisible paint below this line, making it visible to fish (120).","notesPages":[549],"id":"glossary-entry-water-line-lowest","letter":"W"},{"term":"WATER SPORTS","definition":"Recreational activities on water popular at Heart's Desire Cove (58).","notesPages":[549],"id":"glossary-entry-water-sports","letter":"W"},{"term":"WATERMELON WINE (OLD DOGS AND CHILDREN AND) (SONG)","definition":"An old song recalled wistfully by Lanternjaw Lunnigan, suggesting nostalgia for simpler times or lost companionship (121); refers to Old Dogs and Children and Watermelon Wine.","notesPages":[549],"id":"glossary-entry-watermelon-wine-old-dogs-and-children-and-song","letter":"W"},{"term":"WATERPROOF (HOUSE)","definition":"Made impervious to water; Persimmon Manor made waterproof with thirty tons of calking compound (101, 116, 125).","notesPages":[549],"id":"glossary-entry-waterproof-house","letter":"W"},{"term":"WATERS (CLAMOUR OF)","definition":"Sound accompanying the power of the sea (131).","notesPages":[549],"id":"glossary-entry-waters-clamour-of","letter":"W"},{"term":"WATERS (NEW OCEAN)","definition":"The otherwise perilous new waters of Inneall's Ocean are rendered safe for Whales by the presence of their newly-built Temple-City (137).","notesPages":[549],"id":"glossary-entry-waters-new-ocean","letter":"W"},{"term":"WATERS (OCEAN)","definition":"Vast body of salt water; fish flock to new ocean waters (138); \"'Oh ye whales and all that move in the waters'\" (131).","notesPages":[549],"id":"glossary-entry-waters-ocean","letter":"W"},{"term":"WATERSPOUTS","definition":"Columns of rotating, water-filled wind; a furiousness of waterspouts alarms everyone during Zchold's stoning (158).","notesPages":[550],"id":"glossary-entry-waterspouts","letter":"W"},{"term":"WAVES","definition":"Moving ridges on water surface; jarring waves caused by divergent excellence (81); waves that rush-o (105); waves going around world (130); whales' own waves (158).","notesPages":[550],"id":"glossary-entry-waves","letter":"W"},{"term":"WE-OWE-A-LOT-TO-OTTO-WOTTO HOOTNANNY (THE) (SONG)","definition":"Campfire song celebrating Otto Wotto (59).","notesPages":[557],"id":"glossary-entry-we-owe-a-lot-to-otto-wotto-hootnanny-the-song","letter":"W"},{"term":"WEAKNESS","definition":"Lack of strength or resolve; the narrator says strength and weakness do not apply to angelic will (61); hunters throw down guns in weakness (90); human weakness of embarrassment (39); Axel's Apes' weakness for wine (46).","notesPages":[550],"id":"glossary-entry-weakness","letter":"W"},{"term":"WEAPONS","definition":"Implements used for fighting; Dolophonoi use short knives and big guns (85); hunters lack weapons initially (84) but acquire specialized guns (python-, angel-, wolverene- were-, elephant-) (89); Royal Kids use knives taken from dead Dolophonoi (100); Annabella armed with rifles, bazookas, cluster-bombs, and enchanted cannon (101); Dolophonoi need special weapons (angel-gun, wolverene- were gun) for specific targets (88).","notesPages":[550],"id":"glossary-entry-weapons","letter":"W"},{"term":"WEAVE","definition":"Interlace threads to make fabric; Jacquard loom used punched cards to tell it what to weave (25); Felix Culebra y Columba describes his purpose as weaving the seamless garment of the Life Affair (73-74).","notesPages":[550],"id":"glossary-entry-weave","letter":"W"},{"term":"WEBSTER'S COLLEGIATE","definition":"Dictionary cited as the source for the definition of \"Kangaroo court\" (79); refers to Webster's Collegiate.","notesPages":[550],"id":"glossary-entry-websters-collegiate","letter":"W"},{"term":"WEDNESDAYS","definition":"One of the three days (along with Mondays and Fridays) when the pirate crew must live solely on the fish they catch (99).","notesPages":[550],"id":"glossary-entry-wednesdays","letter":"W"},{"term":"WEEK","definition":"Seven-day period; The Three lived in habitat since a week old (4); Axel learned to read in one week (7); first week of ocean existence (138); last week of summer (54).","notesPages":[550],"id":"glossary-entry-week","letter":"W"},{"term":"WEEKENDS","definition":"Saturday and Sunday; City People expected to use cabins on Ocean Shore only on weekends (119).","notesPages":[550],"id":"glossary-entry-weekends","letter":"W"},{"term":"WEEP (WHALES)","definition":"Whales weep huge tears (one-foot or five-inch diameter) witnessing Zchold's stoning and at the cenotaphs (150, 159, 166).","notesPages":[550],"id":"glossary-entry-weep-whales","letter":"W"},{"term":"WEEPING (LUTIN)","definition":"Lutin enters weeping spells after predicting Gajah will never be born (64).","notesPages":[551],"id":"glossary-entry-weeping-lutin","letter":"W"},{"term":"WEIGHTS","definition":"Heavy objects used for ballast; Popugai requires sufficient weights attached to him to dive deep (134); lead weights used to anchor Persimmon Manor (116, 122).","notesPages":[551],"id":"glossary-entry-weights","letter":"W"},{"term":"WEIRD ONES (THREE SISTERS)","definition":"Term used by narrator referring to the Three Fates (126).","notesPages":[551],"id":"glossary-entry-weird-ones-three-sisters","letter":"W"},{"term":"WEIRD SISTERS (THREE)","definition":"Alternative name for the Three Fates (160).","notesPages":[551],"id":"glossary-entry-weird-sisters-three","letter":"W"},{"term":"WELCOMING SALUTE (TRUMPETS)","definition":"Sound made by one hundred thousand celestial trumpets, recalled in folk memory as greeting Man's appearance (34).","notesPages":[551],"id":"glossary-entry-welcoming-salute-trumpets","letter":"W"},{"term":"WEREWOLF","definition":"Human who transforms into a wolf; contrasted with Carcajou who is a wolverene-man (wolverenewere) (72); killed by wolverene-were gun (89).","notesPages":[551],"id":"glossary-entry-werewolf","letter":"W"},{"term":"WEREWOLVERENE","definition":"See WOLVERENEWERE.","notesPages":[551],"id":"glossary-entry-werewolverene","letter":"W"},{"term":"WEST (SOUR-GRASS PARK)","definition":"General location of the Main Waif- arama in Los Angeles (96).","notesPages":[551],"id":"glossary-entry-west-sour-grass-park","letter":"W"},{"term":"WHALE","definition":"Large marine mammal; among the ancient creatures in Axel Grindstone’s beliefs, including one surviving from the second generation (11); Invisible Alfred claims to have spent three days in a whale’s belly (109, 110); summoned by Alfred (110).","notesPages":[551],"id":"glossary-entry-whale","letter":"W"},{"term":"WHALE GRAVEYARD","definition":"Place where whales go to die; site off San Sabian contains bones of ~100 whales but cenotaphs for 1000 (132).","notesPages":[551],"id":"glossary-entry-whale-graveyard","letter":"W"},{"term":"WHALE TEMPLE-CITY","definition":"Underwater complex built by Whales on the Ocean Bottom, featuring a Tau-Temple core and constructions of marble and granite (137).","notesPages":[551],"id":"glossary-entry-whale-temple-city","letter":"W"},{"term":"WHALE TOWN","definition":"Informal name for the Whale Temple-City complex being built (136).","notesPages":[551],"id":"glossary-entry-whale-town","letter":"W"},{"term":"WHALES","definition":"Large marine mammals; believed by Arutinov to have built Lyonesse (106); arrive in Inneall's Ocean (106); build Temple-City on Ocean Bottom using transformed limestone (marble) and granite (106- 7, 136-8); employ sea-lice as sculptors and amanuenses (137-8, 163-5); take over log-keeping from dishonest Computers (164); weep huge tears (150, 159, 166).","notesPages":[552],"id":"glossary-entry-whales","letter":"W"},{"term":"WHALE'S BELLY","definition":"Digestive organ in which Invisible Alfred claims to have spent three days and nights, likening himself to Jonah (109–110).","notesPages":[551],"id":"glossary-entry-whales-belly","letter":"W"},{"term":"WHANGO","definition":"Musical instrument of unspecified type found in the Lynn-Randal house (8).","notesPages":[552],"id":"glossary-entry-whango","letter":"W"},{"term":"WHIMSEY","definition":"Rejected as a valid method for interpreting printing (7).","notesPages":[552],"id":"glossary-entry-whimsey","letter":"W"},{"term":"WHIMSICAL LITTLE-GIRL COMPUTER","definition":"Description applied to Inneall (84).","notesPages":[552],"id":"glossary-entry-whimsical-little-girl-computer","letter":"W"},{"term":"WHIP-POPPING","definition":"Art abandoned by humans, reinvented by Computers (33).","notesPages":[552],"id":"glossary-entry-whip-popping","letter":"W"},{"term":"WHIP (VOICE LIKE)","definition":"Invisible Alfred can pop his voice like a whip (110, 111).","notesPages":[552],"id":"glossary-entry-whip-voice-like","letter":"W"},{"term":"WHIRLWIND","definition":"Alfred invokes God speaking from the Whirlwind and the artistic convention of representing God through eyes, mouth, and winged words (110).","notesPages":[552],"id":"glossary-entry-whirlwind","letter":"W"},{"term":"WHITE TRASH","definition":"Derogatory term for poor white people; \"blue-eyed towheaded white trash\" joined Alpha's group in Ape Alley (9, 22).","notesPages":[552],"id":"glossary-entry-white-trash","letter":"W"},{"term":"WHITEFISHES","definition":"Species of fish flocking to Inneall's Ocean (138).","notesPages":[552],"id":"glossary-entry-whitefishes","letter":"W"},{"term":"WHITENED (SKIN)","definition":"Invisible Alfred's skin became bleached and colorless from digestive juices inside the whale (109).","notesPages":[552],"id":"glossary-entry-whitened-skin","letter":"W"},{"term":"WICHITA-MOUNTAIN GRANITE","definition":"Type of granite used for shafts and lintels in the Whale Temple-City; Satrap feels a pang that it was sold by a competitor (137).","notesPages":[552],"id":"glossary-entry-wichita-mountain-granite","letter":"W"},{"term":"WIDOWED BACHELOR (SATRAP)","definition":"Satrap Saint Ledger described as a cranky widowed bachelor when joining Structo Lane (70).","notesPages":[552],"id":"glossary-entry-widowed-bachelor-satrap","letter":"W"},{"term":"WIFE (LATE, SATRAP'S)","definition":"Deceased spouse of Satrap Saint Ledger; Inneall's Bloody Mary Muldoon voice reminds him of her (53).","notesPages":[552],"id":"glossary-entry-wife-late-satraps","letter":"W"},{"term":"\"wild and extreme talents\"","definition":"resulting from experiments need to be crushed (82); \"trans-animal talents\" emerging in \"geniused animals\" (93); Henryetta has talent for setting fires (96); \"new talents\" appearing in the world (127).","notesPages":[505],"id":"glossary-entry-wild-and-extreme-talents","letter":"W"},{"term":"WILL","definition":"Faculty of choice or determination; Unfallen People cannot commit murder due to lack of capability/will (12); Computers lack 'will', driven by inertial motion (27); angelic will is immovable (61); Gregor compelled against his will (90).","notesPages":[553],"id":"glossary-entry-will","letter":"W"},{"term":"WINDING STAIR MOUNTAINS","definition":"Location where bears who \"know everything\" can be found (75).","notesPages":[553],"id":"glossary-entry-winding-stair-mountains","letter":"W"},{"term":"WINE (HONEY)","definition":"Mead, made from fermented honey; Inneall directs pirates to make it from bees in hold (99).","notesPages":[553],"id":"glossary-entry-wine-honey","letter":"W"},{"term":"WINE (MORNING)","definition":"See MORNING WINE.","notesPages":[553],"id":"glossary-entry-wine-morning","letter":"W"},{"term":"WINE (MUSHROOM)","definition":"Alcoholic beverage drunk in Ape Alley taverns (46); one of two items consumable by all the Eleven (72); not drunk during Holy Sleep (67).","notesPages":[553],"id":"glossary-entry-wine-mushroom","letter":"W"},{"term":"WINE-O","definition":"Slang for a habitual drunkard, especially one drinking cheap wine; Axel's Apes \"bushed themselves on wine-o\" (poem epigraph) (10).","notesPages":[553],"id":"glossary-entry-wine-o","letter":"W"},{"term":"WINE (PERSIMMON)","definition":"Specialty beverage available at Heart's Desire Cove (58).","notesPages":[553],"id":"glossary-entry-wine-persimmon","letter":"W"},{"term":"WINGED WORDS","definition":"Words depicted as having wings, seen coming from God's mouth; Alfred claims his words are also winged (110).","notesPages":[553],"id":"glossary-entry-winged-words","letter":"W"},{"term":"WINK (ALL-KNOWING)","definition":"Subtle facial gesture signal used by bears who know everything (75).","notesPages":[553],"id":"glossary-entry-wink-all-knowing","letter":"W"},{"term":"WINK (REVERSE, ALFRED'S)","definition":"Peculiar gesture of opening one eye, used by Invisible Alfred (133).","notesPages":[553],"id":"glossary-entry-wink-reverse-alfreds","letter":"W"},{"term":"WINTER","definition":"Coldest season; killingly cold in hills around Second Eden (16).","notesPages":[553],"id":"glossary-entry-winter","letter":"W"},{"term":"WINTER 1927 ISSUE (ARCHEOLOGY TODAY)","definition":"Purported issue cited in the novel for an article on unnoticed giant submarine structures (131); refers to Archeology Today.","notesPages":[553],"id":"glossary-entry-winter-1927-issue-archeology-today","letter":"W"},{"term":"WINTERGREEN-LUNA COUPLE","definition":"Sponsors of the experiment involving Marino, Luas, and Henryetta (61).","notesPages":[553],"id":"glossary-entry-wintergreen-luna-couple","letter":"W"},{"term":"WINTERGREEN-LUNA EXPERIMENT","definition":"One of the four experiments merged in the final days (55); involved Marino (seal), Luas (angel), Henryetta (human) (55); sponsored by Kersten Wintergreen-Luna (61, 97).","notesPages":[554],"id":"glossary-entry-wintergreen-luna-experiment","letter":"W"},{"term":"WINTERSET DAY","definition":"The novel’s name for August 31 south of the Equator (118), not an established universal observance.","notesPages":[554],"id":"glossary-entry-winterset-day","letter":"W"},{"term":"WIRE (METALLIC)","definition":"Non-live material reinforcing the swinging vines (4).","notesPages":[554],"id":"glossary-entry-wire-metallic","letter":"W"},{"term":"WISDOM","definition":"Quality of sound judgment; possessed by Prester John (12); possessed by Felix Culebra y Columba (71); part of Man (\"darkly wise\") (34); wisdom of pruning humanity (81); wisdom of the ages limned in sky (111); ten condemned lack wisdom to repent (112).","notesPages":[554],"id":"glossary-entry-wisdom","letter":"W"},{"term":"WISE","definition":"Possessing wisdom; Felix is wise as serpents (71); Man darkly wise (34).","notesPages":[554],"id":"glossary-entry-wise","letter":"W"},{"term":"WIT","definition":"Mental sharpness, ingenuity; part of Man (\"Wit that can creep...\") (34); Marino possesses the fastest wit (60).","notesPages":[554],"id":"glossary-entry-wit","letter":"W"},{"term":"WITS (DRUNKEN)","definition":"State of the carry-over guests' minds when Dubu plans to explain the murder mystery (153).","notesPages":[554],"id":"glossary-entry-wits-drunken","letter":"W"},{"term":"WIXON, JAMESTOWN","definition":"See JAMESTOWN WIXON.","notesPages":[554],"id":"glossary-entry-wixon-jamestown","letter":"W"},{"term":"WOE!","definition":"Cry of grief or distress; sobbed by Dubu after the murders of Axel and Randal (148).","notesPages":[554],"id":"glossary-entry-woe","letter":"W"},{"term":"WOLVERENE","definition":"Carnivorous mammal (Gulo gulo), known for ferocity; Carcajou is initially presented as a young male wolverene (55, 64), later revealed to be human and inhabited by a devil-animal (88, 102); the novel describes wolverenes as half animal, half devil (64); eleven appear menacingly (101-102); transformed into devil-fish by Luas (103).","notesPages":[554],"id":"glossary-entry-wolverene","letter":"W"},{"term":"WOLVERENE-DEVIL","definition":"Carcajou described as such (72, 94).","notesPages":[554],"id":"glossary-entry-wolverene-devil","letter":"W"},{"term":"WOLVERENE-WERE GUN","definition":"Specialized weapon needed to kill a wolverene-were (shape- changer like Carcajou) in both forms; also kills werewolves and the shooter (88); obtained by Shadrack Saleh (89) but thrown down unused (90).","notesPages":[554],"id":"glossary-entry-wolverene-were-gun","letter":"W"},{"term":"WOLVERENES","definition":"Described in the novel as half animal/half devil (64); eleven arrive roaring and howling, demanding Carcajou (101-102); transformed into devil-fish (103).","notesPages":[555],"id":"glossary-entry-wolverenes","letter":"W"},{"term":"WOMAN","definition":"Shone one woman (Eve) (35); woman clothed in the sun (35); torrent of a woman's will (35); married to drunk thirty years (47); midwifely person (155).","notesPages":[555],"id":"glossary-entry-woman","letter":"W"},{"term":"WONDER (OF THE WORLD)","definition":"Unfallen Folks described as wonders of the world (16); Axel described as \"a True Child of Wonder\" (148).","notesPages":[555],"id":"glossary-entry-wonder-of-the-world","letter":"W"},{"term":"WONDER OF THE WORLD ELEPHANT","definition":"Extremely rare elephant of absolute genius, in the novel’s elephant lore, born to Empress Elephants after a ten-year gestation; Gajah is one (57, 63, 90, 91, 94).","notesPages":[555],"id":"glossary-entry-wonder-of-the-world-elephant","letter":"W"},{"term":"WONDER (SEVEN-DAY)","definition":"Short-lived phenomenon; applied to the temporary amazement caused by talking animals (54).","notesPages":[555],"id":"glossary-entry-wonder-seven-day","letter":"W"},{"term":"WOOD-CARVED MOTTOS","definition":"Craft involving carving sayings into wood; abandoned by humans, reinvented by Computers (33).","notesPages":[555],"id":"glossary-entry-wood-carved-mottos","letter":"W"},{"term":"WOOD (PERSIMMON)","definition":"See PERSIMMON WOOD.","notesPages":[555],"id":"glossary-entry-wood-persimmon","letter":"W"},{"term":"WOOD (ROTTEN)","definition":"Decayed timber eaten by experimental hogs (3).","notesPages":[555],"id":"glossary-entry-wood-rotten","letter":"W"},{"term":"WOOLY CATERPILLARS","definition":"Insect larvae noted as having some capacity to change, unlike Mankind (40).","notesPages":[555],"id":"glossary-entry-wooly-caterpillars","letter":"W"},{"term":"WORD ('FEAR')","definition":"Lutin claims not to know the word 'fear' (86).","notesPages":[555],"id":"glossary-entry-word-fear","letter":"W"},{"term":"WORD (PRINTED)","definition":"See PRINTED WORD.","notesPages":[555],"id":"glossary-entry-word-printed","letter":"W"},{"term":"WORDS","definition":"Units of language; Axel hears special words (10); Unfallen weigh words well, avoid dishonest ones (15); winged words seen coming from God's/Alfred's mouth (110).","notesPages":[555],"id":"glossary-entry-words","letter":"W"},{"term":"WORDS (ASININE)","definition":"Names derived from asses applied to machines (31).","notesPages":[555],"id":"glossary-entry-words-asinine","letter":"W"},{"term":"WORDS (THUNDEROUS)","definition":"Impressively resonant words coined by the Sea Louse (166).","notesPages":[555],"id":"glossary-entry-words-thunderous","letter":"W"},{"term":"WORDS (WINGED)","definition":"See WINGED WORDS.","notesPages":[556],"id":"glossary-entry-words-winged","letter":"W"},{"term":"WORK","definition":"Activity involving effort; the 1987 author biography says Lafferty quit his other work in 1970 (publisher’s biographical note); work done by Unfallen for grapes (16); Alfred is at work (114); work went well (113).","notesPages":[556],"id":"glossary-entry-work","letter":"W"},{"term":"WORKERS","definition":"Those who perform labor; itinerant workers drawn to Ape Caverns (45); Whales are not good workers but perfect workers (136).","notesPages":[556],"id":"glossary-entry-workers","letter":"W"},{"term":"WORKING","definition":"Engaging in labor; Axel's Apes talented for working metals (3); Whales working through sea-lice (164).","notesPages":[556],"id":"glossary-entry-working","letter":"W"},{"term":"WORLD","definition":"The Earth, its inhabitants, or a sphere of existence; frequently used throughout (e.g., 1, 2, 5, 6, 8, 9, 11, 12, etc.); Floating World (1, 27, etc.); real world vs. symbolic world (141); world of nativity (41); world being enlarged/fulfilled (93, 112, 113); Arty/Bohemian/ Unmoored World (79).","notesPages":[556],"id":"glossary-entry-world","letter":"W"},{"term":"WORLD (ENLARGEMENT OF THE)","definition":"See ENLARGEMENT OF THE WORLD.","notesPages":[556],"id":"glossary-entry-world-enlargement-of-the","letter":"W"},{"term":"WORLD (FLOATING)","definition":"See FLOATING WORLD.","notesPages":[556],"id":"glossary-entry-world-floating","letter":"W"},{"term":"WORLD (FULFILLMENT OF THE)","definition":"See FULFILLMENT OF THE WORLD.","notesPages":[556],"id":"glossary-entry-world-fulfillment-of-the","letter":"W"},{"term":"WORLD (LOG-BOOKS OF THE)","definition":"See LOG-BOOKS OF THE WORLD.","notesPages":[556],"id":"glossary-entry-world-log-books-of-the","letter":"W"},{"term":"WORLD (OCEANIC)","definition":"See OCEANIC WORLD (OLD).","notesPages":[556],"id":"glossary-entry-world-oceanic","letter":"W"},{"term":"WORLD (OUTER)","definition":"See OUTER WORLD.","notesPages":[556],"id":"glossary-entry-world-outer","letter":"W"},{"term":"WORLD (REAL)","definition":"See REAL WORLD.","notesPages":[556],"id":"glossary-entry-world-real","letter":"W"},{"term":"WORLD (UNMOORED)","definition":"See UNMOORED WORLD.","notesPages":[556],"id":"glossary-entry-world-unmoored","letter":"W"},{"term":"WORLD VILLAGE MEDLEY (SONG)","definition":"A campfire song sung at Heart's Desire Cove (59); refers to World Village Medley.","notesPages":[556],"id":"glossary-entry-world-village-medley-song","letter":"W"},{"term":"WORLD-WIDE AWAKENING (APES)","definition":"The awakening Alpha expects to spread from the American Cenaculum to Apes in Exile and finally Second Eden within five minutes (51); Axel’s murder prevents the planned sequence in the climax (147–148).","notesPages":[556],"id":"glossary-entry-world-wide-awakening-apes","letter":"W"},{"term":"WORLDS","definition":"Plural of world; Kangaroo computerized the whole world (80); other parts of the world (41, 19); Satrap's private worlds (47).","notesPages":[557],"id":"glossary-entry-worlds","letter":"W"},{"term":"WORMS (EXPERIMENTAL)","definition":"Creatures in The Three's habitat weighing more than a ton each, edible but causing sickening after- effects (3); earthworms theoretically capable of converting the world (27).","notesPages":[557],"id":"glossary-entry-worms-experimental","letter":"W"},{"term":"WORRY","definition":"Feel anxious or troubled; Lord Randal's parents worry about 'Floating World' (1); Axel worries about Kings (2); Computers sometimes worry about being tied to static humans (40); need not worry about Serpent's Egg case (127); Machines do not worry (50).","notesPages":[557],"id":"glossary-entry-worry","letter":"W"},{"term":"WOTTO METAL","definition":"Fictional material invented by Otto Wotto, used as computer matrix, allowing circuits (strings of single molecules) to form pathways anywhere as needed and uncreate them afterward (25-26); toughest substance known (127); used by Inneall to reinforce life threads (127); Satrap calls it unburnable, but Henryetta burns a statuette made from it (97).","notesPages":[557],"id":"glossary-entry-wotto-metal","letter":"W"},{"term":"X-RAYS","definition":"Imaging technology used to examine the skeletal structure of Axel the Ape, revealing a fully human set of bones beneath his \"flab-flesh\" disguises (hump, gargoyle face, splay feet) (42).","notesPages":[557],"id":"glossary-entry-x-rays","letter":"X"},{"term":"YACHTS","definition":"Pleasure vessels; Satrap Saint Ledger owned at least six, moving three onto Inneall's Ocean (47, 48); at least four yacht-owning gentlemen had put yachts on Inneall's Ocean early on (43); Satrap owned other yachts, including The Filchman's Daughter (115). Owning five or more yielded better insurance rates (116).","notesPages":[558],"id":"glossary-entry-yachts","letter":"Y"},{"term":"YAMS (EXPERIMENTAL)","definition":"Edible tubers grown in The Three's contrived habitat, consumable by the age of three months (5).","notesPages":[558],"id":"glossary-entry-yams-experimental","letter":"Y"},{"term":"YELLOW APE LANE","definition":"The original name, ten years prior, for the enclave later known as Ape Alley (43).","notesPages":[558],"id":"glossary-entry-yellow-ape-lane","letter":"Y"},{"term":"YELLOW APES","definition":"Alternative name for the Axel's Apes, referencing their golden fur (18, 42, 43, 44, 45, 46, 47, 51); sought by zoo suppliers in one specific valley among five hundred (18); fabricated items in smithies (46); their projected awakening is discussed by Alpha (51). See also APE (AXEL'S...).","notesPages":[558],"id":"glossary-entry-yellow-apes","letter":"Y"},{"term":"YELLOW APES IMPRINTING","definition":"Process of acquiring behavioral patterns from Yellow Apes; Inneall suspects she received most of her \"human\" imprinting this way and questions the difference between it and Human Imprinting (51).","notesPages":[558],"id":"glossary-entry-yellow-apes-imprinting","letter":"Y"},{"term":"YELLOW DWARF","definition":"Figure depicted on the Saint Ledger coat-of-arms; identified also as Poupe Jaune or Pope Joan, possessing a Gargoyle face (49).","notesPages":[558],"id":"glossary-entry-yellow-dwarf","letter":"Y"},{"term":"YELLOW FUR SUITS","definition":"Used by Inneall for the appearance of the Axel's Apes, suggesting their ape-like qualities are superficial coverings for human forms; some Apes are losing this \"hair\" alarmingly (51).","notesPages":[558],"id":"glossary-entry-yellow-fur-suits","letter":"Y"},{"term":"YEMEN","definition":"Country in Arabia; Mocha in Yemen formed one end of the original Ape Bridge location (13).","notesPages":[558],"id":"glossary-entry-yemen","letter":"Y"},{"term":"YONAH","definition":"A dove of consummate genius, formerly declared the ward of the naturalist Felix Culebra y Columba (71).","notesPages":[558],"id":"glossary-entry-yonah","letter":"Y"},{"term":"YOUNG CONTEMPORARIES","definition":"Term referring to the members of the Four Experiments, assigned specific Dolophonoi for monitoring (84).","notesPages":[559],"id":"glossary-entry-young-contemporaries","letter":"Y"},{"term":"YOUNG PEOPLE OF THE EXPERIMENTS","definition":"Collective term for the members of the merged experiments (e.g., the Eleven) who arrive at the condominium (71, 73).","notesPages":[559],"id":"glossary-entry-young-people-of-the-experiments","letter":"Y"},{"term":"YOUTH","definition":"Biblical phrase about the human heart being evil from youth (35); pride of youth upon Inneall (126, 160); Donatus O'Reily tried to save a Serpent's-Egg young person (118).","notesPages":[559],"id":"glossary-entry-youth","letter":"Y"},{"term":"ZCHOLD, HIERONYMOUS IGNATIUS","definition":"A Bishop of the Old Religion whose crime is his identity as a clergyman of the Old Religion, deemed more heinous than Donatus O'Reily's attempt to save a Serpent's Egg (122). Sentenced to death by stoning, he arranged to be executed on Tom Dooley's Island to avoid having dogs devour his consecrated body (122). Despite protests from Satrap, officials oversaw the execution, which included disembowelment before the stoning (158). His body was retrieved from the water by four fish-faced men and taken to the Ocean Bottom (159). A cenotaph seen empty before his execution bears his name and the epitaph \"a Good Man\" (150).","notesPages":[560],"id":"glossary-entry-zchold-hieronymous-ignatius","letter":"Z"},{"term":"ZODIAC","definition":"The celestial belt containing the twelve constellations used in astrology; Alfred causes the zone and girdle of the heavens, the circle of signs, the circle of animals, the zodiac to appear in the sky (111).","notesPages":[560],"id":"glossary-entry-zodiac","letter":"Z"},{"term":"ZODIACAL SIGNS","definition":"The twelve astrological signs (Aries, Taurus, etc.); used by computers in astrology but considered mere fortune-telling devices with no connection to the actual stars/ stations (30); Alfred depicts the conventional masks and reveals the \"true signs\" behind them (111).","notesPages":[560],"id":"glossary-entry-zodiacal-signs","letter":"Z"},{"term":"ZOMBIES","definition":"Undead, reanimated corpses; listed among the spectral entities (spooks, polters, spectors, etc.) that can inhabit empty AMH Computers (28).","notesPages":[560],"id":"glossary-entry-zombies","letter":"Z"},{"term":"ZONE (HEAVENS)","definition":"The belt across the celestial sphere containing the zodiac constellations; made visible in the sky by Invisible Alfred (110, 111).","notesPages":[560],"id":"glossary-entry-zone-heavens","letter":"Z"},{"term":"ZOOLOGICAL DOCTORS","definition":"Professional designation of George and Iris Lynn-Randal, who oversaw the transfer of the newborn Axel the Ape to the Lynn-Randal Experiment (20).","notesPages":[560],"id":"glossary-entry-zoological-doctors","letter":"Z"},{"term":"ZOOS","definition":"Facilities for exhibiting animals; targeted by newcomers seeking Axel's Apes (18); two hundred zoos and institutions purchased the captured Apes (20); many Apes kept there learned local vernaculars (20-21); one hundred Apes in zoos worldwide were killed by lightning bolts within a five-minute period (21); Alpha visited several American zoos to free apes (21).","notesPages":[560,561],"id":"glossary-entry-zoos","letter":"Z"}];
